INSERT INTO "tags" VALUES ('g1','主题','cont',0,'这些标签用于主要和次要[url=http://en.wikipedia.org/wiki/Theme_%28literature%29]主题[/url]，或以显著方式呈现出来的游戏故事元素。

这些就是你可以称之为游戏内容的东西，如果它们是故事的主要主题。又或者，是你在故事中注意到的小细节，它们仍然很突出，并以某种方式为故事增色。');
INSERT INTO "tags" VALUES ('g2','奇幻','cont',13133,'本游戏具有来自[url=http://en.wikipedia.org/wiki/Fantasy]奇幻[/url]类型的元素和主题。');
INSERT INTO "tags" VALUES ('g3','超自然','cont',301,'本游戏具有与[url=http://en.wikipedia.org/wiki/Extrasensory_perception]超自然[/url]概念相关的元素和主题。');
INSERT INTO "tags" VALUES ('g4','魔法','cont',2016,'本游戏具有与[url=http://en.wikipedia.org/wiki/Magic_%28paranormal%29]魔法[/url]的超自然概念相关的元素和主题。

不要用于那些将魔法作为幻术形式、没有超自然性质的游戏。');
INSERT INTO "tags" VALUES ('g5','吸血鬼','cont',966,'本游戏具有与[url=http://en.wikipedia.org/wiki/Vampire]吸血鬼[/url]传说相关的元素和主题。');
INSERT INTO "tags" VALUES ('g6','超能力','cont',1528,'本游戏具有与拥有[url=http://en.wikipedia.org/wiki/Superpower_%28ability%29]超能力[/url]的角色相关的元素和主题。');
INSERT INTO "tags" VALUES ('g7','恐怖','cont',4009,'本游戏具有与[url=http://en.wikipedia.org/wiki/Horror_fiction]恐怖[/url]类型相关的元素和主题。');
INSERT INTO "tags" VALUES ('g8','死亡恐惧','cont',197,'本游戏中的角色大多处于[url=http://en.wikipedia.org/wiki/Fear_of_death]死亡恐惧[/url]状态。这可能有基于故事的正当理由，也可能只是与一种叫做死亡恐惧症的精神疾病有关。');
INSERT INTO "tags" VALUES ('g9','身份认同危机','cont',92,'本游戏中的角色正遭受着[url=http://en.wikipedia.org/wiki/Identity_crisis_%28psychology%29]身份认同危机[/url]的困扰。');
INSERT INTO "tags" VALUES ('g10','被怪物恐吓','cont',167,'本游戏中的角色正受到[url=http://en.wikipedia.org/wiki/Monster]怪物[/url]的恐吓。');
INSERT INTO "tags" VALUES ('g12','动作','cont',2489,'本游戏具有与[url=http://en.wikipedia.org/wiki/Action_(fiction)]动作[/url]类型相关的元素和主题。');
INSERT INTO "tags" VALUES ('g13','战斗','cont',1685,'本游戏包含[url=http://en.wikipedia.org/wiki/Combat]战斗[/url]场景。');
INSERT INTO "tags" VALUES ('g14','机甲战斗','cont',115,'本游戏包含使用[url=http://en.wikipedia.org/wiki/Mecha]机甲[/url]进行[url=http://en.wikipedia.org/wiki/Combat]战斗[/url]的场景。');
INSERT INTO "tags" VALUES ('g19','悬疑','cont',5418,'本游戏具有与[url=http://en.wikipedia.org/wiki/Mystery_fiction]悬疑[/url]类型相关的元素和主题。

悬疑是一种故事，其情节涉及一个犯罪或其他事件，直到最后仍然令人困惑地悬而未决。');
INSERT INTO "tags" VALUES ('g20','角色','cont',0,'这些标签代表了一个游戏中[url=http://en.wikipedia.org/wiki/Character_%28arts%29]角色[/url]的各种突出细节。');
INSERT INTO "tags" VALUES ('g21','其他游戏元素','tech',7980,'这些是关于传统视觉小说中没有的[url=http://en.wikipedia.org/wiki/Gameplay]游戏玩法[/url]元素的标签。');
INSERT INTO "tags" VALUES ('g22','设定','cont',0,'游戏的设定包括时间、地点以及故事发生的所有环境，并确立了该故事的主要背景和氛围。

[编辑自[url=http://en.wikipedia.org/wiki/Setting_%28fiction%29]维基百科[/url]。]');
INSERT INTO "tags" VALUES ('g23','性内容','ero',29412,'此标签可用于含有[url=http://en.wikipedia.org/wiki/Sexual_content]色情内容[/url]的游戏。建议在适用时使用其子标签以提供更多细节。');
INSERT INTO "tags" VALUES ('g24','情节','tech',0,'[url=http://en.wikipedia.org/wiki/Plot_%28narrative%29]情节[/url]标签是关于游戏故事如何讲述的。它是什么类型的故事，包含哪些种类的路线和结局，使用了哪些已知手法等等。');
INSERT INTO "tags" VALUES ('g25','个人武装战斗','cont',1004,'这些游戏包含使用（手持）武器（如剑、枪械等）进行[url=http://en.wikipedia.org/wiki/Combat]战斗[/url]的场景。
与机甲和其他载具的战斗有单独的标签。');
INSERT INTO "tags" VALUES ('g26','路线','tech',0,'这些标签用于描述故事路线的细节（如果有的话）。

关于路线在视觉小说中的作用的详细信息，你可以查看相关的[url=https://en.wikipedia.org/wiki/Visual_novel#Structure]维基百科[/url]文章。');
INSERT INTO "tags" VALUES ('g27','结局','tech',0,'这个元标签用于容纳其他关于游戏结局机制的标签。

关于结局内容的标签是不允许的，例如，幸福结局。

你可以查看相关的[url=http://en.wikipedia.org/wiki/Types_of_fiction_with_multiple_endings]维基百科[/url]文章以获取详细信息。');
INSERT INTO "tags" VALUES ('g28','组织','cont',4368,'此元标签的子标签用于那些特定[url=http://en.wikipedia.org/wiki/Organizations]组织[/url]扮演重要角色的游戏——通常是因为主角和/或其朋友/恋爱对象是所述组织的成员或与其有关联。');
INSERT INTO "tags" VALUES ('g29','世界观','内容',0,'此元标签涵盖描述游戏发生所在的宇宙的标签。它们可能设定在[url=http://en.wikipedia.org/wiki/Known_universe]已知宇宙[/url]或[url=http://en.wikipedia.org/wiki/Fictional_universe]虚构宇宙[/url]的某个地方。');
INSERT INTO "tags" VALUES ('g30','时代背景','内容',0,'这些是定义视觉小说故事所设定的[url=http://en.wikipedia.org/wiki/Time_period]时代背景[/url]的标签。');
INSERT INTO "tags" VALUES ('g31','动作游戏','技术',1066,'此标签表示游戏包含挑战玩家速度、敏捷度和反应时间的游戏玩法序列。

请参阅相关的[url=http://en.wikipedia.org/wiki/Action_Game]维基百科[/url]条目以了解详情。');
INSERT INTO "tags" VALUES ('g32','ADV','技术',35556,'在这些游戏中，文本框只占据屏幕的一部分，通常位于底部。这是目前最常见的文本呈现方式。

如果文本框每次位置不固定，请改用[url=http://vndb.org/g398]浮动文本框[/url]标签，而不要使用本标签。

如果游戏同时使用[url=http://vndb.org/g43]全屏[/url]和部分屏幕文本框，请对游戏应用这两个标签。

[url=http://s.vndb.org/sf/01/6101.jpg]示例1[/url]
[url=http://s.vndb.org/sf/04/1304.jpg]示例2[/url]');
INSERT INTO "tags" VALUES ('g33','策略游戏','技术',986,'[url=http://en.wikipedia.org/wiki/Strategy_game]策略游戏[/url]是一种挑战玩家批判性思考以取得胜利的游戏类型。

本视觉小说包含此类型的游戏玩法序列。');
INSERT INTO "tags" VALUES ('g34','模拟游戏','技术',1726,'[url=http://en.wikipedia.org/wiki/Simulation_video_game]模拟游戏[/url]试图重现现实的某些方面，并让玩家处于控制地位。

本视觉小说包含此类型的游戏玩法序列。

与RPG游戏类似，模拟游戏（SLG）通常有代表角色某些属性的数值。为了达成特定目标，你需要提升特定属性。在RPG中，这些属性大多与战斗相关，而在SLG中，它们大多是日常生活的各个方面。

如果所有属性都与恋爱和对主人公们的吸引力相关，那么你看到的是[url=/g39]恋爱模拟[/url]；如果属性不属于主角，而属于另一个角色，那么你很可能看到的是[url=/g40]养成模拟[/url]。');
INSERT INTO "tags" VALUES ('g35','RPG','技术',1066,'[url=http://en.wikipedia.org/wiki/Role-playing_video_game]RPG[/url]是一种游戏，你扮演一个角色，进入一个广阔的世界去探索。游戏通常强调通过战斗获取装备和经验值，以提升等级。

本视觉小说包含此类型的游戏玩法序列。');
INSERT INTO "tags" VALUES ('g36','枪械战斗','内容',418,'这些游戏的战斗通过使用（个人）[url=http://en.wikipedia.org/wiki/Firearms]枪械[/url]来解决——无论是手枪、燧发枪还是现代突击步枪。通常，如果由单人使用，班组武器也算作个人武器（所以如果有人双持[url=http://en.wikipedia.org/wiki/M1918_Browning_Automatic_Rifle]BARs[/url]... 那就请便吧）');
INSERT INTO "tags" VALUES ('g37','格斗游戏','技术',77,'此游戏要么是完整的[url=http://en.wikipedia.org/wiki/Fighting_game]格斗游戏[/url]，要么包含一个作为小游戏的格斗游戏。');
INSERT INTO "tags" VALUES ('g38','射击游戏','技术',102,'[url=http://en.wikipedia.org/wiki/Shooting_game]射击游戏[/url]是一种挑战玩家速度和反应时间以取得成功的游戏类型。这通常通过玩家控制角色并在游戏中向物体射击来实现。

本视觉小说包含此类型的游戏玩法序列。');
INSERT INTO "tags" VALUES ('g39','恋爱模拟','技术',416,'[url=http://en.wikipedia.org/wiki/Dating_sim]恋爱模拟[/url]是一种以浪漫为中心内容的模拟类型。

本视觉小说包含此类型的游戏玩法序列。

通常，模拟方面意味着你为主角安排日程，主角可能拥有外貌、体质、学习等属性，这些属性影响你能与哪些主人公们有机会发展关系。

虽然带有恋爱模拟元素的视觉小说在数据库中是允许的，但带有简短视觉小说元素的恋爱模拟则不允许。

[b]如果所有属性都不涉及浪漫/恋爱元素，请不要使用此标签；请改用[url=/g34]模拟游戏[/url]标签[/b]。');
INSERT INTO "tags" VALUES ('g40','养成模拟','技术',494,'[url=http://en.wikipedia.org/wiki/Raising_sim]养成模拟[/url]是一种模拟类型游戏，主角训练或养育一个或多个其他角色以达到特定目标，从通过考试到成为公主...

通常，被养成的角色会拥有代表其进度的数值属性，如外貌、体质、学习等。在这类游戏中，玩家负责安排他们的日程。

本视觉小说包含此类游戏类型的玩法序列。

虽然数据库中允许带有养成模拟元素的视觉小说，但仅带有简短视觉小说元素的养成模拟则不允许。');
INSERT INTO "tags" VALUES ('g41','回合制策略','技术',176,'[url=https://en.wikipedia.org/wiki/Turn-based_strategy]回合制策略[/url]是一种策略游戏，游戏玩法在玩家之间交替进行：每位玩家在将控制权交给下一位玩家之前，有时间思考自己的下一步行动并执行。 

TBS游戏源自传统棋盘游戏、桌上战棋游戏（如[i]Warhammer[/i]和[i]BattleTech[/i]），以及几千年来真实将领和历史学家用来演练和实施实际战争的微型桌面战斗。许多电脑TBS游戏在网格地图、命中和伤害系统以及单位平衡概念上，与它们早期的掷骰子和纸面原型相似。

TBS以其行动规模著称，通常包含一张大型地图，范围可以从国际冲突一直延伸到控制整个世界或星系。更大规模的游戏往往从暴力冲突演变为一般的竞争性帝国建设模拟，并有可能实现非暴力胜利，此时它们成为所谓的“4X”（探索、扩张、开发、消灭）或“大战略”游戏。');
INSERT INTO "tags" VALUES ('g42','即时战略游戏','技术',36,'这款游戏具有一些[url=http://en.wikipedia.org/wiki/Real_Time_Strategy]即时战略[/url]游戏类型的元素。');
INSERT INTO "tags" VALUES ('g43','NVL','技术',2245,'在这些游戏中，文本框占据全部或大部分屏幕。文本框可以有边框，如[url=http://s.vndb.org/sf/08/808.jpg]Fate/stay night[/url]，也可以没有边框，如[url=http://s.vndb.org/sf/35/3135.jpg]Kira☆Kira[/url]。

许多游戏使用全屏文本框显示历史文本，使用部分屏幕文本框显示当前文本。这不算作本标签。

如果游戏同时使用全屏和[url=http://vndb.org/g32]部分屏幕文本框[/url]，则同时应用这两个标签。');
INSERT INTO "tags" VALUES ('g44','手枪战斗','内容',170,'手枪。短枪。这些游戏会使用它们。');
INSERT INTO "tags" VALUES ('g45','公司','内容',133,'一家[url=http://en.wikipedia.org/wiki/Corporation]公司[/url]在故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g46','军事','内容',228,'一个军事（或在某种程度上，准军事）组织在视觉小说中扮演重要角色。

这可以是国家的正规军队、特种部队、PMC，或像Teikoku Gekidan或Galaxy Angels这样奇特的组织。');
INSERT INTO "tags" VALUES ('g47','学校','内容',5587,'仅当您无法确定游戏使用的是哪种学校时，才使用此标签。否则，请使用此标签下的子标签。');
INSERT INTO "tags" VALUES ('g48','高中','内容',2223,'游戏的某些部分发生在[url=http://en.wikipedia.org/wiki/High_school]高中[/url]。');
INSERT INTO "tags" VALUES ('g49','大学','内容',290,'游戏的某些部分发生在[url=http://en.wikipedia.org/wiki/University]大学[/url]。');
INSERT INTO "tags" VALUES ('g50','忍者','内容',313,'[url=http://en.wikipedia.org/wiki/Ninja]忍者[/url]氏族或类似的忍者组织是故事的重要组成部分。');
INSERT INTO "tags" VALUES ('g51','步枪战斗','内容',22,'涉及使用非自动步枪的战斗的游戏。

（全）自动武器有单独的标签。');
INSERT INTO "tags" VALUES ('g52','地球','内容',6792,'游戏发生在我们自己的星球上。大部分大陆、国家和城市都按照它们在[url=http://en.wikipedia.org/wiki/Earth]地球[/url]上现在或过去的样貌描绘。故事背景设定在基于公认国家中真实城市的虚构城市，也发生在地球上。');
INSERT INTO "tags" VALUES ('g53','太空','内容',646,'游戏发生在天体之间的太空真空中，或在地球之外的行星（卫星、小行星...）上。例如，此类别可用于定义角色可能居住在穿越宇宙的太空船中的游戏。');
INSERT INTO "tags" VALUES ('g54','神话背景','内容',1332,'这些标签适用于那些场景发生在直接取自这些神话（或受其启发的场所）中的游戏，而不是那些只包含这些神话元素但没有这种场景的游戏。');
INSERT INTO "tags" VALUES ('g55','克苏鲁神话','内容',94,'[url=http://en.wikipedia.org/wiki/Cthulhu_Mythos]克苏鲁神话[/url]强烈影响了这部视觉小说的设定和事件。');
INSERT INTO "tags" VALUES ('g56','不列颠神话','内容',21,'[url=http://en.wikipedia.org/wiki/Matter_of_Britain]不列颠神话[/url]强烈影响了这部视觉小说的设定和事件。');
INSERT INTO "tags" VALUES ('g57','北欧神话','内容',83,'[url=http://en.wikipedia.org/wiki/Nordic_mythology]北欧神话[/url]强烈影响了本作的背景和事件。');
INSERT INTO "tags" VALUES ('g58','希腊神话','cont',112,'[url=http://en.wikipedia.org/wiki/Greek_mythology]希腊神话[/url]强烈影响了本作的背景和事件。');
INSERT INTO "tags" VALUES ('g59','自动枪械战斗','cont',44,'如果冲锋枪、突击步枪和机枪能解决问题，那么这款游戏就配得上这个标签。');
INSERT INTO "tags" VALUES ('g60','现代地球','cont',3937,'这部视觉小说的背景设定在现代[url=http://en.wikipedia.org/wiki/Earth]地球[/url]。
注意：“现代”指的是20世纪末至今的未指定时间段。');
INSERT INTO "tags" VALUES ('g61','中世纪地球','cont',96,NULL);
INSERT INTO "tags" VALUES ('g62','未来地球','cont',795,'这部视觉小说设定在一个虚构的未来[url=http://en.wikipedia.org/wiki/Earth]地球[/url]版本。');
INSERT INTO "tags" VALUES ('g63','刀刃武器战斗','cont',616,'小刀、剑、薙刀……如果游戏中的战斗是用这类器械解决的，那么应该使用这个标签（或更具体的子标签之一）。
光剑等也算作刀刃武器（只要它们仍然能切割/刺穿）。');
INSERT INTO "tags" VALUES ('g64','大和抚子女主角','cont',358,'至少有一位女主角是[url=http://en.wikipedia.org/wiki/Yamato_Nadeshiko]大和抚子[/url]。

大和抚子是一个日语术语，意为“理想化日本女性的化身”，或“纯粹女性美的典范”。');
INSERT INTO "tags" VALUES ('g65','战斗女主角','cont',2860,'这些游戏中至少有一位女主角是[url=http://en.wikipedia.org/wiki/Warrior]战士[/url]。她可能是一名职业士兵、自学成才的武术家、拥有强大护身符和剑的巫女，或者是一个幻想生物。但她绝对能在战斗中独当一面。

一款游戏不需要有女主角实际战斗的场景才能拥有这个标签。这更多是关于角色的气质，而不是动作场面。');
INSERT INTO "tags" VALUES ('g66','剑术战斗','cont',448,'这些游戏有使用剑的战斗——无论是欧洲长剑、日本刀还是幻想中的巨剑，都无关紧要。');
INSERT INTO "tags" VALUES ('g67','女武者女主角','cont',130,'女武芸者——女性武器大师
一种女主角原型——通常手持日本刀或薙刀（少数情况下是弓），她从小就以某种流派训练使用这些武器。
可能随时随身携带武器，并有特定使命（守护某处圣地、降妖除魔、保护特定的人……）。
她们几乎总是有强烈的荣誉感和正义感。 
她们多半会留着黑色长发，并使用过时的用语。');
INSERT INTO "tags" VALUES ('g68','后末日地球','cont',371,'这款游戏的很大一部分（如果不是全部）设定在[url=http://en.wikipedia.org/wiki/Apocalyptic_and_post-apocalyptic_fiction]后末日设定[/url]中。');
INSERT INTO "tags" VALUES ('g69','薙刀战斗','cont',19,'薙刀（長刀）基本上是将刀安装在长杆末端的武器。传统上由（武士阶级的）女性用来保卫家园。这是一种相当致命而优雅的武器。');
INSERT INTO "tags" VALUES ('g70','长矛战斗','cont',47,'顶端带刃的长杆，通常用于刺穿敌人。
不要与薙刀混淆，薙刀主要用于砍杀攻击。
长枪（Pike）和类似武器也属于这一类。');
INSERT INTO "tags" VALUES ('g71','斧战斗','cont',16,'你邻居维京人最喜欢的武器。');
INSERT INTO "tags" VALUES ('g72','小刀/匕首战斗','cont',89,'较短的刀刃，主要用于刺戳。');
INSERT INTO "tags" VALUES ('g73','钝器战斗','cont',31,'本游戏中的战斗涉及钝器，如法杖或棍棒。');
INSERT INTO "tags" VALUES ('g74','双持手枪','cont',48,'这些游戏中有人双手各持一把手枪，可能作为角色的风格。');
INSERT INTO "tags" VALUES ('g75','杖战斗','cont',6,'长棍和类似武器适用。
不要与棍棒混淆，棍棒通常是单手使用，末端比中间粗。');
INSERT INTO "tags" VALUES ('g76','棍棒战斗','cont',6,'使用棍棒及类似的未精制、可能即兴制作的武器进行战斗。
不要与杖混淆，杖通常更长，且双手使用（并且往往优雅得多）。');
INSERT INTO "tags" VALUES ('g77','战斗射术','cont',68,'在这些游戏中，弓（以及类似的投射武器，如弩甚至投石索，但不包括枪、火绳枪或类似物）被用来真正伤害和/或杀死某人——如果你只是射米袋靶，它就不属于这里。');
INSERT INTO "tags" VALUES ('g78','异形武器战斗','cont',51,'主角使用锁链？第二女主角使用飞镖？无论你怎么看，都找不到任何合适的武器名称？
使用这个标签。
不要将其用于稀有但属于常见武器的例子——我们不在乎是否只制造了20把，它仍然是一把手枪 ;-)');
INSERT INTO "tags" VALUES ('g79','徒手战斗','cont',267,'这些游戏涉及徒手战斗——无论是空手道、秘密武术，还是只是扭打和比对方更狠地打脸。');
INSERT INTO "tags" VALUES ('g80','魔法/超能力战斗','cont',513,'如果主要的战斗模式涉及向敌人投掷“能量”，则适用此标签。');
INSERT INTO "tags" VALUES ('g81','载具战斗','cont',184,'此游戏包含人们骑乘载具进行战斗的动作与战斗场景。坦克、直升机、飞机、机甲，甚至普通汽车……');
INSERT INTO "tags" VALUES ('g82','女同性恋性行为','ero',3470,'这款视觉小说包含[url=http://en.wikipedia.org/wiki/Lesbian_sex]女同性恋性行为[/url]的场景。

女同性恋性行为是指参与者均为女性的性活动。

为了本数据库的目的，该标签使用二元性别理解，其中“女性”指顺性别女性，即出生时被指定为女性且认同该身份的人。');
INSERT INTO "tags" VALUES ('g83','男男性行为','ero',2905,'这款视觉小说包含男性之间的性行为场景。

男男性行为者（缩写为MSM，也称为与男性发生性行为的男性）是指与同性发生性行为的男性，无论其性身份如何；许多男性选择不（或因其他原因无法）接受男同性恋或双性恋的社会身份。

为了本数据库的目的，该标签使用二元性别理解，其中“男性”指顺性别男性，即出生时被指定为男性且认同该身份的人。');
INSERT INTO "tags" VALUES ('g84','强奸','ero',6751,'此游戏包含[url=http://en.wikipedia.org/wiki/Rape]强奸[/url]场景。 

请使用具体的子标签标记游戏中的强奸场景，以便希望避免/寻找此类内容的用户能充分利用标签功能。');
INSERT INTO "tags" VALUES ('g85','完全可避免的强奸','ero',170,'你可以在不经历任何强奸场景的情况下看到游戏的全部“正常结局”。唯一的强奸场景只出现在过早的坏结局中，你不是必须阅读它们才能进入其他结局。');
INSERT INTO "tags" VALUES ('g86','乱伦','ero',4180,'这些游戏包含可被视为[url=http://en.wikipedia.org/wiki/Incest]乱伦[/url]的性爱场景。所涉角色是否有血缘关系并不重要。');
INSERT INTO "tags" VALUES ('g87','女主角','cont',0,'[url=http://en.wikipedia.org/wiki/Heroine]女主角[/url]是游戏中拥有各自路线和/或结局的女性角色成员。

不要与视觉小说的领头女性角色混淆，那被称为主人公。');
INSERT INTO "tags" VALUES ('g88','血亲乱伦','ero',2461,'这款成人游戏包含与有血缘关系的角色之间的乱伦性爱场景。');
INSERT INTO "tags" VALUES ('g89','兄妹乱伦','ero',2265,'这些游戏包含兄弟与其姐妹之间的性爱场景。他们可能有血缘关系，也可能没有。');
INSERT INTO "tags" VALUES ('g90','姐妹乱伦','ero',441,'这些游戏包含两个（或更多）姐妹之间的性爱场景。她们可能有血缘关系，也可能没有。');
INSERT INTO "tags" VALUES ('g91','血亲姐妹乱伦','ero',295,'这些游戏包含有血缘关系的姐妹之间的性爱场景。');
INSERT INTO "tags" VALUES ('g92','血亲兄妹乱伦','ero',1370,'这些游戏包含有血缘关系的兄妹之间的性爱场景。');
INSERT INTO "tags" VALUES ('g93','非血亲乱伦','ero',1065,'这款成人游戏包含涉及有亲属关系但无血缘关系的角色（如收养的兄弟姐妹等）的性爱场景。');
INSERT INTO "tags" VALUES ('g94','非血亲姐妹乱伦','ero',27,'这些游戏包含无血缘关系的姐妹之间的性爱场景。');
INSERT INTO "tags" VALUES ('g95','非血亲兄妹乱伦','ero',764,'这些游戏包含无血缘关系的兄妹之间的性爱场景。');
INSERT INTO "tags" VALUES ('g96','浪漫','cont',19791,'浪漫在这些游戏中扮演重要角色。');
INSERT INTO "tags" VALUES ('g97','女孩×女孩浪漫','cont',2987,'此游戏包含女孩之间的浪漫关系。
请注意，这并不一定意味着包含性爱场景，若涉及性爱场景请使用[url=/g82]女同性恋性行为[/url]标签。');
INSERT INTO "tags" VALUES ('g98','男孩×男孩浪漫','cont',4495,'此游戏包含男孩之间的浪漫关系。
请注意，这并不一定意味着包含性爱场景，若涉及性爱场景请使用[url=/g83]男男性行为[/url]标签。');
INSERT INTO "tags" VALUES ('g99','乱伦浪漫','cont',800,'这些游戏包含可被称为[url=http://en.wikipedia.org/wiki/Incest]乱伦[/url]的浪漫关系（涉及方是否有血缘关系无关紧要）。');
INSERT INTO "tags" VALUES ('g100','兄妹浪漫','cont',424,'这些游戏包含兄妹之间的浪漫关系。');
INSERT INTO "tags" VALUES ('g101','姐妹浪漫','cont',41,'这些游戏包含两个姐妹之间的浪漫关系。');
INSERT INTO "tags" VALUES ('g102','空间站','cont',88,'游戏（的大部分）发生在一个空间站上。');
INSERT INTO "tags" VALUES ('g103','宇宙飞船','cont',308,'[url=http://en.wikipedia.org/wiki/Spacecraft]宇宙飞船[/url]在游戏故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g104','喜剧','cont',5560,'喜剧是这些游戏的重要元素。');
INSERT INTO "tags" VALUES ('g105','科幻','cont',4326,'科幻（硬或软）是这些游戏的重要元素。');
INSERT INTO "tags" VALUES ('g106','硬科幻','cont',90,'这些游戏具有[url=http://en.wikipedia.org/wiki/Hard_Science_Fiction]硬科幻[/url]元素——较少出现“依靠<技术词>的力量起作用”的情况，更注重现实主义元素。

……这样的游戏真的存在吗？求知欲旺盛的人想知道。');
INSERT INTO "tags" VALUES ('g107','冷娇女主角','cont',666,'这些游戏至少有一位冷娇型女主角。

冷娇型角色最初对主人公（甚至可能对所有人）冷淡或缺乏感情，随着故事发展，她们会对主人公产生感情。

传统傲娇原型的变体。');
INSERT INTO "tags" VALUES ('g108','天才女主角','cont',634,'拥有此标签的游戏中的一位或多位女主角被视为天才。

[url=https://en.wikipedia.org/wiki/Genius]天才[/url]是指展现出非凡智力、创造力或独创性的人，通常达到与实现前所未有的洞察飞跃相关的程度。

请注意，聪明与天才并非一回事，仅凭学业成就高并不能作为天才的标志。');
INSERT INTO "tags" VALUES ('g109','黑客女主角','cont',71,'这部视觉小说中至少有一位女主角是[url=http://en.wikipedia.org/wiki/Hacker_%28term%29]黑客[/url]。');
INSERT INTO "tags" VALUES ('g110','妹妹型女主角','cont',582,'这些游戏至少有一个妹妹型女主角。妹妹型女主角是指并非主角的亲妹妹或继妹，但行为举止和被对待方式都像小妹妹。

此标签用作女主角的性格特征。若为实际姐妹关系，请使用“姐妹女主角”标签。

译者注：Imouto 意为妹妹。');
INSERT INTO "tags" VALUES ('g111','姐姐型女主角','cont',485,'这些游戏至少有一个姐姐型角色。姐姐型女主角是指并非主角的亲姐姐或继姐，但行为举止和被对待方式都像大姐姐。

此标签用作女主角的性格特征。若为实际姐妹关系，请使用“姐妹女主角”标签。

译者注：Oneesan 意为姐姐。');
INSERT INTO "tags" VALUES ('g112','女仆女主角','cont',1199,'这些游戏至少有一位女主角是[url=http://en.wikipedia.org/wiki/Maid]女仆[/url]。');
INSERT INTO "tags" VALUES ('g113','女主角为主角的前辈','cont',699,'这些游戏至少有一位女主角是主角的前辈。例如在工作场所的资深员工，或高年级的学生。');
INSERT INTO "tags" VALUES ('g114','王室女主角','cont',896,'这些游戏至少有一位女主角拥有贵族血统——是女王、公主，或者如果这确实定义了她的身份，属于“普通”贵族。

当前状况对这些标签并不重要，比如一个已不存在的贵族家庭不会改变女主角的出生权。

不命名为“贵族女主角”是为了避免大量拥有高贵心灵但并无血统的女主角被提名。

详情请查看相关的[url=http://en.wikipedia.org/wiki/Royal_family]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g115','巫女女主角','cont',771,'这些游戏至少有一位女主角是[url=http://en.wikipedia.org/wiki/Miko]巫女[/url]。传统服饰很常见，但并非严格要求。');
INSERT INTO "tags" VALUES ('g116','修女女主角','cont',253,'这些游戏至少有一位女主角是[url=http://en.wikipedia.org/wiki/Nun]修女[/url]。不要求必须是基督教徒。');
INSERT INTO "tags" VALUES ('g117','不可避免的强奸','ero',1385,'在至少一条路线中有一个强奸场景，且这是不可避免的。');
INSERT INTO "tags" VALUES ('g118','骑士女主角','cont',317,'这些游戏至少有一位女主角是[url=http://en.wikipedia.org/wiki/Knight]骑士[/url]。');
INSERT INTO "tags" VALUES ('g119','阴阳师女主角','cont',31,'此游戏的女主角是[url=http://en.wikipedia.org/wiki/Onmyouji#Onmy.C5.8Dji]阴阳师[/url]。

阴阳师是精通魔法和占卜的专家。他们的宫廷职责从记录日历等任务，到占卜和保护首都免受邪灵侵害等神秘职责。他们能够占卜大地的吉凶影响，并在迁都中发挥重要作用。据说阴阳师还能召唤和控制式神。');
INSERT INTO "tags" VALUES ('g120','女忍者女主角','cont',237,'这些游戏至少有一位女主角是女忍者，即女性[url=http://en.wikipedia.org/wiki/Ninja]忍者[/url]。');
INSERT INTO "tags" VALUES ('g121','士兵女主角','cont',275,'这些游戏至少有一位女主角是（或曾是）一名职业[url=http://en.wikipedia.org/wiki/Soldier]士兵[/url]。');
INSERT INTO "tags" VALUES ('g122','军官女主角','cont',99,'这些游戏至少有一位女主角是军事力量中的军官（处于权威地位的士兵）。

在军队中担任临时角色的人不属于此标签。这是针对职业军官的。');
INSERT INTO "tags" VALUES ('g123','非人类女主角','cont',4778,'至少其中一位女主角可能看起来像[url=http://en.wikipedia.org/wiki/Human]人类[/url]，但她远不止如此……');
INSERT INTO "tags" VALUES ('g124','主角','cont',0,'视觉小说的[url=http://en.wikipedia.org/wiki/Protagonist]主角[/url]是玩家所操控的角色。

男女主角的组合是可能的，例如多条主角线。');
INSERT INTO "tags" VALUES ('g125','AI女主角','cont',544,'这些游戏至少有一位女主角是[url=http://en.wikipedia.org/wiki/Artificial_intelligence]人工智能[/url]。');
INSERT INTO "tags" VALUES ('g126','机器人女主角','cont',421,'这个游戏有一个或多个[url=http://en.wikipedia.org/wiki/Robot]机器人[/url]女主角。

机器人是一种机械或虚拟智能体，可以自动或在指导下执行任务，通常通过远程控制。实际上，机器人通常是一种由计算机和电子程序引导的机电机器。机器人可以是自主的、半自主的或远程控制的。

与[URL=http://vndb.org/g127]生化人女主角[/URL]形成对照，后者拥有（部分）人造身体，由人脑控制。');
INSERT INTO "tags" VALUES ('g127','生化人女主角','cont',75,'这部视觉小说至少有一位女主角是[url=http://en.wikipedia.org/wiki/Cyborg]生化人[/url]——也就是说，她身体的至少一部分是人造的。

与[url=http://vndb.org/g126]机器人女主角[/url]形成对照，后者控制身体的智能也是人造的。');
INSERT INTO "tags" VALUES ('g128','狐仙女主角','cont',205,'至少有一位女主角是[url=http://en.wikipedia.org/wiki/Kitsune]狐仙[/url]——一种能化为人形的狐狸。');
INSERT INTO "tags" VALUES ('g129','女神女主角','cont',417,'至少有一位女主角是[url=http://en.wikipedia.org/wiki/Goddess]女神[/url]。');
INSERT INTO "tags" VALUES ('g130','吸血鬼女主角','cont',370,'本游戏中的一位女主角是[url=http://en.wikipedia.org/wiki/Vampire]吸血鬼[/url]。吸血是常见行为，但并非严格要求。');
INSERT INTO "tags" VALUES ('g131','有意识武器女主角','cont',27,'该女主角实际上是一种武器。 
通常她是圣剑的人类化身，但也存在其他变体。');
INSERT INTO "tags" VALUES ('g132','书籍女主角','cont',9,'（至少）一位女主角是力量之书的人形化身。

例子包括《Demonbane》中的Al Azif。');
INSERT INTO "tags" VALUES ('g133','男主角','cont',22809,'这些游戏有一位男性主角。');
INSERT INTO "tags" VALUES ('g134','女主角','cont',14496,'这些游戏有一位女性主角。');
INSERT INTO "tags" VALUES ('g135','带配音的主角','tech',2132,'这些游戏有配音的主角。如果主角几乎全程都有配音，请使用此标签。');
INSERT INTO "tags" VALUES ('g136','多位主角','tech',2060,'这些游戏有多个主角，你可以在开始时选择一个，或在游戏中切换。

短暂切换到另一个角色的视角并不会使该角色成为主角（即游戏的主角），请记住这一点。');
INSERT INTO "tags" VALUES ('g137','成年主角','cont',4617,'本游戏的主角是[url=http://en.wikipedia.org/wiki/Adult]成年人[/url]。

''成人''是一个广泛主观的概念，但在视觉小说设定中通常指任何已成年并完成高中教育的人。在高中不是必须或不存在的高幻想/科幻设定中，有职业或达到应有职业的年龄可以用作''成年''的指标。');
INSERT INTO "tags" VALUES ('g138','法师女主角','cont',475,'这些游戏至少有一位女主角是法师。

法师是使用或练习源自超自然或神秘来源的魔法的人。');
INSERT INTO "tags" VALUES ('g139','战斗型主角','cont',2290,'这些游戏的主角是[url=http://en.wikipedia.org/wiki/Warrior]战士[/url]。他可能是职业士兵、自学成才的武术家、拥有强大护身符和剑的牧师，或者可能是一个幻想生物。但他绝对能在战斗中保护好自己。

一款游戏不需要有主角实际战斗的场景才能具有此标签。这更多关乎角色的行为举止，而非动作场面。');
INSERT INTO "tags" VALUES ('g140','未来','cont',1160,'游戏设定在超越我们时代的时间。游戏可能包含未来技术或未来事件元素。');
INSERT INTO "tags" VALUES ('g141','过去','cont',2636,'游戏设定在我们时代之前。游戏可能遵守历史事实，也可能不遵守。');
INSERT INTO "tags" VALUES ('g142','日常生活喜剧','cont',558,'此标签用于描写日常生活故事，以帮助营造喜剧背景。');
INSERT INTO "tags" VALUES ('g143','现代','cont',4885,'游戏设定在当代。

"现代"是一个主观概念，它将视觉小说的发行日与其设定的时间段联系起来。要应用此标签，视觉小说的设定必须与其创作时间大致相同。

这意味着"现代"时期始于80年代初，当时视觉小说类型的首批先驱已经诞生，并且不断向前推进。');
INSERT INTO "tags" VALUES ('g144','策略卡牌战斗','tech',268,'这些游戏具有策略卡牌战斗。');
INSERT INTO "tags" VALUES ('g145','线性剧情','tech',6406,'线性剧情的游戏具有静态的主线故事；不可能进入传统的、大不相同的路线。

此类别中的许多游戏不向玩家提供选择，只是按原样讲述故事。但这并不是规则：游戏也有可能提供选择，但这些选择对故事本身没有持久影响。（例如 Utawarerumono）');
INSERT INTO "tags" VALUES ('g146','单一结局','tech',6143,'这些游戏只有一个结局。');
INSERT INTO "tags" VALUES ('g147','戏剧','cont',12599,NULL);
INSERT INTO "tags" VALUES ('g148','多结局','tech',12291,'这些游戏有几种不同的结局。');
INSERT INTO "tags" VALUES ('g149','强制游玩顺序','tech',702,'这些游戏有强制要求的结局/路线顺序。 

你首先必须获得特定结局或游玩特定路线，才能解锁你想要的另一个结局/路线。

这些条件是绝对的，没有其他办法可以绕过它们。');
INSERT INTO "tags" VALUES ('g150','家庭生活喜剧','cont',78,'这部视觉小说中的喜剧围绕家庭生活展开：家庭成员之间的关系、共同生活的恶作剧等。');
INSERT INTO "tags" VALUES ('g151','校园生活喜剧','cont',487,'这个故事是基于学生生活的喜剧。故事背景可以是学校，也可以是这些学生去的其他地方，比如度假。');
INSERT INTO "tags" VALUES ('g152','失忆症','cont',1392,'本游戏中的某个角色患有[url=http://en.wikipedia.org/wiki/Amnesia]失忆症[/url]。或者失忆以其他某种方式在游戏故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g153','谋杀悬疑','cont',947,'这个故事具有[url=http://en.wikipedia.org/wiki/Murder_mystery]犯罪小说[/url]的元素，主要在谋杀悬疑方面。');
INSERT INTO "tags" VALUES ('g154','萝莉女主角','cont',2943,'至少有一位女主角是萝莉。她要么是未成年少女，要么长得很像未成年少女。

在归类为萝莉时，年龄完全无关紧要。这只看外表。

详情请参阅相关的[url=http://en.wikipedia.org/wiki/Lolicon]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g155','竞速','cont',53,'这些游戏涉及[url=http://en.wikipedia.org/wiki/Racing]竞速[/url]，无论是步行、驾驶车辆、游泳还是完全不同的方式。');
INSERT INTO "tags" VALUES ('g156','萝莉控','ero',1842,'本游戏包含与萝莉角色相关的性爱场景以及相关的萝莉控主题。

在日本，[url=http://en.wikipedia.org/wiki/Lolicon]萝莉控[/url]描述的是对未成年女孩（无论是青春期前、青春期还是青春期后）的吸引力。

注意：请勿将此标签用于萝莉控角色，如需使用请使用相应的角色标签。');
INSERT INTO "tags" VALUES ('g157','暴力','cont',3973,'本游戏包含某种形式的[url=http://en.wikipedia.org/wiki/Violence]暴力[/url]。

世界卫生组织将暴力定义为故意使用身体力量或权力，以威胁或实际的方式，针对自己、他人或某个群体或社区，导致或极有可能导致伤害、死亡、心理伤害、发育不良或剥夺的行为。该定义将故意性与行为本身的实施相关联，而无论其结果如何。');
INSERT INTO "tags" VALUES ('g158','图形暴力','cont',1115,'本游戏包含一些[url=http://en.wikipedia.org/wiki/Graphic_violence]血腥暴力[/url]内容。

血腥暴力是指在文学、电影、电视和视频游戏等视觉媒体中对特别生动、残酷和逼真的暴力行为的描绘。它可以是真实的、模拟真人表演的或动画形式的。

血腥暴力中的“graphic”是“explicit”的同义词，指所描绘暴力清晰而不加掩饰的性质；这正是真正的血腥暴力与媒体作品中较轻度的暴力形式（包括“卡通”暴力和“幻想”暴力）的区别所在。');
INSERT INTO "tags" VALUES ('g159','暴力描述','cont',699,'本游戏包含一些对[url=http://en.wikipedia.org/wiki/Violence]暴力[/url]进行描述的场景。

上述场景中的暴力并非以视觉方式呈现，而仅仅以文字形式出现，因此该标签与[url=http://vndb.org/g158]血腥暴力[/url]有所不同。这种呈现方式可能更受那些不喜欢看到生动暴力图像的人青睐。');
INSERT INTO "tags" VALUES ('g160','血腥场景','cont',1931,'本游戏包含血腥场景。暴力行为或事故导致流血之前并不需要展示或描述，但屏幕上出现大量血液则是必需的。');
INSERT INTO "tags" VALUES ('g161','血腥残暴','cont',804,'本游戏包含过度暴力场景，并且因暴力而显示大量血液。');
INSERT INTO "tags" VALUES ('g162','Guro','ero',288,'本游戏在性行为过程中包含过度暴力甚至更糟的场景。

Guro是''Erotic Grotesque''的缩写。它是Hentai的一个子类型，以血液、血腥残暴、毁容、酷刑和血淋淋的截肢为特色。Guro的极端例子包括恋尸癖、性行为中截肢和暴力的颅骨性交。');
INSERT INTO "tags" VALUES ('g163','霸凌','cont',662,'这部视觉小说的故事涉及[url=https://en.wikipedia.org/wiki/Bullying]霸凌[/url]。

霸凌是使用武力、胁迫、伤害性的戏弄、评论或威胁，以虐待、攻击性支配或恐吓一个或多个人。这种行为可能是习惯性的，并涉及社会或身体权力的不平衡。

霸凌分为四种基本的虐待类型：心理、言语、身体和网络，尽管一次遭遇可能属于不止一个类别。');
INSERT INTO "tags" VALUES ('g164','儿童虐待','cont',425,'本游戏包含与[url=http://en.wikipedia.org/wiki/Child_Abuse]儿童虐待[/url]相关的戏剧性事件。

儿童虐待是对儿童的身体、性、情感虐待或忽视。');
INSERT INTO "tags" VALUES ('g165','药物使用','cont',424,'这个故事包含毒品使用的元素。

不要用于有角色正在服用医生处方药物的视觉小说。');
INSERT INTO "tags" VALUES ('g166','战国时代','cont',94,'这部视觉小说的背景设定在（或至少基于）[url=http://en.wikipedia.org/wiki/Sengoku_period]日本战国时代[/url]。');
INSERT INTO "tags" VALUES ('g167','健康问题','cont',5624,'关于角色[url=http://en.wikipedia.org/wiki/Health]健康[/url]的问题在这个故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g168','生死戏剧','cont',3090,'一款花费大量时间讨论生命珍贵性，或让角色不断担心自己或所爱之人的生存，或一款有很多人死亡并且这种情况影响角色心理的游戏，可以使用这个标签。');
INSERT INTO "tags" VALUES ('g169','人际关系问题','cont',3612,'这个标签适用于那些角色处于恋爱关系中却难以维持彼此关系的游戏。');
INSERT INTO "tags" VALUES ('g170','自杀','cont',1037,'这个故事以[url=http://en.wikipedia.org/wiki/Suicide]自杀[/url]为主题。

自杀是故意导致自身死亡的行为。自杀通常出于绝望，其原因可归因于精神障碍，如抑郁症、双相情感障碍、精神分裂症、自闭症谱系障碍、酒精中毒或药物滥用。经济困难或人际关系问题等压力因素往往也起重要作用。');
INSERT INTO "tags" VALUES ('g172','父亲支持角色','cont',560,'这款游戏中有一位父亲或父亲型角色作为支持角色，表现得像父亲一样，提供建议等，为游戏增添家庭元素。');
INSERT INTO "tags" VALUES ('g173','母亲支持角色','cont',692,'这款游戏中有一位母亲或母亲型支持角色，表现得像母亲一样，为游戏增添家庭元素。');
INSERT INTO "tags" VALUES ('g174','主角的兄弟作为支持角色','cont',318,'这款游戏有主角的兄弟作为支持角色。');
INSERT INTO "tags" VALUES ('g175','导师支持角色','cont',95,'在这款游戏中，有一位[url=http://en.wikipedia.org/wiki/Mentor]导师[/url]支持角色，在故事的大部分时间里教导主角（或少数情况下教导女主角）。

他/她可能是一位老师或类似老师的角色，总是给主角提建议，令人厌烦。 
或者有一位很棒的导师，把主角训练得很厉害。
或者有一个镇上的老人，到处出现帮助主角摆脱困境...');
INSERT INTO "tags" VALUES ('g176','愚蠢的朋友','cont',302,'其中一个支持角色是个白痴。通常这个角色是主角最好的朋友，或者至少是亲密朋友。');
INSERT INTO "tags" VALUES ('g177','老师女主角','cont',1708,'至少有一位女主角是[url=http://en.wikipedia.org/wiki/Teacher]老师[/url]。');
INSERT INTO "tags" VALUES ('g178','触手强奸','ero',1788,'这部视觉小说包含涉及[url=http://en.wikipedia.org/wiki/Tentacle]触手[/url]的强奸情节。');
INSERT INTO "tags" VALUES ('g179','群交','ero',8292,'这款游戏包含[url=http://en.wikipedia.org/wiki/Group_sex]群交[/url]场景。');
INSERT INTO "tags" VALUES ('g180','早期分支剧情','tech',644,'这款游戏的故事在早期就出现分支。 

这意味着在游戏早期你就会面临一个选择，这个选择会把故事引向与其余部分截然不同的分支。');
INSERT INTO "tags" VALUES ('g181','唯一真结局','tech',1701,'尽管这款游戏有多个结局，其中一个被认为是故事的真结局。

有时从该结局比其他结局长数倍可以明显看出，有时它是续作延续的结局，有时这是创作者后来才透露的。');
INSERT INTO "tags" VALUES ('g182','后期分支剧情','tech',455,'这款游戏的故事在游戏后期才出现分支。

这意味着在游戏的大部分时间里，无论你最终选择哪条路线，你都会读到相同的故事。你会看到一些基于你目标女主角的场景，但在到达分支点之前，%90的故事内容保持不变。所以珍惜你的第一次游玩，并选择你最喜欢的女主角，因为下次就不会那么独特了。');
INSERT INTO "tags" VALUES ('g183','兽交','ero',667,'这款游戏涉及与动物发生性行为。 

详情请查看相关维基百科条目：http://en.wikipedia.org/wiki/Zoophilia

注意：请仅对真实动物使用此标签，对于奇幻生物请使用[url=http://vndb.org/g988]与怪物性交[/url]及其子标签。');
INSERT INTO "tags" VALUES ('g184','正太控','ero',895,'这些成人游戏至少有一个场景包含可被描述为正太的角色。');
INSERT INTO "tags" VALUES ('g185','幽灵女主角','cont',349,'这款游戏中的一位女主角是[url=http://en.wikipedia.org/wiki/Ghost]幽灵[/url]。');
INSERT INTO "tags" VALUES ('g186','大小姐女主角','cont',1317,'这款游戏中的一位或多位女主角属于[url=http://en.wikipedia.org/wiki/Upper_class]上流阶层[/url].

上流阶层是由社会中最富有的成员组成的社会阶层，他们也拥有最大的政治权力。上流阶层通常包含在最富有的1-2%的人口中，并以巨额财富（以地产的形式）为特征，这些财富代代相传。

这个标签是关于女主角的社会地位，并非指她的行为*。

*由于从小习惯于财富和特权，她们倾向于炫耀自己的家族财富和地位。由于习惯了仆人服侍，她们很可能会支使那些与她们社会地位不同的人，甚至无意中也是如此。');
INSERT INTO "tags" VALUES ('g187','女扮男装的女主角','cont',138,'这部视觉小说中至少一位女主角的外貌特征使她看起来像个男孩，甚至可能被误认为是男孩。
[url=http://en.wikipedia.org/wiki/Cross_dressing]异装[/url]并非必需，尽管这往往是混淆的根源。');
INSERT INTO "tags" VALUES ('g188','御宅族女主角','cont',531,'其中一位女主角是动漫（角色扮演/漫画/游戏）御宅族。这意味着她沉迷于这个爱好，不过程度无害。');
INSERT INTO "tags" VALUES ('g189','偶像女主角','cont',580,'其中一位女主角是一位[url=http://en.wikipedia.org/wiki/Japanese_idol]偶像[/url]。');
INSERT INTO "tags" VALUES ('g190','天然呆女主角','cont',588,'其中一位女主角是个天然呆。

天然呆缺乏常识，但拥有愉快友善的态度。');
INSERT INTO "tags" VALUES ('g191','眼镜女主角','cont',3264,'一位或多位女主角佩戴[url=http://en.wikipedia.org/wiki/Glasses]眼镜[/url]。');
INSERT INTO "tags" VALUES ('g192','病娇女主角','cont',545,'本游戏中的一位或多位女主角表现出[url=http://en.wikipedia.org/wiki/Yandere#Y]病娇[/url]行为。

病娇是一个日语术语，指某人起初对某个人非常关爱和温柔，之后其奉献变得具有破坏性，通常通过暴力表现出来。');
INSERT INTO "tags" VALUES ('g193','现代傲娇女主角','cont',560,'一位或多位女主角是现代傲娇。

她对主角（也可能对所有人）有一面是完全的娇羞（坠入爱河）。

她还有另一面，对主角（和/或所有人）极其敌对，并且常常会对他使用极端暴力。

她在这两面之间频繁切换。最糟的情况下，一分钟内预计会切换2到3次。

与经典傲娇、冷娇和病娇形成对比。');
INSERT INTO "tags" VALUES ('g194','经典傲娇女主角','cont',613,'一位或多位女主角是经典傲娇（在动漫\"主流\"同化它之前的定义）。

由于某种原因，她对主角（也可能对所有人）先是傲娇（暴躁、暴力，甚至可能暴力），随着游戏进程会爱上他/变得娇羞（坠入爱河）。

虽然傲娇和娇羞可能相互冲突，但这个阶段会在短时间内结束，并进展为纯粹的娇羞。

与冷娇比较。不要与现代傲娇混淆。');
INSERT INTO "tags" VALUES ('g195','娇羞女主角','cont',889,'其中一位女主角是娇羞型——她基本上从遇见主角的那一刻起就完全迷恋上他了。

即使是最无辜的言语，她也会频频脸红。');
INSERT INTO "tags" VALUES ('g196','病弱女主角','cont',373,'本游戏中的一位女主角身患疾病，该疾病在故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g197','学生会','cont',726,'[url=http://en.wikipedia.org/wiki/Student_government]学生会[/url]在这个故事中扮演重要角色。

学生会是一种学生组织，存在于许多学院、大学，并已开始出现在一些高中。在高等教育中，学生会通常在校内拥有自己的大楼，专门用于学生群体的社交和组织活动。');
INSERT INTO "tags" VALUES ('g198','御宅族主角','cont',265,'主角是一位动漫/漫画/游戏御宅族。');
INSERT INTO "tags" VALUES ('g199','运动','cont',498,'运动是这些游戏的重要元素。');
INSERT INTO "tags" VALUES ('g200','利爪战斗','cont',26,'吸血鬼、狼人或人类将手变形为爪子进行战斗');
INSERT INTO "tags" VALUES ('g201','主角的青梅竹马作为女主角','cont',2834,'一位或多位女主角是主角的[url=http://en.wikipedia.org/wiki/Childhood_friend]青梅竹马[/url]。（被遗忘的）婚姻约定可选但很常见。');
INSERT INTO "tags" VALUES ('g202','虚构生物','cont',8096,'这部视觉小说包含现实世界中不存在的生物和/或存在。');
INSERT INTO "tags" VALUES ('g203','可命名主角','tech',6065,'你可以设置本游戏主角的名字。

如果你使用默认名字，可能会有额外的配音，也可能没有。');
INSERT INTO "tags" VALUES ('g204','狼人','cont',298,'本游戏的一个或多个角色是[url=http://en.wikipedia.org/wiki/Werewolf]狼人[/url]。

狼人，又称变狼狂，是一种神话或民间传说中的人类，能够变形为拟人化的类狼生物，这种变形可能是故意的，也可能是因为被另一只狼人咬伤，或是在受到诅咒之后。');
INSERT INTO "tags" VALUES ('g205','木乃伊','cont',16,'在虚构作品中，木乃伊是不死的生物，其尸体经过防腐处理并被赋予生命。

欲了解现实生活中的木乃伊及防腐过程的更多信息，请阅读相关的[url=https://en.wikipedia.org/wiki/Mummy]维基百科[/url]文章。');
INSERT INTO "tags" VALUES ('g206','魔像','cont',20,'本游戏包含[url=http://en.wikipedia.org/wiki/Golem]魔像[/url]。');
INSERT INTO "tags" VALUES ('g207','强奸未遂','ero',230,'本游戏有一个或多个强奸未遂场景。

这些尝试要么因故事默认而失败，要么因选择正确选项而失败。

此标签旨在标记那些你可以避免强奸（而不仅仅是未遂）的游戏。');
INSERT INTO "tags" VALUES ('g208','突发性爱场景','ero',304,'本游戏中的部分或全部性爱场景与故事几乎无关，只是突然出现，并以你能想象的最牵强的借口发生。');
INSERT INTO "tags" VALUES ('g209','怪物猎人女主角','cont',92,'至少有一位女主角是[url=http://en.wikipedia.org/wiki/Monster]怪物[/url]猎人。');
INSERT INTO "tags" VALUES ('g210','吸血鬼猎人女主角','cont',35,'至少有一位女主角是[url=http://en.wikipedia.org/wiki/Vampire]吸血鬼[/url]猎人。');
INSERT INTO "tags" VALUES ('g211','恶魔女主角','cont',1000,'至少有一位女主角是（西方类型的）[url=http://en.wikipedia.org/wiki/Demon]恶魔[/url]。');
INSERT INTO "tags" VALUES ('g212','半恶魔女主角','cont',75,'游戏中的至少一位女主角是[url=http://en.wikipedia.org/wiki/Demon]恶魔[/url]与人类或类似存在的孩子。');
INSERT INTO "tags" VALUES ('g213','拥有恶魔之血的女主角','cont',43,'这类女主角起初是普通人类，但后来恶魔之血与她的血液混合，最终赋予她超人的素质和力量。');
INSERT INTO "tags" VALUES ('g214','拔作','ero',9583,'这部视觉小说专注于情色内容，剧情和角色刻画（如果有的话）只扮演次要角色，仅为性爱场景提供背景。剧情为性爱场景服务，而非反之。');
INSERT INTO "tags" VALUES ('g215','家庭','cont',933,'家庭环境在这个故事中扮演重要角色。它可以是主角自己的家庭，也可以是某位女主角的家庭。可以期待大量餐桌上的交谈和父母的建议。另一种情况也可能是角色们在没有父母身影的情况下，一直谈论温暖家庭环境的重要性。');
INSERT INTO "tags" VALUES ('g216','犯罪家族','cont',276,'[url=http://en.wikipedia.org/wiki/Crime_family]犯罪家族[/url]在故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g217','黑帮','cont',140,'这个故事包含传统[url=http://en.wikipedia.org/wiki/Yakuza]黑帮[/url]的成员或主题。');
INSERT INTO "tags" VALUES ('g218','传统主义家庭','cont',82,'本游戏有一个庞大的传统主义家庭，一些长辈向主角或女主角施压，要求他们为家族利益做事。');
INSERT INTO "tags" VALUES ('g219','性奴役','ero',1492,'性奴役是一种过程，在此过程中，某人通过各种手段‘强迫’他人从事某种性活动。

上述‘强迫’可能是直接的武力/胁迫，也可能是支配者与顺从者之间协议的一部分。
手段多种多样，其中一些非详尽的手段包括敲诈、催眠、精神摧毁和性暴力，或某种形式的自愿奴隶契约。

性奴役有两种截然不同的形式：
1. 一种[url=http://en.wikipedia.org/wiki/Sexual_slavery]非自愿的[/url]形式，即因胁迫而进行的非自愿性行为。
2. 一种[url=http://en.wikipedia.org/wiki/Sexual_slavery_%28BDSM%29]自愿的[/url]形式，通常表现为支配者将顺从者当作财产来拥有。

在视觉小说（主要是拔作）的语境中，必须假定存在第三种形式的性奴役：
3. 一种半（非）自愿的形式，其中‘顺从者’首先必须被支配者以现实中被视为犯罪的手段所说服。日本亚文化将这种情况定义为‘調教’[choukyou]，其字面意思是‘教动物做事或正确行为’。

注：请酌情使用此标签的子标签。');
INSERT INTO "tags" VALUES ('g220','束缚','ero',3519,'本游戏包含[url=http://en.wikipedia.org/wiki/Bondage_%28sexual%29]性束缚[/url]场景。');
INSERT INTO "tags" VALUES ('g221','现代日本','cont',2544,'这些游戏发生在现代[url=http://en.wikipedia.org/wiki/Japan]日本[/url]。
注："Modern day"指20世纪末至今之间未指定的时间段。');
INSERT INTO "tags" VALUES ('g222','虚构的现代日本小镇','cont',414,'这部视觉小说设定在当代日本的一个虚构城镇。
注：“现代”指的是20世纪末至今天之间的一个未指明时间段。');
INSERT INTO "tags" VALUES ('g223','宗教组织','cont',405,'一个[url=http://en.wikipedia.org/wiki/Religious_organization]宗教组织[/url]在本故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g224','基督教会','cont',74,'游戏的故事中，[url=http://en.wikipedia.org/wiki/Christian_Church]基督教会[/url]扮演了积极角色。

或者使用一个类似的虚构组织/基督教会分支作为故事的一部分。');
INSERT INTO "tags" VALUES ('g225','魔术师协会','cont',40,'游戏中有魔法使用者组织，无论他们在游戏中被称为术士、巫师、魔术师还是魔导师……在现代背景下，这些协会通常隐藏起来，但这并非该标签的必要条件。');
INSERT INTO "tags" VALUES ('g226','主角的姐妹作为女主角','cont',2391,'这款游戏中的一位女主角是主角的[url=http://en.wikipedia.org/wiki/Sister]姐妹[/url]。年龄大小或双胞胎并不重要。');
INSERT INTO "tags" VALUES ('g227','主角的血缘姐妹作为女主角','cont',1250,'这款游戏中的一位女主角是主角有血缘关系的[url=http://en.wikipedia.org/wiki/Sister]姐妹[/url]。');
INSERT INTO "tags" VALUES ('g228','主角的非血缘姐妹作为女主角','cont',810,'这部视觉小说中至少有一位女主角是主角的姐妹，但她们之间没有血缘关系。

这位女主角可以是主角的[URL=https://vndb.org/i295]继姐妹[/URL]、[URL=https://en.wikipedia.org/wiki/Adoption]养姐妹[/URL]或[URL=https://en.wikipedia.org/wiki/Foster_care]寄养姐妹[/URL]。');
INSERT INTO "tags" VALUES ('g229','爱尔兰神话','cont',13,'[url=http://en.wikipedia.org/wiki/Irish_mythology]爱尔兰神话[/url]强烈影响了这部VN的设定和事件。');
INSERT INTO "tags" VALUES ('g230','美索不达米亚神话','cont',9,'[url=http://en.wikipedia.org/wiki/Mesopotamian_mythology]美索不达米亚神话[/url]强烈影响了这部VN的设定和事件。');
INSERT INTO "tags" VALUES ('g235','无性内容','tech',15111,'这款游戏完全没有性内容和真正的色情内容。它可能偶尔会有一些轻微粉丝服务，但程度通常与电视动画中看到的一样。');
INSERT INTO "tags" VALUES ('g236','低性内容','ero',854,'这与拔作完全相反。这类游戏每条路线只有几个H场景，只是为了新奇。它们注重（相对）出色的故事，寻找色情体验的人应该避开。');
INSERT INTO "tags" VALUES ('g237','秘密身份','cont',387,'本游戏有一个或多个具有[url=http://en.wikipedia.org/wiki/Secret_identity]秘密身份[/url]的角色。');
INSERT INTO "tags" VALUES ('g239','配角','cont',0,'这些是游戏中所有非女主角且非主角的角色。');
INSERT INTO "tags" VALUES ('g240','人造人女主角','cont',93,'这个故事中的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Homunculus]人造人[/url]。

人造人是一种由魔法和/或科学赋予生命的人造人类。');
INSERT INTO "tags" VALUES ('g241','激光与光束战斗','cont',47,'这部视觉小说包含战斗，参战角色/机甲/宇宙飞船等互相发射激光和光束。

如果这些光束明显是魔法，请改用[url=http://vndb.org/g80]魔法/超能力战斗[/url]。');
INSERT INTO "tags" VALUES ('g242','激光与光束枪械战斗','cont',33,'这部视觉小说采用[url=http://en.wikipedia.org/wiki/Raygun]发射光束和/或激光的枪械[/url]，而非传统弹射物。');
INSERT INTO "tags" VALUES ('g243','刺客女主角','cont',94,'本游戏的一位女主角是（或曾经是）一名[url=http://en.wikipedia.org/wiki/Assassin]刺客[/url]。');
INSERT INTO "tags" VALUES ('g244','未来的日本','cont',245,'这个故事设定在一个虚构的未来[url=http://en.wikipedia.org/wiki/Japan]日本[/url]。');
INSERT INTO "tags" VALUES ('g245','未来日本附近的虚构岛屿','cont',40,'故事设定在未来日本海岸附近的一个虚构岛屿上。');
INSERT INTO "tags" VALUES ('g246','仅简短分支','tech',434,'游戏基本上是线性的，但根据你的选择会有少量分支，这些分支大多很短，完全不影响实际结局。');
INSERT INTO "tags" VALUES ('g247','残疾女主角','cont',237,'一位或多位女主角有[url=http://en.wikipedia.org/wiki/Disability]残疾[/url]。例如，她可能是盲人、聋人、哑人或瘫痪。

此标签用于身体残疾，如果是精神残疾，请改用[url=/g497]有心理问题的女主角[/url]。');
INSERT INTO "tags" VALUES ('g248','哑巴女主角','cont',50,'这个故事中的一位女主角患有[url=http://en.wikipedia.org/wiki/Muteness]缄默症[/url]。');
INSERT INTO "tags" VALUES ('g249','时间旅行','cont',1022,'这部视觉小说包含[url=http://en.wikipedia.org/wiki/Time_travel]时间旅行[/url]。

时间旅行是指在不同的时间点之间移动的概念，类似于在不同的空间点之间移动。');
INSERT INTO "tags" VALUES ('g250','平行维度','cont',524,'这个标签用于探讨类似[url=http://en.wikipedia.org/wiki/Parallel_universe_%28fiction%29]平行宇宙[/url]存在概念的游戏。');
INSERT INTO "tags" VALUES ('g251','同性恋支持角色','cont',172,'其中一个支持角色是同性恋。这在故事中扮演一定角色。');
INSERT INTO "tags" VALUES ('g252','主角的妹妹作为支持角色','cont',360,'这个游戏将主角的妹妹作为支持角色。与类似的女主角条目不同，她不是主角任何恋爱对象的目标。');
INSERT INTO "tags" VALUES ('g253','心理问题','cont',4983,'关于角色心理[url=http://en.wikipedia.org/wiki/Health]健康[/url]的问题在故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g254','白日梦','cont',62,'用于那些[url=http://en.wikipedia.org/wiki/Daydream]白日梦[/url]是故事不可或缺部分的游戏。不要仅因为游戏中有白日梦就使用这个标签。');
INSERT INTO "tags" VALUES ('g255','身体问题','cont',596,'关于角色身体[url=http://en.wikipedia.org/wiki/Health]健康[/url]的问题在故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g256','成瘾女主角','cont',21,'这部视觉小说至少有一位女主角有某种[url=https://en.wikipedia.org/wiki/Addiction]成瘾[/url]。');
INSERT INTO "tags" VALUES ('g257','胆怯的女主角','cont',230,'这种类型的女主角很软弱（身体上和/或精神上）。至少在游戏大部分时间里，她容易被推来推去和欺负。');
INSERT INTO "tags" VALUES ('g258','害羞的女主角','cont',750,'这种类型女主角很害羞，大多数情况下太害羞，直到主角施展魔法之前都不敢和任何人说话。');
INSERT INTO "tags" VALUES ('g259','虚构世界','cont',2025,'游戏发生在另一个世界。游戏环境可能与我们自己的世界相似，只有一些显著变化，但也可能完全不同。');
INSERT INTO "tags" VALUES ('g260','魔法少女女主角','cont',528,'一位或多位女主角是[url=http://en.wikipedia.org/wiki/Magical_girl]魔法少女[/url]。');
INSERT INTO "tags" VALUES ('g261','反向强奸','ero',480,'这个游戏有一个或多个场景，女性强迫不情愿的男性发生性行为。');
INSERT INTO "tags" VALUES ('g262','士兵主角','cont',360,'游戏的主角是（或曾经是）一名职业[url=http://en.wikipedia.org/wiki/Soldier]士兵[/url]。');
INSERT INTO "tags" VALUES ('g263','领袖主角','cont',1115,'这种类型的主角是[url=http://en.wikipedia.org/wiki/Leader]领袖[/url]。这个主角有雇员/臣民/士兵可以指挥。游戏故事可能包含也可能不包含实际指挥他们。');
INSERT INTO "tags" VALUES ('g264','皇帝主角','cont',22,'这部视觉小说的主角是[url=http://en.wikipedia.org/wiki/Emperor]皇帝[/url]或女皇。');
INSERT INTO "tags" VALUES ('g265','失明的女主角','cont',84,'一位或多位女主角失明，即她看不见。');
INSERT INTO "tags" VALUES ('g266','天使女主角','cont',303,'这个游戏的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Angel]天使[/url]。');
INSERT INTO "tags" VALUES ('g267','主角的女儿作为支持角色','cont',103,'故事中的一个角色是主角的女儿。这个标签用于纯粹的父亲关系，不包括任何恶意。');
INSERT INTO "tags" VALUES ('g268','只有一位女主角','cont',5039,'这个游戏只有一位女主角可以互动，这就是故事的全部内容。');
INSERT INTO "tags" VALUES ('g269','濒死女主角','cont',136,'这个游戏中的一位女主角患有[url=http://en.wikipedia.org/wiki/Terminal_illness]绝症[/url]。无论是从游戏一开始还是大部分时间总体如此。她能否在游戏中活下来取决于游戏，但她的疾病是她作为角色的重要因素。');
INSERT INTO "tags" VALUES ('g270','医院','cont',620,'这部视觉小说有很多场景发生在[url=http://en.wikipedia.org/wiki/Hospital]医院[/url]。');
INSERT INTO "tags" VALUES ('g271','棒球','cont',78,'[url=http://en.wikipedia.org/wiki/Baseball]棒球[/url]在游戏故事中扮演一部分。

棒球是一种用球棒击球、由两支各九名球员组成的球队进行的运动。目标是击中投出的球并触踏九十英尺菱形场地四角的一系列四个垒包，从而得分。击球方球员轮流击打防守方投手投出的球，防守方则试图通过多种方式让击球手出局以阻止得分。击球方球员可以在任何垒包停下，随后通过队友的击球或其他方式推进。每当防守方记录三个出局时，两队交换攻守。每队一次击球构成一局，九局构成一场职业比赛。比赛结束时得分最多的球队获胜。');
INSERT INTO "tags" VALUES ('g272','快速小游戏','tech',660,'这个游戏包含一些需要玩家快速反应并展示一定技巧（即使少量）才能获胜的小游戏。');
INSERT INTO "tags" VALUES ('g273','体弱多病的主角','cont',206,'这个游戏的主角患有疾病，在故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g274','地牢爬行游戏','tech',179,'这个游戏有一些RPG部分，基本上是探索迷宫般的地牢并遭遇敌人战斗。');
INSERT INTO "tags" VALUES ('g275','主角的对手作为女主角','cont',152,'本游戏有一个或多个与主角存在竞争关系的女主角。这些女主角在与竞争相关的事件中会获得许多场景。

这不应与[url=/g1250]作为女主角的对手[/url]标签混淆，因为竞争（Rivalry）指的是持续较长时间的竞争关系，而对手可能只是一面之缘的人。

使用该标签不需要竞争是相互的。');
INSERT INTO "tags" VALUES ('g276','间谍女主角','cont',95,'本游戏中的女主角是一名特工或[url=http://en.wikipedia.org/wiki/Spy]间谍[/url]。她为政府或私人组织工作，拥有多种技能和许多秘密。');
INSERT INTO "tags" VALUES ('g277','动物','cont',1327,'某些游戏的故事与[url=http://en.wikipedia.org/wiki/Animals]动物[/url]有着紧密的联系。这些标签适用于这类游戏。');
INSERT INTO "tags" VALUES ('g278','猫','cont',431,'本游戏中有一只或多只[url=http://en.wikipedia.org/wiki/Cats]猫[/url]在故事中扮演重要角色。或者游戏中许多场景中都有猫，且有大量与它们相关的对话。');
INSERT INTO "tags" VALUES ('g279','狗','cont',271,'本游戏中有一只或多只[url=http://en.wikipedia.org/wiki/Dogs]狗[/url]在故事中扮演重要角色。或者游戏中许多场景中都有狗，且有大量与它们相关的对话。');
INSERT INTO "tags" VALUES ('g280','濒死主角','cont',97,'本游戏的主角患有[url=http://en.wikipedia.org/wiki/Terminal_illness]绝症[/url]。要么从游戏一开始就患病，要么在大部分时间里患病。');
INSERT INTO "tags" VALUES ('g281','疾病','cont',521,'疾病在这个故事中扮演重要角色。游戏花了很多时间来讨论它。');
INSERT INTO "tags" VALUES ('g282','绝症','cont',334,'在游戏中，有人因[url=http://en.wikipedia.org/wiki/Terminal_illness]绝症[/url]而濒临死亡。');
INSERT INTO "tags" VALUES ('g283','交通工具','cont',864,'本游戏中有一些交通工具在故事中扮演重要角色。可能是在船上度过的时光，也可能是一个总是滔滔不绝谈论自己汽车的主角……');
INSERT INTO "tags" VALUES ('g284','汽车','cont',77,'本游戏中有一辆对故事至关重要的[url=http://en.wikipedia.org/wiki/Car]汽车[/url]。也许这是一款公路旅行游戏，或者是一款拥有大量汽车和许多细节的赛车游戏。');
INSERT INTO "tags" VALUES ('g285','类型','tech',0,'如果本游戏属于你无法用现有标签命名的故事类型，你可以使用这些标签。');
INSERT INTO "tags" VALUES ('g286','公路旅行','cont',80,'[url=http://en.wikipedia.org/wiki/Road_trip]维基百科[/url]对该术语的描述：公路旅行是一种通过汽车进行的旅程，有时是计划外的或即兴的，或者是一次涉及离家参加体育比赛的旅程，因此涵盖了任何乘汽车的旅行，无论途中是否停留。

本游戏是一个公路旅行故事，或者至少包含一段在游戏中占相当比重的公路旅行。');
INSERT INTO "tags" VALUES ('g287','不朽女主角','cont',2248,'其中一位女主角是[url=http://en.wikipedia.org/wiki/Immortality]不朽的[/url]，她不会衰老，也无法被常规方式杀死。');
INSERT INTO "tags" VALUES ('g288','疯狂','cont',501,'本游戏中的一个或多个角色要么[url=http://en.wikipedia.org/wiki/Insanity]精神错乱[/url]，要么表现出开始发疯的早期症状。');
INSERT INTO "tags" VALUES ('g289','治疗者女主角','cont',1024,'本游戏的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Healer]治疗者[/url]——无论是使用魔法的牧师、擅长草药的专家还是真正的医生。

通常性格温和（甚至到了母性的程度），是RPG游戏中的常见设定。');
INSERT INTO "tags" VALUES ('g290','多重人格女主角','cont',206,'一位或多位女主角拥有多重人格——这可能有心理原因，也可能是真正的第二人格。

虽然现代的傲娇有时看起来很像，但它们不符合条件。');
INSERT INTO "tags" VALUES ('g291','拥有超能力另一面的女主角','cont',46,'一位或多位女主角拥有比正常人格强大得多的第二人格。');
INSERT INTO "tags" VALUES ('g292','短暂女性主角','tech',349,'本游戏允许你在短时间内扮演女性主角。

请记住，这段短暂的时间仍然应该足够长，以值得提及。

例如；如果一款上百小时的游戏只让你扮演五分钟女性主角，请不要对该游戏使用此标签。

也不要将此标签用于仅短暂从女主角视角进行游戏的作品，例如《G-sen》和《Crescendo》（应使用[url=/g633]其他视角[/url]标签），而是要更像《F/SN》那样真正扮演其中一位。');
INSERT INTO "tags" VALUES ('g293','囚禁','cont',953,'游戏发生在一栋建筑、地形或维度中，角色无法逃离。

他们可能被法律监禁、被限制在精神病院，或被他人非法关押，例如在绑架期间。

该标签与[url=/g2978]搁浅[/url]标签的主要区别在于，囚禁是关于逃跑或首先达到目标，而搁浅则主要是关于生存并常常等待救援。');
INSERT INTO "tags" VALUES ('g294','公主女主角','cont',730,'这部视觉小说中至少有一位女主角是西式[url=http://en.wikipedia.org/wiki/Princess]公主[/url]。通常这意味着她是君主的女儿或近亲。

关于她的外貌，她可能穿着礼服（不过她可能穿盔甲战斗，或穿校服以融入环境），并戴着王冠。

只要符合形象，她不必来自西方（许多奇幻公主属于此类，而非姬原型）。');
INSERT INTO "tags" VALUES ('g295','姬公主女主角','cont',40,'至少有一位女主角是东方式公主，并且是地方领主或国王的女儿——被其他角色称为[url=http://en.wikipedia.org/wiki/Hime]姬[/url]并不足以使女主角符合此标签。

例子包括《Amatsukaze》中的沙夜姬和《Ouzoku》中的一叶。');
INSERT INTO "tags" VALUES ('g296','忍者主角','cont',66,'本游戏的主角是一位[url=http://en.wikipedia.org/wiki/Ninja]忍者[/url]。');
INSERT INTO "tags" VALUES ('g297','地图移动','tech',2470,'玩家可以在地图上选择要去的地方，无论是世界地图还是校园地图。

地图移动的一些视觉示例：[url=https://s.vndb.org/sf/87/108887.jpg]1[/url], [url=https://s.vndb.org/sf/90/39090.jpg]2[/url], [url=https://s.vndb.org/sf/55/33655.jpg]3[/url], [url=https://s.vndb.org/sf/51/32951.jpg]4[/url], [url=https://s.vndb.org/sf/99/31299.jpg]5[/url]。');
INSERT INTO "tags" VALUES ('g298','护士支援角色','cont',179,'游戏中的支援角色之一是护士。');
INSERT INTO "tags" VALUES ('g299','校医支援角色','cont',109,'游戏中的支援角色之一是校医。');
INSERT INTO "tags" VALUES ('g300','后期性内容','ero',585,'本游戏的性内容出现在游戏接近尾声时（例如，在一款三十小时的游戏中，至少是在最后几个小时）。');
INSERT INTO "tags" VALUES ('g301','中世纪欧洲','cont',68,'本游戏有场景设定在[url=http://en.wikipedia.org/wiki/Middle_Ages]中世纪欧洲[/url]。');
INSERT INTO "tags" VALUES ('g302','政治','cont',529,'本游戏有详细政治讨论的场景。

详情请参阅相关的[url=http://en.wikipedia.org/wiki/Politics]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g304','大量性内容','ero',10809,'这部视觉小说有大量性爱场景：大约一半或更多的游戏时间用于露骨的性内容。');
INSERT INTO "tags" VALUES ('g305','场景','cont',0,'这些标签用于游戏的主要地点，请不要标记你在游戏中看到的每个地点，而只标记那些占据游戏至少三分之一左右时间的地点。');
INSERT INTO "tags" VALUES ('g306','宫殿','cont',89,'这部视觉小说有许多场景设定在皇家[url=http://en.wikipedia.org/wiki/Palace]宫殿[/url]中。');
INSERT INTO "tags" VALUES ('g307','亚洲风格宫殿','cont',18,'本游戏有许多场景设定在亚洲风格的宫殿中。');
INSERT INTO "tags" VALUES ('g308','住所','cont',3305,'本游戏有许多场景设定在用作个人、家庭、住户或几个家庭的永久或半永久住所的居住空间内。');
INSERT INTO "tags" VALUES ('g309','西式庄园','cont',686,'本游戏有许多场景设定在西式大宅中。');
INSERT INTO "tags" VALUES ('g310','亚洲风格庄园','cont',62,'本游戏有许多场景设定在亚洲风格的庄园中。');
INSERT INTO "tags" VALUES ('g311','城堡','cont',201,'本游戏有许多场景设定在城堡中。');
INSERT INTO "tags" VALUES ('g312','西式城堡','cont',126,'本游戏有许多场景设定在西式城堡中。');
INSERT INTO "tags" VALUES ('g313','亚洲风格城堡','cont',17,'本游戏有许多场景设定在亚洲风格的城堡中。');
INSERT INTO "tags" VALUES ('g314','军事基地','cont',49,'本游戏有许多场景设定在军事基地上。');
INSERT INTO "tags" VALUES ('g315','游乐园','cont',128,'这部视觉小说有许多场景设定在[url=http://en.wikipedia.org/wiki/Amusement_park]游乐园[/url]或主题公园中。');
INSERT INTO "tags" VALUES ('g316','宗教场所','cont',465,'本游戏有许多场景设定在宗教场所。');
INSERT INTO "tags" VALUES ('g317','寺庙','cont',40,'这部视觉小说有许多场景设定在[url=http://en.wikipedia.org/wiki/Temple]寺庙[/url]中。

对于基督教堂，请使用[url=http://vndb.org/g318]教堂[/url]标签。');
INSERT INTO "tags" VALUES ('g318','教堂','cont',226,'这部视觉小说有相当多的场景设定在[url=http://en.wikipedia.org/wiki/Church_%28building%29]教堂[/url]中。');
INSERT INTO "tags" VALUES ('g319','神社','cont',175,'这部视觉小说有许多场景设定在[url=http://en.wikipedia.org/wiki/Shinto_shrine]神社[/url]中。');
INSERT INTO "tags" VALUES ('g320','多重人格主角','cont',142,'主角患有[url=http://en.wikipedia.org/wiki/Split_Personality]分裂人格[/url]。

解离性身份障碍是一种精神科诊断，描述一个人表现出多种截然不同的身份或人格（称为替换自我或替身）的状况，每种身份或人格都有自己感知和与环境互动的方式。');
INSERT INTO "tags" VALUES ('g321','阴谋','cont',561,'本游戏中有阴谋、秘密计划以及各种暗地里的交易。');
INSERT INTO "tags" VALUES ('g322','犯罪','cont',4582,'这是一个犯罪故事。或者至少有一些法律与秩序、犯罪生活等主题在其中扮演重要角色。

不要将其用于包含一个或多个犯罪行为内容的游戏。游戏必须围绕某个具体罪行展开，比如银行抢劫的故事，或犯罪世界中人物的生活。');
INSERT INTO "tags" VALUES ('g323','侦探工作','cont',1212,'本游戏包含一个或多个角色以[url=http://en.wikipedia.org/wiki/Detective]侦探[/url]的身份工作，以严肃的专业/半专业方式收集线索并调查某些谜团。');
INSERT INTO "tags" VALUES ('g324','悬念','cont',689,'本游戏包含许多秘密和谜团。随着故事进展，紧张感逐渐积累至激动人心的高潮。或者至少这是其意图。');
INSERT INTO "tags" VALUES ('g325','斗智','cont',202,'本游戏包含至少两个人或两个群体运用智慧和快速思考能力试图击败对方的场景。

这可以通过对立双方运用许多阴谋诡计来试图智胜对方，和/或在漫长的辩论交锋中将其逼入绝境来体现。');
INSERT INTO "tags" VALUES ('g326','天才主角','cont',268,'本游戏的主角是一位天才。');
INSERT INTO "tags" VALUES ('g327','虚构世界中的过去背景','cont',1223,'本游戏设定在一个时间线类似我们世界过去的虚构世界中。');
INSERT INTO "tags" VALUES ('g328','虚构世界中的现代背景','cont',217,'本游戏设定在一个时间线类似我们现代世界的虚构世界中。');
INSERT INTO "tags" VALUES ('g329','虚构世界中的未来背景','cont',138,'本游戏设定在一个时间线类似我们世界未来版本的虚构世界中。');
INSERT INTO "tags" VALUES ('g330','游戏玩法元素','tech',0,'这些标签用于描述游戏具有的特定玩法元素，并非用来定义游戏类型。');
INSERT INTO "tags" VALUES ('g331','猫娘女主角','cont',470,'本游戏的一位或多位女主角是猫娘。');
INSERT INTO "tags" VALUES ('g332','战斗公主女主角','cont',75,'至少有一位女主角是西式公主，但与通常版本不同，这位公主会亲临前线指挥战斗。
通常身穿板甲或锁子甲，手持剑。常有强烈的正义感，但不是必须。');
INSERT INTO "tags" VALUES ('g333','召唤','cont',155,'本游戏的一个或多个角色拥有以魔法（或用科幻解释）召唤人物或生物为其战斗或听命的能力。

不严肃的例子包括《宝可梦》。
严肃的例子包括《舞-HiME》中的Childs和《圣なるかな》中的Shinjuu。');
INSERT INTO "tags" VALUES ('g334','具备战斗能力的伙伴','cont',354,'本游戏中主角的伙伴能够在战斗中自我保护。

例如可以说主角的挚友也会参与战斗——通常是为了保护主角的后背，但他也可能变成主角的宿敌。');
INSERT INTO "tags" VALUES ('g335','跨维度组织','cont',14,'一个致力于保护某些理想和/或秩序的跨维度组织在游戏中扮演重要角色。');
INSERT INTO "tags" VALUES ('g336','三角恋','cont',747,'本游戏有一个故事元素，其中两个角色相互竞争或较量，以赢得一个人（通常是主角）的爱。无论是最终与一人约会、与两个恋爱对象都约会，还是根本没有任何结果，都不重要。

如果游戏侧重于三角恋的戏剧或喜剧方面，请使用相应的子标签；但如果两者兼有，则请使用此标签。');
INSERT INTO "tags" VALUES ('g337','戏剧性三角恋','cont',262,'游戏中存在三角恋，它是角色之间冲突和痛苦的来源。');
INSERT INTO "tags" VALUES ('g338','喜剧性三角恋','cont',144,'游戏中存在三角恋，但这是为了搞笑——不会导致角色痛苦或心碎的戏剧性情境。');
INSERT INTO "tags" VALUES ('g339','SRPG','tech',167,'这些游戏将RPG玩法与策略相结合——通常角色定制选项比其他RPG少，更注重战斗战术。');
INSERT INTO "tags" VALUES ('g340','跨维度奥德赛','cont',18,'在故事的大部分中，主角（及其同伴）从一个维度旅行到另一个维度——无论他们是想寻找回家的路，还是有着更崇高的理想。');
INSERT INTO "tags" VALUES ('g341','邪恶路线','tech',227,'本游戏有一条额外的邪恶路线，主要内容是强奸、谋杀和各种大多数人不想看到的事情。

好的一面是，这一切都集中在一个路线中，所以你完全可以避开它。

将本标签用于那些一条或多条路线与其他路线不同且充满更黑暗内容的游戏。');
INSERT INTO "tags" VALUES ('g342','双胞胎姐妹支援角色','cont',69,'本游戏有一位[url=http://en.wikipedia.org/wiki/Twins]双胞胎[/url]姐妹作为支援角色登场。');
INSERT INTO "tags" VALUES ('g343','双胞胎姐妹作为女主角','cont',587,'本游戏的女主角是[url=http://en.wikipedia.org/wiki/Twins]双胞胎[/url]。即使只有其中一位双胞胎有路线，也可以使用本标签。');
INSERT INTO "tags" VALUES ('g344','幽灵','cont',980,'[url=http://en.wikipedia.org/wiki/Ghost]鬼魂[/url]是死者或动物的灵魂或精神，能以可见形式或其他显现方式出现在活人面前。');
INSERT INTO "tags" VALUES ('g345','外星人','cont',555,'本视觉小说包含[url=http://en.wikipedia.org/wiki/Extraterrestrial_life]外星生命[/url]。');
INSERT INTO "tags" VALUES ('g346','残疾女主角','cont',62,'一位因身体部位变形、受伤或截肢而导致身体能力严重受损的女主角。');
INSERT INTO "tags" VALUES ('g347','节奏游戏','tech',109,'本游戏包含根据音乐进行按键或鼠标点击的玩法。

详情请查阅相关的[url=http://en.wikipedia.org/wiki/Rhythm_game]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g349','时间循环','cont',484,'故事涉及时间循环，即一段时间（一天、一周等）不断重复。');
INSERT INTO "tags" VALUES ('g350','互动冒险游戏','tech',1635,'这类游戏通过文本输入 , 点击或 "look/examine/talk to"-式界面与世界互动。

通过常规对话选项选择进行的互动不属于此标签字段。');
INSERT INTO "tags" VALUES ('g351','荒诞','tech',316,'这类游戏的故事常常甚至不打算讲得通。不要与仅仅是错综复杂或令人困惑的情节混淆，这里指的是情节的概念被完全抛弃的情况。

详情请查阅维基百科的[url=http://en.wikipedia.org/wiki/Literary_nonsense]文学荒诞[/url]条目。');
INSERT INTO "tags" VALUES ('g352','存在危机','cont',204,'主角被迫面对关于现实本质或自身感知准确性的重大不确定性。');
INSERT INTO "tags" VALUES ('g353','妖怪','cont',673,'本游戏包含[url=http://en.wikipedia.org/wiki/Y%C5%8Dkai]妖怪[/url]。

妖怪种类繁多，从恶毒到顽皮，偶尔也会给遇到它们的人带来好运。它们通常具有动物特征（例如类似乌龟的河童，或长翅膀的天狗），有时看起来几乎与人类无异，有些则像无生命的物体，还有些没有可辨认的形状。妖怪通常拥有灵异超自然力量，其中变化形态最为常见。能够变形的妖怪被称为お化け（obake）。');
INSERT INTO "tags" VALUES ('g354','反派主角','cont',1267,'本游戏的主角是[url=http://en.wikipedia.org/wiki/Villainous]反派[/url]，或者仅仅是故事中的“邪恶”角色。

一开始就是坏人或者后来变坏，然后又变好等等，只要反派部分在故事中占据重要角色，这些都无所谓。');
INSERT INTO "tags" VALUES ('g355','简短的NVL场景','tech',1216,'本游戏实际上是ADV（冒险游戏），但有时其叙述会切换到NVL（小说式）模式。这些场景通常足以引人注意，但仍未达到游戏三分之一的篇幅。');
INSERT INTO "tags" VALUES ('g356','戏仿','cont',807,'戏仿是一种以夸张方式模仿另一部作品、艺术家或流派风格的作品，通常为了喜剧效果。它利用原作的框架，通过夸大原作的缺陷或使之平庸化，或在某些情况下两者兼有，来加入喜剧元素。戏仿可以采取多种形式，包括小说、诗歌、电影、视觉艺术等。');
INSERT INTO "tags" VALUES ('g357','一男多女的群交','ero',4534,'本视觉小说包含群交场景，即多个女性伴侣与一名男性发生性关系。

为了数据库的目的，该标签采用二元性别理解，“Male”指顺性别男性，即出生时被指定为男性且认同为男性。“Female”指顺性别女性，即出生时被指定为女性且认同为女性。');
INSERT INTO "tags" VALUES ('g358','一女多男的群交','ero',3600,'本视觉小说包含群交场景，即多个男性伴侣与一名女性发生性关系。

为了数据库的目的，该标签采用二元性别理解，“Male”指顺性别男性，即出生时被指定为男性且认同为男性。“Female”指顺性别女性，即出生时被指定为女性且认同为女性。');
INSERT INTO "tags" VALUES ('g359','性别转换','cont',337,'故事中的主角或其他某个角色通过魔法或[url=http://en.wikipedia.org/wiki/Sex_reassignment_surgery]医学手术[/url]手段，或因卷入奇怪的科学事故而改变性别。');
INSERT INTO "tags" VALUES ('g360','其他元素','cont',0,'这些标签是故事中不属于其他组的元素。');
INSERT INTO "tags" VALUES ('g363','奥德赛','cont',124,'在故事的大部分篇幅中，主角（及其同伴）从一个地方旅行到另一个地方 - 无论是试图找到回家的路，还是有某种更崇高的理想。');
INSERT INTO "tags" VALUES ('g364','间谍活动','cont',87,'游戏故事涉及[url=http://en.wikipedia.org/wiki/Espionage]间谍活动[/url]。间谍活动指政府或个人在未经信息持有者许可的情况下获取被视为秘密或机密的信息。');
INSERT INTO "tags" VALUES ('g367','残废主角','cont',37,'因身体部位变形、受伤或截肢而导致身体能力严重受损的主角。');
INSERT INTO "tags" VALUES ('g368','音乐主题','cont',299,'本游戏的故事围绕[url=http://en.wikipedia.org/wiki/Music]音乐[/url]展开。');
INSERT INTO "tags" VALUES ('g369','残疾主角','cont',118,'主角有一种或多种残疾——他可能是盲人、聋人、哑巴或缺少肢体。

如需标记身体残疾，请使用此标签；对于精神残疾，请改用[url=/g500]患有心理问题的主角[/url]。');
INSERT INTO "tags" VALUES ('g370','有健康问题的主角','cont',2165,'对于可以用于身体状况不佳的主角的标签。

如果你认为该主角未被其任何子标签覆盖，你也可以直接使用此标签。');
INSERT INTO "tags" VALUES ('g371','主角的性别','cont',0,NULL);
INSERT INTO "tags" VALUES ('g372','麻将作为游戏元素','tech',174,'[url=https://en.wikipedia.org/wiki/Mahjong]麻将[/url]是一种起源于中国的四人游戏。游戏中，每位玩家手中有十三张或十六张牌（取决于所玩的变体）。轮到玩家时，玩家摸一张牌并打出一张，目标是要组成四组或五组面子（也取决于变体）和一对“雀头”。和牌是在“摸牌”时发生的，即摸到一张新牌或别人打出的牌来凑成完整手牌。因此，一副和牌实际上包含十四张（或十七张）牌。

仅当视觉小说中确实存在麻将小游戏时才使用此标签。如果它仅作为剧情元素使用，请使用[url=http://vndb.org/g1290]麻将作为剧情元素[/url]。');
INSERT INTO "tags" VALUES ('g373','学生女主角','cont',7841,'本游戏中的一名或多名女主角是[url=http://en.wikipedia.org/wiki/Student]学生[/url]。');
INSERT INTO "tags" VALUES ('g374','有健康问题的女主角','cont',1934,'对于可以用于身体状况不佳的女主角的标签。

如果你认为该女主角未被其任何子标签覆盖，你也可以直接使用此标签。');
INSERT INTO "tags" VALUES ('g375','女主角的角色/职业','cont',0,'以她们（谋生）所做的事情或她们在社会中扮演的[url=http://en.wikipedia.org/wiki/Role]角色[/url]来定义的女主角原型。

也包括那些已不再从事该工作（角色等）但仍然表现得像该角色一样的人物。');
INSERT INTO "tags" VALUES ('g376','女主角的关系','cont',0,'这些是根据女主角与主角的[url=http://en.wikipedia.org/wiki/Kinship]关系[/url]来划分的女主角原型。');
INSERT INTO "tags" VALUES ('g377','机甲','cont',202,'本游戏包含由人类飞行员直接操作的机器人和/或机甲。');
INSERT INTO "tags" VALUES ('g378','性内容的实现方式','ero',0,'此元标签下列出的标签定义了本游戏中性内容的实现方式。 

性内容多到令人惊讶？或者也许每条路线只有一幕……');
INSERT INTO "tags" VALUES ('g380','早期性内容','ero',2132,'本游戏中的性内容在游戏开始时就出现（例如，在一个三十小时的游戏中，至少出现在最初几个小时）。');
INSERT INTO "tags" VALUES ('g381','按参与者分类的性内容','ero',0,'这些是按参与者分类或以其当前状态为主要特征的性内容标签。');
INSERT INTO "tags" VALUES ('g382','较阴暗的性内容','ero',7861,'这些性内容标签并非适合所有人。');
INSERT INTO "tags" VALUES ('g383','精灵女主角','cont',512,'其中一位女主角是[url=http://en.wikipedia.org/wiki/Elves_in_fantasy_fiction_and_games]精灵[/url]。

在许多现代奇幻作品中，精灵被描绘为一个半神般的人形种族，与自然和动物友好相处。

奇幻精灵的一个标志性特征也是他们修长而尖的耳朵。这些耳朵的长度和形状因艺术家或媒介的不同而异。与人类相比，精灵往往不朽或长寿，更美丽、更聪明，感官和知觉更敏锐，并且拥有看似异界或魔法的能力和技艺。

此标签不指那种小不点的小精灵。');
INSERT INTO "tags" VALUES ('g385','女主角的特质','cont',0,'定义女主角的角色特质。');
INSERT INTO "tags" VALUES ('g386','徒手战斗的女主角','cont',55,'一名或多名女主角徒手战斗，并且能够用赤手空拳杀死人。

详情请参阅相关的[url=http://en.wikipedia.org/wiki/Hand-to-hand_combat]维基百科[/url]文章。');
INSERT INTO "tags" VALUES ('g387','卖淫','cont',849,'这些游戏包含涉及[url=http://en.wikipedia.org/wiki/Prostitution]卖淫[/url]的场景。');
INSERT INTO "tags" VALUES ('g388','伪娘女主角','cont',486,'这款视觉小说中至少有一位女主角实际上是男孩，其外貌特征让他看起来像女孩，以至于可能会被误认为是女孩。
[url=http://en.wikipedia.org/wiki/Cross_dressing]异性装扮[/url]并非必需，但往往是造成混淆的原因。');
INSERT INTO "tags" VALUES ('g389','学校宿舍','cont',319,'游戏的一部分发生在[url=http://en.wikipedia.org/wiki/Dormitory]宿舍[/url]中。

宿舍（dormitory），在美国常简写为 dorm，是一种住宿楼，由睡眠区或整栋建筑组成，主要为大量人群提供睡眠和居住空间，通常是寄宿学校、学院或大学的学生。在英国，这个词有一个更早但不同但相关的含义：它特指许多人共同睡觉的单独房间，通常见于寄宿学校。英式英语中对应美式大学建筑的说法是 hall of residence，常简写为 halls。');
INSERT INTO "tags" VALUES ('g390','沉默的主角','cont',71,'主角在整个游戏过程中一言不发。这可能基于某种形式的[url=http://en.wikipedia.org/wiki/Muteness]缄默[/url]或一种游戏机制。

例如，大多数JRPG角色在整个游戏过程中从不说话，但剧情角色表现得好像他说过话，并与他进行单方面的对话。可能是在假设你，玩家，在与你的电视/显示器之类的东西说话……');
INSERT INTO "tags" VALUES ('g391','血亲父女乱伦','ero',275,'这些游戏包含有血缘关系的父亲与女儿之间的性爱场景。');
INSERT INTO "tags" VALUES ('g392','涉及卖淫的性行为','ero',450,'这些游戏含有涉及卖淫的性爱场景，即参与者中的一方为了金钱或类似利益而参与其中。

[url=https://en.wikipedia.org/wiki/Prostitution]卖淫[/url]是以性关系换取金钱或其他利益的行为或行业。卖淫有时被描述为商业性行为。 

日本一种常见的卖淫形式被称为[url=https://en.wikipedia.org/wiki/JK_business]JK行业[/url]（Enjo-kousai），意思是“补偿性约会”，这是一种年长男性给有魅力的女性金钱和/或奢侈品礼物，以换取她们的陪伴，甚至可能换取性恩惠的做法。');
INSERT INTO "tags" VALUES ('g393','伪娘配角','cont',116,'这部视觉小说中至少有一个配角是男孩，他的外貌特征使他看起来像女孩，甚至可能被误认为是女孩。
[url=http://en.wikipedia.org/wiki/Cross_dressing]变装[/url]并不是必要条件，但常常是混淆的根源。');
INSERT INTO "tags" VALUES ('g394','怀孕','cont',3632,'涉及怀孕的故事。');
INSERT INTO "tags" VALUES ('g395','失明主角','cont',30,'主角（或者，视角角色）患有光学性、神经性或神经系统性失明。');
INSERT INTO "tags" VALUES ('g396','孕期性行为','ero',2313,'这部视觉小说包含与[url=http://en.wikipedia.org/wiki/Pregnancy]怀孕[/url]女性的性行为。');
INSERT INTO "tags" VALUES ('g397','竖排文本','tech',228,'本游戏中的文本以纵向而非横向显示。');
INSERT INTO "tags" VALUES ('g398','浮动文本框','tech',1010,'文本框不处于固定位置，而是可能以不同的位置和大小出现在屏幕上。

[例: Quartett, Gekkou no Carnevale]');
INSERT INTO "tags" VALUES ('g399','呈现方式','tech',0,'描述游戏外观和感受的标签。不是游戏如何游玩，而是游戏内容如何呈现给读者。

详情请参阅相关的[url=http://en.wikipedia.org/wiki/Presentation]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g400','非人类主角','cont',2204,'主角可能看起来像人类，其他角色可能以为主角是人类，但实际上主角并非人类。');
INSERT INTO "tags" VALUES ('g401','戴眼镜的主角','cont',973,'主角戴着眼镜。');
INSERT INTO "tags" VALUES ('g402','配音','tech',4580,'这个元标签用于容纳那些详细说明游戏中配音使用方式的标签。 

如果主角有配音，是只有女主角的台词部分配音，还是游戏的每一句台词都有配音，包括角色的想法等等……');
INSERT INTO "tags" VALUES ('g403','主角的特质','cont',0,'定义主角的角色特质。');
INSERT INTO "tags" VALUES ('g404','主角的角色/职业','cont',0,'主角原型由他们（为谋生）所做的事情或他们在社会中所扮演的[url=http://en.wikipedia.org/wiki/Role]角色[/url]来定义。

也包括那些已经不再从事这项工作（角色等）但仍然表现得像该角色一样的人物。');
INSERT INTO "tags" VALUES ('g406','强奸犯主角','ero',670,'这部VN中的主角表现出实施强奸的倾向。不要把这个标签用于每一款允许你犯下一两次强奸（很可能导致坏结局）的游戏，而要用于那些将强奸养成习惯的游戏。

通常，这样的主角是一个不知悔改的罪犯，尽管在某些情况下，他们可能会编造自己的理由，认为自己强奸某些角色是可以的。');
INSERT INTO "tags" VALUES ('g407','因必要性而发生的性行为','ero',462,'角色们有一个约束性的、强制性的理由发生性行为。通常很离奇，比如“这种重病只能用主角的特殊精液治愈”或“她变强的唯一方法就是发生性行为”。');
INSERT INTO "tags" VALUES ('g409','双胞胎作为配角','cont',146,'本游戏至少有一对[url=http://en.wikipedia.org/wiki/Twins]双胞胎[/url]作为配角。');
INSERT INTO "tags" VALUES ('g411','痴汉主角','ero',131,'主角是一名[url=http://en.wikipedia.org/wiki/Frotteurism]摩擦癖者[/url]。');
INSERT INTO "tags" VALUES ('g413','扶她女主角','cont',475,'本游戏中的一名或多名女主角同时拥有男性和女性生殖器。通常（但不必然）与其他女性特征相伴随。

详情请参阅相关的[url=http://en.wikipedia.org/wiki/Hermaphrodite]维基百科[/url]页面。');
INSERT INTO "tags" VALUES ('g414','堂表亲乱伦','ero',524,'这些游戏包含两个（或更多）堂表亲之间的性爱场景。他们可能有血缘关系，也可能没有。');
INSERT INTO "tags" VALUES ('g415','堂表亲恋爱','cont',142,'这些游戏包含堂表亲之间的恋爱。');
INSERT INTO "tags" VALUES ('g416','主角的堂表亲作为女主角','cont',566,'一位或多位女主角是主角的[url=http://en.wikipedia.org/wiki/Cousin]表亲[/url]。

表亲是指与一个人共享一个或多个共同祖先的亲属（不是父母、子女/后代、兄弟姐妹、兄弟姐妹的子女/后代，或父母/祖先的兄弟姐妹）。然而在日常用语中，“表亲”通常特指“第一代堂/表亲”。');
INSERT INTO "tags" VALUES ('g417','实时3D','tech',267,'游戏中的大部分图形是3D模型，实时渲染。');
INSERT INTO "tags" VALUES ('g418','返乡','cont',191,'这款游戏中的一些角色回到他们的家乡，通常是主角。这可能只是关于那个人的经历，也可能与相关的大事有关，比如[url=http://en.wikipedia.org/wiki/Homecoming]返乡[/url]庆祝活动。');
INSERT INTO "tags" VALUES ('g420','同一屋檐下','cont',1969,'主角与其中一位女主角/男主角在同一个家中生活了很长一段时间。他们不一定共享卧室，但至少必须有共同的餐厅、厨房、卫生间等设施。');
INSERT INTO "tags" VALUES ('g421','伪娘主角','cont',315,'这部视觉小说的主角是一个男孩，他的外貌特征使他看起来像个女孩，以至于可能被误认为是女孩。
[url=http://en.wikipedia.org/wiki/Cross_dressing]异装[/url]并非必要条件，但往往是混淆的来源。');
INSERT INTO "tags" VALUES ('g422','救世主主角','cont',25,'主角被宣告为“天选之人”，伴随着预言、预兆等等。');
INSERT INTO "tags" VALUES ('g423','女子学校','cont',445,'这款游戏以一所只招收女生的学校为背景。');
INSERT INTO "tags" VALUES ('g424','岛屿','cont',609,'这部视觉小说的很大一部分发生在一个小型的（或者说有点小的）[url=http://en.wikipedia.org/wiki/Island]岛屿[/url]上。');
INSERT INTO "tags" VALUES ('g425','保镖主角','cont',80,'这款游戏的主角是一名[url=http://en.wikipedia.org/wiki/Bodyguard]保镖[/url]。');
INSERT INTO "tags" VALUES ('g427','照片立绘','tech',271,'角色不是通过绘画或CG来表现，而是使用演员的照片。');
INSERT INTO "tags" VALUES ('g428','音乐环境','cont',124,'游戏大部分发生在音乐环境中——例如乐队、管弦乐团、音乐学校或类似场所。');
INSERT INTO "tags" VALUES ('g431','成长戏剧','cont',233,'故事的部分内容叙述了人物从青春期到成年的转变。');
INSERT INTO "tags" VALUES ('g432','转世','cont',341,'游戏中的一个或多个角色，无论人类与否，都是已故之人（或动物或神）的[url=http://en.wikipedia.org/wiki/Reincarnation]转世[/url]。');
INSERT INTO "tags" VALUES ('g433','照片背景','tech',2524,'游戏中的背景原本是照片。可能经过一定程度的滤镜处理，但仍然能明显看出来是照片。');
INSERT INTO "tags" VALUES ('g434','后宫结局','tech',3036,'这款游戏有[url=http://en.wikipedia.org/wiki/Harem]后宫[/url]结局。

这意味着你可以达到一个结局，主角同时被多位女主角爱着，并且以某种方式设法保持她们所有人的关系，而不选择其中一个。

这种情况可能导致情色（导致群体性行为场景）和喜剧（你在那些后宫动漫中看到的东西）结局。');
INSERT INTO "tags" VALUES ('g437','平台游戏','tech',25,'带有此标签的游戏有一定数量的跳上跳下悬浮平台的内容。它们可能是在2D平台游戏中的地牢地面，或者是在3D平台游戏中爬山。');
INSERT INTO "tags" VALUES ('g438','神灵','cont',905,'带有此标签的游戏的登场角色中会有一些超自然的神灵、男神或女神。他们可能源自某个流行神话，也可能基于游戏原创故事。或者，如果游戏足够大胆，他们可能来自世界上公认的某个宗教。');
INSERT INTO "tags" VALUES ('g439','永生主角','cont',1276,'主角是不朽的，不会衰老，也无法通过常规方式被杀死。');
INSERT INTO "tags" VALUES ('g440','神主角','cont',146,'这部视觉小说的主角是[url=http://en.wikipedia.org/wiki/Deity]神[/url]。');
INSERT INTO "tags" VALUES ('g441','同事女主角','cont',331,'其中一位女主角与主角在同一个地方工作，无论是偶尔还是长期。');
INSERT INTO "tags" VALUES ('g442','虚拟现实','cont',313,'这部视觉小说有一个独立的、清晰可辨的虚拟世界，可以通过‘技术’手段进入。');
INSERT INTO "tags" VALUES ('g443','执念','cont',952,'其中一个角色有着在这个故事中扮演重要角色的执念。可能是主角念念不忘的复仇，也可能是女主角痴迷于揭露某个真相。

不要将本标签用于女主角坚持要吃某物的游戏……而是用于当它是心理戏剧因素的游戏。');
INSERT INTO "tags" VALUES ('g444','复仇','cont',786,'这款游戏中的一个角色一心只想复仇。他或她会为复仇不惜一切代价……');
INSERT INTO "tags" VALUES ('g445','恐怖主义','cont',145,'这部视觉小说的情节中包含[url=http://en.wikipedia.org/wiki/Terrorism]恐怖主义[/url]行为。');
INSERT INTO "tags" VALUES ('g446','黑客主角','cont',64,'这部视觉小说的主角是一名[url=http://en.wikipedia.org/wiki/Hacker_%28term%29]黑客[/url]。');
INSERT INTO "tags" VALUES ('g447','自定义','tech',7217,'这款游戏允许你自定义角色、载具等。任何超越通常角色扮演游戏中基本的拾取（和装备）物品及装备细节的详细自定义都可视为自定义。');
INSERT INTO "tags" VALUES ('g448','新游戏+','tech',178,'本游戏允许你在未来的游戏会话中使用之前通关的存档。允许在每次重玩时进一步培养角色并访问更高级别的内容等。

查看相关 [url=http://en.wikipedia.org/wiki/New_Game_Plus]维基百科[/url] 文章了解详情。');
INSERT INTO "tags" VALUES ('g449','图形','tech',0,'所有与游戏图形呈现方式、精灵、动画等相关的标签都放在这里。

查看相关 [url=http://en.wikipedia.org/wiki/Graphics#Computer_graphics]维基百科[/url] 文章了解详情。');
INSERT INTO "tags" VALUES ('g450','可选游戏玩法','tech',94,'本游戏中的小游戏和战斗序列是可选的。它们可以轻松关闭和/或跳过，无需游玩哪怕一次。当然，除了开场介绍或简短教程之外。');
INSERT INTO "tags" VALUES ('g451','可跳过的游戏玩法','tech',102,'本游戏中的小游戏和战斗序列在通关一次后即可跳过。有些游戏可能需要通关不止一次，但该标签仍然适用。');
INSERT INTO "tags" VALUES ('g452','跳过场景','tech',232,'本游戏提供跳过一场或多场场景的选项，通常是在你阅读过一次后的后续游玩中。 

这是大多数游戏使用的通常快进之前读过的文本的替代方案。因为这允许你完全跳过大量文本和图像，而无需强制快进它们。');
INSERT INTO "tags" VALUES ('g453','生活片段戏剧','cont',423,'该标签用于具有戏剧性的生活片段故事。');
INSERT INTO "tags" VALUES ('g454','生活片段','cont',2127,'[url=http://en.wikipedia.org/wiki/Slice_of_life]生活片段[/url] 故事是一种描绘角色生活中“截取”事件序列的故事类别。

它通常试图描绘普通人的日常生活，有时涉及奇幻或科幻元素。

生活片段故事可能具有戏剧性，或以非常严肃的方式呈现，也可能用于构建喜剧背景。');
INSERT INTO "tags" VALUES ('g455','生活片段现实主义','cont',149,'该标签用于以非常写实的方式呈现的生活片段故事。');
INSERT INTO "tags" VALUES ('g456','战争','cont',535,'故事包括大规模武装冲突。');
INSERT INTO "tags" VALUES ('g457','世界末日','cont',390,'故事涉及我们所知的世界的终结。');
INSERT INTO "tags" VALUES ('g459','可解锁路线','tech',2086,'该标签适用于具有新的可解锁路线的游戏。 

它们可以通过到达游戏中的特定点或完成固定次数来解锁。');
INSERT INTO "tags" VALUES ('g460','替代起始点','tech',218,'这个游戏允许用户在完成一条路线后从替代起点开始。通常是在游戏的转折点，用户选择继续哪条路线。

这个标签不适用于具有新解锁路线的游戏。对于这些游戏，请使用[url=http://vndb.org/g459]可解锁路线[/url]。');
INSERT INTO "tags" VALUES ('g461','拥有绝对领域的女主角','续',1335,'本游戏包含一名或多名具有[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/ZettaiRyouiki]绝对领域[/url]的女主角。

"绝对领域"由过膝袜、短裙以及袜子与裙子之间露出的大腿区域组成。"绝对领域"既可以指裸露的大腿区域，也可以指长袜、短裙和裸露大腿的组合。这可能是一种性癖。请注意，真正的绝对领域要求袜子必须过膝。

例子包括《Fate/stay night》中的[url=/c34]凛[/url]、《Kanon》中的[url=/c2928]名雪[/url]、《Kimi ga Aruji》中的[url=/c3793]美夕[/url]，以及《[url=/v1799]绝对领域！[/url]》中的每个女孩。');
INSERT INTO "tags" VALUES ('g462','戴眼罩的女主角','续',161,'本游戏的一位或多位女主角佩戴有[url=http://en.wikipedia.org/wiki/Eyepatch]眼罩[/url]。她不一定需要那只眼睛失明，唯一的要求是该角色经常佩戴它，以至于人们会将其与眼罩联系在一起。

眼罩是一种戴在一只眼睛前的小片。它可以是围绕头部用松紧带或绳子固定的布片，也可以是粘性绷带。人们通常佩戴它来遮住缺失或受伤的眼睛，但它也有治疗作用，用于儿童弱视的治疗。');
INSERT INTO "tags" VALUES ('g464','有性经验的女主角','续',2746,'大多数视觉小说和成人游戏都是纯爱故事。主角是游戏女主角们的初恋，也是她们生命中的第一个男人。

但在某些情况下，故事会采用更现实的手法，描绘在游戏故事开始前已有性经验、或仍保持活跃性生活的女主角。此标签适用于那种在与主角上床时并非处女的女主角。

此标签仅用于角色分类，并非旨在歧视任何人的生活方式或选择。');
INSERT INTO "tags" VALUES ('g465','成人女主角','cont',3949,'本游戏中的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Adult]成年人[/url]。

''成年人''是一个宽泛而主观的概念，但在视觉小说的设定中，通常指任何已达到法定年龄并完成高中学业的人。在高中不是强制或不存在高中教育的奇幻/科幻设定中，拥有职业或达到预期拥有职业的年龄可被视为''成年''的标志。');
INSERT INTO "tags" VALUES ('g466','女主角的外貌','cont',0,'这些是定义女主角[url=http://en.wikipedia.org/wiki/Human_physical_appearance]身体外貌[/url]的标签。');
INSERT INTO "tags" VALUES ('g467','按性格分类的女主角','cont',0,'该元标签用于收集与女主角性格相关的特质。');
INSERT INTO "tags" VALUES ('g468','锦标赛','cont',119,'本游戏有一个作为故事重要组成部分的[url=http://en.wikipedia.org/wiki/Tournament]锦标赛[/url]。');
INSERT INTO "tags" VALUES ('g469','管家配角','cont',124,'本视觉小说的配角之一是[url=http://en.wikipedia.org/wiki/Butler]管家[/url]。');
INSERT INTO "tags" VALUES ('g470','现代东京','cont',247,'游戏设定在[url=http://en.wikipedia.org/wiki/Tokyo]东京[/url]，或至少故事中相当一部分时间发生在现代东京。
注：''现代''指的是20世纪末至今之间一个未具体指明的时间段。');
INSERT INTO "tags" VALUES ('g471','现代涩谷','cont',20,'游戏设定在[url=http://en.wikipedia.org/wiki/Shibuya,_Tokyo]涩谷[/url]，或至少故事中相当一部分时间发生在现代涩谷。
注：''现代''指的是20世纪末至今之间一个未具体指明的时间段。');
INSERT INTO "tags" VALUES ('g473','猫耳女主角','cont',586,'适用于以拥有猫耳状耳朵或任何能让人联想到猫耳作为其标志性部位或外貌特征的女主角为主角的游戏，例如带有猫耳的发箍，或她的头发被设计成猫耳形状。

请勿与''猫女''标签混淆；几乎每个猫女都有猫耳，但并非每个猫耳角色都是猫女……而且''猫女''是''非人类女主角''的子标签，因此不适用于拥有人类身份且长着猫耳的女孩。');
INSERT INTO "tags" VALUES ('g474','兽耳女主角','cont',1279,'本游戏有一位或多位[url=http://en.wikipedia.org/wiki/Kemonomimi#Animals]兽耳[/url]角色以女主角的身份登场。

兽耳角色通常在外貌上与人无异，只是额外添加了动物特征（如耳朵或尾巴）。');
INSERT INTO "tags" VALUES ('g475','教师主角','cont',888,'本游戏的主角是一名[url=http://en.wikipedia.org/wiki/Teacher]教师[/url]。');
INSERT INTO "tags" VALUES ('g476','法师主角','cont',360,'本游戏的主角是一名法师。');
INSERT INTO "tags" VALUES ('g478','骰子游戏','tech',33,'本游戏包含一个会显示掷出骰子结果的骰子小游戏。

请勿用于像RPG那样使用隐藏骰子判定的游戏。');
INSERT INTO "tags" VALUES ('g479','文本','tech',0,'本游戏将文本显示在哪里？它选择用何种文本显示方式来讲述故事？

所有相关标签都汇集在这里。');
INSERT INTO "tags" VALUES ('g480','天使','cont',572,'本游戏中有[url=http://en.wikipedia.org/wiki/Angel]天使[/url]。');
INSERT INTO "tags" VALUES ('g481','恶魔','cont',2001,'本游戏中有[url=http://en.wikipedia.org/wiki/Demons]恶魔[/url]。');
INSERT INTO "tags" VALUES ('g482','兽耳配角','cont',131,'本游戏有一位或多位[url=http://en.wikipedia.org/wiki/Kemonomimi#Animals]兽耳[/url]角色以配角身份登场。

兽耳角色通常在外貌上与人无异，只是额外添加了动物特征（如耳朵或尾巴）。');
INSERT INTO "tags" VALUES ('g484','潜艇','cont',27,'本视觉小说中许多场景发生在[url=http://en.wikipedia.org/wiki/Submarine]潜艇[/url]内部。');
INSERT INTO "tags" VALUES ('g485','异色瞳女主角','cont',243,'一位或多位女主角的眼睛颜色不同。

详情请参阅相关的[url=http://en.wikipedia.org/wiki/Heterochromia]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g486','僵尸女主角','cont',43,'本视觉小说中至少有一位女主角是[url=http://en.wikipedia.org/wiki/Zombie_%28fictional%29]僵尸[/url]。');
INSERT INTO "tags" VALUES ('g487','活人偶女主角','cont',108,'其中一位女主角是活人偶。例如《蔷薇少女》中的设定。');
INSERT INTO "tags" VALUES ('g488','魔女女主角','cont',352,'本作中的一位女主角是女巫，一种深入研究[url=https://en.wikipedia.org/wiki/Witchcraft]巫术[/url]的魔法师。

不要将此标签用于任何能够施法的女主角；只有当女主角被明确说明是女巫或实践巫术时，才使用此标签。');
INSERT INTO "tags" VALUES ('g490','女同性恋女主角','cont',609,'其中一位女主角对其他女性有性吸引力。这一点通过她在游戏中的行为表现出来；她在这方面的性经历与此标签无关。

在故事中，她可能会改变自己的选择，变成双性恋或异性恋；这里的核心思想是她在游戏中的相当长一段时间内以这种方式行事。');
INSERT INTO "tags" VALUES ('g491','亡灵','cont',2231,'适用于包含所有类型角色和生物的游戏，这些角色和生物即使早已死亡，仍然行走着……

详情请查看维基百科[url=http://en.wikipedia.org/wiki/Undead]亡灵[/url]词条。');
INSERT INTO "tags" VALUES ('g492','神性存在','cont',3134,'所有神圣实体都归于此，天使、恶魔、神灵等。

也包括那些受到它们影响/触碰的人、被选中的人等。');
INSERT INTO "tags" VALUES ('g493','亡灵女主角','cont',762,'本作中的一位女主角是[url=http://en.wikipedia.org/wiki/Undead]亡灵[/url]。');
INSERT INTO "tags" VALUES ('g494','神圣女主角','cont',1543,'本游戏以属于[url=http://en.wikipedia.org/wiki/Divinity]神性[/url]的女主角为特色。');
INSERT INTO "tags" VALUES ('g497','有心理问题的女主角','cont',1324,'适用于患有[url=http://en.wikipedia.org/wiki/Mental_disorder]精神障碍[/url]的女主角。');
INSERT INTO "tags" VALUES ('g498','性瘾女主角','cont',511,'本作中的女主角患有[url=http://en.wikipedia.org/wiki/Nympho]性瘾[/url]。');
INSERT INTO "tags" VALUES ('g499','强奸受害者女主角','cont',194,'本作中的一位女主角是强奸的受害者，故事涉及她事后所承受的戏剧冲突和心理问题。

不要用于那些强奸场景后马上游戏结束、或不将强奸视为戏剧元素之一的游戏。');
INSERT INTO "tags" VALUES ('g500','有心理问题的主角','cont',1186,'适用于患有[url=http://en.wikipedia.org/wiki/Mental_disorder]精神障碍[/url]的主角。');
INSERT INTO "tags" VALUES ('g501','强奸受害者主角','cont',104,'本作的主角是强奸的受害者，故事涉及他事后所承受的戏剧冲突和心理问题。

不要用于那些强奸场景后马上游戏结束、或不将强奸视为戏剧元素之一的游戏。');
INSERT INTO "tags" VALUES ('g502','心理创伤','cont',743,'本作中的一些角色患有[url=http://en.wikipedia.org/wiki/Psychological_trauma]心理创伤[/url]。');
INSERT INTO "tags" VALUES ('g503','性瘾主角','cont',107,'本作的主角患有[url=http://en.wikipedia.org/wiki/Nympho]性瘾[/url]。');
INSERT INTO "tags" VALUES ('g504','多人游戏','tech',24,'此游戏可由多名玩家同时游玩。同一台电脑/主机/掌机和在线多人模式均适用于此标签。');
INSERT INTO "tags" VALUES ('g505','迟钝主角','cont',674,'这种类型的主角完全免疫浪漫和性方面的示好。他/她完全不会察言观色。这位主角可能是个天才，但依然无法理解别人对他/她的感情，直到对方明确表白。即便如此，他/她还需要向对方确认，并思考一段时间才能明白那意味着什么。那些爱上这位主角的人可以竭尽全力让他/她明白，从偶尔的亲吻，到甚至以拙劣借口（比如传输魔力等）发生性关系，但他们根本没有机会被理解，完全没有……');
INSERT INTO "tags" VALUES ('g506','性别转换','cont',3205,'本游戏涉及跨性别者、异装癖角色、主动逾越或“打破”预期性别角色的角色，以及/或者围绕这些角色的情境，并作为故事的重要组成部分。');
INSERT INTO "tags" VALUES ('g507','主角外貌','cont',0,'这个元标签用于汇集与主角外貌相关的主角标签。');
INSERT INTO "tags" VALUES ('g508','童年约定','cont',272,'本作中的两个角色，通常是主角和一位女主角，在童年时彼此许下承诺。

这个承诺是故事的关键元素；尽管在许多情况下，一方或双方可能已经忘记，但当它被记起/揭示时，会改变很多事情。');
INSERT INTO "tags" VALUES ('g509','外星女主角','cont',239,'本作中一位或多位女主角是[url=http://en.wikipedia.org/wiki/Extraterrestrial_life]外星[/url]起源。

地外生命被定义为并非源自地球的生命。也称为外星生命，或简称外星人，这些假设的生命形式范围从类似细菌的简单生物到远比人类先进的智慧生物。');
INSERT INTO "tags" VALUES ('g510','狗耳娘女主角','cont',126,'一位或多位女主角是狗耳娘。');
INSERT INTO "tags" VALUES ('g511','大量强奸内容','ero',1053,'本游戏包含大量强奸内容。不是少数，而是成吨的……注意……');
INSERT INTO "tags" VALUES ('g512','天才支援角色','cont',51,'其中一位支援角色是天生天才，几乎通晓一切。');
INSERT INTO "tags" VALUES ('g513','Netorare','ero',1667,'这款视觉小说包含聚焦于NTR（寝取）的剧情。NTR不仅仅是单纯的不忠行为，更是对嫉妒以及其他通常与此类情景相关的负面情感的恋物化。

一款游戏若要归类为NTR，必须满足以下条件：

1. 主角的伴侣、非常亲密的朋友，或某些情况下，亲近的亲属被人通过诱惑、胁迫、勒索、直接强暴或其他手段夺走。这不一定意味着字面上被夺走，但伴侣所经历的负面感受可能会让情况看起来如此。

2. 失去爱人的一方几乎总会发现真相，并饱受嫉妒与因无力改变任何事而产生的无助感折磨。夺走爱人的人和/或被夺走的爱人可能会私下或公开羞辱输家，以此加深其痛苦。

3. 如果与他人发生性关系的角色与主角之间并不存在深厚的恋爱关系，并且主角在发现此事后并未产生嫉妒及其他负面情感，则该标签[b]不[/b]适用。换言之，伴侣之间的羁绊以及这种羁绊被强行拆散的过程，是NTR恋物癖的核心。例如，单相思的对象或另一条路线中的潜在主角，不计入该恋物癖范畴。

4. 被夺走的行为必须发生在主角与被夺走的伴侣处于恋爱关系期间。女主角过去恋爱关系中的场景不计入NTR。

游戏通常从失去伴侣的一方视角展开，以深入挖掘该恋物癖中嫉妒的一面，不过出于剧情需要，游戏也可能在多个人物视角之间切换，并从被夺走伴侣的一方视角来描绘事件。');
INSERT INTO "tags" VALUES ('g514','Netori','ero',911,'Netori是与[url=/g513]NTR[/url]相对应的标签，但玩家并非扮演爱人被夺走的一方，而是扮演主动夺走他人的一方。

Netori并非恋物化嫉妒及其他负面情感，而是一种凌驾于他人之上、夺走属于他人之物的权力快感。

一款游戏若要归类为Netori，必须满足以下条件：

1. 主角通过诱惑、胁迫、勒索、直接强暴或其他手段，从另一名角色手中夺走其伴侣、非常亲密的朋友，或在极为罕见的情况下，亲近的亲属。

2. 被夺走的角色必须是你不应该夺走的人。例如，如果一名女性没有伴侣，主角与某人的母亲发生性关系并不算Netori。但如果她正是主角自己的母亲，且父亲在游戏中有某种形式的存在，那么这就属于Netori。

3. 对于Netori主题的游戏，发现真相这一要素相对不那么重要，因为游戏的重点在于主角及其征服过程。不过，失去的一方仍然需要存在于游戏之中，并在其伴侣被夺走的剧情中扮演一定角色。如果失去的一方从未出现或极少被提及，则该游戏应标记为[url=/g1380]出轨[/url]，而非Netori。

4. 如果主角的征服对象与另一名角色之间不存在深厚的恋爱关系，则该标签不适用，因为伴侣之间的羁绊以及主角强行拆散这种羁绊的过程，是这一恋物癖的重要方面。');
INSERT INTO "tags" VALUES ('g515','已婚女主角','cont',1697,'这部视觉小说中至少有一位女主角是[url=http://en.wikipedia.org/wiki/Wife]已婚女性[/url]。她的婚姻在故事进行期间可能持续，也可能已经破裂。');
INSERT INTO "tags" VALUES ('g516','涉及毒品的性行为','ero',811,'这部视觉小说包含参与者之间的性爱场景，其中参与者在性爱场景之前或期间自愿或非自愿地服用了毒品。');
INSERT INTO "tags" VALUES ('g517','咖啡馆','cont',700,'带有此标签的游戏故事大多发生在咖啡馆或类似场所内。

只有当游戏在咖啡馆场景中花费了相当篇幅时才使用此标签，并非出现一次咖啡馆就必须加上。');
INSERT INTO "tags" VALUES ('g519','森林','cont',493,'这部视觉小说有相当一部分剧情发生在[url=http://en.wikipedia.org/wiki/Forest]森林[/url]之中。');
INSERT INTO "tags" VALUES ('g520','性骚扰','ero',7190,'用于故事中带有[url=http://en.wikipedia.org/wiki/Sexual_harassment]性骚扰[/url]元素的游戏。');
INSERT INTO "tags" VALUES ('g521','痴汉','ero',510,'痴汉（痴漢、チカン或ちかん）是日语中用于指代[url=http://en.wikipedia.org/wiki/Frotteurism]摩擦癖[/url]或实施此类行为的男性的术语（实施此类行为的女性被称为痴女）。

如果游戏中的此类骚扰行为是故事的重要要素，且不仅限于一次性的单纯尝试，则使用此标签。并非作为随口一提的玩笑或致敬。');
INSERT INTO "tags" VALUES ('g522','书虫型女主角','cont',239,'本游戏中的一名或多名女主角是[url=http://en.wikipedia.org/wiki/Bibliophilia]书虫[/url]。

书虫是指热爱书籍内容或喜欢阅读的人。

这类女主角经常被看到在读书、随身携带书或一直谈论书。她们也以在学校图书馆或书店工作或闲逛而闻名。');
INSERT INTO "tags" VALUES ('g523','学生社团','cont',1186,'[url=http://en.wikipedia.org/wiki/Student_club]学生社团[/url]在这个故事中扮演重要角色。

学校社团是以学生为基础的学校组织，由经学校批准的组织组成，承担着各种各样的任务，具体取决于各个社团的宗旨。');
INSERT INTO "tags" VALUES ('g524','废柴主角','cont',220,'与[url=/g692]主动型主角[/url]相反。

本游戏的主角是一个无用、懦弱、一无是处，不配称为男人的人。他对任何人都没有帮助，大多数时候无法及时做出任何决定。他在游戏中总是被其他角色推来搡去，他在游戏开始时是那样，在游戏最后时刻也仍然如此。

请不要将此标签用于那些主角以这种方式开局但在游戏最初几个小时内改正了行为的游戏。因此，通过快速阅读，这种游戏还是多少可以忍受的。

虽然此描述说的是男人，但这个标签也可以用于一无是处、懦弱无能、毫无用处的女性主角。');
INSERT INTO "tags" VALUES ('g525','反英雄主角','cont',158,'本游戏的主角是一位[url=http://en.wikipedia.org/wiki/Antihero]反英雄[/url]。

他通常被认为是一个主角，其性格至少在某种程度上与典型英雄明显相反，在某些情况下甚至是其反面。通常，反英雄缺乏英雄动机，并使用有争议的方法来实现其目标，这样做是出于目的正当化手段的观点。');
INSERT INTO "tags" VALUES ('g526','卷轴射击','tech',27,'本游戏的动作序列设定在滚动背景上，比如画面总是向右或向上滚动。除了在那个滚动屏幕上努力生存之外，没有其他自由移动。');
INSERT INTO "tags" VALUES ('g527','哥特风女主角','cont',261,'本游戏中的一名或多名女主角大多穿着[url=http://en.wikipedia.org/wiki/Gothic_fashion]哥特风格[/url]服装。');
INSERT INTO "tags" VALUES ('g528','虚构的未来日本小镇','cont',27,'本游戏设定在未来的某个虚构日本小镇。');
INSERT INTO "tags" VALUES ('g529','兔女郎女主角','cont',143,'这部视觉小说中的一名或多名女主角是兔女郎。

注意：此标签指那些兔子特征是永久性的女主角——例如，一个兔子特征是其身体一部分的兔耳娘。对于拥有非永久性兔子特征的人类女主角——例如服装或发型——请使用[URL=https://vndb.org/g474/]兔耳娘女主角[/URL]。');
INSERT INTO "tags" VALUES ('g530','假小子女主角','cont',1112,'本小说的一名或多名女主角是[url=http://en.wikipedia.org/wiki/Tomboy]假小子[/url]。

假小子是指表现出被认为是男孩性别角色典型特征或行为的女孩，包括穿着男性化服装，参与身体性质的运动和活动，这些在许多文化中被认为是男孩的领域。假小子女孩也往往粗鲁、粗暴，并且有或表现出坏习惯。');
INSERT INTO "tags" VALUES ('g531','情色精神控制','ero',579,'本游戏中的角色使用[url=https://en.wikipedia.org/wiki/Brainwashing]精神控制[/url]技巧来与他人发生性关系，以及以某种方式将精神控制与性结合在一起的其他情境。');
INSERT INTO "tags" VALUES ('g532','血亲母子乱伦','ero',526,'这些游戏包含有血缘关系的母子之间的性爱场景。');
INSERT INTO "tags" VALUES ('g533','大胸女主角','cont',7588,'这部视觉小说中的一名或多名女主角拥有大、巨大或巨型乳房。');
INSERT INTO "tags" VALUES ('g534','爱情战胜一切','cont',592,'大多数视觉小说都有某种浪漫元素，但也有一些是关于真爱克服一切困难的作品。关于一对命中注定的恋人克服一切困难……

例子包括：
*关于无论发生什么都对彼此忠贞不渝的情侣的故事（允许说一两次谎，但不允许与他人上床），
*关于情侣为爱牺牲一切的故事，
*关于爱将角色从必然毁灭中拯救出来的故事（例如为了爱而放弃无休止的复仇链），
等等');
INSERT INTO "tags" VALUES ('g536','魔王主角','cont',96,'主角是一个魔王，即恶魔之王（或魔鬼之王等）。

他可能刚刚从长达数个世纪的封印中逃脱，旨在恢复他昔日的力量（并奴役那些上次阻挠他的人），最终决定统治世界……或者他可能是一位喜爱小动物和自然环境的魔王，憎恨人类因为他们污染自然，并且最终与一群人类住在一起，看看他们是否真的那么坏。

请注意，此标签仅适用于真正的魔王，而不适用于以魔王作为头衔或绰号的角色。该角色需要具有神奇的、[url=http://en.wikipedia.org/wiki/Demonic]恶魔般的[/url]属性。');
INSERT INTO "tags" VALUES ('g537','节日','cont',1076,'一个[url=http://en.wikipedia.org/wiki/Festival]节日[/url]在这个游戏的故事中占有重要地位。');
INSERT INTO "tags" VALUES ('g538','学园祭','cont',268,'这个游戏的故事有相当一部分发生在学园祭期间或为学园祭做准备的过程中，展示了学生们的活动和准备工作。

更多详情请参阅相关的[url=http://en.wikipedia.org/wiki/Japanese_Cultural_Festival]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g539','法庭','cont',96,'故事涉及一场在屏幕上进行的审判，角色们深度参与其中。可以期待大量充满夸张的辩论、对证人的交叉询问，以及（如果你真的很幸运）也许能听到一两声“反对！”。');
INSERT INTO "tags" VALUES ('g540','通灵','cont',26,'游戏中的一个或多个角色有能力与死者灵魂交流或召唤他们。这可能采取降神会的形式，或者灵魂附身于灵媒的身体。');
INSERT INTO "tags" VALUES ('g541','警察','cont',640,'[url=http://en.wikipedia.org/wiki/Police]警察[/url]在这款游戏中扮演重要角色。一个或多个角色是警察部队的成员，并且/或者警察工作对游戏情节有重大参与。');
INSERT INTO "tags" VALUES ('g542','乙女游戏','tech',6907,'这是一款以女性为主角的游戏，核心重点在于与一个或多个男性角色发展关系。这些游戏通常面向女性受众，例如《心跳回忆女生版》。

请注意，并非所有面向女性玩家的游戏都符合此标签，例如BL游戏。');
INSERT INTO "tags" VALUES ('g543','黑客','cont',211,'这款游戏涉及角色入侵安全网络、公司，甚至只是其他黑客的计算机。可以期待ICE、破冰程序，最坏的情况是“我们的DNS全部宕机！他们正在突破子网！”。');
INSERT INTO "tags" VALUES ('g544','学生主角','cont',6346,'主角在故事进行期间正在上学。');
INSERT INTO "tags" VALUES ('g545','Roguelike','tech',38,'这款游戏具有[url=http://en.wikipedia.org/wiki/Roguelike]Roguelike[/url]玩法。Roguelike是现代电脑角色扮演游戏的祖先，具有随机生成的地牢（或其他地形）以及回合制游戏方式（回合较短——通常每回合只有一个动作——攻击一次、移动一格等）。');
INSERT INTO "tags" VALUES ('g546','叙述他人想法','tech',247,'在普通游戏中，玩家可以听到主角的想法，但听不到其他角色的。与此不同，带有此标签的游戏也允许你听到其他角色的想法，这只是作为叙事的一部分，而不是因为主角有超能力之类的。

不要将此标签与有时会切换到其他角色视角的游戏混淆。');
INSERT INTO "tags" VALUES ('g547','军官主角','cont',104,'这款游戏的主角是军队中的军官（处于权威地位的士兵）。

在军队中担任临时角色的人不属于此标签。此标签面向职业军官。');
INSERT INTO "tags" VALUES ('g548','诅咒','cont',457,'这个故事中有某种[url=http://en.wikipedia.org/wiki/Curse]诅咒[/url]在其中扮演重要角色。');
INSERT INTO "tags" VALUES ('g549','寡妇女主','cont',408,'这款游戏的一个或多个女主角是[url=http://en.wikipedia.org/wiki/Widow]寡妇[/url]。
寡妇是指配偶已去世的女性。');
INSERT INTO "tags" VALUES ('g550','虚构的现代日本乡村','cont',186,'这个故事发生在当代日本一个虚构的乡村地区。
注意：“现代”指的是20世纪末到今天之间一个未指明的时期。');
INSERT INTO "tags" VALUES ('g552','慢热爱情','cont',161,'由于以下原因的组合，这个故事花费“很长时间”才实现相关恋人之间的爱情：

*他们太不成熟，无法意识到自己的感情，
*他们太害羞，不敢谈论自己的感情，
*他们太害怕，不敢表白自己的感情，

……直到很长时间过去或发生某些剧烈的事情。');
INSERT INTO "tags" VALUES ('g553','多线路谜团','tech',512,'为了理解这款游戏的真实故事，玩家需要游玩多条路线。每条路线都会揭示谜团的一部分。

不要将此与[url=http://vndb.org/g149]强制游玩顺序[/url]混淆，因为视觉小说不一定有可解锁的路线，它更多关乎这些路线中的故事内容，以及它们如何为故事的整体谜团/情节做出贡献。');
INSERT INTO "tags" VALUES ('g554','死神女主角','cont',84,'本游戏中的一名或多名女主角是[url=http://en.wikipedia.org/wiki/Shinigami]死神[/url]。');
INSERT INTO "tags" VALUES ('g555','瓦尔基里女主角','cont',40,'本游戏中的一名或多名女主角是[url=http://en.wikipedia.org/wiki/Valkyrie]瓦尔基里[/url]。');
INSERT INTO "tags" VALUES ('g556','儿童主角','cont',315,'这些游戏的主角比此类游戏中常见（学生）主角更年轻。');
INSERT INTO "tags" VALUES ('g557','体育节','cont',51,'本游戏故事的相当一部分时间发生在学校体育节期间，或发生在筹备体育节的过程中，展现了学生们的活动与准备。

请参阅相关的[url=http://en.wikipedia.org/wiki/Japanese_Cultural_Festival]维基百科[/url]文章以了解更多详情。');
INSERT INTO "tags" VALUES ('g558','继承存档','tech',59,'在某些游戏系列中，系列中一个游戏里的存档可用于解锁后续游戏中的内容，或让玩家在后续游戏开始时处于不同的情境。本游戏支持从先前作品加载此类数据。

请参阅相关的[url=http://en.wikipedia.org/wiki/Save_game]维基百科[/url]文章以了解详情。');
INSERT INTO "tags" VALUES ('g559','主角选择','tech',385,'在本游戏开始时，你必须选择其中一个角色作为主角来游玩。

这与在游戏故事过程中切换主角的游戏不同，因为那样的切换不是可选的。');
INSERT INTO "tags" VALUES ('g560','龙女主角','cont',158,'至少有一位女主角是[url=http://en.wikipedia.org/wiki/Dragon]龙[/url]。这包括作为龙但（通过魔法或其他方式）化为人形的女主角。');
INSERT INTO "tags" VALUES ('g561','龙','cont',401,'这些游戏包含真正的[url=http://en.wikipedia.org/wiki/Dragon]龙[/url]（即怪物/生物类型，而不是作为称号、硬币或任何类似事物）。');
INSERT INTO "tags" VALUES ('g562','构造体','cont',1146,'非在正常情况下出生的存在，即使在奇幻设定中也不例外，均属于此标签。它们可能是有意制造的，也可能是意外形成的。关键是，它们是造出来的，而非生出来的。

由魔法驱动的魔像、实验室制造的生物，都属于此类别。行尸走肉不算。');
INSERT INTO "tags" VALUES ('g564','转学生女主角','cont',334,'本游戏中的一位或多位女主角是转学生。

请参阅相关的[url=http://en.wikipedia.org/wiki/Transfer_student]维基百科[/url]文章以了解详情。');
INSERT INTO "tags" VALUES ('g565','班长女主角','cont',273,'该角色是[url=http://en.wikipedia.org/wiki/Class_President]班长[/url]。

班长通常是学生班级的领导者，主持班级内阁或学生会内的组织；在中小学校，班长通常由班级选举产生，班级是由同一年级全体学生组成的选区。

班长与学生会长不同，他们仅代表特定班级的学生，而非全体学生。');
INSERT INTO "tags" VALUES ('g566','学校体育社团成员女主角','cont',222,'一位女主角是隶属于学校的[url=http://en.wikipedia.org/wiki/Sports_club]体育社团[/url]的成员。

学校体育社团是一个经校方批准、以学生为基础的学校组织，专注于某一项体育运动。');
INSERT INTO "tags" VALUES ('g567','持剑女主角','cont',531,'本游戏中的一位女主角随身携带一把[url=http://en.wikipedia.org/wiki/Sword]剑[/url]。她可能参加了与剑相关的学校社团（剑道、居合道、击剑），也可能有其他原因这样做。

另一个标签，[url=http://vndb.org/g67]女武芸者[/url]，也包含刀剑，但它还指具有强烈荣誉感和正义感的角色。如果该标签的描述更贴切，请改用它。');
INSERT INTO "tags" VALUES ('g568','魔法教师主角','cont',23,'本游戏的主角教授魔法。');
INSERT INTO "tags" VALUES ('g570','决斗','cont',250,'本游戏中的大多数战斗以一对一的形式进行。它们可以是比赛形式，也可以是经典的动画风格——其他人都停止行动，观看战斗并讨论和发表评论。

你可以查看[url=http://en.wikipedia.org/wiki/Duel]决斗[/url]的维基百科条目以获取更多信息。');
INSERT INTO "tags" VALUES ('g571','感情上优柔寡断的主角','cont',71,'本游戏的主角无法在女主角们之间做出选择。他要么不确定自己更爱哪一个，要么害怕伤害其他女主角的感情。

在动画世界里，不做出选择并让所有人无限期等待是‘可以’的，因此这一点被照单全收。即使这被视为性格缺陷，也丝毫不会影响相关女主角对他无尽的爱……因为爱太伟大了……

附注：你也可以将此标签用于那些主角在故事后期才做出决定的游戏。');
INSERT INTO "tags" VALUES ('g572','武术家主角','cont',83,'本游戏的主角是[url=http://en.wikipedia.org/wiki/Martial_arts]武术[/url]的练习者。');
INSERT INTO "tags" VALUES ('g573','武术家女主角','cont',141,'本游戏的女主角之一是一位[url=http://en.wikipedia.org/wiki/Martial_arts]武术[/url]修炼者。');
INSERT INTO "tags" VALUES ('g574','不可避免的女主角强奸','ero',708,'至少有一条路线中存在女主角的强奸场景，且这是不可避免的。如果强奸场景出现在每条路线中或在分支点之前，请使用[url=/g3821]完全不可避免的女主角强奸[/url]。');
INSERT INTO "tags" VALUES ('g575','仅非女主角的不可避免强奸','ero',34,'本游戏中不可避免的强奸场景仅涉及非女主角角色。如果有任何涉及女主角的强奸场景，它们是可以避免的。');
INSERT INTO "tags" VALUES ('g576','魅魔女主角','cont',447,'本游戏中的一位或多位女主角是[url=https://en.wikipedia.org/wiki/Succubus]魅魔[/url]，一种女性形态的恶魔，根据神话和传说传统，她们会压在睡眠者（尤其是男性）身上，与他们进行性行为。');
INSERT INTO "tags" VALUES ('g578','主角的后辈作为女主角','cont',739,'这些游戏至少有一位女主角是主角的后辈。例如可以是工作场所的晚辈，或是低年级的学生。');
INSERT INTO "tags" VALUES ('g579','玩家作为角色','cont',202,'本游戏让你，即玩家，以“你自己”的身份积极参与游戏。

大多数时候，你所扮演的这个角色没有任何台词，也没有固定的名字；以保持“那就是你”的感觉。

这可以认为与[url=http://vndb.org/g390]沉默主角[/url]类似，但在某些方面有所不同，因为该主角只是一个在故事中没有任何台词的角色。');
INSERT INTO "tags" VALUES ('g580','打破第四面墙','cont',822,'本故事包含打破游戏设定中现实错觉的事件或角色。（称为[url=http://en.wikipedia.org/wiki/Fourth_wall]第四面墙[/url]）

例如角色直接对玩家说话，或将现实世界与故事的虚构世界进行对比的场景。');
INSERT INTO "tags" VALUES ('g581','医生主角','cont',247,'本游戏的主角（或其中一位主角）是一名医学从业者，即[url=http://en.wikipedia.org/wiki/Physician]医生[/url]。');
INSERT INTO "tags" VALUES ('g582','仅可避免的性内容','ero',272,'本游戏的故事可以在不看到任何性内容的情况下享受至结局。性内容只出现在支线故事或特定结局中，或者可以通过做出正确的选择来避免。（或者错误的选择，取决于你的观点。）

如果游戏的良好结局包含性内容，则不应使用此标签。

**重要提示：此标签仅用于*游戏内*避免性内容。*不要*给视觉小说标注“无性内容补丁”、“全年龄版补丁”等——这些只应在视觉小说的发布部分中指定！**');
INSERT INTO "tags" VALUES ('g583','游泳社','cont',109,'学校[url=http://en.wikipedia.org/wiki/Swimming_%28sport%29]游泳[/url]社及其相关活动在本故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g585','恶魔主角','cont',382,'本游戏的主角是（或后来成为）一个[url=http://en.wikipedia.org/wiki/Demon]恶魔[/url]。');
INSERT INTO "tags" VALUES ('g586','天使主角','cont',110,'本游戏的主角是（或后来成为）一位[url=http://en.wikipedia.org/wiki/Angel]天使[/url]。');
INSERT INTO "tags" VALUES ('g587','小胸部女主角（非萝莉）','cont',1499,'这部视觉小说的一位或多位女主角拥有平坦或较小的胸部。

此标签与[url=/g154]萝莉女主角[/url]标签是分开的，请不要将两者混为一谈。');
INSERT INTO "tags" VALUES ('g588','炼金术','cont',107,'本游戏包含[url=http://en.wikipedia.org/wiki/Alchemy]炼金术[/url]，无论是作为操纵物质的科学，还是作为魔法术语。');
INSERT INTO "tags" VALUES ('g589','领袖女主角','cont',1712,'这种类型的主角是一位[url=http://en.wikipedia.org/wiki/Leader]领袖[/url]。这位女主角有下属/臣民/士兵可供指挥。游戏故事可能包含也可能不包含实际指挥他们的情节。');
INSERT INTO "tags" VALUES ('g590','新闻社','cont',39,'[url=http://en.wikipedia.org/wiki/Newspaper]新闻[/url]社及其相关活动在本故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g591','私家侦探主角','cont',491,'主角以[url=http://en.wikipedia.org/wiki/Private_detective]私家侦探[/url]为生。');
INSERT INTO "tags" VALUES ('g592','龙主角','cont',40,'这部视觉小说的主角是一条[url=http://en.wikipedia.org/wiki/Dragon]龙[/url]。');
INSERT INTO "tags" VALUES ('g593','黑辣妹女主角','cont',17,'本游戏包含一位或多位外貌类似于[url=http://en.wikipedia.org/wiki/Ganguro]黑辣妹[/url]时尚的女主角。');
INSERT INTO "tags" VALUES ('g594','深色皮肤女主角','cont',1407,'本游戏包含一位拥有较深[url=http://en.wikipedia.org/wiki/Skin_tone]肤色[/url]的女主角。

也可用于极度晒黑（tan）的角色。');
INSERT INTO "tags" VALUES ('g595','职业女性女主角','cont',115,'这种类型的女主角通常穿着正式服装，行为严肃，精通商业管理。她通常是就任何金钱和法律问题咨询的最佳人选。

她在游戏故事中的当前职位（工作状态）并不重要，因为这个标签是关于她的态度和外表的。');
INSERT INTO "tags" VALUES ('g596','泣系游戏','tech',392,'这种故事类型旨在对玩家产生情感冲击并使其难忘，哭泣很常见但大多并非必需。

这在[url=http://en.wikipedia.org/wiki/Key_%28company%29]关于KEY的维基百科文章[/url]中解释如下：
Tactics的开发者们为游戏创造了一个简单的公式：喜剧的前半部分，温馨浪漫的中段，随后是悲剧性的分离，最后是感人的重逢，这构成了所谓的“哭泣游戏”。此类游戏的主要目的是让玩家对角色产生共鸣，并通过情感场景让他们哭泣，从而在游戏结束后给玩家留下更大的影响。');
INSERT INTO "tags" VALUES ('g597','未来东京','cont',47,'游戏设定在未来的[url=http://en.wikipedia.org/wiki/Tokyo]东京[/url]，或者至少有相当一部分故事发生在未来东京。');
INSERT INTO "tags" VALUES ('g598','章节式剧情','tech',1427,'这种故事类型以分隔事件并以章节式结构组织它们的方式讲述。每一章都有其自身的流程、铺垫和高潮。

有时采用这种结构的游戏会更进一步，为每一章添加片头、片尾和下一章预告，给人一种完整的电视剧集感。不过这只是额外加分项，并非此标签的必要条件。');
INSERT INTO "tags" VALUES ('g599','美食讨论','cont',570,'这个游戏中有很多场景都是关于品尝和讨论美食的。这些讨论越详细越好。

通常在这类游戏中，每个进食机会都会是一个详细场景，角色们（每次通常不同）一边吃，一边讨论当前菜肴的起源、做法以及类似话题。

这类游戏的进阶版本还包括为准备晚餐而购物，并设法加入关于食材讨论、购物技巧等更多内容。');
INSERT INTO "tags" VALUES ('g600','含触手的合意性行为','ero',412,'这部视觉小说特色是包含涉及[url=http://en.wikipedia.org/wiki/Tentacle]触手[/url]的合意性行为。');
INSERT INTO "tags" VALUES ('g601','独特路线','tech',501,'这个游戏中的各条路线彼此完全不同。

例如，一条路线中的盟友和反派可能在另一条路线中互换位置，你可能发现自己这次要对抗女主角，与你在另一条路线上讨厌的反派并肩作战。

或者当你在一条路线中试图拯救世界时，你可能会发现自己在另一条路线中试图毁灭它。');
INSERT INTO "tags" VALUES ('g602','傲娇女主角','cont',2239,'这个游戏包含一位或多位表现出[url=http://en.wikipedia.org/wiki/Tsundere]傲娇[/url]行为的女主角。

傲娇是一种日本角色发展过程，描述一个人起初对另一个人冷漠甚至敌视，随着时间的推移逐渐展现出温暖的一面。');
INSERT INTO "tags" VALUES ('g603','孩子气暴力女主角','cont',236,'这种类型的故事中，女主角在整个故事中表现出孩子气的暴力行为。每当她感到沮丧时，就会殴打主角和其他人，不管他们是否有过错。

这些攻击可能极其暴力，但由于被视为喜剧的一部分，它们不会造成任何永久性伤害。

此标签适用于在日常生活中表现出暴力行为爆发女主角。请勿将此标签用于战斗相关情况。另外，如果女主角对主角或其他角色的暴力是出于严肃的伤害意图，而非为了喜剧而夸张，则也不要使用此标签。');
INSERT INTO "tags" VALUES ('g604','网球社','cont',46,'学校的[url=http://en.wikipedia.org/wiki/Tennis]网球[/url]社及相关活动在这个故事中扮演着重要角色。');
INSERT INTO "tags" VALUES ('g605','半人女主角','cont',37,'这个游戏包含一位或多位由人类与异种族结合所生的女主角。

例子包括[url=http://en.wikipedia.org/wiki/Half-elves]半精灵[/url]、半魔族、[url=http://en.wikipedia.org/wiki/Demigod]半神[/url]等...

魔法或科学创造的组合计为此标签，但改造人等不在此列。');
INSERT INTO "tags" VALUES ('g606','分支剧情','tech',2770,'这是[url=http://vndb.org/g145]线性剧情[/url]的对立面。这个故事在某个节点会分成多个子故事。');
INSERT INTO "tags" VALUES ('g607','傲慢女主角','cont',362,'这种女主角认为自己各方面都优越于其他人，并乐于抓住一切机会指出这一点。

大多数时候，这个角色最终会显得无能却极度傲慢，伴随矫揉造作的笑声和滑稽表演，但在少数情况下，她可以有充分的理由傲慢。 

通常这类角色身边会跟着几个跟班。');
INSERT INTO "tags" VALUES ('g608','蒸汽朋克','cont',76,'这个游戏包含了[url=http://en.wikipedia.org/wiki/Steampunk]蒸汽朋克[/url]类型的元素。');
INSERT INTO "tags" VALUES ('g609','飞机','cont',54,'[url=http://en.wikipedia.org/wiki/Airplane]飞机[/url]在游戏故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g610','飞行员女主角','cont',101,'这位女主角是飞机的飞行员或机组人员，即[url=http://en.wikipedia.org/wiki/Aviator]飞行员[/url]。');
INSERT INTO "tags" VALUES ('g611','丘比特女主角','cont',14,'女主角是一位[url=http://en.wikipedia.org/wiki/Cupid]丘比特[/url]，爱神。她可能拥有弓箭，这使她能够在人们之间播撒爱情。');
INSERT INTO "tags" VALUES ('g612','可解锁的后宫结局','tech',444,'游戏有后宫结局，但你只能完成其他一些路线后才能游玩。');
INSERT INTO "tags" VALUES ('g613','主角的性格','cont',0,'这个元标签用于收集与主角性格相关的特质。');
INSERT INTO "tags" VALUES ('g614','愚蠢的主角','cont',260,'用于那些不太聪明的主角。');
INSERT INTO "tags" VALUES ('g615','变态主角','cont',1066,'带有此标签的视觉小说中的主角是个变态。

[URL=https://en.wikipedia.org/wiki/Perversion#Sexual_usages]性变态[/URL]是一种偏离正统或正常理解的人类行为。虽然“性变态”一词可以指多种形式的偏离，但最常用于描述被认为特别异常、令人反感或强迫性的性行为。

请注意，此标签特指性变态。');
INSERT INTO "tags" VALUES ('g616','持剑主角','cont',416,'主角随身携带一把[url=http://en.wikipedia.org/wiki/Sword]剑[/url]。这可能与学校社团（剑道、居合道、击剑）有关，也可能有其他原因。');
INSERT INTO "tags" VALUES ('g617','热血主角','cont',73,'主角是热血的。

对于那些不熟悉的人来说，热血角色对正义/爱情/保护朋友感到极度热情（还有其他类型，比如热血艺术家，但这些通常是为了搞笑），以至于他一定会克服非人力所能及的挑战。
热血角色通常会在其他人都会死去之后继续战斗，凭借纯粹的胆量和激情克服精神控制、毒药、疾病、重力、辐射乃至命运本身。

突出的例子包括多蒙·卡修（G高达）、真神勇次（[URL=http://vndb.org/v2000]Only You[/URL]）、卡米那和西蒙（天元突破）以及姬萩爱须香（[URL=http://vndb.org/v1491]Trample on Schatten!![/URL]）。');
INSERT INTO "tags" VALUES ('g618','热血女主角','cont',101,'女主角中的一位或多位是热血的。

对于那些不熟悉的人来说，热血角色对正义/爱情/保护朋友感到极度热情（还有其他类型，比如热血艺术家，但这些通常是为了搞笑），以至于她一定会克服非人力所能及的挑战。
热血角色通常会在其他人都会死去之后继续战斗，凭借纯粹的胆量和激情克服精神控制、毒药、疾病、重力、辐射乃至命运本身。

近年来最突出的热血女主角例子大概是《[URL=http://vndb.org/v1491]Trample on Schatten[/URL]》中的Kizaia Hinokami。');
INSERT INTO "tags" VALUES ('g619','飞行员主角','cont',143,'这位主角是飞机的飞行员或机组人员，即[url=http://en.wikipedia.org/wiki/Aviator]飞行员[/url]。');
INSERT INTO "tags" VALUES ('g620','热血配角','cont',18,'配角中的一位或多位是热血的。

对于那些不熟悉的人来说，热血角色对正义/爱情/保护朋友感到极度热情（还有其他类型，比如热血艺术家，但这些通常是为了搞笑），以至于他一定会克服非人力所能及的挑战。
热血角色通常会在其他人都会死去之后继续战斗，凭借纯粹的胆量和激情克服精神控制、毒药、疾病、重力、辐射乃至命运本身。');
INSERT INTO "tags" VALUES ('g621','喜剧式强奸','ero',111,'本游戏中大部分或全部的强奸场景都是以滑稽的方式呈现的。导致这些场景的情境以及之后的事件都被设计成不会像真实强奸那样带有戏剧性和创伤性。');
INSERT INTO "tags" VALUES ('g622','贸易模拟','tech',54,'本游戏包含[url=http://en.wikipedia.org/wiki/Business_simulation_game]商业模拟[/url]的游戏元素。');
INSERT INTO "tags" VALUES ('g623','女同性恋强奸','ero',348,'此标签用于描述一个或多个女性角色对另一名女性进行性侵犯的故事。');
INSERT INTO "tags" VALUES ('g624','短暂男性主角','tech',104,'本游戏让你在短时间内扮演男性主角。

请记住，这段短时间应当足够长，值得被提及。

例如；如果一个一百小时的游戏只让你扮演五分钟男性主角，就不要使用此标签。

同样，也不要将其用于像G-sen和Crescendo那样只能短暂从其他角色视角观看的游戏（请改用[url=/g633]其他视角[/url]）。');
INSERT INTO "tags" VALUES ('g625','扶她支援角色','cont',176,'其中一个支援角色同时拥有男性和女性生殖器。通常（但不一定）与女性特征配对。

请查看相关的[url=http://en.wikipedia.org/wiki/Futanari]维基百科[/url]条目以获取详细信息。');
INSERT INTO "tags" VALUES ('g626','飞机战斗','cont',14,'本游戏以使用[url=http://en.wikipedia.org/wiki/Airplanes]飞机[/url]在空中进行的战斗为特色。');
INSERT INTO "tags" VALUES ('g627','抑郁（已废弃）','cont',297,'整个游戏都能感受到[url=http://en.wikipedia.org/wiki/Depression_%28mood%29]抑郁[/url]的情绪。（深深的悲伤、无助和绝望的感觉。）

或者本游戏有一个重要角色患有严重的抑郁症，影响了游戏中的其他角色以及氛围。

[b]该标签混合了两个不同的概念，已被废弃，取而代之的是更明确的标签[url=/g3998]临床抑郁症[/url]。请将适用的VN条目转移到新明确的标签下。[/b]');
INSERT INTO "tags" VALUES ('g628','超级英雄','cont',893,'本游戏包含一些[url=http://en.wikipedia.org/wiki/Superhero]超级英雄[/url]。

游戏中一些看似普通的人物会变身为穿着服装/盔甲的形象，为‘公众利益’而战。');
INSERT INTO "tags" VALUES ('g629','超级英雄（女）主角','cont',86,'本游戏的主角是一位[url=http://en.wikipedia.org/wiki/Superhero]超级英雄[/url]。');
INSERT INTO "tags" VALUES ('g630','超级女英雄','cont',107,'本游戏的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Superhero]超级英雄[/url]。');
INSERT INTO "tags" VALUES ('g631','危险傲娇女主角','cont',39,'这种类型的傲娇既危险又可怕。

想象一位女主角，最初是一个试图杀死主角的反派，但爱上他后转而加入了他的阵营。她仍然偶尔会开玩笑说要杀他……');
INSERT INTO "tags" VALUES ('g632','视角切换','tech',4591,'虽然大多数游戏坚持单一主角的视角，但有些游戏使用多个主角，有些则时不时切换到其他角色的[url=http://en.wikipedia.org/wiki/Point_of_view_%28literature%29]视角[/url]。');
INSERT INTO "tags" VALUES ('g633','其他视角','tech',3036,'本游戏有时会跳到主角以外的角色的视角。但该[url=http://en.wikipedia.org/wiki/Point_of_view_%28literature%29]视角[/url]不会持续太久，不足以将该角色视为另一位主角，也不会让你做出选择等。

这样你可以从他们的眼中看到某些事件，看到他们在主角不在身边时遭遇的事情，听到他们的一些想法等等……');
INSERT INTO "tags" VALUES ('g634','园艺社','cont',14,'学校园艺社及其相关活动在本故事中扮演重要角色。本游戏中会大量谈论花卉。');
INSERT INTO "tags" VALUES ('g635','护士女主角','cont',777,'本游戏的一位女主角是一名[url=http://en.wikipedia.org/wiki/Nurse]护士[/url]。

护理是医疗保健领域的一种职业，专注于护理个人、家庭和社区，使他们能够达到、维持或恢复最佳健康和生活质量。');
INSERT INTO "tags" VALUES ('g636','厨师女主角','cont',137,'本游戏的一位女主角是一名[url=http://en.wikipedia.org/wiki/Cook_%28profession%29]厨师[/url]。');
INSERT INTO "tags" VALUES ('g637','记者女主角','cont',72,'本游戏的一位女主角是一名[url=http://en.wikipedia.org/wiki/Journalist]记者[/url]。');
INSERT INTO "tags" VALUES ('g638','单一性别学校','cont',536,'本游戏设定在一所只招收单一性别学生的学校。详情请参阅[url=http://en.wikipedia.org/wiki/Single-sex_school]单一性别教育[/url]。');
INSERT INTO "tags" VALUES ('g639','男子学校','cont',95,'本游戏设定在一所只招收男生的学校。');
INSERT INTO "tags" VALUES ('g640','管家主角','cont',68,'本游戏的主角是一名[url=http://en.wikipedia.org/wiki/Butler]管家[/url]。');
INSERT INTO "tags" VALUES ('g641','保镖女主角','cont',77,'本游戏的一位女主角是一名[url=http://en.wikipedia.org/wiki/Bodyguard]保镖[/url]。');
INSERT INTO "tags" VALUES ('g642','警察女主角','cont',204,'本游戏的一位女主角是一名[url=http://en.wikipedia.org/wiki/Police_officer]警察[/url]。');
INSERT INTO "tags" VALUES ('g643','警察主角','cont',228,'本游戏的主角是一名[url=http://en.wikipedia.org/wiki/Police_officer]警察[/url]。');
INSERT INTO "tags" VALUES ('g644','小偷女主角','cont',102,'本游戏的一位女主角是一名职业[url=http://en.wikipedia.org/wiki/Thief]小偷[/url]。');
INSERT INTO "tags" VALUES ('g645','律师主角','cont',83,'本游戏的主角是一名[url=http://en.wikipedia.org/wiki/Lawyer]律师[/url]。');
INSERT INTO "tags" VALUES ('g646','妓女女主角','cont',365,'本游戏的一位女主角从事以金钱为交换的性活动。详情请参阅[url=http://en.wikipedia.org/wiki/Prostitution]卖淫[/url]。');
INSERT INTO "tags" VALUES ('g647','第二次世界大战','cont',53,'本游戏设定在[url=http://en.wikipedia.org/wiki/World_War_II]第二次世界大战[/url]时期，或有大量场景以一系列冗长闪回或类似方式进行。');
INSERT INTO "tags" VALUES ('g648','阴阳师主角','cont',31,'本游戏的主角是一位[url=http://en.wikipedia.org/wiki/Onmyouji#Onmy.C5.8Dji]阴阳师[/url]。

摘自维基百科描述：
"阴阳师是魔法与占卜的专家。他们的宫廷职责从记录日历等任务，到占卜和保护首都免受恶灵侵害等神秘职责不等。他们能预言大地上的吉凶影响，并在迁都时发挥重要作用。据说阴阳师还能召唤和控制式神。"');
INSERT INTO "tags" VALUES ('g649','主角的母亲作为女主角','cont',743,'本游戏的女主角之一是主角的[url=http://en.wikipedia.org/wiki/Mother]母亲[/url]。');
INSERT INTO "tags" VALUES ('g650','主角的血缘母亲作为女主角','cont',503,'本游戏的女主角之一是主角的[url=http://en.wikipedia.org/wiki/Mother]生母[/url]。');
INSERT INTO "tags" VALUES ('g651','主角的非血缘母亲作为女主角','cont',261,'这部视觉小说中至少有一位女主角是主角的母亲，但她们之间没有血缘关系。

这位女主角可以是主角的继母、养母或寄养母亲。');
INSERT INTO "tags" VALUES ('g652','非血缘母子乱伦','ero',247,'这些游戏包含非血缘关系的母子之间的性爱场景。');
INSERT INTO "tags" VALUES ('g653','牧师支援角色','cont',57,'本游戏的支援角色之一是[url=http://en.wikipedia.org/wiki/Priest]牧师[/url]。

这些角色通常为故事的主角提供帮助和庇护，但有时他们的奇幻版本也会出现，施展神圣法术、与恶魔战斗等。');
INSERT INTO "tags" VALUES ('g654','女医生女主角','cont',299,'本游戏的一位女主角是医学从业者，即[url=http://en.wikipedia.org/wiki/Physician]内科医生[/url]。');
INSERT INTO "tags" VALUES ('g655','治疗者主角','cont',351,'本游戏的主角是一位[url=http://en.wikipedia.org/wiki/Healer]治疗者[/url]——无论他是使用魔法的牧师、擅长使用草药的人，还是真正的医生。

通常具有温和的性格（甚至到慈父般的程度），是角色扮演游戏的常见设定。');
INSERT INTO "tags" VALUES ('g656','厨师主角','cont',163,'本游戏的主角是一位[url=http://en.wikipedia.org/wiki/Cook_%28profession%29]厨师[/url]。');
INSERT INTO "tags" VALUES ('g657','灵媒女主角','cont',30,'本游戏的女主角之一是一位[url=http://en.wikipedia.org/wiki/Mediumship]灵媒[/url]。');
INSERT INTO "tags" VALUES ('g658','艺术家女主角','cont',1367,'本游戏的女主角之一是一位[url=http://en.wikipedia.org/wiki/Artist]艺术家[/url]。');
INSERT INTO "tags" VALUES ('g659','音乐家女主角','cont',952,'本游戏的女主角之一是一位[url=http://en.wikipedia.org/wiki/Musician]音乐家[/url]。');
INSERT INTO "tags" VALUES ('g660','画家女主角','cont',84,'其中一位女主角是以[url=http://en.wikipedia.org/wiki/Painting]绘画[/url]为媒介的创意艺术家。');
INSERT INTO "tags" VALUES ('g661','弓箭社团','cont',36,'学校[url=http://en.wikipedia.org/wiki/Archery]弓箭[/url]社团及其相关活动在本故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g662','勒索','cont',1066,'本故事包含[url=http://en.wikipedia.org/wiki/Blackmail]勒索[/url]情节。

例如；某人（最常见的是女主角）可能被胁迫为他人做事情。');
INSERT INTO "tags" VALUES ('g663','勒索强奸','ero',581,'本游戏包含不情愿的一方被勒索发生性关系的场景。

例如包括；游戏中女主角们被胁迫为反派提供性服务。');
INSERT INTO "tags" VALUES ('g664','大逃杀','cont',126,'至少部分角色卷入了一场扭曲的游戏，游戏要求杀死其他参与者以确保自己的生存。
通常他们是被各种手段强迫参与的（也许他们被绑架，或者他们唯一的选择就是死刑和参加游戏），但也有例外存在。

这不应与竞技场上的决斗混淆，因为它几乎总是涉及生死搏斗，向某人挑战决斗很可能会让你丧命。');
INSERT INTO "tags" VALUES ('g665','植物女主角','cont',37,'本游戏的一位或多位女主角是有知觉的植物——她可能是实际移动的植物，或者只是它的化身。');
INSERT INTO "tags" VALUES ('g666','鬼女主角','cont',46,'本游戏的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Oni_%28folklore%29]鬼[/url]——一种日本恶魔。

不要与恶魔女主角标签混淆，后者指的是西方恶魔。');
INSERT INTO "tags" VALUES ('g668','正太主角','cont',551,'本游戏的主角是正太。他要么是青春期或青春期前的男孩，要么在外表上像这样的男孩

他的年龄在归类为正太时毫不重要。这仅仅关乎外表。

详情请参阅相关的[url=http://en.wikipedia.org/wiki/Shotacon]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g669','萝莉主角','cont',246,'本游戏的主角是萝莉。她要么是未成年少女，要么在外表上像这样的女孩。

她的年龄在归类为萝莉时毫不重要。这仅仅关乎外表。

详情请参阅相关的[url=http://en.wikipedia.org/wiki/Lolicon]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g670','有性经验的主角','cont',951,'大部分视觉小说和成人游戏都是纯爱故事，讲述本游戏的主角如何找到初恋并拥有初次性体验。

但在某些情况下，故事采用更现实的手法，描绘在游戏故事开始前已有性经验的主角，或是持续拥有活跃性生活的主角。此标签用于此类在游戏开始时并非处男/处女的主角。

此标签仅用于角色分类，并非要歧视任何人的生活方式或选择。');
INSERT INTO "tags" VALUES ('g671','鬼屋','cont',222,'鬼屋/豪宅/其他建筑是本游戏的主要场景或重要场景之一。');
INSERT INTO "tags" VALUES ('g672','坏结局','tech',5915,'游戏至少有1个坏结局。坏结局的性质和数量可以有所不同。');
INSERT INTO "tags" VALUES ('g673','密码系统','tech',25,'本游戏不使用传统的保存方法来记录你的进度，而是提供密码让你保存。

详情请查看相关的[url=http://en.wikipedia.org/wiki/Password_%28video_games%29]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g674','风格','tech',0,'这个元标签旨在容纳所有关于游戏引擎如何运作、游戏如何呈现内容以及如何游玩方面的标签。

详情请查看相关的[url=http://en.wikipedia.org/wiki/Style_%28fiction%29]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g675','设计','tech',0,'这个元标签旨在容纳关于游戏系统如何运作的标签。诸如如何保存进度、允许多少名玩家以及类似内容。');
INSERT INTO "tags" VALUES ('g676','闪回','cont',1359,'本游戏有一些[url=http://en.wikipedia.org/wiki/Flashback_%28narrative%29]闪回[/url]场景。

闪回是一种插入场景，使叙事从故事目前到达的时间点回到过去。 

闪回常用于叙述发生在故事主要事件序列之前的事情，或补充关键背景故事。角色起源闪回会展示角色发展早期的关键事件。');
INSERT INTO "tags" VALUES ('g677','马尾辫女主角','cont',1543,'本游戏有一位留着[url=http://en.wikipedia.org/wiki/Ponytail]马尾辫[/url]的女主角。');
INSERT INTO "tags" VALUES ('g678','假日季节','cont',579,'[url=http://en.wikipedia.org/wiki/Christmas]圣诞节[/url]和/或[url=http://en.wikipedia.org/wiki/New_Year%27s_Eve]新年庆祝[/url]（以及所有相关的准备工作）是剧情的重要组成部分。');
INSERT INTO "tags" VALUES ('g679','通过性行为转移能量','ero',147,'在本游戏中，能量可以通过性行为转移甚至创造。包括魔力、生命力等。');
INSERT INTO "tags" VALUES ('g681','活力女主角','cont',635,'这类女主角总是充满活力，四处奔跑，不知为何一直参与体育活动或训练。

这是一种性格特质，因此一位活力女主角不一定是[url=http://vndb.org/g566]体育社女主角[/url]或[url=http://vndb.org/g1491]运动员女主角[/url]，反之亦然。');
INSERT INTO "tags" VALUES ('g682','赛博朋克','cont',248,'赛博朋克是以“高科技与低生活”为焦点而著称的科幻小说类型。这个名字是控制论和朋克的混成词，最初由布鲁斯·贝思克创造，作为他1983年发表的短篇小说《赛博朋克》的标题。它以先进科学为特色，如信息技术和控制论，并伴随着一定程度的社会秩序崩溃或剧烈变革。

赛博朋克的故事情节通常围绕黑客、人工智能和巨型企业之间的冲突展开，并且往往设定在近未来的地球，而不是如艾萨克·阿西莫夫的《基地》或弗兰克·赫伯特的《沙丘》等小说中的遥远未来设定或银河景观。背景通常是后工业化的反乌托邦，但往往以非凡的文化激荡和以创造者从未预料到的方式使用技术为特征（“街道会为事物找到自己的用途”）。

[来自[url=http://en.wikipedia.org/wiki/Cyberpunk]维基百科[/url]]');
INSERT INTO "tags" VALUES ('g683','信息倾泻','tech',258,'这款游戏向读者一次性给出冗长且专业的技术说明。

详情请参考相关的 [url=http://tvtropes.org/pmwiki/pmwiki.php/Main/Infodump]TVTropes[/url] 条目。');
INSERT INTO "tags" VALUES ('g684','完全可避免的寝取','成人',191,'你可以在不经历任何寝取事件的情况下，看到游戏的所有"正确结局"。只有那些过早的坏结局才包含此类事件，而你不必为了解锁其他结局而阅读它们。

那些你可以选择不去目睹NTR事件、但它们在幕后仍然发生的场景，不应被视为可避免的。');
INSERT INTO "tags" VALUES ('g685','魔法学校','内容',284,'游戏的很大一部分发生在一所[url=http://en.wikipedia.org/wiki/Magic_School]魔法学院[/url]或类似的魔法教育机构中。');
INSERT INTO "tags" VALUES ('g686','棒球社','内容',35,'学校的[url=http://en.wikipedia.org/wiki/Baseball]棒球[/url]社及其相关活动在故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g687','多男多女群交','成人',1178,'这部视觉小说包含群交场景，其中多名男性和女性伴侣相互发生性关系。

出于数据库的目的，该标签使用二元性别概念，"Male"指的是出生时被指定为男性且自我认同为男性的顺性别男性。"Female"指的是出生时被指定为女性且自我认同为女性的顺性别女性。');
INSERT INTO "tags" VALUES ('g689','排尿癖','成人',2718,'此游戏包含一个或多个涉及排尿的性场景。');
INSERT INTO "tags" VALUES ('g690','政治家女主角','内容',28,'这个故事中的女主角是一位[url=http://en.wikipedia.org/wiki/Politician]政治家[/url]。由于这是一个虚构故事，她甚至可能是传说中那种不腐败的人物之一……');
INSERT INTO "tags" VALUES ('g691','类型转换','内容',222,'这款游戏在故事后期突然转变为完全不同的类型。例如，它可能以校园喜剧开头，之后变成太空歌剧、机甲或末世科幻等，你懂的。

这类游戏通常在宣传上具有误导性。

更多信息参见[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/GenreShift]类型转换[/url]。');
INSERT INTO "tags" VALUES ('g692','积极主动的主人公','内容',752,'与[url=http://vndb.org/g524]懦弱主人公[/url]相反。

你可以依靠这种类型的主人公去完成需要做的事情。他们不怕做决定。他们主动出击并解决问题，通常靠一己之力。一旦心中有目标，他们会谨慎而巧妙地去实现。

他们通常拥有天赋/能力或人脉，并且知道如何充分利用。

更多详情参见[url=http://en.wikipedia.org/wiki/Proactivity_%28Proactive_behavior%29]主动性[/url]或[url=http://en.wikipedia.org/wiki/Conscientiousness]尽责性[/url]。

仅当主角在游戏大部分时间内都表现出这种行为时才应使用此标签。');
INSERT INTO "tags" VALUES ('g693','致郁游戏','技术',597,'Utsuge 代表 utsu game，意思是"致郁游戏"。据说这类游戏的目的是让玩家感到压抑。

大多数时候，这些游戏没有幸福结局，没有帮助，没有希望……

不要与类似的游戏类型[url=http://vndb.org/g596]泣游戏[/url]混淆。

例如，在一个虚构的致郁游戏中，女主角从一开始就身患重病，最终会死去。但在一个虚构的泣游戏中，游戏会是一个快乐的校园恋爱故事，女主角在游戏结尾突然患病，却只在最后时刻康复。（不过也有主角死去的泣游戏。）');
INSERT INTO "tags" VALUES ('g694','身体互换','内容',140,'身体互换是一种在各类虚构作品中常见的故事手法，尤其是在电视节目和电影中，即两个人（或生物）交换心智，最终进入对方的身体。或者，他们的心智可能留在原地，而身体发生改变。在动画中，两人通常还保留自己的声音，以便区分身份。

[来自[url=http://en.wikipedia.org/wiki/Body_swap]维基百科[/url]]');
INSERT INTO "tags" VALUES ('g695','音乐家主人公','内容',261,'本游戏的主人公是一位[url=http://en.wikipedia.org/wiki/Musician]音乐家[/url]。');
INSERT INTO "tags" VALUES ('g696','艺术家主人公','内容',714,'本游戏的主人公是一位[url=http://en.wikipedia.org/wiki/Artist]艺术家[/url]。');
INSERT INTO "tags" VALUES ('g698','富有主人公','内容',198,'本游戏的主人公拥有巨额财富。');
INSERT INTO "tags" VALUES ('g699','幽灵主人公','内容',130,'本游戏的主人公是一个[url=http://en.wikipedia.org/wiki/Ghost]幽灵[/url]。');
INSERT INTO "tags" VALUES ('g700','不死者主人公','内容',378,'本游戏的主人公是一个[url=http://en.wikipedia.org/wiki/Undead]不死者[/url]。');
INSERT INTO "tags" VALUES ('g701','妓女主人公','内容',82,'本作主角以金钱为代价参与性行为。详情请查看[url=http://en.wikipedia.org/wiki/Prostitution]卖淫[/url]。');
INSERT INTO "tags" VALUES ('g702','奴隶主角','cont',65,'本作主角是[url=http://en.wikipedia.org/wiki/Slave]奴隶[/url]，或在故事后期成为奴隶。

奴隶制是一种将人视为可买卖财产并强迫其劳动的制度。奴隶可能自被俘、被买或出生之时起就被违背其意愿地控制，并被剥夺离开、拒绝工作或要求补偿的权利。');
INSERT INTO "tags" VALUES ('g704','不可避免的主角强奸','ero',334,'至少有一条路线中主角会遭遇强奸场景，且该场景不可避免。如果强奸场景出现在每条路线中或分支点之前，请使用[url=/g3820]完全不可避免的主角强奸[/url]。');
INSERT INTO "tags" VALUES ('g705','神父/女祭司主角','cont',82,'本作主角是[url=http://en.wikipedia.org/wiki/Priest]神父[/url]或女祭司。');
INSERT INTO "tags" VALUES ('g709','无选项视觉小说','tech',4494,'无选项视觉小说是一种完全不向"玩家"提供任何选择的视觉小说；他们只是阅读单一无分支的故事。

该术语源自Visual Art''s的品牌KineticNovel（该品牌下所有游戏都是此类作品），但现在也用于描述其他公司出品的结构类似的游戏。

不要将本标签用于包含游戏性元素的视觉小说，即使该视觉小说在其他方面完全线性。请改用[url=/g145]线性剧情[/url]。');
INSERT INTO "tags" VALUES ('g710','友谊','cont',1598,'[url=http://en.wikipedia.org/wiki/Friendship]友谊[/url]是本作的重要主题。故事可能讲述一群一直在一起的朋友，以及他们成长过程中关系的变化；也可能讲述两人之间的友谊如何抵御一切困难。

例子不胜枚举，但请注意，仅当''友谊''是故事的关键元素之一时才使用本标签，否则每款游戏都有''朋友''。');
INSERT INTO "tags" VALUES ('g711','刺客主角','cont',104,'本作主角是（或曾经是）一名[url=http://en.wikipedia.org/wiki/Assassin]刺客[/url]。');
INSERT INTO "tags" VALUES ('g713','工薪族主角','cont',295,'本作主角是一名[url=http://en.wikipedia.org/wiki/Salaryman]白领商务人士[/url]。

工薪族指收入以薪水为基础的人，尤指为公司工作的人。');
INSERT INTO "tags" VALUES ('g714','装傻的主角','cont',19,'本作主角表现得愚蠢，但这全都是他装出来的。

有时也被称为"装傻"，这是一种策略，其效果取决于角色让其他人相信自己是个彻底的傻瓜，因此无害。

更多信息参见[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/ObfuscatingStupidity]此处[/url]。');
INSERT INTO "tags" VALUES ('g715','汉字双关','cont',61,'本作包含大量日语特有的双关语，通常涉及汉字的构造、字源、部首构成等。

这些双关语可能是为了喜剧效果而作的玩笑，也可能服务于剧情要点。');
INSERT INTO "tags" VALUES ('g717','现代秋叶原','cont',46,'本作设定在现代[url=http://en.wikipedia.org/wiki/Akihabara]秋叶原[/url]，或至少其故事有相当部分发生在现代秋叶原。
注意："现代"指的是20世纪末至今的某个未具体说明的时间段。');
INSERT INTO "tags" VALUES ('g718','女性支配','ero',1475,'本视觉小说至少包含一个涉及[url=https://en.wikipedia.org/wiki/Dominatrix]女性支配[/url]的性爱场景。

女性支配是一种BDSM活动，其中支配方为女性。');
