具有这种性格的女主角通常正遭受某种心理创伤。');
INSERT INTO "tags" VALUES ('g720','性爱器具','ero',5313,'本作包含多个涉及性爱器具或[url=http://en.wikipedia.org/wiki/Sex_toys]性玩具[/url]的场景。');
INSERT INTO "tags" VALUES ('g721','振动器','ero',2862,'本作包含多个涉及使用[url=http://en.wikipedia.org/wiki/Vibrator_(sex_toy)]振动器[/url]的场景。');
INSERT INTO "tags" VALUES ('g722','假阳具','ero',1454,'本作包含多个涉及[url=http://en.wikipedia.org/wiki/Dildo]假阳具[/url]的场景。');
INSERT INTO "tags" VALUES ('g723','穿戴式假阳具','ero',721,'本作包含多个涉及[url=http://en.wikipedia.org/wiki/Strap-on_dildo]穿戴式假阳具[/url]的场景。');
INSERT INTO "tags" VALUES ('g726','笨拙女主角','cont',257,'本游戏中的一位或多位女主角是[url=http://dictionary.reference.com/browse/clumsy]笨拙[/url]的，或者被认为是[url=http://en.wikipedia.org/wiki/Accident-proneness]容易出事故[/url]的。

笨拙的人是指缺乏技能或身体协调性，因而比其他人更容易发生意外的人。

事故倾向，也称为笨拙，是指某些人可能具有先天倾向，或者比其他人更容易遭遇事故（如车祸和工伤）的概念。它可能被用作拒绝为此类个人提供任何保险的理由。');
INSERT INTO "tags" VALUES ('g727','隐藏振动器','ero',712,'本故事包含角色在日常活动中偷偷使用，或被迫/被骗使用振动器的场景，例如在工作、上学、吃晚饭等时候。');
INSERT INTO "tags" VALUES ('g728','有脸的主角','tech',12042,'本游戏的主角在CG和/或[URL=https://vndb.org/g1903]立绘[/URL]中可见脸部。

这是与通常脸部隐藏的视觉小说主角的显著不同之处——脸部隐藏的主角通常有头发或阴影遮住脸部，在每次镜头中脸部几乎不出现在画面中，眼睛未画出等等。');
