INSERT INTO "tags" VALUES ('g733','破处','ero',6421,'本游戏有一个或多个失去童贞或[url=http://en.wikipedia.org/wiki/Defloration#Loss_of_virginity]破处[/url]的场景。通常包括流血和对此冗长的讨论。');
