INSERT INTO "tags" VALUES ('g750','足交','ero',2245,'本游戏中某个角色是[url=http://en.wikipedia.org/wiki/Footjob]足交[/url]的接受者。

足交是指用脚进行的性行为。它被认为是足部恋物癖的一部分。相关行为包括以脚趾为重点的趾交，以及只使用脚掌的掌交。');
INSERT INTO "tags" VALUES ('g751','乳交','ero',5260,'本游戏至少包含一个[url=http://en.wikipedia.org/wiki/Titfuck]乳交[/url]场景。

乳交涉及用女性乳房刺激男性阴茎。');
INSERT INTO "tags" VALUES ('g752','兽人','cont',1998,'本游戏包含[url=http://en.wikipedia.org/wiki/Furry]兽人[/url]角色。

兽人是一个俚语，形容那些拥有动物外貌、用两条腿走路并像人类一样行动的角色。

尽管这个标签很容易与[url=http://vndb.org/g753]兽耳[/url]混淆，但[url=http://th00.deviantart.net/fs70/PRE/f/2011/328/9/7/furry_chart_by_mandalorianjedi-d4h6t0n.jpg]这张图片[/url]可能有助于解惑。');
INSERT INTO "tags" VALUES ('g753','兽耳','cont',1896,'这些游戏以[url=http://en.wikipedia.org/wiki/Kemonomimi#Animals]兽耳[/url]角色为特色，他们通常看起来像人类，但附加了动物特征（如耳朵或尾巴）。');
INSERT INTO "tags" VALUES ('g754','杂项角色标签','cont',0,'这个元标签用于收集那些并不特指主角、女主角或配角的人物标签。');
INSERT INTO "tags" VALUES ('g755','人工智能','cont',963,'剧情至少在一定程度上围绕[url=http://en.wikipedia.org/wiki/Artificial_intelligence]人工智能[/url]展开，并探讨其真实本质。');
INSERT INTO "tags" VALUES ('g756','仅含处女女主角','cont',2900,'本游戏中所有女主角（即有路线的角色）均为处女。

这个[url=http://virgindb.g.ribbon.to/]网站[/url]可能会有所帮助。');
INSERT INTO "tags" VALUES ('g757','冬季','cont',1208,'游戏中有许多场景发生在[url=http://en.wikipedia.org/wiki/Winter]冬季[/url]。');
INSERT INTO "tags" VALUES ('g758','季节','cont',0,'这个元标签用于聚合四个季节标签，供那些发生在特定季节（或多个季节）、捕捉该季节氛围等的游戏使用。');
INSERT INTO "tags" VALUES ('g760','夏季','cont',1064,'游戏中有许多场景发生在夏季。');
INSERT INTO "tags" VALUES ('g761','机甲驾驶员女主角','cont',68,'本游戏中一位或多位女主角驾驶/操控/穿戴？[url=http://en.wikipedia.org/wiki/Mecha]机甲[/url]。

包括各种科幻与幻想情境，例如变成机甲、通过神经链接/远程在现实或虚拟/幻想现实中远程操控机甲等。');
INSERT INTO "tags" VALUES ('g762','驾驶员女主角','cont',27,'本游戏中一位或多位女主角操作陆地载具。

包括[url=http://en.wikipedia.org/wiki/Driving]驾驶[/url]各种陆地载具，从城市汽车到赛车、公共汽车、卡车等，也包括坦克等军用车辆……

还包括由动物拉动的马车和货车，但不包括更适合称为‘骑’而非‘驾驶’的其他载具，如马、自行车、滑板等。');
INSERT INTO "tags" VALUES ('g763','驾驶员主角','cont',66,'本游戏的主角操作陆地载具。

包括[url=http://en.wikipedia.org/wiki/Driving]驾驶[/url]各种陆地载具，从城市汽车到赛车、公共汽车、卡车等，也包括坦克等军用车辆……

还包括由动物拉动的马车和货车，但不包括更适合称为‘骑’而非‘驾驶’的其他载具，如马、自行车、滑板等。');
INSERT INTO "tags" VALUES ('g764','机甲驾驶员主角','cont',94,'本游戏的主角驾驶/操控/穿戴？[url=http://en.wikipedia.org/wiki/Mecha]机甲[/url]。

包括各种科幻与幻想情境，例如变成机甲、通过神经链接/远程在现实或虚拟/幻想现实中远程操控机甲等。');
INSERT INTO "tags" VALUES ('g765','竞速游戏','tech',9,'本游戏拥有属于[url=http://en.wikipedia.org/wiki/Racing_game]竞速游戏[/url]类型的游戏玩法要素。

此标签适用于玩家主动参与这些赛车环节的游戏，不同于初代《Moero Downhill Night》中你只需在比赛中做出视觉小说式选择。');
INSERT INTO "tags" VALUES ('g766','向日葵','cont',50,'这些游戏包含许多有[url=http://en.wikipedia.org/wiki/Sunflower]向日葵[/url]和/或向日葵花田的场景。');
INSERT INTO "tags" VALUES ('g767','情节装置','cont',0,'这些标签最恰当的描述是[url=http://en.wikipedia.org/wiki/Plot_device]情节装置[/url]。

情节装置是故事中的某个物品或角色，其唯一目的是推动情节发展，或者克服情节中的某种困难。');
INSERT INTO "tags" VALUES ('g769','动画结局','tech',47,'包含一个或多个动画结局片段。

只用于有结局动画的游戏，而非那些用动画场景讲述故事的游戏。');
INSERT INTO "tags" VALUES ('g770','植物与花卉','cont',380,'用于包含大量[url=http://en.wikipedia.org/wiki/Plant]植物[/url]和[url=http://en.wikipedia.org/wiki/Flower]花卉[/url]相关场景的游戏。');
INSERT INTO "tags" VALUES ('g771','玫瑰','cont',47,'游戏包含有[url=http://en.wikipedia.org/wiki/Rose]玫瑰[/url]和/或玫瑰园的场景。');
