INSERT INTO "tags" VALUES ('g773','阴谋','cont',327,'这个故事包含一个阴谋。

它可以是一个[url=http://en.wikipedia.org/wiki/Collusion]共谋[/url], [url=http://en.wikipedia.org/wiki/Conspiracy_%28civil%29]民事[/url], [url=http://en.wikipedia.org/wiki/Conspiracy_%28crime%29]刑事[/url] 或 [url=http://en.wikipedia.org/wiki/Conspiracy_%28political%29]政治阴谋[/url]。');
INSERT INTO "tags" VALUES ('g774','部分配音的主角','tech',459,'这些游戏有配音主角，但这种情况并不常见。');
INSERT INTO "tags" VALUES ('g775','孤儿女主角','cont',418,'这个游戏中的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Orphan]孤儿[/url]。

孤儿是指永久失去父母或被父母遗弃的孩子。通常来说，只有失去双亲的孩子（或动物的幼崽）才被称为孤儿。然而，成年人也可以被称为孤儿，或"成年孤儿"。');
INSERT INTO "tags" VALUES ('g776','战术家女主角','cont',51,'这个游戏中的一位或多位女主角是一名战术家 -一位擅长设计和规划行动与政策以实现重大或总体目标的人。

她的行动经过精心计算，通常能跳出框架思考，并采用非正统的战术和策略来实现她的目标。

她可能是领导者、顾问，或者只是一个在旁观战并发表评论的人。');
INSERT INTO "tags" VALUES ('g777','战术家主角','cont',108,'这个游戏的主角是一名战术家 -一位擅长设计和规划行动与政策以实现重大或总体目标的人。

他的行动经过精心计算，通常能跳出框架思考，并采用非正统的战术和策略来实现他的目标。

他可能是领导者、顾问，或者只是一个在旁观战并发表评论的人。');
INSERT INTO "tags" VALUES ('g778','战术家支援角色','cont',17,'这个游戏中的一位或多位支援角色是战术家 - 擅长设计和规划行动与政策以实现重大或总体目标的人。

他们的行动经过精心计算，通常能跳出框架思考，并采用非正统的战术和策略来实现他们的目标。

他们可能是领导者、顾问，或者只是些在旁观战并发表评论的人。');
INSERT INTO "tags" VALUES ('g779','不可靠的叙述者','tech',154,'一种叙述技巧，故事叙述者不真诚，或在叙述方式中引入偏见，并可能误导读者，隐藏或淡化某些事件、角色或动机。

更多信息参见[url=http://en.wikipedia.org/wiki/Unreliable_narrator]维基百科[/url]。');
INSERT INTO "tags" VALUES ('g780','闪前','cont',113,'一种插入的场景，将叙事从故事当前时间点向前推进。闪前通常用于表现预期、计划或想象中将在未来发生的事件。它们也可能揭示故事中尚未发生但即将更详细地发生的重要部分。

更多信息参见[url=http://en.wikipedia.org/wiki/Flashforward]维基百科[/url]。');
INSERT INTO "tags" VALUES ('g781','啦啦队员女主角','cont',111,'这个故事中的一位女主角是[url=http://en.wikipedia.org/wiki/Cheerleader]啦啦队员[/url]。');
