INSERT INTO "tags" VALUES ('g788','自我乱伦','ero',76,'这些成人游戏包含性爱场景，其中某个角色（或主角）与自己的替代版本发生性关系。');
INSERT INTO "tags" VALUES ('g789','惊悚','cont',505,'这个故事含有[url=http://en.wikipedia.org/wiki/Thriller_(genre)]惊悚[/url]元素。

惊悚是文学、电影和电视节目中的一个广泛类型，以悬念、紧张和刺激为主要元素。惊悚作品强烈刺激观众的情绪，带来高度的期待感、超常的预期、不确定性、惊讶、焦虑和/或恐惧。惊悚电影往往令人肾上腺素飙升、粗粝、振奋且节奏明快。');
INSERT INTO "tags" VALUES ('g790','病娇（Yangire）女主角','cont',50,'“Yangire”指那些因嫉妒、恼怒或类似情绪而突然精神崩溃的角色。这种行为与病娇（yandere）角色的区别在于引发角色转变的动机不同。

简而言之，病娇角色（yanderekko）的动机源于对男主角的爱，而yangire角色的动机则源于其他角色，与爱慕或吸引的情感无关。与yandere类似，相关的名词“yangirekko”可以用来描述具有yangire性格特质的女性角色。

[摘自[url=http://en.wikipedia.org/wiki/Yandere#Yangire]维基百科[/url]]');
INSERT INTO "tags" VALUES ('g791','无角色立绘','tech',1992,'带有此标签的游戏不使用立绘来表现角色。但它们可能在文本框一侧显示小型的角色头像。

更多细节请参考相关的[url=http://en.wikipedia.org/wiki/Visual_novel#Style]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g792','深色皮肤角色','cont',3036,'此游戏包含一位肤色较深的[url=http://en.wikipedia.org/wiki/Skin_tone]肤色[/url]配角。

也适用于肤色极深的晒黑角色。');
INSERT INTO "tags" VALUES ('g793','角色肤色','cont',0,'这些是关于[url=http://en.wikipedia.org/wiki/Human_skin_color]肤色[/url]的标签。');
INSERT INTO "tags" VALUES ('g794','大量事件CG','tech',1427,'带有此标签的游戏拥有数量不成比例的大量事件CG。如果游戏仅使用CG和背景来讲述故事，则可能与[url=http://vndb.org/g791]无角色立绘[/url]标签重叠。');
INSERT INTO "tags" VALUES ('g795','无事件CG','tech',945,'此游戏包含的事件CG数量极少，甚至为零。

请不要与效果CG混淆，效果CG是那些在屏幕上短暂出现的全屏CG图像，用于表现各种效果。
效果CG的一些例子包括《Fate/stay night》中的战斗效果和《海猫鸣泣之时》中的枪击效果。');
INSERT INTO "tags" VALUES ('g796','纳米机器','cont',49,'该游戏将[url=http://en.wikipedia.org/wiki/Nanomachines]纳米机器[/url]作为故事的重要部分。');
INSERT INTO "tags" VALUES ('g797','事件CG','tech',4217,'与游戏事件CG相关的标签归入此处。

事件CG的描述来自[url=http://en.wikipedia.org/wiki/Visual_novel]维基百科[/url]：
在典型的视觉小说中，图形由一组通用背景（通常每个场景只有一个）构成，角色立绘（立ち絵，tachi-e）叠加在这些背景之上；视角通常是第一人称，主角是不可见的。在情节的某些关键时刻，会显示特殊的事件CG图形；这些是更详细的图像，专门为该场景绘制，而不是由预定义的元素组成，它们通常使用更具电影感的拍摄角度，并包含主角。这些事件CG一旦在游戏中“解锁”，通常可以随时查看；这为重新玩游戏并尝试做出不同决定提供了动力，因为通常不可能在一次游戏中看到所有特殊事件。');
INSERT INTO "tags" VALUES ('g798','立绘（Sprites）','tech',0,'所有与[url=http://en.wikipedia.org/wiki/Sprite_%28computer_graphics%29]精灵图[/url]相关的标签都归入此处。

当我们提到视觉小说中的“sprite”时，我们通常想到的是“角色立绘”。但实际上，视觉小说屏幕上除了背景和文本之外的所有内容也都是sprite。

角色立绘在日语中被称为tachi-e（立ち絵）。');
INSERT INTO "tags" VALUES ('g799','食人','cont',232,'带有此标签的游戏以某种形式包含[url=http://en.wikipedia.org/wiki/Cannibalism]食人[/url]情节。');
INSERT INTO "tags" VALUES ('g800','极度（不）幸運的女主角','cont',24,'游戏中的一位（或多位）女主角极其[url=http://en.wikipedia.org/wiki/Luck]幸运[/url]、极其不幸，或者可能同时兼备两者。');
INSERT INTO "tags" VALUES ('g802','温泉','cont',317,'游戏的重要部分设定在[url=http://en.wikipedia.org/wiki/Onsen]温泉[/url]中。');
INSERT INTO "tags" VALUES ('g803','猪','cont',43,'此游戏中有一只或多只[url=http://en.wikipedia.org/wiki/Pig]猪[/url]在故事中扮演重要角色。或者游戏在许多场景中都有猪出现，并伴有大量与之相关的对话。');
INSERT INTO "tags" VALUES ('g804','游戏保存方式','tech',1831,'此元标签用于汇集所有与游戏所使用的[url=http://en.wikipedia.org/wiki/Save_game]存档[/url]方法相关的标签。');
INSERT INTO "tags" VALUES ('g805','仅自动存档','tech',209,'本游戏总是将数据保存到同一文件中，通常是在故事的固定节点（这一过程被称为[url=http://en.wikipedia.org/wiki/Autosave]自动保存[/url]）。玩家无法在游戏的不同节点保留多个存档，因此如果想看到做出不同选择的结果，他们通常需要从头开始重新游戏。');
INSERT INTO "tags" VALUES ('g806','地下世界','续',98,'游戏发生在某种形式的[url=http://en.wikipedia.org/wiki/Underworld]冥界[/url]或[url=http://en.wikipedia.org/wiki/Hell]地狱[/url]中，是恶魔和/或被诅咒的灵魂的居所。它可能对应于某个特定神话中的冥界，也可能只是一个普通的地狱。');
INSERT INTO "tags" VALUES ('g809','律师女主角','cont',48,'本游戏的女主角是一名[url=http://en.wikipedia.org/wiki/Lawyer]律师[/url]。');
INSERT INTO "tags" VALUES ('g810','秘密社团','cont',114,'本游戏中有一个[url=http://en.wikipedia.org/wiki/Secret_society]秘密社团[/url]在幕后活动。');
INSERT INTO "tags" VALUES ('g811','朋友团体','cont',633,'本游戏中有一群朋友，他们将自己的团体视为一个实体（有名号、据点等），通常也包括主角在内。');
INSERT INTO "tags" VALUES ('g812','科学家女主角','cont',197,'本游戏中的一名女主角是[url=http://en.wikipedia.org/wiki/Scientist]科学家[/url]。她可能在科学领域工作，在大学、研究中心或科学实验室任职。');
INSERT INTO "tags" VALUES ('g813','戴单片眼镜的女主角','cont',11,'游戏中有一位或多位女主角在游戏的大部分时间里佩戴[url=http://en.wikipedia.org/wiki/Monocle]单片眼镜[/url]。');
INSERT INTO "tags" VALUES ('g814','赛车手主角','cont',11,'本故事的主角是一名[url=http://en.wikipedia.org/wiki/List_of_racing_forms#Motor_racing]赛车[/url]车手。');
INSERT INTO "tags" VALUES ('g815','赛车手女主角','cont',13,'本故事的一名女主角是[url=http://en.wikipedia.org/wiki/List_of_racing_forms#Motor_racing]赛车[/url]车手。');
INSERT INTO "tags" VALUES ('g817','极简主义立绘','tech',62,'本游戏的立绘符合并阐述了现代极简主义运动。

极简主义描述了各种艺术和设计形式中的运动，尤其是视觉艺术和音乐，作品被剥离到最基本的特征。

详情请参阅相关的[url=http://en.wikipedia.org/wiki/Minimalism]维基百科[/url]文章。');
INSERT INTO "tags" VALUES ('g818','失眠','cont',33,'故事中的一位或多位角色患有[url=http://en.wikipedia.org/wiki/Insomnia]失眠[/url]症。');
INSERT INTO "tags" VALUES ('g820','孤儿主角','cont',723,'主角是一个[url=http://en.wikipedia.org/wiki/Orphan]孤儿[/url].

孤儿是指永久失去父母或被父母遗弃的儿童。通常用法中，只有失去双亲的儿童（或动物的幼崽）才被称为孤儿。然而，成年人也可以被称为孤儿，或 "成年孤儿".');
INSERT INTO "tags" VALUES ('g821','监狱','续',169,'这个游戏有许多场景设定在[url=http://en.wikipedia.org/wiki/Prison]监狱[/url]中。');
INSERT INTO "tags" VALUES ('g822','王室主角','续',529,'这个故事的主角目前是或曾经是[url=http://en.wikipedia.org/wiki/Royal_family]王室[/url]成员。');
INSERT INTO "tags" VALUES ('g823','无限自发强化道具','续',12,'与它的父标签类似，不同之处在于这些爆气情况会在一次战斗中出现多次。

游戏中的战斗/冲突往往倾向于依靠意志力或类似方式解决，而非技巧、智慧、装备或已有因素，这使得角色能够超越自身极限，并根据情况需要，一次又一次地不断提升层次。
致命一击并非终点，而是无限爆气的机会。通常，愤怒和濒临死亡（或真正死亡）只会让角色变得更强，使他们能够引出深不可测的力量。
使用这种情节装置的战斗通常总是可能以任何一方获胜告终，因为客观上几乎不限制你爆气的次数——每次都能用比上一次承受的更强攻击来再次爆气。

例如：
当英雄被故事中的大反派痛打时，他想起功夫大师教过的一招，并用它击败了对手。
大反派对此感到困惑，愈发愤怒，变成了恶魔，反过来痛打英雄。
英雄突然得到他死去童年好友（已变成天使）的祝福，用圣火轰击恶魔。
作为回应，恶魔大反派抓起一架恰好落在他摔倒处的机甲（或凭空召唤出一架），与它融合成为大反派恶魔机甲，并用激光束将英雄分解。
之后，英雄有一段关于他的过去、朋友、家人等的漫长场景，这不知何故重新点燃了他的意志，让他死而复生，成为一个超级人类天使祝福功夫男，然后……

简而言之，就像那部经典的[url=http://www.youtube.com/watch?v=16uevTBhgV4&feature=related]金属骑士[/url]电影。');
INSERT INTO "tags" VALUES ('g824','自发爆气','续',82,'这种[url=http://en.wikipedia.org/wiki/Plot_device]情节装置[/url]出现在这样的故事中：角色突然展现出隐藏的力量、策略和技术（招式）来解救自己脱离困境，无论情况多么严峻。

他们要么自发地发明这些新策略和技术（招式），要么以某种方式突然获得新力量，要么记起之前学到/发现的东西（这些东西此前很少被提及），等等。此类例子在少年漫画风格的故事中比比皆是……');
INSERT INTO "tags" VALUES ('g825','记者主角','续',103,'游戏的主角是一名[url=http://en.wikipedia.org/wiki/Journalist]记者[/url]。');
INSERT INTO "tags" VALUES ('g826','基因研究','cont',361,'游戏中展现了对[url=http://en.wikipedia.org/wiki/Genetics]遗传学[/url]、DNR和/或克隆技术的高级研究。');
INSERT INTO "tags" VALUES ('g827','克隆女主角','cont',85,'这款游戏的女主角是一名[url=http://en.wikipedia.org/wiki/Cloning]克隆人[/url]。');
INSERT INTO "tags" VALUES ('g828','间谍主角','cont',122,'这款游戏的主角是一名特工或[url=http://en.wikipedia.org/wiki/Spy]间谍[/url]。他为政府或私人团体工作，拥有众多技能和秘密。');
INSERT INTO "tags" VALUES ('g829','女服务员女主角','cont',545,'这款游戏中的一名女主角是[url=http://en.wikipedia.org/wiki/Waitress]女服务员[/url]。');
INSERT INTO "tags" VALUES ('g830','选集','tech',497,'与其说是一个单一的故事，这部视觉小说是许多互不相干的短篇故事的合集。

通常，建议为不同的游戏创建单独的页面。但有些情况下这既不实际也不适用，请在这些情况下使用此标签。');
INSERT INTO "tags" VALUES ('g831','科学家主角','cont',152,'这款游戏的主角是一名[url=http://en.wikipedia.org/wiki/Scientist]科学家[/url]。他/她可能从事科学领域的工作，在大学、研究中心或科学实验室任职。');
INSERT INTO "tags" VALUES ('g832','醒来性爱','ero',595,'在游戏中的某个时刻，主角醒来发现自己处于性情境中。例如，他在被口交的过程中醒来。');
INSERT INTO "tags" VALUES ('g833','预渲染的3D背景','tech',310,'这款游戏的背景是[url=http://en.wikipedia.org/wiki/Pre-rendering]预渲染[/url]的。

请勿对所有资源均由3D软件预渲染的游戏使用此标签。');
INSERT INTO "tags" VALUES ('g834','拳交','ero',332,'[url=http://en.wikipedia.org/wiki/Fisting]拳交[/url]是一种将手插入阴道或直肠的性行为。一旦完全插入，手指要么自然握成拳头，要么保持伸直。在更激烈的拳交形式中，如“冲击”，完全握紧的拳头可能会缓慢插入并抽出。拳交可单独进行或与伴侣一起进行，所有性取向的人都可以享受。');
INSERT INTO "tags" VALUES ('g835','按活动分类的性内容','ero',0,'这个元标签用于收集与行为[url=http://en.wikipedia.org/wiki/Sex_position]姿势[/url]或类型相关的性活动标签，这些标签未被其他相关标签涵盖。');
INSERT INTO "tags" VALUES ('g836','语音旁白','技术',212,'本游戏的叙事是完全配音的，或至少是显著配音的。');
INSERT INTO "tags" VALUES ('g837','天体女主角','cont',18,'其中一位女主角是宇宙天体（恒星、行星等）的拟人化/化身。

有关更多详情，请参见维基百科关于[url=http://en.wikipedia.org/wiki/Celestial_body]天体[/url]的条目。');
INSERT INTO "tags" VALUES ('g838','外国人主角','cont',297,'主角来自与视觉小说设定不同的国家。例如，如果视觉小说设定在日本，他就是[url=http://en.wikipedia.org/wiki/Gaijin]外国人[/url]。

Gaijin是一个日语词汇，意思是“非日本人”或“外国人”。这个词是gaikokujin的简称，意为“外国国民”。');
INSERT INTO "tags" VALUES ('g839','外国人女主角','cont',903,'一位或多位女主角来自与视觉小说设定不同的国家。例如，如果视觉小说设定在日本，她就是[url=http://en.wikipedia.org/wiki/Gaijin]外国人[/url]。

Gaijin是一个日语词汇，意思是“非日本人”或“外国人”。这个词是gaikokujin的简称，意为“外国国民”。');
INSERT INTO "tags" VALUES ('g842','黑道女主角','cont',32,'本游戏中的一位女主角是（或曾经是）[url=http://en.wikipedia.org/wiki/Yakuza]黑道[/url]成员。');
INSERT INTO "tags" VALUES ('g843','丰满女主角','cont',165,'本游戏中的一位女主角[url=http://en.wikipedia.org/wiki/Overweight]超重[/url]。');
INSERT INTO "tags" VALUES ('g844','暴露癖','ero',1123,'本游戏包含以[url=http://en.wikipedia.org/wiki/Exhibitionism]暴露癖[/url]为特色的场景。');
INSERT INTO "tags" VALUES ('g845','体重过轻的女主角','cont',11,'本游戏中的一位女主角[url=http://en.wikipedia.org/wiki/Underweight]体重过轻[/url]。');
INSERT INTO "tags" VALUES ('g846','超现实','cont',428,'本游戏的剧情具有[url=http://en.wikipedia.org/wiki/Surrealism]超现实主义[/url]的特征，这是一场哲学和艺术运动。

超现实主义作品具有惊奇元素、意想不到的并置和[url=http://en.wikipedia.org/wiki/Non_sequitur_%28humor%29]不根据前提的推论[/url]；然而，许多超现实主义艺术家和作家首先将其作品视为哲学运动的表现，作品只是副产品。');
INSERT INTO "tags" VALUES ('g847','限时选项','tech',408,'在这部视觉小说中，玩家面临的选项通常有时间限制。如果在规定时间内未选择答案，系统将随机选择一个答案，或者主角将被视为没有说话。

在某些情况下，可用选项可能会随着计时器倒数而出现或消失，或者选择选项时剩余的时间可能会影响结果。');
INSERT INTO "tags" VALUES ('g848','女主角之死','cont',1087,'本游戏中的一位女主角可以在某条路线或结局中[url=http://en.wikipedia.org/wiki/Death]死亡[/url]。

如果这导致游戏结束/坏结局，或对于女主角死亡“不算什么大事”、也不是像兰斯系列那样产生戏剧性的游戏，请勿使用此标签。');
INSERT INTO "tags" VALUES ('g851','插入歌曲','tech',188,'这些游戏除了通常的开场和片尾歌曲外，还包含其他歌曲。

对于此标签，只计入有歌词的歌曲。');
INSERT INTO "tags" VALUES ('g852','秋天','cont',585,'本游戏有许多场景发生在[url=http://en.wikipedia.org/wiki/Autumn]秋天[/url]。');
INSERT INTO "tags" VALUES ('g853','冰壶','cont',2,'[url=http://en.wikipedia.org/wiki/Curling]冰壶[/url]运动在这部视觉小说中扮演重要角色。');
INSERT INTO "tags" VALUES ('g854','女主角的服装与配饰','cont',0,'这些是按照  [url=http://en.wikipedia.org/wiki/Clothing]服装[/url]和[url=http://en.wikipedia.org/wiki/Fashion_accessory]配饰[/url]划分的女主角原型。');
INSERT INTO "tags" VALUES ('g855','穿短裤的女主角','cont',401,'本游戏有相当多的场景中可以看到穿着[url=http://en.wikipedia.org/wiki/Shorts]短裤[/url]的女孩（不要与牛仔裤、长裤或内裤混淆）。');
INSERT INTO "tags" VALUES ('g856','穿泳装的女主角','cont',915,'本游戏有相当多的场景中可以看到穿着[url=http://en.wikipedia.org/wiki/Swimsuits]泳装[/url]的女孩。不要因为一次海滩活动或其他罕见出现就打上此标签。只有在这样的场景相当常见时才使用（例如关于游泳俱乐部的视觉小说等）。');
INSERT INTO "tags" VALUES ('g857','可见内裤的女主角','cont',258,'这款游戏有相当多的场景展示女主角们穿着[url=http://en.wikipedia.org/wiki/Panties]内裤[/url].

内裤是一种设计用于女性及儿童穿着的内衣, 位于腰部以下, 胯部区域. 典型组成部分包括弹性腰带, 覆盖生殖器区域的裆部 (通常衬有棉等吸湿材料), 一对裤腿开口 (通常与腰带一样由弹性材料制成), 并采用透气材料制成. 虽然内裤最初设计用于覆盖女性整个下半身, 但现代版本 (自1970年代以来) 要么没有裤腿, 要么在某些情况下非常短, 并且随着时间的推移变得越来越暴露.

不要将此特征用于角色内衣短暂露出的性爱场景. 仅在角色偶尔露出内衣的情况下使用, 要么是因为她们的其他服装设计方式露出内衣, 要么是她们没有穿其他衣物来遮盖内衣.');
INSERT INTO "tags" VALUES ('g858','长筒袜','cont',436,'这款游戏有相当多的场景以[url=http://en.wikipedia.org/wiki/Stockings]长筒袜[/url]为焦点.');
INSERT INTO "tags" VALUES ('g860','穿连裤袜的女主角','cont',803,'这款游戏有相当多的场景可以看到穿着[url=http://en.wikipedia.org/wiki/Tights]连裤袜[/url], 打底裤或类似紧身薄长裤的女孩/女孩们 (不要将它们与牛仔裤, 宽大的或普通的厚长裤或短裤混淆).');
INSERT INTO "tags" VALUES ('g861','穿连体紧身衣的女主角','cont',89,'这款游戏有相当多的场景可以看到穿着[url=http://en.wikipedia.org/wiki/Catsuit]连体紧身衣[/url] (即紧贴全身的连体服装) 的女孩/女孩们.

不, 这个标签与猫或猫娘没有任何关系.');
INSERT INTO "tags" VALUES ('g862','穿盔甲的女主角','cont',160,'这款游戏有相当多的场景可以看到穿着[url=http://en.wikipedia.org/wiki/Armor]盔甲[/url]的女主角们. 可以是西式或东式盔甲, 甚至是某种未来风格的盔甲.');
INSERT INTO "tags" VALUES ('g863','穿牛仔裤的女主角','cont',103,'这款游戏有相当多的场景可以看到穿着[url=http://en.wikipedia.org/wiki/Jeans]牛仔裤[/url]的女主角们. 

此标签仅用于长裤, 不要用于牛仔裤短裤或裙子.');
INSERT INTO "tags" VALUES ('g864','解谜游戏','tech',500,'此标签表示游戏包含涉及解谜的游戏玩法.

有关详细信息, 请查看相关的[url=http://en.wikipedia.org/wiki/Puzzle_game]维基百科[/url]条目.

不要与[url=http://vndb.org/g350]交互式冒险游戏[/url]标签混淆, 仅用于实际有谜题的游戏.');
INSERT INTO "tags" VALUES ('g865','婚礼','cont',453,'这些游戏包含至少一个[url=http://en.wikipedia.org/wiki/Wedding]婚礼[/url]场景.');
INSERT INTO "tags" VALUES ('g867','春天','cont',185,'游戏中有许多场景发生在[url=http://en.wikipedia.org/wiki/Spring_%28season%29]春天[/url].');
INSERT INTO "tags" VALUES ('g868','游戏时间计数器','tech',167,'这些游戏通过时间计数器或[url=http://en.wikipedia.org/wiki/Timer]计时器[/url]让你知道已经花了多少小时阅读它们.');
INSERT INTO "tags" VALUES ('g869','女性穿衣男性裸体','ero',192,'包含女性穿着衣服, 男性裸体 (或至少穿得比女性少得多) 的性爱场景. 可适用于BSDM场景, 以及普通性行为.

有关详细信息, 请查看相关的[url=http://en.wikipedia.org/wiki/CFNM]维基百科[/url]文章.');
INSERT INTO "tags" VALUES ('g870','主仆','cont',200,'这个故事包含一些处于[url=http://en.wikipedia.org/wiki/Servant]主仆[/url]关系中的角色.

不要仅仅因为名字像fate/stay night中的主从那样使用, 或者如果这些只是对故事没有影响的次要角色.');
INSERT INTO "tags" VALUES ('g871','曲目显示','tech',176,'这些游戏会告诉你播放的[url=http://en.wikipedia.org/wiki/Video_game_music]背景音乐[/url]名称, 通常是在曲目开始播放时在屏幕一角弹出显示.');
INSERT INTO "tags" VALUES ('g872','没有常识的女主角','cont',196,'这位女主角对世事一无所知. 
那些本应是常识的东西, 例如操作常见的家用电器, 她脑子里却没有.

无知背后的原因多种多样. 常见原因包括:
在隔离环境中长大的富家千金.
外星人.
来自过去或未来的时间旅行者.
来自另一个维度的人.
等等.

有关详细信息, 请查看维基百科关于[url=http://en.wikipedia.org/wiki/Experience]经验[/url]的条目.');
INSERT INTO "tags" VALUES ('g873','绝望','cont',260,'主角团队陷入绝望的境地. 每次看起来他们终于找到了出路, 形势又会逆转, 未来看起来比以前更加绝望.

直到可能到了最后, 一切是否得到解决尚不确定...');
INSERT INTO "tags" VALUES ('g874','伪装的女主角','cont',451,'这款游戏中的一位或多位女主角正在伪装自己的性格。

例如，一位女主角可能看起来是一位彬彬有礼的淑女（总是礼貌冷静、乐于助人），但这只是掩盖其真实性格的外表——一个更加咄咄逼人且容易粗鲁的性格。

请注意，这并不一定使女主角成为恶人或叛徒。请勿将此标签用于伪装角色，例如间谍、刺客之类。');
INSERT INTO "tags" VALUES ('g875','双马尾女主角','cont',2619,'这款游戏中的一位女主角扎着两条马尾辫。

有关详细信息，请查看相关维基百科文章：[url=http://en.wikipedia.org/wiki/Bunches]发束[/url]和[url=http://en.wikipedia.org/wiki/Pigtail]马尾辫[/url]。');
INSERT INTO "tags" VALUES ('g876','带有故事的坏结局','tech',1495,'与那些在错误选择后很快“游戏结束”的游戏相比，本游戏中的坏结局有其自己的故事，无论是否伴有诸如血腥死亡或性侵等令人不快的最后场景。

那些喜欢阅读更多游戏内容但又希望避免令人不安的坏结局的玩家，也会觉得这些结局令人满意。

请勿将此标签用于每个具有非暴力坏结局的游戏，而仅用于那些包含新的阅读内容的游戏。');
INSERT INTO "tags" VALUES ('g877','游戏结束','tech',1398,'这些游戏具有[url=http://en.wikipedia.org/wiki/Game_over]游戏结束[/url]类型的失败结局。 

这些结局很简短，有时伴随着令人不安的场景，这些场景可被视为一种惩罚形式，比如游戏角色惨死的场景或性侵犯等。

它们并不真正具有太多故事价值，除非你喜欢这类场景，而且避免它们不会导致玩家错过故事的重要部分。');
INSERT INTO "tags" VALUES ('g878','传教士体位','ero',4304,'这款游戏包含[url=http://en.wikipedia.org/wiki/Missionary_position]传教士体位[/url]的性爱内容。');
INSERT INTO "tags" VALUES ('g879','歌手女主角','cont',710,'这款游戏中的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Vocalist]歌手[/url]。');
INSERT INTO "tags" VALUES ('g880','处于恋爱关系中的主角','cont',2139,'这位主角在故事开始时就已经投入了一段浪漫的[url=http://en.wikipedia.org/wiki/Interpersonal_relationship]关系[/url]，或者在故事的很早阶段就如此。

因此，在这个故事的进程中，如果你追求另一段恋情，就会引发各种问题和内疚感。

这也意味着主角不会像初次经历恋情的孩子那样对感情一无所知。

有一个深深爱着主角的青梅竹马，总是叫醒他、为他做饭、随时陪他玩，这些都不算数。因为对于业界标准的钝感主角来说，她其实并不存在。');
INSERT INTO "tags" VALUES ('g881','学生男主角','cont',1375,'这款游戏中的一位男主角是[url=http://en.wikipedia.org/wiki/Student]学生[/url]。');
INSERT INTO "tags" VALUES ('g882','转学生男主角','cont',47,'这款游戏中的一位或多位男主角是转学生。

查看相关[url=http://en.wikipedia.org/wiki/Transfer_student]维基百科[/url]文章以了解详情。');
INSERT INTO "tags" VALUES ('g883','主角的青梅竹马作为男主角','cont',767,'这款游戏中至少有一位男主角是主角的[url=http://en.wikipedia.org/wiki/Childhood_friend]青梅竹马[/url]。');
INSERT INTO "tags" VALUES ('g884','持剑男主角','cont',206,'这款游戏中的一位男主角随身携带一把[url=http://en.wikipedia.org/wiki/Sword]剑[/url]。他可能加入了与剑相关的学校社团（剑道、居合道、击剑），也可能有其他原因这样做。');
INSERT INTO "tags" VALUES ('g885','男主角','cont',0,'[url=http://en.wikipedia.org/wiki/Hero]男主角[/url]是游戏角色阵容中的男性成员，拥有自己的路线和/或结局。

这类角色几乎只出现在乙女游戏中。

不要与视觉小说的主要男性角色混淆，那被称为主角。');
INSERT INTO "tags" VALUES ('g886','男主角的角色/职业','cont',0,'男主角原型根据他们（以什么为生）做什么或他们在社会中扮演的[url=http://en.wikipedia.org/wiki/Role]角色[/url]来定义。

还包括那些已经停止从事该工作（角色等）但仍然表现得像该角色的人物。');
INSERT INTO "tags" VALUES ('g887','男主角的关系','cont',0,'这些是根据男主角与主角的[url=http://en.wikipedia.org/wiki/Kinship]关系[/url]划分的原型。');
INSERT INTO "tags" VALUES ('g888','男主角的特征','cont',0,'定义男主角的性格特征。

查看相关的[url=http://en.wikipedia.org/wiki/Trait_theory]维基百科[/url]文章以了解详情。');
INSERT INTO "tags" VALUES ('g889','男主角的外貌','cont',0,'这些是根据男主角的[url=http://en.wikipedia.org/wiki/Human_physical_appearance]外貌[/url]划分的原型。');
INSERT INTO "tags" VALUES ('g890','男主角的服装和配饰','cont',0,'这些是根据男主角的[url=http://en.wikipedia.org/wiki/Clothing]服装[/url]和[url=http://en.wikipedia.org/wiki/Fashion_accessory]配饰[/url]划分的原型。');
INSERT INTO "tags" VALUES ('g891','战斗男主角','cont',876,'这些游戏中的英雄中至少有一位是[url=http://en.wikipedia.org/wiki/Warrior]战士[/url]。他可能是职业军人、自学的武术家、拥有强大护身符和剑的牧师，或者可能是奇幻生物。但他绝对能在战斗中保护好自己。');
INSERT INTO "tags" VALUES ('g892','魔物娘女主角','cont',304,'[url=http://knowyourmeme.com/memes/subcultures/monster-girls]魔物娘[/url]是一种特殊的人形化类型，其中拟人化角色是生物（现实和虚构的）与女孩的混合体。魔物娘也可以指已有怪物的萌化版本，例如吸血鬼或巨魔。
请勿将此标签用于在完全人形和完全怪物形态之间切换的完整怪物（例如由于变形或狼人化），仅用于同时展现人类和怪物特征的角色（比如有狼耳和尾巴，但其他方面是人形的“狼人”）。');
INSERT INTO "tags" VALUES ('g893','火星','cont',23,'故事发生在[url=http://en.wikipedia.org/wiki/Mars]火星[/url]上。');
INSERT INTO "tags" VALUES ('g894','69式','ero',3107,'包含两个（或更多）角色互相进行口交的场景。

请参阅相关的[url=http://en.wikipedia.org/wiki/69_%28sex_position%29]维基百科[/url]条目了解详情。');
INSERT INTO "tags" VALUES ('g895','图书馆','cont',138,'本游戏的相当一部分场景设在[url=http://en.wikipedia.org/wiki/Library]图书馆[/url]中。');
INSERT INTO "tags" VALUES ('g896','图书馆员女主角','cont',89,'本游戏中至少有一位女主角是[url=http://en.wikipedia.org/wiki/Librarian]图书馆员[/url]。');
INSERT INTO "tags" VALUES ('g897','排便癖','ero',841,'[url=http://en.wikipedia.org/wiki/Coprophilia]排便癖[/url]是一种涉及排便行为或粪便本身在性情境中的恋物癖。');
INSERT INTO "tags" VALUES ('g898','基督教神话','cont',99,'[url=http://en.wikipedia.org/wiki/Christian_mythology]基督教神话[/url]强烈影响了这部视觉小说的设定和事件。');
INSERT INTO "tags" VALUES ('g899','异色瞳主角','cont',72,'主角的眼睛颜色不同。

请参阅相关的[url=http://en.wikipedia.org/wiki/Heterochromia]维基百科[/url]文章了解详情。');
INSERT INTO "tags" VALUES ('g900','主角的双胞胎姐妹作为女主角','cont',102,'这些游戏中的女主角是主角的[url=http://en.wikipedia.org/wiki/Twins]双胞胎[/url]姐妹。与[url=http://vndb.org/g343]双胞胎姐妹女主角[/url]的区别在于，她们是主角的双胞胎姐妹，而不是随便什么双胞胎姐妹。');
INSERT INTO "tags" VALUES ('g901','无法保存','tech',529,'在这部视觉小说中，你完全无法[url=http://en.wikipedia.org/wiki/Save_game]存档[/url]。就这么简单。');
INSERT INTO "tags" VALUES ('g902','第三人称叙事','tech',1115,'在这类故事中，一个脱离肉体的叙述者描述角色的行为以及发生在他们身上的事。你不会像在第一人称叙事中那样直接透过角色的眼睛看到一切，但叙述者常常会描述主角对正在发生的事情的想法和感受。

第三人称叙述者有时可以是全知的，能够鸟瞰所有事情。他们也可以受限，只紧密围绕一两个角色的视角。

在这种叙事风格中，所有角色都以他、她或他们来指代，而不是任何角色在叙述中使用“我”或“我们”。');
INSERT INTO "tags" VALUES ('g903','滥交女主角','cont',593,'本游戏中的女主角很[url=https://en.wikipedia.org/wiki/Promiscuity]滥交[/url]。她频繁且不加选择地与不同伴侣发生性行为。

滥交的角色四处上床不是为了钱，不像妓女，而是为了自己的满足。

不要将其与[url=/g498]性欲亢进女主角[/url]混淆，后者根本无法抵抗任何性场景。');
INSERT INTO "tags" VALUES ('g904','超级变形CG','tech',1100,'这部视觉小说有一些采用[url=http://en.wikipedia.org/wiki/Super_deformed]超级变形[/url]风格的CG。');
INSERT INTO "tags" VALUES ('g905','交合声音','ero',1830,'在这部视觉小说的H场景中，可以听到性行为本身产生的音效。

不要将其与吸吮或接吻的声音或呻吟混淆，那些相当常见。

请不要将其与[url=http://vndb.org/g2063]背景呻吟[/url]标签混淆。');
INSERT INTO "tags" VALUES ('g906','性交内部展示','ero',1053,'在性爱场景中，会出现阴茎（或使用性玩具时的插入物）在伴侣肠道、阴道、子宫、喉咙等内部的视角。');
INSERT INTO "tags" VALUES ('g907','未来中国','cont',10,'这个故事设定在一个想象中的未来[url=http://en.wikipedia.org/wiki/China]中国[/url]。');
INSERT INTO "tags" VALUES ('g909','深色皮肤主角','cont',742,'本游戏的主角拥有较深的[url=http://en.wikipedia.org/wiki/Skin_tone]肤色[/url]。

也可以用于肤色极深（晒黑）的角色。');
INSERT INTO "tags" VALUES ('g910','精灵女主角','cont',145,'一位或多位女主角是[url=http://en.wikipedia.org/wiki/Fairy]仙女[/url]。不是托尔金式的精灵，而是明亮的带翼灵体。');
INSERT INTO "tags" VALUES ('g911','穿紧身连体衣的女主角','cont',135,'本游戏有大量场景可以看到一位或多位身穿[url=http://en.wikipedia.org/wiki/Leotard]紧身连体衣[/url]的女孩（即覆盖躯干但让腿和手臂自由的紧身连体衣）。

不要将其与全身紧身衣或泳装混淆。');
INSERT INTO "tags" VALUES ('g912','穿透明连体衣的女主角','cont',64,'本游戏有大量场景可以看到一位或多位身穿[url=http://en.wikipedia.org/wiki/Bodystocking]透明连体衣[/url]的女孩。这是一种与紧身连体衣或全身紧身衣类似的内衣。关键区别在于它通常由透明材料制成。尽管它是相当性感的服装，但在一些视觉小说中，女主角们会把它当作日常主要服装穿着。');
INSERT INTO "tags" VALUES ('g913','有心理问题的男主角','cont',300,'适用于患有[url=http://en.wikipedia.org/wiki/Mental_disorder]精神障碍[/url]的男主角。');
INSERT INTO "tags" VALUES ('g914','有健康问题的男主角','cont',494,'适用于身体并非处于最佳状态的男主角的标签。

如果你认为此男主角未被任何子标签涵盖，你也可以直接使用此标签。');
INSERT INTO "tags" VALUES ('g915','戏剧社','cont',86,'学校[url=http://en.wikipedia.org/wiki/Drama]戏剧[/url]社及其相关活动在本故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g916','口交','ero',8867,'本游戏包含以[url=http://en.wikipedia.org/wiki/Blowjob]口交[/url]为特色的场景。

口交是用口对阴茎进行的性行为。');
INSERT INTO "tags" VALUES ('g917','手交','ero',4407,'本游戏至少包含一个以[url=http://en.wikipedia.org/wiki/Handjob]手交[/url]为特色的场景。

手交是一个俚语或非正式用语，指一方用手刺激另一方的阴茎，无论对方是女性还是男性，通常刺激到达到性高潮和射精为止。它与口交的区别在于完全用手而非口或手口并用摩擦阴茎。

相比之下，对女性性器官的手动刺激通常称为指交，因为使用手指刺激阴蒂和外阴。');
INSERT INTO "tags" VALUES ('g918','西部','cont',64,'这部视觉小说的设定带有[url=http://en.wikipedia.org/wiki/Western_%28genre%29]西部题材[/url]的特征。');
INSERT INTO "tags" VALUES ('g919','牛仔女郎女主角','cont',29,'本游戏的女主角具有[url=http://en.wikipedia.org/wiki/Cowgirl#Cowgirls]牛仔女郎[/url]外貌。帽子、靴子和牛仔裤……

不要与兽耳或毛茸茸角色混淆。');
INSERT INTO "tags" VALUES ('g920','学生会会长女主角','cont',503,'女主角是[url=http://en.wikipedia.org/wiki/Student-body_president]学生会会长[/url]。

学生会会长是高中、学院或大学级别学生政府或学生会中职位最高的官员。作为学业期间最受尊敬的荣誉职位之一，担任会长可以让学生获得强大的人际交往、领导、社交、经济和管理技能。雇主可能会高度重视有这种任职经历的申请人。

学生会会长与班长不同。班长只代表特定年级的学生，而学生会会长是学校中职位最高的学生。');
INSERT INTO "tags" VALUES ('g921','学生会会长主角','cont',73,'主角是[url=http://en.wikipedia.org/wiki/Student-body_president]学生会会长[/url]。

学生会会长是高中、学院或大学级别学生政府或学生会中职位最高的官员。作为学业期间最受尊敬的荣誉职位之一，担任会长可以让学生获得强大的人际交往、领导、社交、经济和管理技能。雇主可能会高度重视有这种任职经历的申请人。

学生会会长与班长不同。班长只代表特定年级的学生，而学生会会长是学校中职位最高的学生。');
INSERT INTO "tags" VALUES ('g922','超过七位男主角','cont',263,'本游戏拥有比通常视觉小说更多的男主角；具体而言至少八位。');
INSERT INTO "tags" VALUES ('g923','王室男主角','cont',432,'这些游戏至少有一位具有贵族血统的男主角——国王或王子，或者如果这定义了他的话，属于“普通”贵族。

当前状态对这些标签并不重要，例如一个已不复存在的贵族家庭不会改变男主角的与生俱来的权利。

不命名为“贵族英雄”是为了避免大量拥有高贵心灵但没有贵族血统的英雄被提名。

详情请查阅相关的[url=http://en.wikipedia.org/wiki/Royal_family]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g924','恶魔男主角','cont',354,'至少有一位男主角是（西方类型的）[url=http://en.wikipedia.org/wiki/Demon]恶魔[/url]。');
INSERT INTO "tags" VALUES ('g925','领袖男主角','cont',638,'这类英雄是[url=http://en.wikipedia.org/wiki/Leader]领导者[/url]。这位英雄有可供指挥的员工/臣民/士兵。游戏故事可能包括也可能不包括实际指挥他们的情节。');
INSERT INTO "tags" VALUES ('g926','不朽英雄','cont',773,'其中一位英雄是[url=http://en.wikipedia.org/wiki/Immortality]不朽[/url]的，不会衰老，也无法被常规手段杀死。');
INSERT INTO "tags" VALUES ('g927','非人英雄','cont',2035,'至少有一位英雄可能看起来像[url=http://en.wikipedia.org/wiki/Human]人类[/url]，但他的身份远不止如此……');
INSERT INTO "tags" VALUES ('g928','神性英雄','cont',568,'所有属于[url=http://en.wikipedia.org/wiki/Divinity]神性[/url]的英雄都归入此处。');
INSERT INTO "tags" VALUES ('g929','正太英雄','cont',483,'本游戏的至少一位英雄是正太。他要么是青春期或青春前的男孩，要么看起来像这样的男孩。

在将他归类为正太时，他的年龄并不重要。这仅仅关乎外貌。

详情请参阅相关[url=http://en.wikipedia.org/wiki/Shotacon]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g930','骑士英雄','cont',196,'游戏的主要英雄之一是一位[url=http://en.wikipedia.org/wiki/Knight]骑士[/url]。');
INSERT INTO "tags" VALUES ('g931','猫耳英雄','cont',136,'游戏中的一位英雄长着猫一样的耳朵。对于非人/半人角色来说，这可以是天生的，也可以只是装饰品。');
INSERT INTO "tags" VALUES ('g932','神祇英雄','cont',157,'这部视觉小说中的一位英雄是[url=http://en.wikipedia.org/wiki/God]神[/url]。');
INSERT INTO "tags" VALUES ('g933','学生社团社长女主角','cont',165,'其中一位女主角是某个[url=http://en.wikipedia.org/wiki/Student_club]学生社团[/url]的社长。');
INSERT INTO "tags" VALUES ('g934','学生社团社长主角','cont',49,'游戏的主角是某个[url=http://en.wikipedia.org/wiki/Student_club]学生社团[/url]的社长。');
INSERT INTO "tags" VALUES ('g936','兽耳英雄','cont',403,'本游戏有一位或多位以英雄角色出场的[url=http://en.wikipedia.org/wiki/Kemonomimi#Animals]兽耳[/url]角色。

兽耳角色通常看起来像人类，只是增添了动物般的特质（如耳朵或尾巴）。');
INSERT INTO "tags" VALUES ('g937','精神控制','cont',1065,'游戏故事包含精神控制、[url=http://en.wikipedia.org/wiki/Hypnotism]催眠[/url]和[url=https://en.wikipedia.org/wiki/Brainwashing]洗脑[/url]元素。');
INSERT INTO "tags" VALUES ('g938','星际飞船战斗','cont',36,'本游戏包含使用[url=http://en.wikipedia.org/wiki/Starship]星际飞船[/url]在太空进行的战斗。');
INSERT INTO "tags" VALUES ('g939','可避免的强奸','ero',474,'本游戏包含可通过做出正确选择或在游戏阶段中取得成功来避免的[url=http://en.wikipedia.org/wiki/Rape]强奸[/url]场景。

此标签已不再适用，而应使用其子标签。请使用更具体的标签，若你不确定该使用哪个标签（例如，因为你尚未通关游戏），请改用通用的[url=/g84]强奸[/url]标签。');
INSERT INTO "tags" VALUES ('g940','完全可避免的女主角强奸','ero',79,'你可以看到游戏中的每一个“正常结局”，而无需经历任何女主角的强奸场景。她们仅有的强奸场景被保留给过早的坏结局，而你并非必须阅读它们才能进入其他结局。

不适用于非女主角角色。');
INSERT INTO "tags" VALUES ('g941','天体主角','cont',14,'主角是宇宙天体（恒星、行星等）的拟人化/化身。

更多详情请参阅维基百科中关于[url=http://en.wikipedia.org/wiki/Celestial_body]天体[/url]的条目。');
INSERT INTO "tags" VALUES ('g942','酷刑','cont',683,'本游戏包含[url=http://en.wikipedia.org/wiki/Torture]酷刑[/url]场景。

这些场景不要求以图像方式描绘。

此标签旨在标记本游戏中某处存在刻意施加于人们的严重痛苦或折磨（无论是身体还是精神上）的场景。');
INSERT INTO "tags" VALUES ('g943','画面风格变化','tech',125,'视觉小说的[url=http://en.wikipedia.org/wiki/Style_%28visual_arts%29]画面风格[/url]在游戏过程中会明显变化一次或多次。这可能代表角色的性格变化、意识状态的改变、场景的转换、回忆段落等。');
INSERT INTO "tags" VALUES ('g944','剧院','cont',74,'游戏的很大一部分场景设定在[url=http://en.wikipedia.org/wiki/Theater]剧院[/url]中。');
INSERT INTO "tags" VALUES ('g945','音乐剧院','cont',11,'游戏的很大一部分场景设定在[url=http://en.wikipedia.org/wiki/Musical_theatre]音乐剧院[/url]中。');
INSERT INTO "tags" VALUES ('g946','20年代','cont',63,'这个故事发生在地球上的1920年至1929年之间。

关于20年代的更多详情可参阅相关[url=http://en.wikipedia.org/wiki/1920s]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g947','血亲母女乱伦','ero',217,'这些游戏包含有血缘关系的母女之间的性爱场景。');
INSERT INTO "tags" VALUES ('g948','秘书主角','cont',16,'本视觉小说中的主角是一名[url=http://en.wikipedia.org/wiki/Secretary]秘书[/url]。');
INSERT INTO "tags" VALUES ('g949','农民主角','cont',40,'本游戏的主角是一名[url=http://en.wikipedia.org/wiki/Farmer]农民[/url]。');
INSERT INTO "tags" VALUES ('g950','半恶魔主角','cont',63,'游戏主角是[url=http://en.wikipedia.org/wiki/Demon]恶魔[/url]与人类或类似存在所生的孩子。');
INSERT INTO "tags" VALUES ('g951','半人类主角','cont',129,'该游戏的主角诞生于人类与另一物种成员的结合。

例如[url=http://en.wikipedia.org/wiki/Half-elves]半精灵[/url]、半恶魔、[url=http://en.wikipedia.org/wiki/Demigod]半神[/url]等……

通过魔法或科学创造的组合也属于此标签，但生化人等不算。');
INSERT INTO "tags" VALUES ('g952','神性主角','cont',631,'本游戏的主角属于[url=http://en.wikipedia.org/wiki/Divinity]神性存在[/url]。');
INSERT INTO "tags" VALUES ('g953','类型通主角','cont',45,'主角[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/GenreSavvy]类型通[/url]，意味着他会将自己的处境与电影/书籍/电子游戏/视觉小说中的英雄进行比较，并据此得出结论。');
INSERT INTO "tags" VALUES ('g954','科学奇幻','cont',220,'这部视觉小说融合了科幻与奇幻的元素（例如使用魔法的机器人）。

[url=http://en.wikipedia.org/wiki/Science_Fantasy]科学奇幻[/url]是思辨虚构中的一个混合类型，同时借鉴科幻与奇幻的元素。');
INSERT INTO "tags" VALUES ('g955','叛乱','cont',162,'反抗政府的[url=http://en.wikipedia.org/wiki/Rebellion]叛乱[/url]在这部视觉小说中扮演重要角色。

此标签仅用于政治性叛乱，而非描述角色的叛逆态度。');
INSERT INTO "tags" VALUES ('g956','霸主主角','cont',5,'主角是一位霸主。他率领一支黑暗军团征服整个已知宇宙（或类似设定）。');
INSERT INTO "tags" VALUES ('g957','政府','cont',112,'[url=http://en.wikipedia.org/wiki/Government]政府[/url]在这个故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g958','骑士主角','cont',156,'本游戏的主角是一名[url=http://en.wikipedia.org/wiki/Knight]骑士[/url]。');
INSERT INTO "tags" VALUES ('g959','50年代','cont',20,'这个故事发生在1950年至1959年之间的地球。

更多关于[url=https://en.wikipedia.org/wiki/1950s]50年代[/url]的细节可在维基百科找到。');
INSERT INTO "tags" VALUES ('g960','电波','cont',125,'电波游戏是恐怖色情游戏的一个子类型，由1996年Leaf公司的游戏《雫》推广开来，该游戏也为此类型命名。典型模式是恐怖故事，事件发生的催化剂源于熟悉的人以陌生却看似有预谋的方式行动。故事中的世界似乎已经疯狂，而主角也未必是例外。此名称来源于一种想法，即电磁波（电波）导致人们行为异常（尽管很少有如此平凡的解释）。

描述来自Asceai对[url=https://web.archive.org/web/20100511181341/http://www.menhelmate.org/2010/04/subarashiki-hibi-furenzoku-sonzai.html]《美好的每一天》[/url]的评论。');
INSERT INTO "tags" VALUES ('g961','发型遮眼的女主角','cont',195,'本游戏至少有一位女主角在故事相当长的时间里，其发型遮住了她的一只（或两只）眼睛。

也用于描述类似地因阴影而隐藏面部的女主角。');
INSERT INTO "tags" VALUES ('g963','仙境','cont',124,'本游戏的大部分场景设定在刘易斯·卡罗尔所著[url=http://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland]《爱丽丝梦游仙境》[/url]中的仙境。动物和无生命物体通常拥有声音和个性，角色也常常对应卡罗尔原书及其续集中的著名角色。');
INSERT INTO "tags" VALUES ('g964','提示角落','tech',134,'本游戏的坏结局（偶尔也有好结局）之后会有一个短场景，其中角色向玩家解释他们哪里做错了，以及下次如何获得更好的结局。

(至少这是其意图。在许多游戏中，实际建议毫无用处或根本不存在，角色反而开玩笑。似乎没人在意。)');
INSERT INTO "tags" VALUES ('g965','双人口交','ero',1910,'本游戏包含两人同时对一个人进行[url=http://en.wikipedia.org/wiki/Blowjob]口交[/url]的场景。

[url=https://s2.vndb.org/sf/27/130927.jpg]NSFW示例1[/url]
[url=https://s2.vndb.org/sf/28/130928.jpg]NSFW示例2[/url]');
INSERT INTO "tags" VALUES ('g966','有翅膀的女主角','cont',220,'本游戏包含一位或多位拥有[url=http://en.wikipedia.org/wiki/Wing]翅膀[/url]的女主角。 

她可以是一位天使、恶魔，甚至是戴着配饰的普通人类，但许多场景中她的背上都有翅膀。');
INSERT INTO "tags" VALUES ('g967','受欢迎的主角','cont',184,'这类主角在游戏开始时就很受欢迎，或在不久后变得受欢迎。这与通常要在游戏结局才受欢迎的视觉小说主角相反。

拥有几个童年玩伴或一群朋友不算。

详情请参见维基百科上关于[url=http://en.wikipedia.org/wiki/Popularity]人气[/url]的条目。');
INSERT INTO "tags" VALUES ('g968','船长主角','cont',48,'本故事的主角是或将成为一艘船/太空船/潜艇的[url=http://en.wikipedia.org/wiki/Captain_%28nautical%29]船长[/url]/指挥官。

你也可以用这个标签来表示[url=http://en.wikipedia.org/wiki/Captain_%28naval%29]海军上校[/url]的军衔，因为两者几乎相同。但不要将其用于与船只无关的[url=http://en.wikipedia.org/wiki/Captain_%28land%29]陆军上尉[/url]军衔。');
INSERT INTO "tags" VALUES ('g969','海盗','cont',159,'[url=http://en.wikipedia.org/wiki/Pirate]海盗[/url]在本故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g970','海盗女主角','cont',60,'本故事中有一位或多位女主角是[url=http://en.wikipedia.org/wiki/Pirate]海盗[/url]。');
INSERT INTO "tags" VALUES ('g971','海盗主角','cont',28,'本故事的主角是[url=http://en.wikipedia.org/wiki/Pirate]海盗[/url]。');
INSERT INTO "tags" VALUES ('g972','贫民窟','cont',48,'本故事的一部分发生在[url=http://en.wikipedia.org/wiki/Slums]贫民窟[/url]。故事中描绘了贫困和艰难的生活条件。');
INSERT INTO "tags" VALUES ('g973','成年英雄','cont',2108,'本游戏中的一位或多位英雄是[url=http://en.wikipedia.org/wiki/Adult]成年人[/url]。

''成年人''是一个宽泛主观的概念，但在视觉小说设定中，通常指任何已成年并完成高中学业的人。在高中非强制或不存在的高奇幻／科幻设定中，拥有职业或达到通常预期有职业的年龄，可以作为''成年''的标志。');
INSERT INTO "tags" VALUES ('g974','恐男症女主角','cont',93,'本游戏包含一位患有恐男症的女主角——即对男性过度或非理性的恐惧。');
INSERT INTO "tags" VALUES ('g975','短暂性爱场景','ero',592,'这部视觉小说中的性爱场景异常短暂。虽然每个场景可能有很多CG，和/或整体场景很多，但每个场景都很短，结束得很快。');
INSERT INTO "tags" VALUES ('g976','漫长性爱场景','ero',461,'这部视觉小说中的性爱场景异常漫长。每个场景预计会有大段文字（多次射精可选但相当常见）。');
INSERT INTO "tags" VALUES ('g978','受孕','ero',1848,'涉及使其中一位角色受孕的故事。通常出现在关于[url=http://en.wikipedia.org/wiki/Fertilisation]受精[/url]癖好的游戏中。

不要用于那些你突然看到女主角怀孕但受孕行为在故事本身中并未扮演角色的游戏。这个标签描述的是受孕行为，而不是怀孕状态。');
INSERT INTO "tags" VALUES ('g979','白化病女主角','cont',181,'本游戏中某位女主角的外貌类似于[url=http://en.wikipedia.org/wiki/Albino]白化病患者[/url]；她拥有白发，眼睛呈现不自然的颜色（如红色或近乎透明的蓝色）。');
INSERT INTO "tags" VALUES ('g980','主角死亡','cont',1577,'游戏中的主角可以在某条路线或结局中[url=http://en.wikipedia.org/wiki/Death]死亡[/url]。

如果这导致游戏结束／坏结局，请勿使用。');
INSERT INTO "tags" VALUES ('g981','时间流逝','cont',426,'事件的时间跨度对情节而言是实质且重要的。故事结束时，读者应能真切感受到世界中时间的显著流逝。这至少意味着数年甚至数世纪的过去，角色或世界随时间而改变。

此标签不适用于短暂的时间跳跃，或发生在游戏尾声实际事件之后的时间跳跃等。');
INSERT INTO "tags" VALUES ('g982','以真实人物为原型的女主角','cont',134,'本游戏中至少有一位女主角是以现实世界中的某个人物为原型。');
INSERT INTO "tags" VALUES ('g983','有关西口音的女主角','cont',204,'这位女主角使用[url=http://en.wikipedia.org/wiki/Kansai_accent]关西方言[/url]（最常见的是京都或大阪方言），使她脱颖而出。与日本人对该地区人的刻板印象一致，她通常也会有与之匹配的直率性格。');
INSERT INTO "tags" VALUES ('g985','女祭司女主角','cont',120,'本游戏的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Priest]女祭司[/url]。

不要与[url=http://vndb.org/g115]巫女女主角[/url]混淆。');
INSERT INTO "tags" VALUES ('g986','性爱时泌乳','ero',1852,'角色在性交过程中乳房会产生乳汁。');
INSERT INTO "tags" VALUES ('g987','史莱姆怪物强奸','ero',289,'本游戏包含一个或多个与无定形/凝胶状怪物发生强奸的场景。');
INSERT INTO "tags" VALUES ('g988','与怪物性交','ero',2435,'本游戏包含与非人类、非动物的虚构生物发生性行为的场景。');
INSERT INTO "tags" VALUES ('g989','涉及史莱姆怪物的自愿性行为','ero',73,'本游戏包含与无定形/凝胶状怪物自愿发生性行为的场景。');
INSERT INTO "tags" VALUES ('g990','前女子学校','cont',66,'游戏设定在一所前女子学校中，男女比例极低，主角可能是全女生班级中唯一的男生。');
INSERT INTO "tags" VALUES ('g991','内置攻略','tech',343,'本游戏内置[url=http://en.wikipedia.org/wiki/Walkthrough#Video_games]攻略[/url]/流程图，可通过游戏内菜单访问。');
INSERT INTO "tags" VALUES ('g992','近亲繁殖','ero',439,'这些游戏包含导致怀孕的乱伦场景。

详见维基百科上的[url=http://en.wikipedia.org/wiki/Inbreeding]近亲繁殖[/url]条目。');
INSERT INTO "tags" VALUES ('g993','女仆支援角色','cont',242,'游戏中的一位支援角色是[url=http://en.wikipedia.org/wiki/Maid]女仆[/url]。');
INSERT INTO "tags" VALUES ('g994','中世纪奇幻','cont',658,'游戏设定在基于或借鉴中世纪元素的地方，但具有明显的虚构元素，如虚构王国或魔法。

这类游戏通常包含公主、骑士、城堡和魔法。

详见相关的[url=http://en.wikipedia.org/wiki/Medieval_fantasy]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g995','魔法少女主角','cont',217,'本游戏的主角是一位[url=http://en.wikipedia.org/wiki/Magical_girl]魔法少女[/url]。');
INSERT INTO "tags" VALUES ('g996','怪物','cont',3670,'本游戏有一个或多个[url=http://en.wikipedia.org/wiki/Monster]怪物[/url]在故事中扮演重要角色，或者游戏中有大量场景出现怪物并配有多条相关对话。');
INSERT INTO "tags" VALUES ('g997','异装癖','cont',1364,'本游戏中的一些角色有[url=http://en.wikipedia.org/wiki/Crossdressing]异装[/url]行为。');
INSERT INTO "tags" VALUES ('g998','拥有幻想朋友的主角','cont',107,'本游戏的主角有一个或多个[url=http://en.wikipedia.org/wiki/Imaginary_friends]幻想朋友[/url]。');
INSERT INTO "tags" VALUES ('g999','有自杀倾向的主角','cont',252,'在故事中主角试图自杀（无论成功与否）。

详见相关的[url=http://en.wikipedia.org/wiki/Suicide_crisis]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g1000','妖怪女主角','cont',351,'本游戏的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Y%C5%8Dkai]妖怪[/url]。

妖怪的种类从邪恶到调皮不一而足，有时也会给遇到它们的人带来好运。它们常常拥有动物特征（例如类似乌龟的河童，或长有翅膀的天狗），其他时候它们可能看起来接近人类，有些看起来像无生命物体，还有些没有可辨认的形态。妖怪通常具有超自然的精神力量，其中变形是最常见的能力之一。能够变形的妖怪被称为化け物（obake）。');
INSERT INTO "tags" VALUES ('g1001','英雄之死','cont',538,'本游戏中的英雄可以在某条路线或结局中[url=http://en.wikipedia.org/wiki/Death]死亡[/url]。

如果这导致游戏结束/坏结局，请不要使用此标签；也不适用于英雄之死‘无关紧要’或不会引发任何戏剧性事件（如兰斯系列）的游戏。');
INSERT INTO "tags" VALUES ('g1002','雪女女主角','cont',38,'本游戏中的一位女主角是[url=http://en.wikipedia.org/wiki/Yuki-onna]雪女[/url]，一种掌控冰、寒冷天气或能冻结一切的半灵体存在。');
INSERT INTO "tags" VALUES ('g1003','剪影','tech',282,'在带有此标签的游戏中，相当大一部分角色立绘是[url=http://en.wikipedia.org/wiki/Silhouette]剪影[/url]。');
INSERT INTO "tags" VALUES ('g1004','元虚构','tech',1036,'视觉小说的外部属性（如它是虚构作品、是电脑程序、是屏幕上的二维呈现、或受到玩家影响等）本身与情节相关。这可能涵盖从经常打破第四面墙到更精巧的情节构造等多种形式。

详见相关的[url=http://en.wikipedia.org./wiki/Metafiction]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g1005','日期显示','tech',1393,'游戏在屏幕上显示故事内的日期和/或时间，始终显示或至少定期显示。通常以屏幕角落的小型覆盖层形式呈现。');
INSERT INTO "tags" VALUES ('g1006','船只','cont',172,'这部视觉小说有许多场景发生在[url=http://en.wikipedia.org/wiki/Ship]航海船只[/url]上。');
INSERT INTO "tags" VALUES ('g1007','人鱼女主角','cont',118,'本游戏中的一个或多个女主角是[url=http://en.wikipedia.org/wiki/Mermaid]美人鱼[/url].

美人鱼是一种神话中的水生生物，拥有女性的头部和躯干以及鱼的尾巴。美人鱼在民间传说、文学和流行文化中有广泛的展现。');
INSERT INTO "tags" VALUES ('g1008','童话','cont',390,'本游戏融合了[url=http://en.wikipedia.org/wiki/Fairy_tale]童话[/url]的元素和主题。

被如此指定的故事中，只有少数明确提及仙女。尽管如此，这些故事可以与其他民间叙事（如通常涉及对所描述事件真实性的信仰的传说和传统）以及明确的道德故事（包括动物寓言）区分开来。童话通常以仙女、地精、精灵、巨魔、巨人或侏儒等民间角色为特色，并且通常涉及魔法或迷咒。');
INSERT INTO "tags" VALUES ('g1009','学生社团会长主角','cont',31,'其中一位主角是[url=http://en.wikipedia.org/wiki/Student_club]学生社团[/url]的会长。');
