INSERT INTO "tags" VALUES ('g1044','人鱼主角','cont',51,'这部视觉小说的主角属于海洋居住种族，是一位 [url=http://en.wikipedia.org/wiki/Merperson_%28disambiguation%29]人鱼/鱼人[/url]。');
