INSERT INTO "tags" VALUES ('g1046','伪郎主角','cont',76,'这部视觉小说的主角是一位女孩，其外貌特征使她看起来像男孩，甚至可能被误认为男孩。
[url=http://en.wikipedia.org/wiki/Cross_dressing]女扮男装[/url] 并非必需，但往往是造成混淆的根源。');
INSERT INTO "tags" VALUES ('g1047','中学','cont',70,'游戏的部分场景发生在 [url=http://en.wikipedia.org/wiki/Junior_High_School]中学[/url]。');
INSERT INTO "tags" VALUES ('g1048','宗教女主角','cont',113,'这部视觉小说中的一位女主角是某 [url=http://en.wikipedia.org/wiki/Religion]宗教[/url] 的虔诚信徒，而且经常谈论宗教。');
INSERT INTO "tags" VALUES ('g1049','声优女主角','cont',60,'本游戏的一位女主角是 [url=http://en.wikipedia.org/wiki/Seiyuu]声优[/url]。');
INSERT INTO "tags" VALUES ('g1050','旅程','cont',330,'这些游戏在大多数情况下是关于一场旅程的。

它可能是关于公路旅行，或与朋友、家人一起旅行。（[url=/g286]公路旅行[/url]）

或者像 [url=http://en.wikipedia.org/wiki/Odyssey]《奥德赛》[/url] 那样的史诗旅程，涉及指环和火山、跨越星空的航行，甚至可能是跨越维度的旅行。（[url=/g363]Odyssey[/url]）

也可能是关于一段不属于以上两种类型的旅程，例如从北京到柏林的旅行，在这种情况下请直接使用本标签。');
INSERT INTO "tags" VALUES ('g1051','近亲主角','cont',26,'主角的父母在遗传学上彼此有近亲关系。

详情请参阅相关的 [url=http://en.wikipedia.org/wiki/Inbred]维基百科[/url] 页面。');
INSERT INTO "tags" VALUES ('g1052','愚蠢的反派','cont',29,'游戏中的一位反派是 [url=http://en.wikipedia.org/wiki/Idiot]傻瓜[/url]。通常作为喜剧元素。');
INSERT INTO "tags" VALUES ('g1053','呆毛女主角','cont',829,'带有此标签的游戏至少有一位女主角，在游戏的大部分时间里都拥有一根 [url=http://animanga.wikia.com/wiki/Ahoge]呆毛[/url]。呆毛指的是一缕常常很长的、从头顶翘起的头发。
典型例子包括《Fate/Stay Night》中的Saber，或《Muv-Luv》系列中的纯夏。');
INSERT INTO "tags" VALUES ('g1054','疯狂科学家配角','cont',69,'游戏中的一位配角是 [url=http://en.wikipedia.org/wiki/Mad_scientist]疯狂科学家[/url]。');
INSERT INTO "tags" VALUES ('g1055','复活','cont',227,'涉及 [url=http://en.wikipedia.org/wiki/Resurrection]复活[/url] 的故事。');
INSERT INTO "tags" VALUES ('g1056','同人小说','tech',3686,'故事发生在另一位作者已经创造的世界中。这些作品大多为免费的二次创作小说。

详情请参阅相关的 [url=http://en.wikipedia.org/wiki/Fan-fiction]维基百科[/url] 条目。

非官方的忠实改编作品应改用 [url=/g3740]改编[/url] 或其子标签。');
INSERT INTO "tags" VALUES ('g1058','呆毛主角','cont',154,'带有此标签的游戏拥有一位主角，在游戏的大部分时间里，主角头上有一根[url=http://animanga.wikia.com/wiki/Ahoge]呆毛[/url]。呆毛指的是一缕从头顶伸出的，通常很大的头发。');
INSERT INTO "tags" VALUES ('g1059','开放式结局','tech',618,'本游戏的故事没有明确、终结性和决定性的结局。会有许多问题得不到回答，某些事件的结果永远不会被解释。

神秘的程度可能从少数未解释的细节，到让你想知道下一章在哪里的故事。

这种讲述故事的方式将问题的答案和故事的结果留给读者去想象。

仅用于结局可作多种解释的游戏。');
INSERT INTO "tags" VALUES ('g1060','呆毛男主角','cont',69,'带有此标签的游戏拥有一位男主角，他在游戏的大部分时间里都有一根呆毛。呆毛指的是一缕从头顶伸出的，通常很大的头发。');
INSERT INTO "tags" VALUES ('g1061','呆毛配角','cont',26,'带有此标签的游戏拥有一位配角，他在游戏的大部分时间里都有一根呆毛。呆毛指的是一缕从头顶伸出的，通常很大的头发。');
INSERT INTO "tags" VALUES ('g1064','秃头男主角','cont',24,'本游戏的一位男主角是[url=http://en.wikipedia.org/wiki/Bald]秃头[/url]的。');
INSERT INTO "tags" VALUES ('g1065','秃头主角','cont',32,'本游戏的主角是[url=http://en.wikipedia.org/wiki/Bald]秃头[/url]的。');
