INSERT INTO "tags" VALUES ('g1069','进风口发型女主角','cont',323,'女主角具有独特的“[url=https://tvtropes.org/pmwiki/pmwiki.php/Main/HairIntakes]进风口[/url]”发型，即上扬的前发（通常从中间分开）使头发看起来像发动机盖上的进气口。

典型的例子可以在[url=http://vndb.org/v4]Clannad[/url]的杏以及[url=http://vndb.org/v92]Muv Luv Alternative[/url]的角色阵容中找到。');
INSERT INTO "tags" VALUES ('g1070','渐变发色女主角','cont',109,'本游戏有一位女主角，其头发出于风格需要以[url=http://en.wikipedia.org/wiki/Color_gradient]渐变色[/url]呈现。');
INSERT INTO "tags" VALUES ('g1071','女主角的头发','cont',0,'这是一个元标签，用于收集所有关于女主角头发（通常是发型）的标签。');
INSERT INTO "tags" VALUES ('g1072','女主角的身体','cont',0,'这是一个元标签，用于收集所有关于女主角体型、比例和肤色的标签。');
INSERT INTO "tags" VALUES ('g1073','教师男主角','cont',397,'本游戏中的一位男主角从事[url=http://en.wikipedia.org/wiki/Teacher]教师[/url]职业。');
INSERT INTO "tags" VALUES ('g1074','克隆男主角','cont',19,'本游戏的一位男主角是[url=http://en.wikipedia.org/wiki/Cloning]克隆人[/url]。');
INSERT INTO "tags" VALUES ('g1075','克隆','cont',186,'本故事包含[url=http://en.wikipedia.org/wiki/Cloning]克隆[/url]。

生物学中的克隆是产生遗传相同个体的相似种群的过程，当细菌、昆虫或植物等生物进行无性繁殖时，自然界就会发生这种情况。');
INSERT INTO "tags" VALUES ('g1078','单恋','cont',329,'本故事的相当一部分内容以[url=http://en.wikipedia.org/wiki/Unrequited_love]单恋[/url]为特色，即一种没有得到回应或回报的爱。');
INSERT INTO "tags" VALUES ('g1079','运动短裤女主角','cont',369,'本游戏有相当多的场景可以看到穿着[url=http://en.wikipedia.org/wiki/Bloomers_%28clothing%29#Bloomers_in_Japan] 运动短裤[/url]的女孩。

运动短裤是日本女生体育短裤的一种。

请不要将此标签用于经典（即19世纪中叶至20世纪初）的灯笼裤。请改用[url=http://vndb.org/g1751]穿传统灯笼裤的女主角[/url]标签。');
INSERT INTO "tags" VALUES ('g1080','股间性交','ero',1587,'本游戏至少包含一个以[url=http://en.wikipedia.org/wiki/Intercrural_sex]股间性交[/url]为特色的场景。');
INSERT INTO "tags" VALUES ('g1081','微胖主角','cont',223,'一位明显[url=http://en.wikipedia.org/wiki/Overweight]超重[/url]的主角。');
INSERT INTO "tags" VALUES ('g1082','游戏玩家主角','cont',238,'主角是一位狂热的电子游戏玩家，即[url=http://en.wikipedia.org/wiki/Gamer]游戏玩家[/url]。');
INSERT INTO "tags" VALUES ('g1083','游戏玩家男主角','cont',80,'本游戏中的一位或多位男主角是狂热的电子游戏玩家，即[url=http://en.wikipedia.org/wiki/Gamer]游戏玩家[/url]。');
INSERT INTO "tags" VALUES ('g1084','多重插入','ero',2753,'本游戏有一个或多个性爱场景，其特点是[url=http://en.wikipedia.org/wiki/Double_penetration#Multiple_penetration]多重插入[/url]。

多重插入是指一个人同时被多次性插入。');
INSERT INTO "tags" VALUES ('g1085','颜射','ero',2596,'这款游戏包含一个或多个以[url=http://en.wikipedia.org/wiki/Bukkake]颜射[/url]为特色的场景。

颜射（Bukkake）指一个人被多名男性射精，或在某些情况下被同一名男性反复射精的场景。重点是接受者的身体被精液覆盖。');
INSERT INTO "tags" VALUES ('g1086','舔肛','色情',1302,'这款游戏包含一个或多个以[url=http://en.wikipedia.org/wiki/Anilingus]舔肛[/url]为特色的场景。

肛交口交，也称为肛口接触或舔肛（anilingus）（来自anus + lingus（拉丁语Lingere：舔，较少拼写为analingus）），是一种口交形式，涉及一个人的肛门或会阴与另一个人的嘴（嘴唇）或舌头接触。');
INSERT INTO "tags" VALUES ('g1087','自慰','色情',4163,'游戏至少包含一个以[url=http://en.wikipedia.org/wiki/Masturbation]自慰[/url]为特色的场景。

自慰（Masturbation）指对一个人生殖器的性刺激，通常达到性高潮。');
INSERT INTO "tags" VALUES ('g1090','股交','色情',475,'股交是一种性行为，阴茎在女性臀部之间多次抽插。

它类似于乳交，本身不包括任何肛门或阴道插入。');
INSERT INTO "tags" VALUES ('g1092','乳房增大','内容',387,'这款游戏的女主角在极短时间内乳房尺寸增大。这可能是像[url=http://en.wikipedia.org/wiki/Breast_implant]隆胸[/url]这样的真实医疗程序的结果，也可能是如某些超级药物或魔法等幻想来源的结果。

如果乳房增大到不可能、怪诞的尺寸，请改用[url=/g1561]怪诞身体改造[/url]。

如果乳房增大是通过某种现实医疗程序实施的，请将此标签与[url=/g3931]整形外科[/url]一起使用。');
INSERT INTO "tags" VALUES ('g1094','非插入式性行为','色情',9081,'游戏至少包含一个以[url=http://en.wikipedia.org/wiki/Non-penetrative_sex]非插入式性行为[/url]为特色的场景。

非插入式性行为是指没有阴道、肛门或口腔插入的性活动，不同于插入式性交、肛交或口交。');
INSERT INTO "tags" VALUES ('g1095','磨镜','色情',353,'这款游戏包含一个或多个[url=http://en.wikipedia.org/wiki/Tribadism]磨镜[/url]场景。

磨镜（Tribadism）是一种非插入式性行为，女性将外阴摩擦伴侣的身体以获得性刺激。这可能涉及女性间生殖器接触，或女性用自己的外阴摩擦伴侣的大腿、手臂、手掌或胃部，并不总是表现为剪刀式交缠动作。');
INSERT INTO "tags" VALUES ('g1097','反派女主角','内容',331,'这款游戏中的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Villainous]反派[/url]，或者干脆是故事中的“邪恶”角色。

一开始是坏人，或者后来变坏，然后再变好等等，无所谓，只要反派部分在故事中占据重要角色。

例子包括[url=http://vndb.org/v1494]Leet小姐[/url]。');
INSERT INTO "tags" VALUES ('g1102','雇佣兵主角','内容',68,'游戏的主角是（或曾经是）一名[url=http://en.wikipedia.org/wiki/Mercenary]雇佣兵[/url]。

雇佣兵是指参与武装冲突的人，他不是冲突方的国民或当事人，并且“本质上以谋取私利为动机参与敌对行动，事实上，由冲突一方或代表冲突一方承诺给予的物质补偿，远超过该方武装部队中相似军衔和职能的作战人员所承诺或获得的补偿”。');
INSERT INTO "tags" VALUES ('g1103','雇佣兵女主角','内容',45,'这些游戏中至少有一位女主角是（或曾经是）一名[url=http://en.wikipedia.org/wiki/Mercenary]雇佣兵[/url]。

雇佣兵是指参与武装冲突的人，他不是冲突方的国民或当事人，并且“本质上以谋取私利为动机参与敌对行动，事实上，由冲突一方或代表冲突一方承诺给予的物质补偿，远超过该方武装部队中相似军衔和职能的作战人员所承诺或获得的补偿”。');
INSERT INTO "tags" VALUES ('g1104','修女支援角色','内容',37,'游戏中的一位配角是[url=http://en.wikipedia.org/wiki/Nun]修女[/url]。');
INSERT INTO "tags" VALUES ('g1105','无背景音乐','技术',603,'这些视觉小说没有背景音乐，甚至可能没有任何声音。');
INSERT INTO "tags" VALUES ('g1106','声音和音乐','技术',0,'所有与听觉表现相关的标签都归入此元标签之下。

详情请参阅相关的[url=http://en.wikipedia.org/wiki/Game_music]维基百科[/url]文章。');
INSERT INTO "tags" VALUES ('g1107','故事','技术',0,'关于故事如何呈现给读者的标签收集于此。这个元标签与故事本身无关，而是关于用于呈现故事的方法和工具。');
INSERT INTO "tags" VALUES ('g1108','显示','tech',0,'这个元标签用于涵盖与游戏所使用的各种显示方式相关的标签。');
INSERT INTO "tags" VALUES ('g1111','贫穷的主角','cont',219,'本游戏的主角很穷。他（或她）要么为了谋生而工作，要么正遭受[url=http://en.wikipedia.org/wiki/Poverty]贫穷[/url]的困扰。');
INSERT INTO "tags" VALUES ('g1112','只有坏结局','tech',490,'这个游戏只有坏结局。游戏的类型可能各不相同，但当你到达故事结尾时，无论你如何尝试，都不会以幸福结局告终。
这个标签不适用于带有苦乐参半结局的视觉小说。');
INSERT INTO "tags" VALUES ('g1113','吸血鬼主角','cont',291,'视觉小说中的一位主角是[url=http://en.wikipedia.org/wiki/Vampire]吸血鬼[/url]。');
INSERT INTO "tags" VALUES ('g1114','双胞胎兄弟作为主角','cont',125,'这个游戏的主角是[url=http://en.wikipedia.org/wiki/Twins]双胞胎[/url]。');
INSERT INTO "tags" VALUES ('g1117','BDSM','ero',6406,'这个游戏包含一个或多个涉及[url=http://en.wikipedia.org/wiki/BDSM]BDSM[/url]的场景。

BDSM是两个或更多个体之间的一种角色扮演或生活方式选择，他们利用对疼痛和权力的体验来创造性张力、快感和释放。复合缩写BDSM源自以下术语：束缚与纪律（B&D, B/D, 或 BD）、支配与服从（D&s, D/s, 或 Ds）、施虐与受虐（S&M, S/M, 或 SM）。');
INSERT INTO "tags" VALUES ('g1118','贵族主角','cont',167,'这部视觉小说的一个或多个主角出身贵族家庭，是[url=http://en.wikipedia.org/wiki/Nobility]贵族[/url]的一员。');
INSERT INTO "tags" VALUES ('g1119','刺客主角','cont',96,'这个游戏的一位主角是（或曾经是）一名[url=http://en.wikipedia.org/wiki/Assassin]刺客[/url]。');
INSERT INTO "tags" VALUES ('g1120','法师主角','cont',216,'这些游戏至少有一位主角是法师。

法师是指使用或修炼源自超自然或神秘来源的魔法的人。');
INSERT INTO "tags" VALUES ('g1121','病娇主角','cont',711,'这个游戏中的一个或多个主角表现出[url=http://en.wikipedia.org/wiki/Yandere#Y]病娇[/url]行为。

病娇是一个日语术语，指某人最初对某个人非常关爱和温柔，之后其奉献变得具有破坏性，通常通过暴力表现出来。');
INSERT INTO "tags" VALUES ('g1122','含有游戏玩法的性爱场景','ero',155,'这个游戏中的性爱场景带有某种游戏玩法。

它可以是这些场景中大量选择的形式，有不同的路径和结果。或者它可能让玩家能够通过鼠标和键盘与这些场景中的参与者互动，比如触摸、拖放物品等等。');
INSERT INTO "tags" VALUES ('g1123','魔王主角','cont',42,'这个游戏的一位主角是魔王，即恶魔之王（或魔鬼之王等）。

他可能刚从被封印了几个世纪的状态中逃脱，目标是重新获得他以前的力量（并奴役上次阻挠他的人），最终决定统治世界……或者他可能是一个热爱小动物和大自然的魔王，憎恨人类因为人类污染自然，最终与一群人类生活在一起，看看他们是否真的那么坏。

请注意，这个标签仅适用于真正的魔王，而不适用于那些以魔王作为头衔或昵称的角色。该角色需要具备奇幻的、[url=http://en.wikipedia.org/wiki/Demonic]恶魔般[/url]的特性。');
INSERT INTO "tags" VALUES ('g1124','傲娇主角','cont',327,'这个游戏包含一个或多个表现出[url=http://en.wikipedia.org/wiki/Tsundere]傲娇[/url]行为的主角。

傲娇是一个日语的性格发展过程，描述一个人最初对另一个人冷淡甚至敌对，随着时间推移逐渐展现出温暖的一面。');
INSERT INTO "tags" VALUES ('g1125','反派主角','cont',250,'这个游戏中的一个或多个主角是[url=http://en.wikipedia.org/wiki/Villainous]反派[/url]，或者仅仅是故事中的"邪恶"角色。

一开始是坏的或后来变坏，然后再变好等等都不重要，只要反派的部分在故事中扮演重要角色即可。');
INSERT INTO "tags" VALUES ('g1126','按性格划分的主角','cont',0,'这个元标签用于收集与女主角性格相关的特质。');
INSERT INTO "tags" VALUES ('g1127','没有方向感的女主角','cont',31,'游戏中的一个（或多个）女主角没有方向感。');
INSERT INTO "tags" VALUES ('g1128','基于真实人物的主角','cont',109,'本游戏的主角描绘了一个来自现实世界的人。');
INSERT INTO "tags" VALUES ('g1129','神圣宝物','cont',42,'某种神圣的宝物（圣杯、圣剑等）在故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g1130','双持剑','cont',43,'有角色同时使用两把剑的游戏。');
INSERT INTO "tags" VALUES ('g1131','运动员主角','cont',143,'这些游戏至少有一位经常运动的主角，无论是业余还是职业。

详情请参阅相关的[url=http://en.wikipedia.org/wiki/Sportsperson]维基百科[/url]文章。');
INSERT INTO "tags" VALUES ('g1133','主角的阿姨作为女主角','cont',233,'这部视觉小说的女主角之一是主角的[url=http://en.wikipedia.org/wiki/Aunt]阿姨[/url]。');
INSERT INTO "tags" VALUES ('g1135','作家女主角','cont',113,'这个故事中的一位女主角是[url=http://en.wikipedia.org/wiki/Writer]作家[/url]，无论是小说、杂志文章还是其他什么。

也可用于撰写文章的报社记者。');
INSERT INTO "tags" VALUES ('g1136','狼人男主角','cont',140,'一位或多位男主角是[url=http://en.wikipedia.org/wiki/Werewolf]狼人[/url]。

狼人（lycanthrope）是一种神话或民间传说中的人类，能够有意地、被另一只狼人咬伤或受到诅咒后，变形成类狼的人形生物。');
INSERT INTO "tags" VALUES ('g1137','火绳枪战斗','cont',5,'这款游戏包含使用[url=http://en.wikipedia.org/wiki/Arquebus]火绳枪[/url]的战斗场景。');
INSERT INTO "tags" VALUES ('g1138','裸体围裙女主角','cont',831,'这款游戏包含一个或多个女主角只穿着[url=http://en.wikipedia.org/wiki/Apron]围裙[/url]而没有其他衣物的场景。');
INSERT INTO "tags" VALUES ('g1139','旗袍女主角','cont',175,'游戏中的一位或多位女主角穿着[url=http://en.wikipedia.org/wiki/Qipao]旗袍[/url]。

旗袍是一种贴身的（上海改良）中式女性连衣裙；男性版本是长衫。在普通话中被称为旗袍。');
INSERT INTO "tags" VALUES ('g1140','狼人主角','cont',52,'这款游戏的主角是[url=http://en.wikipedia.org/wiki/Werewolf]狼人[/url]。

狼人（lycanthrope）是一种神话或民间传说中的人类，能够有意地、被另一只狼人咬伤或受到诅咒后，变形成类狼的人形生物。');
INSERT INTO "tags" VALUES ('g1141','主角的上司作为女主角','cont',185,'这款游戏中至少有一位女主角是主角的[url=http://en.wikipedia.org/wiki/Boss]上司[/url]。主角直接或间接地听从那位女主角的命令。');
INSERT INTO "tags" VALUES ('g1143','服装开/关','ero',45,'在这些游戏中，玩家可以在大多数性爱场景中选择让角色穿着衣服或脱光衣服。这意味着这些场景的每个CG都有两种变体可供收集。

注意不要与[url=/g2422]裸体滤镜[/url]混淆，裸体滤镜是一个在任何时候移除角色立绘衣服的恶搞选项。');
INSERT INTO "tags" VALUES ('g1145','成人婴儿癖','ero',121,'包含角色进行[url=http://en.wikipedia.org/wiki/Paraphilic_infantilism]成人婴儿癖[/url]行为的场景。

成人婴儿癖是一种性癖好，涉及角色扮演回归到婴儿状态。行为可能包括用奶瓶喝奶或穿尿布。');
INSERT INTO "tags" VALUES ('g1146','现代美国','cont',468,'这款游戏的很大一部分发生在现代[url=http://en.wikipedia.org/wiki/United_States_of_America]美国[/url]。
注意：“现代”指的是20世纪末至今的一个未指定时间段。');
INSERT INTO "tags" VALUES ('g1148','塔防','tech',27,'这款游戏具有[url=http://en.wikipedia.org/wiki/Tower_defense]塔防[/url]游戏元素。这涉及在地图上放置单位和/或建筑物以击退一波波敌人。');
INSERT INTO "tags" VALUES ('g1149','兽耳主角','cont',184,'这款游戏的主角拥有[url=http://en.wikipedia.org/wiki/Kemonomimi#Animals]兽耳[/url]。

兽耳角色通常看起来像人类，只是多了类似动物的特征（如耳朵或尾巴）。');
INSERT INTO "tags" VALUES ('g1150','宗教男主角','cont',74,'这部视觉小说中的一位男主角是某种[url=http://en.wikipedia.org/wiki/Religion]宗教[/url]的虔诚信徒，并且经常谈论它。');
INSERT INTO "tags" VALUES ('g1151','科学家男主角','cont',83,'这款游戏中的一位男主角是[url=http://en.wikipedia.org/wiki/Scientist]科学家[/url]。他可能在科学领域工作，在大学、研究中心或科学实验室任职。');
INSERT INTO "tags" VALUES ('g1153','犬耳女主角','cont',144,'适用于具有狗耳朵或任何让人联想到狗耳朵作为标志性部位或外观的女主角的游戏，例如带有狗耳朵的发带或她的头发形状恰好与狗耳朵相似。

请不要与犬娘标签混淆；几乎每个犬娘都有犬耳，但并非每个犬耳角色都是犬娘……而且犬娘是“非人女主角”的子标签，因此不适合带有犬耳的人类女孩。');
INSERT INTO "tags" VALUES ('g1154','哲学','cont',439,'这款游戏包含[url=http://en.wikipedia.org/wiki/Philosophy]哲学[/url]主题和/或冗长的哲学讨论。

哲学是研究普遍和根本问题的学科，例如与存在、知识、价值观、理性、心灵和语言相关的问题。');
INSERT INTO "tags" VALUES ('g1155','设计故事','cont',115,'这些游戏围绕一群角色致力于[url=http://en.wikipedia.org/wiki/Design]设计[/url]某物展开，或者这种行为在故事中占据重要部分。

他们可能致力于设计（创作）同人漫画、游戏等，或者受雇于从事该领域的公司。

不要用于涉及音乐和食物相关项目的游戏，因为已经有这些标签。');
INSERT INTO "tags" VALUES ('g1156','推销员主角','cont',12,'这款游戏的主角是一位[url=http://www.urbandictionary.com/define.php?term=salesman]推销员[/url]。');
INSERT INTO "tags" VALUES ('g1157','以主角的姻亲姐妹为女主角','cont',142,'一个或多个女主角是主角的[url=http://en.wikipedia.org/wiki/Sister-in-law]姻亲姐妹[/url]。
Sister-in-law指的是主角妻子的姐妹，或主角兄弟的妻子。
在少数情况下，它也可以用来描述与兄弟姐妹结婚的人之间的关系，指主角配偶的兄弟姐妹的妻子。');
INSERT INTO "tags" VALUES ('g1158','以主角的女儿为女主角','cont',216,'这款游戏的一名女主角是主角的[url=http://en.wikipedia.org/wiki/Daughter]女儿[/url]。');
INSERT INTO "tags" VALUES ('g1159','以主角的有血缘关系的女儿为女主角','cont',157,'这款游戏的一名女主角是主角的有血缘关系的女儿。');
INSERT INTO "tags" VALUES ('g1160','以主角的无血缘关系的女儿为女主角','cont',66,'这款游戏的一名女主角是主角的无血缘关系的女儿。');
INSERT INTO "tags" VALUES ('g1162','外星人主角','cont',70,'这款游戏的主角具有[url=http://en.wikipedia.org/wiki/Extraterrestrial_life]地外[/url]起源。

地外生命被定义为并非起源于地球的生命。也被称为外星生命，或简称外星人，这些假设的生命形式范围从类似细菌的简单生物体到远比人类先进的智慧生物。');
INSERT INTO "tags" VALUES ('g1164','单一存档槽位','tech',103,'这些游戏只允许你进行一次[url=http://en.wikipedia.org/wiki/Game_save]存档[/url]。当你决定保存游戏进度时，必须覆盖现有的唯一存档，这使得再次访问游戏的早期部分和探索变得不可能。

允许你在允许创建不同用户档案的游戏上使用此标签。');
INSERT INTO "tags" VALUES ('g1165','包办婚姻','cont',257,'带有此标签的游戏包含涉及至少一个角色的婚姻由新婚夫妇以外的其他人安排的事件。

参见相关[url=http://en.wikipedia.org/wiki/Arranged_marriage]维基百科[/url]条目以获取更多信息。');
INSERT INTO "tags" VALUES ('g1166','浪人主角','cont',46,'游戏的主角是一名浪人。

在日本，浪人是指已从中学或高中毕业，但未能进入更高一级学校的学生，因此在校外学习以准备未来的入学。

[来自[url=http://en.wikipedia.org/wiki/R%C5%8Dnin_%28student%29]维基百科[/url]]

尽管该术语基于古代的[url=http://en.wikipedia.org/wiki/Samurai]武士[/url]，但不要将其用于以无主武士为特色的游戏。请在这些游戏上使用[url=http://vndb.org/g1180]武士主角[/url]。');
INSERT INTO "tags" VALUES ('g1167','半日本血统主角','cont',31,'主角是[url=http://en.wikipedia.org/wiki/Hafu]半日本血统[/url]。');
INSERT INTO "tags" VALUES ('g1168','半日本血统女主角','cont',386,'其中一名女主角是[url=http://en.wikipedia.org/wiki/Hafu]半日本血统[/url]。');
INSERT INTO "tags" VALUES ('g1170','蔷薇（Bara）','ero',555,'Bara（薔薇，“玫瑰”），也被称为和制英语“Mens'' Love”（メンズラブ）或ML，是日本术语，指一种以男性同性爱和欲望为主题的艺术和虚构媒体类型，通常由男同性恋者创作并面向男同性恋者。
Bara的视觉风格和情节可以多种多样，但通常以具有不同程度肌肉、体脂和体毛的男子气概男性为特色，类似于同志文化中的肌肉男或熊（熊）。 
西方评论者有时将Bara称为“yaoi”，但yaoi主要由女性创作并面向女性，其特点是理想化的美少年，符合异性恋规范模式：占主导地位的男性化攻方追求顺从的女性化受方。

更多信息请参见[url=http://en.wikipedia.org/wiki/Bara_%28genre%29]维基百科[/url]。');
INSERT INTO "tags" VALUES ('g1171','色情打屁股','ero',1365,'本视觉小说包含以[url=http://en.wikipedia.org/wiki/Erotic_spanking]情色打屁股[/url]为特色的场景。

情色打屁股  是指为了双方或其中一方的性唤起或性满足而拍打他人的行为。');
INSERT INTO "tags" VALUES ('g1172','射精预警器','技术',250,'带有此标签的成人游戏具有一个巧妙的功能，可提前向读者提示男性参与者将达到性高潮的时机（例如射精前10行）。');
INSERT INTO "tags" VALUES ('g1173','雨','内容',213,'本视觉小说有许多以[url=http://en.wikipedia.org/wiki/Rain]雨[/url]为特色的场景。

这可称为所谓的雨戏剧效果，即当有戏剧性或悲伤事件发生时，天空在这种情况下常常开始下雨，以增强场景的整体效果。');
INSERT INTO "tags" VALUES ('g1174','大会','内容',70,'本视觉小说情节的主要部分涉及角色参加某种[url=http://en.wikipedia.org/wiki/Convention_%28meeting%29]大会[/url]。

大会，在会议的意义上，是指个人在约定的地点和时间聚集，以讨论或参与某种共同兴趣。');
INSERT INTO "tags" VALUES ('g1175','社会崩溃','内容',56,'本视觉小说涉及[url=http://en.wikipedia.org/wiki/Societal_collapse]社会崩溃[/url]。

社会崩溃广泛包括以崩溃为特征的相当突然的社会失败（如玛雅文明），以及更为长期的、逐渐衰落的超级大国衰败（如西欧的罗马帝国和东亚的汉朝）。');
INSERT INTO "tags" VALUES ('g1176','按国籍和民族划分的女主角','内容',0,'这些是关于女主角或其父母出身的标签。

女主角的[url=http://en.wikipedia.org/wiki/Ethnicity]民族[/url]和[url=https://en.wikipedia.org/wiki/Nationality]国籍[/url]被用作故事中角色的刻画特征，而不带有任何如[url=http://en.wikipedia.org/wiki/Discrimination]歧视[/url]之类的负面含义；尽管它们几乎总是[url=http://en.wikipedia.org/wiki/Stereotypical]刻板印象[/url]的。

对于任何种族和民族组合的角色，请使用这些标签。也不要制作任何半日本血统或四分之一美国血统的标签。这些将在以后的新功能中涵盖。');
INSERT INTO "tags" VALUES ('g1177','按国籍和民族划分的主角','内容',0,'这些是关于主角或其父母出身的标签。

主角的[url=http://en.wikipedia.org/wiki/Ethnicity]民族[/url]和[url=https://en.wikipedia.org/wiki/Nationality]国籍[/url]被用作故事中角色的刻画特征，而不带有任何如[url=http://en.wikipedia.org/wiki/Discrimination]歧视[/url]之类的负面含义；尽管它们几乎总是[url=http://en.wikipedia.org/wiki/Stereotypical]刻板印象[/url]的。

对于任何种族和民族组合的角色，请使用这些标签。也不要制作任何半日本血统或四分之一美国血统的标签。这些将在以后的新功能中涵盖。');
INSERT INTO "tags" VALUES ('g1180','武士主角','内容',52,'本视觉小说的主角是或曾经是一名[url=http://en.wikipedia.org/wiki/Samurai]武士[/url]。

不要将此标签用于那些角色行事方式符合[url=http://en.wikipedia.org/wiki/Bushid%C5%8D]武士道[/url]但没有官方头衔的游戏。');
INSERT INTO "tags" VALUES ('g1181','仅限好结局','技术',1067,'本游戏仅包含好结局，没有坏结局或游戏结束。');
INSERT INTO "tags" VALUES ('g1182','大量坏结局','技术',728,'这些游戏有大量坏结局，几乎每个选择都可能让你走向它们。');
INSERT INTO "tags" VALUES ('g1183','樱花','内容',82,'这些游戏有许多以[url=http://en.wikipedia.org/wiki/Sakura]樱花，又称sakura.');
INSERT INTO "tags" VALUES ('g1184','高中生主角','内容',2845,'这些视觉小说的主角是一名[url=http://en.wikipedia.org/wiki/High_school]高中[/url]学生。');
INSERT INTO "tags" VALUES ('g1185','大学生主角','内容',1517,'主角是一名[url=http://en.wikipedia.org/wiki/University]大学[/url]学生');
