INSERT INTO "tags" VALUES ('g1188','变形','内容',283,'这些游戏包含能变形为其他形态的角色，包括动物、物体等。');
INSERT INTO "tags" VALUES ('g1189','兄弟/兄弟乱伦','色情',83,'这些游戏包含两个（或更多）兄弟之间的性爱场景。他们可能有血缘关系，也可能没有。');
INSERT INTO "tags" VALUES ('g1190','舔阴','色情',4489,'这些视觉小说至少有一个[url=http://en.wikipedia.org/wiki/Cunnilingus]舔阴[/url]（对女性生殖器的口部刺激）的场景。');
INSERT INTO "tags" VALUES ('g1191','女仆主角','内容',124,'主角是一位[url=http://en.wikipedia.org/wiki/Maid]女仆[/url]。

女佣，或当前用法中的家庭女佣或女仆，是指受雇从事家政服务的女性。');
INSERT INTO "tags" VALUES ('g1192','镰刀战斗','内容',18,'这些游戏有使用[url=http://en.wikipedia.org/wiki/Scythe]镰刀[/url]的战斗。');
INSERT INTO "tags" VALUES ('g1193','东方','cont',207,'这些游戏与[url=http://en.wikipedia.org/wiki/Touhou]东方[/url]系列游戏设定在同一个宇宙中，或包含来自这些系列的角色。');
INSERT INTO "tags" VALUES ('g1195','命运','cont',137,'[url=http://en.wikipedia.org/wiki/Destiny]命运（宿命）[/url]的概念在这些游戏中扮演重要角色。

命运是指一系列预定的事件进程。它可以被视为一种预定的未来，无论是整体而言还是针对个人。这是一个基于宇宙存在固定自然秩序这一信念的概念。

重点是使用此标签来标记那些特别提及命运（宿命）的游戏，而不是用在每一个''事件''看似不可避免的游戏上。

示例：不要用在某个身患绝症的角色在故事中某处去世的游戏上，即使说那是命运，只要剧本中没有提到这个概念本身。');
INSERT INTO "tags" VALUES ('g1196','白发女主角','cont',972,'这个标签用于至少有一位主要女主角拥有[url=http://en.wikipedia.org/wiki/Human_hair_color#Grey_and_white_hair]白色头发[/url]的游戏。');
INSERT INTO "tags" VALUES ('g1197','深色皮肤男主角','cont',849,'本游戏有一个肤色较深的[url=http://en.wikipedia.org/wiki/Skin_tone]男主角[/url]。

也可以用于极度晒黑的人物。');
INSERT INTO "tags" VALUES ('g1198','丑陋的主角','cont',146,'本游戏的主角是[url=http://en.wikipedia.org/wiki/Ugliness#Ugliness]丑陋[/url]的。

丑陋意味着在美学上不吸引人、令人反感或冒犯。与它的对立面美丽一样，丑陋涉及主观判断，并且至少部分地取决于"观者的眼光"。');
INSERT INTO "tags" VALUES ('g1199','角色堕落','cont',1065,'本游戏的主题之一是角色的[url=http://en.wikipedia.org/wiki/Corruption]堕落[/url]。这指角色性情从善良、符合社会期待转变为更邪恶、更阴暗。

这种角色转变应该在游戏中是显著事件。');
INSERT INTO "tags" VALUES ('g1200','居家型主角','cont',109,'这位主角擅长[url=http://en.wikipedia.org/wiki/Homemaking]家务[/url]，例如打扫和烹饪，并且会运用这些技能。无论他/她是出于需要而学习这些技能，还是实际上喜欢打理家务，只要他/她具备必要技能并且积极使用它们来操持家务，这都无关紧要。');
INSERT INTO "tags" VALUES ('g1201','宿舍管理员主角','cont',56,'本游戏的主角是某个[url=http://en.wikipedia.org/wiki/Dormitory]宿舍[/url]的管理员。');
INSERT INTO "tags" VALUES ('g1202','宿舍管理员女主角','cont',45,'其中一位女主角是某个[url=http://en.wikipedia.org/wiki/Dormitory]宿舍[/url]的管理员。');
INSERT INTO "tags" VALUES ('g1203','赏金猎人主角','cont',26,'主角是一名[url=http://en.wikipedia.org/wiki/Bounty_hunter]赏金猎人[/url]。

赏金猎人为金钱奖励（赏金）追捕逃犯。');
INSERT INTO "tags" VALUES ('g1204','救赎','cont',82,'[url=http://en.wikipedia.org/wiki/Redemption_%28theology%29]救赎[/url]的主题在整体故事中具有某种程度的显著作用。 

救赎是一个宗教概念，指对过去的罪孽或过失的宽恕或赦免，并通常通过牺牲来保护免受永恒的或暂时的诅咒。');
INSERT INTO "tags" VALUES ('g1205','文学改编','tech',885,'本游戏是[url=http://en.wikipedia.org/wiki/Literary_adaptation]文学改编[/url]作品，其故事基于一本实际存在的书。

不要与[url=http://vndb.org/g1056]同人小说[/url]混淆，同人小说基本上是原创作品中不存在的支线故事。');
INSERT INTO "tags" VALUES ('g1206','过去的东京','cont',35,'本游戏设定在过去的[url=http://en.wikipedia.org/wiki/Tokyo]东京[/url]，或至少其故事有相当一部分发生在过去的东京，或发生在东京的旧称[url=http://en.wikipedia.org/wiki/Edo]江户[/url]。');
INSERT INTO "tags" VALUES ('g1207','过去的地球','cont',1407,'这些标签用于设定在地球过去的游戏。');
INSERT INTO "tags" VALUES ('g1208','过去的日本','cont',661,'这些游戏设定在过去的[url=http://en.wikipedia.org/wiki/Japan]日本[/url]。');
INSERT INTO "tags" VALUES ('g1209','律师男主角','cont',55,'本游戏中的男主角是一名[url=http://en.wikipedia.org/wiki/Lawyer]律师[/url]。');
INSERT INTO "tags" VALUES ('g1210','白手起家','cont',52,'这个故事具有[url=http://en.wikipedia.org/wiki/Rags_to_riches]白手起家[/url]文学原型元素。

"白手起家"是指一个人从贫穷走向富裕，或有时从默默无闻走向成名的任何情况。');
INSERT INTO "tags" VALUES ('g1211','学生会成员女主角','cont',595,'女主角是[url=http://en.wikipedia.org/wiki/Student_government]学生政府[/url]的一名成员。

学生政府是存在于许多学院、大学并已开始出现在一些高中学生组织。在高等教育中，学生会通常在校内拥有自己的建筑，专门用于学生群体的社交和组织活动。');
INSERT INTO "tags" VALUES ('g1212','学生社团成员女主角','cont',494,'女主角是[url=http://en.wikipedia.org/wiki/Student_club]学生社团[/url]的一名成员。

学校社团是以学生为基础的学校组织，由经行政批准的组织构成，其职能多种多样，根据各个俱乐部各自的具体目的而有所不同。');
INSERT INTO "tags" VALUES ('g1213','学生社团成员主角','cont',198,'主角是[url=http://en.wikipedia.org/wiki/Student_club]学生社团[/url]的一名成员。

学校社团是以学生为基础的学校组织，由经行政批准的组织构成，其职能多种多样，根据各个俱乐部各自的具体目的而有所不同。');
INSERT INTO "tags" VALUES ('g1214','学生会成员主角','cont',163,'主角是[url=http://en.wikipedia.org/wiki/Student_government]学生政府[/url]的一名成员。

学生政府是存在于许多学院、大学并已开始出现在一些高中学生组织。在高等教育中，学生会通常在校内拥有自己的建筑，专门用于学生群体的社交和组织活动。');
INSERT INTO "tags" VALUES ('g1215','学校体育俱乐部','cont',490,'与学校相关的[url=http://en.wikipedia.org/wiki/Sports_club]体育俱乐部[/url]在故事中扮演重要角色。

学校体育俱乐部是一个经行政批准、以学生为基础的学校组织，专注于某一选定的运动项目。');
INSERT INTO "tags" VALUES ('g1216','物体插入','ero',1248,'这些游戏至少包含一个场景，其中将性玩具或物体（身体部位除外）插入孔口。');
INSERT INTO "tags" VALUES ('g1217','过去的中国','cont',134,'这些游戏发生在过去的[url=http://en.wikipedia.org/wiki/China]中国[/url]。');
INSERT INTO "tags" VALUES ('g1218','三国','cont',36,'这些游戏设定在中国的[url=http://en.wikipedia.org/wiki/Three_Kingdoms]三国时期[/url]，或基于《三国演义》。');
INSERT INTO "tags" VALUES ('g1222','睾丸吸吮','ero',403,'游戏包含以[url=http://en.wikipedia.org/wiki/Tea_bag_(sexual_act)]睾丸吸吮[/url]为特色的性爱场景，也称为茶包行为。

“茶包”是一个俚语，指男性将阴囊放入性伴侣口中的行为。当以重复进出动作进行时，这种做法类似于将茶包浸入茶杯中。

[url=https://s2.vndb.org/sf/38/130938.jpg]NSFW示例[/url]
[url=https://s2.vndb.org/sf/37/130937.jpg]NSFW群交示例1[/url]
[url=https://s2.vndb.org/sf/39/130939.jpg]NSFW群交示例2[/url]');
INSERT INTO "tags" VALUES ('g1225','女儿型女主角','cont',34,'这些游戏至少有一位女儿型女主角。

这些角色与主角没有关系，比如血亲女儿或继女，但她们坚持称呼主角为"父亲"、"爸爸"、"妈妈"等，并表现得像他/她的女儿。

对于真正的父/母-女关系，请使用女儿女主角标签。');
INSERT INTO "tags" VALUES ('g1226','可见内裤的主角','cont',9,'本游戏有相当多的场景可以看到主角的内衣，不包括性爱场景。');
INSERT INTO "tags" VALUES ('g1228','可命名女主角','tech',259,'这些游戏有一位或多位名字可以更改的女主角。');
INSERT INTO "tags" VALUES ('g1229','穿和服的女主角','cont',523,'这些视觉小说有一位或多位大部分时间穿着[url=http://en.wikipedia.org/wiki/Kimono]和服[/url]的女主角。');
INSERT INTO "tags" VALUES ('g1230','Twitter','tech',29,'带有此标签的游戏包含一项功能，可以直接从游戏内向[url=http://en.wikipedia.org/wiki/Twitter]Twitter[/url]发送数据和评论。');
INSERT INTO "tags" VALUES ('g1231','基于真实事件','cont',124,'在这些视觉小说中，角色可能是虚构的，但情节基于真实事件。');
INSERT INTO "tags" VALUES ('g1233','扑克','tech',33,'本游戏以[url=http://en.wikipedia.org/wiki/Poker]扑克[/url]为特色。

扑克是一类纸牌游戏，它们共享投注规则，并且通常（但并非总是）共享牌型排名。扑克游戏的不同之处在于发牌方式、牌型如何组成、摊牌时高牌还是低牌赢取底池（在某些游戏中，底池在高牌和低牌之间平分）、下注额度限制以及允许多少轮下注。');
INSERT INTO "tags" VALUES ('g1234','可解锁选项','tech',693,'游戏有一个或多个在满足特定条件后解锁的选项。锁定选项可能可见但不可选择，也可能凭空出现。');
INSERT INTO "tags" VALUES ('g1235','欧洲','cont',477,'这个游戏的大部分或全部故事发生在[url=http://en.wikipedia.org/wiki/Europe]欧洲[/url].

欧洲是世界七大洲之一。作为欧亚大陆最西端的半岛，欧洲通常以乌拉尔山脉、乌拉尔河、里海、高加索地区（边界的具体划分）和东南部的黑海为界，与东面的亚洲分隔开来。

欧洲北临北冰洋及其他水域，西临大西洋，南临地中海，东南临黑海及与之相连的水道。');
INSERT INTO "tags" VALUES ('g1236','记忆改变','内容',296,'具有重要情节意义的角色通过非自然的方式修改、丢失和获得记忆。例如：在这种情况下，从楼梯上摔下来并遭受脑外伤可被视为自然方式，而摔下楼梯进入另一个维度并传递/获得跨维度记忆则不是。

记忆不一定需要是真实的，除了自然原因之外，唯一的要求是在记忆修改事件（无论是通过现实扭曲、机器、魔力还是其他方式）之后，“新”的记忆集与“旧”的记忆集不同，即使差别很小。

在某些情况下可能有时会与失忆症重叠。');
INSERT INTO "tags" VALUES ('g1237','拳击','内容',18,'这款游戏以[url=http://en.wikipedia.org/wiki/Boxing]拳击[/url]为特色。

拳击是一项格斗运动，两名参赛者用拳头相互搏击以进行比赛。

拳击比赛通常由一名裁判监督，比赛由一系列称为回合的1-3分钟间隔组成，拳手通常体重相近。

获胜方式有四种：如果对手被击倒且在裁判数到十秒前无法站起来（击倒，即KO），或者对手被认为伤势过重无法继续比赛（技术性击倒，即TKO），或者对手因违反规则被取消比赛资格，或者在约定的回合数前比赛没有停止，则胜者由裁判判定或裁判员的计分卡决定。');
INSERT INTO "tags" VALUES ('g1238','主题后宫结局','技术',93,'这款游戏的后宫仅包含符合特定主题或癖好的英雄/女主角。

示例：全伪娘后宫、全傲娇后宫、全女仆后宫。');
INSERT INTO "tags" VALUES ('g1239','幽灵英雄','cont',128,'本游戏中的英雄是一名[url=http://en.wikipedia.org/wiki/Ghost]幽灵[/url]。

在传统信仰中，幽灵是已故的人类或动物的灵魂或精神，能以可见形式或其他表现形式出现在生者面前。对幽灵显现的描述多种多样：显形方式可以从隐形存在到半透明或缥缈的形状，再到逼真、栩栩如生的幻象。');
INSERT INTO "tags" VALUES ('g1241','女王女主角','cont',162,'本游戏中的一位女主角是[url=http://en.wikipedia.org/wiki/Queen]女王[/url]。

女王（queen regnant）是拥有与男性国王同等权力的女性君主。

王后（queen consort）是在位国王的妻子，不享有同等权力。

太后（queen dowager）是丈夫已故的前王后

而太后（queen mother）要么是王太后（queen dowager），要么是已退位的女王（queen regnant），且其儿子或女儿已成为君主。');
INSERT INTO "tags" VALUES ('g1243','患有包茎的主角','ero',56,'带有此标签的游戏主角患有称为[url=http://en.wikipedia.org/wiki/Phimosis]包茎[/url]的病症，即其（或她的）阴茎包皮无法完全从龟头上退缩。');
INSERT INTO "tags" VALUES ('g1244','画家主角','cont',79,'主角是一位以[url=http://en.wikipedia.org/wiki/Painting]绘画[/url]为媒介的富有创造力的艺术家。');
INSERT INTO "tags" VALUES ('g1245','女性穿戴假阴茎肛交','ero',402,'本游戏包含涉及[url=http://en.wikipedia.org/wiki/Pegging_%28sexual_practice%29]女性穿戴假阴茎肛交[/url]的场景。

女性穿戴假阴茎肛交是一种性行为，即女性使用穿戴式假阴茎插入男性肛门。');
INSERT INTO "tags" VALUES ('g1246','内置百科全书','tech',1030,'本游戏内置百科全书/词汇表/提示，可通过游戏内菜单访问。通常用于解释游戏内的术语。最著名的例子（Umineko, Fate/Stay Night）可以包含图片（即角色数据）和其他附加信息。');
INSERT INTO "tags" VALUES ('g1247','性别转换性爱','ero',207,'此标签适用于那些角色以非原始性别进行性交场景的游戏。

这通常发生在角色通过魔法、高科技或普通医疗手段从男性转变为女性，或反之。若要应用该标签，转变必须是完全的。');
INSERT INTO "tags" VALUES ('g1248','Vocaloid','cont',50,'这些游戏的角色来自[url=http://en.wikipedia.org/wiki/Vocaloid]Vocaloid[/url]软件系列。');
INSERT INTO "tags" VALUES ('g1249','一名女性和多名男性之间的自愿群体性行为','色情',331,'本视觉小说包含群交场景，即多个男性伴侣与一名女性发生性关系。

女性和男性参与者都必须自愿，尽管享受这种情况及其结果并不是必须的。因过度强奸、催眠、春药等导致的人格变化（例如变成自愿的性奴隶）不计算在内。

为便于数据库检索，该标签使用二元的性别理解，其中“Male”指顺性别男性，即出生时被指定为男性且认同为男性的人。“Female”指顺性别女性，即出生时被指定为女性且认同为女性的人。');
INSERT INTO "tags" VALUES ('g1250','作为女主角的主角对手','cont',27,'该游戏有一名或多名女主角与主角竞争或对抗。这可以采取竞赛、游戏或争论的形式。

这不应与 [url=/g275]作为女主角的主角对手[/url] 标签混淆，因为对手关系指的是长期持续的竞争关系，而对手可以是仅见过一次的人。');
INSERT INTO "tags" VALUES ('g1251','多于七个结局','tech',1874,'该游戏拥有比通常更多的[url=http://en.wikipedia.org/wiki/Multiple_endings#Video_games]结局[/url]，至少有八个甚至更多。

所有包含某种故事内容的结局都计入此数量。仅显示“你死了”或“游戏结束”而没有相关故事的简单画面不计入。');
INSERT INTO "tags" VALUES ('g1252','背叛','cont',587,'该游戏包含一个[url=http://en.wikipedia.org/wiki/Betrayal]背叛[/url]的故事。

背叛是指打破或违反推定契约、信任或信赖，从而在个人之间、组织之间或个人与组织之间的关系中产生道德和心理冲突。

通常，背叛是支持敌对团体的行为，或者是一方完全打破先前商定或默认的规范。背叛他人的人通常被称为叛徒或背信者。');
INSERT INTO "tags" VALUES ('g1255','作为女主角的风纪委员会委员','cont',89,'女主角是风纪委员会的成员。

风纪委员会是许多学院、大学或高中里的一种学生组织，主要目的是在学生中执行校规，如宵禁。');
INSERT INTO "tags" VALUES ('g1256','作为女主角的风纪委员会委员长','cont',51,'女主角是风纪委员会的委员长。

风纪委员会是许多学院、大学或高中里的一种学生组织，主要目的是在学生中执行校规，如宵禁。');
INSERT INTO "tags" VALUES ('g1257','作为女主角的主角未婚妻','cont',123,'一名或多名女主角是主角的未婚妻。

他们是否在故事结尾结婚并不重要，这是关于他们之间的关系。');
INSERT INTO "tags" VALUES ('g1258','无对话历史','tech',737,'在本视觉小说中没有回顾功能。你无法阅读任何之前的文本。');
INSERT INTO "tags" VALUES ('g1259','检查点','tech',181,'在本视觉小说中，你只能在特定地点保存。例如，仅在重要事件之前和/或之后，战斗之前或之后，仅在特定位置，等等。');
INSERT INTO "tags" VALUES ('g1260','与家庭成员恋爱','cont',827,'该游戏包含主角与一个家庭的多个成员恋爱的情节。

这可能发生在主角必须在两个恋爱对象之间做出选择时，而这两个人可能是兄弟姐妹，或是父母与子女。');
INSERT INTO "tags" VALUES ('g1261','月亮','cont',38,'故事发生在[url=http://en.wikipedia.org/wiki/Moon]月球[/url]上。

月球是地球唯一的天然卫星，也是太阳系中第五大的卫星。');
INSERT INTO "tags" VALUES ('g1262','分娩','cont',482,'该游戏包含角色[url=http://en.wikipedia.org/wiki/Birth]分娩[/url]的场景。

分娩是孕育或产出后代的行为或过程。后代由母亲生出。人类出生时间被定义为胎儿从母亲子宫出来进入世界的时刻。');
INSERT INTO "tags" VALUES ('g1263','膨胀','ero',610,'该游戏包含在性行为中角色腹部膨胀的场景。这可能是由于向体内注入过量外来物质（液体、气体、怪物卵等），或通过任何孔洞插入超大物体（巨大的阴茎、大量触手或粘液等）所导致。这可以是双方自愿的，也可以是强迫的。

如果导致腹部变形，可以与[url=/g1559]巨大插入[/url]一起使用。');
INSERT INTO "tags" VALUES ('g1264','双持匕首','cont',20,'游戏包含角色同时使用两把匕首。');
INSERT INTO "tags" VALUES ('g1265','牺牲','cont',266,'该游戏包含角色（可能是主角、女主角或其他人）牺牲自己以拯救他人或世界的情节。');
INSERT INTO "tags" VALUES ('g1266','女演员女主角','cont',133,'该游戏中的一名或多名女主角是[url=http://en.wikipedia.org/wiki/Actor]女演员[/url]。

女演员是在戏剧制作中表演的人，并以此身份在电影、电视、戏剧或广播中工作。古希腊语中“演员”一词的字面意思是“解释者”，从这个意义上说，演员是诠释戏剧角色的人。');
INSERT INTO "tags" VALUES ('g1267','Q版立绘','tech',130,'游戏时常（如果不是总是）采用[url=http://en.wikipedia.org/wiki/Sprite_%28computer_graphics%29]角色精灵图[/url]，以[url=http://en.wikipedia.org/wiki/Super_deformed]Q版[/url]风格绘制。

本标签仅适用于Q版精灵图，[url=http://s.vndb.org/sf/35/20535.jpg]如这个示例[/url]。不应与偶尔以这种方式展现角色的CG混淆，[url=http://s.vndb.org/sf/93/16593.jpg]如这个示例[/url]。');
INSERT INTO "tags" VALUES ('g1268','机器人英雄','cont',101,'这些游戏至少有一位英雄是[url=http://en.wikipedia.org/wiki/Robot]机器人[/url] - 由AI控制的人造身体。

与赛博格英雄形成对比，后者拥有由人脑控制的（部分）人造身体。');
INSERT INTO "tags" VALUES ('g1269','兄控女主角','cont',848,'至少有一位女主角是兄控，这种人总是对自己的哥哥（通常是主角）充满热情，愿意为他做任何事。

注意：本标签用于描述女主角的性格。如需实际的妹妹关系，请使用妹妹女主角标签。');
INSERT INTO "tags" VALUES ('g1270','外星人英雄','cont',93,'本游戏的一位或多位英雄具有[url=http://en.wikipedia.org/wiki/Extraterrestrial_life]外星[/url]起源。

外星生命被定义为并非起源于地球的生命。也被称为外星生命，或简称外星人，这些假想生命形式从类似细菌的简单生物到远比人类先进的智慧生物不等。');
INSERT INTO "tags" VALUES ('g1273','阳刚主角','cont',20,'一位充分具备传统男性特征（如阳刚、力量和坚韧）的主角，尤其是在性吸引力方面。');
INSERT INTO "tags" VALUES ('g1274','性暗示','cont',487,'这款游戏包含暗示性内容，这意味着它有一个或多个性爱场景，这些场景不会以图形方式呈现或详细描述，但仍然存在。或者其场景明显设计为性暗示，但以笑话或规避成人评级的方式伪装起来。

这可能以图形方式出现，例如角色在性行为后穿衣。或者剧本可以随后暗示性行为。此类场景的示例可在[url=http://s.vndb.org/sf/26/62526.jpg]Ever17[/url]、[url=http://s.vndb.org/sf/25/62525.jpg]Ar Tonelico[/url]等中找到。');
INSERT INTO "tags" VALUES ('g1275','多个开场动画','tech',102,'这款游戏除了最开头的第一个开场动画外，还有多个开场动画，通常在游戏进入故事新阶段时出现，有时也在玩家开始新解锁的路线时出现。');
INSERT INTO "tags" VALUES ('g1276','问答游戏','tech',300,'这些游戏包含一些[url=http://en.wikipedia.org/wiki/Quiz]问答[/url]元素。

在问答游戏中，玩家会被问一个问题，必须选择正确答案，否则将受到惩罚。');
INSERT INTO "tags" VALUES ('g1277','近亲女主角','cont',41,'女主角的父母在基因上彼此密切相关。');
INSERT INTO "tags" VALUES ('g1278','环境保护主义','cont',26,'这些游戏以环境保护和改善环境的问题为主题。

环境保护主义是一种广泛的哲学和社会运动，关注环境保护和环境健康改善，特别是这种健康衡量标准试图纳入非人类要素的关切。

更多详情请参阅相关的[url=http://en.wikipedia.org/wiki/Environmentalism]维基百科[/url]。');
INSERT INTO "tags" VALUES ('g1279','吞噬','ero',150,'这款游戏包含某人被活活吃掉的场景。

[url=http://en.wikipedia.org/wiki/Vorarephilia]吞食癖[/url]是一种性癖好和性偏离，性唤起来自被吃掉、吃掉他人、观察这一过程或一般进食过程的想法。幻想通常涉及受害者被活吞，可能包含也可能不包含消化。');
INSERT INTO "tags" VALUES ('g1280','纯文字性内容','ero',315,'这些视觉小说的部分或全部色情内容仅以文字呈现，不显示任何露骨图形。');
INSERT INTO "tags" VALUES ('g1281','多个女性的群体性行为','ero',361,'这部视觉小说包含群体性爱场景，其中多个女性伴侣彼此发生性关系。

为了数据库的目的，该标签使用二元的性别理解，“女性”指顺性别女性，即出生时被指定为女性并认同为女性的人。');
INSERT INTO "tags" VALUES ('g1282','傲娇主角','cont',115,'本游戏的主人公表现出[url=http://en.wikipedia.org/wiki/Tsundere]傲娇[/url]行为。

傲娇是一种日本角色发展过程，描述了一个人最初对另一个人冷淡甚至敌对，但随着时间的推移逐渐展现出温暖一面的角色描写手法。');
INSERT INTO "tags" VALUES ('g1283','偷窥','色情',1092,'游戏中有相当多的场景中偷窥起着重要作用，例如偷看女主角换衣服、偷看别人做爱等。请仅将其用于性偷窥。

偷窥是指对窥视他人进行亲密行为（如脱衣、性活动或其他通常被视为私人性质的活动）的性兴趣或行为。');
INSERT INTO "tags" VALUES ('g1284','关系图','tech',256,'These games have some sort of in-game chart, graph, or other system which displays how the characters relate to you. Examples: http://yare-yare.com/sakurasakura/seesawtohru.jpg or http://s.vndb.org/sf/84/5084.jpg');
INSERT INTO "tags" VALUES ('g1286','军校','cont',26,'游戏中的很大一部分场景发生在[url=http://en.wikipedia.org/wiki/Military_academy]军校[/url]。');
INSERT INTO "tags" VALUES ('g1288','变态朋友','cont',158,'其中一个配角过于沉迷于性事。通常这恰好是主角最好的朋友，或者至少是亲密的朋友。');
INSERT INTO "tags" VALUES ('g1289','车中性爱','ero',600,'这部视觉小说中的一些性爱场景发生在交通工具中，如汽车、飞机、船、火车等。');
INSERT INTO "tags" VALUES ('g1290','麻将作为故事元素','cont',33,'游戏中的[url=http://en.wikipedia.org/wiki/Mahjong]麻将[/url]以某种内容出现在故事中，但它并不是一个真正可玩的小游戏，只是故事元素或情节装置。

如果麻将作为可玩游戏出现在视觉小说中，请改用[url=http://vndb.org/g372]麻将作为游戏元素[/url]。');
INSERT INTO "tags" VALUES ('g1292','灌肠','ero',767,'该游戏包含涉及使用[url=http://en.wikipedia.org/wiki/Enema]灌肠剂[/url]的性爱场面。

灌肠是一种通过肛门将液体引入直肠和结肠的程序。');
INSERT INTO "tags" VALUES ('g1293','穿衣女性与裸体女性','ero',18,'包含一些女性穿着衣服而另一些则裸体（或至少穿得更少）的女同性恋性爱场面。可适用于BSDM场景以及普通性爱。

请参阅相关的[url=http://en.wikipedia.org/wiki/CFNM]维基百科[/url]文章以获取详细信息。');
INSERT INTO "tags" VALUES ('g1294','管家主角','cont',149,'游戏中的一位主角是[url=http://en.wikipedia.org/wiki/Butler]管家[/url]或其他家庭仆人。

管家是大家庭中的仆人。在大宅中，家庭有时会分为多个部门，由管家负责餐厅、酒窖和食品储藏室。有些管家还负责整个客厅楼层，而管家们则负责整个房子及其外观。');
INSERT INTO "tags" VALUES ('g1295','乳头插入','ero',304,'这些游戏至少包含一个场景，其中有物体（物品或身体部位）被插入乳头。');
INSERT INTO "tags" VALUES ('g1296','双胞胎乱伦','ero',205,'这些游戏包含双胞胎（或三胞胎或更多胞胎）之间的性爱场景。

请参阅相关的[url=http://en.wikipedia.org/wiki/Incest_between_twins]维基百科[/url]文章以获取更多信息。');
INSERT INTO "tags" VALUES ('g1297','后入式','ero',5574,'[url=http://en.wikipedia.org/wiki/Doggy_style]后入式[/url]或狗狗式是一种性交方式，通常涉及接受方四肢着地蹲伏，而插入方从后面插入阴道或肛门，或进行其他性行为。');
INSERT INTO "tags" VALUES ('g1299','虚构的现代日本岛屿','cont',88,'这个故事发生在当代日本海岸附近的一个虚构岛屿上。
注意："现代"指的是从20世纪末到今天的未指明的时间段。');
INSERT INTO "tags" VALUES ('g1300','与昆虫性交','ero',146,'带有此标签的视觉小说包含涉及昆虫或类昆虫怪物的性爱场景。

[URL=https://en.wikipedia.org/wiki/Insect]昆虫[/URL]是指一类具有几丁质外骨骼、三部分身体（头、胸和腹部）、三对关节腿、复眼和一对触角的无脊椎动物。

[url=http://en.wikipedia.org/wiki/Formicophilia]嗜蚁癖[/url]是一种动物恋，指的是对昆虫（如蚂蚁）在身上爬行或啃咬的性兴趣。');
INSERT INTO "tags" VALUES ('g1305','狼人女主角','cont',71,'一位或多位女主角是[url=http://en.wikipedia.org/wiki/Werewolf]狼人[/url]。

狼人，也称为变狼狂，是神话或民间传说中的人类，能够变形为类人狼形生物，要么是故意为之，要么是被另一个狼人咬伤，要么是受到诅咒之后。');
INSERT INTO "tags" VALUES ('g1306','主角的前任作为女主角','cont',186,'一位或多位女主角曾与主角有过恋爱关系，但现已分手、离婚和/或疏远。');
INSERT INTO "tags" VALUES ('g1307','身体书写','ero',628,'一种性支配形式（属于BDSM的一部分），通常与性羞辱或性虐待相关。');
INSERT INTO "tags" VALUES ('g1308','孤儿主角','cont',152,'本游戏中的一名或多名主角是[url=http://en.wikipedia.org/wiki/Orphan]孤儿[/url].

孤儿是指永久失去父母或被父母遗弃的儿童。在通常用法中，只有失去双亲的儿童（或幼小动物）才被称为孤儿。然而，成年人也可以被称为孤儿，或“成年孤儿”。');
INSERT INTO "tags" VALUES ('g1309','梦','内容',729,'[url=http://en.wikipedia.org/wiki/Dream]梦[/url]在本游戏中扮演重要角色。');
INSERT INTO "tags" VALUES ('g1311','拥有超能力一面的主角','内容',40,'本游戏的主角拥有一个比其平时人格强大得多的第二人格。

有时这表现为一个古老而邪恶的一面，最终以某种方式与主角结盟。');
INSERT INTO "tags" VALUES ('g1312','大学生女主角','内容',784,'至少有一位女主角是[url=http://en.wikipedia.org/wiki/University]大学[/url]生。');
INSERT INTO "tags" VALUES ('g1313','反向NTR','成人',125,'本视觉小说包含以反向NTR为主题的场景。与[url=/g513]NTR[/url]不同，本作的焦点不是对嫉妒的恋物癖，而是对诱惑及随之而来的关系破坏的恋物癖，同时将新形成的性关系抬高到基于感情的前一段关系之上。

一款游戏要归类为反向NTR，必须满足以下条件：

1. 主角被某人通过诱惑、胁迫、勒索、直接强奸或其他手段，从其所爱之人身边夺走。例如，已婚的男性主角可能会在游戏过程中遇到另一个女人，她引诱他，并使他离开妻子。

2. 主角的所爱之人几乎总会发现情况，并因无法改变任何事而产生的嫉妒和无力感而痛苦。夺取主角的人和/或主角可能会通过私下或公开羞辱失败的一方来火上浇油。

3. 如果主角与他人发生性关系时，并未体验到与背叛禁忌及可能破坏既有关系相关的下流快感，则该特征[b]不[/b]适用。换句话说，主角与所爱之人之间已有的联系对于反向NTR的性癖非常重要。

4. 偷情行为必须发生在主角正处于一段现有关系中时。主角过去关系的场景不计入反向NTR。

游戏通常从主角的视角描绘，他/她被引诱而抛弃所爱之人， 然而，出于剧情需要，游戏可能会在多个视角之间切换，并从失败的一方视角描述事件。');
INSERT INTO "tags" VALUES ('g1314','妄想','内容',186,'本游戏的剧情要点涉及[url=http://en.wikipedia.org/wiki/Delusion]妄想[/url]。

妄想是一种即使有强大的证据，仍被绝对坚信的错误信念。与幻觉不同，妄想总是病理性的（由疾病或疾病过程引起）。作为一种病理现象，它区别于基于错误或不完整信息、教条、愚蠢、记忆不佳、错觉或其他感知影响所产生的信念。');
INSERT INTO "tags" VALUES ('g1315','凉宫春日','内容',58,'这些游戏的角色来自[url=http://en.wikipedia.org/wiki/Haruhi_Suzumiya]凉宫春日[/url]的世界。');
INSERT INTO "tags" VALUES ('g1316','腋交','成人',337,'这些游戏至少包含一次腋交场景。这是一种非插入式性行为，将阴茎插入一个人的[url=http://en.wikipedia.org/wiki/Axilla]腋窝[/url]。');
INSERT INTO "tags" VALUES ('g1318','无血缘关系的父女乱伦','成人',117,'这些游戏包含无血缘关系的父女之间的性爱场景。');
INSERT INTO "tags" VALUES ('g1319','黑塔利亚','内容',55,'这些游戏的角色来自[url=http://en.wikipedia.org/wiki/Axis_Powers_Hetalia]黑塔利亚[/url]系列。');
INSERT INTO "tags" VALUES ('g1320','乡村','内容',579,'带有此标签的游戏设定在低人口密度区域。

[url=http://en.wikipedia.org/wiki/Rural]乡村地区[/url]是指未被城市化的土地区域，尽管描述大面积区域时，会包括乡村城镇和较小的城市。其人口密度较低，通常大部分土地用于农业，并且空气和水污染可能比城市地区少。该词对荒野地区包含的程度不一；在大多数语境下，非常大的荒野地区不太可能被该词描述。');
INSERT INTO "tags" VALUES ('g1321','都市圈','内容',125,'游戏的很大一部分设定在都市圈。

更多信息：[url=http://en.wikipedia.org/wiki/Metropolitan_area]维基百科[/url]');
INSERT INTO "tags" VALUES ('g1323','轮奸','成人',1171,'本游戏包含一个或多个轮奸场景。

群交是一种情况，其中一个人与多人进行性交和其他性行为，可以是轮流进行或同时进行。当此人未同意此类行为时，则称为轮奸或群体强奸。');
INSERT INTO "tags" VALUES ('g1324','女性射液','ero',2009,'本游戏包含一个或多个女性射液场景。

[url=http://en.wikipedia.org/wiki/Female_ejaculation]女性射液[/url]是指人类女性在性高潮期间或之前，从尿道旁腺通过尿道及周围排出明显量透明液体的现象。');
INSERT INTO "tags" VALUES ('g1325','万圣节','cont',399,'故事至少部分围绕[url=http://en.wikipedia.org/wiki/Halloween]万圣节[/url]这一节日展开。');
INSERT INTO "tags" VALUES ('g1326','小学','cont',59,'游戏的某些部分发生在[url=http://en.wikipedia.org/wiki/Elementary_school]小学[/url]。');
INSERT INTO "tags" VALUES ('g1327','小学生女主角','cont',141,'至少有一位女主角是[url=http://en.wikipedia.org/wiki/Elementary_school]小学[/url]学生。');
INSERT INTO "tags" VALUES ('g1328','多男群交','ero',254,'本视觉小说包含群交场景，多名男性伴侣互相发生性行为。

就本数据库而言，该标签采用二元性别理解，\"男性\"指顺性别男性，即出生时被指定为男性且认同为男性的人。');
INSERT INTO "tags" VALUES ('g1329','搭讪','ero',57,'寻找约会对象是本游戏故事的一个重要主题。

[url=http://en.wikipedia.org/wiki/Nanpa]搭讪[/url]（女孩猎寻）在日本文化中是一种流行于青少年及二三十岁人群的调情与诱惑方式。当日本女性以类似搭讪的方式追求男性时，称为gyakunan（男友猎寻）。

在实际视觉小说术语中，这通常意味着你在城市中游荡，随机遇到女孩（或男孩），尝试搭话，如果成功，最终以性交结束。');
INSERT INTO "tags" VALUES ('g1330','身体穿孔','cont',563,'本游戏中的角色拥有穿孔饰品，或在故事进程中获得新的穿孔。

[url=http://en.wikipedia.org/wiki/Body_piercing]身体穿孔[/url]是一种身体改造形式，即在人体某部位穿刺或切割。');
INSERT INTO "tags" VALUES ('g1331','互动触摸游戏','tech',353,'本游戏包含''触摸''玩法元素。

通过点击身体特定部位来执行脱衣或抚摸等操作，或通过菜单实现相同效果。');
INSERT INTO "tags" VALUES ('g1332','清洁工主角','cont',49,'本游戏的主角是一名[url=http://en.wikipedia.org/wiki/Janitor]清洁工[/url]。

清洁工或看管人是指负责照看医院、学校等建筑物的专业人员。清洁工主要负责清洁工作，通常（但并非总是）还承担一些维护和安全职责。');
INSERT INTO "tags" VALUES ('g1333','主角女友作为女主角','cont',627,'游戏开始时，一位或多位女主角已经作为主角的女友与其处于恋爱关系中。

[url=http://en.wikipedia.org/wiki/Girlfriend]女友[/url]是指非婚姻恋爱关系中的女性伴侣。

此标签应与[url=/g880]主角恋爱中[/url]同时使用。如果女主角在故事过程中才成为主角的女友，则不应使用此标签。');
INSERT INTO "tags" VALUES ('g1334','寄宿学校','cont',93,'游戏的某些部分发生在[url=http://en.wikipedia.org/wiki/Boarding_school]寄宿学校[/url]，这是一种学生们部分时间或全部时间住在那里的学校。');
INSERT INTO "tags" VALUES ('g1335','核心女主角','cont',584,'大多数视觉小说中会有一位女主角出镜时间多于其他角色，有些甚至整个故事围绕特定女主角展开。此标签用于帮助找到这些对剧情有重要意义的女主角。

并非所有核心女主角的例子都像[url=http://vndb.org/c325]宇佐美春[/url]出自[url=http://vndb.org/v211]G线上的魔王[/url]（一部围绕该角色构建的视觉小说，其他女主角只是\"如果？\"式的支线故事）那样显而易见，但区别应当是清晰的。

如果一位女主角只是出现频率高于其他角色，或者你认为她更重要，请不要使用此标签。其本意是寻找以某位特定女主角为核心的故事，而不是女主角以某种方式占据更多出镜时间的故事。');
INSERT INTO "tags" VALUES ('g1336','采耳','cont',69,'本视觉小说至少包含一个角色为另一个角色清理耳朵的场景。');
INSERT INTO "tags" VALUES ('g1337','儿童性虐待','ero',137,'本游戏包含成人或年长青少年利用儿童进行性刺激的场景。

在虚构故事中，并非所有涉及儿童的性内容都被视为[url=http://en.wikipedia.org/wiki/Child_sexual_abuse]儿童性虐待[/url]，因此当成人或年长青少年强迫（强奸）、恐吓、诱骗、欺骗，或通过药物或精神控制影响儿童以满足性欲时，应使用此标签。');
INSERT INTO "tags" VALUES ('g1340','性别不明主角','cont',710,'主角的性别没有明确说明。');
INSERT INTO "tags" VALUES ('g1341','血亲姑侄乱伦','ero',161,'这些游戏包含血亲姑姑与侄子之间的性场景。');
INSERT INTO "tags" VALUES ('g1342','御宅族朋友','cont',68,'其中一个配角是动漫（角色扮演/漫画/电子游戏）[url=http://en.wikipedia.org/wiki/Otaku]御宅族[/url]。这意味着他/她对这个爱好痴迷，尽管程度无害。通常这个角色是主角最好的朋友，或者至少是亲密的朋友。');
INSERT INTO "tags" VALUES ('g1343','杀人','cont',1862,'一起[url=http://en.wikipedia.org/wiki/Homicide]杀人[/url]事件在这款游戏的故事中扮演重要角色。

杀人是指一个人杀害另一个人的行为。');
INSERT INTO "tags" VALUES ('g1344','贫穷女主角','cont',125,'这款游戏中的一位女主角很贫穷。她要么为了谋生而工作，要么正遭受[url=http://en.wikipedia.org/wiki/Poverty]贫困[/url]之苦。');
INSERT INTO "tags" VALUES ('g1345','阴茎切除','cont',22,'游戏包含[url=http://en.wikipedia.org/wiki/Penis_removal]阴茎切除[/url]的场景，无论是自愿还是并非完全自愿...');
INSERT INTO "tags" VALUES ('g1347','绑架','cont',792,'游戏将[url=http://en.wikipedia.org/wiki/Kidnapping]绑架[/url]作为故事元素。

在刑法中，绑架是指违背他人意愿将其带走或运送，通常是将该人非法监禁，即没有法律授权的拘禁。这可能是为了勒索赎金或实施另一项犯罪，或与子女监护权纠纷有关。');
INSERT INTO "tags" VALUES ('g1349','会说话的动物','cont',262,'会说话的生物是神话、民间故事以及儿童文学中的常见主题。虚构的会说话的生物通常具有拟人化特征，拥有人类特质但以生物形象出现。使用会说话的生物能让讲故事的人将生物的基本特征与人类行为结合起来，运用隐喻，并娱乐儿童。

[来自[url=http://en.wikipedia.org/wiki/Talking_animals_in_fiction]维基百科[/url]]');
INSERT INTO "tags" VALUES ('g1350','班长主角','cont',36,'这个角色是[url=http://en.wikipedia.org/wiki/Class_President]班长[/url]。

班长通常是一个学生班级的领导者，主持班级内阁或学生会内的班级组织。在小学，班长通常由班级选举产生，班级是由同年级所有学生组成的选民群体。

班长与学生会主席不同，他们只代表特定的一个班级学生，而不是全体学生。');
INSERT INTO "tags" VALUES ('g1351','大胸部主角','cont',283,'这部视觉小说的主角拥有硕大、巨大或巨型的胸部。');
INSERT INTO "tags" VALUES ('g1352','触手主角','cont',95,'这款游戏的主角是（或后来变成）一只触手怪物。');
INSERT INTO "tags" VALUES ('g1354','正太控女主角','cont',56,'其中一位女主角在性方面被正太——即未成年男孩——所吸引。这通过她在游戏中的行为表现出来，她在此主题上的性经验与本标签无关。');
INSERT INTO "tags" VALUES ('g1355','阴毛选项','ero',151,'在这些游戏开始时，玩家可以选择参与者是否拥有[url=http://en.wikipedia.org/wiki/Pubic_hair]阴毛[/url]。');
INSERT INTO "tags" VALUES ('g1356','射精选择','ero',1167,'游戏使用选择，读者可以选择在哪里射精。
这种游戏机制会产生不同CG场景以供收集。有时，女主角可能怀孕也与读者所做的选择结果相关，这进一步可能导致视觉小说的不同结局。');
INSERT INTO "tags" VALUES ('g1357','办公室','cont',223,'带有此标签的游戏大多发生在[url=http://en.wikipedia.org/wiki/Office]办公室[/url]或类似场所内。

办公室是一种建筑与设计现象，也是一种社会现象，无论它是极小型办公室，比如一家“夫妻店”角落里的一条长凳，还是占据整层楼，乃至整栋专门为一家公司而建的巨型建筑。在现代语境中，办公室通常指白领受雇工作的场所。

只有当游戏在办公室中花费大量时间时才使用此标签，而不是每个只出现过一次办公室的游戏都使用。');
INSERT INTO "tags" VALUES ('g1358','办公室女郎女主角','cont',290,'本游戏中的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Office_lady]办公室女职员[/url]。

办公室女职员，常缩写为OL（日语：オーエル Oueru），是日本的一种女性办公室职员，通常从事粉领工作，例如端茶倒水以及秘书或文书工作。OL们往往未婚，并一直与父母同住到成年初期。办公室女职员通常是全职正式员工，虽然她们所做的工作通常晋升机会很少，而且通常有不成文的期望：一旦结婚就要离职。

这些女性常被昵称为shokuba no hana或‘办公室之花’，她们因M形曲线而遭受歧视。办公室女职员通常在高中或初中毕业后即被雇佣，大学毕业生则被劝阻从事此类职业。她们被留在办公室是因为她们给办公室带来的青春气息，因此得名‘办公室之花’。她们被要求承担支持男性员工的日常琐碎工作。这种职业几乎没有晋升机会，而且被特意设计成让女性在三十岁前结婚离职。二十四岁到二十八岁之间的女性常被建议安定下来，这其实是暗示她们辞职，因为那几年被认为是结婚的最佳时机。');
INSERT INTO "tags" VALUES ('g1359','办公室女职员主角','cont',88,'本游戏的主角是一位[url=http://en.wikipedia.org/wiki/Office_lady]办公室女职员[/url]。

办公室女职员，常缩写为OL（日语：オーエル Oueru），是日本的一种女性办公室职员，通常从事粉领工作，例如端茶倒水以及秘书或文书工作。OL们往往未婚，并一直与父母同住到成年初期。办公室女职员通常是全职正式员工，虽然她们所做的工作通常晋升机会很少，而且通常有不成文的期望：一旦结婚就要离职。

这些女性常被昵称为shokuba no hana或‘办公室之花’，她们因M形曲线而遭受歧视。办公室女职员通常在高中或初中毕业后即被雇佣，大学毕业生则被劝阻从事此类职业。她们被留在办公室是因为她们给办公室带来的青春气息，因此得名‘办公室之花’。她们被要求承担支持男性员工的日常琐碎工作。这种职业几乎没有晋升机会，而且被特意设计成让女性在三十岁前结婚离职。二十四岁到二十八岁之间的女性常被建议安定下来，这其实是暗示她们辞职，因为那几年被认为是结婚的最佳时机。');
INSERT INTO "tags" VALUES ('g1361','舞者女主角','cont',63,'本游戏中的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Dancer]舞者[/url]。

舞者是以舞蹈为职业的人，例如在舞台上表演。');
INSERT INTO "tags" VALUES ('g1362','奴隶制度','cont',242,'本游戏包含[url=http://en.wikipedia.org/wiki/Slavery]奴隶制度[/url]的内容。

奴隶制度是一种把人当作可买卖的财产并强迫其劳动的制度。奴隶从被捕获、购买或出生之时起就可能被违背意愿地扣留，并被剥夺离开、拒绝工作或要求补偿的权利。

历史上，奴隶制度曾被许多社会制度性地承认；在近代，大多数社会已将其定为非法，但通过债务奴役、契约劳役、农奴制、被囚禁的家庭佣人、某些强迫儿童为奴的收养、儿童兵以及强迫婚姻等形式，奴隶制仍然存在。');
INSERT INTO "tags" VALUES ('g1363','占卜师女主角','cont',47,'本游戏的一位女主角是占卜师。

[url=http://en.wikipedia.org/wiki/Fortune_teller]占卜[/url]是一种预测个人生活信息的活动。占卜的范围原则上与占卜术（divination）相同。区别在于，占卜术（divination）一词用于被视为宗教仪式一部分、祈求神灵或精灵的预测，而占卜（fortune-telling）一词则意味着一个不那么严肃或正式的场合，甚至是流行文化中的场合，在这种情况下，对预测背后神秘运作的信仰不如暗示、精神或实际建议或肯定那么突出。');
INSERT INTO "tags" VALUES ('g1364','时间停止','cont',68,'故事涉及某种形式的时间停止。');
INSERT INTO "tags" VALUES ('g1365','发交','ero',470,'游戏包含以发交为特色的场景。

发交是指性伴侣用自己的头发刺激另一方的阴茎，通常直至射精的性行为。

通常由接受性刺激的一方主动发起。
如果被动方主动采取行动，则常被称为发交性行为。');
INSERT INTO "tags" VALUES ('g1366','重逢','cont',370,'重逢在故事中起着重要作用。

此标签仅应用于再次相聚的行为，而不是普通的会面之类。');
INSERT INTO "tags" VALUES ('g1367','无名主角','cont',562,'本游戏的主角从不以姓名被提及。角色们在与他/她说话或提到他/她时，会使用“老师”或“哥哥”等称呼。需要时，游戏会将此角色的名字显示为“主角”、“玩家”或类似内容。 

这不应与可命名主角混淆，因为这位主角的名字无法更改。');
INSERT INTO "tags" VALUES ('g1368','40年代','cont',20,'故事发生在地球上1940年至1949年之间的某个时期。

有关40年代的更多详情，可参见相关的[url=http://en.wikipedia.org/wiki/1940s]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g1370','剑道社','cont',32,'[url=http://en.wikipedia.org/wiki/Kendo]剑道[/url]社及其相关活动在这段故事中扮演着重要角色。

剑道，意为“剑之道”，是一种现代日本剑术武术，基于传统剑术（kenjutsu），源自封建日本的武士阶级。剑道是一项对身心都有挑战的活动，它将强烈的武术价值观与类似体育的身体要素相结合。');
INSERT INTO "tags" VALUES ('g1371','吸血鬼主角','cont',210,'本游戏的主角是[url=http://en.wikipedia.org/wiki/Vampire]吸血鬼[/url]。吸血很常见，但并非必需。');
INSERT INTO "tags" VALUES ('g1372','有表情丰富呆毛的女主角','cont',29,'带有此标签的游戏至少有一位女主角，她在游戏的大部分时间里都拥有表情丰富的呆毛。与普通的[url=http://animanga.wikia.com/wiki/Ahoge]呆毛[/url]不同，表情丰富的呆毛会通过改变形状来表达人物的情绪或心境。
表情丰富的呆毛通常比普通呆毛更长。

一个例子包括来自Defcon☆One的[url=http://vndb.org/c2934]土屋 圭[/url]。');
INSERT INTO "tags" VALUES ('g1373','有虎牙的女主角','cont',315,'本游戏包含一名或多名拥有[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/CuteLittleFangs]虎牙[/url]的女主角。

她可以是吸血鬼、猫娘、狐娘，甚至是一个拥有通常可见的超长虎牙/犬齿的普通人类。');
INSERT INTO "tags" VALUES ('g1374','同一角色多次破处','ero',30,'这部视觉小说包含一些角色，她们的处女膜会被重建，从而有可能在同一个故事中再次失去童贞。

这可能是一次性事件，由魔法或[url=https://en.wikipedia.org/wiki/Hymenorrhaphy]科学[/url]干预所致，或者这种再生可能是该角色身体的一种自然或魔法特征。');
INSERT INTO "tags" VALUES ('g1375','完整贞操带','ero',121,'本游戏包含一名或多名角色穿戴[url=http://en.wikipedia.org/wiki/Chastity_belt]贞操带[/url]。

贞操带是一种带锁的服装，旨在防止性交。它们可用于保护穿戴者免受强奸或诱惑。有些装置还设计了附加功能以防手淫。贞操带为男性和女性都制作过，表面目的是保持贞洁。

不要将其与[url=https://vndb.org/g2831]贞操笼[/url]混淆：贞操笼或阴茎笼没有完整的腰带组件，它们套在阴茎上并靠睾丸固定。男性的完整贞操带也存在（见下图），但相对少见。

[url=https://s2.vndb.org/sf/14/131014.jpg]NSFW 女性示例1[/url]
[url=https://s2.vndb.org/sf/15/131015.jpg]NSFW 女性示例2[/url]
[url=https://s2.vndb.org/sf/16/131016.jpg]NSFW 男性示例[/url]');
INSERT INTO "tags" VALUES ('g1376','恶搞结局','tech',245,'本游戏的部分/全部结局并非要认真对待。角色做出不符合性格的行为，打破第四面墙，或者在一个原本严肃或大体严肃的游戏中显得十分愚蠢。');
INSERT INTO "tags" VALUES ('g1377','愚蠢的家长配角','cont',34,'其中一位父/母角色是个笨蛋。可以是主角、女主角、男主角或配角们的父亲或母亲。

一个男性例子是《Yuki Sakura》中Saki的父亲。女性例子可以是《EF》中Renji的妈妈。

不要将此标签用于Oya-baka(親馬鹿)，即“认为孩子所做的一切都很出色的父母”，除非他们真的是笨蛋。');
INSERT INTO "tags" VALUES ('g1378','裙底走光','cont',322,'游戏含有大量[url=http://en.wikipedia.org/wiki/Panchira]走光[/url]场景。

走光场景指的是女孩的内裤无意中暴露给主角、其他角色和/或我们读者的事件。

不要将其与[url=http://vndb.org/g857]可见内裤的女主角[/url]标签混淆，后者更侧重于女孩的日常穿着。它更侧重于内裤的长期可见性，而走光则更侧重于相对短暂的瞬间。');
INSERT INTO "tags" VALUES ('g1379','大叔主角','cont',343,'至少有一位主要主角是年长男性。');
INSERT INTO "tags" VALUES ('g1380','不忠','cont',1314,'这个游戏的故事包含[url=http://en.wikipedia.org/wiki/Infidelity]不忠[/url]内容。

不忠是对伴侣间关于情感和/或性排他性的假定或明确契约的违反。这种违反会导致愤怒、嫉妒、性嫉妒和敌对感。什么构成不忠行为，取决于双方关系中的排他性期望。');
INSERT INTO "tags" VALUES ('g1381','外国人主角','cont',296,'一位或多位主角来自视觉小说设定国家以外的其他国家。例如，如果视觉小说设定在日本，他就是[url=http://en.wikipedia.org/wiki/Gaijin]外国人[/url]（gaijin）。

Gaijin是一个日语单词，意思是“非日本人”或“外国人”。这个词是gaikokujin的缩写，意思是“外国人”。');
INSERT INTO "tags" VALUES ('g1382','转学生主角','cont',348,'主角最近[url=http://en.wikipedia.org/wiki/Academic_transfer]转学[/url]到他/她目前的学校。

大学转学是学生从一所高等教育机构转到另一所的过程，以及接收机构接受或不接受学分的程序。

然而，任何教育级别的学生都可以转学，在视觉小说中，高中最为常见。年幼的学生可能因父母工作调动到新地区而转学，但在视觉小说中，这往往是学生个人、且常常是秘密或神秘情况所致。');
INSERT INTO "tags" VALUES ('g1383','狙击手主角','cont',7,'游戏的主角是（或曾经是）一名[url=http://en.wikipedia.org/wiki/Sniper]狙击手[/url]。

狙击手是训练有素的射手，以一到两人小组行动，与敌人保持密切视觉接触，并从隐蔽位置或超出敌方人员探测能力的物理距离上攻击目标，且不被发现。');
INSERT INTO "tags" VALUES ('g1384','狙击手女主角','cont',30,'这些游戏中至少有一位女主角是（或曾经是）一名[url=http://en.wikipedia.org/wiki/Sniper]狙击手[/url]。

狙击手是训练有素的射手，以一到两人小组行动，与敌人保持密切视觉接触，并从隐蔽位置或超出敌方人员探测能力的物理距离上攻击目标，且不被发现。');
INSERT INTO "tags" VALUES ('g1388','闹剧','cont',104,'[url=http://en.wikipedia.org/wiki/Slapstick]闹剧[/url]是一种喜剧形式，涉及夸张的暴力和可能超越常识界限的活动。');
INSERT INTO "tags" VALUES ('g1389','妹控配角','cont',31,'游戏中的一位配角是妹控，一个总是对妹妹充满热情并愿意为她做任何事的人。

通常作为喜剧因素。');
INSERT INTO "tags" VALUES ('g1390','未来预测','cont',77,'游戏中的主角或某个角色，通过科学技巧或自身能力，能够预见未来事件。这促使他们要么尝试阻止/改变这些事件的结果，要么寻求其实现。');
INSERT INTO "tags" VALUES ('g1391','以欺骗手段强奸','ero',107,'这个游戏包含一个[url=http://en.wikipedia.org/wiki/Rape_by_deception]骗奸[/url]故事。 

这是一种犯罪，施害者通过欺骗获得受害者的性同意和顺从。也称为骗奸罪，但仅在部分司法管辖区被认定为犯罪。

例子包括使用伪装来迷惑受害者，或对自己或发生性行为的目的撒谎。');
INSERT INTO "tags" VALUES ('g1392','带有色情创可贴的女主角','cont',23,'这个游戏至少有一个场景，其中一位或多位女主角只贴着[url=http://en.wikipedia.org/wiki/Adhesive_bandage]创可贴[/url]来遮盖私密部位。');
INSERT INTO "tags" VALUES ('g1393','户外性行为','ero',4074,'这些游戏包含在户外区域的性爱场景。即，任何没有被墙壁、屋顶和地板围合的区域。

虽然这个标签可能看起来与[url=/g735]公共场所性行为[/url]相似，但它们指的是不同的事物。');
INSERT INTO "tags" VALUES ('g1395','马','cont',62,'这个游戏中有一匹或多匹[url=http://en.wikipedia.org/wiki/Horse]马[/url]在故事中扮演重要角色。或者在许多场景中都有马，并有与之相关的多行对话。');
INSERT INTO "tags" VALUES ('g1396','仅限萝莉女主角','cont',698,'游戏的所有女主角都是萝莉。');
INSERT INTO "tags" VALUES ('g1397','人造人主角','cont',42,'这个故事的主人公是一个[url=http://en.wikipedia.org/wiki/Homunculus]人造人[/url]。

人造人是一种人造人类，通过魔法和/或科学赋予生命。');
INSERT INTO "tags" VALUES ('g1398','精神冲击','内容',152,'故事包含狂野、难以理解、超现实或令人费解的元素。最终结果是让你感到困惑和不知所措，并质疑你观察世界的方式。');
INSERT INTO "tags" VALUES ('g1399','救世主女主角','内容',4,'至少有一位女主角被誉为“天选之人”，并伴有预言、征兆等。');
INSERT INTO "tags" VALUES ('g1400','衣物破损','内容',543,'故事中的人物偶尔会受到衣物破损的影响。他们的衣服在故事中被撕碎，无论是由于剧情还是游戏机制。');
INSERT INTO "tags" VALUES ('g1401','校医女主角','内容',206,'游戏中的一位女主角是学校[url=http://en.wikipedia.org/wiki/Nurse]护士[/url]。

护理是医疗保健领域的一种职业，专注于照顾个人、家庭和社区，使他们能够获得、维持或恢复最佳的健康和生活质量。');
INSERT INTO "tags" VALUES ('g1402','色情','色情',1185,'游戏包含[url=http://en.wikipedia.org/wiki/Pornography]色情[/url]场景。

这可能是拍摄影片（无论是合法的还是非法的、业余的还是专业的）、拍摄照片或其他种类的色情内容（如绘画Hentai）。它还包含消费色情内容。

注意：如果您不确定应使用哪个子标签，或者一般意义上的色情主题很重要，请仅使用此标签。否则请使用其子标签代替。');
INSERT INTO "tags" VALUES ('g1403','多变的结局歌曲','技术',181,'带有此标签的游戏在结尾不一定使用相同的歌曲。结束歌曲可能是随机的，或者取决于玩家获得的结局。');
INSERT INTO "tags" VALUES ('g1404','不良少女','内容',122,'本游戏中的一位或多位女主角是不良少女。

通常不遵守校规、逃课、是帮派成员，学校的大多数学生都害怕她。');
INSERT INTO "tags" VALUES ('g1405','巨物癖','色情',118,'带有此标签的视觉小说包含巨物癖性质的场景。这通常是性方面的，但有时不是.

[url=http://en.wikipedia.org/wiki/Macrophilia]巨物癖[/url]指的是对巨人的迷恋或涉及巨人的性幻想。这些巨人可能本来就是那个体型，也可能原本是普通人，后来突然身高暴涨.');
INSERT INTO "tags" VALUES ('g1406','工薪族男主角','cont',78,'本游戏中的一位或多位主角是[url=http://en.wikipedia.org/wiki/Salaryman]白领商务人士[/url].

工薪族是指收入以工资为基础的人，尤其是为公司工作的人.');
INSERT INTO "tags" VALUES ('g1407','互联网','cont',367,'带有此标签的视觉小说将[url=http://en.wikipedia.org/wiki/Internet]互联网[/url]作为故事的重要组成部分。例如，在线游戏或在线约会。');
INSERT INTO "tags" VALUES ('g1408','核心男主角','cont',69,'大多数视觉小说都有一个比其他角色出场时间更多的主角，而有些视觉小说甚至可能将整个故事围绕某个特定主角展开。这个标签就是用来帮助找到这些对剧情重要的主角.

如果某个主角只是比其他角色出场更频繁，或者你认为他更重要，请不要使用此标签。这个标签的目的是找到以某个特定主角为中心的故事，而不是某个主角设法占据了比其他角色更多出场时间的故事.');
INSERT INTO "tags" VALUES ('g1409','主角的前辈是男主角','cont',163,'这些游戏至少有一位男主角是主角的前辈。例子可以是在工作场所的资深前辈，或是比主角高几届的学生。');
INSERT INTO "tags" VALUES ('g1410','主角的后辈是男主角','cont',97,'这些游戏至少有一位男主角是主角的后辈。例子可以是在工作场所的资浅后辈，或是比主角低几届的学生。');
INSERT INTO "tags" VALUES ('g1411','主角的上司是男主角','cont',134,'这款游戏中至少有一位男主角是主角的上司。主角直接或间接地听从那位男主角的命令。');
INSERT INTO "tags" VALUES ('g1414','面包师主角','cont',72,'这款游戏的主角是一名[url=http://en.wikipedia.org/wiki/Baker]面包师[/url].

面包师是指使用烤箱或其他集中热源制作、烘烤并销售面包、面包卷、饼干或曲奇，以及/或薄脆饼干的人。蛋糕和类似食品也可能由其生产，因为近年来面包师与糕点师所制作产品之间的传统界限已经模糊.');
INSERT INTO "tags" VALUES ('g1415','面包师女主角','cont',49,'本游戏的女性主角之一是一位[url=http://en.wikipedia.org/wiki/Pastry_chef]糕点师[/url]。

糕点师是专业厨房中的岗位厨师，擅长制作糕点、甜点、面包及其他烘焙食品。他们受雇于大型酒店、小餐馆、餐厅、面包店和一些咖啡馆。');
INSERT INTO "tags" VALUES ('g1416','佣兵支援角色','续',23,'本游戏至少有一名支援角色是（或曾经是）[url=http://en.wikipedia.org/wiki/Mercenary]佣兵[/url]。

佣兵是指参与武装冲突的人，不是冲突方的国民或当事方，并且是“本质上为了私人利益而参与敌对行动，事实上由冲突一方或代表冲突一方承诺给予的物质补偿，大大超过对该方武装部队中类似级别和职能的战斗人员所承诺或支付的补偿”。');
INSERT INTO "tags" VALUES ('g1417','快速性爱','ero',84,'这个故事包含短暂性行为的场景，也称为[url=http://en.wikipedia.org/wiki/Quickie_%28sex%29]快速性爱[/url]。

快速性爱指的是短暂或自发的性行为，整个行为在很短的时间内完成。

通常这个词预设了跳过前戏，且至少一方达到高潮。快速性爱可能包括性交，也可能仅限于手淫或口交。');
INSERT INTO "tags" VALUES ('g1419','妖怪主角','cont',52,'本游戏的主角是[url=http://en.wikipedia.org/wiki/Y%C5%8Dkai]妖怪[/url]。

妖怪种类繁多，从恶毒到调皮捣蛋，偶尔也会给遇到它们的人带来好运。它们常具有动物特征（例如类似乌龟的河童，或长着翅膀的天狗），有时也能看起来像人类，有些像无生命物体，还有些没有可辨认的形状。妖怪通常拥有超自然灵力，其中变形是最常见的能力之一。具有变形能力的妖怪被称为obake。');
INSERT INTO "tags" VALUES ('g1420','魔物娘支援角色','cont',73,'本故事包含一个或多个非女主角的女性[url=http://en.wikipedia.org/wiki/Monster]怪物[/url]。关于怪物女主角，请使用[url=http://vndb.org/g892]魔物娘女主角[/url]。

怪物是任何虚构的生物，通常出现在传说或恐怖小说中，往往狰狞可怕，可能通过外貌或行为造成恐惧或身体伤害。');
INSERT INTO "tags" VALUES ('g1421','血亲祖母/孙乱伦','ero',27,'这些游戏包含有血缘关系的祖母与孙子之间的性爱场景。');
INSERT INTO "tags" VALUES ('g1422','非人形生物授精','ero',312,'故事涉及由某种非人类或非人形生物对某一角色进行[url=http://en.wikipedia.org/wiki/Insemination]授精[/url]。

此标签用于授精行为，而非生物导致的怀孕。');
INSERT INTO "tags" VALUES ('g1423','尿道性交','ero',75,'[url=http://en.wikipedia.org/wiki/Urethral_intercourse]尿道性交[/url]指用阴茎、手指（或视觉小说中的触手）等物体插入女性尿道。

不要与尿道扩张混淆，后者是将专门的医用工具插入尿道，作为一种性行为或恋物癖活动。');
INSERT INTO "tags" VALUES ('g1424','尿道扩张','ero',125,'[url=http://en.wikipedia.org/wiki/Urethral_sounding]尿道扩张[/url]是一种医学操作，使用称为“扩张条”的探针来增大尿道内径并查找其中的梗阻。扩张条也用于拉伸尿道以进行穿刺。

在性语境下，尿道扩张和尿道玩法也指这种做法。

尿道玩法可涉及将软性或硬性物品插入阴茎尿道口（以及更深处）。诸如扩张条之类的物品通常只插入龟头约一半深度，通常可以轻松取出。其他玩具和物品，如导管，可能插入更深；某些情况下甚至进入膀胱。有些物品甚至可以在膀胱内盘曲数次或膨胀。
在男性中，这种行为可能直接或间接与前列腺刺激及某些膀胱控制有关。');
INSERT INTO "tags" VALUES ('g1425','怪物分娩','ero',412,'本游戏包含角色在故事过程中通过[url=https://en.wikipedia.org/wiki/Viviparity]胎生[/url]分娩出任何非人类生物或怪物的场景。 
[b]如果是阴道产卵，请使用[url=/g3833]阴道产卵[/url][/b]。

重要提示：只有当幼体怪物的出生是故事的一部分时，才使用此标签。如果只是暗示或通过时间跳跃略过，只显示了结果（例如怪物在原本没有怪物的区域肆虐），则不要使用此标签！');
INSERT INTO "tags" VALUES ('g1426','跟踪','cont',324,'本故事包含[url=http://en.wikipedia.org/wiki/Stalker_%28Stalking%29]跟踪[/url]情节。

跟踪（Stalking）一词通常指个人或群体对另一个人不受欢迎且过度的关注。跟踪行为与骚扰和恐吓相关，可能包括亲自尾随受害者及/或对其进行监控。');
INSERT INTO "tags" VALUES ('g1427','新选组','cont',44,'本故事以[url=http://en.wikipedia.org/wiki/Shinsengumi]新选组[/url]为主要特色。

新选组是幕府末期的一支特别警察部队。');
INSERT INTO "tags" VALUES ('g1428','情人节','cont',214,'[url=http://en.wikipedia.org/wiki/Valentine%27s_Day]情人节[/url]是本视觉小说故事的重要部分。

情人节在每年的2月14日庆祝。如今，世界上许多国家都会庆祝情人节，主要集中在西方，尽管在这些国家它仍然是工作日。

最初的“圣瓦伦丁”是对一位或多位名为瓦伦丁努斯的早期基督教圣徒的礼拜庆祝。几百年后，诗人赋予了它现代的浪漫含义。');
INSERT INTO "tags" VALUES ('g1429','傲慢的主角','cont',116,'这类主角认为自己各方面都比别人优越，并乐于利用一切机会指出这一点。

大多数时候，这类主角最终显得无能却又极其傲慢，伴随着做作的大笑和滑稽表演；但在少数情况下，他确实有傲慢的充分理由。

通常这类主角身边会有几个跟班追随。');
INSERT INTO "tags" VALUES ('g1431','彩色文本','tech',1037,'本游戏在每个角色说话时使用特定的文本颜色。

有些游戏只对主要角色这样做，而对次要角色和旁白使用中性色（通常是白色或黑色）。');
INSERT INTO "tags" VALUES ('g1434','彩色名字标签','tech',3532,'本游戏在每个角色说话时使用特定的文本颜色来显示其名字。

有些游戏只对主要角色这样做，而对次要角色使用中性色（通常是白色或黑色）。');
INSERT INTO "tags" VALUES ('g1435','主角之妻作为女主角','cont',419,'其中一位女主角是（或曾经是）主角的[url=http://en.wikipedia.org/wiki/Wife]妻子[/url]。

妻子是在持续婚姻关系中的女性终身伴侣。妻子也可被称为配偶。只有在婚姻因法律承认的离婚或配偶死亡而结束后，这些称呼才不再适用于该女性。');
INSERT INTO "tags" VALUES ('g1436','逃跑的女主角','cont',114,'本故事包含一名或多名[url=http://en.wikipedia.org/wiki/Runaway_%28dependent%29]离家出走[/url]的女主角。

离家出走者是指未成年人或未达到法定年龄的人（具体年龄取决于当地司法管辖区），未经父母或法定监护人许可离开家，或被父母赶出家门，并被当地政府认为缺乏独立生活能力的人（后者有时被称为“被抛弃者”）。');
INSERT INTO "tags" VALUES ('g1437','少量选择','tech',1940,'本游戏的选择很少，有时甚至只有一个。');
INSERT INTO "tags" VALUES ('g1438','猫耳男主角','cont',111,'其中一名或多名男主角是[url=http://en.wikipedia.org/wiki/Cat]猫[/url]耳少年。');
INSERT INTO "tags" VALUES ('g1439','兔耳男主角','cont',61,'本视觉小说中的一名或多名男主角具有非永久性的兔耳特征。例如，戴着带兔耳发带的男主角。

注意：此标签适用于其兔耳特征并非生物性身体一部分的男主角。对于具有永久兔耳特征的非人男主角（即不是由穿着造成的），请使用[URL=https://vndb.org/g2733]兔男主角[/URL]。');
INSERT INTO "tags" VALUES ('g1441','只有一位男主角','cont',1804,'本游戏只有一位可供互动的男主角，故事完全围绕他展开。');
INSERT INTO "tags" VALUES ('g1442','带有美人痣的女主角','cont',608,'本游戏中的一位女主角有一颗[url=http://en.wikipedia.org/wiki/Beauty_mark]美人痣[/url]。

美人痣通常位于面部或上身的小痣，被视为有吸引力的特征。请勿将本标签用于带有难看或（在游戏背景下）不寻常胎记的女主角。');
INSERT INTO "tags" VALUES ('g1443','戴眼罩的男主角','cont',163,'本游戏有一位戴着[url=http://en.wikipedia.org/wiki/Eyepatch]眼罩[/url]的男主角。他那只眼睛不一定失明；唯一的要求是角色佩戴眼罩的频率足以让人将其与眼罩联系起来。

眼罩是戴在一只眼睛前的小片。它可以是布片，用松紧带或绳子固定在头部周围，也可以是粘性绷带。人们常佩戴眼罩来遮盖失去或受伤的眼睛，但它也对儿童有治疗弱视的用途。');
INSERT INTO "tags" VALUES ('g1444','情色殴打（非自愿）','ero',198,'本游戏包含非自愿情境下的色情殴打场景。

情色殴打是一种为了性满足而伤害或击打角色的性行为。角色可能被束缚，击打者持续对其施以打击。

关于Ryona：
Ryona是一个日语术语，指一种性情结，其中女性角色通常遭到男性或另一位女性角色的性攻击或折磨。作为一种恋物癖，Ryona围绕受害者展开，受害者几乎都是类人女性，受到施害者的身体攻击或心理虐待。

它与施虐癖的不同之处在于，它是一种窥视性的幻想恋物，专注于电子游戏、动画、漫画、电视和电影中的虚构角色，内容包含殴打、虐待或以其他方式杀害女性。由真人女演员出演的电影和电视剧角色变得越来越常见，因为媒体中对女性施加暴力的污名化已经减少。由于这种恋物癖范围广泛，它常常根据个人喜好融入其他更常见的恋物癖，如羞辱、强奸和BDSM。受害者通常具有体格健壮、训练有素或意志坚强等特点，因为许多人认为受害者和施害者平时实力差距越大，ryona越有吸引力。

如果受害者是男性，通常被标记为gyaku-ryona。这在女性中相当流行，甚至一些男性也喜欢，尤其是当施袭者是女性时。');
INSERT INTO "tags" VALUES ('g1445','喜剧性爱场景','ero',234,'本游戏中的性爱场景意在让读者发笑，而不是为了挑逗。

注意：不要将此标签用于无意间显得搞笑的性爱场景。');
INSERT INTO "tags" VALUES ('g1446','裸体立绘','tech',3367,'本游戏包含裸露的角色立绘。

此标签适用于游戏中的角色以立绘形式裸露，而不仅仅是在CG中出现。');
INSERT INTO "tags" VALUES ('g1447','虚假选择','tech',228,'本游戏包含一些初看像是选择的选择，但实际上你并没有选择权。例如，你可能只有一个选项的选择，或者除一个选项外其余都不可选，或者选择“错误”选项可能会触发“抱歉，请重试”之类的回应，直到你选择“正确”选项。

与[url=/g1467]无意义的选择[/url]不同，在那里你有选择，但选择哪一个并不重要。在这里你被迫选择某个特定选项。

如果选择“错误”选项会导致“游戏结束”或其他不幸结果，则不要使用此标签。那种情况下你是有选择的。');
INSERT INTO "tags" VALUES ('g1448','生态巨构','cont',9,'游戏的一部分发生在[url=http://en.wikipedia.org/wiki/Arcology]生态巨构[/url]中。

生态巨构（Arcology）融合了“建筑学”和“生态学”，是一套建筑设计原则，旨在设计极高人口密度的巨大栖息地（超结构）。这些很大程度上是假想的结构，将包含各种住宅、商业和农业设施，并尽量减少个体人类对环境的影响。它们通常被描绘为自给自足或经济上自给自足的。');
INSERT INTO "tags" VALUES ('g1449','受虐狂主角','cont',134,'这部视觉小说的主角是一名[url=http://en.wikipedia.org/wiki/Sadomasochism]受虐狂[/url]。');
INSERT INTO "tags" VALUES ('g1450','施虐狂主角','cont',157,'这部视觉小说的主角是一名[url=http://en.wikipedia.org/wiki/Sadomasochism]施虐狂[/url]。');
INSERT INTO "tags" VALUES ('g1451','施虐狂配角','cont',32,'这部视觉小说中至少有一名配角是[url=http://en.wikipedia.org/wiki/Sadomasochism]施虐狂[/url]。');
INSERT INTO "tags" VALUES ('g1452','受虐狂配角','cont',22,'这部视觉小说中至少有一名配角是[url=http://en.wikipedia.org/wiki/Sadomasochism]受虐狂[/url]。');
INSERT INTO "tags" VALUES ('g1453','自杀未遂','cont',237,'这个故事包含一次[url=http://en.wikipedia.org/wiki/Suicide]自杀[/url]的尝试。

自杀是故意导致自己死亡的行为。自杀常出于绝望，其原因可归因于精神障碍，如抑郁症、双相障碍、精神分裂症、自闭症谱系障碍、酗酒或药物滥用。财务困难或人际关系问题等压力因素往往起重要作用。');
INSERT INTO "tags" VALUES ('g1454','深喉','ero',1122,'本游戏包含[url=http://en.wikipedia.org/wiki/File:Wiki-dthroat.png]深喉[/url]。

深喉是一种性行为，其中男性的性伴侣，无论女性还是男性，将其伴侣的整个勃起阴茎深含入口中，越过会厌进入喉咙。这种行为是口交的一种形式。

[url=https://s2.vndb.org/sf/32/130932.jpg]NSFW示例1[/url]
[url=https://s2.vndb.org/sf/30/130930.jpg]NSFW示例2[/url]
[url=https://s2.vndb.org/sf/31/130931.jpg]NSFW示例3[/url]
[url=https://s2.vndb.org/sf/29/130929.jpg]NSFW群交示例[/url]');
INSERT INTO "tags" VALUES ('g1455','宠物扮演','色情',865,'本游戏包含宠物扮演。

[url=http://en.wikipedia.org/wiki/Animal_roleplay]动物角色扮演[/url]既可以是非性的，也可以是色情的性角色扮演。在其色情性角色扮演形式中，一名或多名参与者扮演真实或虚构动物的角色，包括相应的举止和行为，有时伴侣会扮演另一种动物，或者在性情境中，可能扮演骑手、训练师、看护者（甚至交配伴侣）。

动物角色扮演的主旨通常是人类自愿转变为动物状态，并关注由此产生的心理空间改变。

最常见的例子可能是犬科动物（幼犬、狗、狼）、猫科动物（猫、小猫、狮子）或马科动物（小马、马）。

动物角色扮演也用于BDSM情境中，一个人可能因被视为动物而受到羞辱。');
INSERT INTO "tags" VALUES ('g1456','性角色扮演','色情',1104,'本游戏包含性角色扮演。

[url=http://en.wikipedia.org/wiki/Sexual_roleplay]性角色扮演[/url]是一种色情形式的角色扮演：这是一种性行为，两个人或更多人按照性幻想中的角色进行表演。其严肃程度取决于参与者，场景可以从简单临时到细致复杂，配有服装和脚本。几乎任何角色都可以成为色情体验的基础材料，个体认为什么是性方面的事物也毫无限制。');
INSERT INTO "tags" VALUES ('g1457','寝取类型A','色情',269,'女主角自愿与另一个男人出轨，并享受其中的每一刻。没有强奸、勒索、药物等情节，从一开始就是双方自愿的性行为。');
INSERT INTO "tags" VALUES ('g1458','寝取类型B','色情',326,'起初，女主角被强奸、勒索、下药或以其他方式欺骗，与主角以外的人发生性关系。然而，她最终开始享受其中，并为完全自愿的性行为结束。');
INSERT INTO "tags" VALUES ('g1459','寝取类型C','色情',102,'女主角在主角面前被强奸，而他只能无助地看着。从始至终都是非自愿的。');
INSERT INTO "tags" VALUES ('g1461','多重人格的支持角色','内容',11,'本游戏中的一名或多名支持角色具有多重人格——这可能是心理原因所致，或者是真实的第二人格。');
INSERT INTO "tags" VALUES ('g1462','在线','技术',113,'本游戏部分功能需要有效的互联网连接才能使用，例如在线多人游戏、上传或下载自定义角色或地图等。');
INSERT INTO "tags" VALUES ('g1463','男着衣女裸体','色情',272,'包含性爱场景，其中男性穿着衣服，而女性裸体（或至少比男性穿得少得多）。可适用于BSDM场景以及普通性爱。');
INSERT INTO "tags" VALUES ('g1464','儿童支持角色','内容',188,'本游戏的一名或多名支持角色是儿童。
此标签仅表示纯关系，不包含恶意意图。

从生物学上讲，[url=http://en.wikipedia.org/wiki/Child]儿童[/url]（复数：children）通常是指处于出生至青春期阶段之间的人。一些对于儿童的非正式定义还包括胎儿，即未出生的孩子。法律上对“儿童”的定义通常指未成年人，也就是年龄小于法定成年年龄的人。');
INSERT INTO "tags" VALUES ('g1465','发明家主角','内容',37,'本游戏的主角是一位[url=http://en.wikipedia.org/wiki/Inventor]发明家[/url]。

发明家是创造新设备或新方法的人。他/她甚至可能拥有自己的工作室。');
INSERT INTO "tags" VALUES ('g1466','发明家女主角','内容',47,'本游戏至少有一位女主角是发明家。

[url=http://en.wikipedia.org/wiki/Inventor]发明家[/url]是指创造新设备或新方法的人。她甚至可能拥有自己的工作室。');
INSERT INTO "tags" VALUES ('g1467','无意义的选择','技术',1267,'本游戏包含一些毫无意义的选择。它们不影响结局，最多只会改变一两行对话；或者给出的选择无论选择哪一个都会导致完全相同的结果。

有时候游戏甚至会给玩家提供完全相同的选择。');
INSERT INTO "tags" VALUES ('g1468','选择','tech',0,'用于容纳与选择相关标签的元标签。');
INSERT INTO "tags" VALUES ('g1469','无感情的主角','cont',32,'本游戏中的一位主角在说话或做任何其他事情时都不表现出任何情感、活力或表情。

具有这种性格的主角通常正遭受某种心理创伤。');
INSERT INTO "tags" VALUES ('g1470','同性恋主角','cont',789,'主角是[url=http://en.wikipedia.org/wiki/Homosexuality]同性恋[/url]。

同性恋是指对同性别或同社会性别成员的浪漫或性吸引。');
INSERT INTO "tags" VALUES ('g1471','盲目选择','tech',183,'玩家会面临许多选择，而这些选择最终会通向哪条路线/哪位女主角是完全无法预料的。

一个例子是主角每天可以选择在学校哪里吃午饭（教室、食堂、屋顶等），而每位女主角每天都出现在新的地点。

此标签仅适用于影响路线选择的选择。如果盲目选择完全不影响路线，请考虑g1467。
只要盲目选择影响路线决策，即使并非所有选择都是盲目的，也可以使用此标签。');
INSERT INTO "tags" VALUES ('g1472','歧视','cont',350,'带有此标签的视觉小说包含涉及[url=http://en.wikipedia.org/wiki/Discrimination]歧视[/url]的故事。

歧视是指基于个人在某个群体或类别中的成员身份 - 或被感知的成员身份 - 而对其进行的偏见性对待。');
INSERT INTO "tags" VALUES ('g1473','90年代','cont',137,'故事的主要部分发生在[url=http://en.wikipedia.org/wiki/1990s]1990-1999[/url]年间。');
INSERT INTO "tags" VALUES ('g1474','结局列表','tech',730,'这些游戏允许玩家查看所有可能结局的列表，并可在该列表上标示哪些结局已被达成。');
INSERT INTO "tags" VALUES ('g1475','游戏中视频','tech',189,'本游戏除片头和片尾外，还包含视频或类似的动画片段。');
INSERT INTO "tags" VALUES ('g1476','严肃的主角','cont',144,'这种类型的主角总是很严肃，他/她很少笑或表现出快乐的情绪。');
INSERT INTO "tags" VALUES ('g1477','黑客主角','cont',48,'这些游戏至少有一位主角是[url=http://en.wikipedia.org/wiki/Hacker_%28term%29]黑客[/url]。');
INSERT INTO "tags" VALUES ('g1478','额外支线故事','tech',869,'这些游戏具有可选的支线故事，它们不影响主线故事，并且可能不属于正史。它们可能从一开始就可以玩，也可能需要通过达成特定条件（例如达到真结局）来解锁。

额外故事可能以表示支路的选择形式出现，也可能直接从主菜单访问。');
INSERT INTO "tags" VALUES ('g1479','地点显示','tech',166,'这些游戏会告诉你当前场景发生地点的名称，通常是在场景开始时屏幕角落弹出的显示。');
INSERT INTO "tags" VALUES ('g1480','少量事件CG','tech',755,'这些游戏只使用少量事件CG来讲述故事。');
INSERT INTO "tags" VALUES ('g1481','多段演职员表','tech',134,'本游戏有多个结局演职员表，通常出现在结局数量众多的游戏以及每章末尾有分段式故事的游戏上。');
INSERT INTO "tags" VALUES ('g1483','失落的技术','cont',50,'世界存在着比当前水平更先进的技术元素，这些元素由现已灭绝的过去文明所遗留。有时，这种技术在当前时代无法被复制。');
INSERT INTO "tags" VALUES ('g1484','纯语音部分','tech',132,'此标签描述的游戏包含文本对话框不出现、但游戏随着角色说话而推进的片段。

虽然大多数日式游戏时不时会有一些没有对应文本显示的配音，但此标签应仅用于整句、整场出现这种情况的游戏。');
INSERT INTO "tags" VALUES ('g1485','作家主角','cont',232,'这个故事的主角是一位作家。

[url=http://en.wikipedia.org/wiki/Writer]作家[/url]是指创作非虚构作品或文学艺术（如小说、短篇故事、诗歌、戏剧、剧本或散文）的人—尤其是以写作为职业的人。');
INSERT INTO "tags" VALUES ('g1486','由他人破处','ero',277,'本游戏包含一个或多个女主角向不同于主角的角色献出处女之身的场景。

对于角色从故事一开始就有性经验的游戏，请勿使用此标签。');
INSERT INTO "tags" VALUES ('g1487','互动电影','tech',83,'本游戏是一部[url=http://en.wikipedia.org/wiki/Interactive_movie]互动电影[/url]

互动电影是一种电子游戏，具有高度电影化的表现方式并大量使用脚本，通常使用动画或真人实景的全动态视频。

并非所有互动电影都可以被视为视觉小说，它们仍必须符合d2#1中所述的混合视觉小说的要求。');
INSERT INTO "tags" VALUES ('g1490','病娇主角','cont',140,'本游戏的主角表现出[url=http://en.wikipedia.org/wiki/Yandere#Y]病娇[/url]行为。

病娇是一个日语术语，指一个人最初对某人非常关爱和温柔，之后其奉献变得具有破坏性，通常通过暴力表现出来。');
INSERT INTO "tags" VALUES ('g1491','运动型女主角','cont',312,'这部视觉小说中至少有一位女主角经常从事[url=http://en.wikipedia.org/wiki/Athletics_%28sport%29]田径运动[/url]，并在职业或业余水平上参加比赛。

与[url=http://vndb.org/g681]活力女主角[/url]不同，因为该标签与女主角的职业/角色有关，而非生活方式或个性特征。');
INSERT INTO "tags" VALUES ('g1492','顺从的主角','情色',193,'带有此标签的作品中，主角在性行为中扮演性顺从的角色，将主导权交给伴侣。顺从的主角通常不会主动发起性行为，甚至可能被迫，但他们不一定是受虐狂，也不一定是自愿顺从。

此标签并不暗示BDSM内容。');
INSERT INTO "tags" VALUES ('g1493','戴眼罩的主角','cont',45,'这款游戏的主角戴着[url=http://en.wikipedia.org/wiki/Eyepatch]眼罩[/url]。他那只眼睛不一定失明；唯一的要求是角色经常戴着它，以至于与之相关联。

眼罩是一小块戴在一只眼睛前面的布片。它可能是用松紧带或绳子固定在头上的布片，也可能是粘性绷带。人们通常用它来遮盖失去或受伤的眼睛，但它在儿童弱视治疗中也有治疗用途。');
INSERT INTO "tags" VALUES ('g1494','多配偶制','cont',90,'本游戏包含[url=http://en.wikipedia.org/wiki/Polygamy]多配偶制[/url]。

多配偶制是指包含两个以上伴侣的婚姻。当一个男人同时与多名妻子结婚时，这种关系称为一夫多妻制，且妻子之间没有婚姻关系；当一个女人同时与多名丈夫结婚时，称为一妻多夫制，且丈夫之间没有婚姻关系。如果一段婚姻包含多个丈夫和多个妻子，则可称为群婚。');
INSERT INTO "tags" VALUES ('g1495','有遮眼发型的男主角','cont',95,'本游戏中至少有一位男主角在故事的相当长一段时间内，发型遮住一只（或两只）眼睛。

也用于那些面部以类似方式被阴影遮住的男主角。');
INSERT INTO "tags" VALUES ('g1498','白发男主角','cont',538,'此标签适用于至少有一位主要女主角拥有[url=http://en.wikipedia.org/wiki/Human_hair_color#Grey_and_white_hair]白色头发[/url]的游戏。');
INSERT INTO "tags" VALUES ('g1499','白化病男主角','cont',73,'本游戏中某位男主角的外貌类似于[url=http://en.wikipedia.org/wiki/Albino]白化病患者[/url]；他拥有白发，眼睛颜色不自然（如红色或几乎透明的蓝色）。');
INSERT INTO "tags" VALUES ('g1500','马尾辫男主角','cont',308,'本游戏有一位留[url=http://en.wikipedia.org/wiki/Ponytail]马尾辫[/url]的男主角。');
INSERT INTO "tags" VALUES ('g1501','有虎牙的男主角','cont',70,'本游戏包含一位或多位拥有[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/CuteLittleFangs]虎牙[/url]的男主角。

他可以是吸血鬼、猫娘、狐妖，甚至是拥有通常可见的特别长虎牙/犬齿的普通人。');
INSERT INTO "tags" VALUES ('g1502','异色瞳男主角','cont',136,'一位或多位男主角的眼睛颜色不同。

详情请查看相关的[url=http://en.wikipedia.org/wiki/Heterochromia]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g1503','有翅膀的男主角','cont',77,'本游戏包含一位或多位拥有[url=http://en.wikipedia.org/wiki/Wing]翅膀[/url]的男主角。

他可以是天使、恶魔，甚至是佩戴配饰的普通人，但在许多场景中他背上都有翅膀。');
INSERT INTO "tags" VALUES ('g1504','哥特造型的男主角','cont',60,'本游戏中的一位或多位男主角大多穿着[url=http://en.wikipedia.org/wiki/Gothic_fashion]哥特风格[/url]服装。');
INSERT INTO "tags" VALUES ('g1505','穿盔甲的男主角','cont',42,'本游戏中有相当多的场景可以看到穿着[url=http://en.wikipedia.org/wiki/Armor]盔甲[/url]的男主角。它可以是西式或东式盔甲，甚至某种未来风格的盔甲。');
INSERT INTO "tags" VALUES ('g1506','戴单片眼镜的主角','cont',4,'游戏的主角在游戏的大部分时间里戴着[url=http://en.wikipedia.org/wiki/Monocle]单片眼镜[/url]。');
INSERT INTO "tags" VALUES ('g1507','戴单片眼镜的男主角','cont',30,'本游戏中一位或多位男主角在游戏的大部分时间里戴着[url=http://en.wikipedia.org/wiki/Monocle]单片眼镜[/url]。');
INSERT INTO "tags" VALUES ('g1508','天使男主角','cont',100,'本游戏中的一位或多位男主角是[url=http://en.wikipedia.org/wiki/Angel]天使[/url]。');
INSERT INTO "tags" VALUES ('g1509','白化病主角','cont',59,'本游戏主角的外貌类似于[url=http://en.wikipedia.org/wiki/Albino]白化病患者[/url]；他/她有白发，眼睛颜色不自然（如红色或几乎透明的蓝色）。');
INSERT INTO "tags" VALUES ('g1510','白发主角','cont',273,'此标签适用于主角拥有[url=http://en.wikipedia.org/wiki/Human_hair_color#Grey_and_white_hair]白色头发[/url]的游戏。');
INSERT INTO "tags" VALUES ('g1511','小学生英雄','继续',25,'至少有一位英雄是[url=http://en.wikipedia.org/wiki/Elementary_school]小学生[/url]。');
INSERT INTO "tags" VALUES ('g1512','小学生主角','继续',67,'本游戏的主角是一名[url=http://en.wikipedia.org/wiki/Elementary_school]小学生[/url]。');
INSERT INTO "tags" VALUES ('g1513','学生会成员英雄','继续',109,'英雄是[url=http://en.wikipedia.org/wiki/Student_government]学生会[/url]的成员。

学生会是一个存在于许多大学、学院，并开始在一些高中出现的学生组织。在高等教育中，学生会通常在校园内拥有自己的建筑，专门用于学生群体的社交和组织活动。');
INSERT INTO "tags" VALUES ('g1514','学生会会长英雄','继续',88,'英雄是[url=http://en.wikipedia.org/wiki/Student-body_president]学生会主席[/url]。

学生会主席是高中、学院或大学级别学生会或学生联合会中最高级别的学生干部。作为学术生涯中备受尊崇的最高荣誉角色之一，担任主席可以使学生获得强大的人际交往、领导力、社交、经济和管理技能。雇主可能会对担任过此职务的应聘者给予高度评价。

学生会主席与班长不同。班长仅代表特定班级（年级）的学生，而学生会主席是整个学校中级别最高的学生。');
INSERT INTO "tags" VALUES ('g1515','手指插入','性内容',4167,'[url=http://en.wikipedia.org/wiki/Fingering_%28sexual_act%29]手指插入[/url]是指为了性唤起和性刺激而对阴蒂、外阴、阴道或肛门进行手动（生殖器）刺激。它可以构成整个性行为，也可以是相互手淫、前戏或其他性活动的一部分。自慰是指以此方式手淫。它类似于手交，即对阴茎的手动刺激。这些活动提供性快感，无论是作为非插入式还是插入式性交使用。');
INSERT INTO "tags" VALUES ('g1516','有美人痣的英雄','继续',250,'本游戏中的英雄有[url=http://en.wikipedia.org/wiki/Beauty_mark]美人痣[/url]。

美人痣是通常位于面部或上半身的小痣，被认为是迷人的特征。不要将此标签用于游戏中有碍观瞻或不寻常（在游戏语境中）胎记的女主角。');
INSERT INTO "tags" VALUES ('g1517','主角的未婚妻作为英雄','继续',54,'一个或多个英雄是主角的未婚妻。

她们在故事结尾是否结婚并不重要，这关乎她们之间的关系。');
INSERT INTO "tags" VALUES ('g1518','有晒痕的女主角','继续',298,'本游戏特色为女主角的身体带有[url=http://en.wikipedia.org/wiki/Tan_line]晒痕[/url]。

晒痕指的是人体皮肤上一个或多个区域与身体其他经过长时间紫外线辐射而晒黑的区域相比，呈现出明显相对苍白的肤色分界线。辐射源可以是太阳，也可以是日光浴床中使用的人工紫外线源。');
INSERT INTO "tags" VALUES ('g1519','精神崩溃','继续',624,'此视觉小说中的一个或多个角色是精神崩溃的对象——严重和/或持续的创伤超出其承受能力，导致精神崩溃。可能的影响包括但不限于：
- 变成性瘾者/性奴。
- 变成没有生气的空壳。');
INSERT INTO "tags" VALUES ('g1521','广播社','继续',11,'广播社及其相关活动在本故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g1522','有血缘关系的叔侄乱伦','性内容',53,'这些游戏包含有血缘关系的叔叔和侄女之间的性场景。');
INSERT INTO "tags" VALUES ('g1523','纪律委员长主角','继续',8,'主角是纪律委员会的委员长。

纪律委员会是存在于许多大学、学院或高中的学生组织，主要目的是在学生中执行学校规章制度，如宵禁等。');
INSERT INTO "tags" VALUES ('g1524','纪律委员主角','继续',19,'主角是纪律委员会的成员。

纪律委员会是存在于许多大学、学院或高中的学生组织，主要目的是在学生中执行学校规章制度，如宵禁等。');
INSERT INTO "tags" VALUES ('g1525','驱魔','继续',93,'本游戏包含[url=http://en.wikipedia.org/wiki/Exorcism]驱魔[/url]内容。

驱魔是一种宗教实践，将从被认为被其附身的人或区域中驱逐恶魔或其他灵体的行为。根据驱魔者的精神信仰，这可以通过让灵体发誓、进行复杂的仪式，或者仅仅以更高力量的名义命令其离开来完成。这种做法历史悠久，是许多文化和宗教信仰体系的一部分。');
INSERT INTO "tags" VALUES ('g1526','标题致敬','技术',215,'这部视觉小说的标题是对已有著名作品或小说的模仿、套用、调侃或致敬。这个类别也可以包括那些带有明显意在戏仿其他作品的标志或设计的作品。

这里的"Parody"与日语中该词的用法无关，比如用来描述同人志；它类似于西方的色情恶搞标题，并且像那些标题一样，内容可能与所提及的作品无关或关系甚微。');
INSERT INTO "tags" VALUES ('g1527','穿刺游戏','ero',121,'本游戏包含一个或多个场景，其中涉及[url=http://en.wikipedia.org/wiki/Play_piercing]穿刺游戏[/url]。

穿刺游戏、针刺游戏或娱乐性针灸是一种身体穿刺，其目的是享受体验而非制造永久的身体装饰。针、磨尖的骨头或其他用于穿刺游戏的工具会在活动结束时从身体上移除，让伤口愈合。参与穿刺游戏的人可能出于自我表达、作为模仿原始部落文化的仪式的一部分、为了精神上的自我发现、为了性愉悦、为了单纯的娱乐、提高意识或消磨无聊而进行。');
INSERT INTO "tags" VALUES ('g1528','旅行者主角','cont',19,'这些游戏中的至少一位主角是[url=http://en.wikipedia.org/wiki/Traveler]旅行者[/url]。');
INSERT INTO "tags" VALUES ('g1529','师生恋','cont',252,'带有此标签的游戏将包含学生与其老师之间的浪漫关系。');
INSERT INTO "tags" VALUES ('g1530','社交网络服务','cont',176,'游戏故事以使用[url=http://en.wikipedia.org/wiki/Social_networking_service]社交网络服务[/url]为特色。

社交网络服务是一种在线服务、平台或网站，其重点是促进人们之间建立社交网络或社会关系，例如共享兴趣、活动、背景或现实生活中的联系的人。');
INSERT INTO "tags" VALUES ('g1531','蛰居族主角','cont',20,'带有此标签的游戏以一位曾是/是[url=http://en.wikipedia.org/wiki/Hikikomori]蛰居族[/url]的主角为特色。

"Hikikomori"是一个日语术语，指的是隐居的青少年或年轻人退出现实社会生活的现象，他们通常寻求极端的隔离和封闭。该术语既指一般的社会学现象，也指属于这一社会群体的人。');
INSERT INTO "tags" VALUES ('g1532','蛰居族主人公','cont',103,'带有此标签的游戏以一位曾是/是[url=http://en.wikipedia.org/wiki/Hikikomori]蛰居族[/url]的主人公为特色。

"Hikikomori"是一个日语术语，指的是隐居的青少年或年轻人退出现实社会生活的现象，他们通常寻求极端的隔离和封闭。该术语既指一般的社会学现象，也指属于这一社会群体的人。');
INSERT INTO "tags" VALUES ('g1533','异地恋','cont',74,'带有此标签的故事包含角色之间因相当远的距离（例如海外）而分离的浪漫关系和/或恋情。');
INSERT INTO "tags" VALUES ('g1534','学生社团成员主角','cont',110,'一位主角是学生社团的成员。

学校社团是基于学生的学校组织，由学校批准的组织构成，承担着各种各样的任务，具体取决于每个社团的特定目的。');
INSERT INTO "tags" VALUES ('g1535','作家主角','cont',93,'本故事中的一位主角是作家，无论是小说、杂志文章还是其他任何内容。

也可用于撰写文章的报纸记者。');
INSERT INTO "tags" VALUES ('g1536','演员主角','cont',108,'本游戏中的一位或多位主角是[url=http://en.wikipedia.org/wiki/Actor]演员[/url]。

演员/女演员是在戏剧制作中表演的人，并以该身份在电影、电视、戏剧或广播中工作。古希腊语中“actor”一词的字面意思是“诠释者”，在这个意义上，演员就是诠释戏剧角色的人。');
INSERT INTO "tags" VALUES ('g1537','表演艺术导演主角','cont',9,'本游戏中一位或多位主角担任电影、电视或戏剧[url=http://en.wikipedia.org/wiki/Director]导演[/url]。');
INSERT INTO "tags" VALUES ('g1538','盲人主角','cont',20,'一位或多位主角是完全或法律意义上的失明，暂时或永久性的。');
INSERT INTO "tags" VALUES ('g1539','胆怯主角','cont',46,'这种类型的主角是软弱的（情感上、身体上和/或精神上）。他很容易被摆布和欺负，至少大部分游戏过程中如此。胆怯的主角往往性情温和、有礼貌且温顺。');
INSERT INTO "tags" VALUES ('g1540','三人行结局','tech',1196,'本游戏拥有一个结局，其中角色最终处于三人行的关系中，无论是浪漫的还是纯粹性爱的。');
INSERT INTO "tags" VALUES ('g1541','胆怯主人公','cont',120,'这种类型的主人公是软弱的（情感上、身体上和/或精神上）。他/她很容易被摆布和欺负，至少大部分游戏过程中如此。胆怯的主人公也往往性情温和、有礼貌且温顺。');
INSERT INTO "tags" VALUES ('g1542','医生主角','cont',185,'本游戏的一位主角是医学从业者，[url=http://en.wikipedia.org/wiki/Physician]医师[/url]。');
INSERT INTO "tags" VALUES ('g1543','跨种族/跨物种恋爱','cont',348,'带有此标签的游戏包含至少一段不同种族或物种角色之间的浪漫关系。');
INSERT INTO "tags" VALUES ('g1544','冷娇主角','cont',109,'这些游戏至少有一位酷娇型角色。

酷娇型角色一开始对主角（也可能对其他人）冷漠或冷淡，但随着故事发展会对主角产生感情。

传统傲娇原型的一种变体。');
INSERT INTO "tags" VALUES ('g1545','可命名的角色（们）','tech',108,'这些游戏有一个或多个名字可以更改的角色。');
INSERT INTO "tags" VALUES ('g1546','大学生角色','cont',343,'至少有一位角色是大学生。');
INSERT INTO "tags" VALUES ('g1547','主角的兄弟角色','cont',333,'该游戏中的一位角色是主角的[url=http://en.wikipedia.org/wiki/Brother]兄弟[/url]。无论是弟弟、哥哥还是双胞胎都没关系。');
INSERT INTO "tags" VALUES ('g1548','主角的血缘兄弟角色','cont',125,'该游戏中的一位角色是主角的[url=http://en.wikipedia.org/wiki/Brother]亲兄弟姐妹[/url]。');
INSERT INTO "tags" VALUES ('g1549','主角的非血缘兄弟角色','cont',106,'在这部视觉小说中至少有一位角色是主角的兄弟，但他们在生物学上并无关系。

这位角色可以是主角的[URL=https://vndb.org/i292]继兄弟[/URL]、[URL=https://en.wikipedia.org/wiki/Adoption]养兄弟[/URL]或[URL=https://en.wikipedia.org/wiki/Foster_care]寄养兄弟[/URL]。');
INSERT INTO "tags" VALUES ('g1550','主角的堂/表兄弟角色','cont',70,'一位或多位角色是主角的[url=http://en.wikipedia.org/wiki/Cousin]堂/表亲[/url]。

堂/表亲是指与一个人共享一个或多个共同祖先的亲戚（不包括父母、子女/后代、兄弟姐妹、兄弟姐妹的子女/后代，或父母/祖先的兄弟姐妹）。但在日常用语中，“cousin”通常特指“第一代堂/表亲”。');
INSERT INTO "tags" VALUES ('g1551','与睡者性交','ero',471,'这款游戏中的角色利用睡眠（自然的或通过安眠药诱导的）与他人发生性关系，以及其他将睡眠与性结合的情况（例如假装睡觉以引诱等）。

通常情况下，这样做是为了不吵醒睡着的人。

不要将其与“唤醒性爱”混淆——因为这主要是指在醒来后发生的性行为。');
INSERT INTO "tags" VALUES ('g1552','妹控主角','cont',306,'游戏的主角是一个妹控，一个总是对自己的妹妹（通常是女主角之一）充满热情的人，他愿意为她做任何事。');
INSERT INTO "tags" VALUES ('g1553','克隆主角','cont',49,'这部视觉小说的主角是[url=http://en.wikipedia.org/wiki/Cloning]克隆[/url]人。

生物学中的克隆是指产生基因相同的个体种群的过程，在自然界中发生在细菌、昆虫或植物等生物无性繁殖时。');
INSERT INTO "tags" VALUES ('g1554','剧本选择','tech',1124,'这款游戏不是向玩家提供标准选择，而是有一个选择界面或其他类似方法，玩家只需选择想阅读的剧本。');
INSERT INTO "tags" VALUES ('g1555','普通场景回想','tech',464,'这款游戏的回想模式不仅包含H场景，还包含故事中的普通事件。这帮助玩家无需读取存档和快进即可重玩故事的某个部分。');
INSERT INTO "tags" VALUES ('g1557','施虐癖女主角','cont',236,'这部视觉小说中至少有一位女主角是[url=http://en.wikipedia.org/wiki/Sadomasochism]施虐狂[/url]。');
INSERT INTO "tags" VALUES ('g1558','已读文本标记','tech',541,'游戏系统会用不同颜色标记已读文本，以便于识别。');
INSERT INTO "tags" VALUES ('g1559','巨大插入','ero',482,'这些游戏至少包含一幕阴道、肛门或口腔插入的场景，其中插入的物体或身体部位明显大于被插入的孔道，常常不可思议地撑开并鼓起腹部/喉咙。

例如用超大型/怪物阴茎插入，其直径大于女孩的大腿，同时使用多个振动器或大型触手，正常男性与迷你女孩发生性行为（参见[url=/g1405]巨人癖[/url]），或者将双手肘部深插入阴道。');
INSERT INTO "tags" VALUES ('g1560','漫画家女主角','cont',58,'该游戏中的一位女主角是[url=http://en.wikipedia.org/wiki/Mangaka]漫画家[/url]。

Mangaka是日语中漫画艺术家或卡通画家的词汇。在日本以外，manga通常指日本漫画书，而mangaka指漫画的作者，通常是日本人。');
INSERT INTO "tags" VALUES ('g1561','怪诞身体改造','ero',203,'这款游戏包含情色怪诞场景，涉及极端的身体改造、奇异突变和/或极度毁容的角色。仅适用于非血腥场景，对于血腥截肢等应使用[url=http://vndb.org/g162]Guro[/url]代替。');
INSERT INTO "tags" VALUES ('g1562','妄想型女主角','cont',34,'这个游戏中的女主角脑袋里充满了妄想。

妄想是一种即使有相反的有力证据仍坚信不疑的信念。与幻觉不同，妄想总是病理性的（疾病或疾病过程的结果）。作为一种病态，它区别于基于错误或不完整信息的信念、虚构症、教条、错觉或其他感知影响。');
INSERT INTO "tags" VALUES ('g1564','口型同步','tech',560,'本游戏具有口型同步功能，角色的嘴巴动画与台词同步。

口型同步是一个技术术语，指使嘴唇动作与演唱或说话的声音相匹配。在现场表演和录音的背景下，该术语可以指许多不同的技术和过程。');
INSERT INTO "tags" VALUES ('g1565','男性怀孕','cont',44,'指男性在事件进程中已经怀孕或变得怀孕的情况。');
INSERT INTO "tags" VALUES ('g1566','会说话的物体','cont',92,'游戏中有某个或多个可以说话的物体，例如魔法物品或被灵魂附身的物品。');
INSERT INTO "tags" VALUES ('g1567','摄影玩法','tech',34,'这些视觉小说包含玩家拍照的小游戏。');
INSERT INTO "tags" VALUES ('g1568','返老还童','cont',54,'本故事涉及[url=http://en.wikipedia.org/wiki/Rejuvenation_%28aging%29]返老还童[/url]的概念，即假设逆转衰老过程。

返老还童不同于延长寿命。延长寿命的策略通常研究衰老的原因，并试图对抗这些原因以减缓衰老。返老还童是逆转衰老，因此需要不同的策略，即修复与衰老相关的损伤，或用新组织替换受损组织。返老还童可以作为一种延长寿命的手段，但大多数延长寿命的策略并不涉及返老还童。');
INSERT INTO "tags" VALUES ('g1569','务实的主角','cont',138,'这部视觉小说的主角基于逻辑、实际和/或理性的考虑与视角做出决定并采取行动。需要注意的是，务实的人不一定冷漠或缺乏情感。');
INSERT INTO "tags" VALUES ('g1570','冲动的主角','cont',64,'一个凭冲动行事而非经过深思熟虑的主角。这类主角常常完全基于对情况的直觉把握来行动，而不是基于理性的评估。');
INSERT INTO "tags" VALUES ('g1577','舔脚','ero',474,'舔一个人脚的行为。');
INSERT INTO "tags" VALUES ('g1578','老年人性行为','ero',98,'此作品包含一个或多个情色场景，其中一方或双方参与者为六十岁或以上的老年人。如果参与者仅人到中年或更年轻，请不要使用此标签。');
INSERT INTO "tags" VALUES ('g1579','肛门玩具','ero',1599,'本故事包含使用[url=http://en.wikipedia.org/wiki/Sex_toy#Anal_toys]肛门玩具[/url]的场景。这些玩具用于对肛门进行性刺激。

使用此标签表示各种类型的肛门玩具，包括肛塞、肛门拉珠和肛门振动器。');
INSERT INTO "tags" VALUES ('g1580','过量精液','ero',803,'该视觉小说包含出现大量精液的场景。这些精液可能来自一个男性多次射精、多个男性，甚至来自怪物或其他超自然生物等奇异来源。唯一重要的因素是上述液体的量应该是压倒性的和/或覆盖参与者。');
INSERT INTO "tags" VALUES ('g1581','骑乘位','ero',5238,'[url=http://en.wikipedia.org/wiki/Woman_on_top_%28sex_position%29]骑乘位[/url]是一组性交体位的名称，其中男性仰卧或坐着，女性跨坐于其上，双方面对面，接受方的阴道或肛门与插入方的阴茎对齐以实现插入。

[url=http://upload.wikimedia.org/wikipedia/commons/8/84/Wiki-cowgirl.png]NSFW示例[/url]

注意：如果参与者彼此背对，请改用[url=http://vndb.org/g1582]反向骑乘位[/url]标签。');
INSERT INTO "tags" VALUES ('g1582','反向骑乘位','ero',1707,'反向骑乘位是[url=http://vndb.org/g1582]骑乘位[/url]的一种变体，其中女性背对男性。她可以跪姿或蹲姿，躯干可以直立，也可以与插入方男性的身体对齐。');
INSERT INTO "tags" VALUES ('g1583','蝎狮','cont',2,'蝎狮是一种类似埃及狮身人面像的波斯传说生物。它拥有红色狮子的身体、长着三排利齿（如鲨鱼般）的人类头部，以及喇叭般的嗓音。它可能有角、有翅膀，或两者兼有。尾巴则是龙尾或蝎尾。');
INSERT INTO "tags" VALUES ('g1584','章鱼','cont',11,'这个游戏中有一只或多只[url=http://en.wikipedia.org/wiki/Octopus]章鱼[/url]在故事中扮演重要角色。或者，在多个场景中到处都有章鱼，并有若干相关对话。');
INSERT INTO "tags" VALUES ('g1585','巨型蜘蛛','cont',37,'[url=http://en.wikipedia.org/wiki/Spider]蜘蛛[/url]是呼吸空气的节肢动物，有八条腿和带有毒牙的螯肢，可注射毒液。

请仅将此标签用于[url=http://en.wikipedia.org/wiki/Monster]怪物[/url]，而不是现实存在的蜘蛛物种。');
INSERT INTO "tags" VALUES ('g1586','独角兽','cont',23,'独角兽是源自欧洲民间传说的传奇动物，外形类似白马，前额长有巨大、尖锐、螺旋状的角，有时还有山羊胡和偶蹄。');
INSERT INTO "tags" VALUES ('g1587','带辫子的女主角','cont',426,'这款游戏至少有一位女主角拥有[url=https://en.wikipedia.org/wiki/Braid]编成辫子[/url]的头发。

[url=https://en.oxforddictionaries.com/definition/braid]辫子[/url]（也称发辫）是由三股或更多股头发交织而成的发束。');
INSERT INTO "tags" VALUES ('g1588','灵长类','cont',6,'本游戏中有一个或多个[url=http://en.wikipedia.org/wiki/Primate]灵长类[/url]（人类除外）在故事中扮演重要角色。或者游戏中多处场景都有灵长类（人类除外）出现，并有多条与之相关的对话。');
INSERT INTO "tags" VALUES ('g1589','爬行动物','cont',39,'本游戏中有一个或多个[url=http://en.wikipedia.org/wiki/Reptile?]爬行动物[/url]在故事中扮演重要角色。或者游戏中多处场景都有爬行动物出现，并有多条与之相关的对话。');
INSERT INTO "tags" VALUES ('g1590','鱼','cont',53,'本游戏中有一个或多个[url=http://en.wikipedia.org/wiki/Fish]鱼[/url]在故事中扮演重要角色。或者游戏中多处场景都有鱼出现，并有多条与之相关的对话。');
INSERT INTO "tags" VALUES ('g1591','鸟类','cont',128,'本游戏中有一个或多个[url=http://en.wikipedia.org/wiki/Bird]鸟[/url]在故事中扮演重要角色。或者游戏中多处场景都有鸟出现，并有多条与之相关的对话。');
INSERT INTO "tags" VALUES ('g1593','两栖动物','cont',31,'本游戏中有一个或多个[url=http://en.wikipedia.org/wiki/Amphibian]两栖动物[/url]在故事中扮演重要角色。或者游戏中多个场景都有两栖动物出现，并有数条与之相关的对话。');
INSERT INTO "tags" VALUES ('g1594','吸吮阴茎','ero',68,'本游戏包含怪物或机械对阴茎进行吸吮的场景（非口交）。');
INSERT INTO "tags" VALUES ('g1595','水中性爱','ero',1462,'本故事包含一些在水中进行的性行为：例如海中、河里、浴缸、淋浴等。');
INSERT INTO "tags" VALUES ('g1596','死神英雄','cont',42,'本游戏中的一位或多位英雄是[url=http://en.wikipedia.org/wiki/Shinigami]死神[/url]。

Shinigami（死神，意为“死神”或“死亡之神”）是日本民间传说中的一种实体，负责确保人按规定时间死亡，并引导其灵魂在来世接受审判。在这方面，Shinigami与西方观念中的死神（Grim Reaper）相关。尽管Grim Reaper是单一实体，但多位shinigami常被想象为协同工作。Shinigami是日本民间传说中相对较新的存在。');
INSERT INTO "tags" VALUES ('g1597','植物英雄','cont',10,'本游戏中的一位或多位英雄是有感知能力的植物——他可以是实际移动的植物本身，或者“仅仅”是其化身。');
INSERT INTO "tags" VALUES ('g1598','服务员英雄','cont',50,'本游戏中的一位英雄是[url=http://en.wikipedia.org/wiki/Waiter]服务员[/url]。');
INSERT INTO "tags" VALUES ('g1599','服务员主角','cont',114,'本游戏的主角是[url=http://en.wikipedia.org/wiki/Waiting_staff]服务员[/url]（男/女）。');
INSERT INTO "tags" VALUES ('g1600','漫画大会','cont',28,'[url=http://en.wikipedia.org/wiki/Comiket]Comiket[/url]或类似活动（以戏仿名称出现）在故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g1601','多重人格英雄','cont',38,'本游戏中的一位或多位英雄具有多重人格——这可能是心理原因造成的，也可能是真实的第二人格。');
INSERT INTO "tags" VALUES ('g1602','穿着运动紧身短裤的女主角','cont',137,'本游戏有大量场景可以看到穿着紧身贴合短裤的女孩，这种短裤覆盖大腿大部分区域，或类似的紧身短款腿部衣物。在西方，它们常与骑行联系在一起，英语中称为cycling或[url=http://en.wikipedia.org/wiki/Cycling_shorts]自行车短裤[/url]，但在日本动漫和游戏中主要被称为“Spats”，常被视为常见的运动装。

不要将其与通常穿在裙子下面的长款或透明紧身裤混为一谈，也不要与跑步短裤（更短且不那么贴身）混淆。那些请使用更通用的标签。');
INSERT INTO "tags" VALUES ('g1603','吐槽主角','cont',89,'本游戏中的主人公扮演一个[url=http://en.wikipedia.org/wiki/Manzai#Boke_and_tsukkomi]tsukkomi[/url]的角色。

他们不需要在真实的喜剧二人组中担任tsukkomi。他们只需在日常生活中表现得像tsukkomi，并与表现出boke特质的人物互动。例如，他们可能经常反驳其他角色的滑稽误解。

在执行上与双人喜剧中的“funny man”和“straight man”概念相似，boke和tsukkomi是漫才（日本式喜剧）的一个非常重要的特征。Boke来自动词bokeru，意为“衰老”或“头脑空洞”，并体现在boke易于误解和健忘的倾向上。Tsukkomi一词指的是第二位喜剧演员“插嘴”并纠正boke错误的角色。在表演中，tsukkomi通常会斥责boke，并迅速拍打他们的头部；常用于此目的的传统漫才道具是折叠纸扇。

参见[url=http://en.wikipedia.org/wiki/Manzai]Wikipedia[/url]和[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/BokeAndTsukkomiRoutine]tvtropes[/url]以进一步阅读。');
INSERT INTO "tags" VALUES ('g1604','Boke主角','cont',38,'本游戏中的主人公扮演一个[url=http://en.wikipedia.org/wiki/Manzai#Boke_and_tsukkomi]boke[/url]的角色。

他们不需要在真实的喜剧二人组中担任boke，他们只需在日常生活中表现得像个boke。例如，他们的头脑空洞可能是整个故事中的幽默来源。

注意，boke仍然需要一个tsukkomi来互动。如果你没有tsukkomi，你可能应该使用[url=/g746]天然呆主角[/url]替代。

在执行上与双人喜剧中的“funny man”和“straight man”概念相似，boke和tsukkomi是漫才（日本式喜剧）的一个非常重要的特征。Boke来自动词bokeru，意为“衰老”或“头脑空洞”，并体现在boke易于误解和健忘的倾向上。Tsukkomi一词指的是第二位喜剧演员“插嘴”并纠正boke错误的角色。在表演中，tsukkomi通常会斥责boke，并迅速拍打他们的头部；常用于此目的的传统漫才道具是折叠纸扇。

参见[url=http://en.wikipedia.org/wiki/Manzai]Wikipedia[/url]和[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/BokeAndTsukkomiRoutine]tvtropes[/url]以进一步阅读。');
INSERT INTO "tags" VALUES ('g1605','公主主角','cont',245,'本游戏的主人公是一位[url=http://en.wikipedia.org/wiki/Princess]公主[/url]——她通常穿着礼服（尽管她可能会为战斗穿上盔甲，或为融入环境而穿校服）并戴着王冠。

她不一定非要是西方人，只要符合这形象即可（许多奇幻公主属于这一类，而非姬（Hime）原型）。
与“皇家女英雄”一样，并不需要真正的皇室身份，但贵族身份是必要的。');
INSERT INTO "tags" VALUES ('g1606','贯穿到底','ero',187,'本游戏至少包含一个场景，触手完全穿过整个胃肠道，从肛门进入并从嘴中出来（或反向）。');
INSERT INTO "tags" VALUES ('g1607','伪装英雄','cont',190,'本游戏中的一位或多位英雄在伪装自己的性格。

例如，一位英雄可能显得是个有礼貌的人（总是彬彬有礼、冷静且乐于帮助），但这只是一个伪装，掩盖了他真实的性格——一种更加强硬且容易粗鲁的性格。

注意，这并不一定使英雄变得邪恶或背叛。不要将此标签用于像间谍、刺客等伪装角色。');
INSERT INTO "tags" VALUES ('g1608','修女主角','cont',33,'这个游戏的主角是一位[url=http://en.wikipedia.org/wiki/Nun]修女[/url]。

修女是女性宗教团体的成员，通常立誓遵守贫穷、贞洁和服从..她可能是一个决定奉献一生去服务所有其他生命的人，也可能是一个自愿选择离开主流社会、在修道院或女修道院中以祈祷和冥想度过一生的苦行者。 

术语“修女”适用于天主教徒 – 包括东方和西方传统 – 东正教徒、圣公会教徒、路德宗、耆那教徒、佛教徒、道教徒和印度教徒。');
INSERT INTO "tags" VALUES ('g1609','摩擦','情色',122,'这个游戏包含一个或多个[url=http://en.wikipedia.org/wiki/Frot]摩擦[/url]场景。

“摩擦”是一个俚语，源自frottage（最终来自法语动词frotter，“擦”），描述一种非插入式的男男性行为，通常但不总是涉及直接的阴茎对阴茎接触。');
INSERT INTO "tags" VALUES ('g1610','交叉','cont',182,'这个故事包含一个[url=http://en.wikipedia.org/wiki/Fictional_crossover]交叉[/url]。

虚构交叉是将两个或多个原本独立的虚构角色、设定或宇宙置入同一个故事背景中。它们可能源于相关版权所有者之间的法律协议、粉丝未授权的努力，甚至是在共同企业所有权下产生的。');
INSERT INTO "tags" VALUES ('g1611','旅行者主角','cont',60,'主角是一位[url=http://en.wikipedia.org/wiki/Traveler]旅行者[/url]。

旅行者通常指的是旅行的人，尤其是前往远方的土地。

该术语还包括但不限于流浪者。流浪者是指不断旅行、没有家或工作的人');
INSERT INTO "tags" VALUES ('g1612','富有的英雄','cont',318,'这个游戏中的一个或多个英雄很富有。

[URL=http://en.wikipedia.org/wiki/Wealth]财富[/URL]是宝贵的资源或物质财富的丰富。所述宝贵资源或物质财富的常见例子是金钱、珠宝和房地产。');
INSERT INTO "tags" VALUES ('g1613','牧师英雄','cont',75,'这个游戏中的一个或多个英雄是[url=http://en.wikipedia.org/wiki/Priest]牧师[/url]。

祭司或女祭司是授权执行宗教神圣仪式的人，尤其是作为人类与一个或多个神祇之间的中介。他们也有权威或权力执行宗教仪式；特别是向神祇献祭和求情的仪式。');
INSERT INTO "tags" VALUES ('g1614','基于真实人物的英雄','cont',184,'这部小说中至少有一位英雄（不要与主角混淆）基于真实的历史人物。');
INSERT INTO "tags" VALUES ('g1615','大和抚子主角','cont',18,'这部小说的主角是一位[url=http://en.wikipedia.org/wiki/Yamato_Nadeshiko]大和抚子[/url]。

大和抚子是一个日语术语，意为“理想化日本女性的化身”，或“纯粹女性美的典型”。');
INSERT INTO "tags" VALUES ('g1616','穿着和服的主角','cont',72,'这个故事的主角大部分时间穿着[url=http://en.wikipedia.org/wiki/Kimono]和服[/url]。

和服是日本传统服饰，男女和儿童均可穿着。单词“kimono”字面意思是“穿戴之物”（ki“穿”和mono“物”），[2]已经用来指代这些长袍。');
INSERT INTO "tags" VALUES ('g1618','鬼主角','cont',17,'这个游戏中的主角是一个[url=http://en.wikipedia.org/wiki/Oni]鬼[/url]。

鬼是日本民间传说中的生物，可译为恶魔、魔鬼、食人魔或巨魔。它们是日本艺术、文学和戏剧中受欢迎的角色。

对鬼的描绘各不相同，但通常将它们描绘成丑陋、巨大、类似食人魔的生物，长着利爪、乱发和从头上长出的两根长角。它们大部分是人形的，但偶尔也会出现不自然的特征，例如奇数只眼睛或多余的指头。它们的皮肤可以是任意颜色，但红色和蓝色特别常见。

不要与恶魔主角标签混淆，“鬼”在日本民间传说中不仅指恶魔。');
INSERT INTO "tags" VALUES ('g1619','武士英雄','cont',54,'这部视觉小说的英雄是或曾经是一位[url=http://en.wikipedia.org/wiki/Samurai]武士[/url]。

不要将本标签用于那些角色行事方式符合[url=http://en.wikipedia.org/wiki/Bushid%C5%8D]武士道[/url]但未获得正式头衔的游戏。');
INSERT INTO "tags" VALUES ('g1620','鬼英雄','cont',41,'本游戏中的一个或多个主角是[url=http://en.wikipedia.org/wiki/Oni]鬼[/url]。

鬼是日本民间传说中的生物，有多种译法，如恶魔、魔鬼、食人魔或巨魔。它们是日本艺术、文学和戏剧中常见的人物。

对鬼的描绘差异很大，但通常将其描绘成可怕、巨大的食人魔般的生物，长有锋利的爪子、蓬乱的头发和从头上长出的两根长角。它们大部分是人形的，但偶尔也会显示出不自然的特征，如奇数只眼睛或多余的指头。它们的皮肤可以是任何颜色，但红色和蓝色尤为常见。

不要与“恶魔主角”标签混淆，“鬼”涵盖的不仅仅是日本民间传说中的恶魔。');
INSERT INTO "tags" VALUES ('g1621','怪物猎人主角','续',99,'主角是一名[url=http://en.wikipedia.org/wiki/Monster]怪物[/url]猎人。');
INSERT INTO "tags" VALUES ('g1623','蜡油Play','色情',394,'本游戏包含一个或多个涉及[url=http://en.wikipedia.org/wiki/Wax_play]蜡油play[/url]的场景。

蜡油play是一种感官游戏，涉及温热或滚烫的蜡，通常从蜡烛滴下或用勺子浇在人的裸露皮肤上。蜡油play可与其他BDSM或性行为结合。');
INSERT INTO "tags" VALUES ('g1624','有纹身的女主角','续',397,'本游戏的女主角带有[url=http://en.wikipedia.org/wiki/Tattoo]纹身[/url]。

纹身是一种身体改造形式，通过将不可磨灭的墨水注入皮肤真皮层来改变色素。');
INSERT INTO "tags" VALUES ('g1625','御宅族主角','续',62,'其中一个主角是动漫（角色扮演/漫画/电子游戏）御宅族，意思是他沉迷于这个爱好，通常是无害的。');
INSERT INTO "tags" VALUES ('g1626','蛰居族女主角','续',66,'带有此标签的游戏有一个曾经或现在仍是[url=http://en.wikipedia.org/wiki/Hikikomori]蛰居族[/url]的女主角。

“蛰居族”是一个日语术语，指隐居的青少年或年轻人从社会生活中退缩的现象，他们往往寻求极度的孤立和幽禁。该术语既指这种普遍的社会学现象，也指属于这一社会群体的人。');
INSERT INTO "tags" VALUES ('g1627','百合NTR','色情',26,'包含主角的女性伴侣被另一个女性夺走的场景的游戏，应给予此标签。

需要注意的是，由于“女孩间亲密很性感”这一套路普遍存在，许多视觉小说在女主角和另一个女性之间加入百合场景很常见。大多数情况下，这并不被视为NTR，因为主角不介意甚至鼓励其伴侣进行百合探索。只有当一个女性明确有夺取女主角的意图，并且主角产生了嫉妒等与寝取（netorare）情结相关的负面情绪时，才应使用此标签。');
INSERT INTO "tags" VALUES ('g1628','中二病主角','续',33,'本游戏的主角患有[url=http://www.urbandictionary.com/define.php?term=Chuunibyou]中二病[/url]。

[url=http://en.dic.pixiv.net/a/Chuunibyou]中二病[/url]或“中学二年级综合征”，是日本一个口语化且略带贬义的术语，用来形容十四岁左右的人，要么表现得像个无所不知的成年人，要么认为自己拥有别人没有的特殊能力。有些人甚至会令人讨厌、傲慢，并且经常瞧不起成年人或年长者。这种思维或行为方式多见于青春期的青少年，但也有一些人成年后仍然如此。

不要将此标签用于这种思维或行为对设定来说很自然的情况（例如，在具有实际魔法力量的幻想世界中的魔法少女女主角）。只有在这种行为显得不合时宜时才使用。');
INSERT INTO "tags" VALUES ('g1629','中二病女主角','续',97,'本游戏中的一位女主角患有[url=http://www.urbandictionary.com/define.php?term=Chuunibyou]中二病[/url]。

[url=http://en.dic.pixiv.net/a/Chuunibyou]中二病[/url]或“中学二年级综合征”，是日本一个口语化且略带贬义的术语，用来形容十四岁左右的人，要么表现得像个无所不知的成年人，要么认为自己拥有别人没有的特殊能力。有些人甚至会令人讨厌、傲慢，并且经常瞧不起成年人或年长者。这种思维或行为方式多见于青春期的青少年，但也有一些人成年后仍然如此。

不要将此标签用于这种思维或行为对设定来说很自然的情况（例如，在具有实际魔法力量的幻想世界中的魔法少女女主角）。只有在这种行为显得不合时宜时才使用。');
INSERT INTO "tags" VALUES ('g1630','偶像主角','续',68,'这款游戏的主角是一名[url=http://en.wikipedia.org/wiki/Japanese_idol]偶像[/url]。

在日本文化中，偶像是十几岁到二十出头的媒体人物，被认为特别有吸引力或可爱，并且会在从几个月到几年的时间里定期出现在大众媒体中，例如作为流行乐队歌手、小角色演员、电视名人（tarento）、杂志写真模特、广告等。');
INSERT INTO "tags" VALUES ('g1631','高科技性爱引擎','色情',124,'这部视觉小说包含至少一个性爱场景，其中角色与精致、高科技和/或魔法科技机器发生性行为。

请不要将此标签用于：
 - 常规性爱器具
 - 现实生活中的性爱机器，如sybians、[url=https://s2.vndb.org/sf/74/159374.jpg]假阳具推进机[/url]或[url=/g3045]钻头假阳具[/url]
 - 描述与[url=https://vndb.org/i458]机器人[/url]、[url=https://vndb.org/i459]半机械人[/url]或类似性质的角色发生性行为');
INSERT INTO "tags" VALUES ('g1632','大叔主角','内容',136,'这部小说的主角是一名老年（或较年长）男性。');
INSERT INTO "tags" VALUES ('g1633','受虐狂女主角','内容',323,'这部视觉小说中至少有一位女主角是[url=http://en.wikipedia.org/wiki/Sadomasochism]受虐狂[/url]。');
INSERT INTO "tags" VALUES ('g1634','意志薄弱的女主角','内容',37,'这个故事的女主角很容易被他人指使，尤其是被她情感上依恋的人指使，并且通常容易被潮流、事件和其他事情冲昏头脑。 

这种类型的女主角很难独立思考，更难以将自己的想法付诸行动。即使她真的行动了，也很容易被阻碍而改变行动方向。');
INSERT INTO "tags" VALUES ('g1635','龙英雄','内容',93,'这部小说中至少有一位英雄是[url=http://en.wikipedia.org/wiki/Dragon]龙[/url]。这包括那些是龙但（通过魔法或其他方式）化为人形的英雄。

龙是一种传说中的生物，通常具有蛇形或爬行动物的特征，出现在许多文化的神话中。');
INSERT INTO "tags" VALUES ('g1636','管家女主角','内容',10,'游戏中的一位女主角是[url=http://en.wikipedia.org/wiki/Butler]管家[/url]。

管家是大宅中的家政工人。在豪门大宅中，家庭有时会分为多个部门，由管家负责餐厅、酒窖和餐具室。有些管家还负责整个客厅楼层，而女管家则负责整栋房屋及其外观。管家通常是男性，负责管理男仆；而女管家通常是女性，负责管理女仆。传统上，男性仆人（如贴身男仆）较为稀少，因此比女性仆人薪水更高、地位更高。管家作为高级男仆，拥有最高的仆人地位。');
INSERT INTO "tags" VALUES ('g1637','近代早期地球','内容',57,'这款游戏中的场景设定在近代早期（16世纪至19世纪）。');
INSERT INTO "tags" VALUES ('g1638','女友突然出现','内容',71,'这个故事涉及主角生活的突然改变，他突然面临一个让自己产生性吸引的人，结果两人不可避免地成为情侣。

当这种情况突然发生、没有任何铺垫，主角一生的挚爱凭空出现时，请使用此标签。');
INSERT INTO "tags" VALUES ('g1639','贫乳主角','内容',26,'这款游戏的主角胸围非常小。

此标签与萝莉主角标签不同，请不要将两者混淆。');
INSERT INTO "tags" VALUES ('g1640','怪物强奸','色情',2056,'这款游戏包含一个或多个涉及[url=http://en.wikipedia.org/wiki/Monster]怪物[/url]的强奸场景。

例子可能包括狼人、龙（非人形）、奇美拉和其他奇幻野兽。

外表与正常同类没有显著差异的恶魔动物，通常应归入[url=http://vndb.org/g183]兽交[/url]。');
INSERT INTO "tags" VALUES ('g1642','四个或更多选项的选择','技术',586,'游戏包含提供4个或更多选项的选择（相对于更常见的2或3个选项）。此标签没有上限。

此标签不适用于[url=http://vndb.org/g297]地图移动[/url]或带有RPG元素的游戏中的战斗行动选择；它仅适用于影响路线选择的实际选择。');
INSERT INTO "tags" VALUES ('g1643','多选选择','技术',121,'游戏包含允许你从同一列表中选择多个答案的选项，可以一次性选择，也可以连续选择。

一个常见的例子是，你可能会被要求寻找某物，然后看到一个可能藏有该物的几个地点列表，如果你选错了，但主角还有时间，你会被再次询问是否想去其他地方看看。（你最终可能不必选择列表中的每个选项，也可能必须选择。）

第二个常见的例子是审讯场景，你必须质问某人——可能是你自己，试图回忆某事，这时你会看到一个需要思考的事项列表。（同样，你最终可能不必选择列表中的每个选项，也可能必须选择；可能会有“我完成了”选项。）

第三个例子是，你需要执行一项团队任务，并被询问希望得到哪2位或更多其他女主的帮助。这可能决定从任务成功到你所选择的每个人获得关系值的任何结果。

不要将此标签用于[url=http://vndb.org/g297]地图移动[/url]，或带有RPG元素的游戏中的成员选择。');
INSERT INTO "tags" VALUES ('g1644','与怪物的自愿性行为','色情',509,'本游戏包含与非人类、非动物的虚构生物之间的自愿性爱场景。');
INSERT INTO "tags" VALUES ('g1645','自愿性奴役（合意）','色情',159,'在[url=http://en.wikipedia.org/wiki/Sexual_slavery_%28BDSM%29]性奴役[/url]的这种形式中，就BDSM而言，奴役是指支配者将顺从者作为财产拥有。这是个体之间自愿的权力交换。

在“支配与顺从”（也称为D&s、Ds或D/s）的情色或生活方式背景下，所进行活动的类型通常事先明确界定，有时会在所谓的‘奴隶契约’中详细说明，该契约是一份不具法律约束力的文件，概述了所有相关方的欲望、限制和期望。
通常会明确列出期望，即伴侣双方是一夫一妻制还是多伴侣制，以及是否允许/期望与他人发生性行为。
否则，性奴通常需要履行许多与顺从者相同的职能，包括穿着非常暴露的衣服、佩戴项圈和/或牵引绳、被分享、参与S&M或束缚活动。');
INSERT INTO "tags" VALUES ('g1646','多样化的标题画面','技术',813,'游戏的标题画面会在游戏过程中通过完成路线、达成结局、结束章节或由于某些其他随机变量而变化。它可以有不同的颜色/色调，引入新的元素/角色，将白天的画面改为夜晚，甚至呈现一幅全新的图像。');
INSERT INTO "tags" VALUES ('g1647','体育老师女主','内容',55,'游戏中的一位女主是[url=http://en.wikipedia.org/wiki/Physical_education]体育[/url][url=http://en.wikipedia.org/wiki/Teacher]老师[/url]。

体育是中小学教育期间开设的一门课程，鼓励在游戏或运动探索环境中进行心理运动学习。');
INSERT INTO "tags" VALUES ('g1648','游戏玩家女主','内容',269,'其中一位女主是电子游戏的狂热玩家，即[url=http://en.wikipedia.org/wiki/Gamer]游戏玩家[/url]。

从历史上看，“gamer”一词通常指玩角色扮演游戏和战争游戏的人。自从这些游戏变得非常流行以来，这个词已包括电子游戏玩家。虽然该词名义上包括那些不一定认为自己属于玩家的人（即休闲玩家），但通常用来指那些在闲暇时间花大量时间游玩或学习游戏的人。');
INSERT INTO "tags" VALUES ('g1650','双性恋女主','内容',445,'其中一位女主在性方面或浪漫方面同时被女性和男性所吸引。这一点通过她在游戏中的行为表现出来。她在这方面的性经验与此标签无关。

此标签适用于从开始就对女性和男性都表现出兴趣的女主。对于最初只对女性感兴趣的角色，请使用“女同性恋女主”标签。');
INSERT INTO "tags" VALUES ('g1651','可更换服装','技术',540,'在本游戏中，玩家可以更换角色的服装。通常此功能在游戏的后期阶段甚至二周目时才可用。

请不要将此标签与“cosplay”标签混淆，因为后者是关于角色按照自己的意愿更换服装，而不是由玩家意愿决定。');
INSERT INTO "tags" VALUES ('g1653','卖淫主角','内容',31,'游戏中的一位主角从事[url=http://en.wikipedia.org/wiki/Prostitution]以性行为换取金钱[/url]的活动。');
INSERT INTO "tags" VALUES ('g1654','间谍主角','内容',43,'本游戏中的一位主角是秘密特工或为政府或私人团体工作的[URL=http://en.wikipedia.org/wiki/Spy]间谍[/URL]。他拥有许多技能和许多秘密。

间谍活动或刺探情报涉及政府或个人在未经信息持有者许可的情况下获取被视为秘密或机密的信息。间谍活动本质上是秘密进行的，因为人们理所当然地认为它不受欢迎，而且在许多情况下是非法并受法律惩罚的。');
INSERT INTO "tags" VALUES ('g1655','模特主角','内容',45,'带有此标签的游戏中的一个或多个主角是职业[URL=http://en.wikipedia.org/wiki/Model_%28profession%29]模特[/URL]。');
INSERT INTO "tags" VALUES ('g1656','模特女主角','cont',148,'带有此标签的游戏中的一个或多个女主角是职业[URL=http://en.wikipedia.org/wiki/Model_%28profession%29]模特[/URL]。');
INSERT INTO "tags" VALUES ('g1657','兄控支援角色','cont',35,'游戏中的一位支援角色是兄控，一个总是对兄弟充满热情并愿为他做任何事的人。

通常作为喜剧因素。');
INSERT INTO "tags" VALUES ('g1658','桌游','tech',37,'带有此标签的游戏具有类似[URL=http://en.wikipedia.org/wiki/Board_game]桌游[/URL]的主要游戏风格，或包含实现桌游玩法的时刻。

桌游是一种游戏，涉及根据一套规则在预先标记的表面或"棋盘"上移动或放置棋子或标记。游戏可以基于纯策略、运气（如掷骰子）或两者混合，并且通常有一个玩家努力实现的目标。');
INSERT INTO "tags" VALUES ('g1659','懒惰女主角','cont',78,'其中一位女主角很懒惰，她完全没有动力去做任何事，或者做事时三心二意。');
INSERT INTO "tags" VALUES ('g1660','吐槽役女主角','cont',38,'本游戏中的一位女主角扮演[url=http://en.wikipedia.org/wiki/Manzai#Boke_and_tsukkomi]吐槽役[/url]的角色。

她们不需要是真正喜剧组合中的吐槽役。她们只需在日常生活中表现得像吐槽役，并与表现出呆角特质的角色互动。例如，她们可能经常反驳其他角色的滑稽误解。

在执行方式上，类似于双人喜剧中的"funny man"和"straight man"概念，呆角和吐槽役是漫才（日本喜剧风格）的一个非常重要的特征。呆角（boke）来自动词"bokeru"，意为"senility"或"air headed-ness"，体现在呆角容易误解和健忘的倾向上。吐槽役（tsukkomi）指第二位喜剧演员在"butting in"并纠正呆角错误时所扮演的角色。在表演中，吐槽役常常责骂呆角并迅速扇打其头部；一个常用于此目的的传统漫才道具是折纸扇。

更多内容请参见[url=http://en.wikipedia.org/wiki/Manzai]维基百科[/url]和[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/BokeAndTsukkomiRoutine]tvtropes[/url]。');
INSERT INTO "tags" VALUES ('g1661','呆角女主角','cont',26,'本游戏中的一位女主角扮演[url=http://en.wikipedia.org/wiki/Manzai#Boke_and_tsukkomi]呆角[/url]的角色。

她们不需要是真正喜剧组合中的呆角。她们只需在日常生活中表现得像个呆角。例如，她们的发呆可能是整个故事中的幽默来源。

请注意，呆角仍然需要吐槽役来互动。如果你没有吐槽役，你可能需要使用[url=/g190]天然呆女主角[/url]来代替。

在执行方式上，类似于双人喜剧中的"funny man"和"straight man"概念，呆角和吐槽役是漫才（日本喜剧风格）的一个非常重要的特征。呆角（boke）来自动词"bokeru"，意为"senility"或"air headed-ness"，体现在呆角容易误解和健忘的倾向上。吐槽役（tsukkomi）指第二位喜剧演员在"butting in"并纠正呆角错误时所扮演的角色。在表演中，吐槽役常常责骂呆角并迅速扇打其头部；一个常用于此目的的传统漫才道具是折纸扇。

更多内容请参见[url=http://en.wikipedia.org/wiki/Manzai]维基百科[/url]和[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/BokeAndTsukkomiRoutine]tvtropes[/url]。');
INSERT INTO "tags" VALUES ('g1662','黑白','tech',776,'这部视觉小说的画面是[url=http://en.wikipedia.org/wiki/Black-and-white]黑白[/url]的。

“黑白”作为一种描述可能被认为用词不当，因为图像通常不是黑白分明、强烈对比，而是将黑白连续混合，产生一系列深浅不一的灰色调。

请仅在整部视觉小说（或至少大部分内容）为黑白画面时使用此标签。不要将其用于只有简短黑白场景（例如闪回）的视觉小说。');
INSERT INTO "tags" VALUES ('g1663','寝取らせ','成人',265,'通过主角的故意作为/不作为，或与伴侣达成协议，在这部视觉小说中，其忠实伴侣最终与他人发生性关系。只有主角的伴侣（无论男女）与其他人发生性行为。

在正常情况下，伴侣双方都没有出轨的欲望，但由于主角的欲望，其伴侣最终会与他人发生性关系。这可以是与一个值得信任的人达成的双方同意的行为，即伴侣说服其伴侣与之发生性关系；也可以是一种自私的行为，即伴侣为了个人利益（金钱、敲诈材料等）而出卖或利用其伴侣。

在任何情况下，主角（至少最初）都对其伴侣与他人发生性关系持无所谓态度，甚至可能乐在其中。

不要与[url=/g1710]交换伴侣[/url]混淆，后者是双方恋爱伴侣都与他人发生性行为；也不要与[url=/g2141]多角恋[/url]混淆，后者是一种长期的、涉及浪漫感情的协议；而寝取らせ是一种瞬间满足癖好的行为。');
INSERT INTO "tags" VALUES ('g1664','神秘学社团','续',81,'[url=http://en.wikipedia.org/wiki/Occult]神秘学[/url]社团及其相关活动在故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g1665','同事女主角','续',151,'其中一位女主角与主角在同一个地方工作，无论是偶尔还是长期。');
INSERT INTO "tags" VALUES ('g1667','滥交','成人',862,'这部视觉小说展现了[url=https://en.wikipedia.org/wiki/Promiscuity]滥交[/url]行为，即角色与多个伴侣发生性行为，但并不与他们建立恋爱关系。

角色也可能在保持恋爱关系的同时与其他角色发生性接触，但这一点并不会显著改变原有关系。

注意：请勿将其与[url=http://vndb.org/g179]群体性行为[/url]混淆，与多个伴侣的性接触不一定发生在同一场景中。');
INSERT INTO "tags" VALUES ('g1668','巫女主角','续',98,'本游戏的主角是一位[url=http://en.wikipedia.org/wiki/Miko]巫女[/url]。传统服装很常见，但不是严格必需。');
INSERT INTO "tags" VALUES ('g1669','木马','成人',259,'这部视觉小说包含使用[url=http://en.wikipedia.org/wiki/Wooden_horse_%28device%29]木马[/url]的场景。

这些设备既可用于折磨受害者，也可作为BDSM场景的一部分。');
INSERT INTO "tags" VALUES ('g1671','仅有一个好结局','技术',675,'本游戏只有一个好结局，其余结局均为坏结局。根据故事不同，坏结局的数量可能多也可能少，但无论结局总数如何，只有一个结局是好的。

请勿将其与[url=http://vndb.org/g181]唯一真结局[/url]混淆，后者可能有多好坏结局，但只有一个真结局。');
INSERT INTO "tags" VALUES ('g1673','嫉妒','续',2740,'当所爱之人与其他角色调情，或成为他人调情的对象，或因其他可能在恋爱关系中引发嫉妒的原因时，本游戏中的某些角色会感到嫉妒。

仅在嫉妒是游戏情节重要组成部分时才使用此标签。');
INSERT INTO "tags" VALUES ('g1674','有性经验的女主角','续',169,'在这部视觉小说中，一位或多位女主角在故事开始前已有性经验，或者她们仍保持活跃的性生活。此标签适用于那些在与主角发生关系时并非处女的女主角。');
INSERT INTO "tags" VALUES ('g1675','城市建设游戏','技术',12,'本游戏融入了[url=http://en.wikipedia.org/wiki/Construction_and_management_simulation]建设与经营模拟[/url]游戏的某些方面。

建设与经营模拟是一种模拟游戏，玩家在其中利用有限资源建造、扩展或管理虚构社区或项目。');
INSERT INTO "tags" VALUES ('g1676','哔声审查','技术',444,'这部视觉小说会用哔声屏蔽某些词语。

[url=http://en.wikipedia.org/wiki/Bleep_censor]哔声审查[/url]（即\"哔声\"）是用哔哔声替代粗俗用语或机密信息的手法。
哔声屏蔽在英语和日语广播中常用，但在其他一些语言中很少使用。');
INSERT INTO "tags" VALUES ('g1677','人鱼男主角','续',57,'本作中有一位或多位男主角是[url=http://en.wikipedia.org/wiki/Merman]男性人鱼[/url]。

男性人鱼是神话中与美人鱼相对应的雄性形态——传说生物，上半身为人形男性，下半身似鱼，没有双腿，长着带鳞片的鱼尾。');
INSERT INTO "tags" VALUES ('g1678','人造人支援角色','cont',26,'本作中有一位或多位支援角色是[url=http://en.wikipedia.org/wiki/Homunculus]人造人[/url]。

人造人是一种通过魔法和/或科学获得生命的人工人类。');
INSERT INTO "tags" VALUES ('g1679','渔夫女主角','cont',9,'本作中的一位女主角是[url=http://en.wikipedia.org/wiki/Fisherman]渔夫[/url]。');
INSERT INTO "tags" VALUES ('g1680','三胞胎支援角色','cont',10,'本作中至少有一组[url=http://en.wikipedia.org/wiki/Multiple_birth#Higher_order_multiples]三胞胎[/url]作为支援角色。');
INSERT INTO "tags" VALUES ('g1681','超人类主义','cont',67,'通过控制论、基因改造等科技手段人为改变人类状态的概念，以及认为这种行为值得推崇的文化运动。这可以包括在人脑中植入装置、使用假肢部件、改变人的基因，或者为了增强某些特征而进行人类选择性繁殖，同时也包括认定这类行为对整个社会而言正确有益的社会运动。');
INSERT INTO "tags" VALUES ('g1685','公共交通上的猥亵','ero',295,'带有此标签的游戏中有位或多位角色在拥挤的公共交通工具上被猥亵。

这在日本是一种常见的性骚扰形式（大多发生在电车上），因为日本公共交通系统极为拥挤。');
INSERT INTO "tags" VALUES ('g1687','完全可避免的主角强暴','ero',74,'你可以看到游戏的所有“正式结局”，而不会经历任何主角被强奸的场景。这些主角的强奸场景仅出现在提前的坏结局中，你无须阅读它们即可进入其他结局。');
INSERT INTO "tags" VALUES ('g1689','共同路线中的破处','ero',218,'本作在共同路线中至少出现一次失去童贞的情节；换句话说，在进入特定恋爱对象的分支之前。此标签不适用于只有单条恋爱线的游戏。');
INSERT INTO "tags" VALUES ('g1690','姐妹丼结局','tech',320,'姐妹丼（Shimai Donburi）是一个日语术语，描述一个人同时与姐妹两人发生关系（通常指性方面）的情形。在本标签中，如果游戏结束时主角同时与两姐妹保持恋爱关系（且姐妹双方都知情），则适用此标签。

最好（但不是必须）有同时包含两位女主角和主角的H场景。');
INSERT INTO "tags" VALUES ('g1691','母女丼结局','tech',341,'母女丼（Oyako Donburi）是一个日语术语，描述一个人同时与母亲和女儿发生关系（通常指性方面）的情形。在本标签中，如果游戏结束时主角同时与母女俩保持恋爱关系（且双方都知情），则适用此标签。 

最好（但不是必须）有同时包含两位女主角和主角的H场景。');
INSERT INTO "tags" VALUES ('g1692','足球','cont',32,'[url=http://en.wikipedia.org/wiki/Soccer]足球[/url]在本作的故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g1693','无血缘关系的母女乱伦','ero',21,'这些游戏包含无血缘关系的母女之间的性爱场景。');
INSERT INTO "tags" VALUES ('g1694','兄控主角','cont',29,'本作的主角是兄控，即总是对自己的哥哥（通常是主要角色之一）充满热情，并愿意为他做任何事的人。');
INSERT INTO "tags" VALUES ('g1695','可解锁的额外内容','tech',804,'在完成游戏或其某一部分后，会解锁额外内容。例如，声优访谈、壁纸、工作人员评论、迷你游戏。

大多数视觉小说在通关后允许你从主菜单重新查看游戏中的图片或场景，因此这些不计入此标签。');
INSERT INTO "tags" VALUES ('g1696','可怕的主角','cont',14,'这种主角外表可怕，常人会避而远之。 

在很多情况下，他其实只是个普通人，往往甚至心地善良，但由于他的长相，周围的人会认为他是不良少年之类的人物。在游戏开始时，他大多数时候几乎没有朋友，只有那些足够亲近他的人才会了解他的真实自我，无论好坏。 

此外，他的外表常常会引起与其他角色，尤其是女主角们的误解，这可能导致其中一位女主角对他成为[url=/http://vndb.org/g194]经典傲娇[/url]。

他也可能装成别人以为的样子，或者他确实像他看起来那样坏，但关键是他的外表，人们第一眼看到他就会害怕/产生坏印象。那些因其他原因而非外貌被畏惧的角色，或故意摆出可怕外表的角色不算在内。

这类角色一个非常著名的例子就是轻小说[url=/http:/http://en.wikipedia.org/wiki/Toradora!]龙与虎[/url]中的高须龙儿。');
INSERT INTO "tags" VALUES ('g1697','血亲父子乱伦','ero',20,'这些游戏包含有血缘关系的父亲与儿子之间的性爱场景。');
INSERT INTO "tags" VALUES ('g1698','血亲兄弟乱伦','ero',37,'这些游戏包含有血缘关系的兄弟之间的性爱场景。');
INSERT INTO "tags" VALUES ('g1699','夏洛克·福尔摩斯','cont',22,'这些游戏以[url=http://en.wikipedia.org/wiki/Arthur_Conan_Doyle]阿瑟·柯南·道尔爵士[/url]的系列故事中的角色为特色，主角是[url=http://en.wikipedia.org/wiki/Sherlock_Holmes]夏洛克·福尔摩斯[/url]。这些角色可能包括但不限于夏洛克·福尔摩斯、约翰·华生、莫里亚蒂、哈德森太太和艾琳·艾德勒。

故事很可能围绕谜团和侦探工作展开。');
