INSERT INTO "tags" VALUES ('g1710','交换伴侣','ero',112,'[url=http://en.wikipedia.org/wiki/Swinging]交换伴侣[/url]或（很少见的）伴侣交换是一种非一夫一妻制行为，在这种行为中，单身人士或处于稳定关系的伴侣与他人进行性活动，作为娱乐或社交活动。

交换伴侣可以发生在多种场合，从朋友非正式聚会中的自发性性行为，到定期计划的社会聚会，再到在交换伴侣俱乐部与志同道合的人勾搭。它还可能涉及基于互联网的线上交换伴侣社交网络服务。

较旧的术语“妻子交换”（wife-swapping），曾被视为等同于“交换伴侣”（swinging），如今却被批评为以男性为中心，因为它假定伴侣是一对已婚的异性恋夫妇，并且由男性控制性活动，同时它也不能准确描述单身人士或夫妻可能参与的全部性活动范围。

注意：不要将交换伴侣与[url=http://vndb.org/g1380]通奸[/url]混淆。');
INSERT INTO "tags" VALUES ('g1713','怀孕结局','tech',927,'游戏有一个角色怀孕的结局。
不一定要显示受孕或任何性爱场景。');
