INSERT INTO "tags" VALUES ('g1716','来自其他媒体','cont',1788,'这些标签用于包含其他现有媒体设定或角色的游戏。');
INSERT INTO "tags" VALUES ('g1717','虐待狂男主角','cont',93,'这部视觉小说中至少有一位男主角是[url=http://en.wikipedia.org/wiki/Sadomasochism]虐待狂[/url]。');
INSERT INTO "tags" VALUES ('g1718','皮条客/老鸨主角','cont',21,'人口贩子，也称为皮条客或老鸨，利用受害者的脆弱和缺乏机会，同时承诺婚姻、就业、教育和/或更好的生活。
然而，最终，人口贩子强迫受害者成为妓女或从事性行业。
性行业中的各种工作包括卖淫、在脱衣舞俱乐部跳舞、出演色情电影和色情作品，以及其他形式的非自愿劳役。

[url=http://en.wikipedia.org/wiki/Pimp]皮条客[/url]是妓女的代理（通常是男性），从她们的收入中收取一部分。这种行为被称为拉皮条或介绍卖淫。皮条客可能因为提供广告服务、人身保护，或者提供（甚至垄断）一个他或她（即妓女）可以接客的场所而获得这笔钱。

经营妓院的女性被称为老鸨（madam），而不是皮条客。

皮条客与妓女之间的关系可能是虐待性和占有性的，皮条客/老鸨会使用心理恐吓、操纵、饥饿、强奸和/或轮奸、殴打、监禁、威胁对受害者家属施暴、强迫吸毒以及这些行为带来的羞耻感等手段。');
INSERT INTO "tags" VALUES ('g1719','Bodyguard Hero','cont',77,'这款游戏的主角是一名[url=http://en.wikipedia.org/wiki/Bodyguard]保镖[/url]。');
INSERT INTO "tags" VALUES ('g1720','Cook Hero','cont',110,'这款游戏中的主角之一是一名[url=http://en.wikipedia.org/wiki/Cook_%28profession%29]厨师[/url]。');
INSERT INTO "tags" VALUES ('g1722','Thief Hero','cont',65,'这款游戏的主角是一名职业[url=http://en.wikipedia.org/wiki/Thief]小偷[/url]。');
INSERT INTO "tags" VALUES ('g1723','Combat Sport','cont',116,'[url=http://en.wikipedia.org/wiki/Combat_sport]格斗运动[/url]或搏击运动是一种竞技性接触运动，两名选手根据特定的直接对抗规则互相搏斗，以获得足够分数或达到某种条件来判定唯一胜者。这些对抗规则和条件与为技术挑战、练习或武术演示而设计的模拟接触或格斗规则大不相同，后者通常旨在通过套路和自卫训练模拟真实徒手搏斗的部分内容。

拳击、踢拳、业余摔跤、柔道、综合格斗、泰拳和剑术都是格斗运动的例子。');
INSERT INTO "tags" VALUES ('g1724','Only Protagonist''s Sisters as Heroine(s)','cont',433,'游戏中的所有女主角都是主角的姐妹。');
INSERT INTO "tags" VALUES ('g1725','Photographer Hero','cont',47,'这款游戏中的主角之一是一名摄影师。');
INSERT INTO "tags" VALUES ('g1726','Beautician Hero','cont',23,'这款游戏中至少有一位主角是美容师，他可能在一家美容院工作。

这可以包括发型师、美容师和美甲师。');
INSERT INTO "tags" VALUES ('g1727','Rape Roleplay','ero',58,'这款游戏包含一个或多个性爱场景，其中在参与者自愿的情况下演绎强奸情节。');
INSERT INTO "tags" VALUES ('g1729','Siscon Hero','cont',50,'至少有一位主角是妹控，即一个总是对妹妹（通常是主角）充满热情，愿意为她做任何事的人。');
INSERT INTO "tags" VALUES ('g1730','Protagonist''s Twin as a Hero','cont',28,'这些游戏以主角的双胞胎兄弟为主角。与[url=/g1114]双胞胎兄弟主角[/url]不同，他们是主角的双胞胎兄弟，而不仅仅是随机的双胞胎兄弟。');
INSERT INTO "tags" VALUES ('g1731','Living Doll Support Character','cont',39,'其中一个支持角色是活人偶，就像《蔷薇少女》中的那样。');
INSERT INTO "tags" VALUES ('g1732','Modern Day Canada','cont',45,'故事的大部分情节发生在现代[url=http://en.wikipedia.org/wiki/Canada]加拿大[/url]。
注意：“现代”指的是20世纪末至今天之间的一段未指明的时间段。');
INSERT INTO "tags" VALUES ('g1733','Long Common Route','tech',277,'这款游戏有一条相当长的公共路线，然后才切换到个人路线。一条路线可以被定义为“长”，是因为它在小说总长度中占显著比例，以及主观感受。');
INSERT INTO "tags" VALUES ('g1734','Mirror Sex','ero',332,'带有此标签的视觉小说至少包含一个在镜子或任何其他反光表面前进行性活动的场景。

当性活动的重要焦点涉及反射影像时，应使用此标签。如果只是偶然出现反射，则不应使用此标签。');
INSERT INTO "tags" VALUES ('g1735','Standing Sex','ero',3193,'这款游戏中有角色在性交场景中使用[URL=http://en.wikipedia.org/wiki/Sex_positions#Standing]站立姿势[/URL]的场景。

在基本的站立姿势中，双方面对面站立进行阴道性交。为了匹配身高，较矮的一方可以站在台阶上或穿高跟鞋。如果女性背靠墙壁，可能更容易保持有力的抽送。或者，插入方站立，接受方手臂环抱其颈部，双腿环住其腰部，从而将阴道或肛门暴露给男性的阴茎。');
INSERT INTO "tags" VALUES ('g1736','Sitting Sex','ero',3227,'这款游戏包含角色在做爱场景中采用[URL=http://en.wikipedia.org/wiki/Sex_positions#Sitting_and_kneeling]坐姿[/URL]的场面。

在坐姿中，插入方坐在某个平面上，双腿伸展。接受方背对插入方坐在其上方。');
INSERT INTO "tags" VALUES ('g1737','汤匙式','色情',1240,'这款游戏包含角色在做爱场景中采用[URL=http://en.wikipedia.org/wiki/Spoons_sex_position]汤匙式[/URL]的场面。

在性爱汤匙式中，插入方侧卧，双膝弯曲。接受方也侧卧于同一侧，背部贴在插入方的胸前。双方的上半身可以贴在一起，也可以分开，仅让骨盆相连；双腿还可以交叠。接受方可能需要抬起上方的膝盖以便更容易插入。');
INSERT INTO "tags" VALUES ('g1738','蝴蝶式','色情',1451,'本视觉小说中一个或多个性爱场景描绘了[url=https://sexinfo101.com/positions/butterfly]蝴蝶式[/url]体位。

在性爱语境中，“蝴蝶式”可能指[url=https://sexinfo101.com/positions/butterfly]特定体位[/url]，即接受方仰卧，而插入方站在或跪在较低的平面上。然而，此标签（或其子标签之一）应适用于任何接受方仰卧、插入方面对接受方跪下、蹲下或站立且躯干大致直立的体位。接受方可将臀部抬高或略微旋转。插入方可跪或站在比接受方低的平面上，以免过高。

如果插入方在接受方上方支撑自己，则可考虑改用[url=/g878]传教士体位[/url]标签。如果插入方站立且接受方的臀部远高于肩膀，则应使用[url=/g1739]倒插式[/url]标签。

该标签的使用应包括常见的蝴蝶式变体，如[url=/i1702]富永式[/url]和[url=/i1701]第七姿势[/url]。');
INSERT INTO "tags" VALUES ('g1739','倒插式','色情',1005,'本标签下的视觉小说在性爱场景中至少包含一次采用[URL=https://sexinfo101.com/positions/pile-driver]倒插式[/URL]体位的场面。

在倒插式中，接受方以头和上身为支撑躺下，双腿和臀部向上抬起，通常双腿弯曲越过头部，而插入方站在上方。');
INSERT INTO "tags" VALUES ('g1740','腹黑英雄','内容',98,'带有此标签的游戏至少包含一位腹黑英雄。

腹黑角色是指外表看起来和蔼、友好、天真、善良和/或清爽，但利用上述特质中的任意组合来隐藏其真实、残忍、狡猾、邪恶、善于操纵、刻薄和/或施虐一面的人。 

尽管带有负面含义，但并非所有腹黑角色都是反派或反社会者。他们的动机因角色本人以及故事的“严肃程度”而有很大差异。 

该词来自日语词“Haraguroi（腹黒い）”，意为“黑心；刻薄；诡计多端”。');
INSERT INTO "tags" VALUES ('g1742','隐蔽性爱','色情',1129,'该游戏包含在不知情的第三方观众面前以隐蔽方式进行的性行为，例如在桌子底下抚摸伴侣的生殖器、性爱时一方隐身的场景等。

与通过向观众暴露行为而获得性快感的暴露癖不同，隐蔽性爱侧重于在公共场合进行性行为但不被察觉，观众对真正发生的事一无所知。');
INSERT INTO "tags" VALUES ('g1743','药物性侵','色情',337,'本视觉小说包含某人成为强奸受害者的场景，该场景发生在角色因药物影响而无法做出有效同意的情况下。

这甚至可能导致角色表现出与施暴者发生性关系的欲望，即使在正常情况下他们不会给予同意。

仅适用于人工制造并施加的药物，触手怪的自然分泌物等不计入此列。');
INSERT INTO "tags" VALUES ('g1744','第二人称叙事','技术',964,'本视觉小说采用[url=https://en.wikipedia.org/wiki/Second-person_narrative]第二人称叙事[/url]模式。

第二人称叙事是一种叙事模式，其中主角以第二人称代词和其他形式的称呼方式指代，例如英语代词“you”。');
INSERT INTO "tags" VALUES ('g1745','贫穷英雄','内容',40,'本游戏至少有一位英雄是贫穷的，或处于[url=http://en.wikipedia.org/wiki/Poverty]贫困[/url]之中。

贫穷是指一个人缺乏一定数量的物质财产或金钱的状态。绝对贫困或赤贫指的是基本人类需求的剥夺，通常包括食物、水、卫生设施、衣物、住所、医疗保健和教育。');
INSERT INTO "tags" VALUES ('g1746','挠痒折磨','ero',80,'[url=http://en.wikipedia.org/wiki/Tickling]挠痒[/url]是一种以引起不自主的抽动或笑声的方式触摸身体的行为。

[url=http://en.wikipedia.org/wiki/Tickle_torture]挠痒折磨[/url]是指利用挠痒来虐待、支配、羞辱甚至“恶作剧”某人。受害者即使觉得这种经历不愉快也会笑，因为笑声是一种先天反射而非社会条件作用。挠痒折磨可以是双方自愿的，也可以是强迫的，具体取决于情况。如果是自愿的，通常作为某种性仪式或其他亲昵方式的一部分。强迫挠痒折磨既可用于轻度审讯，也可作为一种无害的支配他人的方法。');
INSERT INTO "tags" VALUES ('g1749','三合会','cont',20,'[url=http://en.wikipedia.org/wiki/Triad_%28underground_society%29]三合会[/url]（中国黑手党）在故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g1750','意大利黑手党','cont',47,'[url=http://en.wikipedia.org/wiki/Mafia]黑手党[/url]在故事中扮演重要角色。 

请仅将此标签用于意大利黑手党或具有意大利血统的黑手党。对于未指定的犯罪家族，请改用[url=http://vndb.org/g216]犯罪家族[/url]标签。');
INSERT INTO "tags" VALUES ('g1751','穿旧式灯笼裤的女主角','cont',22,'这部视觉小说中至少有一位女主角穿着旧式[url=http://en.wikipedia.org/wiki/Bloomers_(clothing)]灯笼裤[/url]。

请不要将此标签用于典型的日本女生运动短裤。请改用[url=http://vndb.org/g1079]穿运动灯笼裤的女主角[/url]标签。');
INSERT INTO "tags" VALUES ('g1752','火车','cont',237,'[url=http://en.wikipedia.org/wiki/Train]火车[/url]在游戏故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g1754','残障英雄','cont',72,'一位或多位英雄患有[url=http://en.wikipedia.org/wiki/Disability]残疾[/url]。例如，他可能失明、失聪、失语或跛足。

请将此标签用于身体残疾，而心理残疾请使用[url=/g913]有心理问题的英雄[/url]标签。');
INSERT INTO "tags" VALUES ('g1757','主角是唯一的男性','cont',438,'在整个游戏中，主角是唯一出现的男性角色。

无名无姓、没有面貌的角色，在整个故事中只有一两句台词，不计入此条件。例如：店主、同学、随机路人等。');
INSERT INTO "tags" VALUES ('g1758','受虐狂英雄','cont',38,'本游戏中一位或多位英雄是受虐狂。

受虐型人格障碍是指：

A） 一种普遍的自我挫败行为模式，始于成年早期，存在于各种情境中。此人可能经常回避或破坏愉悦的体验，被吸引到会使自己受苦的情境或关系中，并阻止他人帮助自己，至少有下列五项：

-即使有更好的选择，也会选择导致失望、失败或受虐的人和情境
-拒绝或使他人的帮助无效
-在积极的个人事件（如新的成就）之后，以抑郁、内疚或产生痛苦的行为（如意外）来回应
-激起他人的愤怒或排斥反应，然后感到受伤、挫败或被羞辱（例如，在公共场合取笑配偶，引发愤怒的回应，然后感到崩溃）
-拒绝愉悦的机会，或不愿承认自己享受愉悦（尽管具备足够的社交能力和享受愉悦的能力）
-虽然表现出能力，却无法完成对其个人目标至关重要的任务，例如，帮助同学写论文，却写不出自己的论文
-对一贯善待自己的人不感兴趣或加以拒绝，例如，对关心自己的性伴侣没有吸引力
-进行过度的自我牺牲，而这种牺牲并未得到牺牲对象的请求
B） A中的行为不仅仅发生在遭受或预期遭受身体、性或心理虐待时。
C） A中的行为不仅仅在抑郁时发生。');
INSERT INTO "tags" VALUES ('g1759','迷人的主角','cont',141,'这部视觉小说的主角在故事中被普遍认为是好看的。');
INSERT INTO "tags" VALUES ('g1760','半孤儿英雄','cont',41,'本视觉小说中的一位或多位主角是[URL=http://en.wikipedia.org/wiki/Half-orphan]半孤儿[/URL]。

半孤儿是指失去双亲之一的儿童。通常用法中，只有失去父母之一的儿童被称为半孤儿。然而，成年人也可以被称为半孤儿，或“成年半孤儿”。');
INSERT INTO "tags" VALUES ('g1761','半孤儿主角','内容',160,'带有此标签的视觉小说包含至少一位主角，其是[URL=http://en.wikipedia.org/wiki/Half-orphan]半孤儿[/URL]。

半孤儿是指失去双亲之一的儿童。通常用法中，只有失去父母之一的儿童被称为半孤儿。然而，成年人也可以被称为半孤儿，或“成年半孤儿”。');
INSERT INTO "tags" VALUES ('g1762','半孤儿女主角','内容',114,'本视觉小说中的一位或多位女主角是[URL=http://en.wikipedia.org/wiki/Half-orphan]半孤儿[/URL]。

半孤儿是指失去双亲之一的儿童。通常用法中，只有失去父母之一的儿童被称为半孤儿。然而，成年人也可以被称为半孤儿，或“成年半孤儿”。');
INSERT INTO "tags" VALUES ('g1763','病弱男主角','内容',80,'本游戏中的一位主角患有在故事中起重要作用的疾病。');
INSERT INTO "tags" VALUES ('g1764','阿黑颜','成人',2113,'[url=http://knowyourmeme.com/memes/ahegaokin-%E3%82%A2%E3%83%98%E9%A1%94%E8%8F%8C]阿黑颜[/url]是一种过度夸张的高潮表情，眼睛通常向上翻，有时带着泪水/汗水，嘴巴大张，舌头伸出，脸颊泛红。');
INSERT INTO "tags" VALUES ('g1765','黑暗奇幻','内容',419,'本游戏包含[url=http://en.wikipedia.org/wiki/Dark_fantasy]黑暗奇幻[/url]的元素和主题。

黑暗奇幻是奇幻的一个子类型，将奇幻与恐怖元素相结合。该术语可广泛用于指代具有黑暗、阴郁氛围或恐怖与恐惧感的奇幻作品。');
INSERT INTO "tags" VALUES ('g1772','海滩','内容',385,'这部视觉小说的故事发生在[url=http://en.wikipedia.org/wiki/Beach]海滩[/url]或多个海滩上。');
INSERT INTO "tags" VALUES ('g1775','忍者主角','内容',47,'这些游戏中至少有一位主角是[url=http://en.wikipedia.org/wiki/Ninja]忍者[/url]。');
INSERT INTO "tags" VALUES ('g1777','色情制品制作','成人',981,'关于不同类型色情制品制作的标签属于这个元标签之下。');
INSERT INTO "tags" VALUES ('g1778','色情制品制作（业余）','成人',839,'这部视觉小说包含非专业[url=http://en.wikipedia.org/wiki/Pornography]色情材料[/url]的制作。原因和情况可能各不相同。录制行为可以是合法的（例如一对夫妇录制他们的欢乐时光）或非法的（例如录制强奸以用作敲诈材料）。

注意：请勿将本标签用于专业色情作品，即演员和/或女演员通过合法途径被雇佣以制作色情视频和/或图片。对于这类内容，请使用[url=http://vndb.org/g1779]色情制品制作（专业）[/url]标签。');
INSERT INTO "tags" VALUES ('g1779','色情制品制作（专业）','成人',145,'色情制品制作（专业）
描述：这部视觉小说包含专业制作的[url=http://en.wikipedia.org/wiki/Pornography]色情作品[/url]的制作过程。

注意：请勿将此标签用于业余色情内容，请改用[url=http://vndb.org/g1778]色情制品制作（业余）[/url]。');
INSERT INTO "tags" VALUES ('g1780','色情制品制作（绘画）','成人',33,'这部视觉小说包含绘画形式的[url=http://en.wikipedia.org/wiki/Pornography]色情内容[/url]的制作过程，无论是否为动画。这包括但不限于成人动画（hentai）。

注意1：大多数视觉小说使用绘画艺术作品进行视觉呈现。因此，仅在明确说明所展示的色情内容是作品内绘制的情况下使用此标签。如果所制作的色情内容是真人电影或照片，并且仅仅因为视觉小说的视觉呈现而看起来像绘画，请勿使用此标签。

注意2：此标签可用于专业（例如成人游戏公司）和业余（例如同人社团）制作。');
INSERT INTO "tags" VALUES ('g1781','色情制品的消费','成人',233,'本视觉小说至少包含一个场景，其中一名或多名角色观看或阅读了任意形式的[url=http://en.wikipedia.org/wiki/Pornography]色情作品[/url]。无论是色情电影、成人漫画还是业余性爱录像，都不重要，唯一重要的是有人被展现正在阅读/观看它。

注意：暗示观看或阅读色情作品（例如在某人床下发现一本《花花公子》）本身不足以贴上此标签。');
INSERT INTO "tags" VALUES ('g1782','无跳过功能','tech',526,'在这部视觉小说中，无法快进台词或场景，即使已经读过。');
INSERT INTO "tags" VALUES ('g1783','攻方主角','ero',300,'主角在本游戏的BL配对中担任[url=http://en.wikipedia.org/wiki/Yaoi#Top_and_bottom.2FSeme_and_uke]攻方[/url]（上位/插入者）角色——与那些主角扮演受方（下位/被插入者）角色的作品相反。');
INSERT INTO "tags" VALUES ('g1784','双性恋主角','cont',217,'其中一位主角对女性和男性都有性吸引或恋爱吸引。这一点通过他在游戏中的行为表现出来。他在这方面的性经验与本标签无关。');
INSERT INTO "tags" VALUES ('g1785','伪郎支援角色','cont',11,'这部视觉小说中至少有一个支援角色是女孩，她的外表特征使她看起来像个男孩，甚至可能被误认为男孩。
[url=http://en.wikipedia.org/wiki/Cross_dressing]变装[/url]并非必要条件，尽管它常常是造成混淆的根源。');
INSERT INTO "tags" VALUES ('g1787','双方自愿的电话性爱','ero',94,'本游戏包含一个或多个[url=https://en.wikipedia.org/wiki/Phone_sex]电话性爱[/url]场景，其中角色通过电话进行露骨的性对话/性幻想。

注意：只有在通话双方都清楚该电话的性爱性质时，才可使用本标签。例如，在带有[url=http://vndb.org/g513]寝取[/url]标签的视觉小说中，女主角与主角以外的人发生性关系，同时与上述主角通电话，并试图掩盖她的呻吟和其他性爱声音，这种情况很常见。本标签不应用于此类场景。在这种情况下，请改用[url=https://vndb.org/g2192]隐秘电话性爱[/url]。');
INSERT INTO "tags" VALUES ('g1788','夹子（BDSM）','ero',398,'这部视觉小说包含使用[url=http://en.wikipedia.org/wiki/Nipple_clamp]乳头夹[/url]或类似装置（例如用于此用途的木夹）的场景。');
INSERT INTO "tags" VALUES ('g1789','偏执','cont',87,'[url=http://en.wikipedia.org/wiki/Paranoia]偏执[/url]是一种被认为深受焦虑或恐惧影响的思维过程，往往达到非理性和妄想的地步。偏执思维通常包括被害信念，或认为存在针对自己的阴谋威胁的信念。（例如：“所有人都想害我。”）

作出虚假指控和普遍不信任他人也常常伴随偏执。例如，大多数人视为意外或巧合的事件，偏执者可能认为是故意的。');
INSERT INTO "tags" VALUES ('g1790','吸烟主角','cont',108,'故事中的一位主角偶尔会[url=http://en.wikipedia.org/wiki/Smoking]抽[/url]某种烟草、雪茄或香烟。

对于大麻和其他类似物质，请使用[url=http://vndb.org/g165]药物使用[/url]标签。');
INSERT INTO "tags" VALUES ('g1791','超能力学校','cont',13,'游戏的很大一部分发生在[url=http://en.wikipedia.org/wiki/Psionics]超能力[/url]学院内。

注意：这与[url=http://vndb.org/g685]魔法学校[/url]不同，后者教授诸如魔法咒语或药水之类的巫术；超能力学校则教导学生如何掌握自己的超能力。');
INSERT INTO "tags" VALUES ('g1792','偶像主角','cont',120,'至少有一位主角是[url=http://en.wikipedia.org/wiki/Japanese_idol]偶像[/url]。');
INSERT INTO "tags" VALUES ('g1794','食物调情','ero',591,'带有此标签的游戏至少包含一个性爱场景，其中食物/饮料在该体验中扮演重要角色。');
INSERT INTO "tags" VALUES ('g1795','醉酒性爱','ero',324,'带有此标签的游戏至少包含一个场景，其中[URL=http://en.wikipedia.org/wiki/Alcohol_and_sex]酒精在性爱场景中起重要作用[/URL]，或用于诱发性爱场景。通常，双方参与者都已醉酒，但本标签也适用于只有一方参与者醉酒的情况，例如用酒精作为[URL=http://en.wikipedia.org/wiki/Date_rape]约会强奸[/URL]的手段。');
INSERT INTO "tags" VALUES ('g1796','浴室性爱','ero',2519,'带有此标签的游戏至少包含一个发生在浴室中的性爱场景，无论是公共浴室还是私人浴室。');
INSERT INTO "tags" VALUES ('g1797','诗歌','tech',72,'这部视觉小说使用诗歌来讲述其全部或部分故事。');
INSERT INTO "tags" VALUES ('g1799','精灵主角','cont',79,'其中一位英雄是[url=http://en.wikipedia.org/wiki/Elves_in_fantasy_fiction_and_games]精灵[/url]。

在许多现代奇幻作品中，精灵被描绘为一个半神性的类人种族，与自然和动物友好相处。

奇幻精灵的一个标志性特征也是他们又长又尖的耳朵。这些耳朵的长度和形状因艺术家或媒介而异。与人类相比，精灵往往是不朽或长寿的，更美丽、更睿智，拥有更敏锐的感觉和知觉，以及看似异域或神奇的能力或技艺。

这个标签不是指那种微小的、小妖精般的精灵。');
INSERT INTO "tags" VALUES ('g1800','兼职工作','cont',222,'从事[url=http://en.wikipedia.org/wiki/Part-time]兼职工作[/url]的角色是这个故事的重要组成部分。

兼职工作是一种每周工作时间少于全职工作的就业形式。如果工人通常每周工作少于30或35小时，则被视为兼职。从事兼职工作的原因有很多，包括个人意愿、雇主削减工作时间以及无法找到全职工作。');
INSERT INTO "tags" VALUES ('g1801','教育','cont',212,'这部视觉小说旨在向读者传授其主题相关知识。例如，一个关于学生的故事可能围绕角色学习新语言或完成学校项目展开，或者一个关于动物的故事可能介绍动物生物学和环境方面的事实。

参见[url=http://en.wikipedia.org/wiki/Edutainment]教育娱乐[/url]。');
INSERT INTO "tags" VALUES ('g1802','不良主角','cont',75,'这款游戏的主角是一个不良少年。

通常不遵守校规，逃课，是帮派成员，学校里大多数学生都害怕他/她。');
INSERT INTO "tags" VALUES ('g1803','不良英雄','cont',89,'这款游戏中的一个或多个英雄是不良少年。

通常不遵守校规，逃课，是帮派成员，学校里大多数学生都害怕他。');
INSERT INTO "tags" VALUES ('g1805','兽人','cont',129,'这个故事中有[url=http://en.wikipedia.org/wiki/Orc]兽人[/url]。');
INSERT INTO "tags" VALUES ('g1806','兽人英雄','cont',22,'其中一位英雄是[url=http://en.wikipedia.org/wiki/Orc]兽人[/url]。');
INSERT INTO "tags" VALUES ('g1807','奴隶女主角','cont',80,'这款游戏中的一位女主角是奴隶

奴隶制是一种将人当作可买卖的财产并强迫其劳动的制度。奴隶从被俘获、购买或出生之时起就可能被违背其意愿地扣留，并被剥夺离开、拒绝工作或要求补偿的权利。');
INSERT INTO "tags" VALUES ('g1808','奴隶英雄','cont',17,'这款游戏中的一位英雄是奴隶

奴隶制是一种将人当作可买卖的财产并强迫其劳动的制度。奴隶从被俘获、购买或出生之时起就可能被违背其意愿地扣留，并被剥夺离开、拒绝工作或要求补偿的权利。');
INSERT INTO "tags" VALUES ('g1809','不知情的乱伦','ero',70,'至少有一方不知道性关系的乱伦性质，尽管另一方可能完全清楚。

无论乱伦关系是偶然发生，还是知情方有意欺骗，都无关紧要。');
INSERT INTO "tags" VALUES ('g1810','现代四国','cont',5,'游戏背景设定在[url=http://en.wikipedia.org/wiki/Shikoku]四国[/url]，日本四大主岛之一。
注意：“现代”指的是20世纪末至今的一个未明确指定的时期。');
INSERT INTO "tags" VALUES ('g1811','现代北海道','cont',24,'游戏背景设定在当代[url=http://en.wikipedia.org/wiki/Hokkaido]北海道[/url]，日本四大主岛之一。
注意：“现代”指的是20世纪末至今的一个未明确指定的时期。');
INSERT INTO "tags" VALUES ('g1812','中美洲','cont',5,'这部视觉小说的背景设定在[url=http://en.wikipedia.org/wiki/Central_America]中美洲[/url]。

中美洲是连接南北美洲大陆的地峡。它由伯利兹、哥斯达黎加、萨尔瓦多、危地马拉、洪都拉斯、尼加拉瓜和巴拿马等国组成。');
INSERT INTO "tags" VALUES ('g1813','小马宝莉','cont',45,'这部视觉小说包含了来自[url=http://en.wikipedia.org/wiki/My_Little_Pony]小马宝莉[/url]系列的角色和/或设定。');
INSERT INTO "tags" VALUES ('g1814','猜拳','tech',82,'这部视觉小说使用猜拳（英文通常称为[url=http://en.wikipedia.org/wiki/Rock-paper-scissors]石头剪刀布[/url]）作为游戏元素。');
INSERT INTO "tags" VALUES ('g1815','印度尼西亚','cont',27,'这部视觉小说的背景设定在[url=http://en.wikipedia.org/wiki/Indonesia]印度尼西亚[/url]。');
INSERT INTO "tags" VALUES ('g1816','特写CG','tech',106,'在这款游戏中，玩家可以选择手动放大事件CG并调整其画面，以便更仔细地查看图片和/或查看更多细节。这可能与PC的图像查看程序或相机的[url=http://en.wikipedia.org/wiki/Close-up]缩放/特写[/url]功能有些类似。');
INSERT INTO "tags" VALUES ('g1818','饮食失调','cont',20,'至少有一名角色患有某种[url=https://en.wikipedia.org/wiki/Eating_disorder]饮食失调[/url]（如厌食症、暴食症等），或者饮食失调在故事中占据重要地位。

饮食失调是指以异常饮食习惯为特征的疾病，可能涉及食物摄入不足或过量，从而损害个人的身心健康。');
INSERT INTO "tags" VALUES ('g1819','鳏夫主角','cont',46,'本游戏中的一位或多位主角是[url=http://en.wikipedia.org/wiki/Widow]鳏夫[/url]。
鳏夫是指配偶已故的男子。');
INSERT INTO "tags" VALUES ('g1820','可逆的Yaoi配对','ero',112,'Yaoi情侣中的角色有时会互换在[url=http://en.wikipedia.org/wiki/Yaoi#Top_and_bottom.2FSeme_and_uke]攻方（上位）和受方（下位）[/url]中的角色。这种情况可能发生在游戏中的某条路线里，或者角色可能根据你的选择扮演不同角色。

仅当特定的一对情侣互换角色时才使用此标签，而不是例如主人公与某些恋爱对象在一起时是受方、与其他人在一起时是攻方的情况。

另请参阅[url=http://vndb.org/g1783]攻方主角[/url]。');
INSERT INTO "tags" VALUES ('g1821','祖父/孙女乱伦','ero',17,'这些游戏包含祖父与孙女之间的性爱场景。他们可能有血缘关系，也可能没有。');
INSERT INTO "tags" VALUES ('g1822','性奴役（非自愿）','ero',133,'这种形式的[url=http://en.wikipedia.org/wiki/Sexual_slavery]性奴役[/url]是对非自愿者进行性剥削的奴役。
强迫卖淫，也称为非自愿卖淫，是这种性奴役的典型形式，其中性贩运者强迫受害者成为妓女或从事性产业工作。
性产业中的各种工作包括卖淫、在脱衣舞俱乐部跳舞、出演色情电影和色情作品，以及其他形式的非自愿劳役。

重要提示：非自愿性奴役以非自愿开始并始终保持非自愿。受害者不会经历精神崩溃，也不会在故事中的任何时刻变成心甘情愿的奴隶。');
INSERT INTO "tags" VALUES ('g1823','性奴役（调教变体）','ero',497,'这是非自愿和自愿形式的性奴役的一种模糊融合，通常出现在拔作中。
虽然像非自愿性奴役一样对某些不情愿的人使用了某种强制手段，但最终与自愿奴役的界限大多模糊不清。

在这种媒介的夸张表现中，不情愿会通过性刺激相当迅速地转变为（半）自愿的形式。
角色这种不自然的行为纯属虚构，是拔作的一个特征。
此外，这种性奴役的描绘经常借用一些象征符号，通过这些符号，顺从者向他人展示自愿屈服，表明其属于支配者，例如佩戴项圈、特殊纹身、穿孔、超短发或光头。

因此，以性奴役为主题的拔作往往无法明确归类为现实中两种性奴役形式中的任何一种。

重要提示：这种性奴役变体以非自愿开始，要么通过激发受害者内心的受虐倾向而转变为自愿，要么精神崩溃抹去了受害者大部分原有性格，以至于无法真正谈论“意志”和“同意”。');
INSERT INTO "tags" VALUES ('g1824','当众性行为','ero',1282,'带有此标签的游戏包含一个性爱场景，其中一个角色进行性行为时有其他人在旁观看。

此标签不同于[url=https://vndb.org/g735]公共场所性行为[/url]，因为地点可以是私人或公共的，只要有观众在场即可。也与[url=https://vndb.org/g1742]隐秘性行为[/url]不同，因为性行为并未对观众隐藏。');
INSERT INTO "tags" VALUES ('g1825','勇者斗恶龙','cont',105,'这部视觉小说以[url=https://en.wikipedia.org/wiki/Dragon_Quest]勇者斗恶龙[/url]系列中的角色为特色。');
INSERT INTO "tags" VALUES ('g1826','黑色喜剧','cont',406,'带有此标签的视觉小说是[URL=http://en.wikipedia.org/wiki/Black_comedy]黑色喜剧[/URL]，或者包含黑色幽默。  

黑色喜剧是一种采用黑色幽默的喜剧作品，其最基本的定义是，将原本严肃的主题以轻松的方式处理，或者称为[URL=http://en.wikipedia.org/wiki/Gallows_humor]绞刑架幽默[/URL]。');
INSERT INTO "tags" VALUES ('g1827','菲律宾','cont',31,'这部视觉小说以[url=http://en.wikipedia.org/wiki/Philippines]菲律宾[/url]为背景。');
INSERT INTO "tags" VALUES ('g1828','比赛','cont',282,'比赛是故事的重要组成部分。

竞争是多人或团队之间为获得奖品、名誉和/或道德满足感而进行的正式的体育或智力对抗。这可以是几个学校社团的内部竞赛，也可以是像奥运会这样的大型活动。

请不要将此标签用于轻微争执，例如几个朋友试图确定谁更擅长喝啤酒之类的争执。');
INSERT INTO "tags" VALUES ('g1829','相互手淫','ero',673,'此标签下的视觉小说至少包含一个[URL=http://en.wikipedia.org/wiki/Non-penetrative_sex#Mutual_masturbation]相互手淫[/URL]场景。

相互手淫通常涉及两个或更多人通过手动刺激自己或彼此的生殖器。相互手淫的类型包括[URL=http://vndb.org/g917]手交[/URL]和[URL=http://vndb.org/g1515]指交[/URL]。也可能包括[URL=http://vndb.org/g750]用脚[/URL]刺激生殖器，以及手动刺激肛门。');
INSERT INTO "tags" VALUES ('g1830','虚构现代地球','cont',802,'带有此标签的视觉小说以现代地球上的虚构地点为背景，或包含这样的地点。地点可以小到村庄，大到国家。

注意：“现代”指的是20世纪末至今的一段未明确的时间。');
INSERT INTO "tags" VALUES ('g1831','警察男主角','cont',137,'带有此标签的游戏主角是一名[URL=http://en.wikipedia.org/wiki/Police_officer]警察[/URL]。');
INSERT INTO "tags" VALUES ('g1832','调皮的女主角','cont',355,'这部视觉小说中至少有一位女主角是调皮的：她喜欢捉弄其他角色，恶作剧，并且总体上态度俏皮。');
INSERT INTO "tags" VALUES ('g1834','受方主角','ero',281,'主角在此游戏的BL配对中担任受方（bottom/receiving）角色。

Uke一词源自动词“to receive”（接受），在日本同性恋俚语中用来指代肛交中的接受方。');
INSERT INTO "tags" VALUES ('g1835','酒吧','cont',212,'带有此标签的游戏大部分发生在酒吧或类似场所。

仅当游戏在某个酒吧中花费相当多时间时才使用此标签，而不是每个出现一次酒吧的游戏。');
INSERT INTO "tags" VALUES ('g1836','酒保男主角','cont',71,'游戏中的一位男主角是酒保。

酒保是在有执照的场所吧台后面通常供应酒精饮料，并维护用品和库存的人。');
INSERT INTO "tags" VALUES ('g1837','学校体育社团社长女主角','cont',14,'其中一位女主角是学校体育社团的负责人。');
INSERT INTO "tags" VALUES ('g1838','主角的雇员作为男主角','cont',12,'游戏中至少有一位男主角是主角的雇员。该男主角（直接或间接）接受主角的命令。');
INSERT INTO "tags" VALUES ('g1840','仅限伪娘女主角','cont',163,'这部视觉小说的所有女主角都是男孩，其身体特征使他们看起来像女孩，甚至可能被误认为女孩。
[url=http://en.wikipedia.org/wiki/Cross_dressing]异装[/url]不是必需的，但通常是造成混淆的根源。');
INSERT INTO "tags" VALUES ('g1842','纹身男主角','cont',157,'这部视觉小说中有一位或多位带有[url=http://en.wikipedia.org/wiki/Tattoo]纹身[/url]的男主角。

纹身是一种身体改造形式，通过将不可褪色的墨水注入皮肤真皮层来改变色素。');
INSERT INTO "tags" VALUES ('g1843','结局场景回顾','tech',240,'此游戏的场景回放模式包含路线结局场景。这些场景应可完整回放，并且可能包含也可能不包含性内容。

注意：当游戏的场景回顾/回放模式除H场景外只包含结局时，请使用此标签。如果它包含普通（非结局、非H场景）场景，请使用[url=http://vndb.org/g1555]普通场景回顾[/url]标签。');
INSERT INTO "tags" VALUES ('g1844','主角的前任作为男主角','cont',75,'一位或多位男主角曾与主角有过恋爱关系，但现在他们已经分手、离婚和/或疏远。');
INSERT INTO "tags" VALUES ('g1845','班长男主角','cont',21,'这个角色是[url=http://en.wikipedia.org/wiki/Class_President]班长[/url]。

班长通常是一个学生班的领导者，主持班内阁或学生委员会内的组织。在小学，班长通常由全班选举产生，班级是由同一年级所有学生组成的选民群体。

班长与学生会长不同，他们只代表特定班级的学生，而不是全体学生。');
INSERT INTO "tags" VALUES ('g1846','K-On!','cont',35,'这些游戏包含来自[url=http://en.wikipedia.org/wiki/K-On!]K-On![/url]系列的角色。');
INSERT INTO "tags" VALUES ('g1847','Death Note','cont',12,'这些游戏包含来自[url=http://en.wikipedia.org/wiki/Death_Note]Death Note[/url]系列的角色。');
INSERT INTO "tags" VALUES ('g1848','Katekyo Hitman Reborn!','cont',27,'这些游戏包含来自[url=http://en.wikipedia.org/wiki/Katekyo_Hitman_Reborn!]家庭教师[/url]系列的角色。');
INSERT INTO "tags" VALUES ('g1849','宝可梦','cont',36,'这部视觉小说的世界观与[url=http://en.wikipedia.org/wiki/Pok%C3%A9mon]宝可梦[/url]相同，或包含该系列的角色。');
INSERT INTO "tags" VALUES ('g1850','最终幻想','cont',48,'这部视觉小说包含来自[url=http://en.wikipedia.org/wiki/Final_fantasy]最终幻想[/url]系列的角色。');
INSERT INTO "tags" VALUES ('g1851','生物武器','cont',38,'在这个故事中，生物武器正在被制造和/或使用。

生物武器包含[url=http://en.wikipedia.org/wiki/Biological_agent]生物制剂[/url]（细菌、病毒、寄生虫等），这些制剂能以各种方式对人类健康产生不利影响，从相对轻微的过敏反应到严重的疾病状况，包括死亡。在大多数情况下，生物武器被开发为大规模杀伤性武器。');
INSERT INTO "tags" VALUES ('g1852','流行病','cont',144,'在这个故事中，发生了[url=http://en.wikipedia.org/wiki/Epidemic]流行病[/url]或[url=http://en.wikipedia.org/wiki/Pandemic]大流行病[/url]。

当某种疾病在特定人群和特定时期内的新病例数量大大超过基于近期经验所预期的数量时，就会发生流行病。通常，当宿主对寄生虫群体的免疫力突然降低时，流行病就会发生。原因之一可能是病毒、细菌等新物种的出现。流行病可能仅限于一个地点；然而，如果它蔓延到其他国家或大陆并影响大量人群，则可能被称为大流行病。
在一些虚构故事中，流行病或大流行病的起因可能是使用生物武器。这可能导致僵尸启示录或其他有趣的效果。');
INSERT INTO "tags" VALUES ('g1853','爱情旅馆','cont',552,'[url=http://en.wikipedia.org/wiki/Sex_hotel]爱情旅馆[/url]是一种在世界各地都能找到的短时住宿旅馆，主要目的是为情侣提供隐私空间进行性活动。
这个名字源自大阪1968年建成的“Hotel Love”，其招牌是旋转的。');
INSERT INTO "tags" VALUES ('g1854','夏令营','cont',172,'这款游戏的主要事件发生在[url=http://en.wikipedia.org/wiki/Summer_camp]夏令营[/url]。');
INSERT INTO "tags" VALUES ('g1855','先锋女主角','cont',27,'这款游戏中至少有一位女主角是共产主义[url=http://en.wikipedia.org/wiki/Pioneer_movement]先锋[/url]组织的成员。');
INSERT INTO "tags" VALUES ('g1856','环境音','tech',274,'这款游戏有大量场景仅播放环境音。

对于那些环境音与音乐同时播放的游戏，请勿使用此标签。环境音应在整个游戏中持续存在，并在营造游戏氛围方面发挥重要作用（例如：[url=http://vndb.org/v67]寒蝉鸣泣之时[/url]）。');
INSERT INTO "tags" VALUES ('g1857','阴茎生长','ero',465,'这部视觉小说至少包含一个场景，其中参与的女性角色长出阴茎，从而暂时或永久成为扶她。这可能是特殊药水、魔法、未来手术等等的结果。

注意：请勿将此标签用于一开始就是扶她的角色。同时，也请勿将此标签用于阴茎增大。');
INSERT INTO "tags" VALUES ('g1859','找物游戏','tech',33,'这部视觉小说包含找物游戏玩法。

[url=http://en.wikipedia.org/wiki/Puzzle_video_game#Hidden_object_game]找物游戏[/url]是一种益智游戏类型，玩家必须从列表中找出隐藏在图片中的物品。');
INSERT INTO "tags" VALUES ('g1861','渐变发色男主角','cont',38,'这款游戏中的男主角因风格需要而拥有渐变发色。');
INSERT INTO "tags" VALUES ('g1862','平安时代','cont',51,'这部视觉小说的背景设定在（或至少基于）[url=http://en.wikipedia.org/wiki/Heian_period]平安时代[/url]。');
INSERT INTO "tags" VALUES ('g1864','黑帮男主角','cont',91,'游戏中的男主角是[url=http://en.wikipedia.org/wiki/Gangster]黑帮分子[/url]。');
INSERT INTO "tags" VALUES ('g1865','家族世仇','cont',26,'情节包含两个或多个家族之间的世仇。

最著名的例子可能是莎士比亚的《罗密欧与朱丽叶》。');
INSERT INTO "tags" VALUES ('g1866','佣兵男主角','cont',20,'这些游戏中至少有一位男主角是（或曾经是）雇佣兵。

雇佣兵是指参与武装冲突的人，他不属于冲突的任何一方或国民，并且“参与敌对行动的基本动机是出于私人利益，且事实上，由冲突一方或代表冲突一方向其承诺的物质补偿，实质性地超过该方武装部队中相似军衔和职位的战斗人员所承诺或支付的报酬”。');
INSERT INTO "tags" VALUES ('g1867','沙漠','cont',50,'这部视觉小说有很多场景发生在[url=http://en.wikipedia.org/wiki/Desert]沙漠[/url]中。');
INSERT INTO "tags" VALUES ('g1868','赌场','cont',55,'本视觉小说有大量场景设定在[url=http://en.wikipedia.org/wiki/Casino]赌场[/url]。');
INSERT INTO "tags" VALUES ('g1869','坚强的女主角','内容',441,'女主角不是软柿子，她意志坚定、自信果断、善于表达，拥有鲜明的个性。这在以女性为主角的乙女游戏中尤为罕见；因为大多数游戏要么塑造一个无脸、性格空白的透明主角，要么塑造一个端庄、柔弱、逆来顺受的主角。');
INSERT INTO "tags" VALUES ('g1871','娇羞痴情型男主角','内容',77,'其中一位男主角是娇羞痴情型（deredere）——他从遇见他/她的那一刻起就彻底陷入爱恋。

即使是最无辜的言论，他也会脸红不已。');
INSERT INTO "tags" VALUES ('g1872','女性朋友','内容',651,'配角包括主角的一位或多位女性朋友。');
INSERT INTO "tags" VALUES ('g1874','阴阳师男主角','内容',19,'作为阴阳师工作的男主角，使用基于佛教和/或道教神话的方法战斗或驱逐恶魔。这通常包括使用手印（手势）、念珠、念诵和/或梵文神圣符号。');
INSERT INTO "tags" VALUES ('g1875','礼貌正式型男主角','内容',74,'与其他角色相比，这一男主角的言谈举止极其正式和礼貌。');
INSERT INTO "tags" VALUES ('g1876','开朗型男主角','内容',145,'这一男主角以开朗乐观的性格为特征。');
INSERT INTO "tags" VALUES ('g1878','滑稽型男主角','内容',47,'这一男主角的性格倾向于滑稽、傻气或逗趣，而非严肃或戏剧化。');
INSERT INTO "tags" VALUES ('g1884','阿拉伯风格宫殿','内容',26,'设定包含外观为阿拉伯或中东风格的宫殿。

[url=https://t.vndb.org/sf/95/205495.jpg]示例[/url]');
INSERT INTO "tags" VALUES ('g1887','穿和服的男主角','内容',81,'这些游戏包含一位穿着和服或类似日本传统服饰的男主角。');
INSERT INTO "tags" VALUES ('g1888','政治家男主角','内容',34,'在此标签下的视觉小说中，一位或多位男主角是政治家。 

[URL=http://en.wikipedia.org/wiki/Politician]政治家[/URL]是指参与影响公共政策和决策的人。这包括在政府中担任决策职位的人，以及通过选举、继承、政变、任命、选举舞弊、征服、神权或其他方式谋求这些职位的人。');
INSERT INTO "tags" VALUES ('g1889','角色档案','技术',585,'带有此标签的视觉小说包含游戏内的角色档案。 
角色档案包含诸如生日、星座、身高和体重等信息。有时还包括额外信息，如角色的历史、故事事件前的经历，或他们在空闲时间的所作所为。

角色档案常常包含剧透，请相应添加标签。

示例1：http://s.vndb.org/sf/76/62076.jpg
示例2：http://tinyurl.com/meclzef');
INSERT INTO "tags" VALUES ('g1890','男公关俱乐部男主角','内容',25,'本视觉小说中的一位男主角在[url=http://en.wikipedia.org/wiki/Host_club]男公关俱乐部[/url]工作。');
INSERT INTO "tags" VALUES ('g1891','女公关俱乐部女主角','内容',45,'本视觉小说中的一位女主角在[url=http://en.wikipedia.org/wiki/Host_club]女公关俱乐部[/url]工作。');
INSERT INTO "tags" VALUES ('g1892','现代中国','内容',104,'故事背景设定在现代[url=http://en.wikipedia.org/wiki/China]中国[/url]。
注意：“现代”指的是20世纪末至今天之间一个未具体指明的时间段。');
INSERT INTO "tags" VALUES ('g1893','木偶师女主角','内容',4,'本游戏中的一位女主角是[url=http://en.wikipedia.org/wiki/Puppeteer]木偶师[/url]。');
INSERT INTO "tags" VALUES ('g1894','女房东女主角','内容',43,'本游戏的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Landlady]女房东[/url]。

女房东是指拥有房屋、公寓、共管公寓、土地或不动产并将其出租或租赁给个人或企业的人，该租户称为承租人（亦称租客）。当法人处于该地位时，也使用“女房东”一词。');
INSERT INTO "tags" VALUES ('g1897','都市奇幻','内容',278,'本游戏包含[url=http://en.wikipedia.org/wiki/Urban_fantasy]都市奇幻[/url]的元素和主题。

都市奇幻是奇幻的一个子类型，其定义基于地点；奇幻叙事以都市为背景。都市奇幻存在于一个光谱的一端，与设定在完全虚构世界中的高奇幻相对。许多都市奇幻设定在当代并包含超自然元素。然而，故事可以发生在历史、现代或未来时期，且设定可以包含虚构元素。前提是它们必须主要设定在城市中。');
INSERT INTO "tags" VALUES ('g1898','应急按钮','技术',91,'本游戏包含一个应急按钮。这允许玩家在NSFW场景被打断时，通过空白屏幕或看似无害的图像快速隐藏游戏。');
INSERT INTO "tags" VALUES ('g1899','帮派','内容',68,'一个[url=http://en.wikipedia.org/wiki/Gang]帮派[/url]在故事中扮演重要角色。

帮派是一群经常交往的个体或密友组成的群体，具有可识别的领导层和内部组织，认同或声称控制社区内的地盘，并单独或集体地参与暴力或其他形式的非法行为。

帮派成员被称为黑帮分子。');
INSERT INTO "tags" VALUES ('g1900','死神主角','内容',28,'这款游戏的主角是一个[url=http://en.wikipedia.org/wiki/Shinigami]死神[/url]。

死神（死神, "死亡之神"或"死亡之灵"）是日本民间传说中的一种实体，负责使人在预定时间死亡，然后引导其灵魂在来世接受审判。在这方面，死神与西方的“死神”（Grim Reaper）概念相关。尽管格里姆·里珀是单一实体，但死神有多个，通常被想象为一起工作。死神是日本民间传说中相对较新的存在。');
INSERT INTO "tags" VALUES ('g1903','有立绘的主角','技术',4611,'与许多视觉小说不同，这部视觉小说的主角拥有自己的立绘。');
INSERT INTO "tags" VALUES ('g1905','播音员女主角','内容',39,'这款游戏中的一位女主角是一名[url=http://en.wikipedia.org/wiki/Announcer]播音员[/url]。');
INSERT INTO "tags" VALUES ('g1907','海盗主角','内容',46,'这款游戏中的一个或多个主角是海盗。

[URL=http://en.wikipedia.org/wiki/Piracy]海盗行为[/URL]通常是指海上的抢劫或犯罪暴力行为。 

该术语可以包括在陆地、空中或其他主要水域或海岸上实施的行为。它通常不包括对与犯罪者同乘一艘船的旅客实施的犯罪（例如，一名乘客在船上偷窃他人的财物）。在整个历史中，该术语一直被用来指非国家行为体跨越陆地边境进行的突袭。');
INSERT INTO "tags" VALUES ('g1908','海军军人主角','内容',9,'这款游戏中的一个或多个主角在海军部队中服役。

一个[URL=http://en.wikipedia.org/wiki/Navy]海军[/URL]（或海上力量）是一支由水上军用舰船（watercraft）组成的舰队。它是一个国家武装部队中主要指定用于海军和两栖作战的分支；即湖泊、河流、沿海或海洋作战行动及相关职能。它包括由水面舰艇、两栖舰艇、潜艇和海上航空所进行的任何行动，以及辅助支援、通信、训练和其他领域；近期的发展包括与太空相关的行动。');
INSERT INTO "tags" VALUES ('g1909','跨性别女主角','内容',202,'这部视觉小说的女主角是[url=https://en.wikipedia.org/wiki/Transgender]跨性别者[/url]。女主角的"性别认同"（自我认同为女性、男性、两者皆非或两者皆是）与她的"指定性别"（由他人根据生理/基因性别将其认定为男性、女性或间性人）不符。

"跨性别"并不暗示任何特定形式的性取向；跨性别者可能认同为异性恋、同性恋、双性恋、泛性恋、多性恋或无性恋；有些人可能认为传统的性取向标签不适用于或不足以描述他们。

她可能已经进行了永久或部分的性别转换（这可能在故事之前或期间发生），从而成为变性者。

请不要将其与拥有两套生殖器的扶她（futanari）混淆，而跨性别角色只有一套。');
INSERT INTO "tags" VALUES ('g1911','自我口交','色情',55,'这部视觉小说包含至少一个场景，其中扶她或男性角色对自己进行口交。

[url=https://s2.vndb.org/sf/36/130936.jpg]NSFW男性示例[/url]
[url=https://s2.vndb.org/sf/35/130935.jpg]NSFW扶她示例1[/url]
[url=https://s2.vndb.org/sf/34/130934.jpg]NSFW扶她示例2[/url]
[url=https://s2.vndb.org/sf/33/130933.jpg]NSFW无头骑士示例[/url]');
INSERT INTO "tags" VALUES ('g1912','中二病主角','内容',15,'这款游戏中的一位男主角患有中二病。

[URL=http://en.dic.pixiv.net/a/Chuunibyou]中二病[/URL] 或"中学二年级综合征"，是日本一种口语化的、略带嘲讽的术语，用来描述一个十四岁的人要么表现得像个自以为什么都知道的成年人，要么认为自己拥有别人没有的特殊能力。有些人甚至表现得令人讨厌、傲慢，还常常看不起成年人或年长者。这种想法或行为多见于青春期的青少年，但也有人成年后仍保持这种行为。

不要将此标签用于这种想法或行为在该设定中属于自然情况的情形（即，在拥有真实魔法的奇幻世界中的魔法少女女主角）。仅在这种行为不合时宜时使用。');
INSERT INTO "tags" VALUES ('g1913','Xonix游戏','技术',8,'Xonix 是一款风格类似于 [url=http://en.wikipedia.org/wiki/Qix]Qix[/url] 的视频游戏。

玩家可以围绕屏幕向四个方向移动光标来占领区域。玩家绘制一个封闭方框所包含的任何区域都会被占领，但如果在方框闭合之前有其他物体碰到玩家的光标（或正在绘制的线），则该区域和一条生命都会丢失。游戏的目标是占领屏幕上的特定百分比区域。当玩家在屏幕上划出区域时，所占领区域会显示隐藏图片的一部分，而未占领区域则保持不透明的遮挡或半透明覆盖在整个图像上。通关后可以查看完整图像作为奖励。');
INSERT INTO "tags" VALUES ('g1915','已婚男主角','内容',105,'这部视觉小说中至少有一位男主角是[url=http://en.wikipedia.org/wiki/Husband]已婚男人[/url]。他的婚姻在故事过程中可能会或可能不会持续。');
INSERT INTO "tags" VALUES ('g1916','妖怪男主角','内容',144,'这款游戏中有一位或多位男主角是妖怪。

妖怪形形色色，有的恶意，有的顽皮，偶尔也会给遇到它们的人带来好运。它们通常具有动物特征（例如长得像乌龟的河童，或长着翅膀的天狗），有时它们看起来几乎和人一样，有些看起来像无生命物体，还有一些则没有可辨认的形状。妖怪通常拥有精神上的超自然力量，变形是最常见的能力之一。能够变形的妖怪被称为obake。');
INSERT INTO "tags" VALUES ('g1918','现代韩国','内容',74,'这款游戏以现代[url=http://en.wikipedia.org/wiki/Korea]韩国[/url]为背景。
注意："现代"指的是20世纪末至今天之间的一个未明确指定的时期。');
INSERT INTO "tags" VALUES ('g1919','过去的韩国','内容',12,'这些游戏发生在过去的[url=http://en.wikipedia.org/wiki/Korea]韩国[/url]。');
INSERT INTO "tags" VALUES ('g1920','女主角的母亲作为女主角','内容',613,'其中一位女主角的母亲，本身就是一名女主角。 

如果女主角的母亲同时也是主角的母亲/继母，则不要使用此标签，因为已有相应的标签。');
INSERT INTO "tags" VALUES ('g1921','发明家男主角','内容',21,'这款游戏中至少有一位男主角是发明家。

[url=http://en.wikipedia.org/wiki/Inventor]发明家[/url]是创造新设备或新方法的人。他甚至可能有自己的工作室。');
INSERT INTO "tags" VALUES ('g1922','熟女控','内容',79,'这款游戏中至少有1个角色是熟女控。

熟女控是萝莉控的反面：对年长女性的吸引。
可以是奶奶辈、妈妈辈，甚至姐姐辈。
重点在于，熟女控只会追求年长和/或更成熟的女性。');
INSERT INTO "tags" VALUES ('g1923','友情结局','技术',408,'这款游戏包含一个或多个以与某个其他角色之间的柏拉图式[url=http://en.wikipedia.org/wiki/Friendship]友情[/url]为中心的结局。');
INSERT INTO "tags" VALUES ('g1927','NaNoRenO','技术',904,'此标签表示专为[url=http://lemmasoft.renai.us/forums/viewtopic.php?f=50&t=25451&sid=d08621f6e10902e7254668c8928ed644]NaNoRenO[/url]创作的视觉小说，该活动每年三月在OELVN/EVL社区举办，每位参与者在一个月内创作一部完整的视觉小说。');
INSERT INTO "tags" VALUES ('g1929','不死男主角','内容',444,'这款游戏中的一位男主角是[url=http://en.wikipedia.org/wiki/Undead]不死者[/url]。');
INSERT INTO "tags" VALUES ('g1930','LGBTQ议题','内容',680,'这款游戏探讨了[url=http://en.wikipedia.org/wiki/LGBT]LGBTQ[/url]经历与身份的主题，例如角色质疑自己的性取向或性别认同、向朋友和家人出柜，以及应对偏见。');
INSERT INTO "tags" VALUES ('g1931','泡泡浴按摩','成人',490,'一种情色按摩，其中一名参与者全身涂满肥皂，然后按摩师用自己赤裸的身体摩擦对方的身体，以清洁其身体。起源于日本，用以规避反卖淫法。');
INSERT INTO "tags" VALUES ('g1932','仅限同性性内容','ero',1912,'本视觉小说中的所有性爱场景仅包含全女性或全男性参与者。这包括同性场景（百合、耽美或两者皆有）以及自慰。请注意，在相互自慰的情况下，所有参与者也必须为同一性别。

包含无性别生物（例如普通的触手/史莱姆怪物）的性爱场景是不被接受的（只有明确界定性别的生物才可接受，例如v5657中的魔物娘）。');
INSERT INTO "tags" VALUES ('g1933','双性恋主角','cont',363,'主角在性方面或浪漫情感上同时被女性和男性所吸引。这一点通过其在游戏中的行为表现出来。他们在该方面过去的性经验与本标签无关。

本标签适用于从一开始就对女性和男性都表现出兴趣、或在游戏过程中发现自身性取向的主角。若主角只对同性角色感兴趣，请使用同性恋主角标签。');
INSERT INTO "tags" VALUES ('g1935','学校体育社团成员角色','cont',50,'本游戏中一位或多位角色是学生体育社团的成员。');
INSERT INTO "tags" VALUES ('g1936','学校体育社团社长角色','cont',10,'本游戏中一位或多位角色是学生体育社团的社长。');
INSERT INTO "tags" VALUES ('g1937','学校体育社团成员主角','cont',36,'本游戏的主角是学生体育社团的成员。');
INSERT INTO "tags" VALUES ('g1938','妓院','cont',109,'本游戏的情节有时或总是发生在[url=http://en.wikipedia.org/wiki/Brothel]妓院[/url]中。

妓院是一个人们可以前来与妓女进行性行为的地方。');
INSERT INTO "tags" VALUES ('g1941','大正时代','cont',105,'[url=http://en.wikipedia.org/wiki/Taish%C5%8D_period]大正时代[/url]是日本历史中的一个时期，从1912年7月30日至1926年12月25日，与大正天皇的统治时期一致。

请仅在视觉小说中明确说明故事发生在大正时代时才使用此标签。');
INSERT INTO "tags" VALUES ('g1942','无血缘兄弟/兄弟乱伦','ero',10,'这些游戏包含无血缘兄弟之间的性爱场景。');
INSERT INTO "tags" VALUES ('g1943','不可避免的角色强奸','ero',26,'至少有一条路线中会出现角色强奸场景，且此场景无法避免。如果强奸场景出现在每条路线中或在分支点之前，请使用[url=/g3819]完全不可避免的角色强奸[/url]。');
INSERT INTO "tags" VALUES ('g1944','完全可避免的角色强奸','ero',12,'你无需经历任何角色强奸场景即可看到游戏的所有"正常结局"。这些角色强奸场景仅出现在提前的坏结局中，而阅读这些坏结局并非解锁其他结局所必需。

不适用于非主要角色。');
INSERT INTO "tags" VALUES ('g1945','喂食癖','cont',27,'本视觉小说中的角色从大量进食以增重或喂食他人使其增重中获得快感。

故事和画面聚焦于喂食与增重的行为，而不只是出现胖角色。');
INSERT INTO "tags" VALUES ('g1946','微胖角色','cont',123,'本游戏中有一位角色是[url=http://en.wikipedia.org/wiki/Overweight]超重[/url]的。');
INSERT INTO "tags" VALUES ('g1947','游戏开发竞赛','tech',6503,'本视觉小说是作为游戏开发竞赛的一部分而创作的，例如[url=http://www.globalgamejam.org/]Global Game Jam[/url]或[url=http://www.ludumdare.com/]Ludum Dare[/url]。

[url=http://en.wikipedia.org/wiki/Game_jam]游戏开发竞赛[/url]是游戏开发者聚集在一起，在短时间内（通常为24到48小时）规划、设计和创作一款或多款游戏的活动。');
INSERT INTO "tags" VALUES ('g1948','新世纪福音战士','cont',56,'本视觉小说的世界观与[url=http://en.wikipedia.org/wiki/Neon_Genesis_Evangelion]新世纪福音战士[/url]相同，或包含该系列中的角色。');
INSERT INTO "tags" VALUES ('g1950','双方自愿的情色羞辱','ero',165,'[URL=http://en.wikipedia.org/wiki/Humiliation_%28BDSM%29]情色羞辱[/URL]是在双方自愿的情况下，为了被羞辱与贬低者、实施羞辱者或某些旁观者的情色兴奋或性唤起，而进行心理羞辱的行为。它可以是BDSM及其他性角色扮演的一部分，或伴随活动中一方或双方的性刺激。 

羞辱本身不一定具有性本质；与许多其他性活动一样，人们追求的是从中获得的感受，而非实际活动本身的性质。对于被羞辱者来说，这通常是一种顺从感；对于实施羞辱者来说，则是一种支配感。羞辱可以是言语上的或身体上的，也可以在私下或公开进行。');
INSERT INTO "tags" VALUES ('g1951','公共场合自慰','ero',377,'带有此标签的游戏至少有一个场景中某人[URL=http://vndb.org/g1087]公开自慰[/URL]。无论是谨慎进行还是公开进行都无关紧要。');
INSERT INTO "tags" VALUES ('g1952','进击的巨人','cont',38,'带有此标签的视觉小说包含来自[URL=http://en.wikipedia.org/wiki/Shingeki_no_Kyojin]进击的巨人[/URL]的角色，和/或设定在其宇宙中。');
INSERT INTO "tags" VALUES ('g1954','离别结局','tech',303,'此游戏有一个或多个结局，其中主角与所爱之人的关系走向终结。

他们可能因环境（战争、社会等级、家庭搬迁等）而被迫分离，或者他们可能只是意识到不再相爱，因此分手。

请不要将此标签用于游戏[url=http://vndb.org/g877]游戏结束[/url]，仅用于实际路线结局、[url=http://vndb.org/g181]真实结局[/url]和[url=http://vndb.org/g876]带有剧情的坏结局[/url]。当视觉小说只有[url=http://vndb.org/g146]单一结局[/url]时，也可以使用此标签。');
INSERT INTO "tags" VALUES ('g1955','接吻场景','cont',1395,'这些视觉小说有围绕与伴侣接吻的完整场景。');
INSERT INTO "tags" VALUES ('g1956','水果','cont',23,'水果是这款游戏的重要组成部分，或者有许多涉及水果的场景。');
INSERT INTO "tags" VALUES ('g1957','强迫异装','ero',53,'角色不是自愿异装，而是被强迫作为色情羞辱的一种形式。');
INSERT INTO "tags" VALUES ('g1958','主角的侄女作为女主角','cont',71,'这款游戏的女主角之一是主角的侄女。');
INSERT INTO "tags" VALUES ('g1959','那伽女主角','cont',15,'这款游戏的一个或多个女主角是[url=http://en.wikipedia.org/wiki/N%C4%81ga]那伽[/url]。');
INSERT INTO "tags" VALUES ('g1960','魔法少女小圆','cont',24,'此视觉小说包含来自[url=http://en.wikipedia.org/wiki/Puella_Magi_Madoka_Magica]魔法少女小圆[/url]系列的角色。');
INSERT INTO "tags" VALUES ('g1961','主角的员工作为女主角','cont',22,'这款游戏中至少有一位女主角是主角的员工。该女主角直接或间接地从主角那里接受命令。');
INSERT INTO "tags" VALUES ('g1962','濒死性爱','ero',76,'角色在一方（或双方）濒死时发生性行为。

这可能以悲伤浪漫的方式呈现，如恋人进行最后的告别——也可能残酷施虐，一方从另一方的死亡中获得快感。');
INSERT INTO "tags" VALUES ('g1963','主角的对手作为男主角','cont',55,'此游戏有一个或多个与其他英雄或主角存在竞争关系的男主角。这些英雄在与此类竞争相关的事件中拥有许多场景。

竞争不一定是相互的才能应用此标签。');
INSERT INTO "tags" VALUES ('g1964','天才男主角','cont',55,'带有此标签的游戏中，一个或多个英雄被认为是天才。

[URL=http://en.wikipedia.org/wiki/Genius]天才[/URL]是指展现出非凡智力、创造力或独创性的人，通常达到与实现前所未有的洞察飞跃相关联的程度。

请注意，聪明并不等于天才，仅凭高学业成就并不是天才的标志。');
INSERT INTO "tags" VALUES ('g1965','花花公子男主角','cont',73,'这个故事中的一个或多个英雄是花花公子。 

“一个[URL=http://en.wikipedia.org/wiki/Promiscuity#Male_promiscuity]花花公子[/URL]”指与女性发生恋爱关系或性关系，或两者兼而有之，但不结婚或不承诺一段关系的男人。');
INSERT INTO "tags" VALUES ('g1966','爱调情的男主角','cont',179,'带有此标签的游戏中，一个或多个英雄是[URL=http://en.wikipedia.org/wiki/Flirt]爱调情[/URL]的。这个英雄不断调情，无论是确实挑逗还是只是开玩笑。这是“情场浪子”原型典型特征，但并不一定意味着英雄滥交。');
INSERT INTO "tags" VALUES ('g1967','昭和时代','cont',80,'带有此标签的视觉小说设定在日本的昭和时代。 

[URL=http://en.wikipedia.org/wiki/Sh%C5%8Dwa_period]昭和时代[/URL]是日本历史中对应昭和天皇裕仁在位时期，从1926年12月25日至1989年1月7日。');
INSERT INTO "tags" VALUES ('g1968','明治时代','cont',40,'带有此标签的游戏设定在日本的明治时代。

[URL=http://en.wikipedia.org/wiki/Meiji_period]明治时代[/URL]是日本的一个时代，从1868年9月持续到1912年7月。');
INSERT INTO "tags" VALUES ('g1969','江户时代','cont',129,'带有此标签的游戏以日本江户时代为背景。

[URL=http://en.wikipedia.org/wiki/Edo_period]江户时代[/URL]是日本历史上的一个时期，介于1603年至1867年之间，当时日本社会处于德川幕府和国内300位地方大名的统治之下。');
INSERT INTO "tags" VALUES ('g1970','愚人节','tech',178,'这款视觉小说是为[url=http://en.wikipedia.org/wiki/April_Fools''_Day]愚人节[/url]制作的。

愚人节游戏通常短小幽默，往往是对创作者其他作品的戏仿。许多游戏只在限定时间内开放。');
INSERT INTO "tags" VALUES ('g1971','有孩子的女主角','cont',1520,'这部视觉小说中的女主角育有一个或多个子女，无论是亲生的还是收养的。这些子女可能是游戏中的角色，也可能不是。

请勿将此标签用于女主角在游戏接近尾声时才生育的游戏。该标签适用于那些游戏开始时已有孩子，或进入游戏不久后就有孩子的女主角。');
INSERT INTO "tags" VALUES ('g1972','有孩子的男主角','cont',70,'这部视觉小说中的男主角育有一个或多个子女，无论是亲生的还是收养的。这些子女可能是游戏中的角色，也可能不是。');
INSERT INTO "tags" VALUES ('g1973','室町时代','cont',3,'带有此标签的游戏以日本室町时代为背景。 

[URL=http://en.wikipedia.org/wiki/Muromachi_period]室町时代[/URL]（又称足利时代）是日本历史上约从1337年到1573年的一个时期。');
INSERT INTO "tags" VALUES ('g1974','兼有男性和女性恋爱对象','cont',1088,'一款玩家可以攻略至少一位男主角和至少一位女主角的视觉小说。

这并不一定意味着主角是双性恋——可能有多个主角，或者主角的性取向取决于玩家的选择。

这不适用于主角能与同性发展友情路线的情况。该路线必须明确（即使不一定要直白地）是恋爱性质的。');
INSERT INTO "tags" VALUES ('g1975','历史上的不列颠群岛','cont',113,'带有此标签的游戏以[URL=http://en.wikipedia.org/wiki/History_of_England]不列颠群岛历史上的一段时期[/URL]为背景。');
INSERT INTO "tags" VALUES ('g1976','以虚构人物为原型的男主角','cont',144,'带有此标签的游戏中，一位或多位男主角的原型来自其他书籍、动画、卡通、漫画、连环画、电影、戏剧、视觉小说等中的虚构角色。');
INSERT INTO "tags" VALUES ('g1977','以虚构人物为原型的女主角','cont',101,'带有此标签的游戏中，一位或多位女主角的原型来自其他书籍、动画、卡通、漫画、连环画、电影、戏剧、视觉小说等中的虚构角色。');
INSERT INTO "tags" VALUES ('g1978','以神话角色为原型的女主角','cont',30,'带有此标签的游戏中，一位或多位女主角的原型来自[URL=http://en.wikipedia.org/wiki/Mythology]神话记述或故事[/URL]中的角色。神话人物通常是女神、女英雄或具有超能力的人类。');
INSERT INTO "tags" VALUES ('g1979','以神话角色为原型的男主角','cont',31,'带有此标签的游戏中，一位或多位男主角的原型来自[URL=http://en.wikipedia.org/wiki/Mythology]神话记述或故事[/URL]中的角色。神话人物通常是神、英雄或具有超能力的人类。');
INSERT INTO "tags" VALUES ('g1980','以神话角色为原型的主角','cont',27,'带有此标签的游戏的主角，其原型来自[URL=http://en.wikipedia.org/wiki/Mythology]神话记述或故事[/URL]中的角色。神话人物通常是神、英雄或具有超能力的人类。');
INSERT INTO "tags" VALUES ('g1981','以虚构人物为原型的主角','cont',139,'带有此标签的游戏的主角，其原型来自其他书籍、动画、卡通、漫画、连环画、电影、戏剧、视觉小说等中的虚构角色。');
INSERT INTO "tags" VALUES ('g1982','带关西腔的男主角','cont',31,'这位男主角使用关西方言，最常见的是京都或大阪方言，这使他脱颖而出。按照日本人对于该地区人群的刻板印象，他通常也会有与之相配的直率性格。');
INSERT INTO "tags" VALUES ('g1983','与双胞胎的Shimaidon结局','tech',86,'当[url=http://vndb.org/g1690]Shimaidon[/url]关系发生在双胞胎身上的特殊情况。');
INSERT INTO "tags" VALUES ('g1985','自闭症女主角','cont',19,'这部视觉小说中至少有一位女主角患有[url=http://en.wikipedia.org/wiki/Autism]自闭症[/url]。

自闭症是一种神经发育障碍，其特征是社交互动受损、言语和非言语交流受损，以及行为受限、重复或刻板。诊断标准要求症状在孩子三岁之前变得明显。

注意：只有该女主角确实被诊断患有自闭症时，才请使用此标签。例如，不要用于那些仅仅因为过于害羞而无法正常交流的角色。');
INSERT INTO "tags" VALUES ('g1986','仅限女女恋爱','cont',1697,'这款游戏专注于女/女恋爱关系，主角为女性，且只有女性角色可以攻略。');
INSERT INTO "tags" VALUES ('g1988','热血男主角','cont',28,'带有此标签的视觉小说中有一位或多位英雄是热血的。

[URL=http://dictionary.reference.com/browse/hotblooded?s=t]热血[/URL]的人是指：
1. 容易兴奋的；冲动的。
2. 热情的、充满激情的或富有男子气概的。
3. 爱冒险的、令人兴奋的

他们也充满活力，而且通常相当吵闹。');
INSERT INTO "tags" VALUES ('g1989','孩子般暴力的英雄','cont',7,'这类英雄在故事中表现出孩子气的暴力行为。每当他感到沮丧时，就会殴打主角和他人，不管对方是否有错。

这些攻击可能变得极其暴力，但由于被视为喜剧的一部分，不会造成任何永久性伤害。

此标签适用于在日常生活中表现出暴力冲动的英雄。请勿将本标签用于战斗相关场景。另外，当英雄对主角的暴力是出于真正的伤害意图，而非为了喜剧效果而过度夸张时，也不应使用本标签。');
INSERT INTO "tags" VALUES ('g1990','生化人主角','cont',37,'这部视觉小说的主角是生化人——也就是说，其身体至少部分是人造的，但通常由人脑控制。');
INSERT INTO "tags" VALUES ('g1991','怀孕坏结局','tech',182,'怀孕并不总是积极的。根据解读的不同，有时候可能非常不愉快甚至悲惨。
最常见的情况是女主角被[url=http://vndb.org/g84]强奸[/url]或[url=http://vndb.org/g513]寝取[/url]而从主角身边夺走，但也可能有其他原因。唯一条件是怀孕本身必须对故事结局具有负面价值。');
INSERT INTO "tags" VALUES ('g1992','情色电刺激','ero',236,'带有此标签的视觉小说包含一个或多个使用电流来获得性满足的场景。

[URL=http://en.wikipedia.org/wiki/Erotic_electrostimulation]情色电刺激[/URL]是一种人类性行为实践，涉及使用电源（如TENS、EMS、Violet wand或专用情趣装置）对身体的神经施加电刺激，尤其侧重于生殖器部位，以达到性刺激的目的。');
INSERT INTO "tags" VALUES ('g1993','非自愿情色羞辱','ero',376,'带有此标签的视觉小说包含一个或多个场景，其中[URL=http://vndb.org/g1950]羞辱[/URL]被非自愿地用来贬低承受者，并（通常是在性方面）满足施辱者。

这种现象在涉及强奸或复仇的视觉小说中很常见。');
INSERT INTO "tags" VALUES ('g1994','体毛选项','tech',29,'玩家可以设置角色的体毛量。');
INSERT INTO "tags" VALUES ('g1995','面部毛发选项','tech',17,'玩家可以选择角色是否有面部毛发（胡须）。');
INSERT INTO "tags" VALUES ('g1996','与动物自愿性行为','ero',30,'本游戏包含涉及非人类、普通动物生物的自愿性行为场景。');
INSERT INTO "tags" VALUES ('g1997','兽医女主角','cont',3,'本游戏中的一位女主角是从事动物医学的医生，即兽医。');
INSERT INTO "tags" VALUES ('g1998','文本解析器','tech',179,'这些游戏包含一个[url=http://en.wikipedia.org/wiki/Text_parser]文本解析器[/url]，玩家通过输入信息来推进故事，而不是（或除了）从菜单中选择选项。');
INSERT INTO "tags" VALUES ('g1999','精灵主角','cont',80,'主角是一位[url=http://en.wikipedia.org/wiki/Elves_in_fantasy_fiction_and_games]精灵[/url]。

在许多现代奇幻作品中，精灵被描绘为一个半神性的类人种族，与自然和动物友好相处。

奇幻精灵的标志性特征还有他们又长又尖的耳朵。这些耳朵的长度和形状因艺术家或媒介的不同而有所差异。与人类相比，精灵往往不朽或长寿，更加美丽和睿智，感官与知觉更加敏锐，还拥有看似奇异或魔法的能力或技艺。

此标签并非指那种微小、小仙子般的精灵。');
INSERT INTO "tags" VALUES ('g2002','仅限男孩×男孩恋爱','cont',3258,'本游戏专注于男孩/男孩关系，主角为男性，且可攻略的英雄只有男性。');
INSERT INTO "tags" VALUES ('g2003','代理强奸','ero',74,'两人（或更多人）被第三方通过暴力威胁或其他强制手段强迫发生性行为。

换句话说，发生性行为的人均未同意，但强奸的实施者并未亲身参与性行为本身。');
INSERT INTO "tags" VALUES ('g2004','非二元性别角色','cont',1041,'本游戏至少有一名角色自我认同为非二元性别。

非二元性别是不符合公认的男女性别二元划分的性别认同。人们可能感觉自己是两者兼具、两者皆非，或是两者的某种混合。

这与他们的生理性别或外在表现方式无关。

请不要将此标签用于性别未确认的角色。此标签仅用于官方确认为非二元性别的角色。');
INSERT INTO "tags" VALUES ('g2005','正确选项指示器','tech',390,'带有此标签的游戏会通过某种方式告知玩家已做出正确选择。 

这可以是以音效、好感度增加图形等形式呈现。');
INSERT INTO "tags" VALUES ('g2008','结婚结局','tech',790,'带有这种结局的视觉小说至少包含一个关键角色[URL=http://en.wikipedia.org/wiki/Marriage]结婚[/URL]的结局。 

这很可能是主角和恋爱对象。不一定要有[URL=http://en.wikipedia.org/wiki/Wedding]婚礼[/URL]场景。');
INSERT INTO "tags" VALUES ('g2009','无口主角','cont',19,'带有此标签的视觉小说至少包含一位无口的主角。

[URL=http://en.wikipedia.org/wiki/Dandere#D]无口[/URL]角色通常是不善交际和沉默寡言的，但最终会展现出甜蜜、浪漫、充满爱意的温柔一面。');
INSERT INTO "tags" VALUES ('g2011','钟楼','cont',18,'这部视觉小说有一些场景发生在钟楼中，或者故事中经常提到钟楼。');
INSERT INTO "tags" VALUES ('g2014','穿着吊袜带的女主角','cont',261,'这款游戏中至少有一位女主角，在出现她的场景中通常穿着[url=http://en.wikipedia.org/wiki/Garter_belt#Garter_belts]吊袜带[/url]。');
INSERT INTO "tags" VALUES ('g2015','拟人化的无生命物体','cont',141,'这部视觉小说中有一个或多个角色是无生命物体的化身。这包括[url=http://en.wikipedia.org/wiki/Moe_anthropomorphism]萌拟人化[/url]的情况，但不包括拟人化的生物（对于动物，请使用相应的猫娘/狗娘等标签）。');
INSERT INTO "tags" VALUES ('g2016','成就','tech',520,'这款游戏本身包含一个[url=http://en.wikipedia.org/wiki/Achievement_%28video_gaming%29l]成就/奖杯[/url]系统。

如果成就是通过与游戏发行平台绑定的外部程序（例如 Steam、GOG Galaxy 等）提供的，请不要使用此标签。');
INSERT INTO "tags" VALUES ('g2018','妖精','cont',313,'[url=http://en.wikipedia.org/wiki/Fairy]妖精[/url]是欧洲民间传说中一种神话生物或传说中的生物，是灵魂的一种形式，通常被描述为形而上、超自然或异常的。');
INSERT INTO "tags" VALUES ('g2019','现代欧洲','cont',216,'这个故事发生在现代[url=http://en.wikipedia.org/wiki/Europe]欧洲[/url]。
注意："现代"指的是20世纪末到今天之间的一个未指定的时间段。');
INSERT INTO "tags" VALUES ('g2020','虚构的现代欧洲小镇','cont',33,'这部视觉小说以当代欧洲的一个虚构小镇为背景。
注意："现代"指的是20世纪末到今天之间的一个未指定的时间段。');
INSERT INTO "tags" VALUES ('g2022','高中AU','cont',52,'[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/HighSchoolAU]高中AU[/url]是一种平行宇宙故事，其中现有作品中的角色被重新设定在高中环境中。

这是[url=http://en.wikipedia.org/wiki/Alternative_universe_(fan_fiction)]平行宇宙同人小说[/url]的常见设定。然而，也存在由原作同一创作者制作的官方高中AU视觉小说，例如[url=http://vndb.org/v12424]Hakuouki SSL[/url]和[url=http://vndb.org/v14690]CAGE-SCHOOL-[/url]。');
INSERT INTO "tags" VALUES ('g2023','涉及儿童的性行为','ero',451,'本视觉小说包含与萝莉/正太角色的露骨性爱场景，这些角色不仅看起来非常年轻，而且其年龄实际被确认与外貌相符，无论是直接（明确说明他们的年龄）还是间接（例如提及角色是小学生，或女主角还没有来月经）。');
INSERT INTO "tags" VALUES ('g2024','恶作剧的男主角','cont',63,'带有此标签的游戏有一位[URL=http://dictionary.reference.com/browse/mischievous?s=t]恶作剧[/URL]的男主角。

恶作剧的人倾向于或天生喜欢戏弄、惹恼或烦扰他人。通常这是以玩笑的方式进行，但也可能是恶意的。');
INSERT INTO "tags" VALUES ('g2026','僵尸','cont',250,'本作品以[url=http://en.wikipedia.org/wiki/Zombie_(fictional)]僵尸[/url]为特色，这些虚构生物通常被描绘为无意识的、复活的尸体，渴望人肉，常见于恐怖和奇幻主题作品中。僵尸有着复杂的文学传承，其前身从理查德·马西森和H.P.洛夫克拉夫特，到玛丽·雪莱的《弗兰肯斯坦》，借鉴了欧洲民间传说中关于亡灵的故事。“僵尸启示录”的概念，即文明世界因全球僵尸泛滥而沦陷，已成为现代流行艺术的常见题材。');
INSERT INTO "tags" VALUES ('g2027','怪物主角','cont',82,'这款游戏的主角是一个怪物。

怪物是任何虚构的生物，通常出现在传说或恐怖小说中，往往面目可憎，并可能通过其外表或行为引起恐惧或造成身体伤害。');
INSERT INTO "tags" VALUES ('g2028','可避免的NTR（已废弃）','ero',69,'在某些条件下，游戏中的NTR情节可以避免。那些你可以选择不去目睹NTR事件，但这些事件仍在幕后发生的场景，不应被视为可避免的。
与“[url=/g684]仅可避免的NTR[/url]”不同，可避免的NTR意味着游戏中可能存在无法避免的类似NTR的情节。

[b]该标签已废弃，取而代之的是新澄清的标签[url=/g3169]不可避免的NTR[/url]和[url=/g684]完全可避免的NTR[/url]。请使用这些标签，如果不确定该使用哪个标签（例如，因为你还没通关游戏），请使用通用的[url=/g513]NTR[/url]标签。[/b]');
INSERT INTO "tags" VALUES ('g2029','Gokkun','ero',444,'[url=http://en.wikipedia.org/wiki/Gokkun]Gokkun[/url] (ゴックン) 是一个日语术语，指一种性行为，其中一个人（不一定但通常是女性）吞下一名或多名男性的精液，通常是从某种容器中。

“gokkun”一词是拟声词，翻译成英文为“gulp”，即吞咽时发出的声音。');
INSERT INTO "tags" VALUES ('g2030','眼镜选项','tech',151,'玩家可以选择角色是否戴眼镜。');
INSERT INTO "tags" VALUES ('g2031','叔叔/侄子乱伦','ero',5,'这些游戏包含叔叔与侄子之间的性爱场景。他们可能有血缘关系，也可能没有。');
INSERT INTO "tags" VALUES ('g2032','排球社','cont',21,'学校[url=http://en.wikipedia.org/wiki/Volleyball]排球[/url]社及其相关活动在本故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g2033','可解锁的主角（男/女）','tech',336,'本视觉小说包含一位主角（男或女），其路线需要满足一定条件后才能进入。事实上，在此之前甚至可能没有任何迹象表明他们是可攻略角色。');
INSERT INTO "tags" VALUES ('g2036','忘年恋','cont',327,'本视觉小说包含年龄差距显著的角色之间的恋情。

使用此标签表示实际的恋爱关系，而不仅仅是年龄差异巨大的角色之间的性爱场景。');
INSERT INTO "tags" VALUES ('g2038','高度动画化的立绘','tech',571,'带有此标签的游戏使用[url=http://emote.mtwo.co.jp/index.php]E-mote[/url]等软件，通过矢量动画增强其立绘。立绘不必持续动画化，但它们有非常丰富的表情和姿势库，且使用频繁。它们具有普通立绘无法做到的内部运动。

仅嘴唇和眼睑同步不算，但带有此标签的游戏显然使用了此类技术。');
INSERT INTO "tags" VALUES ('g2039','巨乳萝莉女主角','cont',225,'本游戏包含一位具有典型“萝莉”外表的女主角，但她拥有大胸部，而不是这类设计中常见的平坦胸部。');
INSERT INTO "tags" VALUES ('g2040','遮蔽文字','tech',620,'本视觉小说包含被遮蔽的文字，其中单词的全部或部分被无意义的符号（例如 * 或 ●）替换，或以其他方式故意隐藏。通常用于隐藏脏话或对受版权保护材料的引用。

基本上，这是[url=http://vndb.org/g1676]哔声审查[/url]在文字上的对应物。');
INSERT INTO "tags" VALUES ('g2041','跨性别主角','cont',330,'本视觉小说的主角是[url=https://en.wikipedia.org/wiki/Transgender]跨性别者[/url]。主角的“性别认同”（自我认同为女性、男性、两者皆非或两者皆是）与其“被指派性别”（他人根据生理/遗传性别将其识别为男性、女性或间性人）不一致。

“跨性别”并不暗示任何特定的性取向；跨性别者可能认同自己为异性恋、同性恋、双性恋、泛性恋、多性恋或无性恋；有些人可能认为常规的性取向标签对他们不适用或不充分。

他们可能已经进行了永久或部分的性别转换（这可能在故事之前或期间发生），从而成为变性者。

请不要将其与拥有两套生殖器的扶她混淆，跨性别角色只有一套生殖器。');
INSERT INTO "tags" VALUES ('g2042','恋父情结女主角','cont',72,'至少一位女主角是恋父情结者，即总是对父亲（或父亲般的人物）充满热情并过度依恋，愿意为他做任何事的人。

注意：此标签仅用于描述女主角的性格。 
如果女主角（或视觉小说中的普遍人群）将她们的关系视为父女关系，则此标签有效。她们可能有也可能没有真正的父女血缘关系。');
INSERT INTO "tags" VALUES ('g2043','女性恐惧症/男性恐惧症主角','cont',11,'这位主角对女性或男性恐惧到一定程度，即使只是接触或身处其身边也会引发战或逃反应。  

不要与厌恶女性（厌女）的主角或厌恶男性（厌男）的主角混淆。');
INSERT INTO "tags" VALUES ('g2045','腹黑女主角','cont',84,'包含此标签的游戏至少拥有一位腹黑女主角。

腹黑角色是指外表看起来和蔼、友善、天真、善良和/或令人耳目一新，但利用上述特质中的任意组合来隐藏其真实残忍、狡猾、邪恶、工于心计、刻薄和/或施虐倾向的角色。 

尽管带有负面含义，但并非所有腹黑角色都是反派或反社会者。他们的动机因角色本身和故事的“严肃程度”而千差万别。 

该术语源自日语词“Haraguroi（腹黒い）”，意为“黑心；刻薄；诡计多端”。');
INSERT INTO "tags" VALUES ('g2046','异性恋正太','ero',621,'这些游戏包含正太与女性之间的性爱场面。');
INSERT INTO "tags" VALUES ('g2047','同性恋正太','ero',297,'本游戏包含正太与另一名男性之间的性爱场面。');
INSERT INTO "tags" VALUES ('g2048','高个子男主角','cont',173,'本游戏中的男主角比平均水平高出很多。');
INSERT INTO "tags" VALUES ('g2049','矮个子男主角','cont',36,'本游戏中的男主角比平均水平矮很多，但不是正太。');
INSERT INTO "tags" VALUES ('g2050','可爱型男主角','cont',32,'本游戏中的男主角举止可爱。');
INSERT INTO "tags" VALUES ('g2051','扶他对男性','ero',170,'扶他与男性之间的性行为，男性为接受方。');
INSERT INTO "tags" VALUES ('g2054','篮球','cont',49,'篮球在本游戏中扮演重要角色。');
INSERT INTO "tags" VALUES ('g2056','向导女主角','cont',25,'女主角在博物馆、野生动物园、公园、探险或旅行团中担任向导。向导是指带领旅行者或游客穿越未知或不熟悉地点的人。');
INSERT INTO "tags" VALUES ('g2057','空乘女主角','cont',26,'本作（小说）的女主角之一是空乘人员。');
INSERT INTO "tags" VALUES ('g2058','魔法少年男主角','cont',19,'本视觉小说中的魔法少女女主角实际上是一个异装或魔法变身的男孩。');
INSERT INTO "tags" VALUES ('g2059','仇恨故事','cont',28,'与通常的爱情故事不同，人们彼此憎恨，随着故事发展，仇恨逐渐加深……');
INSERT INTO "tags" VALUES ('g2060','无主角','cont',182,'故事中的所有事件（如果真有故事的话）都没有明确的主角。它不特别聚焦于某个人，或对所有角色给予大致相等的出镜时间。');
INSERT INTO "tags" VALUES ('g2062','快速反应事件','tech',98,'在电子游戏中，[url=http://en.wikipedia.org/wiki/Quick_time_event]快速反应事件[/url]（QTE）是一种上下文敏感的游戏玩法，玩家在屏幕提示出现后不久在控制设备上执行操作。它允许在游戏的过场动画或电影序列中对游戏角色进行有限控制。执行提示动作不当或完全未执行，会导致角色任务失败，通常还会立即游戏结束。

注意：请勿将此标签与[url=http://vndb.org/g847]限时选择[/url]混淆。');
INSERT INTO "tags" VALUES ('g2063','背景呻吟','ero',1257,'在本VN的H场景中，可以听到持续的背景声音（通常是循环音轨形式的呻吟或吸吮声）。这与女主角的配音台词无关（即使她们包含类似的呻吟或吸吮声）。 
不要将其与[url=http://vndb.org/g905]交合之声[/url]混淆——因为该标签是关于摩擦的机械声音，而本标签是关于额外的人声（而且通常游戏选项中会有专门的开关）。');
INSERT INTO "tags" VALUES ('g2064','刑讯室','cont',79,'本游戏设有一个专门用于折磨人的地牢或房间（奴隶/绑架受害者/战俘等）。');
INSERT INTO "tags" VALUES ('g2065','拼写错误','tech',433,'本游戏的文本在正字法意义上写得非常糟糕。存在拼写错误、语法错误、重音错置、句子结构混乱、机器翻译文本、用表情符号代替情感描述等。仅当原始作品包含这些错误且后续版本未修复时，才应添加此标签。非官方翻译不应使用此标签，但可以用于其他语言的官方发布版。

如果拼写错误仅出现在异国情调的语言中，请勿使用此标签，例如：日式英语标识、拉丁语诵文、伪德语。');
INSERT INTO "tags" VALUES ('g2066','四人及以上口交','ero',46,'本视觉小说包含一个场景，其中四个或更多角色共同对一根阴茎进行口交。

[url=https://s2.vndb.org/sf/43/130943.jpg]NSFW示例1[/url]
[url=https://s2.vndb.org/sf/42/130942.jpg]NSFW示例2[/url]');
INSERT INTO "tags" VALUES ('g2067','摩擦自慰','ero',128,'本作中的某个角色通过用身体摩擦桌子、书桌、椅子或其他家具的边角来自慰。');
INSERT INTO "tags" VALUES ('g2068','苏联','cont',47,'本视觉小说的故事发生在苏联。');
INSERT INTO "tags" VALUES ('g2069','血液游戏','ero',37,'[url=http://en.wiktionary.org/wiki/bloodplay]血液游戏[/url]是一种性行为，其中参与者被故意割伤以流血。');
INSERT INTO "tags" VALUES ('g2070','酒吧女招待女主角','cont',75,'角色之一是一名酒吧女招待。

酒吧女招待是指在有执照的场所的吧台后通常供应酒精饮料并管理物资和库存的人。这是“调酒师主角”标签的女性版本。');
INSERT INTO "tags" VALUES ('g2071','大量角色立绘','tech',253,'这些视觉小说使用了更多角色立绘，不仅限于主要角色。即使是故事中扮演小角色的角色也有完整的立绘。

注意：此标签用于那些拥有许多完整角色立绘（立ち绘）的游戏，而不仅仅是小的角色头像（[url=http://vndb.org/g737]侧边图像[/url]）。');
INSERT INTO "tags" VALUES ('g2073','公园','cont',94,'故事，或故事的重要部分，发生在公园里。');
INSERT INTO "tags" VALUES ('g2074','无标题画面','tech',75,'没有标题画面，游戏启动时立即自动开始……');
INSERT INTO "tags" VALUES ('g2075','温柔主角','cont',189,'这个故事的主角很温柔，通常关心他人，有礼貌，并考虑他们的感受。他或她更看重伴侣的幸福而非自己的幸福，并且不会在未经同意的情况下做出任何进一步举动。');
INSERT INTO "tags" VALUES ('g2076','同性恋英雄','cont',202,'这部视觉小说中的英雄被认定为[url=http://en.wikipedia.org/wiki/Homosexuality]同性恋[/url]；也就是说，他在感情和/或性方面被其他男性所吸引。

注意：此标签涉及[url=http://en.wikipedia.org/wiki/Sexual_orientation]性取向[/url]，不必然是性经历。一个与其他男性有关系的英雄可能会被认定为[url=http://vndb.org/g1784]双性恋[/url]或异性恋，或者故事可能根本不涉及他的性取向。对于以男性之间的恋爱和/或性行为为主题的视觉小说，请酌情使用[url=http://vndb.org/g98]shounen ai[/url]或[url=http://vndb.org/g83]yaoi[/url]标签。');
INSERT INTO "tags" VALUES ('g2077','经理主角','cont',119,'主角是一个团体或企业的经理或发言人。');
INSERT INTO "tags" VALUES ('g2078','双人乳交','ero',761,'游戏至少包含一个场景，由两名女性同时进行乳交。

乳交（boobjob，也称paizuri）是指用女性乳房刺激男性阴茎。');
INSERT INTO "tags" VALUES ('g2079','坐脸','ero',881,'[url=http://en.wikipedia.org/wiki/Facesitting]坐脸[/url]是一种性行为，其中一方坐在另一方的脸上，通常是为了让口腔刺激生殖器和/或肛门。');
INSERT INTO "tags" VALUES ('g2080','体操女主角','cont',60,'这个故事中至少有一位女主角从事某种体操运动，例如[url=http://en.wikipedia.org/wiki/Aerobics]有氧操[/url]、[url=http://en.wikipedia.org/wiki/Fitness_and_figure_competition]健身[/url]、[url=http://en.wikipedia.org/wiki/Artistic_gymnastics]竞技体操[/url]、[url=http://en.wikipedia.org/wiki/Rhythmic_gymnastics]艺术体操[/url]、[url=http://en.wikipedia.org/wiki/Synchronized_swimming]花样游泳[/url]和[url=http://en.wikipedia.org/wiki/Acrobatic_gymnastics]技巧体操[/url]。这些艺术运动的女性练习者通常穿着紧身裤或连体衣，以最大限度地自由活动。');
INSERT INTO "tags" VALUES ('g2081','狐仙英雄','cont',78,'至少有一位英雄是狐仙——一种能化为人形的狐狸。');
INSERT INTO "tags" VALUES ('g2083','失踪','cont',267,'谜团围绕角色的失踪展开。');
INSERT INTO "tags" VALUES ('g2086','激烈的角色成长（正面）','cont',155,'一个重要角色（主角、英雄、女主角等）经历了向好的剧烈转变。例如，他或她可能一开始是一个无名失败者，是所有人的出气筒，最终成为镇上最厉害的人。这种变化是视觉小说剧情的重要组成部分。');
INSERT INTO "tags" VALUES ('g2087','日裔混血英雄','cont',47,'带有此标签的游戏至少包含一位英雄是[URL=http://en.wikipedia.org/wiki/H%C4%81fu]日裔混血[/URL]。');
INSERT INTO "tags" VALUES ('g2088','有语音的内心想法','tech',377,'角色的想法（通常用括号而不是引号表示）会有语音。可能会使用回声效果来区分有语音的想法和有语音的对话。

注意：不要将此标签与[url=http://vndb.org/g836]有语音的旁白[/url]混淆。');
INSERT INTO "tags" VALUES ('g2089','有孩子的主角','cont',354,'这部视觉小说的主角有一个或多个孩子，无论是亲生的还是领养的。这些孩子可能是也可能不是游戏中的角色。

不要用于主角在游戏临近结束时才有孩子的游戏。此标签适用于那些在游戏开始时就已经有孩子，或者在游戏开始不久后就有孩子的主角。');
INSERT INTO "tags" VALUES ('g2090','立体视觉','tech',26,'兼容3D立体视觉软硬件（Nvidia 3DVision、Tridef、Oculus等），并且能够产生立体视觉游戏体验。');
INSERT INTO "tags" VALUES ('g2091','度假村','cont',51,'这个故事有很多场景设置在[url=http://en.wikipedia.org/wiki/Resort]度假村[/url]。');
INSERT INTO "tags" VALUES ('g2093','可解锁的主角','tech',97,'完成游戏或看到一定数量的内容后，你就能解锁从另一个角色的视角进行游戏。');
INSERT INTO "tags" VALUES ('g2094','保姆','cont',11,'[url=http://en.wikipedia.org/wiki/Babysitting]保姆服务[/url]是一种临时照顾孩子的服务。各年龄段的人都通常将其作为一种工作来从事。');
INSERT INTO "tags" VALUES ('g2095','截图背景','技术',36,'本游戏的背景和/或CG图像是从另一部创意作品（动画、电影、电视剧）中通过视频或图像捕捉工具提取的静止帧。');
INSERT INTO "tags" VALUES ('g2096','肤色选择','技术',385,'在本游戏开始时，玩家可以为角色选择一种肤色，以在游戏中全程显示（通常是苍白肤色或古铜色）。

此标签也适用于在游戏过程中提供切换肤色选项的游戏。');
INSERT INTO "tags" VALUES ('g2097','脱衣游戏','技术',159,'本游戏的主要焦点或目标是脱掉角色的衣服。');
INSERT INTO "tags" VALUES ('g2099','可解锁色情内容','色情',165,'色情场景可以由玩家解锁（例如通过完成路线）。');
INSERT INTO "tags" VALUES ('g2101','跳转到选项','技术',329,'具有“跳转到选项”功能的游戏可让您直接跳到下一个可用选项，或跳回您做出的最后一个选项。');
INSERT INTO "tags" VALUES ('g2102','害羞主角','内容',98,'本游戏中的一位或多位主角是[URL=http://en.wikipedia.org/wiki/Shyness]害羞的[/URL]。

害羞是一种忧虑、不适或尴尬的感觉，尤其是当一个人靠近他人时。这通常发生在新的环境或与不熟悉的人在一起时。害羞可能是自卑人群的一个特征。更强烈的害羞形式通常被称为社交焦虑或社交恐惧症。');
INSERT INTO "tags" VALUES ('g2103','机器人','内容',211,'本游戏以机器人作为故事的重要组成部分。

这包括可能实际安装了AI，也可能没有安装AI的机器人。

如果机器人是主角或主要角色，则适用相应的特定标签。');
INSERT INTO "tags" VALUES ('g2105','改造人主角','内容',22,'这部视觉小说至少有一位主角是[url=http://en.wikipedia.org/wiki/Cyborg]赛博格[/url]——也就是说，其身体至少有一部分是人工的，但通常由人脑控制。');
INSERT INTO "tags" VALUES ('g2106','幕末时代','内容',61,'本游戏发生在日本的幕末时期。 
1853年至1867年间，关于日本的统治方式存在许多动荡。
从德川时代后期到明治时代初期。');
INSERT INTO "tags" VALUES ('g2107','穿泳装的主角','内容',12,'本游戏有相当多的场景可以看到穿泳装的男性角色。不要因为一个海滩事件或其他罕见出场就添加此标签。只有当此类场景相当常见时才添加（例如关于游泳俱乐部的视觉小说等）。');
INSERT INTO "tags" VALUES ('g2109','性爱眼罩','色情',1115,'带有此标签的视觉小说包含一个或多个场景，其中至少一名性爱场景参与者使用眼罩。

[URL=http://en.wikipedia.org/wiki/Blindfold#Sexology]性爱眼罩[/URL]的使用在[URL=https://vndb.org/g220]束缚[/URL]社群内外都很常见。据说使用眼罩可以增强佩戴者的其余感官，将注意力集中在声音、气味和身体接触上。这种增强的意识据说可以通过消除视觉线索来带来更大的兴奋和期待，因为人们无法看到会发生什么。');
INSERT INTO "tags" VALUES ('g2110','反转传教士体位','色情',807,'带有此标签的视觉小说至少包含一个场景，其中性爱场景的参与者采用反转传教士体位。

当女性躺在伴侣的胸口上时，更准确的描述是[URL=http://en.wikipedia.org/wiki/Woman_on_top_(sex_position)#Reverse_missionary_position]反转传教士体位[/URL]。她双腿伸直搁在男性身上，会对女性的阴阜和阴蒂施加更多压力。如果男性分开双腿，女性可以将腿伸入其两腿之间。');
INSERT INTO "tags" VALUES ('g2111','多根阴茎','色情',60,'本视觉小说包含一个场景，其中角色拥有两根或更多阴茎，无论是天生的还是由于暂时效果（魔法、手术等）。');
INSERT INTO "tags" VALUES ('g2112','口交群交','色情',247,'这种群交行为仅限于一个人对多个男性进行口交，通常被称为gangsuck、blowbang或lineup。
所有这些都是俚语“gang bang”的派生词。

[url=https://s2.vndb.org/sf/46/130946.jpg]NSFW示例1[/url]
[url=https://s2.vndb.org/sf/44/130944.jpg]NSFW示例2[/url]
[url=https://s2.vndb.org/sf/45/130945.jpg]NSFW示例3[/url]');
INSERT INTO "tags" VALUES ('g2113','群交','色情',1515,'群交（gang bang）是一种多人依次或同时与特定一个人进行身体性活动的情形。通常，有一个个体是性活动的核心焦点；例如，一个男人或女人被几个男人或女人包围。
与其说是一对一的连续交合，不如说群交是由各种性行为的数量和同时性来定义的，例如阴道性交、肛交、口交或双重插入。

群交并不是由参与者的确切人数来定义的，但通常涉及三个人以上，可能涉及十多人或更多。

群交也不同于群体性行为，例如三人行和四人行，因为群交期间大部分（如果不是全部）性行为都以核心人物为中心或仅与核心人物进行。

[来自[url=http://en.wikipedia.org/wiki/Gang_bang]维基百科[/url]]');
INSERT INTO "tags" VALUES ('g2116','主角叔叔是英雄','cont',23,'视觉小说中的英雄之一是主角的叔叔。');
INSERT INTO "tags" VALUES ('g2117','性幻想','ero',494,'游戏包含角色进行[url=https://en.wikipedia.org/wiki/Sexual_fantasy]性幻想[/url]的场景。这可能发生在手淫活动期间，或作为无所事事的白日梦。');
INSERT INTO "tags" VALUES ('g2118','作为角色的叙述者','tech',122,'这部视觉小说的叙述者本身就是一个独立的角色，与主角不同，并清楚自己叙述故事的角色。他们可能[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/InteractiveNarrator]与角色互动[/url]，提供建议或引导故事，而角色也可能意识到叙述者的存在，并与他们交谈或争论。');
INSERT INTO "tags" VALUES ('g2119','小精灵英雄','cont',46,'这部VN中的一位或多位英雄是小精灵。不是托尔金式的那种精灵族，而是明亮的带翅膀的小精灵类型。');
INSERT INTO "tags" VALUES ('g2120','吸血鬼猎人主角','cont',35,'这部VN的主角是一名吸血鬼猎人。');
INSERT INTO "tags" VALUES ('g2121','怪物猎人英雄','cont',39,'至少有一位英雄是[url=http://en.wikipedia.org/wiki/Monster]怪物[/url]猎人。');
INSERT INTO "tags" VALUES ('g2122','吸血鬼猎人英雄','cont',19,'至少有一位英雄是吸血鬼猎人。');
INSERT INTO "tags" VALUES ('g2124','公主主角','cont',22,'主角是一位东方风格的公主——被其他角色称为“hime”（姬）并不足以使主角符合此标签。');
INSERT INTO "tags" VALUES ('g2125','大小姐主角','cont',116,'这款游戏的主角是一位上流社会女性。

上流社会是由社会中最富有的成员组成的社会阶级，他们也拥有最大的政治权力。上流社会通常包含在最富有的1-2%人口中，并以巨额财富（以地产形式存在）为特征，这些财富代代相传。

此标签关于主角的社会地位，而非指她的行为。');
INSERT INTO "tags" VALUES ('g2126','默认姓名配音','tech',331,'在某些允许你重命名主角的游戏中，如果你保留默认名字，配音角色实际上会大声说出主角的名字。
而不是给他们一个通用的昵称，只用“你”称呼他们，或者在对话中本该出现名字的地方出现尴尬的停顿。');
INSERT INTO "tags" VALUES ('g2127','寻宝','cont',31,'故事中有角色为个人利益寻找遗失已久的宝藏和历史文物。');
INSERT INTO "tags" VALUES ('g2129','中国神话','cont',35,'中国神话强烈影响了这部VN的背景和事件。');
INSERT INTO "tags" VALUES ('g2130','魔法少女奈叶','cont',19,'这些游戏设定在（或包含来自）[url=http://en.wikipedia.org/wiki/Magical_Girl_Lyrical_Nanoha]魔法少女奈叶[/url]宇宙中。');
INSERT INTO "tags" VALUES ('g2133','跨阶级恋爱','cont',92,'带有此标签的游戏涉及浪漫关系，其中相互恋爱（或正在发展恋爱关系）的角色属于不同的[URL=http://en.wikipedia.org/wiki/Social_class]社会阶级[/URL]。');
INSERT INTO "tags" VALUES ('g2134','邪教','cont',219,'带有此标签的视觉小说在其故事中涉及一个[URL=http://en.wikipedia.org/wiki/Cult]邪教[/URL]。');
INSERT INTO "tags" VALUES ('g2136','魔法少年主角','cont',19,'这部视觉小说的魔法少女主角实际上是一个男扮女装的男孩。');
INSERT INTO "tags" VALUES ('g2137','机器人主角','cont',123,'这款游戏的主角是一个[url=http://en.wikipedia.org/wiki/Robot]机器人[/url]——一个由人工智能控制的人造躯体。

与[url=https://vndb.org/g1990]赛博格主角[/url]对比，后者拥有由人脑控制的（部分）人造身体。');
INSERT INTO "tags" VALUES ('g2138','快速固定体位','ero',2829,'这个角色在性交场景中采用速成体位。 

在速成体位中，接受方弯腰，双手撑在家具、自己的膝盖或墙壁上以保持平衡。插入方从后方插入接受方，并抓住其臀部作为支撑进行抽插。

[url=https://s.vndb.org/sf/68/84168.jpg]示例1[/url], [url=https://s.vndb.org/sf/70/84170.jpg]示例2[/url]');
INSERT INTO "tags" VALUES ('g2141','多元恋爱','cont',385,'这部视觉小说包含[url=http://en.wikipedia.org/wiki/Polyamory]多元恋爱[/url]角色。

多元恋爱是指在所有相关人员知情并同意的情况下，实践、渴望或接受与其他人建立不排他的亲密关系，即不排斥其他性关系或亲密关系。');
INSERT INTO "tags" VALUES ('g2142','怪物女主角','cont',664,'这个故事中的一个或多个女主角是[url=http://en.wikipedia.org/wiki/Monster]怪物[/url]。

怪物是任何虚构的生物，通常出现在传说或恐怖小说中，往往面目可憎，可能因其外表或行为引起恐惧或造成身体伤害。');
INSERT INTO "tags" VALUES ('g2147','不可避免的女主角死亡','cont',364,'至少有一条路线（无论是女主角自己的路线还是其他路线）中会出现女主角的死亡场景，且这是无法避免的。如果死亡场景出现在每条路线中或分支点之前，请使用[url=/g3815]完全不可避免的女主角死亡[/url]。

即使女主角后来以某种方式复活，也可以使用此标签。');
INSERT INTO "tags" VALUES ('g2148','可解锁的概念艺术','tech',105,'本游戏包含可解锁的概念艺术。');
INSERT INTO "tags" VALUES ('g2149','萝莉配角','cont',126,'本游戏的其中一名配角是萝莉。');
INSERT INTO "tags" VALUES ('g2150','正太配角','cont',73,'本游戏的其中一名配角是正太。他要么是青春期或青春期前的男孩，要么外表看起来像其中之一。

在将其归类为正太时，年龄一点也不重要。这完全取决于外表。

详情请参阅相关的[url=http://en.wikipedia.org/wiki/Shotacon]维基百科[/url]条目。');
INSERT INTO "tags" VALUES ('g2151','红灯区','cont',29,'带有此标签的视觉小说在游戏的部分或全部内容中设定在红灯区。

[URL=http://en.wikipedia.org/wiki/Red-light_district]红灯区[/URL]是城市区域中集中了卖淫和性相关行业（如性用品商店、脱衣舞俱乐部、成人影院等）的部分。该术语源于曾用作妓院标志的红灯。');
INSERT INTO "tags" VALUES ('g2152','种族灭绝','cont',34,'这部视觉小说包含针对特定种族或意识形态群体的谋杀提及或场景。');
INSERT INTO "tags" VALUES ('g2153','无画廊','tech',2114,'这部视觉小说没有画廊。已看过的结局/CG/事件无法从主菜单中查看。');
INSERT INTO "tags" VALUES ('g2157','食粪症','ero',55,'食粪症（Coprophagia 或 coprophagy）是指食用粪便的行为。');
INSERT INTO "tags" VALUES ('g2158','喝尿','ero',566,'饮用尿液。');
INSERT INTO "tags" VALUES ('g2159','可解锁事件','tech',278,'在你完成游戏/路线并重新开始新周目时，以前不存在的新事件会随机插入（大多在共同路线中）， 

它们主要用于
-在每次游玩中向读者呈现更多故事细节
-作为通往真实路线的渐进式伏笔，通常需要多次游玩才能解锁。
-仅仅是作为一个"奖励事件"。

不要将此与[url=/g1478]奖励支线故事[/url]混淆。与作为"奖励内容"并需要单独访问的支线故事不同，新事件是自然添加到整个故事中的。');
INSERT INTO "tags" VALUES ('g2160','勒颈性交','ero',448,'在因勒颈导致缺氧的状态下进行性交的行为。');
INSERT INTO "tags" VALUES ('g2161','无男女主角','cont',781,'这部视觉小说没有值得一提的明确男主角或女主角。它没有围绕可攻略角色展开的路线。

造成这种情况的原因有很多。也许故事根本没有涉及任何浪漫情节（例如 The 39 Steps），也许主角从未与任何人安定下来（例如 Ikazuchi no Senshi Raidy II ~Jain no Shinden~），又或者它只是一部短篇拔作，没有任何角色塑造，只是主角与一堆随机伴侣经历一系列随机性爱场景（例如 Stopping!!! 9: Natsu no Omoide Hen）。重点在于，在这部视觉小说的语境中谈论"女主角"没有意义。

注意：此标签的目的是防止在完全不适用其他男主角/女主角标签的视觉小说上使用这些标签。');
INSERT INTO "tags" VALUES ('g2162','怪物男主角','cont',100,'这个故事中的一个或多个男主角是[url=http://en.wikipedia.org/wiki/Monster]怪物[/url]。

怪物是任何虚构的生物，通常出现在传说或恐怖小说中，往往面目可憎，可能因其外表或行为引起恐惧或造成身体伤害。');
INSERT INTO "tags" VALUES ('g2163','犬耳男主角','cont',57,'游戏中的一位英雄长着狗一样的耳朵。对于非人类/半人类角色来说，这可能是天生的，也可能只是一个配饰。');
INSERT INTO "tags" VALUES ('g2164','犬男孩英雄','cont',41,'一位或多位英雄是犬男孩。');
INSERT INTO "tags" VALUES ('g2165','校园护士英雄','cont',19,'游戏中的一位英雄是校园护士。

护理是医疗保健行业中的一种职业，专注于照顾个人、家庭和社区，使他们能够达到、维持或恢复最佳健康和生活质量。');
INSERT INTO "tags" VALUES ('g2166','中学生主人公','cont',138,'这部视觉小说的主人公是一名[url=http://en.wikipedia.org/wiki/Middle_school]中学[/url]生。');
INSERT INTO "tags" VALUES ('g2168','Tennis no Ouji-sama','cont',79,'带有此标签的视觉小说包含了来自[URL=http://en.wikipedia.org/wiki/The_Prince_of_Tennis]《网球王子》[/URL]的角色，以及/或者设定在其世界观中。');
INSERT INTO "tags" VALUES ('g2169','三重乳交','ero',135,'游戏至少包含一个场景，三名女性同时进行乳交。

乳交，又称paizuri，涉及女性乳房对男性阴茎的刺激。');
INSERT INTO "tags" VALUES ('g2170','武术家英雄','cont',22,'本游戏中的一位英雄是[url=http://en.wikipedia.org/wiki/Martial_arts]武术[/url]的练习者。');
INSERT INTO "tags" VALUES ('g2171','漫画家英雄','cont',6,'本游戏中的一位英雄是漫画家。

Mangaka是日语中漫画家或卡通画家的称呼。在日本以外，manga通常指日本漫画书，而mangaka指漫画的作者，通常是日本人。');
INSERT INTO "tags" VALUES ('g2172','无感情的主人公','cont',27,'本游戏的主人公在说话或做任何其他事情时，都不表现出任何情感、活力或表情。

具有这种性格的角色通常遭受着某种心理创伤。');
INSERT INTO "tags" VALUES ('g2173','鞋交','ero',165,'[url=http://www.urbandictionary.com/define.php?term=shoejob&defid=375815]鞋交[/url]是一种性行为，女性穿着鞋子用脚按压或挤压男性的生殖器，直到他达到高潮。
