Heeljob指穿高跟鞋的鞋交。
Bootjob指穿靴子的鞋交。');
INSERT INTO "tags" VALUES ('g2174','护士主人公','cont',41,'本游戏的主人公是一名[url=http://en.wikipedia.org/wiki/Nursing]护士[/url]。');
INSERT INTO "tags" VALUES ('g2175','颈手枷性交','ero',164,'带有此标签的游戏有这样一个性爱场景：一个角色在被颈手枷约束时进行性行为。
性行为可以是主动或被动的，双方自愿或非自愿。');
INSERT INTO "tags" VALUES ('g2177','濒死英雄','cont',29,'本游戏中的一位英雄患有绝症。要么从游戏一开始就患病，要么在大部分时间里都是如此。他是否能在游戏中存活取决于游戏，但疾病是他作为角色的重要因素。');
INSERT INTO "tags" VALUES ('g2178','校长英雄','cont',11,'其中一位英雄是资历最深的教师，也是学校的领导者。');
INSERT INTO "tags" VALUES ('g2179','打字游戏','cont',74,'本游戏要求玩家在计时器结束前输入指定的文本或按键。');
INSERT INTO "tags" VALUES ('g2180','来自异世界的主人公','cont',693,'这部视觉小说的主人公来自与视觉小说发生地不同的世界或不同的维度。

此标签的用途是针对那些并非视觉小说设定中土生土长的主人公。

注意：有时此标签可能与[url=/g1162]外星人主人公[/url]等标签重叠。只有当确认主人公来自不同设定时，才应与其他标签结合使用。例如，如果视觉小说发生在火星上，而主人公是外星人，那么就不应使用此标签，因为主人公与设定相符。');
INSERT INTO "tags" VALUES ('g2181','战败强奸','ero',137,'本游戏将“战败强奸”或“胜利强奸”作为其关键机制之一。 

“战败强奸”或“胜利强奸”机制包括在失败或胜利后立即显示的强奸性场景，通常是在战斗中。
这通常伴随着游戏玩法，主人公被强奸以惩罚玩家的失败（战败强奸），或者主人公因玩家胜利而强奸另一个角色（胜利强奸）。');
INSERT INTO "tags" VALUES ('g2182','乳头吸吮','ero',196,'本游戏有怪物或机械对乳头施加吸力的场景。');
INSERT INTO "tags" VALUES ('g2183','舞者英雄','cont',24,'本游戏中的一位或多位英雄是舞者。

舞者是指专业跳舞的人，例如在舞台上。');
INSERT INTO "tags" VALUES ('g2184','乳房压玻璃','ero',462,'在性交场景中，该角色将她的[url=http://boobsonglass.blogspot.it/]乳房压在玻璃上[/url]。

乳房压在玻璃上，顾名思义，就是一个女孩把乳房压在玻璃上的姿势。要达到效果，乳房必须裸露，或者至少T恤是透明的或湿的。');
INSERT INTO "tags" VALUES ('g2186','高个子女主角','cont',128,'本游戏的女主角比平均身高高出不少。');
INSERT INTO "tags" VALUES ('g2187','卡在墙中性交','ero',125,'带有此标签的游戏包含一个性爱场景，其中一人或多人进行性行为，对象是一个或多个卡在墙壁或混凝土块中的角色。 

在这种性行为的[url=https://s.vndb.org/sf/04/83504.jpg]常见版本[/url]中，墙壁将卡住者的身体在腰部区域分成两半，因为身体通常像后入式性姿势一样弯曲，[url=https://s.vndb.org/sf/02/83502.jpg]脸和胸部[/url]在一侧，[url=https://s.vndb.org/sf/03/83503.jpg]臀部和腿部[/url]在另一侧。以这种方式卡住的人随后可能受到来自一侧或两侧的性侵犯。

此标签的某些极端版本考虑完全[url=https://s.vndb.org/sf/05/83505.jpg]卡在混凝土块上[/url]，只从块中露出脸、肛门和阴部。');
INSERT INTO "tags" VALUES ('g2188','悬吊束缚','ero',453,'[url=http://en.wikipedia.org/wiki/Suspension_bondage]悬吊束缚[/url]是一种性束缚形式，被束缚者被悬挂在一个或多个头顶悬挂点上。');
INSERT INTO "tags" VALUES ('g2189','人体烙印','ero',49,'人体烙印或污名化是一种将标记（通常是符号或装饰图案）烙入活人皮肤的过程，目的是使由此产生的疤痕永久化。这是通过使用热的或极冷的烙印铁来进行的。

因此，它将对牲畜烙印的物理技术应用于人类，要么是出于同意作为一种身体改造形式；要么是在胁迫下，作为惩罚或用于标识被奴役或受压迫的人。它也可能作为一种“成人礼”来实践，例如在部落内，或表示成为某个组织的成员或被其接纳。');
INSERT INTO "tags" VALUES ('g2190','澳大利亚','cont',36,'这部视觉小说发生在[url=http://en.wikipedia.org/wiki/Australia]澳大利亚[/url]，这是一个大洋洲国家，包括澳大利亚大陆本土、塔斯马尼亚岛以及众多较小的岛屿。');
INSERT INTO "tags" VALUES ('g2191','非二元性别主角','cont',678,'这款游戏的主角自我认同为非二元性别。

非二元性别是不符合公认的男性和女性二元划分的性别认同。人们可能感觉自己两者都是、两者都不是，或是两者的某种混合。

这与他们的生理性别或外在表现方式无关。

此标签仅适用于官方确认为非二元性别的主角。如果主角的性别不清楚，请使用[url=/g1340]未知性别主角[/url]标签。');
INSERT INTO "tags" VALUES ('g2192','隐秘电话性爱','ero',353,'游戏包含在电话交谈中进行的性行为，通话另一端的人对此行为毫不知情。

注意：如果通话双方都知晓性行为，则应改用[url=https://vndb.org/g1787]电话性爱[/url]标签。');
INSERT INTO "tags" VALUES ('g2193','幼稚暴力主角','cont',11,'这类主角在整个故事中表现出幼稚的暴力行为。每当他/她感到沮丧时就会打别人，不管对方是否该为此负责。

这些攻击可能变得极其暴力，但由于它们被视为喜剧的一部分，并不会造成任何永久性伤害。

此标签适用于在日常生活中表现出暴力冲动的主角。不要将此标签用于战斗相关的情况。此外，当主角的暴力是认真意图造成伤害，而不是为了喜剧而夸张时，也不要使用此标签。');
INSERT INTO "tags" VALUES ('g2194','半龙主角','cont',8,'游戏主角是龙与人类或类似生物的后代。');
INSERT INTO "tags" VALUES ('g2195','与其他角色有关系的女主角','cont',326,'这部视觉小说的至少一位女主角在故事开始时已经处于恋爱关系中，或者在故事一开始便如此。不要将此标签用于与主角的关系（这种情况请使用g880），仅用于与其他角色的关系。

在她的路线中，她可能会与现任伴侣分手并与主角在一起。然而，她也可能维持现有关系——那么主角可能会成为她的情人，或者他们只是保持朋友关系。');
INSERT INTO "tags" VALUES ('g2196','跨性别主角','cont',89,'这款视觉小说的主角是[url=https://en.wikipedia.org/wiki/Transgender]跨性别者[/url]。主角的“性别认同”（自我认同为女性、男性、两者皆非或两者皆是）与其“指定性别”（他人根据生理/遗传性别认定为男性、女性或间性人）不一致。

“跨性别”并不代表任何特定的性取向；跨性别者可能认同自己为异性恋、同性恋、双性恋、泛性恋、多性恋或无性恋；有些人可能认为传统的性取向标签不够合适或不适用于他们。

他可能已经永久或部分地转换到异性（这可能发生在故事之前或期间），从而成为变性者。');
INSERT INTO "tags" VALUES ('g2197','梦魔英雄','cont',51,'一位或多位主角是[url=http://en.wikipedia.org/wiki/Incubus]梦魔[/url]，这是一种男性形态的恶魔，根据神话和传奇传统，它会压在睡眠者身上，尤其是女性，以与她们发生性行为。

关于女性对应角色，请参见[url=/g576]魅魔女主角[/url]。');
INSERT INTO "tags" VALUES ('g2201','主角性别选择','tech',920,'你可以扮演男性或女性（或可能是其他性别）主角。

这可能是不同角色之间的选择（参见[url=/g559]主角选择[/url]），或者只是自定义单一主角性别的选项。');
INSERT INTO "tags" VALUES ('g2202','只有一个坏结局','tech',528,'这款游戏只有一个坏结局。其余结局都是好结局。');
INSERT INTO "tags" VALUES ('g2203','恋父情结主角','cont',7,'这款游戏的主角是一个恋父情结者，这个人总是对父亲（或类似父亲的人物）充满热情且过度依恋，她愿意为他做任何事。

注意：此标签仅用于描述主角的个性。

如果主角（或VN中的一般人群）认为他们的关系是父女或父子，则此标签有效。他们可能有也可能没有真正的亲子关系。');
INSERT INTO "tags" VALUES ('g2204','全身摩擦','ero',35,'游戏至少包含一个以全身摩擦为特色的场景。

全身摩擦是一种非插入式性行为，涉及全身摩擦另一个人的阴茎。要做到这一点，参与角色之间必须有显著的体型差异。 
可能的例子包括：一个小仙女摩擦身体于常人的阴茎，或一个正常女孩摩擦身体于巨人的阴茎。这种性行为大多数时候表现为全身摩擦的施行者试图拥抱接受者的阴茎。

这种性行为被认为是[url=https://vndb.org/g1405]巨物癖[/url]的众多例子之一。

[url=https://s2.vndb.org/sf/87/130887.jpg]NSFW巨人示例[/url]');
INSERT INTO "tags" VALUES ('g2206','祖父/孙子乱伦','ero',4,'这些游戏包含祖父与其孙子之间的性场景。他们可能有或没有血缘关系。');
INSERT INTO "tags" VALUES ('g2207','可命名的宠物','tech',57,'这款视觉小说允许玩家为宠物命名。

注意：此标签仅适用于真正的宠物。不要用于角色扮演宠物的人。');
INSERT INTO "tags" VALUES ('g2212','非原创配乐','tech',1793,'这部VN中的音乐并非专为此VN创作。它要么是授权使用的（非VN的例子是GTA游戏中的游戏内电台），要么开发者使用了免版税音乐。或者，配乐可能是未经许可非法使用的。');
INSERT INTO "tags" VALUES ('g2213','随机选择','tech',27,'在游戏中，选项本身或其结果是随机化的。

一个例子是从10个候选项中随机出现3个选项在屏幕上，或者一个选项导致3个结局中的1个。在不同的游玩中，游戏可能选择3个不同的选项或不同的结局（除非运气让你得到完全相同的结果）。');
INSERT INTO "tags" VALUES ('g2214','风纪委员主角','cont',13,'主角是纪律委员会成员。

纪律委员会是许多学院、大学或高中存在的学生组织，主要目的是在学生中执行校规，例如宵禁。');
INSERT INTO "tags" VALUES ('g2215','双人足交','ero',120,'游戏至少包含一个由两人同时进行的[url=http://en.wikipedia.org/wiki/Footjob]足交[/url]场景。

