INSERT INTO "tags" VALUES ('g2216','梦魔主角','cont',26,'这款游戏的主角是梦魔，一种男性形态的恶魔，根据神话和传奇传统，它会压在睡眠者身上，尤其是女性，以与她们发生性行为。');
INSERT INTO "tags" VALUES ('g2217','和平手势阿黑颜','ero',337,'这个角色被描绘成做出名为[url=https://vndb.org/g1764]阿嘿颜[/url]的表情，同时用一只手的手指做出[url=http://en.wikipedia.org/wiki/V_sign]V字手势[/url]（和平手势/胜利手势），或用双手做出双V手势。

双V手势阿嘿颜（也称为W手势阿嘿颜）也缩写为[url=http://g.e-hentai.org/g/581355/1d1c939056/?p=1]AWP[/url]：（A）阿嘿颜 -（W）双V -（P）和平手势

[url=https://s.vndb.org/sf/56/84856.jpg]NSFW示例：V手势阿嘿颜[/url]
[url=https://s.vndb.org/sf/09/85309.jpg]NSFW示例：W手势阿嘿颜[/url]');
INSERT INTO "tags" VALUES ('g2218','纵向方向','tech',923,'这部视觉小说以[url=http://en.wikipedia.org/wiki/Page_orientation]纵向方向[/url]呈现（高度大于宽度），与更常见的横向方向（宽度大于高度）相对。

