INSERT INTO "tags" VALUES ('g2220','女主角选择','tech',488,'不是（或有时在此外）提供标准选项，而是从菜单中选择你想互动的女主角，通常有每个女主角的可选头像。');
INSERT INTO "tags" VALUES ('g2221','工作场所性爱','ero',217,'这部视觉小说中的一些性爱场景发生在办公室或工作场所。');
INSERT INTO "tags" VALUES ('g2223','无恋爱剧情','tech',1659,'这部视觉小说不注重恋爱，也没有任何专门的恋爱支线剧情。虽然角色之间可能存在吸引力、性张力或挑逗，无论是主要角色还是次要角色，但没有明确聚焦于恋爱。');
