INSERT INTO "tags" VALUES ('g2233','口交鸭子脸','ero',436,'本游戏包含性爱场景，其中一个角色在进行口交时做出 [url=http://g.e-hentai.org/g/464776/49db7f00a9/]\"口交鸭脸\"[/url] 的表情。

