INSERT INTO "tags" VALUES ('g2234','伪娘攻男性','ero',30,'本视觉小说包含伪娘插入或性支配非伪娘男性的场景。');
INSERT INTO "tags" VALUES ('g2235','Arkanoid 游戏','tech',12,'本作包含某种 \"[url=https://en.wikipedia.org/wiki/Arkanoid]Arkanoid[/url]\" 游戏的变体。

玩家控制 \"Vaus\"，一艘充当游戏 \"球拍\" 的太空船，防止球从游戏场中掉落，并尝试将其弹向一堆砖块。球击中砖块会使砖块消失。当所有砖块都被清除后，玩家进入下一关，那里会出现另一组砖块图案。');
INSERT INTO "tags" VALUES ('g2236','双人肚皮交','ero',27,'游戏包含至少一个场景，呈现由两名女性同时进行的肚皮交。

双人肚皮交是一种性行为，将角色的阴茎插入另外两个角色的肚皮之间，通过将她们的肚皮彼此紧贴，阴茎位于中间来实现。

