INSERT INTO "tags" VALUES ('g2239','性高潮剥夺','ero',194,'性高潮剥夺通常与BDSM关系相关。它意味着支配方不允许顺从方达到性高潮。这种剥夺可能持续较长时间（通常涉及g1375），或者以将顺从方带至高潮边缘但不让其真正达到高潮的形式出现。这可能持续几分钟或几个小时。

只要存在一个场景中角色想要高潮却被阻止，该标签即适用。');
INSERT INTO "tags" VALUES ('g2241','肚皮交','ero',45,'游戏包含至少一个呈现肚皮交的场景。

肚皮交是一种性行为，将阴茎插入或顶住女性的肚皮，通常通过将肚皮皮肤包裹在阴茎周围或将其紧贴来实现。为此，施动者通常体重超重或怀孕。

[url=https://s.vndb.org/sf/54/86254.jpg]NSFW包裹示例[/url]');
INSERT INTO "tags" VALUES ('g2242','三人足交','ero',28,'游戏包含至少一个场景，呈现由三人同时进行的[url=https://en.wikipedia.org/wiki/Footjob]足交[/url]。

足交是指以足部进行的性行为。它被认为是足部恋物癖的一部分。相关活动包括趾交（专注于脚趾）和脚底交（仅使用脚掌）。');
INSERT INTO "tags" VALUES ('g2243','旁观者主角','cont',37,'本故事中的主角仅作为行动或故事的旁观者。除了向读者讲述故事外，他们不采取任何重要行动，或者其行动对情节或人物几乎没有影响。

不要与[url=https://vndb.org/g2060]无主角[/url]或[url=https://vndb.org/g902]第三人称叙事[/url]混淆。本故事中的主角是一个真实的人，只是不参与其中。他们可能是[url=https://en.wikipedia.org/wiki/Frame_story]框架故事[/url]的一部分。');
INSERT INTO "tags" VALUES ('g2245','书虫主角','cont',87,'这个游戏中的主角是一个书虫。

书虫是指因书籍内容而爱书，或者热爱阅读的人。

这类主角常常会被人看到读书、携带书籍或谈论书籍。他们也以在学校图书馆或书店工作或闲逛而闻名。');
INSERT INTO "tags" VALUES ('g2247','反向倒插式','色情',141,'此标签下的视觉小说至少包含一个在性场景中采用[url=https://sexinfo101.com/positions/pile-driver/pile-driver-180]反向倒插式[/url]姿势的场景。

在反向倒插式中，接受方以头部和上身支撑躺下，双腿和臀部向上抬起，而插入方站在上方，但背对接受方而非面向对方。');
INSERT INTO "tags" VALUES ('g2248','肛门拳交','色情',143,'此标签下的视觉小说至少包含一个肛门拳交的场景。

