[url=https://s2.vndb.org/sf/57/130957.jpg]NSFW示例2[/url]');
INSERT INTO "tags" VALUES ('g2249','阴茎摩擦','色情',479,'本游戏包含一个或多个阴茎摩擦场景。

阴茎摩擦是一种涉及一男两女的性行为。两名女性将阴部贴在一起摩擦，而男性的阴茎位于她们之间。男性也可以采取更主动的角色，将阴茎在她们阴部之间抽送，或插入其中一名女性（或轮流插入两人）。

[url=https://s.vndb.org/sf/73/85273.jpg]示例1[/url]
[url=https://s.vndb.org/sf/99/70699.jpg]示例2[/url], [url=https://s.vndb.org/sf/74/85274.jpg]示例3[/url] - 不同的姿势。');
INSERT INTO "tags" VALUES ('g2251','乳房摩擦','色情',194,'游戏至少包含一个由小胸角色实施的[url=https://en.wikipedia.org/wiki/Mammary_intercourse]乳交[/url]场景。

