注意：角色有可能意识到这种尝试徒劳无功，便用手帮忙。例如，将阴茎夹在胸口和手掌之间摩擦。此类情况下该特征仍然适用。');
INSERT INTO "tags" VALUES ('g2252','变态女主角','内容',2114,'带此标签的视觉小说中，一名或多名女主角是变态。

[URL=https://en.wikipedia.org/wiki/Perversion#Sexual_usages]变态[/URL]是一种偏离正统或正常理解范畴的人类行为。虽然“变态”一词可以指多种形式的偏离，但最常用于描述被认为特别异常、令人厌恶或执迷的性行为。

请注意，此标签特指性变态。');
