INSERT INTO "tags" VALUES ('g2263','睾丸打击','色情',53,'这款游戏包含[url=http://www.urbandictionary.com/define.php?term=ballbusting]睾丸打击[/url]的场景。

睾丸打击是指故意踢、用膝盖顶或拳打男性睾丸，以使一方或双方产生性唤起或性满足的行为。
行为的实施者直接与支配概念相关联，而接受者则与受虐以及足部/鞋子癖好相关。

[url=https://s.vndb.org/sf/85/87685.jpg]NSFW示例[/url]');
INSERT INTO "tags" VALUES ('g2264','踩踏','色情',78,'这款游戏包含涉及[url=https://en.wikipedia.org/wiki/Trampling]踩踏[/url]的场景。 

踩踏是指被另一个人或多人用脚踩踏的性活动。由于踩踏可以产生疼痛，对某些爱好者而言，踩踏癖好与虐恋癖密切相关。

最常见的踩踏形式是由女性（少数情况下为男性）踩在顺从的男性或女性身上，通常赤脚、穿袜子、丝袜或鞋子进行。施踩者主要会在对方的背部、胸部、腹部、生殖器和面部行走、跳跃和跺脚。

[url=https://s.vndb.org/sf/84/87684.jpg]NSFW示例[/url]');
INSERT INTO "tags" VALUES ('g2265','阴茎与睾丸酷刑装置','色情',57,'这个故事包含多个涉及[url=https://en.wikipedia.org/wiki/Cock_and_ball_torture]阴茎与睾丸酷刑（CBT）[/url]装置或性装置的场景。

阴茎与睾丸酷刑（CBT）是一种涉及折磨男性生殖器的性活动。以下是著名的CBT性装置的部分列表： 
[url=https://s.vndb.org/sf/37/88237.jpg]阴茎环[/url] - [url=https://s.vndb.org/sf/49/88249.jpg]睾丸拉伸器[/url] - 睾丸压碎器 - [url=https://s.vndb.org/sf/39/88239.jpg]阴茎贞操锁[/url] - [url=https://s.vndb.org/sf/48/88248.jpg]阴茎绳[/url] - 睾丸铐 - 降落伞 - [url=https://s.vndb.org/sf/38/88238.jpg]羞辱器[/url]');
INSERT INTO "tags" VALUES ('g2266','阴茎与睾丸酷刑','色情',187,'这款游戏包含一个或多个涉及[url=https://en.wikipedia.org/wiki/Cock_and_ball_torture]阴茎与睾丸酷刑（CBT）[/url]的场景。

阴茎与睾丸酷刑（CBT）是一种涉及折磨男性生殖器的性活动。这可能包括直接对男性生殖器施加痛苦的活动，例如[url=https://s.vndb.org/sf/40/88240.jpg]蜡玩[/url]、[url=https://s.vndb.org/sf/62/88262.jpg]生殖器拍打/鞭打[/url]、[url=https://s.vndb.org/sf/50/88250.jpg]挤压生殖器[/url]、[url=https://s.vndb.org/sf/85/87685.jpg]睾丸打击[/url]、[url=https://s.vndb.org/sf/61/88261.jpg]尿道插入[/url]、[url=https://s.vndb.org/sf/89/66989.jpg]挠痒折磨[/url]、[url=https://s.vndb.org/sf/59/88259.jpg]色情电刺激[/url]或[url=https://s.vndb.org/sf/51/88251.jpg]任何其他折磨睾丸或阴茎的方式[/url]。

此类活动的接受者可能通过受虐获得直接的身体快感，或通过知道这种玩法取悦了施虐的支配者而获得情感快感。此外还有多种多样的[url=https://vndb.org/g2265]CBT性装置[/url]来增强痛苦或快感。');
