INSERT INTO "tags" VALUES ('g2274','模拟现实中的囚禁','续',109,'故事中的角色们被囚禁在一个[URL=https://en.wikipedia.org/wiki/Simulated_reality]模拟现实[/URL]中，无论自愿与否。

这种套路的一个特定变体被称为“食莲者机器”。在这种设定中，一个角色，通常是主角，被打晕或入睡，然后在自己的个人天堂中醒来。实际上，他们被另一个角色囚禁，该角色利用技术、魔法或其他方法，诱发非常强烈且逼真的幻觉。有时食莲者不知道这一切都是假的。有时他们知道但不在乎。[改编自[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/LotusEaterMachine]TV Tropes[/url]]');
