INSERT INTO "tags" VALUES ('g2307','阴茎增强器','ero',10,'本游戏包含至少一个性爱场景，其中一个角色使用了阴茎增强器。

这类性玩具通常由硅胶制成，用于通过以下方式增强人的性表现：
- 增大阴茎，试图在插入过程中获得更大直径
- 延长阴茎，试图获得更长的长度和更深的插入深度
- 增强阴茎，因为玩具表面覆盖着凸点和纹路，试图在插入过程中增强女性的快感

请勿将此标签用于安全套，请改用g731。

