[url=https://s.vndb.org/sf/28/90128.jpg]示例2[/url]');
INSERT INTO "tags" VALUES ('g2310','塔罗牌','cont',36,'[url=https://en.wikipedia.org/wiki/Tarot]塔罗牌[/url]和/或其神秘象征主义在故事中发挥作用。

塔罗牌是一种游戏牌，通常有78张，自15世纪起在欧洲用于纸牌游戏，大约从17世纪开始被神秘学家和占卜师用于占卜。78张牌中的56张（普通52张牌最终由此演变而来）被称为小阿卡纳，与普通牌一样分为四个花色，有编号从1到10的数字牌和四张人物牌（国王、王后、骑士和侍从）。其余22张牌被称为王牌或大阿卡纳，如魔术师、力量、星星等，描绘了象征性的场景。');
