INSERT INTO "tags" VALUES ('g2353','涉及截肢者的性行为','ero',47,'本游戏包含至少一个涉及[url=https://vndb.org/i485]截肢[/url]的性爱场景。

涉及截肢的性行为是指在一场性爱场景中，一名或多名参与者被截去一条或多条肢体。
当截肢行为是由某人（通常是疯子）在性行为之前或期间故意实施，作为一种邪恶行为时，涉及截肢的性行为应与[url=https://vndb.org/g162]guro[/url]结合使用。

