INSERT INTO "tags" VALUES ('g2370','人畜','色情',38,'这部视觉小说包含涉及人类转变为人畜的性场景.

人畜是将人类作为家畜饲养的行为，通常用于挤奶和/或繁殖. 它与[url=https://vndb.org/g1455]宠物扮演[/url]的不同之处有很多因素，首先人畜从来不被视为角色扮演，而是非自愿的，或精神崩溃后 (调教变体) 自愿的，因为它旨在将人类转变成真正的牲畜，而不仅仅是短期羞辱或支配某人. 相反，它可以被视为一种更具体的性奴役形式，其中以下列出的某些或全部要点都应适用.
人畜的关键点:
- 人类被关在马厩中，被锁链拴住或被圈在牛栏或围栏内
- 人类被用于挤奶或繁殖，连接到繁殖机器或挤奶机上，强调他们不再是人类，而只是永远使用的农耕工具
- 人类穿着牛、猪等服装，有时他们也可以通过外科手术转变为动物，例如在截肢后植入动物假肢

[url=https://s.vndb.org/sf/18/91018.jpg]NSFW示例1[/url]
[url=https://s.vndb.org/sf/21/91021.jpg]NSFW示例2[/url]
[url=https://s.vndb.org/sf/20/91020.jpg]NSFW示例3[/url]');
