INSERT INTO "tags" VALUES ('g2380','Time Jump','cont',171,'这个故事涉及一种情节装置，即故事向前跳跃一段相当长的时间，中间的时间段仅在后来的闪回中被提及或展示。');
INSERT INTO "tags" VALUES ('g2382','Living Clothes Sex','ero',43,'这款游戏至少包含一个"活体衣物"发挥重要作用的性爱场景。

"活体衣物"一词指的是能自行活动的衣物。此标签分为两个主要应用领域：
1) 衣物觉醒——衣物通常通过魔法或任何其他超自然方式获得生命，通常描绘为表面下有细小触手的衣物。
2) 用作衣物的怪物——特定怪物附着在身体上并用作衣物。在这些情况下，怪物通常呈现出某件特定衣物的形状，例如胸罩或内裤。

[url=https://s.vndb.org/sf/61/91661.jpg]NSFW示例 衣物觉醒1[/url]
[url=https://s.vndb.org/sf/60/91660.jpg]NSFW示例 衣物觉醒2[/url]

[url=https://s2.vndb.org/sf/98/132498.jpg]NSFW示例 怪物（衣物）1[/url]
[url=https://s2.vndb.org/sf/14/131914.jpg]NSFW示例 怪物（衣物）2[/url]');
INSERT INTO "tags" VALUES ('g2383','Wormhole Sex','ero',19,'这款游戏至少包含一个涉及虫洞性爱的性爱场景。

简而言之：虫洞性爱是一种在传送门内或通过传送门实现插入的性行为。 

详细版本："虫洞性爱"可分为两个子类别： 
1) 由于传送门或虫洞，一个人的身体在物理上同时处于多个位置（也包括多个维度），同时与另一个人发生性关系。这通常被描绘为被插入者的身体被虫洞从物理上切成两半（或更多部分）。在这个版本中，传送门起到的作用类似于"[url=https://vndb.org/g2187]卡在墙里性爱[/url]"标签中墙壁所起的作用。

[url=https://s.vndb.org/sf/63/91663.jpg]NSFW示例1[/url]

2) "虫洞性爱"第二种版本的关键点在于，两个人即使相隔很远，也可以通过虫洞或魔法传送装置进行性行为。例如魔法镜子、手持设备等等。

[url=https://s.vndb.org/sf/62/91662.jpg]NSFW示例2[/url]');
INSERT INTO "tags" VALUES ('g2386','Interracial Sex','ero',309,'这款游戏至少包含一个跨种族性爱场景。 

跨种族性爱是指不同种族成员之间的性行为。在色情内容中，主要用于定义黑人男性与白人女性发生性关系或反之的场景。');
