INSERT INTO "tags" VALUES ('g2390','Forbidden Love','cont',242,'这款游戏包含其社会或家庭认为其关系是禁忌的角色之间的恋情。');
INSERT INTO "tags" VALUES ('g2394','Laid-back Heroine','cont',48,'这款游戏有一位性格温和的女主角；她很少生气、悲伤、焦虑、兴奋等。');
INSERT INTO "tags" VALUES ('g2395','Afterlife','cont',253,'视觉小说发生在[URL=https://en.wikipedia.org/wiki/Afterlife]来世[/URL]中，无论其是否基于现有神话概念（如亚伯拉罕诸教中的天堂与地狱，或天主教中的炼狱）。

来世是一个领域的概念，或领域本身（无论是物质的还是超验的），个体身份或意识的基本部分在个体生前身体死亡后继续存在于此。在一些流行的观点中，这种继续存在通常发生在精神领域；而在其他流行观点中，个体可能会重生到这个世界，重新开始生命周期，很可能对自己过去所做之事毫无记忆。');
INSERT INTO "tags" VALUES ('g2396','对话驱动','技术',371,'这款游戏中绝大部分（如果不是全部）文本由对话构成。

[i]请注意，只有纯视觉小说才能完全以对话为基础并仍符合收录条件。混合视觉小说以叙事存在为要求之一，此标签不应被引用为混合VN应被收录进数据库的理由。[/i]');
INSERT INTO "tags" VALUES ('g2397','非日语配音','技术',1919,'这款游戏包含非日语配音。

如果游戏包含至少一种非日语语言的配音，则应应用此标签。日语配音的有无与应用此标签无关。');
INSERT INTO "tags" VALUES ('g2400','量表显示','技术',374,'这款游戏包含任何形式的“状态量表”作为视觉小说游戏的一部分。

这个量表会根据玩家所做出的[url=https://vndb.org/g1468]选择[/url]而受到正面或负面影响。增减量及结果取决于游戏玩法风格。结果——当达到某个阈值时——可以以两种方式运作：正面或负面。');
INSERT INTO "tags" VALUES ('g2401','软核','色情',166,'这款游戏包含一些H场景，如性交或自慰，但游戏缺乏视觉上的性插入、舔阴、口交或射精。性行为之外裸露生殖器的视觉描绘是否存在，视游戏而定。

被认为过于露骨的图像部分被以多种方式隐藏，例如使用遮盖的头发或衣物、特别放置的手或其他身体部位、场景中精心放置的前景元素（通常是植物、枕头、家具或帷幕）或精心选择的镜头角度。');
INSERT INTO "tags" VALUES ('g2402','作者评论模式','技术',18,'这款游戏拥有可选的评论模式，让你在游玩时听到作者/工作人员的插话。');
INSERT INTO "tags" VALUES ('g2403','辣妹女主角','内容',404,'这款游戏以一名或多名[url=https://vndb.org/i1219]辣妹[/url]或[url=https://vndb.org/i2114]黑辣妹[/url]女主角为特色。
此标签用于区分涉及辣妹和晒黑肤色辣妹的游戏与包含龚古罗的游戏：对于后者请使用[url=https://vndb.org/g593]龚古罗标签[/url]。

要了解龚古罗与黑辣妹之间的区别，请查看[url=https://vndb.org/i2114]黑辣妹[/url]特征示例。');
INSERT INTO "tags" VALUES ('g2405','非循环背景音乐','技术',20,'此标签表示游戏中的BGM完全不会循环播放。

大多数视觉小说拥有原声带，如果单曲结束而新曲尚未触发，那么它就会再次播放。

这里不会发生这种情况。它要么跳到另一曲目，要么如果曲目结束而没有触发新曲目，音乐就会静默。');
INSERT INTO "tags" VALUES ('g2407','存档备注功能','技术',155,'在带有此标签的视觉小说中，玩家可以在游戏的存档界面做笔记。 

玩家可以使用的笔记方法通常是纯文本形式的，例如为每个存档输入简短备忘/标签的功能。');
INSERT INTO "tags" VALUES ('g2408','跳跃惊吓','技术',208,'这款游戏包含[url=https://en.wikipedia.org/wiki/Jump_scare]跳跃惊吓[/url]。

跳跃惊吓是一种常用于恐怖电影和电子游戏中的技巧，旨在通过图像或事件的突然变化让观众受惊，通常伴随响亮、可怕的声音。');
INSERT INTO "tags" VALUES ('g2410','俄罗斯','内容',139,'这部视觉小说发生在[url=https://en.wikipedia.org/wiki/Russia]俄罗斯[/url]。');
INSERT INTO "tags" VALUES ('g2411','100%完成度奖励','技术',173,'带有此标签的视觉小说为达成100%完成度提供特殊奖励。

这通常以祝贺CG的形式出现，但也包括任何*只有*完全完成游戏才能获得的额外内容。');
INSERT INTO "tags" VALUES ('g2412','设计师主角','内容',20,'带有此标签的视觉小说中，一名或多名主角是某种类型的设计师，例如时尚、平面、室内等设计师。

[URL=https://en.wikipedia.org/wiki/Designer]设计师[/URL]是设计产品的人。更正式地说，设计师是规定“设计对象的结构属性”的代理。实际上，任何创造有形或无形物体（如消费品、流程、法律、游戏、图形、服务和体验）的人都被称为设计师。');
INSERT INTO "tags" VALUES ('g2415','独立的文本框','tech',26,'本游戏包含同一屏幕上短暂出现多个文本框的场景。

这类文本框在屏幕上的位置与其指定的说话者相关联。有时它们可以相互堆叠，也许作为一种“打断”的形式。

[url=https://s.vndb.org/sf/70/11970.jpg]示例[/url] - 位置
