[url=https://s.vndb.org/sf/73/11973.jpg]示例[/url] - 堆叠2');
INSERT INTO "tags" VALUES ('g2417','私奔','cont',19,'[URL=https://en.wikipedia.org/wiki/Elopement_%28marriage%29]私奔[/URL]通常指以突然而秘密的方式进行的婚姻，通常涉及与心爱之人匆忙逃离居住地，意图结婚。口语上也用于指任何仓促进行的婚姻，公开订婚期有限或没有公开订婚期。有些情侣选择私奔是因为希望避免父母的反对或宗教义务。');
