这只是一个恶搞选项，不会影响故事或游戏玩法，与[url=/g1143]服装开/关[/url]不同。');
INSERT INTO "tags" VALUES ('g2425','哥特小说','tech',138,'本视觉小说遵循传统[url=https://en.wikipedia.org/wiki/Gothic_fiction]哥特小说[/url]的模式。

这是一种结合了虚构、恐怖、死亡与浪漫的文学类型。它赞美欣快与崇高，同时对忧郁、疯狂、犯罪与怪诞抱有同样强烈的迷恋。');
INSERT INTO "tags" VALUES ('g2426','主角的同父异母/同母异父兄弟作为主角','cont',23,'本游戏的一位主角是主角的同父异母/同母异父兄弟。

同父异母/同母异父兄弟是指与其他兄弟姐妹共享一位亲生父亲的男性兄弟。不要与继兄弟混淆。同父异母/同母异父兄弟有血缘关系，而继兄弟没有。');
INSERT INTO "tags" VALUES ('g2427','带辫子的主角','cont',82,'本游戏至少有一位主角拥有[url=https://en.wikipedia.org/wiki/Braid]辫子[/url]发型。

[url=https://en.oxforddictionaries.com/definition/braid]辫子[/url]（也称发辫）是由三股或更多股头发交织而成的发束。');
INSERT INTO "tags" VALUES ('g2428','书虫主角','cont',45,'本游戏中有一位或多位主角是书虫。

书虫是指因为书籍内容而热爱书籍，或热爱阅读的人。

这类主角经常被看到在读书、携带书籍或谈论书籍。他们以在学校图书馆或书店工作或闲逛而闻名。');
INSERT INTO "tags" VALUES ('g2429','半人主角','cont',28,'本游戏包含一位或多位由人类与不同物种成员结合而生的主角。

例如半精灵、半兽人、半神等……

通过魔法或科学创造的组合属于此标签，但半机械人等不算。');
INSERT INTO "tags" VALUES ('g2430','灯神主角','cont',4,'镇尼（Djinns 或 Jinn）是中东传说中的超自然生物。 
在中东童话中，它们是被奴役并束缚在魔法物品中的强大精灵，有些会被困在其中。它们可以选择隐形或变成各种形态，包括植物、动物、物品，这些形态随后可以拟人化。');
INSERT INTO "tags" VALUES ('g2436','分腿棒','ero',216,'本游戏包含涉及角色被绑在[url=https://en.wikipedia.org/wiki/Spreader_bar]分腿固定棒[/url]上的性爱场景。

分腿固定棒是一种束缚装备，由金属或木制杆组成，可通过绳索或手铐固定在手腕、脚踝或膝盖上，使其保持分开。它的主要目的是限制被捆绑者的行动，并保持手臂或双腿张开，以便无阻碍地接触对象的腹股沟和躯干。

