[url=https://s.vndb.org/sf/40/91040.jpg]NSFW示例3[/url]');
INSERT INTO "tags" VALUES ('g2437','双重插入（群交）','ero',1353,'本游戏包含涉及双重插入的性爱场景。 

双重插入是一种群体性行为，由另外两个人（男性、扶她或使用穿戴式假阳具的女性）同时对阴道和肛门进行插入。

