INSERT INTO "tags" VALUES ('g2438','乳房窒息','ero',204,'本游戏包含涉及乳房窒息的场景。

乳房窒息是一种特殊类型的性窒息，通过将对方的头部按压在（通常巨大的）乳房上来剥夺其氧气。  乳房窒息在涉及[url=https://vndb.org/g184]正太控[/url]、母子关系或BDSM的视觉小说中很常见。

窒息有助于强化BDSM伴侣中的支配与顺从关系，因为支配者拥有完全的控制权。顺从者常常因身体感受到的重量或压力而增强快感。他们也可能享受伴侣如此近距离时的味道和气味。与任何切断人空气供应的活动一样，顺从者也可能因缺氧而产生欣快感。

[url=https://s.vndb.org/sf/64/94264.jpg]NSFW示例1[/url]
