INSERT INTO "tags" VALUES ('g2447','阴蒂生长','ero',81,'这部视觉小说至少包含一个场景，在VN故事中，至少有一个角色因[url=https://en.wikipedia.org/wiki/Clitoral_enlargement_methods]阴蒂增大方法[/url]、魔法或其他因素而出现阴蒂增大。

常见的成人作品增大方法包括： 
- 使用阴蒂泵或阴茎泵
- 用绳子拉扯阴蒂
- 因使用药物或睾酮而增大
- 魔法阴蒂增大

有时阴蒂会变得像拇指上端那么大，有时甚至比手指还长。如果阴蒂在这个过程中变成了功能完全的阴茎，请与[url=https://vndb.org/g1857]阴茎增长[/url]结合使用，当然这并不总是从阴蒂演变而来的。

[url=https://s.vndb.org/sf/58/94658.jpg]NSFW示例 阴蒂泵增大[/url]
[url=https://s.vndb.org/sf/57/94657.jpg]NSFW示例 用绳子增大[/url]
[url=https://s.vndb.org/sf/56/94656.jpg]NSFW示例 大阴蒂[/url]');
INSERT INTO "tags" VALUES ('g2449','恶作剧主角','续',40,'游戏的主角喜欢捉弄或恶作剧其他角色。');
INSERT INTO "tags" VALUES ('g2451','店主女主角','续',64,'这款游戏的女主角是一名[url=https://en.wikipedia.org/wiki/Shopkeeper]店主[/url]。');
INSERT INTO "tags" VALUES ('g2452','音乐回忆','技术',1246,'这款视觉小说允许玩家从菜单中收听其原声带。');
INSERT INTO "tags" VALUES ('g2454','难度设置','技术',163,'这款视觉小说允许玩家设置游戏部分的难度级别。');
INSERT INTO "tags" VALUES ('g2455','可暂停实时','技术',5,'这款即时战略游戏允许玩家在行动期间暂停游戏。玩家可以在暂停时给部队下达命令、在基地排队生产单位和建筑，或进行其他操作。');
INSERT INTO "tags" VALUES ('g2457','运动员主角','续',81,'带有此标签的视觉小说至少包含一位参与体育运动的主角，无论是职业还是业余。

[URL=https://en.wikipedia.org/wiki/Athlete]运动员[/URL]是指参与一项或多项涉及体力、速度和/或耐力的运动的人。运动员可以是职业选手或业余选手。');
INSERT INTO "tags" VALUES ('g2458','婴儿情结女主角','续',55,'这位女主角有着婴儿情结。

她想要一个孩子，并愿意为此做任何事。生育的想法对她来说意味着一切，她基本上对此着迷。
在极端情况下，女主角甚至可能强奸其他角色或使用其他极端方法，只为了拥有孩子。');
INSERT INTO "tags" VALUES ('g2461','可更改字体','技术',1130,'可以在游戏设置中更改显示文本的字体。');
INSERT INTO "tags" VALUES ('g2464','Omegaverse','续',42,'这部VN发生在具有[url=http://fanlore.org/wiki/Alpha/Beta/Omega]Alpha/Beta/Omega动态[/url]的世界观中，在这个世界观里，部分或所有人根据等级制度具有明确的生物角色，这些术语源自动物行为研究。可能涉及狼人、成结或其他动物性元素，或者角色可能以其他方式保持纯粹的人类特征。

具体设定各有不同，但一般来说，Alpha主导，Omega服从，Omega会周期性进入发情期并必须进行性行为。常见的相关情节包括[url=/g1565]男性怀孕[/url]、[url=/g407]必要性行为[/url]、[url=/g1117]BDSM[/url]和[url=http://fanlore.org/wiki/Knotting]成结[/url]。');
INSERT INTO "tags" VALUES ('g2466','可解锁画廊','技术',625,'画廊按钮最初不会出现在菜单中，但可以通过达到视觉小说的某个特定节点来解锁（例如完成一条路线、达到100%完成度、抵达第一个色情场景等）。');
INSERT INTO "tags" VALUES ('g2467','自由视角','技术',48,'这款游戏允许你移动视角或视点。你可以平移、有时缩放或倾斜，以达到你想要的观点。

大多数带有3D模型的3D游戏都具备此功能，但伪3D的2D游戏也能达到类似效果。');
INSERT INTO "tags" VALUES ('g2468','成人吮乳','色情',959,'这部视觉小说中的角色会进行成人哺乳行为。

哺乳行为是直接吮吸乳房的动作，并不需要可见或实际存在的乳汁。此标签仅用于这种特定恋物情结，而非普通的儿童/母亲哺乳。

[url=https://s.vndb.org/sf/51/95951.jpg]NSFW示例[/url]');
INSERT INTO "tags" VALUES ('g2469','离异主角','续',73,'主角已经与前一段婚姻[url=https://en.wikipedia.org/wiki/Divorce]离婚[/url]。');
INSERT INTO "tags" VALUES ('g2470','日本偶像','续',149,'[url=https://en.wikipedia.org/wiki/Japanese_idol]日本偶像[/url]背景在游戏中扮演着重要的主题。

日本偶像是一种流行文化娱乐职业，年轻女演员被包装成值得崇拜的对象，常常因为她们可爱的外表。偶像通常作为榜样。她们参与营销、配音、音乐会和巡演等娱乐活动。偶像也可以聚集在一起组成"偶像团体"。

这个设定中经常涉及多个偶像。但并非总是如此，只要游戏的主题围绕偶像崇拜。');
INSERT INTO "tags" VALUES ('g2471','扶她与女性','色情',402,'扶她与女性（非扶她）之间的性行为，女性为接受方。');
INSERT INTO "tags" VALUES ('g2473','面包师英雄','内容',38,'本游戏的英雄之一是一位[url=https://en.wikipedia.org/wiki/Baker]面包师[/url]。

面包师是使用烤箱或其他集中热源制作、烘烤和销售面包、面包卷、饼干或曲奇饼以及/或薄脆饼干的人。蛋糕和类似食品也可以生产，因为近年来，面包师与糕点厨师所制作的传统界限已经模糊。');
INSERT INTO "tags" VALUES ('g2474','作弊码','技术',32,'本游戏内置了[url=https://en.wikipedia.org/wiki/Cheating_in_video_games#Cheat_codes]作弊码[/url]。

与其他作弊方法不同，作弊码是由游戏开发者自己实现的，通常作为工具，以便轻松测试游戏的某些方面。');
INSERT INTO "tags" VALUES ('g2475','高达','内容',60,'这部视觉小说设定在任何[url=https://en.wikipedia.org/wiki/Gundam]高达[/url]系列的同一宇宙中，或者包含该系列的角色。');
INSERT INTO "tags" VALUES ('g2476','手动前列腺刺激','色情',124,'男性接受前列腺刺激。这与使用假阳具插入不同，这里是通过手指或玩具进行手动刺激，无论是由本人还是他人进行。');
INSERT INTO "tags" VALUES ('g2477','日本迷女主角','内容',15,'一个非日本女主角，总体上对日本，特别是对日本文化痴迷。');
INSERT INTO "tags" VALUES ('g2478','女王主角','内容',36,'本游戏的主角是一位女王。

女王是在位女王，是与男性国王权力相等的女性君主。

王后是在位国王的妻子，没有同等权力。

太后是丈夫已去世的前王后。

而王太后要么是嫡居王后，要么是退位的女王，其儿子或女儿已成为君主。');
INSERT INTO "tags" VALUES ('g2479','变身场景','技术',137,'本游戏包含变身场景。即角色变身的场景，无论是风格上的变身还是整体呈现上的变身。

例子包括男性角色变身为超级英雄，或女性角色变身为[url=https://en.wikipedia.org/wiki/Magical_girl]魔法少女[/url]。');
INSERT INTO "tags" VALUES ('g2480','精灵滤镜','技术',17,'本游戏附带更改角色立绘的选项。游戏玩法和故事不受更改影响。');
INSERT INTO "tags" VALUES ('g2483','母子恋爱','内容',96,'这部视觉小说包含母亲与儿子之间的恋爱。');
INSERT INTO "tags" VALUES ('g2484','人体盛','色情',153,'本游戏包含涉及[url=https://en.wikipedia.org/wiki/Nyotaimori]人体盛[/url]的性爱场景。

人体盛是一种在人体裸体上摆放食物的做法。女体盛是一种特殊的人体盛，涉及寿司和生鱼片，在日本常见。

[url=https://s.vndb.org/sf/39/97139.jpg]NSFW示例[/url]
[url=https://s.vndb.org/sf/42/97142.jpg]NSFW示例2[/url]');
INSERT INTO "tags" VALUES ('g2485','强暴受害者主角','内容',20,'本游戏的一位主人公是强暴的受害者，故事涉及他之后的戏剧冲突和心理问题。

不要用于那些有强暴场景后立即游戏结束的游戏，或那些不将其视为戏剧元素的游戏。');
INSERT INTO "tags" VALUES ('g2490','操作系统模拟','内容',200,'本游戏依赖于模拟现实操作系统的使用，例如DOS电脑或安卓手机，作为推进故事叙事的主要方式之一。');
INSERT INTO "tags" VALUES ('g2491','未命名女主角','内容',61,'本游戏中的女主角从未被以名字称呼。角色们在与她交谈或提及她时，使用诸如''年轻女士''、''老师''或''姐姐''之类的称呼。当需要时，游戏会以''女孩''或类似名称显示该角色。

这不应与可命名女主角混淆，因为这位女主角的名字无法更改。');
INSERT INTO "tags" VALUES ('g2492','未命名男主角','内容',46,'本游戏中的男主角从未被以名字称呼。角色们在与他交谈或提及他时，使用诸如''年轻男士''、''老师''或''哥哥''之类的称呼。当需要时，游戏会以''男孩''或类似名称显示该角色。

这不应与可命名男主角混淆，因为这位男主角的名字无法更改。');
INSERT INTO "tags" VALUES ('g2493','妖精支援角色','内容',49,'本游戏中的妖精角色担任支援角色。');
INSERT INTO "tags" VALUES ('g2494','乳头穿孔','色情',379,'这款视觉小说中至少有一名角色带有乳头穿孔。

[url=https://en.wikipedia.org/wiki/Nipple_piercing]乳头穿孔[/url]是一种身体穿刺，通常以乳头根部为中心。');
INSERT INTO "tags" VALUES ('g2496','有肛毛的女主角','ero',67,'本游戏中一名或多名女性角色在肛门周围有毛发。

在成人动漫角色中，肛毛是毛发角色的极端化表现，通常毛发只生长在阴道周围。有肛毛的角色被认为是粗心又邋遢的角色，通常出现在涉及[url=https://en.wikipedia.org/wiki/Pubic_hair_fetishism]阴毛恋物癖[/url]的小众恋物癖视觉小说中。

[url=https://s.vndb.org/sf/35/97835.jpg]NSFW 示例1[/url]
[url=https://s.vndb.org/sf/33/97833.jpg]NSFW 示例2[/url] 
[url=https://s.vndb.org/sf/34/97834.jpg]NSFW 特写示例[/url]');
INSERT INTO "tags" VALUES ('g2497','怪异的乳头','ero',77,'这款游戏包含以怪异乳头改造为特色的色情场景。

在成人动漫中，常见的怪异乳头改造有三种： 
 - 阴茎乳头：乳头上长有阴茎。
 - 增大/拉伸的乳头：乳头被增大/拉伸到异常大小。
 - 空洞乳头：乳房在乳头位置有一个大洞，这些洞通常用于插入。

[url=https://s.vndb.org/sf/92/89292.jpg]NSFW 阴茎乳头[/url]
[url=https://s.vndb.org/sf/48/2648.jpg]NSFW 拉伸的乳头[/url]
[url=https://s.vndb.org/sf/43/97843.jpg]NSFW 空洞乳头[/url]');
INSERT INTO "tags" VALUES ('g2500','少量强奸','ero',37,'这款视觉小说至少包含一个强奸场景，但与其他性场景的数量相比，强奸场景的数量较少。

例如，如果一个游戏有一个特定的坏结局，其中女主角被强奸，但除此之外性内容都是自愿的，则应用此标签。');
INSERT INTO "tags" VALUES ('g2502','怪物配角','cont',45,'至少有一个怪物型角色担任配角。

无论他们是聪明的非人形生物（例如：哥布林、兽人或蜥蜴人）还是普通生物，在游戏中扮演重要角色的怪物角色都可以归入此类别。

（注：g988和g1640不构成“重要”角色。）');
INSERT INTO "tags" VALUES ('g2504','纯痛苦强奸','ero',73,'带有此标签的视觉小说包含一个或多个强奸场景，在这些场景中，受害者完全感受不到任何快感。

从头到尾，这种行为完全违背受害者的意愿，只会给他们带来痛苦——心理上和/或身体上的。


这与本数据库中大多数作品对强奸的不现实描绘形成鲜明对比，在这些作品中，无论角色遭受多大折磨，快感都是理所当然的。');
INSERT INTO "tags" VALUES ('g2505','有胡须的男主角','cont',360,'这款游戏有一个或多个拥有[url=https://en.wikipedia.org/wiki/Facial_hair]胡须[/url]的男主角。

胡须是人类男性的第二性征，指下巴、下颌及上唇区域或其周围生长的毛发。');
INSERT INTO "tags" VALUES ('g2507','附身强奸','ero',34,'一个人被附身实体从内部控制，被迫强奸他人。附身实体包括恶魔、鬼魂和幽灵。

被附身的角色可能同意也可能不同意性行为，但无论哪种情况，都是附身实体通过被附身的受害者进行性行为。附身者甚至可能在强奸中提供额外手段，包括增强或身体变形。');
INSERT INTO "tags" VALUES ('g2508','校园七大不可思议','cont',98,'[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/TheSevenMysteries]学校七大不可思议[/url]在这个游戏中扮演重要角色。

学校七大不可思议是与特定学校相关的七个神秘传说或鬼故事。它们通常出现在日本学校背景中，并且因学校而异。一些最常见和广为人知的不可思议包括：[url=https://en.wikipedia.org/wiki/Hanako-san]厕所里的花子[/url]、[url=https://en.wikipedia.org/wiki/Aka_Manto]赤纸青纸（红纸、蓝纸）[/url]、[url=https://en.wikipedia.org/wiki/Teke_Teke]Teke Teke[/url]、下楼台阶比上楼多或夜晚台阶数变化的楼梯（第13级台阶）、会活动的解剖模型或[url=https://en.wikipedia.org/wiki/Japanese_friendship_dolls#American_Blue-eyed_dolls]蓝眼睛[/url][url=http://www.bill-gordon.net/dolls/american/index.htm]娃娃[/url]、闹鬼的音乐室（自行弹奏的钢琴、贝多芬画像上闪烁的眼睛）、空无一人的体育馆里弹跳的球、被溺死学生灵魂出没的游泳池、[url=https://en.wikipedia.org/wiki/Ninomiya_Sontoku]二宫金次郎[/url]的雕像在深夜绕着校园跑步，以及隐藏的第八个不可思议的存在。据说，如果有人得知全部七个不可思议，就会发生奇妙或不祥的事情。

注意：带有此标签的视觉小说不必包含全部七个不可思议。');
INSERT INTO "tags" VALUES ('g2510','幽灵支援角色','cont',105,'这部视觉小说包含一个或多个[url=https://en.wikipedia.org/wiki/Ghost]幽灵[/url]支援角色。

在传统信仰中，幽灵是死者或动物的灵魂或精神，能够以可见的形式或其他显现方式出现在生者面前。对幽灵显现的描述差异很大：显现方式可以从不存在的存在感，到半透明或缥缈的形状，再到逼真、栩栩如生的幻象。');
INSERT INTO "tags" VALUES ('g2512','已选选项标记','tech',379,'游戏系统会用不同颜色或其他方式标记已选过的选项，以便于识别。');
INSERT INTO "tags" VALUES ('g2513','务实型女主角','cont',190,'这部视觉小说的女主角基于逻辑、实际和/或理性的考虑与视角做出决定并采取行动。需要注意的是，务实的人不一定冷漠或缺乏感情。');
INSERT INTO "tags" VALUES ('g2516','选角沙发','ero',21,'带有此标签的视觉小说至少包含一个"[URL=https://en.wikipedia.org/wiki/Casting_couch]选角沙发[/URL]"场景。其中有以性服务换取升职、新工作、角色不会失去现有工作等交易内容的性爱场景。

常见情况包括：
1. 为了升职与老板发生性关系。
2. 为了顺利达成商业交易而客户/商业伙伴发生性关系。
3. 为了挽救家族生意而发生性关系。

"[URL=https://ja.wikipedia.org/wiki/%E6%9E%95%E5%96%B6%E6%A5%AD]枕营业[/url]"是日本使用的一个类似术语。');
INSERT INTO "tags" VALUES ('g2517','寻欢洞性爱','ero',112,'本游戏包含涉及"[url=https://en.wikipedia.org/wiki/Glory_hole_(sexual_slang)]寻欢洞[/url]"性爱的性场景。

“glory hole”是墙壁或其他隔板上的一个洞，常见于公共厕所隔间或成人视频游戏厅，供人们进行性活动，或在双方中一方或双方自慰时观察隔壁隔间里的人。除了阴茎，手指、阴蒂、乳房或舌头也可以插入洞中。

不要将其与[url=https://vndb.org/g2187]卡墙性爱[/url]混淆，后者中的人通常卡在洞里，但性行为可以从一侧或两侧自由进行；也不要与[url=https://vndb.org/g2383]虫洞性爱[/url]混淆，后者是通过传送门进行性行为。
（附注：从技术上讲，维度寻欢洞可能存在，在这种情况下两种特征都适用！:P）

[url=https://s.vndb.org/sf/21/98921.jpg]NSFW 寻欢洞性爱[/url]
[url=https://s.vndb.org/sf/23/98923.jpg]NSFW 寻欢洞口交[/url]');
INSERT INTO "tags" VALUES ('g2520','与克隆人群交','ero',153,'本游戏包含仅两人的群体性行为，其中一方拥有自身完全相同的复制体，或双方同时拥有。克隆可通过科学克隆或魔法手段完成（例如：忍者技巧）。

在此群体性行为活动中，克隆的是哪一方并不重要。只要至少一方拥有自身相同的复制体，并且双方与克隆体彼此发生性行为，该标签即可适用。

男性示例：
[url=https://s.vndb.org/sf/04/99004.jpg]NFSW示例1[/url]
[url=https://s.vndb.org/sf/05/99005.jpg]NFSW示例2[/url]（注意头发颜色，包括头部和阴毛）

女性示例：
[url=https://s.vndb.org/sf/06/99006.jpg]NFSW示例1[/url] - 科学？
[url=https://s.vndb.org/sf/07/99007.jpg]NFSW示例2[/url] - 忍者
[url=https://s.vndb.org/sf/08/99008.jpg]NFSW示例3[/url] - 魔法');
INSERT INTO "tags" VALUES ('g2523','花样滑冰女主角','续',13,'本游戏中的女主角是一位[url=https://en.wikipedia.org/wiki/Figure_skating]花样滑冰运动员[/url]；或者说是冰上滑冰者。

花样滑冰是一项运动和活动，个人、双人或团体穿着花样滑冰鞋在冰上表演。这项运动包括一人或两人穿着冰鞋在冰场上表演。通常与冬季奥运会相关，花样滑冰的官方活动包括单人滑、双人滑和冰舞。');
INSERT INTO "tags" VALUES ('g2527','多条共同路线','tech',88,'本视觉小说不止一条“共同路线”。通常以以下方式呈现：

1) 玩家在游戏开始时直接选择想要进入的共同路线。
2) 玩家可能会根据所做的选择进入多条共同路线中的一条。
3) 游戏可能有多个主角，每个主角都有自己的共同路线。

通常，你在这些游戏中可以进入的个人角色路线将取决于你选择/最终进入的共同路线。');
INSERT INTO "tags" VALUES ('g2528','天然呆主角','续',29,'其中一位主角是个天然呆。

天然呆缺乏常识，但态度快乐而友善。');
INSERT INTO "tags" VALUES ('g2529','伪装主角','续',122,'本游戏的主角伪装了自己的个性。

例如，主角可能看起来是一个有礼貌的人（总是彬彬有礼、冷静，主动提供帮助），但这只是掩盖其真实个性的表象——真实个性更加咄咄逼人且容易无礼。

注意，这并不一定意味着主角是邪恶的或叛徒。不要将本标签用于伪装角色，如间谍、刺客等。');
INSERT INTO "tags" VALUES ('g2530','阴道镜摄像头（性用途）','ero',17,'本故事包含使用[url=https://en.wikipedia.org/wiki/Colposcopy]阴道镜[/url]摄像头进行性行为的情节。

阴道镜检查是一种通过阴道镜摄像头对腔口（通常是肛门或阴道）进行的检查。通常（但并非标签适用的必要条件），子宫内壁和宫颈的视频会投射在附近的电脑或笔记本电脑屏幕上，以增强参与者的性欲或羞耻感。

不要将本特性用于常规医学检查。

[url=https://s.vndb.org/sf/21/99821.jpg]NSFW示例1[/url], [url=https://s.vndb.org/sf/20/99820.jpg]NSFW示例2[/url]');
INSERT INTO "tags" VALUES ('g2532','体液管','ero',95,'本作中存在涉及使用体液管的场景。
体液管是一种插入口腔、肛门或阴道的圆柱形管子，用于喂食、交换或运输液体、粪便或其他身体物质。

使用体液管时会出现三种常见场景：
- 粪便交换导致[url=https://vndb.org/i1169]排便癖[/url]
- 管子连接到口腔导致[url=https://vndb.org/g2157]食粪[/url]
- 将液体插入肛门导致[url=https://vndb.org/i1168]灌肠[/url]

不要将此特征用于随意的管子，仅用于导致灌肠、排便癖或食粪的管子，并根据情况相应地将这些特征与此特征结合使用。

[url=https://s.vndb.org/sf/84/99884.jpg]NSFW 体液管[/url]
[url=https://s.vndb.org/sf/83/99883.jpg]NSFW 管子与灌肠[/url]
