INSERT INTO "tags" VALUES ('g2534','穿着太阳裙的女主角','续',79,'本游戏包含一种女主角典型形象，她们主要穿着[url=https://vndb.org/i1582]太阳裙[/url]作为服装。通常这些太阳裙是白色的，有时还搭配佩戴[url=https://vndb.org/i1609]太阳帽[/url]。');
INSERT INTO "tags" VALUES ('g2537','公开使用（调教或非自愿）','成人',153,'本作至少包含一个性场景，涉及一个角色遭受某种形式的性奴役（调教或非自愿），这种形式被非正式地称为“公开使用”或“公共精液垃圾桶”。

“公开使用”或“公共精液垃圾桶”是成人作品中使用的术语，用于指代一种特殊的性奴役形式，即角色被留在原地供每个陌生人或路人性使用（且经常被虐待）。通常，角色的“公开使用（调教或非自愿）”出现在视觉小说中，是在一段以主人失去兴趣或最终惩罚告终的性奴役之旅之后发生的。

“公开使用（调教或非自愿）”特征的关键因素是：
- 极端化了一个概念，即角色被视为不情愿的物体，供所有人进行性使用，实际上这是最彻底的性奴役
- 角色不是一小群人（主角、反英雄、女主角的朋友）的性奴隶，而是被留下供所有人操弄，尤其是陌生人或路人（全城、全校学生等等） 
- 角色被留在公共场所（厕所、市场、广场等）中，受到束缚、被锁在颈手枷上、被锁链锁住，或被关在笼子里或固定在墙上

注意：请将此标签与相关且正确的性奴役标签结合使用。不要将此标签与[url=https://vndb.org/g735]公共场所性行为[/url]混淆，后者并不意味着性奴役。 

[url=https://s.vndb.org/sf/50/100350.jpg]NSFW 示例：颈手枷[/url]
[url=https://s.vndb.org/sf/51/100351.jpg]NSFW 示例：卡住[/url]
[url=https://s.vndb.org/sf/52/100352.jpg]NSFW 示例：厕所 1[/url]
[url=https://s.vndb.org/sf/53/100353.jpg]NSFW 示例：厕所 2[/url]');
INSERT INTO "tags" VALUES ('g2539','生殖器穿孔','成人',190,'这款视觉小说至少包含一个拥有[url=https://en.wikipedia.org/wiki/Genital_piercing]生殖器穿刺[/url]或[url=https://en.wikipedia.org/wiki/Genital_jewellery]生殖器首饰[/url]的角色。

生殖器穿刺是身体穿刺的一种形式。它涉及穿刺生殖器的一部分，从而为佩戴不同类型的首饰创造合适的位置。不过，该术语也可能以部分代全体（pars pro toto）的方式用来表示肛门、会阴、生殖器和阴阜区域的所有身体穿刺，包括不涉及生殖器穿孔的肛穿刺、会阴穿刺（guiche）和阴阜穿刺等。
生殖器首饰，又称性首饰或成人首饰，是专门设计用于佩戴在生殖器上或突出生殖器的首饰。

