INSERT INTO "tags" VALUES ('g2542','家庭暴力','cont',227,'本游戏包含[url=https://en.wikipedia.org/wiki/Domestic_violence]家庭暴力[/url]的场景或主题。这可能是某个角色对配偶或家庭成员的身体暴力，或其他形式的虐待行为。

