INSERT INTO "tags" VALUES ('g2553','救生员女主角','cont',16,'本游戏中的一位或多位女主角是[url=https://en.wikipedia.org/wiki/Lifeguard]救生员[/url]。

救生员是负责监督游泳者、冲浪者以及其他水上运动参与者（如在游泳池、水上乐园或海滩）的安全和救援的人员。');
INSERT INTO "tags" VALUES ('g2554','肛门怪物分娩','情色',56,'本游戏包含这样的场景：在故事过程中，角色通过肛门进行[url=https://en.wikipedia.org/wiki/Viviparity]胎生[/url]分娩，生出各种非人类生物或怪物。 
