[url=https://s.vndb.org/sf/40/101340.jpg]NSFW 胶带木乃伊化[/url]');
INSERT INTO "tags" VALUES ('g2569','太空海盗女主角','cont',7,'这个故事中至少有一位女主角是[url=https://en.wikipedia.org/wiki/Space_pirate]太空海盗[/url]。

太空海盗在外太空以海盗身份活动，乘坐宇宙飞船旅行，这与地球上传统公海的海盗不同，后者乘船旅行。然而，正如传统海上海盗以帆船为目标一样，太空海盗在科幻媒体中也扮演着类似的角色：他们捕获和掠夺宇宙飞船以获取货物和战利品，偶尔还会偷走整艘宇宙飞船，并杀死船员。');
INSERT INTO "tags" VALUES ('g2570','女性化','cont',99,'本故事的主角或其中一位男主角以男性身份开始，但通过自己的选择或性训练（无论是否自愿），他的生活方式被改造为伪娘/异装者的生活方式。这个标签的关键不在于外貌，而在于承担明显女性化的任务、行为和角色，并采取女性的举止和姿态。

所有这些通常最终会演变成异装打扮，尤其是穿着与传统顺从女性角色相关的服装，如女学生、秘书或女仆。手术干预和/或变性手术最终可能会发生，但并非必要条件。

在被强迫女性化的情况下，通常还会导致情色羞辱、体罚和戴绿帽。

什么情况不算女性化：
- 角色醒来发现自己变成女孩身体，或魔法般地性别转换的视觉小说
- 角色为了各种目的伪装成异装者，例如潜入女校的视觉小说
- 角色是跨性别者，并在其转变过程中扮演女性角色的视觉小说

关于女性化的视觉小说示例（NSFW）：[url=/v15423]Boku wa Bishoujo Nanka ja Arimasen![/url]。

如果对该标签是否适用有疑问，请注意女性化是一种恋物癖，因此它被用于满足被女性化者或女性化者的欲望。');
INSERT INTO "tags" VALUES ('g2571','男主角与他人的恋爱关系','cont',56,'本视觉小说中至少有一位男主角在故事开始时已经处于恋爱关系中，或者在故事的最初阶段就如此。不要将此标签用于与主角的关系，仅用于与其他角色的关系。

在他的路线中，他可能会与现任伴侣分手并与主角在一起。然而，他也可能维持现有的关系——然后主角可能会成为他的情人，或者他们也可以只是朋友。');
