INSERT INTO "tags" VALUES ('g2574','程序员女主角','cont',48,'这部VN的一位或多位女主角是[url=https://en.wikipedia.org/wiki/Programmer]程序员[/url]。

计算机编程是设计、编写、测试、调试/排除故障和维护计算机程序源代码的过程。

这些源代码以编程语言编写。编程的目的是创建一个表现出特定预期行为的程序。编写源代码的过程通常需要多个不同领域的专业知识，包括应用领域知识、专门算法和形式逻辑。');
INSERT INTO "tags" VALUES ('g2577','仇恨性爱 (合意)','情色',39,'参与性行为的一方憎恨另一方，并且不掩饰这种恨意。愤怒的眼神和辱骂很常见。

注意：尽管有私人感情，但性行为全程完全自愿。如果不是自愿，请使用众多强奸相关标签之一，而不是使用此标签。');
INSERT INTO "tags" VALUES ('g2579','记忆配对 (游戏)','技术',21,'这部VN包含[url=https://en.wikipedia.org/wiki/Concentration_(game)]记忆配对[/url]的某种变体，该游戏也被称为Match Match、Memory、Pelmanism、Shinkei-suijaku、Pexeso或简称为Pairs。这是一种纸牌游戏，所有牌都面朝下放在桌面上，每回合翻开两张牌。游戏的目标是翻出成对的匹配牌。');
INSERT INTO "tags" VALUES ('g2582','方块匹配','技术',56,'益智类游戏的一个子类型。该类型定义为任何通过将物体与其他具有相同大小、形状或颜色的物体进行匹配来消除物体的游戏。 

VNDB之外的例子：俄罗斯方块和宝石迷阵。
VNDB上的例子：v19972');
