INSERT INTO "tags" VALUES ('g2591','臂缚','情色',37,'本VN至少包含一个场景，其中一名角色穿着[url=https://en.wikipedia.org/wiki/Armbinder]臂缚[/url]进行性行为。

臂缚是一种主要用于束缚调教（而非执法、医疗或精神病学）的限制装置，旨在将手臂和/或手腕相互或与身体绑在一起，通常绑在背后，并使用一系列束缚装备，包括手铐、杆、带子和手套。

通常被称为单手套或单袖，单手套是被称为臂缚的一类束缚中最突出的例子，用于束缚调教。

[url=https://s.vndb.org/sf/38/102738.jpg]NSFW示例1[/url]
[url=https://s.vndb.org/sf/39/102739.jpg]NSFW示例2[/url]
[url=https://s.vndb.org/sf/40/102740.jpg]NSFW示例3[/url]');
INSERT INTO "tags" VALUES ('g2592','动物角色扮演','内容',525,'这部视觉小说中有一个角色扮演成动物（狗、猫、兔子等）。

注意：对于[url=https://vndb.org/g753]兽耳[/url]角色，请勿使用这些标签，因为其动物特征是生物学特征，或者代表动物特征的服装和配饰是其正常装束。');
INSERT INTO "tags" VALUES ('g2594','开裆服装女主角','内容',180,'本游戏有大量场景可以看到角色穿着开裆或露胸罩杯的衣服或内衣，这些通常是在性爱场景中穿着以显得更性感或淫荡。 

此标签是通用的，不特定于某一种开裆或露胸罩杯服装，因此所有开裆或露胸罩杯服装都算数。 

重要提示：此标签仅适用于制造的开裆和露胸罩杯服装及内衣，因此撕裂的服装或内衣不算。

在视觉小说中可以找到的示例有：

 - 开裆服装：
 --- [url=https://vndb.org/i2060]开裆紧身裤[/url]、[url=https://vndb.org/i1973]开裆内裤[/url]、[url=https://vndb.org/i2061]开裆连裤袜[/url]

 - 露胸罩杯服装：
 --- [url=https://vndb.org/i1981]露胸罩杯束身衣[/url]、[url=https://vndb.org/i2327]露胸罩杯娃娃装[/url]、[url=https://vndb.org/i1971]露胸罩杯胸罩[/url]

 - 可以是开裆或露胸罩杯两类的服装：
 --- [url=https://vndb.org/i1986]开裆连体袜[/url]、[url=https://vndb.org/i2101]开裆紧身连体衣[/url]、[url=https://vndb.org/i2045]开裆体操服[/url]、[url=https://vndb.org/i2279]开裆微型比基尼[/url]、[url=https://vndb.org/i2344]开裆情趣连体衣[/url]

可以在这些特性的页面上找到示例。');
INSERT INTO "tags" VALUES ('g2595','乳房按压','情色',18,'本视觉小说包含至少一个场景，涉及性活动，其中一名角色的乳房被一种名为“乳房按压”的性装置挤压。

