INSERT INTO "tags" VALUES ('g2597','老虎角色扮演','续',9,'本视觉小说有一些角色进行老虎角色扮演，穿着老虎服装或连衣裙。

老虎角色扮演的关键要点（并非全部必须满足才能适用此标签）：虎耳（发箍、头罩、帽子等）、虎尾、虎爪手套、类似虎皮的老虎服装（紧身连体衣、连裤袜、手套等）。

如果是性角色扮演，请与[url=https://vndb.org/g1455]宠物扮演[/url]结合使用。

