带有性宠物扮演的老虎角色扮演：
[url=https://s.vndb.org/sf/05/103005.jpg]NSFW 示例[/url]');
INSERT INTO "tags" VALUES ('g2599','握蛋','情色',214,'本视觉小说包含至少一个性爱场景，其中角色进行一种称为“握蛋”的非插入式性行为。

握蛋是一种类似手淫的性行为，区别在于不是用手刺激阴茎体，而是用手刺激含有睾丸的阴囊（蛋袋）。

