INSERT INTO "tags" VALUES ('g2609','妇科检查椅','情色',109,'本视觉小说包含至少一个场景，其中角色被束缚在妇科检查椅、医疗椅或实验椅上，并参与性行为。

妇科检查椅是用于妇科检查的设备，其构造包含腿部支架，用于帮助患者张开双腿。在色情作品中，这些椅子主要被用作束缚工具，在捆绑性爱场景中限制角色活动。 

注意：仅当医疗椅被用于完成性爱或捆绑场景时，才可使用此标签。若椅子同时是具有插入功能的高科技设备，请与[url=https://vndb.org/g1631]性爱机械[/url]标签结合使用。

[url=https://s.vndb.org/sf/40/103140.jpg]NSFW示例1[/url], [url=https://s.vndb.org/sf/41/103141.jpg]NSFW示例2[/url], [url=https://s.vndb.org/sf/42/103142.jpg]NSFW示例3[/url]
[url=https://s.vndb.org/sf/43/103143.jpg]NSFW配备性爱机械的椅子示例[/url]');
INSERT INTO "tags" VALUES ('g2612','现代不列颠群岛','续',78,'故事背景设定在当代的[URL=https://en.wikipedia.org/wiki/British_Isles]不列颠群岛[/URL]。

不列颠群岛是欧洲大陆西北海岸外的一组岛屿群，由大不列颠岛、爱尔兰岛以及超过六千个较小的岛屿组成。两个主权国家位于这些岛屿上：爱尔兰，以及大不列颠及北爱尔兰联合王国。

注意：\"当代\"指的是20世纪末期至今之间的一个未明确指明的时间段。');
INSERT INTO "tags" VALUES ('g2613','三胞胎及以上女主角','续',13,'本游戏包含女主角为[url=https://en.wikipedia.org/wiki/Multiple_birth#Triplets]三胞胎[/url]、四胞胎、五胞胎、六胞胎等的情况。');
INSERT INTO "tags" VALUES ('g2616','主角的堂/表亲作为配角','续',50,'一个或多个配角是主角的[url=https://en.wikipedia.org/wiki/Cousin]堂/表亲[/url]。

堂/表亲是指与某人共享一个或多个共同祖先的亲属（不是父母、子女/后代、兄弟姐妹、兄弟姐妹的子女/后代，或父母/祖先的兄弟姐妹）。不过在通常用语中，\"cousin\"具体指的是一等堂/表亲。');
INSERT INTO "tags" VALUES ('g2617','异世界女主角','续',159,'本视觉小说中至少有一位或以上的女主角来自与本视觉小说所发生世界不同的世界或不同的维度。

此标签的想法是用于那些并非视觉小说设定原住民的女主角。

注意：有时此标签会与[url=/g509]外星人女主角[/url]等标签重叠。仅当女主角被确认为来自不同设定时，才可与其他标签结合使用。例如，如果视觉小说发生在火星上且所有女主角都是外星人，则不应使用此标签，因为这些女主角与其设定相匹配。');
INSERT INTO "tags" VALUES ('g2619','由中段开始（倒叙手法）','技术类',107,'采用[URL=https://en.wikipedia.org/wiki/In_medias_res]由中段开始（in medias res）[/URL]手法的叙事作品，在情节正进行到高潮时展开。通常，背景说明会被略过，而是通过对话、闪回或对过往事件的描述逐步补充完整。

采用\"由中段开始\"手法的作品，往往（但不总是）会随后使用闪回和非线性叙事来交代早期事件，以填补前情背景。

例如，[url=https://vndb.org/v1286]eden*[/url]以谅与紫音已经一起生活在山中作为开篇，之后通过长篇闪回补充前情背景。');
INSERT INTO "tags" VALUES ('g2621','动物主角','续',114,'本游戏的主角是一只[URL=https://en.wikipedia.org/wiki/Animal]现实动物[/URL]，或者在游戏的相当一部分时间内拥有现实动物的身体。

注意：此标签仅指现实世界中存在的动物。此外，由于此标签仅指完全为动物的主角，因此请勿用于兽耳娘主角（请使用[URL=https://vndb.org/g1149]兽耳娘主角[/URL]标签代替）。');
INSERT INTO "tags" VALUES ('g2624','双方同意的痴汉','色情类',38,'在此类痴汉情境中，[url=http://en.wikipedia.org/wiki/Frotteurism]摩擦癖[/url]行为是得到接受方同意的。');
INSERT INTO "tags" VALUES ('g2627','摔跤（运动）','续',49,'带有此标签的游戏以摔跤为特色。

[URL=https://en.wikipedia.org/wiki/Wrestling]摔跤[/URL]是一种格斗运动，涉及擒拿型技术，如缠斗、投掷和摔倒、关节锁定、压制以及其他擒拿技巧。这项运动既可以是娱乐性的戏剧表演，也可以是真正的竞技比赛。摔跤比赛是两名（偶尔更多）参赛者或陪练伙伴之间的身体对抗，他们试图获得并保持优势位置。');
INSERT INTO "tags" VALUES ('g2631','主角的青梅竹马作为支援角色','cont',178,'其中一个支援角色是主角的[url=https://en.wikipedia.org/wiki/Friendship]青梅竹马[/url]。');
INSERT INTO "tags" VALUES ('g2633','舌钉','cont',22,'这部视觉小说中至少有一个角色带有[url=https://en.wikipedia.org/wiki/Tongue_piercing]舌钉[/url]。

舌钉是一种身体穿刺，通常直接穿过舌头的中心。');
INSERT INTO "tags" VALUES ('g2635','可解锁的尾声','tech',410,'带有此标签的视觉小说有一个尾声，需要在满足特定条件（例如达成所有结局）后解锁。

[URL=https://en.wikipedia.org/wiki/Epilogue]尾声[/URL]是文学作品末尾的一段文字，通常用来为作品画上句号。它是从故事内部的角度呈现的。

注意：不要与后记混淆，后记是故事之外的，作者介入并间接向读者说话（注：后记是[URL=https://vndb.org/g1695]可解锁奖励内容[/URL]的半常见类型）');
INSERT INTO "tags" VALUES ('g2643','仅以主角的兄弟作为英雄（们）','cont',24,'游戏中的所有英雄都是主角的兄弟。');
INSERT INTO "tags" VALUES ('g2644','Yangire英雄','cont',28,'这部视觉小说中的一个或多个英雄是[URL=https://vndb.org/i222]yangire[/URL]

Yangire用于描述一个精神不健全的角色，会瞬间爆发，且对爆发受害者不表现出任何感情。

就像yandere角色一样，yangire角色一开始非常可爱温柔，然后突然变得暴力，但区别在于yangire角色的行为与浪漫情感无关。');
