INSERT INTO "tags" VALUES ('g2646','隐形','cont',54,'这些游戏中的角色可以变成[url=https://en.wikipedia.org/wiki/Invisibility]隐形[/url]，无论是永久的还是非永久的，自愿的还是非自愿的。');
INSERT INTO "tags" VALUES ('g2651','无快速存档/读档','tech',1067,'此游戏不提供[url=https://en.wikipedia.org/wiki/Saved_game#Quick_saving]快速保存和加载[/url]的选项。

快速保存和快速加载允许玩家通过单次按键或按钮操作来保存或加载游戏。');
INSERT INTO "tags" VALUES ('g2652','无自动功能','tech',562,'此游戏不提供经过设定时间后自动进入下一个文本框或下一行的选项。
用户只能选择手动按下确认按钮来推进。');
INSERT INTO "tags" VALUES ('g2656','男同性恋NTR','ero',19,'此视觉小说包含一个（或多个）场景，其中一名英雄被另一名男性从主角身边夺走。

要被归类为Netorare，游戏必须满足以下条件：

1. 英雄必须与主角亲近（如他的\她的青梅竹马等）、有浪漫关系，或者是主角的亲近亲属（兄弟、父亲等）。

2. 如果是色情游戏，相关的性事件必须明确展示或随后详细描述。');
INSERT INTO "tags" VALUES ('g2669','Mayadere英雄','cont',13,'带有此标签的视觉小说中，有一个或多个英雄是[URL=https://vndb.org/i219]mayadere[/URL]。

一个致命危险的傲娇，mayadere英雄通常以反派身份开始，但在坠入爱河后转阵营。这个英雄对所有人（包括他所爱的人）都难以预测且危险。');
INSERT INTO "tags" VALUES ('g2678','妄想英雄','cont',18,'带有此标签的视觉小说中有一个或多个妄想型英雄。

[URL=https://en.wikipedia.org/wiki/Delusion]妄想[/URL]是一种尽管有相反的确凿证据仍坚信不疑的信念。与幻觉不同，妄想总是病理性的（疾病或疾病过程的结果）。作为一种病理，它区别于基于虚假或不完整信息的信念、虚构症、教条、错觉或其他感知效应。');
INSERT INTO "tags" VALUES ('g2679','妄想症主角','cont',81,'带有此标签的视觉小说有一个或多个妄想（delusional）的主角。

[URL=https://en.wikipedia.org/wiki/Delusion]妄想[/URL]是一种信念，尽管有相反的有力证据，仍然坚信不疑。与幻觉不同，妄想总是病理性的（疾病或疾病过程的结果）。作为一种病理，它区别于基于错误或不完整信息的信念、虚谈、教条、错觉或其他感知效应。');
INSERT INTO "tags" VALUES ('g2682','摄影师主角','cont',121,'本游戏中的主角是一名摄影师。

[URL=https://en.wikipedia.org/wiki/Photographer]摄影师[/URL]是拍摄照片的人。专业摄影师可能通过薪水或展示、出售或使用这些照片来赚钱。业余摄影师可能为了乐趣而拍照，并记录事件、情感、地点，作为没有金钱动机的人。');
INSERT INTO "tags" VALUES ('g2683','兄弟/兄弟恋爱','cont',31,'这些游戏包含两个兄弟之间的恋爱。');
INSERT INTO "tags" VALUES ('g2684','可解锁序章','tech',43,'带有此标签的视觉小说有一个序章，在满足特定条件（例如达成所有结局）后可解锁。

[URL=https://en.wikipedia.org/wiki/Prologue]序章[/URL]是一个故事的开端，确立背景并提供细节，通常是连接主线的早期故事以及其他杂项信息。');
INSERT INTO "tags" VALUES ('g2685','国王主角','cont',31,'这部视觉小说的主角是一位国王，无论是世袭、政变还是偶然事件所致。

“[URL=https://en.wikipedia.org/wiki/King]国王[/URL]”是在各种语境下给予男性君主的头衔。');
INSERT INTO "tags" VALUES ('g2686','屋顶性爱','ero',301,'此角色在屋顶上进行性行为。这可能包括房屋等“传统”屋顶，或学校等建筑物顶层的开放式外部区域。

[URL=https://e-hentai.org/s/ea49dbb390/41985-294]NSFW 房屋示例[/URL]
[URL=https://e-hentai.org/s/0538da149d/742467-45]NSFW 学校示例[/URL]');
INSERT INTO "tags" VALUES ('g2687','与无脊椎动物的性爱','ero',151,'带有此标签的视觉小说包含涉及无脊椎动物的性爱场景。

[URL=https://en.wikipedia.org/wiki/Invertebrate]无脊椎动物[/URL]是没有脊椎骨的动物。常见的无脊椎动物包括：昆虫；螃蟹、龙虾及其同类；蜗牛、蛤、章鱼及其同类；海星、海胆及其同类；水母和蠕虫。

注意：*不要*将此标签用于形似无脊椎动物的幻想生物——应将它们标记为[URL=https://vndb.org/g988]与怪物性交[/URL]（或其子标签）。');
INSERT INTO "tags" VALUES ('g2689','模组','tech',39,'带有此标签的视觉小说支持并包含[URL=https://en.wikipedia.org/wiki/Mod_(video_gaming)]模组[/URL]和/或用户制作的额外场景。 

仅将此标签用于已有模组的游戏。*不要*将其用于界面补丁、移植到其他引擎、去审查补丁以及类似的技术调整。');
INSERT INTO "tags" VALUES ('g2690','仅限受方主角','ero',46,'在这部视觉小说的BL配对中，所有主角都扮演[URL=https://en.wikipedia.org/wiki/Yaoi#Seme_and_uke]受方（uke）[/URL]（“bottom”/接受方）角色。');
INSERT INTO "tags" VALUES ('g2691','仅限攻方主角','ero',42,'在这部视觉小说的BL配对中，所有主角都扮演[URL=https://en.wikipedia.org/wiki/Yaoi#Seme_and_uke]攻方（seme）[/URL]（“top”/插入方）角色。');
INSERT INTO "tags" VALUES ('g2693','预渲染3D图形','tech',2892,'这款游戏的美术是3D的，但不是实时渲染的。

对于实时3D的作品，请使用标签[URL=https://vndb.org/g417]实时3D[/URL]。');
INSERT INTO "tags" VALUES ('g2694','口塞','ero',418,'带有此标签的视觉小说包含一个或多个在性情境中使用口塞的场景。

[URL=https://en.wikipedia.org/wiki/Gag]口塞[/URL]通常是一种设计用于阻止说话的工具，通常作为约束装置，防止对象呼救并使其保持安静。这通常是通过部分或完全堵住嘴，或试图阻止舌头、嘴唇或下颌正常发声来实现的。

在[URL=https://en.wikipedia.org/wiki/Gag_(BDSM)]BDSM[/URL]中，口塞通常与涉及束缚的角色扮演相关，但并非一定如此。戴口塞的人被视为顺从方，而另一方则被视为支配方。');
INSERT INTO "tags" VALUES ('g2695','点击游戏','tech',34,'带有此标签的视觉小说具有点击游戏玩法。

[URL=https://en.wikipedia.org/wiki/Incremental_game]点击游戏[/URL]是一种视频游戏，其玩法包括玩家重复执行简单操作（如点击屏幕）以获取货币。[1]这可以用来获得物品或能力，从而增加货币累积的速度。');
INSERT INTO "tags" VALUES ('g2701','天体英雄','cont',4,'其中一位英雄是宇宙天体（恒星、行星等）的化身/体现。

更多详情请参见维基百科关于[url=https://en.wikipedia.org/wiki/Astronomical_object]天体[/url]的条目。');
INSERT INTO "tags" VALUES ('g2704','清版格斗','tech',25,'带有此标签的游戏包含清版格斗玩法。

[URL=https://en.wikipedia.org/wiki/Beat_%27em_up]清版格斗[/URL]是一种电子游戏类型，其特点是主角与数量多得不可思议的对手进行徒手格斗。');
INSERT INTO "tags" VALUES ('g2708','游戏内性内容开关','ero',155,'带有此标签的视觉小说具有一种游戏内机制，允许玩家在性内容出现之前或出现时禁用它/启用它。

例如，玩家可以在标题的设置菜单和/或阅读时文本框附近的指定按钮中进行调整。

这可能导致性爱场景被完全移除，或者能够在特定性爱场景出现时进行审查。


**重要提示：此标签仅用于游戏内性内容切换。*不要*为带有"无性内容补丁"、"全年龄版补丁"等的视觉小说添加此标签 - 这些只能在视觉小说的发布部分中指定！**');
INSERT INTO "tags" VALUES ('g2709','肌肉发达的主角','cont',351,'主角肌肉非常发达。通常，他们的特点是体型健硕、庞大、粗犷，从外观上就显得强壮有力。');
INSERT INTO "tags" VALUES ('g2711','扭蛋游戏','tech',92,'此视觉小说的玩法包含扭蛋游戏序列。

[url=https://en.wikipedia.org/wiki/Gashapon#Gacha_games]扭蛋游戏[/url]是一种从大型池中随机抽取数据、人物、英雄等的游戏类型。');
INSERT INTO "tags" VALUES ('g2713','哑巴英雄','cont',9,'故事中的一位英雄患有[url=https://en.wikipedia.org/wiki/Muteness]缄默症[/url]。');
INSERT INTO "tags" VALUES ('g2715','变态英雄','cont',71,'带有此标签的视觉小说中，一位或多位英雄是变态。

[URL=https://en.wikipedia.org/wiki/Perversion#Sexual_usages]性变态[/URL]是一种偏离正统或正常理解的人类行为。虽然性变态一词可以指多种形式的偏离，但最常用于描述被认为特别异常、令人反感或强迫性的性行为。

请注意，此标签特指性变态。');
INSERT INTO "tags" VALUES ('g2720','弓箭手女主角','cont',53,'这款游戏中的一位女主角是弓箭手，无论是作为运动相关的能力还是作为一般的职业技能。

[URL=https://en.wikipedia.org/wiki/Archery]射箭[/URL]是使用弓发射箭矢的运动、练习或技能。历史上，射箭曾被用于狩猎和战斗。在现代，它主要是一项竞技运动和娱乐活动。');
INSERT INTO "tags" VALUES ('g2725','按国籍和族裔划分的英雄','cont',0,'这些是关于英雄或其父母出身的标签。

英雄的[url=http://en.wikipedia.org/wiki/Ethnicity]族裔[/url]和[url=https://en.wikipedia.org/wiki/Nationality]国籍[/url]被用作故事中角色细节的调味料，而非任何其他负面意义，如[url=http://en.wikipedia.org/wiki/Discrimination]歧视[/url]；虽然它们几乎总是[url=http://en.wikipedia.org/wiki/Stereotypical]刻板[/url]的。

无论种族和族裔如何组合，都可以为角色使用这些标签。并且不要制作任何"半日本人"或"四分之一美国人"标签。这些将在以后由新功能覆盖。');
INSERT INTO "tags" VALUES ('g2732','兔耳女主角','cont',162,'用于那些女主角拥有类似兔子的耳朵或任何让人联想到兔子特征作为其标志性部分或外观的游戏，例如带有兔耳的发箍或她的头发形状恰好像兔耳。

请不要与兔女郎标签混淆；几乎每个兔女郎都有兔耳，但并非每个兔耳角色都是兔女郎。兔女郎是[url=https://vndb.org/g123]非人女主角[/url]的子标签，因此不适合用于拥有兔耳的人类女孩。');
INSERT INTO "tags" VALUES ('g2733','兔男郎英雄','cont',54,'此视觉小说中的一位或多位英雄是兔男郎。

注意：此标签指的是兔子特征是永久性的英雄 - 例如，兔子兽耳角色，其兔子特征是他身体的一部分。对于具有非永久性兔子特征的人类英雄 - 例如服装或发型 - 请使用[URL=https://vndb.org/g1439]兔耳英雄[/URL]。');
INSERT INTO "tags" VALUES ('g2739','商人主角','cont',35,'主角是一名商人。

商人是指从事商品交易和营销的人。');
INSERT INTO "tags" VALUES ('g2741','女巫主角','cont',235,'这款游戏的主角是一名女巫，属于深入探讨[url=https://en.wikipedia.org/wiki/Witchcraft]巫术[/url]领域的魔法师。

不要将本标签用于任何能够施法的主角；仅当主角被明确设定为女巫或从事巫术活动时才使用本标签。

男性巫师有时被称为“warlock”，不过“witch”一词也可以作为中性描述词使用。');
INSERT INTO "tags" VALUES ('g2748','中东','cont',52,'本游戏设定在[url=https://en.wikipedia.org/wiki/Middle_East]中东[/url]背景下。');
INSERT INTO "tags" VALUES ('g2749','血腥内容过滤','tech',55,'本游戏有一个选项，可以不显示/隐藏部分血腥CG、立绘和场景。这些内容可以被替换为等效的非血腥内容，或者干脆不显示血腥内容。游戏玩法和故事不受影响。');
INSERT INTO "tags" VALUES ('g2753','性角色扮演','ero',696,'本视觉小说包含角色进行[url=https://vndb.org/g783]角色扮演[/url]的性化场景，即在进行性行为时打扮成另一个虚构角色或生物（真实或虚构的）。');
INSERT INTO "tags" VALUES ('g2756','Seke主角','ero',148,'本主角是一名[url=https://www.urbandictionary.com/define.php?term=seke]Seke[/url]，这意味着主角可以根据恋爱对象或所处情境，逆转“受”和“攻”的角色。

这并不代表本视觉小说具有[url=https://vndb.org/g1820]可逆男男配对[/url]，因为主角不一定在同一段关系中切换角色。他在不同路线中可能扮演不同角色，取决于伴侣。');
INSERT INTO "tags" VALUES ('g2757','非二元性别恋爱对象','cont',281,'本游戏中至少有一位恋爱对象是[url=https://en.wikipedia.org/wiki/Genderqueer]非二元性别或性别酷儿[/url]。

非二元性别是指不符合男女性别二元划分的性别认同。人们可能觉得自己既是两者、既非两者，或是两者的混合。

这与他们的生理性别或外在表现无关。

请勿将本标签用于性别未确认的角色。本标签仅用于官方确认具有非二元性别的角色。');
INSERT INTO "tags" VALUES ('g2758','不孕女主角','cont',10,'女主角的[url=https://en.wikipedia.org/wiki/Infertility]不孕[/url]是故事中的一个情节点。

只要不孕在故事中占有重要地位，她们后来是否能通过魔法或科学手段怀孕并不重要。');
INSERT INTO "tags" VALUES ('g2759','面部放屁','ero',37,'一种支配形式，一个人（通常是女孩）坐在另一个人的脸上，让对方闻自己的屁。这可以给任何一方带来性愉悦。');
INSERT INTO "tags" VALUES ('g2760','度假小屋','cont',67,'游戏设定在一间小屋中，通常是租来的，位于乡村某处，往往靠近水域或其他自然景点。

通常包括一群朋友一起去度假。');
INSERT INTO "tags" VALUES ('g2761','寄宿公寓','cont',21,'本游戏或其许多场景设定在一个[url=https://en.wikipedia.org/wiki/Pension_%28lodging%29]住宿加早餐式场所[/url]，比酒店更小、更私密。');
INSERT INTO "tags" VALUES ('g2765','不可避免的主角死亡','cont',133,'至少有一条路线中（无论是主角自己的路线还是其他路线）存在任何一位主角的死亡场景，并且这是不可避免的。如果死亡场景出现在每一条路线或分支点之前，请使用[url=/g3816]完全不可避免的主角死亡[/url]。

即使主角后来通过某种方式复活，也可以使用本标签。');
INSERT INTO "tags" VALUES ('g2766','物体破处','ero',54,'本视觉小说包含角色用物品/性玩具进行第一次性体验的场景。

[url=https://s2.vndb.org/sf/15/112315.jpg]示例[/url]');
INSERT INTO "tags" VALUES ('g2768','来自其他视角的选择','tech',177,'在本视觉小说中，读者将一次或多次以非主角的视角做出选择。
例如，读者将从一个男主角或女主角的视角做出选择。');
INSERT INTO "tags" VALUES ('g2769','懒惰的主角','cont',28,'其中一位主角很懒，他完全没有动力去做任何事，或者做事时态度敷衍。');
INSERT INTO "tags" VALUES ('g2771','关西口音配角','cont',20,'游戏包含一个非主角/女主角的角色使用关西方言，最常见的是京都或大阪方言。');
INSERT INTO "tags" VALUES ('g2777','系统时间事件','tech',62,'当你在特定日历日期（设备上设置的日期）开始游戏时，游戏会播放一个简短的小事件来庆祝现实或虚构的节日。

示例：
* 在2月14日（情人节）开始游戏时，会播放一位女主角送你巧克力的场景；
* 在游戏中某位女主的生日当天开始游戏，会播放你向她祝贺生日的场景；
* 在新年期间开始游戏，会显示你收到女主角们的问候。');
INSERT INTO "tags" VALUES ('g2778','技师主角','cont',59,'本游戏的主角是一位[url=http://en.wikipedia.org/wiki/Technician]技师[/url]。 

技师是擅长处理机械、装置和技术的人。');
INSERT INTO "tags" VALUES ('g2779','店主英雄','cont',41,'本游戏中的英雄是一位店主。');
INSERT INTO "tags" VALUES ('g2781','怪盗','cont',56,'本游戏围绕怪盗的主题展开。或者用英语说是“[url=https://en.wikipedia.org/wiki/Gentleman_thief]绅士大盗[/url]”。

绅士大盗是一种富有的绅士或淑女的角色原型，具有礼貌、魅力，有时还有荣誉准则。通常，绅士大盗不为利益而偷窃，而是为了刺激。有时还与纠正道德错误、选择富裕目标或只偷特定稀有或具有挑战性的物品相结合。');
INSERT INTO "tags" VALUES ('g2786','近未来','cont',108,'本游戏设定在近未来时期。这是一个介于现代与未来之间的边缘时期。

深入而言，近未来是一个时间上技术上仍属于现代，但社会与生活方式已足够先进，几乎与遥远未来相当的时代。');
INSERT INTO "tags" VALUES ('g2791','弑父','cont',24,'本游戏包含主角或另一角色杀害其父亲的情节。');
INSERT INTO "tags" VALUES ('g2793','逃亡中','cont',135,'在本视觉小说中，一个或多个角色（通常只是主角）正在躲避某人。

也许他们被诬陷犯罪，警察在追捕他们。也许他们确实犯了罪。也许他们惹恼了黑手党老大，现在有职业杀手在跟踪他们。

他们需要低调行事并找到摆脱困境的方法。然而，如果他们要躲避的人先抓住了他们，那就无法做到了。');
INSERT INTO "tags" VALUES ('g2794','王子主角','cont',100,'本故事中至少有一位主角是王子。');
INSERT INTO "tags" VALUES ('g2798','男性对跨性别女性','ero',48,'一位[url=/i2450]跨性别女性[/url]与一名男性发生性关系，跨性别女性为接受方。');
INSERT INTO "tags" VALUES ('g2799','跨性别女性对男性','ero',19,'一位[url=/i2450]跨性别女性[/url]与一名男性发生性关系，男性为接受方。');
INSERT INTO "tags" VALUES ('g2800','男性对扶她','ero',15,'一位[url=/i3103]扶她[/url]与一名男性发生性关系，扶她为接受方。');
INSERT INTO "tags" VALUES ('g2801','扶她对男性','ero',20,'一位[url=/i3103]Body > Dickgirl[/url]与一名男性发生性行为，男性为接受方。');
INSERT INTO "tags" VALUES ('g2806','榨乳（性）','ero',285,'本视觉小说包含涉及[url=https://en.wikipedia.org/wiki/Milking]榨乳[/url]的场景，无论是通过使用榨乳机还是使用自己或他人的手。此标签应用于性情境下的榨乳，而非仅仅用于一些随意的挤牛奶。

尽管乳汁可能被另一角色饮用，但此特征不同于[url=https://vndb.org/g2468]哺乳或母乳喂养[/url]，因为不是用嘴直接吸取乳汁。

[url=https://s.vndb.org/sf/15/112415.jpg]NSFW示例 榨乳机1[/url], [url=https://s.vndb.org/sf/16/112416.jpg]NSFW示例 榨乳机2[/url]
[url=https://s.vndb.org/sf/17/112417.jpg]NSFW示例 容器榨乳1[/url], [url=https://s.vndb.org/sf/19/112419.jpg]NSFW示例 容器榨乳2[/url]');
INSERT INTO "tags" VALUES ('g2814','店主主角','cont',125,'本游戏的主角是一位店主。');
INSERT INTO "tags" VALUES ('g2815','真空床','ero',14,'[url=https://en.wikipedia.org/wiki/Vacuum_bed]真空床[/url]是一种带呼吸孔的全身乳胶信封，置于框架内。当对象躺入其中后，空气被抽出，将里面的人紧紧束缚住。

[url=https://s.vndb.org/sf/51/113151.jpg]NSFW示例[/url]
