INSERT INTO "tags" VALUES ('g2817','漫画家主角','cont',44,'游戏的主角是一位[url=http://en.wikipedia.org/wiki/Mangaka]漫画家[/url]。

漫画家是日语中用来指代漫画艺术家或卡通画家的词。在日本以外，漫画通常指日本漫画书，而漫画家指漫画的作者，通常是日本人。');
INSERT INTO "tags" VALUES ('g2820','可命名角色','tech',6157,'这些游戏有一个或多个可更改姓名的角色。');
INSERT INTO "tags" VALUES ('g2821','开放关系','cont',830,'[URL=https://en.wikipedia.org/wiki/Open_relationship]开放关系[/URL]是一个总称，指任何对新的性伴侣和/或浪漫伴侣开放的关系。

具体来说，它是一种人际关系，其中各方希望在一起，但同意一种非一夫一妻制的关系形式。这意味着他们同意允许，或经常容忍其他人以调情、性行为、身体接触或亲密方式与他们的伴侣交往。通常，开放关系是指相关各方同时拥有两个或更多的性关系，这些关系可以是短期关系，如约会，也可以是长期关系，如婚姻。');
INSERT INTO "tags" VALUES ('g2822','恋童癖主角','cont',154,'本游戏的主角是[url=https://en.wikipedia.org/wiki/Pedophilia]恋童癖者[/url]。如果主角与其性兴趣对象之间没有相当大的年龄差距，不要使用此标签。

使用儿童标签来定义对特定性别有吸引力的主角，除非他/她对此并不挑剔。');
INSERT INTO "tags" VALUES ('g2823','萝莉控主角','cont',115,'本游戏的主角患有[url=https://en.wikipedia.org/wiki/Lolicon]萝莉控综合症[/url]，即一个对年轻或青春期前女孩有吸引力的[url=https://en.wikipedia.org/wiki/Pedophilia]恋童癖者[/url]。虽然在现实生活中这些定义之间存在一些差异 - 但在视觉小说（或日本文化）中则没有。

如果主角与其性兴趣对象之间没有相当大的年龄差距，不要使用此标签。

不要因为主角在某个偶尔出现的萝莉女主角路线中的行为而使用此标签。仅当这种特质持续存在，或这种倾向的实现对游戏主线剧情起重要作用时，才使用它。');
INSERT INTO "tags" VALUES ('g2824','正太控主角','cont',37,'本游戏的主角患有[url=https://en.wikipedia.org/wiki/Shotacon]正太情结[/url]，即一个对年轻或青春期前男孩有吸引力的[url=https://en.wikipedia.org/wiki/Pedophilia]恋童癖者[/url]。虽然在现实生活中这些定义之间存在一些差异 - 但在视觉小说（或日本文化）中则没有。

如果主角与其性兴趣对象之间没有相当大的年龄差距，不要使用此标签。

不要因为主角在某个偶尔出现的正太男主角路线中的行为而使用此标签。仅当这种特质持续存在，或这种倾向的实现对游戏主线剧情起重要作用时，才使用它。');
