INSERT INTO "tags" VALUES ('g2831','阴茎笼','ero',82,'本视觉小说中有角色穿着一种称为[url=https://s.vndb.org/sf/51/113551.jpg]阴茎笼[/url]的男性贞操带的场景。

阴茎笼是一种男士锁紧衣物，旨在防止性交和手淫。阴茎笼常用于与[url=https://vndb.org/g1117]BDSM[/url]和[url=https://vndb.org/g718]女性支配[/url]相关的视觉小说中。

[url=https://s.vndb.org/sf/52/113552.jpg]NSFW 阴茎笼 1[/url]
