[url=https://s.vndb.org/sf/53/113553.jpg]NSFW 阴茎笼 3[/url]');
INSERT INTO "tags" VALUES ('g2833','支配女王女主角','cont',79,'本游戏包含一位或多位[url=https://en.wikipedia.org/wiki/Dominatrix]支配女王[/url]女主角。

支配女王是一种以象征性表现方式运作的女性原型，与特定的服装和道具相关联，这些在流行文化中被用来表明她的角色—一个强大、强势、性感的女性—与性恋物形象相关但又有所区别。

此标签适用于包含付费专业人员（职业女王）和习惯在BDSM活动中采取支配者角色的角色的视觉小说。不适用于包含角色仅在单一性爱场景中扮演支配女王，或是作为支配方但只是随意而为并未呈现出相应人设的视觉小说。');
INSERT INTO "tags" VALUES ('g2835','主角之间的恋爱关系','tech',154,'一个或多个可能的主角从其他主角的视角扮演英雄（女英雄）的角色。

示例： [url=/v10588]Roommates[/url], [url=/v21114]Pairs[/url], [url=/v13298]Shutter Chance[/url], [url=/v18550]The Letter[/url], [url=/v12827]Terminal Happiness[/url].');
INSERT INTO "tags" VALUES ('g2836','悬念式结尾','技术',169,'这款游戏要么以悬念式结尾结束，要么有包含悬念式结尾的路线。  悬念式结尾是游戏结束时戏剧性高潮或揭示的结果。  这通常是为了为系列中的下一款游戏或在另一种娱乐媒体上继续故事做铺垫。');
INSERT INTO "tags" VALUES ('g2837','自杀契约','内容',49,'这个故事包含一个[url=https://en.wikipedia.org/wiki/Suicide_pact]自杀契约[/url]。

自杀契约是两个或更多个人之间商定自杀的计划。计划可以是共同死亡，也可以是分别且时间相近地死亡。');
INSERT INTO "tags" VALUES ('g2838','主角的父亲作为英雄','内容',35,'这款游戏中的一位英雄是主角的[url=https://en.wikipedia.org/wiki/Father]父亲[/url]。');
INSERT INTO "tags" VALUES ('g2839','主角的无血缘关系的父亲作为英雄','内容',13,'这部视觉小说中至少有一位英雄是主角的父亲，但他们之间没有血缘关系。

这位英雄可能是主角的继父、养父或寄养父亲。');
INSERT INTO "tags" VALUES ('g2840','主角的血缘父亲作为英雄','内容',22,'这款游戏中的一位英雄是主角的[url=https://en.wikipedia.org/wiki/Father]亲生父亲[/url]。');
INSERT INTO "tags" VALUES ('g2846','Yaoi游戏制作活动','技术',187,'这部视觉小说是为[url=https://itch.io/jam/yaoijam18]YaoiJam[/url]制作的，这是一个专注于Yaoi和男性之间关系的游戏制作活动。');
INSERT INTO "tags" VALUES ('g2847','一千零一夜','内容',3,'《一千零一夜》是在伊斯兰黄金时代用阿拉伯语编纂的中东民间故事集。这不同于中东标签，因为一千零一夜宇宙中的故事大多以奇幻和历史为导向。

以一千零一夜宇宙为背景的游戏示例： https://vndb.org/v23465');
INSERT INTO "tags" VALUES ('g2849','阶梯结构','技术',112,'这部视觉小说有一种像"阶梯"一样运作的分支系统。
基本上，路线不是从共同路线/序章结束时分支出来，而是在其中就分开了。

它被称为"阶梯结构"的原因在于，你可以把沿途选择英雄（女英雄）路线看作是"走下阶梯"，而继续留在共同路线上则是走向顶端（这些"台阶"上的最终路线）。
 
[url=/v211]G-Senjou no Maou[/url]和[url=/v5154]Grisaia no Kajitsu[/url]是这种结构的典型例子。
其他VNs中这种结构的例子： [url=/v2002]STEINS;GATE[/url], [url=/v3770]Aiyoku no Eustia[/url], [url=/v10016]Tokeijikake no Ley Line -Tasogaredoki no Kyoukaisen-[/url], [url=/v18852]Amatsutsumi[/url], [url=/v15708]Sen no Hatou, Tsukisome no Kouki[/url]和[url=/v1399]sweet pool[/url]。');
