INSERT INTO "tags" VALUES ('g2864','跨性别配角','内容',93,'本视觉小说中有一个或多个支持角色是[url=https://en.wikipedia.org/wiki/Transgender]跨性别者[/url]。角色的“性别认同”（自我认同为女性、男性、两者皆非或两者皆是）与其“指定性别”（他人基于生理/遗传性别将其识别为男性、女性或间性人）不符。

“跨性别者”并不暗示任何特定的性取向；跨性别者可能认同为异性恋、同性恋、双性恋、泛性恋、多性恋或无性恋；有些人可能认为传统的性取向标签不适用于他们或不够充分。

他们可能已经进行了永久或部分的跨性别转变（这可能发生在故事之前或期间），从而成为变性者。

请不要将其与拥有两套生殖器的扶她（futanari）混淆，而跨性别角色只有一套生殖器。
请不要将其与异装男性/女性支持角色（[url=/g393]伪娘支持角色[/url]、[url=/g1785]伪郎支持角色[/url]）混淆。');
INSERT INTO "tags" VALUES ('g2867','随机事件','tech',82,'本视觉小说中的事件，例如某个角色随机生病的日子，可能在游戏过程中的任何时候发生，使得每次游玩都不相同。');
INSERT INTO "tags" VALUES ('g2871','女主角姐妹','cont',1155,'本游戏中至少有两个女主角是姐妹关系。');
INSERT INTO "tags" VALUES ('g2872','骷髅英雄','cont',11,'本游戏中的一位英雄是骷髅。

骷髅是一种实体显现的不死生物，常见于奇幻、恐怖小说和神话艺术中。大多数是人类的骷髅，但也可能来自地球或奇幻世界中的任何生物或种族。');
