INSERT INTO "tags" VALUES ('g2876','第一次世界大战','cont',14,'本游戏以[url=https://en.wikipedia.org/wiki/World_War_I]第一次世界大战[/url]为背景，或者有大量场景通过冗长的闪回或类似的叙事手法来展现这场冲突。');
INSERT INTO "tags" VALUES ('g2877','60年代','cont',25,'这个故事发生在地球上1960年至1969年之间。

关于60年代的更多细节可以在[url=https://en.wikipedia.org/wiki/1960s] 维基百科[/url]上找到。');
INSERT INTO "tags" VALUES ('g2878','昆虫','cont',131,'本游戏中有一种或多种[url=https://en.wikipedia.org/wiki/Insect]昆虫[/url]在故事中扮演重要角色。或者游戏中的许多场景都遍布昆虫，并有大量与它们相关的对话。');
INSERT INTO "tags" VALUES ('g2879','被诬告','cont',116,'本游戏以一名主角或一群人被诬告犯罪的故事为特色。他们必须在故事的一部分时间里证明自己的清白。');
INSERT INTO "tags" VALUES ('g2885','程序员英雄','cont',34,'这部视觉小说中的一位或多位英雄是程序员。

计算机编程是设计、编写、测试、调试/排查问题以及维护计算机程序源代码的过程。

源代码是用编程语言编写的。编程的目的是创建一个表现出特定期望行为的程序。编写源代码的过程通常需要许多不同领域的专业知识，包括应用领域知识、专门算法和形式逻辑。');
INSERT INTO "tags" VALUES ('g2886','双马尾英雄','cont',15,'这款游戏中有一位英雄，他把头发扎成两条马尾辫。

有关详细信息，请查看维基百科上关于[url=http://en.wikipedia.org/wiki/Bunches]发束[/url]和[url=http://en.wikipedia.org/wiki/Pigtail]马尾辫[/url]的相关文章。');
INSERT INTO "tags" VALUES ('g2888','选择性着色','tech',224,'这部视觉小说使用了选择性着色的技术。这意味着虽然游戏是黑白的，但可能会有某些物体或人物是彩色的，以突出其重要性。这种技术常用于电影中。

使用选择性着色的游戏示例：https://vndb.org/v24178');
INSERT INTO "tags" VALUES ('g2890','怪兽','cont',20,'这部视觉小说属于[url=https://en.wikipedia.org/wiki/Kaiju]怪兽[/url]类型。这种类型包含通常攻击主要城市、其他巨兽或军队的巨型怪物。');
INSERT INTO "tags" VALUES ('g2891','主角的男朋友作为英雄','cont',124,'在游戏开始时，一位或多位英雄已经作为主角的男朋友与其处于恋爱关系中。

[url=https://en.wikipedia.org/wiki/Boyfriend]男朋友[/url]是指在非婚姻恋爱关系中的男性伴侣。

此标签应与[url=/g880]主角恋爱中[/url]同时使用。如果一位英雄在故事过程中成为主角的男朋友，则不应使用此标签。');
INSERT INTO "tags" VALUES ('g2892','老虎与兔子','cont',17,'这些游戏中的角色来自[url=https://en.wikipedia.org/wiki/Tiger_%26_Bunny] 老虎与兔子[/url]系列。');
