如果英雄/女主角的父亲同时也是主角的父亲，请不要使用此标签，因为已有适当的标签。');
INSERT INTO "tags" VALUES ('g2897','体育老师英雄','cont',40,'这部视觉小说中的一位英雄是[url=http://en.wikipedia.org/wiki/Physical_education]体育老师[/url]。

体育教育是在中小学阶段开设的课程，鼓励在游戏或运动探索环境中进行心理运动学习。');
INSERT INTO "tags" VALUES ('g2898','图书馆员英雄','cont',10,'这部视觉小说中至少有一位英雄是[url=https://en.wikipedia.org/wiki/Librarian]图书馆员[/url]。');
INSERT INTO "tags" VALUES ('g2900','钢管舞','cont',33,'本游戏描绘了[url=https://en.wikipedia.org/wiki/Pole_dance]钢管舞[/url]。

钢管舞是一种以垂直钢管为中心，结合舞蹈和杂技的表演艺术。舞者利用上肢力量和柔韧性绕着钢管运动，并运用肌肉耐力悬挂在钢管上，使身体悬在空中。

钢管舞通常与绅士俱乐部和脱衣舞俱乐部等色情舞蹈联系在一起。然而，钢管舞作为一种锻炼和娱乐活动也存在，既可作为有氧运动，也可作为无氧运动。');
INSERT INTO "tags" VALUES ('g2901','记者英雄','cont',27,'这部视觉小说中的一位英雄是[url=https://en.m.wikipedia.org/wiki/Journalist]记者[/url]。');
INSERT INTO "tags" VALUES ('g2902','排泄物过滤','tech',26,'本游戏可以选择不显示/隐藏部分排泄物CG和场景。它们可以将内容替换为等效的非排泄物内容，或直接不显示排泄物内容。游戏玩法和故事不受影响。');
INSERT INTO "tags" VALUES ('g2903','马桶上的性行为','ero',736,'这部视觉小说中的一些性爱场景发生马桶上或厕所隔间/房间里。');
INSERT INTO "tags" VALUES ('g2904','按地点分类的性内容','ero',0,'任何指明行为地点的性内容都属于此元标签之下。');
INSERT INTO "tags" VALUES ('g2905','鞭打','cont',242,'[url=http://en.wikipedia.org/wiki/Flagellation]鞭笞[/url]（拉丁语flagellum，“鞭子”），鞭打、抽打或笞打，是用鞭子、笞条、棍棒、枝条、九尾鞭、犀牛皮鞭等特殊工具，有条理地击打人体的行为。 

通常，鞭笞是作为一种惩罚施加于不愿受罚者；然而，在宗教或施虐受虐的情境中，也可能自愿接受或自我施予。');
INSERT INTO "tags" VALUES ('g2906','石化','cont',43,'这部视觉小说中的角色暂时或永久地变成了雕像/岩石状形态。');
