INSERT INTO "tags" VALUES ('g2910','无生命物体英雄','cont',12,'这部视觉小说中至少有一位英雄是无生命物品的化身，甚至就是该物品本身。 

该物品可以是食物、工具、家具，甚至是一栋房子。');
INSERT INTO "tags" VALUES ('g2911','教练英雄','cont',8,'本游戏中有一位或多位英雄是教练。

教练的角色是在辅导过程中支持客户（被辅导者）、学生或学徒，以便他/她能够实现从项目一开始就确定的目标。

教练的一个例子是游泳教练或棒球教练（尽管他们不限于这些职业）。');
INSERT INTO "tags" VALUES ('g2912','教练女主角','cont',18,'本游戏中有一位或多位女主角是教练。

教练的角色是在辅导过程中支持客户（被辅导者）、学生或学徒，以便他/她能够实现从项目一开始就确定的目标。

教练的一个例子是游泳教练或棒球教练（尽管他们不限于这些职业）。');
INSERT INTO "tags" VALUES ('g2914','傲慢的英雄','cont',55,'这类英雄认为自己在各方面都优于他人，并且非常乐于抓住一切机会指出这一点。

大多数时候，这个角色最终表现出无能却极度傲慢，伴随着做作的笑声和滑稽动作，但在极少数情况下，他可能有充分的理由傲慢。 

通常这些角色身边会跟着几个跟班。');
INSERT INTO "tags" VALUES ('g2915','被他人强奸','ero',680,'本游戏至少有一个场景中，角色被主角以外的人强奸。');
