INSERT INTO "tags" VALUES ('g2924','教练主角','cont',33,'本游戏中的一名或多名主要角色是教练。

教练的职责是在指导过程中支持客户（被指导者）、学生或学徒，使其能够实现项目开始时确定的目标。

教练的一个例子是游泳教练或棒球教练（但不仅限于这些职业）。');
INSERT INTO "tags" VALUES ('g2925','体育老师主角','cont',22,'本视觉小说的主角是体育老师（http://en.wikipedia.org/wiki/Physical_education）。

体育教育是小学和中学教育期间开设的一门课程，旨在通过游戏或运动探索环境促进心理运动学习。');
