INSERT INTO "tags" VALUES ('g2929','30年代','cont',24,'本故事发生在公元1930年至1939年之间的地球上。

关于30年代的更多详情可参见相关的[url=https://en.wikipedia.org/wiki/1930s]维基百科[/url]词条。');
INSERT INTO "tags" VALUES ('g2930','幼儿园','cont',11,'游戏设定在幼儿园或托儿所或类似的场所，3至6岁（左右）的儿童在进入小学之前在此接受教育。');
INSERT INTO "tags" VALUES ('g2931','可解锁的格斗角色','tech',6,'这款格斗类视觉小说有可解锁的格斗角色，他们可能与故事模式相关，也可能仅与街机模式（或游戏特有的其他模式）相关。');
INSERT INTO "tags" VALUES ('g2932','主角的祖父作为英雄','cont',2,'游戏中的英雄之一是主角的祖父（不考虑血缘关系）。');
INSERT INTO "tags" VALUES ('g2933','赤裸土下座','ero',101,'[url=https://en.wikipedia.org/wiki/Dogeza]土下座[/url]是日本礼仪中的一种元素，包括直接跪在地上，俯身鞠躬，同时将头触地。本视觉小说中有角色赤裸着做出这一动作的场景，通常作为一种性羞辱的形式。

[url=https://s.vndb.org/sf/46/117746.jpg]NSFW示例[/url]');
INSERT INTO "tags" VALUES ('g2936','配角被他人强奸','ero',37,'本游戏至少包含一个配角被主角以外的人强奸的场景。');
INSERT INTO "tags" VALUES ('g2938','仅完全自愿的BDSM','ero',61,'本视觉小说包含某种形式的BDSM场景，从轻微束缚到完全的性奴役都有。共同点是所有行为都是完全自愿的。没有精神控制、没有超级药物、没有魔法、没有勒索、没有强奸至屈服等等，只是两个（或更多）性癖特殊的人在享受一些特殊的乐趣。');
INSERT INTO "tags" VALUES ('g2942','性行为中的食毛','ero',55,'游戏至少包含一个涉及吞食毛发、阴毛或散落阴毛的性场景（[url=https://en.wikipedia.org/wiki/Trichophagia]食毛癖[/url]）。

吞食散落阴毛：[url=https://s.vndb.org/sf/53/118453.jpg]NSFW示例1[/url]
[url=https://s.vndb.org/sf/54/118454.jpg]NSFW示例2[/url]
[url=https://s.vndb.org/sf/55/118455.jpg]NSFW示例3[/url]
[url=https://s.vndb.org/sf/56/118456.jpg]NSFW示例4[/url]
吞食阴毛：[url=https://s.vndb.org/sf/57/118457.jpg]NSFW示例[/url]');
INSERT INTO "tags" VALUES ('g2943','活人偶英雄','cont',22,'这部视觉小说中的一位或多位角色是活人偶。就像[url=https://vndb.org/v12396]《无名》[/url]中那样。');
INSERT INTO "tags" VALUES ('g2945','性爱秋千','色情',10,'本游戏包含涉及角色被捆绑、束缚或坐在[url=https://en.wikipedia.org/wiki/Sex_swing]性爱秋千[/url]上的性场景。

性爱秋千（也称为吊带）是一种束缚装置，旨在让一方被秋千悬挂，另一方自由移动，从而进行性交。虽然设计种类繁多，但最常见的性爱秋千有背部支撑、臀部支撑和每条腿的马镫，可以在使用者被悬挂时进行调整。

[url=https://s.vndb.org/sf/17/118517.jpg]NSFW 示例[/url]');
INSERT INTO "tags" VALUES ('g2947','人体家具','色情',37,'本游戏包含[url=https://en.wikipedia.org/wiki/Human_furniture]人体家具癖[/url]的元素，这是一种BDSM形式，支配方将服从方用作家具，例如椅子或桌子。

[url=https://s.vndb.org/sf/42/119042.jpg]NSFW 示例1[/url]
[url=https://s2.vndb.org/sf/13/125313.jpg]NSFW 示例2[/url]');
INSERT INTO "tags" VALUES ('g2949','护士主角','内容',34,'游戏中的一位主角是[url=https://en.m.wikipedia.org/wiki/Nursing]护士[/url]。

护理是医疗保健领域的一种职业，专注于照顾个人、家庭和社区，使他们能够获得、维持或恢复最佳健康和生活质量。');
INSERT INTO "tags" VALUES ('g2950','足部插入','色情',15,'本游戏包含一个或多个涉及足部插入孔窍的性场景。

注意: 请勿使用[url=https://vndb.org/g750]足交[/url]来标记足部插入场景，因为它们是两种不同的性行为。足交是非插入式的，而足部插入是插入式的。

[url=https://s.vndb.org/sf/76/118676.jpg]NSFW 示例[/url]');
INSERT INTO "tags" VALUES ('g2951','裙带菜酒','色情',39,'这部视觉小说包含涉及一种称为“裙带菜酒”的日本性行为的性场景。

[url=https://www.sankakucomplex.com/2009/08/04/nyotaimori-hentai-food-play-gallery/]裙带菜酒[/url]是一种食物性行为，指的是将清酒倒在裸体女性的双腿之间，同时她将双腿紧紧合拢，形成一个容器。然后另一个人从中饮用。 

裙带菜酒是一种日本性游戏，主要在1956年以前，由艺妓/游女在游廓中表演。之所以称之为“海藻”，是因为清酒中的阴毛看起来像海中的裙带菜。 
 
虽然不常见，但也可以用其他种类的酒来进行，酒可以倒在裸体的其他部位，例如胸部。

大腿裙带菜酒: [url=https://s.vndb.org/sf/76/118776.jpg]NSFW 示例1[/url], [url=https://s.vndb.org/sf/77/118777.jpg]NSFW 示例2[/url]
胸部裙带菜酒: [url=https://s.vndb.org/sf/78/118778.jpg]NSFW 示例[/url]');
INSERT INTO "tags" VALUES ('g2952','日式旅馆','内容',55,'[url=https://en.wikipedia.org/wiki/Ryokan_(inn)]日式旅馆[/url]是遍布日本的日式旅店，尤其是在温泉度假区。日式旅馆不仅仅是一个睡觉的地方，更是一个体验传统日本生活方式和待客之道的机会，包含了榻榻米地板、蒲团床、日式浴室和当地美食等元素。');
INSERT INTO "tags" VALUES ('g2953','往自己脸上撒尿','色情',51,'这部视觉小说包含至少一个角色往自己脸上撒尿的性场景；这通常通过[url=https://en.wikipedia.org/wiki/Halasana]犁式姿势[/url]实现。

这种性行为通常是对角色往自己脸上撒尿的服从和羞辱的极端化。
如果往自己脸上撒尿的角色也喝尿，请与[url=https://vndb.org/g2158]喝尿[/url]结合使用。

[url=https://s.vndb.org/sf/98/118898.jpg]NSFW 示例1[/url]
[url=https://s.vndb.org/sf/99/118899.jpg]NSFW 示例2[/url]');
INSERT INTO "tags" VALUES ('g2954','受孕选择','内容',77,'这部视觉小说让你可以选择是否让角色受孕。这可以是具有实际后果的[url=https://vndb.org/g1356]射精选择[/url]的形式，或者对于养成模拟器混合类型，可以是从菜单中选择的选项。');
INSERT INTO "tags" VALUES ('g2955','僧侣英雄','cont',16,'本游戏中的一位英雄是僧侣（https://en.wikipedia.org/wiki/Monk）。
僧侣是一种通过修道生活实践宗教禁欲主义的人，可以独自一人，也可以与任何数量的其他僧侣共处。僧侣可以是决定将自己的生命奉献给服务所有其他众生的人，也可以是自愿选择离开主流社会、在祈祷和冥想中度过一生的苦行者。这一概念源远流长，可见于许多宗教和哲学中。

注意：此标签适用于任何类型的僧侣，无论其所属宗教是真实的还是为故事虚构的。');
INSERT INTO "tags" VALUES ('g2956','僧侣女主角','cont',3,'本游戏中的一位女主角是僧侣（link）。
僧侣是一种通过修道生活实践宗教禁欲主义的人，可以独自一人，也可以与任何数量的其他僧侣共处。僧侣可以是决定将自己的生命奉献给服务所有其他众生的人，也可以是自愿选择离开主流社会、在祈祷和冥想中度过一生的苦行者。这一概念源远流长，可见于许多宗教和哲学中。

注意：此标签适用于任何类型的僧侣，无论其所属宗教是真实的还是为故事虚构的。');
INSERT INTO "tags" VALUES ('g2957','沙滩性爱','ero',428,'本视觉小说至少包含一个发生在沙滩上的性爱场景。如果角色在水中进行性行为，请将此标签与g1595一起使用。');
INSERT INTO "tags" VALUES ('g2959','蛋交','ero',6,'蛋交是指男性或扶她用其睾丸夹住男性的阴茎进行摩擦刺激。或者，该男性也可以采取更主动的角色，将其阴茎在对方的睾丸之间抽送。

[url=https://s.vndb.org/sf/58/119158.jpg]NSFW 伪娘示例[/url]
[url=https://s.vndb.org/sf/57/119157.jpg]NSFW 扶她示例[/url]');
INSERT INTO "tags" VALUES ('g2961','无法避免的他者强奸','ero',98,'在至少一条路线中，存在由主角以外的人实施的强奸场景，且这一场景无法避免。');
INSERT INTO "tags" VALUES ('g2962','无法避免的女主角被他人强奸','ero',81,'在至少一条路线中，存在由主角以外的人对女主角实施的强奸场景，且这一场景无法避免。');
INSERT INTO "tags" VALUES ('g2965','腿交','ero',210,'本视觉小说至少包含一个涉及腿交的性爱场景。

腿交是一种非插入式性行为，将阴茎在人的双腿之间或对着一条腿进行抽送。

注意：如果使用大腿来抽送阴茎，请使用[url=https://vndb.org/g1080]股间性交[/url]；如果使用脚部来抽送阴茎，请使用[url=https://vndb.org/g750]足交[/url]；如果使用膝窝来抽送阴茎，请使用[url=https://vndb.org/g2279]膝窝性交[/url]

[url=https://s.vndb.org/sf/37/119237.jpg]NSFW 双腿腿交示例[/url]
[url=https://s.vndb.org/sf/38/119238.jpg]NSFW 单腿腿交示例[/url]
[url=https://s.vndb.org/sf/36/119236.jpg]NSFW 腿交示例[/url]');
INSERT INTO "tags" VALUES ('g2967','厨师辅助角色','cont',17,'本游戏中的一位辅助角色是[url=https://en.wikipedia.org/wiki/Cook_%28profession%29]厨师[/url]。');
INSERT INTO "tags" VALUES ('g2968','发型选项','tech',353,'玩家可以在某个时点选择改变角色的发型，并提供一种或多种替代发型。除非是可选的，否则仅剪发不算。');
INSERT INTO "tags" VALUES ('g2972','着衣男与裸露男','ero',18,'包含男同性恋性爱场景，其中一些男性穿着衣服，而另一些则裸体（或至少穿着少得多的衣服）。可适用于BSDM场景以及普通性爱。');
INSERT INTO "tags" VALUES ('g2974','双耳音频','tech',53,'本视觉小说的配音使用多个麦克风或仿真人头麦克风来营造[url=https://en.wikipedia.org/wiki/Binaural_recording]双耳效果[/url]，为听者创造一种仿佛与角色同处一室的3D立体声感。这种技术更常用于广播剧CD，但有时也用于视觉小说，例如[url=/v9846]《魔鬼恋人》系列[/url]。');
INSERT INTO "tags" VALUES ('g2978','搁浅','cont',110,'本故事中的角色处于[url=https://www.thefreedictionary.com/stranded]滞留[/url]或[url=https://www.thefreedictionary.com/marooned]放逐[/url]状态，即他们被留在某个地方，没有离开的交通工具，获救或逃脱的希望渺茫。

例如，他们可能遭遇海难被困在荒岛上，被遗忘在无人居住的星球上，在暴风雪中困于山中，或被故意遗弃在沙漠里。

此标签与[url=/g293]禁闭[/url]的主要区别在于，滞留主要关乎生存，且往往是等待救援，而禁闭则关乎逃脱或首先达成目标。');
INSERT INTO "tags" VALUES ('g2979','无胸罩女主角','内容',114,'本游戏中有大量场景展示女主角在衣服内不穿胸罩。胸罩（[url=https://en.wikipedia.org/wiki/Bra]bra[/url]）是brassiere的缩写，是一种贴身内衣，用于支撑或遮盖穿戴者的乳房。

不穿胸罩可以通过透视上衣、乳头凸起撑起布料等方式观察到。请勿将此特征用于性爱场景中角色穿着刺激性特殊服装或可以裸体的场景。此特征仅适用于女主角穿着的日常/典型服装，不包括设计上不适合穿胸罩的服装类型——泳衣、紧身连衣裤、比基尼盔甲等。');
INSERT INTO "tags" VALUES ('g2982','主角的姐姐作为女主角','内容',439,'本游戏中有一位或多位女主角是主角的姐姐。她们与主角是否有血缘关系并不重要。');
INSERT INTO "tags" VALUES ('g2986','微交易','技术',1020,'本视觉小说使用了[url=https://en.wikipedia.org/wiki/Microtransaction]微交易[/url]机制。微交易是一种游戏机制，玩家可以用真实货币购买游戏内的内容。微交易在“免费游玩”游戏中极为常见，由此产生了“免费增值（freemium）”这一术语来描述这类游戏。它们最常见于移动平台游戏，但并非仅限于此。

采用微交易的游戏通常不直接为内容付费，而是要求玩家购买一定数量的“高级”货币，然后用这些货币兑换他们想要的内容。

在视觉小说中，微交易可以通过以下任意一种或全部方式实现（此列表并非详尽无遗）：

1. 玩家每天只能阅读一定量的视觉小说（VN），但可以付费阅读更多。这在视觉小说中通常以“门票”系统表示，在其他类型游戏中则表现为“体力”或“能量”条。

2. 当玩家到达选择点时，“最佳”选择需要付费才能选中。这可能只是解锁一张CG，也可能是达到好结局所必需的。

3. 玩家可以使用金钱/高级货币从奖池中抽取随机内容（支线故事、游戏道具、游戏货币等）。对于包含此机制的游戏，请使用g2711。

请勿将此标签用于那些提供免费序章然后允许你购买各条路线的游戏（这些在功能上与试玩版加付费游戏相同），或用于那些有付费支线故事或类似奖励内容的游戏（这些只是普通的DLC），除非它们还包含另一种类型的微交易机制。');
INSERT INTO "tags" VALUES ('g2987','房东主角','内容',8,'本游戏中的一位或多位男主角是[url=https://en.wikipedia.org/wiki/Landlord]房东[/url]。

房东是房屋、公寓、共管公寓、土地或房地产的所有者，将其出租或租赁给个人或企业，后者被称为租户（也称承租人或有租借者）。当法人处于这种地位时，也使用房东一词。');
INSERT INTO "tags" VALUES ('g2988','非二元性别主角选项','技术',479,'读者可以选择成为[url=http://gender.wikia.com/wiki/Non-binary]非二元性别[/url]，通过选择性别中立代词或选择非二元性别主角选项。');
INSERT INTO "tags" VALUES ('g2995','有面部毛发的主角','内容',172,'本游戏的主角有面部毛发。面部毛发的特征是男性脸上长出的毛发，包括下巴、脸颊和颈部的生长。');
INSERT INTO "tags" VALUES ('g2997','平成时代','内容',47,'带有此标签的视觉小说以日本平成时代为背景。 

平成时代是日本历史上对应平成天皇明仁在位的时期，从1989年1月7日至2019年4月30日。');
INSERT INTO "tags" VALUES ('g2999','体味恋物癖','色情',118,'[url=https://en.wikipedia.org/wiki/Olfactophilia]嗅觉癖[/url]是一种对来自身体的气味产生性唤起或将其作为恋物的性欲倒错。最常见的引起性欲的气味来自腋窝、肛门和脚。

这部视觉小说包含因体味而产生性唤起的场景，和/或有角色承认自己有这种恋物癖。');
INSERT INTO "tags" VALUES ('g3001','古罗马','cont',19,'这部视觉小说以[url=https://en.wikipedia.org/wiki/Ancient_Rome]古罗马[/url]为背景。

古罗马是指从公元前8世纪意大利城市罗马建立，到公元5世纪西罗马帝国灭亡期间的罗马文明，包括罗马王国（公元前753年–前509年）、罗马共和国（公元前509年–前27年）和罗马帝国（公元前27年–公元476年），直至西罗马帝国灭亡。');
