INSERT INTO "tags" VALUES ('g3005','主要反派角色','cont',479,'反派角色是故事中与主角对立、对剧情起决定性作用的角色，即可以被视为主角的敌人。

这部视觉小说包含一个或多个在故事中起重要作用的反派角色，主角试图战胜他们是剧情的关键部分。 

