INSERT INTO "tags" VALUES ('g3072','多人（4+）手交','ero',10,'这部视觉小说至少有一个场景，其中四人或更多同时为同一根阴茎进行手交。 

[url=https://s2.vndb.org/sf/71/125771.jpg]NSFW示例[/url]');
INSERT INTO "tags" VALUES ('g3075','卡拉OK包厢性爱','ero',48,'本游戏至少包含一个在[url=https://en.wikipedia.org/wiki/Karaoke_box]卡拉OK包厢[/url]或房间内性爱的场景。

卡拉OK包厢由多个配备卡拉OK设备的房间组成，通常按时间段出租。典型的卡拉OK包厢场所有10–20个（或更多）这样的房间，并在前方设有主要的卡拉OK酒吧区。卡拉OK包厢场所通常出售茶点。
卡拉OK包厢通常由卡拉OK设备、沙发、桌子和用于延长租用时间的电话组成。
卡拉OK包厢在日本非常受欢迎。

[url=https://s2.vndb.org/sf/27/125827.jpg]NSFW示例1[/url]
[url=https://s2.vndb.org/sf/26/125826.jpg]NSFW示例2[/url]
[url=https://s2.vndb.org/sf/25/125825.jpg]NSFW示例3[/url]');
INSERT INTO "tags" VALUES ('g3076','出生率下降','cont',64,'在这部视觉小说中，存在出生率下降的情况。
故事可能围绕解决这一下降问题展开，或者这一情节将成为某个路线中的重要剧情点。');
INSERT INTO "tags" VALUES ('g3078','前男子学校','cont',17,'这部视觉小说设定在一所曾经只招收男生、但最近才改为男女同校的学校。这通常意味着在校男生多得多，而女生只有很少几个。');
INSERT INTO "tags" VALUES ('g3081','雪球（精液传递）','ero',83,'本游戏至少包含一个涉及被称为“雪球”的性行为场景。

[url=https://en.wikipedia.org/wiki/Snowballing_(sexual_practice)]雪球（Snowballing）[/url]是一种人类性行为，其中一个人将别人的精液含入口中，然后通常通过接吻将其传入另一个人的嘴里。

之后，精液可能会与唾液混合后送回伴侣口中；这对伴侣或其他伴侣可能会多次交换这种液体，使其体积增加（因此称为“雪球”）。

[url=https://s2.vndb.org/sf/09/126509.jpg]NSFW示例1[/url]
[url=https://s2.vndb.org/sf/08/126508.jpg]NSFW示例2[/url]
[url=https://s2.vndb.org/sf/07/126507.jpg]NSFW示例3[/url]');
INSERT INTO "tags" VALUES ('g3084','男同性恋主角','cont',340,'主角是男同性恋。');
INSERT INTO "tags" VALUES ('g3085','女同性恋主角','cont',444,'主角是女同性恋。');
INSERT INTO "tags" VALUES ('g3088','放屁恋物癖','ero',63,'此作品包含性化的放屁行为。例如，角色可能在肛交前戏或性爱中不小心放屁，或为了性兴奋而在某人面前故意放屁。理想情况下，放屁应该被明确表现出来，而不是仅仅通过某种迂回的表达来暗示。');
INSERT INTO "tags" VALUES ('g3089','带纹身的主角','cont',119,'本游戏的主角带有[url=http://en.wikipedia.org/wiki/Tattoo]纹身[/url].

纹身是一种身体改造形式，通过将不可褪色的墨水注入皮肤真皮层以改变色素。');
INSERT INTO "tags" VALUES ('g3090','有序选项','技术',25,'本游戏中的选项是有序的。

例如，所有正确选项可能是列表中的第一个选择，或者每个第一个选择都是针对第一位女主角，每个第二个选择针对第二位女主角，第三个选择针对第三位女主角，以此类推。');
INSERT INTO "tags" VALUES ('g3092','19世纪','内容',150,'本故事发生在公元1801年至1900年间的地球上。

有关[url=https://en.wikipedia.org/wiki/19th_century]19世纪[/url]的更多详情可在维基百科上找到。');
INSERT INTO "tags" VALUES ('g3093','法国','内容',78,'本视觉小说以[url=https://en.wikipedia.org/wiki/France]法国[/url]为背景。');
INSERT INTO "tags" VALUES ('g3094','未署名配音','技术',96,'本视觉小说的配音演员未被指名或以其他方式得到官方确认。');
INSERT INTO "tags" VALUES ('g3095','黑子的篮球','内容',23,'这些游戏包含来自[url=https://en.wikipedia.org/wiki/Kuroko%27s_Basketball]黑子的篮球[/url]系列的角色。');
INSERT INTO "tags" VALUES ('g3097','哈利·波特','内容',20,'这些视觉小说以[url=https://en.wikipedia.org/wiki/Harry_Potter]哈利·波特[/url]宇宙为背景和/或包含其中角色。');
INSERT INTO "tags" VALUES ('g3098','钢之炼金术师','内容',17,'这些视觉小说包含来自[url=https://en.wikipedia.org/wiki/Fullmetal_Alchemist]钢之炼金术师[/url]系列的角色。');
INSERT INTO "tags" VALUES ('g3099','从章节索引重新开始','技术',151,'本视觉小说允许你从所选的任何索引章节重新开始游戏，而不是从头或序章之后重新开始。

此章节索引通常位于主菜单中\"开始\"按钮之外的单独位置。
示例1：[url=https://vndb.org/r25641]Sweet Fuse[/url] 在主菜单的\"日记\"下有这个章节索引。 
示例2：[url=https://vndb.org/r21021]Hakuoki[/url] 在主菜单的\"服务记录\"下有这个章节索引。

注意1：此标签不用于整个路线选择，而是用于章节选择，即从构成完整路线的众多章节中的任何一个重新开始游戏的能力。

注意2：这种章节索引不同于[url=https://vndb.org/g1555]普通场景回放[/url]，因为你是从指定章节重新开始游戏，而不仅仅是重读一个场景。选择起始章节后，未来的游戏机制仍然启用，使得未读的分支/结局仍然可以到达。');
INSERT INTO "tags" VALUES ('g3100','口爆（一嘴多阴茎）','色情',41,'本视觉小说包含至少一个涉及称为\"[url=https://vndb.org/g2112]口爆[/url]\"（即群体口交）的性行为场景，其中表演者同时将两个或更多阴茎放入口中。 

[url=https://s2.vndb.org/sf/18/126618.jpg]NSFW示例1[/url]
[url=https://s2.vndb.org/sf/19/126619.jpg]NSFW示例2[/url]
[url=https://s2.vndb.org/sf/20/126620.jpg]NSFW示例3[/url]');
INSERT INTO "tags" VALUES ('g3101','艾灸（酷刑）','内容',4,'本游戏包含[url=https://en.wikipedia.org/wiki/Moxibustion]艾灸[/url]酷刑的场景。

艾灸是一种传统中医疗法，包括在身体的特定点上燃烧干艾草。在我们的语境中，艾灸被用来通过让艾草灼烧皮肤来折磨角色。

[url=https://s2.vndb.org/sf/11/128911.jpg]NSFW示例[/url]');
INSERT INTO "tags" VALUES ('g3104','仅非处女女主角','内容',638,'游戏中的女主角都不是处女；所有女主角在故事开始前都确认有过性经验。');
INSERT INTO "tags" VALUES ('g3105','性堕落','色情',906,'这部视觉小说的主题之一是角色的性堕落。这意味着一些角色起初在性方面是\"纯洁\"和\"天真\"的，逐渐变成变态的慕男狂、心甘情愿的性奴、享受工作的妓女、渴望性的魅魔等等。

注意：正如其名，此标签仅用于角色的性堕落。如果视觉小说包含更普遍、非色情化的角色道德堕落，请改用[url=https://vndb.org/g3106]非色情道德堕落[/url]。');
INSERT INTO "tags" VALUES ('g3106','非色情道德堕落','内容',65,'这部视觉小说中的一个主题是某些角色道德上的堕落。 

这些角色通常一开始是道德良好、纯洁、天真等的，随着视觉小说的发展，他们失去了天真，变得麻木，变成反英雄或彻头彻尾的邪恶反派。 

注意：此标签专用于非色情的道德腐化（顾名思义）。情色腐化请使用[url=https://vndb.org/g3105]性腐化[/url]。');
INSERT INTO "tags" VALUES ('g3107','包皮玩法','色情',39,'本视觉小说包含至少一个涉及[url=https://en.wikipedia.org/wiki/Foreskin]包皮[/url]玩法的性爱场景。 

包皮是覆盖阴茎末端的一圈皮肤，因此包皮玩法是指用舌头或手指玩弄上述皮肤的行为。
在包皮玩法过程中，可能会提到[url=https://en.wikipedia.org/wiki/Phimosis]包茎[/url]的存在或可能性（即包皮无法轻易从阴茎龟头上翻下）。通常，在口交之前或期间会特别关注完全翻下包皮，从而增强男性伴侣的性快感。

包皮玩法不应与以下混淆： 
 - [url=https://vndb.org/g1423]尿道性交[/url]：指阴茎或触手插入尿道口 
 - [url=https://vndb.org/g1424]尿道探入[/url]：指物体插入尿道口
 - [url=https://vndb.org/g1609]阴茎摩擦[/url]：指两根阴茎相互摩擦

[url=https://s2.vndb.org/sf/18/129118.jpg]NSFW示例1[/url]
[url=https://s2.vndb.org/sf/17/129117.jpg]NSFW示例2[/url]
[url=https://s2.vndb.org/sf/19/129119.jpg]NSFW示例3[/url]
[url=https://s2.vndb.org/sf/20/129120.jpg]NSFW示例4[/url]');
INSERT INTO "tags" VALUES ('g3108','跳转至先前选择','tech',193,'此视觉小说有一个专用按钮，可直接跳回先前的选项选择。');
INSERT INTO "tags" VALUES ('g3109','跳转至下一选择','tech',213,'此视觉小说有一个专用按钮，可直接跳转到后续的选项选择。');
INSERT INTO "tags" VALUES ('g3110','主角侧像切换','tech',82,'此视觉小说提供开关选项，可启用或关闭位于文本框侧面的主角肖像。');
INSERT INTO "tags" VALUES ('g3111','兽人主角','cont',15,'这部视觉小说的主角是[url=http://en.wikipedia.org/wiki/Orc]兽人[/url]。');
INSERT INTO "tags" VALUES ('g3114','哺乳式手淫','色情',308,'这部视觉小说包含至少一个以哺乳式手淫为特色的场景。

哺乳式手淫是成人哺乳与手淫的结合。被挑逗阴茎的一方仰卧，吸吮实施方的乳房，而实施方则坐在或站在旁边，用手挑逗其阴茎。

哺乳式手淫的对象通常躺在伴侣的腿上，但这不是适用此标签的严格必要条件。

[url=https://s.vndb.org/sf/49/95949.jpg]NSFW示例1[/url]
[url=https://s2.vndb.org/sf/60/129660.jpg] NSFW示例2[/url]
[url=https://s.vndb.org/sf/50/95950.jpg]NSFW示例3[/url]');
INSERT INTO "tags" VALUES ('g3115','校园剧','cont',16,'剧情涉及一场校园剧。');
INSERT INTO "tags" VALUES ('g3116','改编自漫画','tech',261,'这部视觉小说是改编自已有的漫画。

不要与[url=http://vndb.org/g1056]同人小说[/url]混淆，同人小说基本上是原作品中不存在的衍生故事。');
INSERT INTO "tags" VALUES ('g3117','孩子结局','tech',232,'这部视觉小说至少有一个结局是主角至少有一个孩子。与怀孕结局的不同之处在于，孩子角色必须实际出现，尽管也可能存在两者兼有的结局。');
INSERT INTO "tags" VALUES ('g3118','改编自轻小说','tech',98,'这款游戏基于[url=https://en.wikipedia.org/wiki/Light_novel]轻小说[/url]改编。

不要与[url=http://vndb.org/g1056]同人小说[/url]混淆，同人小说基本上是原作品中不存在的衍生故事。');
INSERT INTO "tags" VALUES ('g3119','改编自动画','tech',214,'这部视觉小说基于[url=https://en.wikipedia.org/wiki/Anime]动画[/url]改编，或是其改编作品。

不要与[url=http://vndb.org/g1056]同人小说[/url]混淆，同人小说基本上是原作品中不存在的衍生故事。');
INSERT INTO "tags" VALUES ('g3121','主角的同父异母或同母异父妹妹作为女主角','cont',102,'至少一位女主角是主角的同父异母或同母异父的姐妹。

同父异母或同母异父的姐妹是与另一位兄弟姐妹共享一位生物学亲代的女性兄弟姐妹。不要与继姐妹混淆。同父异母/同母异父的姐妹有血缘关系，而继姐妹没有。');
INSERT INTO "tags" VALUES ('g3122','被怪物繁殖','色情',80,'带有此标签的游戏涉及角色（通常是女性）被用于或捕获以进行繁殖，通常由怪物、触手和非类人生物进行。

与怪物分娩类别的主要区别在于，虽然怪物分娩可能是怪物性交或强奸的意外结果，但苗床的目标包括使角色怀孕以及养育怪物。此外，为了达到这一目的，角色通常被长时间关在特定区域。而且，为了繁殖目的，可能会涉及身体改造、转化、堕落、精神控制或精神崩溃， 

可能是自愿的，也可能不是。通常涉及触手性行为、吞噬（vore）和肉壁相关类别。

例如《Venus Blood》系列游戏将此作为生产军队或单位的游戏机制。');
INSERT INTO "tags" VALUES ('g3123','正太强奸','色情',34,'此游戏中至少有一个场景是角色被正太或多个正太强奸。
无论角色的背景或动机如何，强奸犯是正太（无论年龄还是外表），他强迫受害者进行非自愿性行为。');
INSERT INTO "tags" VALUES ('g3126','架空日式风格国家','内容',20,'这部视觉小说发生在一个与日本相似和/或基于日本的虚构国家。');
INSERT INTO "tags" VALUES ('g3127','当代奇幻','内容',256,'这款游戏具有[url=https://en.wikipedia.org/wiki/Contemporary_fantasy]当代奇幻[/url]的元素和主题。

当代奇幻是奇幻的一个子流派，设定在当代，更准确地说，是创作者所处的时代。');
INSERT INTO "tags" VALUES ('g3128','高奇幻','内容',189,'这款游戏具有[url=https://en.wikipedia.org./wiki/High_fantasy]高奇幻[/url]的元素和主题。

高奇幻设定在一个另类的、虚构的("次要")世界中，而非"真实"或"主要"世界。这个次要世界通常内部一致，但其规则与主要世界不同。');
INSERT INTO "tags" VALUES ('g3129','低奇幻','内容',145,'这款游戏具有[url=https://en.wikipedia.org/wiki/Low_fantasy]低奇幻[/url]的元素和主题。

低奇幻是奇幻小说的一个子流派，其中魔法事件侵入了原本正常的世界。因此它与高奇幻故事形成对比，后者发生在拥有自己的规则和物理法则的虚构世界中。

低奇幻相对较少强调与奇幻相关的典型元素，将叙事设置在现实环境中并加入奇幻元素。有时奇幻元素刚好足够模糊真实与纯心理或超自然之间的界限。“低”一词指的是作品中传统奇幻元素的突出程度，并非对作品质量的任何评价。');
INSERT INTO "tags" VALUES ('g3130','像素艺术','技术',1110,'这款游戏使用[url=https://en.m.wikipedia.org/wiki/Pixel_art]像素艺术[/url]。

此标签表示游戏的美术资源主要是在像素级别以数字方式创建的。');
INSERT INTO "tags" VALUES ('g3131','强制自动阅读段落','技术',202,'这款游戏包含一些段落，在此类段落中，用户无法控制文本移动到下一行的速度。游戏会进入自动模式状态，该状态不遵循配置中设置的自动模式速度选项。您无法在这些段落中暂停游戏来查看日志。
此标签还涵盖主要包含文本并自动出现和消失的切入画面。

示例游戏：HoshiOri, GinHaru, FLOWERS（全部四部游戏）, Mirai Radio to Jinkou-bato, Tsukihime');
INSERT INTO "tags" VALUES ('g3132','腿袜足交','色情',829,'这部视觉小说包含至少一个涉及腿袜[url=/http://en.wikipedia.org/wiki/Footjob]足交[/url]的性爱场景。 

腿袜足交就是在穿着连裤袜或任何长袜或短袜等腿袜时进行的足交。

[url=https://s2.vndb.org/sf/59/130859.jpg]NSFW连裤袜示例[/url]
[url=https://s2.vndb.org/sf/60/130860.jpg]NSFW短袜示例[/url]
[url=https://s2.vndb.org/sf/61/130861.jpg]NSFW长袜示例[/url]');
INSERT INTO "tags" VALUES ('g3133','人类分娩','内容',64,'这部视觉小说包含一个人类孩子正在出生的场景。仅在分娩实际发生时使用此标签，如果女主角在时间跳跃后有了孩子，则不适用此标签。

请注意，场景不一定非要以图像方式呈现分娩过程。例如，如果主角站在女主角正在分娩的房间外，只要小说中呈现了分娩过程而不是跳过，也算作此标签。');
