INSERT INTO "tags" VALUES ('g3209','书信体叙事','tech',127,'一个故事主要通过信件、消息或文件的形式来讲述，读者会发现或收到这些内容，而不是通过对话或叙述。');
INSERT INTO "tags" VALUES ('g3212','仅平涂','tech',931,'本视觉小说的CG或立绘（sprite）的基础着色仅使用平涂色调，与渐变相对。
平涂色调是一层均匀色调的水彩，而[url=https://uigradients.com/#Relaxingred]渐变[/url]是从一种色调或阴影（如颜色）到另一种色调或阴影的逐渐或几乎难以察觉的变化。
这适用于立绘和事件CG，不适用于背景（背景通常由另一位画师绘制，可能采用完全不同的艺术风格）。
这两种技法可以在同一张CG/立绘中结合使用，但此类作品不得使用此标签。

仅平涂色调的示例：
https://s.vndb.org/sf/77/33177.jpg
https://s.vndb.org/sf/04/19104.jpg （此图是动画，这解释了为何使用这种着色方式，以及为何动漫式着色是此标签的别名）

渐变的示例（几乎每部视觉小说都有）：
https://s.vndb.org/sf/13/7413.jpg
https://s.vndb.org/sf/14/59814.jpg

使用PC98素材的示例和反例（关于皮肤的）：
[url=https://s.vndb.org/sf/38/31138.jpg]Kuro no Danshou[/url]
[url=https://s.vndb.org/sf/99/82199.jpg]Toumei Ningen[/url]

在基础着色上添加的图形效果和滤镜可以应用于CG，并改变平涂色调，以至于为CG增加少许渐变，但只要基础着色由平涂色调构成，该视觉小说仍然可以被标记。
图形效果的示例有蒸汽（用于温泉事件）、模糊（用于聚焦）、日落效果等。滤镜的一个例子是 "dazzling" 滤镜。

两个示例取自同一部视觉小说，[url=/v18580]Aoiro Note[/url]：

[url=https://s.vndb.org/sf/79/33179.jpg]图形日落效果[/url]。
它从单一光源（玻璃后面的太阳）为基础着色增加了更多光线，目的是使CG变得炫目。

[url=https://s.vndb.org/sf/41/105541.jpg]“dazzling”滤镜示例[/url]。
它使整个色情场景看起来像来自幻境，即使它没有像前一个示例那样有额外的光源。

现在，可以从[url=https://s.vndb.org/sf/77/33177.jpg]立绘[/url]中看到无杂质的基础着色。');
