INSERT INTO "tags" VALUES ('g3216','带阴茎的女性主角','cont',11,'这部视觉小说的主角拥有整体女性化的身体，但没有阴道，而是有阴茎（睾丸可有可无）。此外，主角并非生为男性——他们通过其他方式获得了男性生殖器。

这类角色在各种奇幻和科幻作品中最为常见，也常见于那些不清楚扶她定义的人的作品中，因此他们创造出仅拥有男性生殖器的整体女性化角色。

请注意，此标签不涉及变性或性别认同。这只是一个身体标签。

如果视觉小说的主角同时拥有女性和男性两套生殖器，请勿使用此标签，请改用[url=/g1187]扶她主角[/url]。');
