INSERT INTO "tags" VALUES ('g3277','湿乱','ero',190,'[url=https://en.wikipedia.org/wiki/Wet_and_messy_fetishism]湿乱恋物癖[/url]是一种性恋物癖，当大量物质涂抹在裸露的皮肤、面部或衣物上时，人会产生性唤起。

WAM参与者最常关注的脏乱物质包括生奶油、生鸡蛋、牛奶、[url=/g3185]乳液[/url]、油漆、油、泥、布丁、巧克力酱、果汁、啤酒、剃须泡沫、洗发水、肥皂、蛋奶糊、烤豆、糖蜜、番茄酱、冰淇淋、花生酱、黏液和蛋糕面糊等。

[b]对粪便、尿液、呕吐物、精液和女性潮吹等体液的恋物癖不被视为WAM的一部分。[/b]

如果涉及的是食物产品，则可以与[url=/g1794]食物性爱[/url]一起使用。');
INSERT INTO "tags" VALUES ('g3280','洛夫克拉夫特式恐怖','cont',221,'洛夫克拉夫特式恐怖是恐怖小说的一种亚类型，它强调未知（或不可知）的宇宙恐怖，而不是血腥或其他震撼元素。宇宙恐怖常常呈现一个黑暗而虚无主义的宇宙，人类被当作各种不可思议恐怖的玩物，我们所有的理想都不过是残酷的幻觉

它得名于并受到美国作家H·P·洛夫克拉夫特（1890-1937）作品的启发，洛夫克拉夫特倾向于描绘恐怖与科幻的自然主义融合，其中关于现实本质的假设被“侵蚀”，但本标签并不需要与其实际作品相关。');
INSERT INTO "tags" VALUES ('g3281','可自定义角色关系','tech',124,'游戏允许玩家设置主角和/或其他角色之间的关系。这可以以选择预定义关系或直接输入的形式出现。在后一种情况下，有些游戏能够识别某些输入并相应处理。

大多数情况下，游戏引入这种机制是为了避免某些发行平台上的乱伦禁令。通常，开发者或游戏会提示哪些关系是“正确”的。');
INSERT INTO "tags" VALUES ('g3283','植物性交','ero',88,'带有此标签的视觉小说包含与非人形怪物、突变体或外星植物进行性交的镜头。

活动可能是插入性的（用根、卷须或植物的其他部分插入）或非插入性的。  交合在性质上可能是自愿的或非自愿的。

如果性活动的性质如此，可以与[url=/g178]触手强奸[/url]/[url=/g600]经同意的触手性行为[/url]或[url=/g1279]吞噬[/url]一起使用。

不要使用此标签来描述与[url=/g665]魔物娘[/url]的性行为（所涉植物不应具有人形特征），或使用植物性物体进行自慰/插入（例如用黄瓜自慰）。

[url=https://s2.vndb.org/sf/15/128215.jpg]示例[/url]');
INSERT INTO "tags" VALUES ('g3284','基于虚构人物的支持角色','cont',29,'带有此标签的游戏中，一名或多名支持角色基于来自其他书籍、动画、卡通、漫画、日本漫画、电影、戏剧、视觉小说等作品中的虚构角色。');
INSERT INTO "tags" VALUES ('g3285','令和时代','cont',21,'带有此标签的视觉小说以日本的[url=https://en.wikipedia.org/wiki/Reiwa]令和时代[/url]为背景。

[url=https://en.wikipedia.org/wiki/Reiwa]令和时代[/url]是日本历史上对应于德仁天皇统治的时期。它始于2019年5月1日，是日本官方历法当前的年号。');
INSERT INTO "tags" VALUES ('g3286','无家可归的女主角','cont',30,'本游戏中的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Homeless]无家可归[/url]的。

无家可归描述的是没有固定住所的人们的情况。无家可归者无法或不愿获得并维持常规、安全且充足的住房，或者缺乏“固定、常规且适当的夜间住所”。');
INSERT INTO "tags" VALUES ('g3288','演员/女演员主角','cont',58,'本游戏中的一位或多位主角是[url=http://en.wikipedia.org/wiki/Actor]演员/女演员[/url]。

演员/女演员是在戏剧作品中表演的人，并以此身份在电影、电视、戏剧或广播中工作。古希腊语中“演员”一词的字面意思是“解释者”，在这个意义上，演员就是诠释戏剧角色的人。');
INSERT INTO "tags" VALUES ('g3295','包裹','cont',13,'该视觉小说包含角色完全或部分被包裹在某种有机或无机起源的封闭物中的场景。这可能出于各种原因，例如孵化、停滞、克隆、治疗等。

这是一个非性相关标签——不要将其用于与BDSM活动相关的包裹场景。此类情况请使用g3328或其子标签。');
INSERT INTO "tags" VALUES ('g3298','农场','cont',41,'本视觉小说的重要部分以[url=https://en.wikipedia.org/wiki/Farm]农场[/url]为背景，例如耕地农场、蔬菜农场、水果农场、奶牛场、养猪场和家禽农场。

农场是一片主要致力于农业生产过程的土地，其主要目标是生产食物和其他农作物；它是粮食生产的基本设施。');
INSERT INTO "tags" VALUES ('g3299','酒保主角','cont',56,'主角是一名酒保。

酒保是在有执照的场所的吧台后面通常供应酒精饮料并管理物资和库存的人。');
INSERT INTO "tags" VALUES ('g3300','基于网络小说','tech',84,'本游戏基于[url=https://en.wikipedia.org/wiki/Web_fiction#Web_novel]网络小说[/url]。

不要与[url=http://vndb.org/g1056]同人小说[/url]混淆，同人小说基本上是原作中没有的支线故事。');
INSERT INTO "tags" VALUES ('g3301','水下','cont',88,'这部视觉小说有许多场景设定在水下。');
INSERT INTO "tags" VALUES ('g3303','斯拉夫神话','cont',19,'[url=https://en.wikipedia.org/wiki/Slavic_paganism]斯拉夫神话[/url]强烈影响了这部视觉小说的设定和事件。');
INSERT INTO "tags" VALUES ('g3305','姑姨/侄女乱伦','ero',16,'这些游戏包含一位姑母/姨母与其侄女或外甥女之间的性爱场景。她们可能有血缘关系，也可能没有。');
INSERT INTO "tags" VALUES ('g3306','黑帮主角','cont',44,'本游戏中的一位主角是[url=http://en.wikipedia.org/wiki/Gangster]黑帮[/url]。');
INSERT INTO "tags" VALUES ('g3311','虐待动物','cont',48,'本游戏包含一些[url=https://en.wikipedia.org/wiki/Cruelty_to_animals]虐待动物[/url]的场景。

虐待动物是指对动物（通常是驯养动物）施加超出正常管教必要限度的身体疼痛、痛苦或死亡的犯罪行为。它可能包括极其恶劣的忽视（例如不给食物和水），致使动物遭受痛苦、死亡或面临迫在眉睫的死亡危险。');
INSERT INTO "tags" VALUES ('g3312','基于真实人物的配角','cont',43,'带有此标签的游戏中，一位或多位配角基于现实世界中的真实人物。');
INSERT INTO "tags" VALUES ('g3315','共生体 / 寄生虫','cont',92,'带有此标签的游戏涉及与世界中的生物存在某种共生或寄生关系。这种关系通常带有性色彩，但也不一定涉及性行为。这种关系可以是双方自愿的或强迫的，双向的或单向的，正如“共生”或“寄生”这两个名称所暗示的那样。

它与附身标签类似，主要区别在于它涉及某种实体生理生物体，而非无形的灵魂，即使所涉及的寄生虫被认为是恶魔或奇幻生物也是如此。 

寄生虫或共生体可能导致相关角色的身心发生剧烈变化，无论是永久性的还是暂时性的。例如，可能包括长出触手，或身体被活体衣物形态覆盖。角色可能能够控制这些变化或新增部分，也可能无法控制。

这些影响可能导致角色变得性活跃、失去理智，或被生物所控制。寄生虫或共生体也有可能以某种代价赋予角色超自然或非凡的力量和能力。');
INSERT INTO "tags" VALUES ('g3316','成瘾主角','cont',35,'这部视觉小说有一个具有某种[url=https://en.wikipedia.org/wiki/Addiction]成瘾症[/url]的主角。');
INSERT INTO "tags" VALUES ('g3317','仅限有血缘关系的女主角','cont',458,'本故事中的所有女主角均与主角有血缘关系，无论其亲属身份或姓氏如何（例如，包括已出嫁并改换家族归属的姐妹，或者是主角父母/祖父母隐藏的私生子）。');
INSERT INTO "tags" VALUES ('g3318','疗养院','cont',29,'疗养院是治疗慢性疾病（如结核病或严重精神障碍）的历史性医院。患者会在医学监督下接受长期疗养。

如今，许多疗养院都是健康度假村和养生中心，提供水疗、体能训练和饮食疗法等治疗性服务。');
INSERT INTO "tags" VALUES ('g3319','姻亲乱伦','ero',142,'本游戏包含姻亲角色之间的性爱场景。 

姻亲是指因婚姻而成为亲属的人，例如丈夫的姐妹、妻子的父亲等。');
INSERT INTO "tags" VALUES ('g3320','VR头显支持','tech',14,'本游戏支持VR头显，可能还支持VR手柄控制器。例如Oculus Rift、HTC Vive、Playstation VR和Valve Index。');
INSERT INTO "tags" VALUES ('g3321','非双胞胎主角兄弟','cont',89,'本游戏中至少两位主角互为兄弟，但他们不是双胞胎。');
INSERT INTO "tags" VALUES ('g3322','蝴蝶','cont',44,'本游戏中蝴蝶作为主题或角色在故事中扮演重要角色，或者在许多场景中都有蝴蝶出现，并有与之相关的多行对话。

蝴蝶（象征意义）是精神成长和超越的化身。在日本文化中，白蝴蝶象征着人类灵魂的化身。在许多文化中，蝴蝶也象征着重生，因为蝴蝶在茧中度过一段时间后苏醒。');
INSERT INTO "tags" VALUES ('g3323','美少女战士 水手月亮','cont',31,'本视觉小说设定在与[url=https://en.wikipedia.org/wiki/Sailor_Moon]美少女战士[/url]相同的世界观中，或包含该系列中的角色。');
INSERT INTO "tags" VALUES ('g3324','身体恐怖','cont',254,'本游戏包含[url=https://en.wikipedia.org/wiki/Body_horror]身体恐怖[/url]场景。

身体恐怖或生物恐怖是恐怖片的一个子类型，故意展示对人体生动或心理上令人不安的侵犯。这些侵犯可能表现为异常性行为、突变、肢解、僵尸化、无端暴力、疾病或身体的不自然运动。身体恐怖最初用于描述北美恐怖电影中新兴的一个子类型，但起源于早期哥特文学，并已扩展到其他媒体。');
INSERT INTO "tags" VALUES ('g3325','多重真结局','tech',74,'本游戏中有多个结局要么被视为真结局，要么在视觉小说本身中被指定为真结局。');
INSERT INTO "tags" VALUES ('g3326','后退跳过功能','tech',25,'本视觉小说具有后退跳过功能。');
INSERT INTO "tags" VALUES ('g3328','感官剥夺','ero',1147,'感官剥夺是一种感觉玩法，常被纳入BDSM中。它涉及剥夺一个人（通常是顺从方）的某些感官，如视觉和听觉。这不仅让他们感到更加无助，也使他们的其他感官（如触觉）对刺激更加敏感。这通常会产生强烈的色情体验。');
INSERT INTO "tags" VALUES ('g3330','血缘表亲/堂亲乱伦','ero',116,'这些游戏包含两个（或更多）有血缘关系的表亲之间的性爱场景。');
INSERT INTO "tags" VALUES ('g3331','跳转到上一场景','tech',28,'本视觉小说有一个按钮，允许玩家跳转到上一场景。');
INSERT INTO "tags" VALUES ('g3332','跳转到下一场景','tech',38,'本视觉小说有一个按钮，允许玩家前进到下一场景。');
INSERT INTO "tags" VALUES ('g3333','火影忍者','cont',50,'这些游戏包含来自[url=https://en.wikipedia.org/wiki/Naruto]火影忍者[/url]系列的角色。');
INSERT INTO "tags" VALUES ('g3337','仓促的游戏结局','tech',86,'此标签应用于视觉小说，其结局为了完成游戏而仓促且低于标准（在一些众筹视觉小说中常见）。

请勿使用此标签描述故意留下悬念或坏结局的视觉小说。此标签适用于开发者显然对游戏感到厌倦，仅用几句话草草收尾“完成”游戏，并自愿放弃解释他在游戏中创造的部分或全部主要情节的标题。');
INSERT INTO "tags" VALUES ('g3342','死亡游戏','cont',241,'本视觉小说包含以死亡游戏为主要元素的内容。在死亡游戏中，一名或多名“玩家”违背自己的意愿被迫参加游戏，如果失败就会被处死。

如果“游戏”涉及杀死其他玩家，请改用[url=/g664]大逃杀[/url]。');
INSERT INTO "tags" VALUES ('g3345','强奸犯主角','ero',39,'本视觉小说中的主角表现出实施强奸的倾向。不要将此标签用于每个英雄有一两次实施强奸选项（可能导致坏结局）的游戏，而是用于使强奸成为惯常行为的游戏。

通常，这样的主角是顽固不化的罪犯，尽管在某些情况下，他可能会编造自己的理由，认为强奸某些角色是可以的。');
INSERT INTO "tags" VALUES ('g3346','强奸犯女主角','ero',16,'这部视觉小说中的女主角表现出实施强奸的倾向。不要把这个标签用于每个女主角只有一两次强奸选项、可能导致坏结局的游戏，而是用于那些将这种行为变成习惯的游戏。

通常，这样的女主角是一个不知悔改的罪犯，尽管在某些情况下，她可能会编造自己的理由，认为强奸某些角色是可以的。');
INSERT INTO "tags" VALUES ('g3349','决定性反派','内容',39,'这部视觉小说中有一个或多个角色，根据路线/结局，可能扮演反派角色。');
INSERT INTO "tags" VALUES ('g3350','高管英雄','内容',65,'这款游戏中的英雄是高管。

高管是组织管理层最高层的人员，负责管理公司或企业的日常事务。');
INSERT INTO "tags" VALUES ('g3351','来自异世界的英雄','内容',44,'这部视觉小说中至少有一位英雄来自与故事发生地不同的世界或维度。

这个标签的用途是用于那些并非出生于视觉小说设定中的英雄。

注意：有时此标签可能与[url=/g1270]外星英雄[/url]等标签重叠。仅当英雄被确认来自不同设定时，才与其他标签一起使用。例如，如果视觉小说发生在火星上，而英雄全都是外星人，则不应应用此标签，因为英雄符合其设定。');
INSERT INTO "tags" VALUES ('g3353','素材图形','技术',579,'这部视觉小说使用了免费或付费的素材图形资源，无论是背景还是立绘。');
INSERT INTO "tags" VALUES ('g3355','素材立绘','技术',263,'游戏使用了免费或付费的素材立绘。');
INSERT INTO "tags" VALUES ('g3356','日语配音（适用于非日语原创视觉小说）','技术',211,'即使这款游戏的[url=https://vndb.org/d2#2]原始语言[/url]不是日语，它也包含日语配音。是否具有非日语配音与此标签的使用无关。');
INSERT INTO "tags" VALUES ('g3370','仅假名脚本','技术',20,'这款游戏中的文本仅使用平假名或片假名书写，不使用汉字。');
INSERT INTO "tags" VALUES ('g3373','插入式性行为','性爱',12704,'这款游戏至少包含一次涉及阴道、肛门或口腔插入的性行为，使用身体部位、性玩具或物体。有时插入发生在通常不会被插入的身体部位，如乳头。

不涉及插入但具有性性质的活动，如[url=/g751]乳交[/url]，则属于[url=/g1094]非插入式性行为[/url]类别。');
INSERT INTO "tags" VALUES ('g3374','无支援角色','内容',280,'这款游戏没有任何支援角色，甚至连路人或无立绘角色都没有。游戏的故事只围绕主角和/或主要角色展开。');
INSERT INTO "tags" VALUES ('g3375','肛门物体插入','性爱',468,'这些游戏至少包含一个场景，其中将性玩具或物体（非身体部位）插入肛门。');
INSERT INTO "tags" VALUES ('g3376','阴道物体插入','性爱',529,'这些游戏至少包含一个场景，其中将性玩具或物体（非身体部位）插入阴道。');
INSERT INTO "tags" VALUES ('g3377','阴道多重物体插入','性爱',31,'这些游戏至少包含一个涉及阴道多重物体插入的场景。

阴道多重物体插入是指将多个物体或性玩具（例如多个振动器、笔、蔬菜等）插入人的阴道。

[url=https://s.vndb.org/sf/24/90724.jpg]NSFW示例[/url]');
INSERT INTO "tags" VALUES ('g3378','肛门多重物体插入','性爱',25,'这些游戏至少包含一个涉及肛门多重物体插入的场景。

肛门多重物体插入是指将多个物体或性玩具（例如多个振动器、笔、蔬菜等）插入人的肛门。

[url=https://s.vndb.org/sf/25/90725.jpg]NSFW示例[/url]');
INSERT INTO "tags" VALUES ('g3379','公开使用（合意）','性爱',29,'本VN至少包含一个性爱场景，其中角色经历一种被称为“公开使用”或“公共精液垃圾桶”的合意性奴役形式。

“公开使用”或“公共精液垃圾桶”是Hentai中使用的术语，用来识别一种特殊的性奴役，即角色被留在那里，供每个陌生人或路人进行性使用（并常常被虐待）。

“公开使用（合意）”标签的关键要素是：
- 角色自愿提供自己供他人使用
- 角色通常以被他人使用为傲，有时也会扮演非自愿的场景
- 角色通常自愿被束缚、受颈手枷束缚、被锁链锁住、或被关在笼子里或墙上，置于公共场所（厕所、市场、广场等），并且他随时可以自由离开

[url=https://s.vndb.org/sf/50/100350.jpg]NSFW示例：颈手枷[/url]
[url=https://s.vndb.org/sf/51/100351.jpg]NSFW示例：被困[/url]
[url=https://s.vndb.org/sf/52/100352.jpg]NSFW示例：厕所1[/url]
[url=https://s.vndb.org/sf/53/100353.jpg]NSFW示例：厕所2[/url]');
INSERT INTO "tags" VALUES ('g3383','乱伦角色扮演','ero',45,'本游戏包含一个或多个性爱场景，在自愿参与者之间演绎虚构的乱伦情节。');
INSERT INTO "tags" VALUES ('g3387','用户界面','tech',0,'此元标签用于收纳关于游戏[url=https://en.wikipedia.org/wiki/User_interface]用户界面[/url]的标签。例如快捷键或特定按钮。');
INSERT INTO "tags" VALUES ('g3390','仅扶她女主角','cont',59,'本游戏中的所有女主角都是扶她。');
INSERT INTO "tags" VALUES ('g3391','仅福瑞女主角','cont',96,'本游戏中的所有女主角都是福瑞。');
INSERT INTO "tags" VALUES ('g3392','仅与动物性交','ero',24,'本游戏中的所有性爱场景都涉及动物。');
INSERT INTO "tags" VALUES ('g3393','仅与怪物性交','ero',45,'本游戏中的所有性爱场景都涉及怪物。

不要将此标签用于涉及[url=/g3418]魔物娘[/url]的性爱。');
INSERT INTO "tags" VALUES ('g3395','母女恋情','cont',15,'本视觉小说包含母亲与女儿之间的恋情。');
INSERT INTO "tags" VALUES ('g3396','超级英雄','cont',28,'本游戏中的一位或多位英雄是[url=http://en.wikipedia.org/wiki/Superhero]超级英雄[/url]。');
INSERT INTO "tags" VALUES ('g3397','2010s','cont',126,'故事发生在地球上的2010年至2019年之间。');
INSERT INTO "tags" VALUES ('g3399','身体互换性爱','ero',24,'此标签适用于那些角色与另一角色互换身体后进行性交场景的游戏。互换后的身体可能与其原本性别相同，也可能不同。

如果身体互换也导致性别互换，请将此标签与[url=/g1247]性别转换性爱[/url]一起使用。');
INSERT INTO "tags" VALUES ('g3401','大规模谋杀','cont',192,'本视觉小说包含描绘大规模谋杀的场面。

