INSERT INTO "tags" VALUES ('g3413','女巫主角','cont',30,'本作中的主角是一位女巫，一种深入研究[url=https://en.wikipedia.org/wiki/Witchcraft]巫术[/url]的法师。

不要将此标签用于任何能够施放魔法的角色；仅当角色被明确描述为女巫或修炼巫术时才使用此标签。

