INSERT INTO "tags" VALUES ('g3415','小胸女主角（非萝莉）','cont',872,'本视觉小说中的一位或多位女主角胸部较小。
此标签与[url=/g154]萝莉女主角[/url]标签是分开的，请勿混淆两者。

