INSERT INTO "tags" VALUES ('g3420','技师女主角','cont',20,'本游戏中的一位或多位女主角是[url=http://en.wikipedia.org/wiki/Technician]技师[/url]。 

技师是擅长操作机械、装置和技术的人员。');
INSERT INTO "tags" VALUES ('g3423','体育作为游戏元素','tech',31,'[url=https://en.wikipedia.org/wiki/Sports_video_game]体育视频游戏[/url]是模拟体育运动的视频游戏。有些游戏强调实际参与运动，而另一些则强调策略和体育管理。

本视觉小说包含该类型的玩法序列。');
INSERT INTO "tags" VALUES ('g3427','无语音回放','tech',79,'本游戏没有重播配音的功能，而许多现代视觉小说通常都有。 

注意：不要标记在任何发布版本中都没有实施语音的视觉小说。');
INSERT INTO "tags" VALUES ('g3428','讽刺','cont',101,'讽刺可以简单地描述为以幽默、反讽或嘲笑的方式批评社会、社会中的人或观念。

讽刺的主要目的是揭露社会的愚蠢和弱点。讽刺作家使用委婉、反讽、夸张和轻描淡写的手法，以不同程度的轻松诙谐展示人类的愚蠢，以及这些愚蠢可能导致的悖论和愚行。');
INSERT INTO "tags" VALUES ('g3431','街机','cont',21,'本视觉小说中有许多场景设定在[url=https://en.wikipedia.org/wiki/Amusement_arcade]娱乐街机厅[/url]中，主角和/或主要角色经常在那里玩街机游戏。

娱乐街机厅（通常称为视频街机厅、游乐场或简称为街机厅）是人们玩街机游戏的场所，包括街机视频游戏、弹球机、机电游戏、兑奖游戏、自动售货机（如抓娃娃机），或投币式台球桌和空气曲棍球桌。');
INSERT INTO "tags" VALUES ('g3432','乙女游戏Game Jam','tech',333,'本视觉小说是为[url=https://itch.io/jam/otomejam]乙女游戏Game Jam[/url]制作的，该活动专注于创建[url=https://vndb.org/g542]乙女游戏[/url]。');
INSERT INTO "tags" VALUES ('g3433','扶她女主角','cont',28,'这部视觉小说的女主角拥有整体女性化的身体，但没有阴道，而是有阴茎（睾丸可有可无）。此外，女主角并非生为男性——她们以某种其他方式获得了男性生殖器。

这种角色在各种奇幻和科幻作品中最为常见，也常见于那些不清楚扶她定义的人的作品中，因此他们创作出只拥有男性生殖器的整体女性化角色。

请注意，此标签不涉及变性过程和性别认同。这只是一个身体标签。

对于女主角同时拥有女性与男性两套生殖器的视觉小说，请勿使用此标签，而应使用[url=/g413]扶她女主角[/url]。');
INSERT INTO "tags" VALUES ('g3435','宗教学校','cont',23,'这部视觉小说以一所[url=https://en.wikipedia.org/wiki/Religious_school/]宗教学校[/url]为背景。

宗教学校是指在其运营或课程中包含宗教成分的学校，或者主要为了教授特定宗教的某些方面而存在的学校。  
                                                                                                           
[来自[url=https://wikipedia.org/]维基百科[/url]]');
INSERT INTO "tags" VALUES ('g3436','公共使用','ero',176,'本视觉小说包含至少一个性爱场景，涉及一个角色遭受一种非正式称为“公共使用”或“公共精液垃圾桶”的性奴役形式。

“Public Use”或“Public Cum Dumpster”是成人漫画中使用的术语，用来指代一种特殊的性奴役，即一个角色被留下来供每个陌生人或路人进行性使用（且经常遭受性虐待）。');
INSERT INTO "tags" VALUES ('g3437','平胸女主角（非萝莉）','cont',450,'本视觉小说中的一位或多位女主角拥有平胸。 
此标签与[url=/g154]萝莉女主角[/url]标签不同，请勿混淆两者。

平胸正如其名，即完全没有乳房。换句话说，胸部小到连阴影都无法投下。

下限：无
