重要规则：角色的胸部应在正常立绘（可能是裸体）的站立姿势下进行评估，因为特写和奇怪的镜头角度会放大或缩小胸部大小的透视效果。
在模棱两可的情况下，始终优先给角色标注更大的尺寸。
如果是因为怪异的胸部/身体改造导致乳房增大，则使用：[url=/g1561]怪异身体改造[/url]');
