INSERT INTO "tags" VALUES ('g3450','有孙辈的女主角','cont',38,'本游戏中的一位女主角有孙辈，无论是亲生的还是收养的。

如果女主角在游戏接近尾声或某种尾声章节中才成为祖母，则不要使用此标签。此标签适用于在游戏开始时已有孙辈或在游戏早期获得孙辈的女主角。

此标签也不适用于收养孩子并让孩子称她们为“祖母”的女主角。必须涉及三代人。');
INSERT INTO "tags" VALUES ('g3451','跨性别角色','cont',600,'本视觉小说中的某个角色是[url=https://en.wikipedia.org/wiki/Transgender]跨性别者[/url]，这意味着他们的“性别认同”与其“出生指定性别”不符。其中一些人可能已经进行了永久性或部分性的性别转换，从而成为变性人。

如需更多信息，请查看相应的子标签。不要将其与拥有两套生殖器的扶她混淆，跨性别角色只有一套生殖器。');
INSERT INTO "tags" VALUES ('g3452','非时间顺序','cont',31,'多个场景、事件、剧情线等以非时间顺序发生。这意味着对于故事的[b][u]大部分[/u][/b]而言，事件被讲述的顺序与它们发生的顺序不匹配。

这方面的两个例子（来自动画）包括《物语系列》和《凉宫春日的忧郁》。其中许多事件的讲述与时间顺序无关。

[b]注1：[/b]不要包含一次性的前传事件或背景故事线。一个有用的经验法则是，如果大多数情况下你需要查阅时间线指南才能确定某事是否可被视为“非时间顺序”，那么它很可能符合。

[b]注2：[/b]不要包含仅具有分支情节的视觉小说，那些仍然是按照众多时间线中的一条来讲述的时间顺序故事。');
INSERT INTO "tags" VALUES ('g3453','渔夫英雄','cont',5,'游戏中的一位英雄是[url=https://en.wikipedia.org/wiki/Fisherman]渔夫[/url]。');
INSERT INTO "tags" VALUES ('g3455','无家可归的英雄','cont',10,'这款游戏中的一位或多位英雄是[url=https://en.wikipedia.org/wiki/Homelessness]无家可归的[/url]。

无家可归指的是没有固定住所的人的状况。无家可归者无法或不愿获得并维持常规、安全且足够的住房，或缺乏“固定、常规且足够的夜间居所”。');
INSERT INTO "tags" VALUES ('g3457','仅将主角的亲属作为女主角们','cont',731,'这款游戏中的全部女主角都是主角的亲属。');
INSERT INTO "tags" VALUES ('g3459','非原创图形','tech',1088,'该视觉小说使用的图形并非专门为本作制作。 

这些图形可能是从其他来源非法盗用的，或者是开发者非正典地重复使用其其他作品中的原创CG，例如[url=/p1224]Atelier Sakura[/url]制作了原创背景CG，但实际上在一部又一部的视觉小说中反复使用，即使这些作品原本应该设定在完全不同的地点。

当图形对于一个系列的世界观是正典时，不要使用此标签。例如，[url=/v20194]Grisaia: Phantom Trigger[/url]系列在[url=/v5154]Grisaia no Kajitsu[/url]中重复使用了美滨学院的CG。

所涉及的图像必须是显著的。短暂使用公共领域艺术或摄影，例如[url=/v5240]Ikinari Anata ni Koishiteiru[/url]中Matthew Perry的立绘，不在考虑范围内。');
INSERT INTO "tags" VALUES ('g3461','仅限兽人英雄','cont',265,'这款游戏中的所有英雄都是兽人。');
INSERT INTO "tags" VALUES ('g3463','怪物猎人','cont',208,'这部视觉小说有一个或多个场景，其中怪物猎人在故事中扮演重要角色，或者有多个此类角色。');
INSERT INTO "tags" VALUES ('g3464','种族多元的角色阵容','cont',179,'这部视觉小说拥有一个[url=https://en.wikipedia.org/wiki/Diversity_(politics)]种族多元的角色阵容[/url]。本视觉小说中的角色描绘了多种种族、国籍等。

此标签不应与角色阵容中物种多样性的故事混淆，后者在[url=/g2]奇幻[/url]和[url=/g105]科幻[/url]类型中很常见。此标签仅适用于人类角色。');
INSERT INTO "tags" VALUES ('g3465','武士女主角','cont',39,'本视觉小说的女主角是或曾经是一名武士。

对于角色以[url=http://en.wikipedia.org/wiki/Bushid%C5%8D]武士道[/url]方式行事但并未拥有正式头衔的游戏，请勿使用此标签。');
INSERT INTO "tags" VALUES ('g3467','黑执事','cont',3,'这些游戏中的角色来自[url=https://en.wikipedia.org/wiki/Black_Butler]黑执事[/url]漫画或动画系列。');
INSERT INTO "tags" VALUES ('g3470','军官英雄','cont',64,'这款游戏中至少有一位英雄是军队中的军官（处于权威地位的士兵）。

在军队中担任临时职务的人不属于此标签。此标签适用于职业军官。');
INSERT INTO "tags" VALUES ('g3471','SCP基金会','cont',13,'[url=https://en.wikipedia.org/wiki/SCP_Foundation]SCP基金会[/url]是一个虚构的秘密组织，由同名的协作写作wiki项目记录。在网站的共享宇宙中，SCP基金会负责捕获和收容各种超自然、超常及其他主流科学无法解释的神秘现象（称为“异常”或“SCP”），同时对其存在向全球人类社会其他部分保密。');
INSERT INTO "tags" VALUES ('g3472','雌小鬼女主角','cont',93,'这部VN有一个以高度早熟方式行事的萝莉。尽管她仍有孩子般的外表，但她对性相关的事情以及如何通过炫耀自己的身体来操纵他人有着充分的认知。这一特点主要通过以下方式展现：对成年男性举止粗鲁且厚脸皮，以性暗示的方式挑逗和激怒他们（轻轻触碰、故意穿着暴露的服装），并因他们的反应而贬低他们。 

由于这关乎态度，与[url=/g903]滥交女主角[/url]重合并非必要，因为先前的性行为不是必要条件，且她们的行为可以只针对一个人。');
INSERT INTO "tags" VALUES ('g3473','孤儿院','续',23,'孤儿院是一种寄宿机构，负责照看孤儿，直到他们被收养。');
INSERT INTO "tags" VALUES ('g3477','使用日语方言的女主角','续',217,'这部VN有一位说标准日语（ひょうじゅんご，标准语）之外日语方言的女主角。

日语分为几种方言，其中东京方言被视为标准日语。这些方言分为两大主要分支：东部方言（主要包括东京方言）和西部方言（包括关西弁等多种不同方言），而九州方言和八丈岛方言通常被区别为额外的分支。');
INSERT INTO "tags" VALUES ('g3478','偶像大师','续',36,'本视觉小说包含来自系列作品[url=https://en.wikipedia.org/wiki/The_Idolmaster]偶像大师[/url]的角色。');
INSERT INTO "tags" VALUES ('g3481','女同性恋支配','色情',86,'本视觉小说至少包含一个性场景，其中支配方和顺从方均为女性。');
INSERT INTO "tags" VALUES ('g3482','影响下的强奸','色情',889,'本VN包含某人成为强奸受害者的场景，该情况发生在此角色因精神状态受影响而无法提供有效同意之时。

例子包括被下春药、处于精神控制或魔法影响下，这甚至可能导致角色表现出与施暴者发生性关系的欲望，即使在正常情况下他们不会同意。');
INSERT INTO "tags" VALUES ('g3484','主角的哥哥作为可攻略角色','续',56,'本游戏中的一位或多位可攻略角色是主角的哥哥。无论他们与主角是否有血缘关系都可以。');
INSERT INTO "tags" VALUES ('g3485','主角的弟弟作为可攻略角色','续',71,'本游戏中的一位或多位可攻略角色是主角的弟弟。无论他们与主角是否有血缘关系都可以。');
INSERT INTO "tags" VALUES ('g3486','舔鞋','色情',15,'本视觉小说包含角色舔另一个人鞋子的场景。

舔鞋是一种非插入式性行为，指某人舔另一个人所穿的鞋。这是一种类似于舔脚的性行为，但对象是鞋子或靴子。');
INSERT INTO "tags" VALUES ('g3488','只有年长的可攻略角色','续',70,'本游戏中所有可攻略角色都比主角年长。');
