[url=https://s2.vndb.org/sf/29/158029.jpg]NSFW示例[/url]');
INSERT INTO "tags" VALUES ('g3495','金发傻妞化','色情',79,'这个视觉小说包含角色经历性化降智（Bimbofication）的情节。性化降智是[url=/g3105]性堕落[/url]的一种类型，其结果是角色变成[url=/i3547]Bimbo（胸大无脑的女人）[/url]。受影响的角色通常一开始被描述为天真/保守、聪明、勤奋或毫不起眼，但环境使他们变成一个性欲过剩的性感尤物，通常被称为[url=/i3547]Bimbo（胸大无脑的女人）[/url]。角色通常经历的变化如下：

1. 外貌：角色开始穿着暴露、引人注目的服装，化着俗艳的妆容，戴大量时尚配饰，把头发染成浅色（以金色为主，但也有其他变化）。经常有Bimbo通过整形手术来提升外貌。偶尔也会自豪地展示纹身和穿孔。

2. 观念：角色开始渴望享乐活动，并经常参加派对和其他社交聚会。他们通常变得在性方面[url=/g1667]淫乱[/url]，开始与多个伴侣发生性关系。他们甚至可能卷入性工作。

3. 智力：在奇幻/科幻设定中，角色通常会受到某种精神退化，使其智力下降。在现实世界设定中，角色会重新调整生活方式，通常退学、辞职，以追求更享乐和社交的生活方式。吸毒和滥用药物在这类作品中也很常见。

日本特有的一种变体是辣妹化（Gyarufication）（以及由此延伸的黑辣妹化（Gangurofication）），普通女高中生（或年轻女性）通常会结交不良群体，并在游戏过程中开始表现出与负面[url=/i1219]辣妹（Gyaru）[/url] / [url=/i1054]黑辣妹（Ganguro）[/url]刻板印象相关的外貌和态度。常见的Bimbo套路适用：改变外貌、道德沦丧、追求享乐活动和性，不在乎学业或工作。她们的生活方式往往很昂贵，并常导致援助交际和卖淫。

[i]如果受影响的角色在故事开头已经是Bimbo/辣妹/黑辣妹，或者已经道德沦丧、堕落，请不要使用此标签。[/i]

性化降智示例

[url=https://s2.vndb.org/sf/02/158002.jpg]1[/url], [url=https://s2.vndb.org/sf/04/158004.jpg]2[/url], [url=https://s2.vndb.org/sf/05/158005.jpg]3[/url]

辣妹化 / 黑辣妹化示例

[url=https://s2.vndb.org/sf/06/158006.jpg]1[/url], [url=https://s2.vndb.org/sf/07/158007.jpg]2[/url]');
