[url=https://s.vndb.org/sf/63/89163.jpg]NSFW肛门示例[/url]');
INSERT INTO "tags" VALUES ('g3498','堕入邪恶（色情）','工口',188,'这个视觉小说包含角色经历一种性堕落的情节，最终导致他们从善良阵营转投邪恶阵营。与其他形式的性堕落一样，角色在游戏开始时是纯洁/正义/善良的，受到魔法、精神控制、强奸与精神崩溃或其他类似手段的折磨，最终使角色爱上/渴望其堕落者并加入他们的阵营。

适用此标签的条件：
1) 游戏必须设定在明确区分善良与邪恶阵营的宇宙中。如果故事过于复杂且存在灰色地带，或者善/恶二元对立没有明确界定，则不应使用该标签。
2) 故事必须包含角色从非邪恶阵营转变为邪恶阵营，这种转变是通过邪恶一方实施的性堕落实现的。');
INSERT INTO "tags" VALUES ('g3499','肛门多重拳交','工口',3,'本游戏包含一个或多个以肛门多重拳交为特色的性爱场景。

