INSERT INTO "tags" VALUES ('g3500','与触手性交','工口',2050,'本游戏包含一个或多个以与有触手的人类或生物进行性活动为特色的性爱场景。

[url=https://en.wikipedia.org/wiki/Tentacle]触手[/url]是一种灵活、可移动、细长的器官，存在于某些动物物种中，其中大多数是无脊椎动物。');
INSERT INTO "tags" VALUES ('g3501','肛门多重触手插入','工口',20,'本游戏包含一个或多个涉及肛门多重触手插入的性爱场景。

肛门多重触手插入是指将多根触手插入一个人的肛门。

