INSERT INTO "tags" VALUES ('g3502','性别与性取向相关','内容',3283,'这是一个用于收集性别与性取向相关标签的元标签。');
INSERT INTO "tags" VALUES ('g3503','性取向重新定向/发现','内容',51,'这是一个元标签，用于包含所有涉及性取向改变的标签，无论是双方自愿的（发现）还是非自愿的（强制重新定向）。');
INSERT INTO "tags" VALUES ('g3504','性取向发现','内容',32,'本视觉小说包含一些情境，其中角色经历了自愿的接触，在小说的过程中使他们发现了新的性取向。

通常情况涉及一个同性恋角色接近一个异性恋者，并诱惑或操纵他们（不使用完全非法的手段）使其变成同性恋。

反向情景，一个同性恋角色被异性恋诱惑者诱惑并被"掰直"也是可能的，但在虚构作品中要罕见得多，因为现实世界的负面含义。

有时变化并不彻底，角色会变成双性恋，而不是完全改变他们的性取向。');
INSERT INTO "tags" VALUES ('g3505','性取向重新定向','内容',19,'本视觉小说包含这样的情境：在一个角色不同意的情况下，其受到某些技术和方法的影响，在游戏过程中改变其性取向。

通常的情况是同性恋角色接近异性恋受害者，并使用催眠、魔法、科幻术语或干脆通过强奸/精神摧毁让其变成同性恋。

相反情景也是可能的，即同性恋角色成为异性恋攻击者的受害者，并被“掰直”，但由于现实中负面含义，在虚构作品中要少见得多。

有时改变并不彻底，角色变成双性恋，而不是完全改变其性取向。');
