INSERT INTO "tags" VALUES ('g3517','乳房折磨','情色',38,'本视觉小说包含至少一个涉及[url=https://en.wikipedia.org/wiki/Breast_torture]乳房折磨[/url]的性爱场景.

乳房折磨是一种对女性乳房施加疼痛或勒紧的性行为。这可能涉及对女性乳房/乳头直接施以疼痛或不适的活动，例如乳房束缚、蜡玩、拍打、挤压、拳击、鞭打、电击等.

此类活动的接受者可能通过受虐获得直接的身体快感，或通过知道这种行为取悦了施虐的主导者而获得情感上的快感.

[url=https://s2.vndb.org/sf/08/159108.jpg]NSFW示例：通过束缚进行的乳房折磨[/url]
[url=https://s2.vndb.org/sf/11/159111.jpg]NSFW示例：通过乳房挤压进行的乳房折磨[/url]
[url=https://s2.vndb.org/sf/10/159110.jpg]NSFW示例：乳头折磨[/url]');
INSERT INTO "tags" VALUES ('g3518','性爱机器','ero',138,'这是一个元标签，用于收录所有与性爱机器相关的标签。');
INSERT INTO "tags" VALUES ('g3519','Sybian','ero',11,'这部视觉小说至少包含一个使用[url=https://en.wikipedia.org/wiki/Sybian]sybian[/url]的性爱场景。 

Sybian，或称Sybian鞍座，是一种主要设计用于女性的自慰设备。 

它由一个中空的鞍状座椅组成，内含两个电动机、电机速度控制板、齿轮、皮带轮和一个位于曲轴上的平台，使得设备顶部的脊状突起可以根据有线外部手持控制器设定的速度在一定范围内振动；同时，一个穿过脊状突起、向上倾斜的轴可以通过有线遥控器以从零转到每分钟数百转的速度旋转。还提供柔韧的模制附件，套在振动的脊和轴上，其顶部大多集成有假阳具。使用时，骑乘者将假阳具插入体腔进行内部刺激，同时将外部性感带压在振动的脊上

[url=https://s2.vndb.org/sf/76/159376.jpg]NSFW 示例 1[/url]
[url=https://s2.vndb.org/sf/75/159375.jpg]NSFW 示例 2[/url]');
INSERT INTO "tags" VALUES ('g3520','心理恐怖','cont',1179,'这部视觉小说的类型是心理恐怖。

心理恐怖是恐怖和心理小说的一个子类型，特别关注精神、情感和心理状态，以惊吓、干扰或使观众不安。该子类型经常与相关的心理惊悚子类型重叠，并常利用神秘元素以及具有不稳定、不可靠或异常心理状态的角色，来增强背景和情节中的悬念、戏剧性、动作和偏执感，并营造一种总体上令人不快、不安或痛苦的气氛。');
INSERT INTO "tags" VALUES ('g3522','乌托邦','cont',7,'这部视觉小说发生在乌托邦中。

乌托邦通常描述一个想象中的社区或社会，为其成员拥有高度理想或近乎完美的品质。该词由托马斯·莫尔爵士在他1516年的著作《乌托邦》中创造，描述了一个新大陆中的虚构岛屿社会。然而，它也可以指一个有意建立的社区。在通常的说法中，该词或其形容词形式可以与“不可能的”、“牵强的”或“受骗的”同义使用。

对应的标签是[url=/g772]反乌托邦[/url]，许多乌托邦设定最终往往被发现其实是反乌托邦。然而，只要我们最初被引导相信该设定是一个真正的乌托邦，就可以使用这个标签。');
INSERT INTO "tags" VALUES ('g3523','战争罪行','cont',23,'这部视觉小说包含对[url=https://en.wikipedia.org/wiki/War_crime]战争罪行[/url]的描绘。

战争罪行是“在战争进行期间违反公认国际战争规则的行为。”在大众文化中通常表现为士兵对平民和已投降的敌方士兵犯下罪行。在大多数法院中，法律上认为其与普通犯罪行为（谋杀、强奸等）不同。

可以适用于现实的战争规则。或游戏中的战争规则所规定的内容。

[url=/v22670]示例 1[/url]


[url=/v32751]示例 2[/url]');
INSERT INTO "tags" VALUES ('g3528','我的英雄学院','cont',23,'这些视觉小说以[url=https://en.wikipedia.org/wiki/My_Hero_Academia]我的英雄学院[/url]中的角色为特色，或设定在其宇宙中。');
INSERT INTO "tags" VALUES ('g3530','鼻钩','ero',156,'这部视觉小说包含使用[url=https://s2.vndb.org/sf/65/160865.jpg]鼻钩[/url]的内容。这通常发生在捆绑场景中。');
INSERT INTO "tags" VALUES ('g3531','太空海盗英雄','cont',1,'这个故事中至少有一位英雄是[url=https://en.wikipedia.org/wiki/Space_pirate]太空海盗[/url]。

太空海盗在外太空以海盗身份活动，乘坐航天器旅行，这不同于地球上传统的公海海盗，后者乘船旅行。然而，正如传统航海海盗以帆船为目标，太空海盗在科幻媒体中扮演类似角色：他们捕获和掠夺航天器以获取货物和战利品，偶尔还会偷走整个航天器本身，并杀害船员。');
INSERT INTO "tags" VALUES ('g3534','海洋哺乳动物','cont',17,'这款游戏中有一个或多个[url=https://en.wikipedia.org/wiki/Marine_mammal]海洋哺乳动物[/url]在故事中扮演重要角色。或者，在许多场景中都有海洋哺乳动物出现，并伴有与之相关的多句对话。');
INSERT INTO "tags" VALUES ('g3537','穿着衣服的乳交','ero',99,'这部视觉小说包含一个乳交场景，其中女主角穿着大部分衣服。特别是她的乳房，尤其是乳头，必须被遮盖。

