INSERT INTO "tags" VALUES ('g3544','治疗师英雄','cont',229,'本游戏中的一个或多个英雄是[url=https://en.wikipedia.org/wiki/Healer]治疗者[/url]——无论是使用魔法的牧师、擅长使用草药者还是真正的医生.

