INSERT INTO "tags" VALUES ('g3545','性产业','cont',1734,'该元标签收集与[url=https://en.wikipedia.org/wiki/Sex_industry]性产业[/url]相关的标签。');
INSERT INTO "tags" VALUES ('g3546','糖爹约会','cont',31,'该视觉小说描绘了糖恋行为，这是一种交易型约会行为，通常表现为一位较年长且更富有的人（糖爹/糖妈）为一位需要经济援助的较年轻者（糖宝）的关注、陪伴和性服务买单。报酬可以通过金钱、礼物、资助或其他物质利益的形式获得。

这种行为与卖淫的不同之处在于，糖宝不会不断寻找新客户，而是只有一位或少数几位固定的资助者，他们为其陪伴付费。此外，虽然性是被期待的，但在资助者与受益者之间的所有互动中，性并非必不可少。

带有援助交际情节的视觉小说应标记为[url=/g387]卖淫[/url]，除非如上所述正确描绘了糖恋（一种主要是排他性忠诚的关系）。');
INSERT INTO "tags" VALUES ('g3549','物体头','cont',55,'该视觉小说中有一个或多个角色的头部是无生命物体。如果是由于[url=https://vndb.org/g2015]无生命物体的拟人化[/url]所致，请将该标签与当前标签一同添加。

[url=https://knowyourmeme.com/memes/object-head]物体头[/url]是一种常用于超现实主义艺术中的视觉母题。它通常被用来象征人类与无生命符号之间的联系。');
INSERT INTO "tags" VALUES ('g3550','政治家主角','cont',11,'主角是一位[url=http://en.wikipedia.org/wiki/Politician]政治家[/url]。

政治家是参与影响公共政策和决策的人。这包括在政府中担任决策职位的人，以及通过选举、继承、政变、任命、选举舞弊、征服、神权或其他方式谋求这些职位的人。');
INSERT INTO "tags" VALUES ('g3552','由富转贫','cont',16,'这个故事包含了与“从贫穷到富有”相反的文学原型元素。

“由富转贫”指的是一个人从富有跌入贫穷，或有时从成名陷入默默无闻的任何情况。');
INSERT INTO "tags" VALUES ('g3553','可自定义角色年龄','tech',29,'游戏允许玩家设置或更改角色的年龄。

