INSERT INTO "tags" VALUES ('g3566','肛交后口交 (Ass To Mouth)','ero',35,'这部VN描绘了包含[url=https://en.wikipedia.org/wiki/Ass_to_mouth]肛门至口部[/url]的场景。

肛门至口部是一个术语，主要用于描述一种性行为，即将勃起的阴茎从接受方的肛门中抽出，然后直接放入其口中，或可能放入另一个人的口中。');
INSERT INTO "tags" VALUES ('g3568','一切只是一场梦','cont',119,'这部视觉小说的大部分事件都是角色在故事世界内产生的幻觉或梦境。

在极端情况下，游戏在最后揭示，玩家到目前为止所追踪的所有角色的故事，都不过是另一个角色想象中的产物。');
INSERT INTO "tags" VALUES ('g3570','闪烁灯光','tech',94,'本游戏包含快速闪烁灯光的场景，如闪烁的背景、CG或其它特效。游戏中可能可以禁用它们，因为闪烁灯光可能引发光敏性癫痫。');
INSERT INTO "tags" VALUES ('g3571','相亲','cont',31,'这部视觉小说描绘了一个被称为"相亲"的事件。

相亲是指两个之前未曾谋面的人之间的社交约会，通常由共同的熟人或通过在线约会程序或互联网安排。');
INSERT INTO "tags" VALUES ('g3572','我的世界','cont',18,'这些视觉小说包含来自[url=https://en.wikipedia.org/wiki/Minecraft]Minecraft[/url]的角色，或设定在其宇宙中。');
INSERT INTO "tags" VALUES ('g3573','过去的欧洲','cont',249,'游戏设定在[url=https://en.wikipedia.org/wiki/History_of_Europe]过去的欧洲[/url]。');
INSERT INTO "tags" VALUES ('g3575','有胸毛的英雄','cont',47,'这部视觉小说中的某位英雄在胸部及/或腹部区域有明显毛发。');
INSERT INTO "tags" VALUES ('g3576','性爱许可','ero',8,'在这部视觉小说中，主角或其他角色拥有免费性爱的通行证/许可/凭证，无论接收者是否感兴趣。这在拔作中是一种快速开启性爱场景的简单方法。');
INSERT INTO "tags" VALUES ('g3579','虚拟YouTuber','cont',133,'这些游戏以[url=https://en.wikipedia.org/wiki/VTuber]虚拟YouTuber[/url]为特色。

虚拟YouTuber是一种在线艺人，使用计算机图形生成的虚拟化身。通常（但并非总是）使用实时动作捕捉软件或技术来捕捉动作。');
INSERT INTO "tags" VALUES ('g3580','拥有恶魔之血的英雄','cont',10,'这类英雄起初是普通人，但后来体内混入了恶魔之血，最终赋予他超人的素质和力量。');
INSERT INTO "tags" VALUES ('g3581','拥有恶魔之血的主角','cont',13,'这类主角起初是普通人，但后来体内混入了恶魔之血，最终赋予他们超人的素质和力量。');
INSERT INTO "tags" VALUES ('g3582','半恶魔英雄','cont',11,'游戏中的至少一位英雄是[url=http://en.wikipedia.org/wiki/Demon]恶魔[/url]与人类或类似生物的子女。');
INSERT INTO "tags" VALUES ('g3583','魅魔主角','cont',26,'这款游戏的主角是[url=https://en.wikipedia.org/wiki/Succubus]魅魔[/url]，一种女性形态的恶魔，根据神话和传说传统，她会压在睡眠者（尤其是男性）身上，与他们进行性行为。');
INSERT INTO "tags" VALUES ('g3584','天文学','cont',69,'这些游戏反复出现[url=https://en.wikipedia.org/wiki/Astronomy]天文学[/url]主题。');
INSERT INTO "tags" VALUES ('g3585','仅限更年轻的英雄','cont',30,'这款游戏中所有英雄都比主角年轻。');
INSERT INTO "tags" VALUES ('g3588','史莱姆女主角','cont',33,'这款游戏中的一位或多位女主角是[url=https://monstergirlencyclopedia.miraheze.org/wiki/Slime]史莱姆[/url]。');
INSERT INTO "tags" VALUES ('g3589','半天使英雄','cont',4,'游戏中的至少一位英雄是[url=https://en.wikipedia.org/wiki/Angel]天使[/url]与人类或类似生物的子女。');
INSERT INTO "tags" VALUES ('g3590','半天使女主角','cont',4,'游戏中的至少一位女主角是[url=https://en.wikipedia.org/wiki/Angel]天使[/url]与人类或类似生物的子女。');
INSERT INTO "tags" VALUES ('g3591','半天使主角','cont',16,'这款游戏的主角是[url=https://en.wikipedia.org/wiki/Angel]天使[/url]与人类或类似生物的子女。');
INSERT INTO "tags" VALUES ('g3592','合租屋','cont',40,'这部视觉小说的重要部分发生在合租屋内。

合租屋是一种住所，几个没有家庭关系或恋爱关系的人住在一起。通常厨房、客厅和浴室是共用的，卧室是私密的。');
INSERT INTO "tags" VALUES ('g3593','妓女养成模拟器','ero',26,'妓女养成是一种养成模拟，主角训练或培养一个或多个角色与他人发生性关系。

当妓女养成构成游戏玩法的主要部分时，请为相应作品使用此标签。对于仅作为次要元素且非主要焦点的游戏，请使用通用[url=/g40]养成模拟[/url]标签。

示例： 
[url=/v35476]Heleisi de Juedouchang Ⅱ[/url]
[url=/v30490]~Makai de Maid~ Akuma to Tenshi to Yuusha no Himitsu no Kissaten[/url]');
INSERT INTO "tags" VALUES ('g3595','静音粗话','tech',14,'游戏包含被审查的淫秽或粗俗词语，这些词语被静音而不是被[url=/g1676]哔声屏蔽[/url]。

如果游戏的有声台词中包含被审查的词语，尤其是与生殖器相关的词语，如おちん (ochinpo)、おまんこ (omanko) 和おちんちん (ochinchin)，则应使用此标签。');
INSERT INTO "tags" VALUES ('g3597','葬礼','cont',33,'这部视觉小说包含至少一个葬礼场景。可以是土葬、火葬或任何其他类型的仪式活动。');
INSERT INTO "tags" VALUES ('g3598','选择阵营','tech',27,'本视觉小说中的主角可以在两个或更多截然不同的派系/阵营之间进行选择，而故事会根据你选择的一方发生巨大变化。通常这意味着选择后主角将与之互动的场景和角色阵容完全不同。

当只有一个组织可加入，或选择仅仅是在对立角色之间时，请勿使用此标签。当选择意味着加入一群人，他们拥有自己的意识形态和利益，并且通常相互竞争/争斗时使用此标签。');
INSERT INTO "tags" VALUES ('g3600','自动战斗','tech',4,'本视觉小说包含自动战斗元素。

自动战斗（又称自走棋）是一种游戏类型，其核心策略特征为：让游戏在玩家交互极少或完全没有的情况下自行运行。与游戏的交互虽然通常有助于进程推进，但在长时间的游戏过程中是可选操作。');
INSERT INTO "tags" VALUES ('g3607','双马尾主角','cont',127,'本游戏中的主角将头发扎成双马尾。

详情请参阅维基百科上关于[url=http://en.wikipedia.org/wiki/Bunches]bunches[/url]和[url=http://en.wikipedia.org/wiki/Pigtail]pigtails[/url]的相关条目。');
INSERT INTO "tags" VALUES ('g3608','恶魔契约（非性）','cont',60,'本游戏包含恶魔契约。

恶魔契约是一种古老的信仰，认为凡人可以向恶魔献上重要的东西，以换取自己选择的愿望成真。通常是指人类将灵魂献给恶魔，从而获得永生、治愈疾病，甚至统治世界。

不要将此标签用于主角与发情的魅魔发生性关系因而莫名其妙地缔结契约的场景。此标签仅用于涉及出卖灵魂、以血签名等常见套路的严肃恶魔交易。');
INSERT INTO "tags" VALUES ('g3610','女主角在故事开始前已将初夜给予主角','cont',139,'本游戏中，女主角在游戏故事开始前已将贞操失去给主角。

如果该游戏是系列作品的一部分，并且失去贞操的情节发生在之前的一部作品中，此标签同样适用。');
INSERT INTO "tags" VALUES ('g3611','丧尸男主角','cont',14,'本视觉小说中至少有一位男主角是[url=http://en.wikipedia.org/wiki/Zombie_%28fictional%29]丧尸[/url]。');
INSERT INTO "tags" VALUES ('g3612','导尿管','ero',26,'本故事包含将导尿管用于性目的的描写。导尿管是一根细长的管子，插入尿道以将液体（主要是尿液）排出体外。

如果涉及排便或灌肠，请使用标签[url=https://vndb.org/g2532]body fluid tube[/url]。');
INSERT INTO "tags" VALUES ('g3613','中性主角','cont',64,'本游戏中的主角是中性化的。

中性化的人是指同时具有高度女性特征和男性特征的女性或男性。');
INSERT INTO "tags" VALUES ('g3614','中性化男主角','cont',79,'本游戏中至少有一位男主角是中性化的。

中性化的人是指同时具有高度女性特征和男性特征的女性或男性。');
INSERT INTO "tags" VALUES ('g3615','中性化女主角','cont',77,'本游戏中至少有一位女主角是中性化的。

中性化的人是指同时具有高度女性特征和男性特征的女性或男性。');
INSERT INTO "tags" VALUES ('g3616','纯文字性内容','ero',135,'这些视觉小说的所有色情内容均为纯文字形式，不显示任何露骨图像。');
INSERT INTO "tags" VALUES ('g3619','医学生主角','cont',15,'这位主角是一名[url=http://en.wikipedia.org/wiki/Medical_student]医学生[/url]，即被医学院录取并注册参加医学教育项目的人。');
INSERT INTO "tags" VALUES ('g3620','家庭教师主角','cont',97,'本游戏的主角是一名[url=http://en.wikipedia.org/wiki/Tutor#Private_tutors]私人教师[/url]。

私人教师向个别学生或小组学生教授特定学科或技能。这种关注理想情况下能让学生比在课堂环境中更快地提高知识或技能。');
INSERT INTO "tags" VALUES ('g3622','离家出走的主角','cont',19,'本故事的主角是一名[url=https://en.wikipedia.org/wiki/Runaway_%28dependent%29]离家出走者[/url]。

离家出走者是指未成年人或根据当地司法管辖区规定处于特定年龄以下的人，未经许可离开父母或法定监护人的住所，或被父母赶出家门，并被当地当局认为没有能力独立生活（后者有时被称为“弃儿”）。');
INSERT INTO "tags" VALUES ('g3623','离家出走的男主角','cont',15,'本故事中有一位或多位男主角是[url=https://en.wikipedia.org/wiki/Runaway_%28dependent%29]离家出走者[/url]。

离家出走者是指未成年人或根据当地司法管辖区规定处于特定年龄以下的人，未经许可离开父母或法定监护人的住所，或被父母赶出家门，并被当地当局认为没有能力独立生活（后者有时被称为“弃儿”）。');
INSERT INTO "tags" VALUES ('g3624','财物支配','色情',12,'一种支配与服从的实践，其中顺从方（现金小猪、财务服从者、人形ATM、金钱奴隶或支付猪）向财物支配者赠送礼物和金钱。');
INSERT INTO "tags" VALUES ('g3625','母权制','内容',30,'[url=https://en.wikipedia.org/wiki/Matriarchy]母权制[/url]在这部视觉小说中扮演重要角色。母权制是一种社会制度，在这种制度下，女性在权威角色中占据主要权力地位。

要应用此标签，游戏设定所在的世界、国家或社会应由母权制统治。不要仅仅因为游戏以女性主导为主题或拥有强势女主角就应用此标签。');
INSERT INTO "tags" VALUES ('g3627','触手与男性','色情',61,'这部视觉小说包含男性角色被[url=http://en.wikipedia.org/wiki/Tentacle]触手[/url]进行性使用的场景。

该行为是否双方自愿并不影响此标签的适用。');
INSERT INTO "tags" VALUES ('g3628','王子主角','内容',168,'这部视觉小说中至少有一位主角是西式[url=https://en.wikipedia.org/wiki/Prince]王子[/url]。通常指在位君主的儿子或近亲。

只要他符合王子的形象，并不需要来自西方（许多奇幻作品中的王子都是如此）。');
INSERT INTO "tags" VALUES ('g3629','装傻主角','内容',3,'本游戏中至少有一位主角扮演[url=https://en.wikipedia.org/wiki/Manzai#Boke_and_tsukkomi]装傻[/url]角色。

他们不必是真实喜剧二人组中的装傻角色，只需要在日常生活中表现得像装傻角色即可。例如，他们的天然呆可能成为整个故事中的幽默来源。

请注意，装傻角色仍然需要一个吐槽角色来互动。如果没有吐槽角色，你可能应该使用[url=https://vndb.org/g2528]天然呆主角[/url]替代。

与双人喜剧中“逗哏”和“捧哏”的概念类似，装傻和吐槽是漫才（日本喜剧风格）的一个非常重要的特征。装傻（boke）来自动词bokeru，带有“老糊涂”或“天然呆”的意思，体现在装傻角色容易误解和健忘的倾向上。吐槽（tsukkomi）一词指的是第二位喜剧演员“插嘴”并纠正装傻角色错误所扮演的角色。在表演中，吐槽角色通常会责骂装傻角色并快速拍打他们的头部；一种传统的漫才道具常被用于此目的——折纸扇。

更多信息请参见[url=http://en.wikipedia.org/wiki/Manzai]维基百科[/url]和[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/BokeAndTsukkomiRoutine]tvtropes[/url]。');
INSERT INTO "tags" VALUES ('g3630','吐槽主角','内容',4,'本游戏中至少有一位主角扮演[url=http://en.wikipedia.org/wiki/Manzai#Boke_and_tsukkomi]吐槽[/url]角色。

他们不必是真实喜剧二人组中的吐槽角色。他们只需要在日常生活中表现得像吐槽角色，并与展现装傻特质的角色互动即可。例如，他们可能经常对其他人滑稽的误解进行反驳。

与双人喜剧中“逗哏”和“捧哏”的概念类似，装傻和吐槽是漫才（日本喜剧风格）的一个非常重要的特征。装傻（boke）来自动词bokeru，带有“老糊涂”或“天然呆”的意思，体现在装傻角色容易误解和健忘的倾向上。吐槽（tsukkomi）一词指的是第二位喜剧演员“插嘴”并纠正装傻角色错误所扮演的角色。在表演中，吐槽角色通常会责骂装傻角色并快速拍打他们的头部；一种传统的漫才道具常被用于此目的——折纸扇。

更多信息请参见[url=http://en.wikipedia.org/wiki/Manzai]维基百科[/url]和[url=http://tvtropes.org/pmwiki/pmwiki.php/Main/BokeAndTsukkomiRoutine]tvtropes[/url]。');
INSERT INTO "tags" VALUES ('g3631','性瘾主角','内容',7,'本游戏中至少有一位主角患有[url=http://en.wikipedia.org/wiki/Nympho]性瘾[/url]。');
INSERT INTO "tags" VALUES ('g3632','成瘾主角','内容',13,'这部视觉小说中至少有一位主角有某种[url=https://en.wikipedia.org/wiki/Addiction]成瘾[/url]。');
INSERT INTO "tags" VALUES ('g3633','恐女症主角','内容',6,'本游戏有一位患有女性恐惧症（对女性过度或非理性的恐惧）的主角。');
INSERT INTO "tags" VALUES ('g3635','大学教师英雄','cont',31,'游戏中的一位英雄是高等院校（如大学或学院）的讲师。');
INSERT INTO "tags" VALUES ('g3636','歌手主角','cont',35,'本游戏的主角是一位[url=http://en.wikipedia.org/wiki/Vocalist]歌手[/url]。');
INSERT INTO "tags" VALUES ('g3637','主角的对手作为支持角色','cont',11,'本游戏有一个或多个支持角色与主角之间存在竞争关系。对手角色在与这种竞争相关的事件中拥有许多场景。与类似的英雄/女主角标签不同，他们不是主角（们）的（潜在）恋爱目标。

该标签的适用不要求竞争必须是相互的。');
INSERT INTO "tags" VALUES ('g3642','七夕','cont',24,'[url=https://en.wikipedia.org/wiki/Tanabata]七夕[/url]是本视觉小说情节的重要组成部分。

七夕是日本的节日，庆祝织女与牛郎（分别由织女星和牵牛星代表）这两位神灵的相会。根据传说，银河将这对恋人隔开，他们每年只能在农历七月初七相会一次。庆祝活动在七月至八月之间的不同日期举行。');
INSERT INTO "tags" VALUES ('g3643','购物中心','cont',28,'这部视觉小说有许多场景发生在[url=https://en.wikipedia.org/wiki/Shopping_mall]购物中心[/url]。');
INSERT INTO "tags" VALUES ('g3647','尼特族英雄','cont',13,'游戏中的一位英雄是尼特族，即他没有接受教育、没有就业或没有参加培训。');
INSERT INTO "tags" VALUES ('g3649','抢劫','cont',49,'这部视觉小说包含一个或多个对故事重要的偷窃事件。无论行为是偷偷进行还是使用恐吓，该标签均可适用。');
INSERT INTO "tags" VALUES ('g3650','沙盒','tech',155,'沙盒是一种模拟类型，玩家不是跟随不间断的故事情节，而是需要在"开放世界"地图中自行娱乐——类似于"在沙盒中玩耍"。通常玩家应自行决定下一步做什么、去哪里、按什么顺序进行哪些事件。

该类型的主要特征包括日历（即时间管理）、地图移动、需要收集和升级的各种资源和统计数据、可重复事件（这些事件通常根据你之前完成的次数而有各种升级/延续）、根据各种条件解锁的新事件等。

与纯[url=/g39]恋爱模拟[/url]或[url=/g40]养成模拟[/url]游戏的一个关键区别在于，沙盒不一定涉及约会/浪漫，而且需要升级的各种参数不仅限于主角或其他角色，尽管这些类型的元素可能存在。最常见的例子是各种堕落游戏。

[b]虽然数据库中允许包含沙盒元素的视觉小说，但仅含简短视觉小说元素的沙盒则不被允许。[/b]

诸如[url=/v22826]Insexual Awakening[/url]之类的视觉小说是该类型的良好例子。');
INSERT INTO "tags" VALUES ('g3651','破坏性事件','cont',735,'这是一个统称标签，汇集了与视觉小说中描绘的各种破坏性事件相关的标签。');
INSERT INTO "tags" VALUES ('g3653','生日','cont',67,'生日是这部视觉小说故事的重要组成部分。');
INSERT INTO "tags" VALUES ('g3657','伪娘对女性','ero',52,'这部视觉小说包含伪娘插入或性支配女性的场景。');
INSERT INTO "tags" VALUES ('g3658','史莱姆主角','cont',6,'这部视觉小说的主角是一个[url=https://monstergirlencyclopedia.miraheze.org/wiki/Slime]史莱姆[/url]。');
INSERT INTO "tags" VALUES ('g3659','有腋毛的英雄','cont',21,'本游戏中一个或多个男性角色腋下毛发浓密。');
INSERT INTO "tags" VALUES ('g3662','体内排尿','ero',59,'这部视觉小说包含角色在另一个角色的肛门和/或阴道内排尿的性场景。如果是在角色嘴里，请改用[url=/g2158]饮尿[/url]。');
INSERT INTO "tags" VALUES ('g3663','AI生成的图像','tech',1053,'这部视觉小说使用[url=https://en.wikipedia.org/wiki/Artificial_intelligence_art]AI生成的图像[/url]。');
INSERT INTO "tags" VALUES ('g3664','AI生成的故事','tech',46,'本游戏的故事由[url=https://en.wikipedia.org/wiki/Artificial_intelligence]人工智能（AI）[/url]生成。');
INSERT INTO "tags" VALUES ('g3669','胸围尺寸选择','tech',16,'玩家可以自定义女主角的胸部尺寸。');
INSERT INTO "tags" VALUES ('g3670','大学教师主角','cont',26,'本游戏的主角是高等院校（如大学或学院）的讲师。');
INSERT INTO "tags" VALUES ('g3671','失忆女主角','cont',106,'本游戏的女主角患有[url=https://en.wikipedia.org/wiki/Amnesia]失忆症[/url]。');
INSERT INTO "tags" VALUES ('g3672','极小的主角','cont',10,'本游戏的主角极其矮小。例如仙女或小精灵。');
INSERT INTO "tags" VALUES ('g3674','男同性恋支配','ero',42,'这部视觉小说至少有一个性场景，其中支配方和顺从方都是男性。');
INSERT INTO "tags" VALUES ('g3675','阴茎尺寸选择','tech',1,'玩家可以自定义主角或英雄的阴茎尺寸。');
INSERT INTO "tags" VALUES ('g3684','AI生成的资源','tech',1186,'本视觉小说的部分或全部素材由[url=https://en.wikipedia.org/wiki/Artificial_intelligence]人工智能（AI）[/url]生成。');
INSERT INTO "tags" VALUES ('g3685','马戏团','cont',42,'本视觉小说有许多场景设定在[url=https://en.wikipedia.org/wiki/Circus]马戏团[/url]中。

马戏团是一个由表演者组成的团体，他们呈现多样化的娱乐演出，可能包括小丑、杂技演员、驯养动物、空中飞人表演、音乐家、舞者、呼啦圈表演者、走钢丝者、杂耍者、魔术师、口技表演者、独轮车骑手，以及其他擅长物件操控和特技表演的艺人。');
INSERT INTO "tags" VALUES ('g3686','文字转语音人声','tech',57,'本游戏使用人工智能[url=https://en.wikipedia.org/wiki/Speech_synthesis]语音合成[/url]技术进行角色配音。请注意，这是有意设计的，而非游戏引擎提供的功能，如[url=https://www.renpy.org/doc/html/self_voicing.html]Ren''py[/url]。

游戏示例：[url=/v39021]UTAtte! Korone Imu![/url]');
INSERT INTO "tags" VALUES ('g3690','男性对跨性别男性','ero',8,'本视觉小说包含男性与作为接受方的跨性别男性之间的性行为。');
INSERT INTO "tags" VALUES ('g3691','兄妹作为恋爱对象','cont',39,'本游戏中，男主角和女主角互为兄弟姐妹。');
INSERT INTO "tags" VALUES ('g3692','多变的文本框','tech',130,'游戏的文本框会在游戏过程中变化，通过切换视角、通关路线、完成章节，或其他随机变量触发。它可能呈现不同的颜色/色调，引入新元素，甚至呈现完全崭新的画面。');
INSERT INTO "tags" VALUES ('g3693','不投入的性行为','ero',16,'本视觉小说有多个场景描绘参与者对性行为缺乏热情，可能在性交过程中做其他事情（如玩手机、打电子游戏或看漫画）。他们甚至可能在发生关系时毫无情感表现。

此标签仅用于双方自愿的性爱场景，不适用于受害者进入无情感状态的非自愿内容。');
INSERT INTO "tags" VALUES ('g3695','长雀斑的男主角','cont',90,'本游戏中的男主角长有[url=https://en.wikipedia.org/wiki/Freckle]雀斑[/url]。');
INSERT INTO "tags" VALUES ('g3696','哀悼','cont',131,'哀悼某人离世的情节在本故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g3698','跨性别女性对女性','ero',18,'[url=https://vndb.org/i2450]跨性别女性[/url]与女性之间的性行为，女性为接受方。');
INSERT INTO "tags" VALUES ('g3699','跨性别女性对跨性别女性','ero',22,'本视觉小说包含两名[url=https://vndb.org/i2450]跨性别女性[/url]之间的性行为。');
INSERT INTO "tags" VALUES ('g3700','涉及性别不遵从者的性行为','ero',827,'本视觉小说包含的性爱场景中，至少一名角色不符合传统性别认同（跨性别、性别酷儿、非二元性别或双性人），或是没有传统性别认同的实体（扶她、伪娘）。');
INSERT INTO "tags" VALUES ('g3707','重叠的恋爱对象','cont',27,'本视觉小说中的一名或多名角色作为多于一位主角的恋爱对象。该标签不要求其必须在同一路线/时间线内成为所有相关主角的恋爱对象。此标签与[url=/g3182]每位主角有不同恋爱对象[/url]相反。

示例：在[url=/v3144]《美好的每一天 ～不连续的存在～》[/url]中，[url=/c3563]橘希实香[/url]是对于[url=/c3559]高岛柘榴[/url]和[url=/c3560]间宫卓司[/url]都可攻略的角色。');
INSERT INTO "tags" VALUES ('g3709','情色精神控制角色扮演','ero',4,'本游戏包含一个或多个性爱场景，其中双方自愿扮演虚假的精神控制情景。');
INSERT INTO "tags" VALUES ('g3710','实时性爱直播','ero',49,'本视觉小说包含角色在性交时面向广大普通观众进行直播的场景，例如通过电视或互联网的新闻播报。

此标签不适用于非实况的露骨色情内容，例如[url=https://vndb.org/g1778]色情拍摄[/url]。');
INSERT INTO "tags" VALUES ('g3711','训练营','cont',15,'[url=https://en.wikipedia.org/wiki/Training_camp]训练营[/url]在本视觉小说中扮演主要角色。

训练营是一段有组织的时期，军事人员或运动员在此期间参与严格且专注的训练日程，以学习或提高技能。运动员通常利用训练营为即将到来的赛事做准备；在竞技体育中，则专注于发展技能和策略以击败对手。');
INSERT INTO "tags" VALUES ('g3712','跑步（运动）','cont',12,'[url=https://en.wikipedia.org/wiki/Running]跑步[/url]运动在本视觉小说中扮演主要角色。');
INSERT INTO "tags" VALUES ('g3715','怀孕的女主角','cont',42,'本游戏中有一位女主角在游戏开始时已怀孕，原因可能是主角或其他角色。

若女主角在故事发展过程中才怀孕，请勿使用此标签。');
INSERT INTO "tags" VALUES ('g3720','鼠娘女主角','cont',7,'一位或多位女主角是鼠女。');
INSERT INTO "tags" VALUES ('g3721','生存焦点','cont',182,'故事中的角色在一段时间内面临切实的死亡威胁，并积极努力在处境中生存。
例子可以包括角色被困在[url=/g3342]死亡游戏[/url]/[url=/g664]大逃杀[/url]、[url=/g2440]自然灾害[/url]、[url=/g456]战争[/url]中，或在太空中氧气不足等。

不要将此标签用于瞬时威胁，即没有把生存作为目标重点的情况，因为此标签并不是用来标记每一部含有死亡打斗的视觉小说——这类设定在奇幻背景（如刀剑武器）中很常见。');
INSERT INTO "tags" VALUES ('g3722','动漫风格3D','tech',717,'本游戏使用的3D唤起了东西方动画的风格（与写实3D相反），通常使用像恋活（Koikatsu）这样的渲染引擎制作。

例子有[url=/v29271]What''s Mine Is Yours: Season 1[/url]、[url=/v35869]Keepers 1: Revolution[/url]等。

使用此标签时，还需要同时使用描述游戏是[url=/g417]实时3D[/url]还是[url=/g2693]基于渲染[/url]的标签。');
INSERT INTO "tags" VALUES ('g3723','写实风格3D','tech',1816,'本游戏使用的3D是写实风格的（与动漫和卡通风格相反），通常使用Daz 3D或Honey Select等渲染引擎制作。

通过Patreon制作的大多数游戏都是写实风格。例子有[url=/v25288]Being a DIK[/url]、[url=/v21824]Depraved Awakening[/url]、[url=/v25342]City of Broken Dreamers[/url]等。

使用此标签时，还需要同时使用描述游戏是[url=/g417]实时3D[/url]还是[url=/g2693]预渲染3D图形[/url]的标签。');
INSERT INTO "tags" VALUES ('g3725','黑暗世界','cont',35,'这部视觉小说设定在与[url=https://en.wikipedia.org/wiki/World_of_Darkness]黑暗世界[/url]相同的宇宙中，或者包含该系列的角色。');
INSERT INTO "tags" VALUES ('g3726','驾驶英雄','cont',6,'本游戏中的一位或多位英雄驾驶陆上载具。

包括驾驶各种陆上载具，从城市轿车到赛车、公共汽车、卡车等，也包括坦克等军用车辆...

还包括由动物拉动的马车和货车，但不包括更适合归类为“骑乘”而非“驾驶”的其他类型，如马、自行车、滑板等。');
INSERT INTO "tags" VALUES ('g3728','仅女性支配','ero',130,'游戏的主要焦点是女性支配，所有或绝大部分场景都与该行为有关。

女性支配是一种BDSM活动，其中支配方为女性。');
INSERT INTO "tags" VALUES ('g3729','基于广播剧','tech',23,'这部视觉小说基于或改编自[url=https://en.wikipedia.org/wiki/Radio_drama]广播剧[/url]。

不要与[url=http://vndb.org/g1056]同人小说[/url]混淆，同人小说基本上是原作中没有的支线故事。');
INSERT INTO "tags" VALUES ('g3730','可更换配音演员','tech',41,'在这部视觉小说中，你可以为一个或多个角色在几位配音演员之间进行选择。');
INSERT INTO "tags" VALUES ('g3731','发情期','ero',30,'这部视觉小说含有会进入发情期的角色。

处于\"发情\"状态，也称为[url=http://en.wikipedia.org/wiki/Estrous_cycle]发情周期[/url]，是大多数哺乳动物（人类除外）的雌性在排卵前经历的最大性接受期。

在有发情周期的物种/怪物中，雌性通常只在周期的发情阶段有性行为。');
INSERT INTO "tags" VALUES ('g3732','毕业','cont',31,'从学术机构毕业是这部视觉小说故事的重要组成部分。');
INSERT INTO "tags" VALUES ('g3734','警察暴行','cont',9,'[url=https://en.wikipedia.org/wiki/Police_brutality]警察暴行[/url]在这部视觉小说的故事中扮演重要角色。

警察暴行是指执法部门对个人或群体过度且无根据使用武力的行为。这是警察不当行为的一种极端形式，也是一种侵犯公民权利的行为。警察暴行包括但不限于殴打、枪击、\"不当制服，以及无根据使用电击枪\"。

例子：[url=/v22728]Silver Jiken 25 Ku[/url]、[url=/v4511]Portopia Renzoku Satsujin Jiken[/url]');
INSERT INTO "tags" VALUES ('g3735','基于命令的冒险游戏','tech',52,'此标签用于数据库中具有基于指令的冒险游戏特征的作品。这些冒险游戏在一个列出可能指令（如交谈、检查、交谈、移动等）的菜单上供玩家选择，用于推进叙事和解谜。许多带有此标签的游戏是视觉小说的直接前身，并且[url=https://vndb.org/d2#1]仅因此被收录到数据库中[/url]，因此它们在数据库中的存在不应被用作收录非视觉小说的理由。');
INSERT INTO "tags" VALUES ('g3736','点击式冒险游戏','tech',465,'此视觉小说含有[url=https://en.wikipedia.org/wiki/Adventure_game#Point-and-click_adventure_games]点击式冒险游戏[/url]的元素。

点击式冒险游戏是指玩家通常通过计算机鼠标或类似指向设备，以点击式界面控制角色的游戏，尽管也可能提供其他控制方式。玩家点击来移动角色、与非玩家角色互动（通常会开启对话树）、检查游戏场景中的物体，或使用角色物品栏中的物品。许多早期的点击式游戏会像文字冒险游戏一样在屏幕上列出动词来描述具体动作，但较新的游戏更多使用上下文相关的用户界面元素来减少或取消这种方式。

虽然含有上述元素的视觉小说允许收录在数据库中，但视觉小说元素可忽略不计的点击式冒险游戏则不允许。');
INSERT INTO "tags" VALUES ('g3737','有晒痕的主人公','cont',7,'此游戏中的主人公身体带有[url=http://en.wikipedia.org/wiki/Tan_line]晒痕[/url]。

晒痕是指人体皮肤上一个或多个区域与其他区域相比明显更为苍白的界线，这些其他区域因长时间暴露于紫外线辐射而被晒黑。辐射源可以是太阳，也可以是日光浴床中使用的人工紫外线源。');
INSERT INTO "tags" VALUES ('g3738','种族扮演（角色扮演）','ero',3,'此视觉小说包含一个或多个涉及[url=https://en.m.wiktionary.org/wiki/raceplay]种族扮演主题角色扮演[/url]的场景。这是一种性角色扮演形式，玩家会演绎带有种族色彩的情境，例如跨种族的主奴关系。 

示例：[url=/v28951]Under Control[/url]');
INSERT INTO "tags" VALUES ('g3739','色情化种族主义','ero',7,'此视觉小说包含一个或多个情色场景，其中至少两个角色之间存在种族主义权力动态。应当至少有一个角色出于种族偏见对另一个角色表现出支配性的一面。

此标签不应与[url=/g3738]种族扮演（角色扮演）[/url]混淆，后者的这些动态明显是各方同意的，种族主义只是表演。 

示例：[url=/v24622]Bully[/url]');
INSERT INTO "tags" VALUES ('g3740','改编','tech',1087,'此视觉小说是另一部来自不同媒介（动画、漫画、小说、其他游戏等）作品的改编。

对于尽可能忠实于原作的官方或非官方改编，使用此标签或其任何子标签。

如果视觉小说包含原作中没有的支线故事、非官方角色或事件，请改用[url=/g1056]同人小说[/url]标签。');
INSERT INTO "tags" VALUES ('g3741','角色移动','tech',488,'此视觉小说具有一种游戏机制，玩家可以在2D或3D空间中控制角色。这让玩家能够在环境中漫游，并与推进或发展故事的其他角色和物体（如书籍、音频日志或线索）互动。

常见例子有兰斯系列等RPG游戏，或弹丸论破系列等互动冒险游戏。');
INSERT INTO "tags" VALUES ('g3742','少女前线','cont',4,'此视觉小说设定在[url=https://en.wikipedia.org/wiki/Girls%27_Frontline]少女前线[/url]的同一宇宙中，或包含其中的角色。');
INSERT INTO "tags" VALUES ('g3743','极乐迪斯科','cont',4,'此视觉小说设定在[url=https://en.wikipedia.org/wiki/Disco_Elysium]极乐迪斯科[/url]的同一宇宙中，或包含其中的角色。');
INSERT INTO "tags" VALUES ('g3746','泡泡浴','cont',8,'此视觉小说有许多场景设定在日本[url=https://en.wikipedia.org/wiki/Types_of_prostitution_in_modern_Japan#Soapland]泡泡浴[/url]中。');
INSERT INTO "tags" VALUES ('g3747','辣妹男主人公','cont',4,'此游戏包含一个或多个[url=https://en.wikipedia.org/wiki/Gyaruo]辣妹男[/url]主人公。

常被视为辣妹（Gyaru）时尚的男性对应版，Gyaruo的''-o''后缀是汉字''男''的一种读法。');
INSERT INTO "tags" VALUES ('g3748','失忆的主人公','cont',57,'此游戏中的主人公患有[url=https://en.wikipedia.org/wiki/Amnesia]失忆症[/url]。');
INSERT INTO "tags" VALUES ('g3749','自闭症主人公','cont',6,'本视觉小说至少有一位主角患有[url=https://en.wikipedia.org/wiki/Autism]自闭症[/url].

自闭症是一种神经发育障碍，其特征是社交互动受损、语言和非语言交流受损，以及受限的、重复的或刻板的行为。诊断标准要求症状在三岁前显现.

注意：请仅在相关主角确实被诊断为自闭症时才使用此标签。不要将其用于例如仅仅过于害羞而无法正常交流的角色.');
INSERT INTO "tags" VALUES ('g3751','帮派头目主角','cont',5,'本游戏中的一位主角是一个[url=https://en.wikipedia.org/wiki/Gang]帮派[/url]的头目.

帮派头目是帮派中拥有最高权力的人。在日本，帮派头目通常被其他帮派成员称为“Aniki”（意为大哥）.');
INSERT INTO "tags" VALUES ('g3752','日本黑帮主角','cont',12,'本游戏中的一位主角是（或曾经是）[url=http://en.wikipedia.org/wiki/Yakuza]日本黑帮[/url]的成员.');
INSERT INTO "tags" VALUES ('g3754','拟似家庭','cont',34,'本视觉小说包含[url=https://en.wikipedia.org/wiki/Family_of_choice]拟似家庭[/url]的桥段.

拟似家庭是一种现象，一群人如同家人般彼此相爱，即使（且因为）他们没有血缘关系.');
INSERT INTO "tags" VALUES ('g3755','滥交主角','cont',17,'本游戏中的一位主角生性滥交。他频繁且不加选择地与不同伴侣发生性行为.

滥交的主角四处上床并非像妓女那样为了钱，而是为了满足自己.

不要将此与[url=/g3631]性瘾主角[/url]混淆，后者完全无法抗拒任何性场合.');
INSERT INTO "tags" VALUES ('g3756','务实主角','cont',26,'本视觉小说的主角基于逻辑、实际和/或理性的考量与观点做出决定并采取行动。应注意的是，务实的人不一定冷漠或没有感情.');
INSERT INTO "tags" VALUES ('g3757','随和主角','cont',16,'本游戏有一位性格随和的主角；他很少生气、悲伤、焦虑、兴奋等.');
INSERT INTO "tags" VALUES ('g3759','非原创配音','tech',10,'本视觉小说使用的配音并非专门为本视觉小说制作。它可能是从其他媒体源非法提取的，可能是重复使用的同一开发商制作的另一款视觉小说的配音，也可能是免版税的配音.');
INSERT INTO "tags" VALUES ('g3760','裸体模特','ero',23,'本视觉小说包含一个角色为广告或艺术目的摆出裸体模特姿势的场景.

[url=https://s2.vndb.org/sf/35/179835.jpg]NSFW示例[/url]');
INSERT INTO "tags" VALUES ('g3764','场景回顾','tech',873,'本游戏允许观看已看过的场景，而无需读取之前的存档或开始新游戏.

大多数场景回顾在满足特定条件后解锁，通常可从主菜单或标题画面进入.');
INSERT INTO "tags" VALUES ('g3765','性爱场景回顾','ero',285,'本游戏允许观看主线故事中的性爱场景，而无需读取之前的存档或开始新游戏，通常可从主菜单或标题画面进入.

如果游戏画廊仅显示性爱场景CG而不允许你重播整个场景，请不要使用此标签.');
INSERT INTO "tags" VALUES ('g3767','人造人主角','cont',8,'本故事中至少有一位主角是[url=https://en.wikipedia.org/wiki/Homunculus]人造人[/url].

人造人是一种人工创造的人类，通过魔法和/或科学获得生命.');
INSERT INTO "tags" VALUES ('g3768','回合制战术','cont',21,'[url=https://en.wikipedia.org/wiki/Turn-based_tactics]回合制战术[/url]是策略游戏的一个子类型，通常专注于小规模冲突和控制单个单位，而不是同时控制大批作战人员，这通常以移除或大大简化资源管理等非战斗战略层为代价. 

TBT游戏往往更重视单个单位。为此，详细的战场地图、姿态或朝向等状态规则以及其他注重真实性的机制都很常见.

对于与RPG类型重叠的TBT游戏（特别是可以改变单位装备和获得经验的情况），请改使用[url=/g339]SRPG[/url]标签.');
INSERT INTO "tags" VALUES ('g3769','哥特风格主角','cont',19,'本游戏主角大多穿着[url=https://en.wikipedia.org/wiki/Gothic_fashion]哥特式服装[/url].');
INSERT INTO "tags" VALUES ('g3770','动画切换','tech',12,'本视觉小说有一个可以打开或关闭动画的开关.

示例：[url=/v32624]Study § Steady 2[/url]、[url=/v8438]Witch''s Garden[/url]等.');
INSERT INTO "tags" VALUES ('g3771','超过七个恋爱对象','cont',1119,'本游戏的恋爱对象（无论性别或性别组合）比典型的视觉小说更多；具体来说至少有八个.');
INSERT INTO "tags" VALUES ('g3772','技术员主角','cont',12,'本游戏中的一位或多位主角是技术员.

