INSERT INTO "tags" VALUES ('g3781','猎人男主角','cont',50,'至少有一位男主角是猎人。

狩猎是指为了食物、娱乐或交易而追捕任何生物（通常是野生动物）的行为。在现代用法中，该术语指合法狩猎，有别于偷猎，偷猎是指违反适用法律杀死、诱捕或捕获狩猎物种的行为。被猎捕的物种被称为猎物，通常是哺乳动物以及迁徙或非迁徙的猎鸟。

另一方面，虚构的猎人则以狩猎从动物到人类再到怪物等任何东西而闻名……');
