INSERT INTO "tags" VALUES ('g3794','皮条客男主角','cont',15,'人口贩子，也称为皮条客或老鸨，利用受害者的弱点和缺乏机会，同时以婚姻、就业、教育和/或整体更好的生活为承诺。
然而，最终人口贩子强迫受害者成为妓女或从事性行业工作。
性行业中的各种工作包括卖淫、在脱衣舞俱乐部跳舞、出演色情电影和色情制品，以及其他形式的强迫劳役。

皮条客是妓女的代理人（通常是男性），收取她们部分收入。这种行为被称为拉皮条或撮合。皮条客可能通过提供广告服务、人身保护，或提供并可能垄断一个他或她（即妓女）可以接客的场所来获得这笔钱。

皮条客与妓女之间的关系可能是虐待性和占有性的，皮条客会使用心理恐吓、操纵、挨饿、强奸和/或轮奸、殴打、禁闭、威胁对受害者家人施暴、强迫吸毒以及这些行为带来的羞耻等手段。');
INSERT INTO "tags" VALUES ('g3795','老鸨女主角','cont',17,'人口贩子，也称为皮条客或老鸨，利用受害者的弱点和缺乏机会，同时以婚姻、就业、教育和/或整体更好的生活为承诺。
然而，最终人口贩子强迫受害者成为妓女或从事性行业工作。
性行业中的各种工作包括卖淫、在脱衣舞俱乐部跳舞、出演色情电影和色情制品，以及其他形式的强迫劳役。

[url=https://en.wikipedia.org/wiki/Procuring_(prostitution)]皮条客[/url]是妓女的代理人（通常是男性），收取她们部分收入。这种行为被称为拉皮条或撮合。皮条客可能通过提供广告服务、人身保护，或提供并可能垄断一个他或她（即妓女）可以接客的场所来获得这笔钱。

经营妓院的女人被称为老鸨，而不是皮条客。

皮条客/老鸨与妓女之间的关系可能是虐待性和占有性的，皮条客/老鸨会使用心理恐吓、操纵、挨饿、强奸和/或轮奸、殴打、禁闭、威胁对受害者家人施暴、强迫吸毒以及这些行为带来的羞耻等手段。');
INSERT INTO "tags" VALUES ('g3798','恋爱竞争','cont',774,'本游戏有一个故事元素，角色们相互竞争或对抗，以赢得一个人的爱，通常是主角。无论角色最终是与一个人约会、与所有心上人约会，还是根本没有在一起，都不影响此标签的适用。

如果所涉角色之间没有明显的竞争或对抗，即使明确他们彼此相爱，也不应使用此标签。

如果竞争角色是两个人，请改用其子标签[url=/g336]三角恋[/url]。');
