INSERT INTO "tags" VALUES ('g3828','完全不可避免的寝取','ero',81,'在游戏所有可能路线中（必须发生在伴侣自己的路线上）或分支点之前（也适用于线性/视觉小说），都会发生寝取事件。这无法避免。

