INSERT INTO "tags" VALUES ('g3830','吸烟恋物癖','ero',4,'这部视觉小说包含与[url=https://en.wikipedia.org/wiki/Smoking_fetishism]吸烟恋物癖[/url]相关的场景。

吸烟恋物癖是一种基于肺部消耗（吸食）烟草或大麻的性癖好，通常通过香烟、雪茄，以及某种程度上通过烟斗、电子烟和水烟筒进行。作为一种癖好，其机制涉及从观察或想象他人吸烟中获得性唤起，有时也包括自己吸烟。');
INSERT INTO "tags" VALUES ('g3831','肛门液体排出','ero',42,'这部视觉小说包含至少一个涉及肛门液体排出的性场景。

本视觉小说中的角色排出注入其肛门的液体，通常通过灌肠，不过也可能在[url=/g3662]体内排尿[/url]后排出大量精液甚至尿液。

如果排出的液体中还含有粪便，请将此标签与[url=/g897]粪便[/url]标签一同使用。

[url=https://t.vndb.org/sf/90/183190.jpg]示例[/url]');
INSERT INTO "tags" VALUES ('g3832','反向寝取','ero',14,'由于主角的伴侣（SO）的故意作为/不作为，或由于SO与主角的协议，在本视觉小说中主角最终与他人发生性关系。只有主角（无论是男是女）与他人发生性行为。

通常情况下，伴侣双方都没有出轨的欲望，但由于主角伴侣（SO）的欲望，主角最终会与他人发生性关系。这可以是一种与可信之人的双方同意的行为，由伴侣说服其重要他人与该可信之人发生性关系；也可能是一种自私行为，伴侣为了个人利益（金钱、勒索某人的把柄等）而出卖或让其重要他人卖淫。

在任何情况下，主角的伴侣（SO）都（至少最初）接受主角与他人发生性关系，甚至可能乐在其中。

不要将其与[url=/g1710]交换伴侣[/url]混淆，后者是双方恋爱伴侣都与他人发生性关系；也不要与[url=/g2141]多元之爱[/url]混淆，那是一种涉及浪漫情感的长期安排；而反向寝取只是对某种性癖的一时满足。');
INSERT INTO "tags" VALUES ('g3833','阴道产卵','ero',34,'本游戏包含其角色从阴道产卵的场景，这种现象也称为[url=https://en.wikipedia.org/wiki/Oviparity]卵生[/url]。

