INSERT INTO "tags" VALUES ('g3848','Spooktober视觉小说开发大赛','tech',540,'这部视觉小说是为[url=https://itch.io/jam/spooktober-visual-novel-jam]Spooktober视觉小说开发大赛[/url]而创作，这是一项年度游戏开发大赛，专注于制作万圣节和恐怖主题的视觉小说。');
INSERT INTO "tags" VALUES ('g3858','必须选择语音或字幕','tech',13,'这款游戏有语音，但强制读者在“无字幕的语音”和“无语音的字幕”之间做出选择。两者不能同时拥有。');
INSERT INTO "tags" VALUES ('g3864','无性恋角色','cont',108,'本游戏中的至少一名角色认同为无性恋。 

