INSERT INTO "tags" VALUES ('g3876','拼图游戏','tech',12,'本游戏包含[url=https://en.wikipedia.org/wiki/Jigsaw_puzzle]拼图游戏[/url]。

拼图游戏是一种拼图类游戏，需要组装通常形状不规则的互锁和镶嵌碎片，每个碎片通常包含画面的一部分。组装完成后，拼图碎片形成一幅完整图片。');
INSERT INTO "tags" VALUES ('g3878','残疾英雄','cont',14,'因畸形、受伤或身体部位截肢而严重丧失身体能力的英雄。');
INSERT INTO "tags" VALUES ('g3879','越南','cont',14,'本视觉小说的故事背景设定在[url=https://en.wikipedia.org/wiki/Vietnam]越南[/url]。');
INSERT INTO "tags" VALUES ('g3880','作为秘密的异装主角','cont',34,'该游戏的主角（男性或女性）正在进行异装，并且必须保守异装的秘密，否则将带来后果。

最常见的例子是主角必须潜入[url=/g423]女子学校[/url]，因此被迫进行异装。

另一个例子是主角喜欢异装但不想让别人知道，因为一旦被发现就会被嘲笑。

如果没有人知道主角异装，但这不是主角积极试图欺骗他人的结果，而仅仅是异装逼真的结果，则不要添加此标签。

如果秘密在早期就被揭露，请不要添加此标签。');
INSERT INTO "tags" VALUES ('g3881','德国','cont',15,'本视觉小说的故事背景设定在[url=https://en.wikipedia.org/wiki/Germany]德国[/url]。');
INSERT INTO "tags" VALUES ('g3882','自闭症主角','cont',21,'本视觉小说的主角患有[url=https://en.wikipedia.org/wiki/Autism]自闭症[/url]。

自闭症是一种神经发育障碍，其特征是社交互动受损、语言和非语言交流受损，以及行为受限、重复或刻板。诊断标准要求症状在三岁之前显现。

注意：仅当该主角确实被确诊为自闭症时才可使用此标签。不要将其用于例如仅仅因为过于害羞而无法正常交流的角色。');
INSERT INTO "tags" VALUES ('g3890','弓箭手英雄','cont',13,'本游戏中的英雄是一名弓箭手，无论是与体育相关的能力还是作为一般职业技能。

[url=https://en.wikipedia.org/wiki/Archery]射箭[/url]是一项使用弓来发射箭矢的运动、练习或技能。历史上，射箭曾用于狩猎和战斗。在现代，它主要是一项竞技运动和休闲活动。');
INSERT INTO "tags" VALUES ('g3892','网络主播主角','cont',41,'本游戏的主角是一名[url=https://en.wikipedia.org/wiki/Online_streamer]网络主播[/url]。

网络主播是通过直播或预录视频在网络上进行自我播出的人。网络主播的范围已扩展到不同类型的领域，包括玩电子游戏、教程、甚至单人聊天。

注意：此特质仅适用于非色情主播。');
INSERT INTO "tags" VALUES ('g3893','网络主播女主角','cont',71,'本游戏中的一名或多名女主角是[url=https://en.wikipedia.org/wiki/Online_streamer]网络主播[/url]。

网络主播是通过直播或预录视频在网络上进行自我播出的人。网络主播的范围已扩展到不同类型的领域，包括玩电子游戏、教程、甚至单人聊天。

注意：此特质仅适用于非色情主播。');
INSERT INTO "tags" VALUES ('g3894','家庭伦理剧','cont',180,'这个故事包含家庭伦理剧的元素，例如兄弟姐妹之间或父母与子女之间的失和/争斗。

不要将此标签与[url=/g1865]家族恩怨[/url]混淆，后者是指两个或多个不同家族之间的争斗。');
INSERT INTO "tags" VALUES ('g3895','乐器演奏者主角','cont',38,'本视觉小说的主角会演奏一种乐器。');
INSERT INTO "tags" VALUES ('g3897','背景中多个位置固定视角','cont',9,'游戏包含至少一个性爱场景，该场景以固定视角的单一背景为舞台，而其中的角色会改变体位。

可以表现时间的流逝，同时展示的物品可以改变位置，以体现该场所随时间推移而变得凌乱。

请勿将此标签用于涉及多种体位的性爱场景，其中每个CG都是独一无二的，因此具有不同的视角。

示例来自[url=/v15167]Kedamono-tachi no Sumu Ie de[/url]：https://f.blicky.net/f.php?h=2S5XjsYO&p=1 > https://f.blicky.net/f.php?h=0Dj6NHwu&p=1 > https://f.blicky.net/f.php?h=1VdA85hI&p=1.');
INSERT INTO "tags" VALUES ('g3899','仅限非二元性别恋爱对象','cont',32,'本游戏中的所有恋爱对象均为[url=https://en.wikipedia.org/wiki/Non-binary_gender]非二元性别或性别酷儿[/url]。 

非二元性别是指不符合公认男性与女性二元划分的性别认同。人们可能觉得自己两者皆是、两者皆非，或是两者的某种混合。

这与他们的生理性别或外在表现方式无关。

请不要将此标签用于性别未经证实的角色。此标签仅用于官方确认为非二元性别的角色。');
INSERT INTO "tags" VALUES ('g3900','To Love Ru','cont',31,'这些游戏包含来自[url=https://en.wikipedia.org/wiki/To_Love_Ru]To Love Ru[/url]系列的角色。');
INSERT INTO "tags" VALUES ('g3901','笨拙主角','cont',6,'本游戏中的一位或多位主角是[url=http://dictionary.reference.com/browse/clumsy]笨拙的[/url]，或被认为是[url=https://en.wikipedia.org/wiki/Accident-proneness]易出事故的[/url]。

笨拙的人是指缺乏技巧或身体协调性的人，往往比其他人更容易发生意外。

易出事故的倾向，也称为笨拙，是指某些人可能具有某种倾向，或比其他人更容易遭遇事故（如车祸和工伤）的概念。它可能被用作拒绝向此类个人提供任何保险的理由。');
INSERT INTO "tags" VALUES ('g3904','主角面部开关','tech',91,'这些视觉小说有一个开关，可以开启或关闭主角的面部。

通常这会影响侧立绘，但在某些情况下甚至可能影响主角精灵图的出现与否。');
INSERT INTO "tags" VALUES ('g3907','跳至射精按钮','ero',3,'带有此标签的成人游戏提供了一种方式，让读者在情色场景中可以直接跳至射精序列。');
INSERT INTO "tags" VALUES ('g3909','舞者主角','cont',22,'本游戏的主角是一名舞者。

舞者指以舞蹈为职业的人，例如在舞台上表演。');
INSERT INTO "tags" VALUES ('g3910','程序员主角','cont',56,'这部视觉小说的主角是一名程序员。 

计算机编程是设计、编写、测试、调试/排障以及维护计算机程序源代码的过程。

源代码是用编程语言编写的。编程的目的是创建一个表现出某种预期行为的程序。编写源代码的过程通常需要多个不同领域的专业知识，包括应用领域知识、专门算法和形式逻辑。');
INSERT INTO "tags" VALUES ('g3911','肌肉崇拜','ero',9,'肌肉崇拜（sthenolagnia）是BDSM的一种轻度形式，某人会以性唤起的方式触摸、摩擦、按摩、亲吻和/或舔舐伴侣身体的肌肉。');
INSERT INTO "tags" VALUES ('g3912','渐变发色主角','cont',19,'本游戏主角的头发在风格上采用[url=https://en.wikipedia.org/wiki/Color_gradient]颜色渐变[/url]渲染。');
INSERT INTO "tags" VALUES ('g3914','战后','cont',19,'故事发生在战争之后。

战后时期是指战争结束后的那段间隔时间。

即使地球因战争而沦为末日状态，也请勿将此标签用于[url=/g68]末日地球[/url]。');
INSERT INTO "tags" VALUES ('g3915','亚洲','cont',90,'本游戏的大部分或全部故事发生在[url=https://en.wikipedia.org/wiki/Asia]亚洲[/url]。

亚洲是世界上陆地面积和人口最大的大洲。它东临太平洋，南临印度洋，北临北冰洋。亚洲与欧洲的边界是一种历史和文化构建，因为两者之间没有明确的自然和地理分隔。');
INSERT INTO "tags" VALUES ('g3916','网络主播主角','cont',23,'本游戏中的一位或多位主角是[url=https://en.wikipedia.org/wiki/Online_streamer]网络主播[/url]。

网络主播是指通过直播或预录视频在网上播出自我的个人。网络主播的范围已扩展到不同类型，包括玩电子游戏、教程，甚至单人聊天。

请注意，此特征仅适用于非色情主播。');
INSERT INTO "tags" VALUES ('g3917','肌肉增长','cont',11,'这款游戏描绘了男主角和/或女主角在极短时间内肌肉量剧增的情节，这通常是魔法或某种药物的结果。');
INSERT INTO "tags" VALUES ('g3918','自我恋爱','cont',6,'这款游戏包含一个角色与其另一个自我版本之间的浪漫情节。

如果这种浪漫情节发展为性爱，可以与本标签一同使用[url=/g788]Selfcest[/url]。');
INSERT INTO "tags" VALUES ('g3921','渔民主角','cont',8,'本游戏的主角是一位[url=https://en.wikipedia.org/wiki/Fisherman]渔夫[/url]。

渔夫或渔人是指从水域中捕捞鱼类及其他动物，或采集贝类的人。');
INSERT INTO "tags" VALUES ('g3922','橄榄球','cont',4,'[url=https://en.wikipedia.org/wiki/Rugby_union]橄榄球[/url]在本游戏故事中扮演重要角色。');
INSERT INTO "tags" VALUES ('g3930','身体美学','cont',933,'这是一个总括性标签，收集与身体美学相关的标签。');
INSERT INTO "tags" VALUES ('g3931','整容手术','cont',10,'该视觉小说显著地展现了整容手术。整容手术是在身体正常部位进行的选择性手术，其唯一目的是改善个人外貌和/或消除衰老迹象。

整容手术的范围包括：
* 乳房整形：隆乳、提升、缩小
* 面部轮廓整形：鼻整形、下巴或脸颊增强
* 面部年轻化：拉皮、眼睑提升、颈部提升、提眉
* 身体塑形：腹部除皱、吸脂、男性乳房发育症治疗
* 皮肤年轻化：激光换肤、肉毒杆菌、填充治疗');
INSERT INTO "tags" VALUES ('g3932','健身中心','cont',24,'这款视觉小说中有许多场景设于公共健身房，这是一种专门进行室内运动和锻炼的设施。

请勿在场景设在校园健身房或其周围的视觉小说上使用此标签。');
INSERT INTO "tags" VALUES ('g3933','骗子主角','cont',12,'本游戏的主角是个骗子。

骗子通过[url=https://en.wikipedia.org/wiki/Scam]骗局[/url]欺诈他人。骗局通常依靠骗子先获取受害者的信任，然后再骗取他们的金钱或其他财产。');
INSERT INTO "tags" VALUES ('g3934','按参与者性别分类的性行为','ero',0,'这些是性行为特征，其主要特征是以性别对参与者进行分类。');
INSERT INTO "tags" VALUES ('g3935','女性和性别非常规者之间的性行为','ero',457,'这款视觉小说包含性爱场景，其中至少一名角色为女性，而至少另一名角色要么不符合传统性别认同（跨性别、性别酷儿、非二元或双性人），要么是一个不具有传统性别认同的实体（futanari、dickgirl）。');
INSERT INTO "tags" VALUES ('g3936','男性和性别非常规者之间的性行为','ero',389,'这款视觉小说包含性爱场景，其中至少一名角色为男性，而至少另一名角色要么不符合传统性别认同（跨性别、性别酷儿、非二元或双性人），要么是一个不具有传统性别认同的实体（futanari、dickgirl）。');
INSERT INTO "tags" VALUES ('g3937','性别非常规者之间的性行为','ero',136,'这款视觉小说包含性爱场景，其中一名性别非常规者与另一名角色发生性关系，后者要么不符合传统性别认同（跨性别、性别酷儿、非二元或双性人），要么是一个不具有传统性别认同的实体（futanari、dickgirl）。');
INSERT INTO "tags" VALUES ('g3938','群体性行为参与者','ero',0,'这是一个元标签，用于包含所有定义群体性行为参与者的标签。');
INSERT INTO "tags" VALUES ('g3939','涉及性别非常规者的群体性行为','ero',40,'这款视觉小说包含群体性爱场景，其中至少一名角色要么不符合传统性别认同（跨性别、性别酷儿、非二元或双性人），要么是一个不具有传统性别认同的实体（futanari、dickgirl）。');
INSERT INTO "tags" VALUES ('g3940','涉及男性、女性和性别非常规者混合群体的性行为','ero',9,'这款视觉小说包含性爱场景，其中至少一名角色为男性，至少一名为女性，而至少另一名角色要么不符合传统性别认同（跨性别、性别酷儿、非二元或双性人），要么是一个不具有传统性别认同的实体（futanari、dickgirl）。

为数据库之目的，此标签采用二元性别理解，“Male”指顺性别男性，即出生时被指定为男性且认同该性别的人。“Female”指顺性别女性，即出生时被指定为女性且认同该性别的人。');
INSERT INTO "tags" VALUES ('g3941','一女性与多名性别非常规者的群体性行为','ero',6,'这款视觉小说包含群体性爱场景，其中至少一名角色为女性，而其他角色要么不符合传统性别认同（跨性别、性别酷儿、非二元或双性人），要么是不具有传统性别认同的实体（futanari、dickgirl）。

为数据库之目的，此标签采用二元性别理解，“Female”指顺性别女性，即出生时被指定为女性且认同该性别的人。');
INSERT INTO "tags" VALUES ('g3942','一名男性与数名性别非常规者的群体性行为','色情',6,'这部视觉小说包含群体场景，其中至少一个角色为男性，其他角色要么不符合传统性别认同（跨性别、性别酷儿、非二元或间性人），要么是没有传统性别认同的实体（扶她、双性女）。

出于数据库的目的，该标签使用二元的性别理解，其中\"男性\"指顺性别男性，即出生时被指派为男性并认同该身份的人。');
INSERT INTO "tags" VALUES ('g3943','多名女性和至少一名性别非常规者的群体性行为','色情',5,'这部视觉小说包含性场景，其中多个角色为女性，且至少另一个角色要么不符合传统性别认同（跨性别、性别酷儿、非二元或间性人），要么是没有传统性别认同的实体（扶她、双性女）。

出于数据库的目的，该标签使用二元的性别理解，其中\"女性\"指顺性别女性，即出生时被指派为女性并认同该身份的人。');
INSERT INTO "tags" VALUES ('g3944','数名性别非常规者的群体性行为','色情',3,'这部视觉小说包含群体场景，其中所有参与者要么不符合传统性别认同（跨性别、性别酷儿、非二元或间性人），要么是没有传统性别认同的实体（扶她、双性女）。');
INSERT INTO "tags" VALUES ('g3945','数名男性和至少一名性别非常规者的群体性行为','色情',8,'这部视觉小说包含性场景，其中多个角色为男性，且至少另一个角色要么不符合传统性别认同（跨性别、性别酷儿、非二元或间性人），要么是没有传统性别认同的实体（扶她、双性女）。

出于数据库的目的，该标签使用二元的性别理解，其中\"男性\"指顺性别男性，即出生时被指派为男性并认同该身份的人。');
INSERT INTO "tags" VALUES ('g3949','骗子女主角','内容',1,'本游戏中至少有一位女主角是骗子。

骗子通过[url=https://en.wikipedia.org/wiki/Scam]骗局[/url]诈骗他人。骗局依赖骗子先获取受害者的信任，再骗取他们的金钱或其他资产。');
INSERT INTO "tags" VALUES ('g3952','双性女与女性','色情',16,'[url=/i3103]身体 > 双性女[/url]与女性之间的性行为，女性为接受方。');
INSERT INTO "tags" VALUES ('g3954','罗斯 vs. 蜥蜴人','内容',3,'一个关于古代罗斯与蜥蜴人对抗的虚构设定。

这一虚构理论的主要来源是YouTube频道[url=https://www.youtube.com/channel/UC5vQ7qMTapu70SGUe9lYGzA]巴吉罗夫教授[/url]。其作者自称拥有4个高等教育学历的历史学副博士。\"在我的频道上，我致力于揭露蜥蜴意识形态，并对历史事件被篡改这一事实进行详细分析。\"他的简介这样写道。

这些视频迅速走红，并在俄语社区中形成了一个长期流行的梗。在‘罗斯 vs. 蜥蜴人’的设定下，已经制作了许多电子游戏、视频和书籍。');
INSERT INTO "tags" VALUES ('g3956','无家可归的主人公','内容',16,'本游戏的主角是[url=https://en.wikipedia.org/wiki/Homelessness]无家可归者[/url]。

无家可归描述的是没有固定住所的人群的状况。无家可归者无法或不愿获得和维持稳定、安全且充足的住房，或缺乏\"固定、常规且充足的夜间住所\"。');
INSERT INTO "tags" VALUES ('g3957','丘比特主角','内容',7,'本游戏中至少有一位主角是[url=https://en.wikipedia.org/wiki/Cupid]丘比特[/url]，即爱神。');
INSERT INTO "tags" VALUES ('g3959','女仆角色扮演','内容',92,'这部视觉小说的特色是有一个角色扮演女仆。

女仆角色扮演的关键是一件[url=https://t.vndb.org/sf/30/205330.jpg]女仆装[/url]（头饰、长袜、高跟鞋……）。并不是所有服装部件都必须具备才能应用该标签。');
INSERT INTO "tags" VALUES ('g3969','印度','内容',10,'这部视觉小说的背景设定在[url=https://en.wikipedia.org/wiki/India]印度[/url]。');
INSERT INTO "tags" VALUES ('g3978','性玩具支持','技术',44,'本游戏内置对性玩具互动的支持，例如支持蓝牙的振动器。');
INSERT INTO "tags" VALUES ('g3983','侧边文本框','技术',212,'本游戏的文本框覆盖屏幕的左侧或右侧，另一侧通常用于显示图像。

文本框可以完全透明或半透明，也可以有自己独特的背景。');
INSERT INTO "tags" VALUES ('g3985','管理模拟','技术',94,'一种电子游戏类型，玩家在该类型中运营或管理一个虚构场景，如企业或城市，并通过有效管理多个统计数据以达到特定目标。

该类型的大多数游戏还要求精心管理有限的资源，通常是金钱、时间或精力，玩家必须对其进行分配、花费和组织以最大限度地提高效率。

这些游戏可能还包含一些角色的统计数据，例如保持员工或顾客的满意或舒适，这可以解锁新的互动、场景或能力。');
INSERT INTO "tags" VALUES ('g3989','宗教/信仰','cont',97,'这部视觉小说涉及围绕宗教、信仰和灵性的突出讨论或主题。 

这部视觉小说中的角色会谈论、质疑或辩论宗教信仰、实践或概念，如神（们）的存在。情节可能围绕宗教观点的冲突、角色的精神之旅，或宗教对其决定和世界观的影响展开。');
INSERT INTO "tags" VALUES ('g3990','继承/传承冲突','cont',31,'这部视觉小说中的角色卷入一场冲突，该冲突涉及一个职位或一项物质财富，由于权力转移（通常涉及现任或前任持有者的离世），其正在或即将成为争夺目标。

这种令人垂涎的职位或物质利益应被多人觊觎，这些人通常属于同一家族或组织。');
INSERT INTO "tags" VALUES ('g3991','粗暴性行为（自愿）','ero',22,'本游戏包含一个或多个描述自愿粗暴性行为的场景。

粗暴性行为仅仅是以攻击性方式进行的性行为或性实践，例如[url=/g2160]勒颈性行为[/url]、[url=/g1454]深喉[/url]、[url=/g1171]情色打屁股[/url]、[url=/g3042]拉扯头发（性）[/url]、[url=/g3151]肛交[/url]。不存在权力交换，也没有支配或服从的意图。其意图/动机更多与无拘无束的激情有关，而不是给予/夺取权力。 
粗暴性行为并不浪漫。它是兽性的、激情的、刺激的、侵略性的，有时甚至是痛苦的。

请注意，此标签仅涉及在自愿背景下发生的粗暴性行为，否则就只是强奸或侵犯。实施粗暴性行为的一方不能强行施加于接受者，也不能被第三方怂恿而强行施加。接受者不能处于药物/春药影响下，或受到精神控制。');
INSERT INTO "tags" VALUES ('g3992','战队','cont',43,'战队代表了一种以超级战队系列为基础的充满动作、以团队为核心的剧集类型，其中协作、团队合作和勇气是核心主题。

战队节目的主要特征：
颜色编码的英雄：每个英雄通常穿着特定颜色的制服（例如，红色战士、蓝色战士等）。
变身：战队成员可以使用特殊装置或口令变身为超级英雄形态。
巨型机器人（机甲）：团队通常可使用由单个载具或机器人组合而成的大型机器人。
对抗邪恶：战队团队以各种形式与恶棍、怪物或邪恶组织作战。');
INSERT INTO "tags" VALUES ('g3993','冲击玩法','ero',1442,'本游戏包含一个或多个涉及[url=https://en.wikipedia.org/wiki/Impact_play]冲击玩法[/url]的场景。

冲击玩法是一种性实践，其中一个人被另一个人击打（通常是反复地），以获得一方或双方的满足，其性质可能与性相关也可能不相关。它被认为是[url=/g1117]BDSM[/url]的一种形式。');
INSERT INTO "tags" VALUES ('g3994','情色击打（自愿）','ero',12,'本游戏包含一个或多个在自愿背景下进行情色击打的场景。

自愿情色击打是一种性活动，涉及伤害、殴打、击打、拳打或掌掴角色，以使参与者获得性满足，无论是被殴打的一方还是实施殴打的一方。');
INSERT INTO "tags" VALUES ('g3995','犯罪女主角','cont',192,'本游戏中至少有一位女主角是[url=http://en.wikipedia.org/wiki/Criminal]罪犯[/url]。

罪犯是指违反法律的角色。犯罪是指违反规则或法律，而某些管理机构（通过法律体系等机制）最终可以对此定罪。');
INSERT INTO "tags" VALUES ('g3996','犯罪主人公','cont',152,'本游戏中的主人公是一名[url=http://en.wikipedia.org/wiki/Criminal]罪犯[/url]。

罪犯是指违反法律的角色。犯罪是指违反规则或法律，而某些管理机构（通过法律体系等机制）最终可以对此定罪。');
INSERT INTO "tags" VALUES ('g3997','犯罪男主角','cont',168,'本游戏中至少有一位男主角是[url=http://en.wikipedia.org/wiki/Criminal]罪犯[/url]。

罪犯是指违反法律的角色。犯罪是指违反规则或法律，而某些管理机构（通过法律体系等机制）最终可以对此定罪。');
INSERT INTO "tags" VALUES ('g3998','临床抑郁症','cont',187,'这款游戏中有重要角色患有[url=http://en.wikipedia.org/wiki/Major_depressive_disorder]重度抑郁症[/url]。这影响了游戏中的其他角色以及整体氛围。

重度抑郁症是一种精神障碍，其特征是全面的低落情绪伴随自卑，以及对通常愉快的活动失去兴趣或乐趣。

不要将此标签用于具有普遍压抑故事情节或包含悲伤、情绪化角色的游戏。');
INSERT INTO "tags" VALUES ('g4008','地下','cont',20,'这部视觉小说的很大一部分设定在地表以下：地下洞穴、地下城、下水道、地铁站等。');
INSERT INTO "tags" VALUES ('g4010','体型差恋物癖','ero',133,'带有此标签的视觉小说包含参与者之间的身高差扮演恋物癖角色的场景。这通常是性方面的，但有时不是。');
INSERT INTO "tags" VALUES ('g4011','微型恋物癖','ero',38,'带有此标签的视觉小说包含微型恋物癖性质的场景。这通常是性方面的，但有时不是。

微型恋物癖指的是对微型或缩小的人物的迷恋或性幻想。所涉及的微型人物可能原本就是那个大小，也可能是正常大小的人突然被缩小了。');
