INSERT INTO "tags" VALUES ('g4018','刺猬索尼克','cont',16,'这些游戏以《刺猬索尼克》系列中的角色为特色，或者发生在《刺猬索尼克》的宇宙中。');
INSERT INTO "tags" VALUES ('g4024','大屁股英雄','cont',23,'这款视觉小说中的一个或多个英雄拥有相当大、匀称、丰满的臀部。这要么在美术中很明显（例如在事件CG中），要么被游戏中的角色讨论。

在[url=/g1170]Bara[/url]作品中非常常见，因为英雄通常具有大而夸张的特征，或者具有变装英雄以强调其''女性气质''，但这并不限于这两种情况。

示例：[url=/v16719]Meat Log Mountain[/url]、[url=/v18950]Himitsu Kessha Transparency[/url]和[url=/v14942]Specie to Chimera[/url]。');
INSERT INTO "tags" VALUES ('g4025','扶她×扶她','ero',2,'这部视觉小说包含扶她之间的性爱场景。');
INSERT INTO "tags" VALUES ('g4028','主角的孙女作为女主角','cont',3,'这款游戏的女主角之一是主角的孙女。');
INSERT INTO "tags" VALUES ('g4029','有孙辈的主角','cont',6,'这部视觉小说的主角有一个或多个孙辈，无论是亲生的还是收养的。这些孩子可能是也可能不是游戏中的角色。

不要将此标签用于主角在游戏接近尾声时才有孙辈的游戏。该标签适用于那些在游戏开始时已经有孙辈，或者在游戏开始后不久就有孙辈的主角。');
INSERT INTO "tags" VALUES ('g4030','黄金周','cont',4,'游戏中有以黄金周为背景的场景。

黄金周（ゴールデンウィーク）或ōgon Shūkan（黄金週間）是日本从4月29日到5月5日的假期期间，包含多个公共假日。它也被称为Haru no ōgata Renkyū（春の大型連休）。
作为日本一年中最大的假期期间之一，黄金周期间全国各地的度假旅行通常会激增。尽管名称如此，这一周中只有4天被正式指定为公共假日，上班族通常会选择休满一整周。');
