INSERT INTO "tags" VALUES ('g4042','考古学','cont',14,'游戏的故事以[url=https://en.wikipedia.org/wiki/Archaeology]考古学[/url]为特色。考古学是通过物质文化的回收和分析来研究人类活动的学科。该学科涉及调查、发掘，最终分析收集到的数据，以更多地了解过去。');
INSERT INTO "tags" VALUES ('g4046','胸肌交','ero',5,'游戏包含至少一个以胸肌交为特色的场景。胸肌交涉及用另一个人的胸肌刺激男性阴茎。 

与[url=/g2204]Bodyjob[/url]不同，胸肌交与[url=/g1405]Macrophilia[/url]几乎没有联系，它可以对任何体型的人进行。');
INSERT INTO "tags" VALUES ('g4047','播音员主角','cont',3,'这款游戏的主角是一位[url=http://en.wikipedia.org/wiki/Announcer]播报员[/url]。');
INSERT INTO "tags" VALUES ('g4049','僵尸启示录','cont',51,'灾难性虚构作品的一个子类型，故事中世界因僵尸大规模爆发而终结或经历灾难性崩溃。这些僵尸通常是无意识、复活的尸体，对人类的血肉有着永无餍足的渴望。 

带有此标签的故事聚焦于瘟疫引发的全球或社会性毁灭，强调生存、孤立、道德沦丧与文明崩溃等主题。');
INSERT INTO "tags" VALUES ('g4052','黑色虚构','tech',23,'这部视觉小说遵循传统[url=https://en.wikipedia.org/wiki/Noir_fiction]黑色叙事[/url]的套路。

这是一种植根于犬儒主义、道德模糊和宿命论的虚构类型。它常以冷硬派主角在充满犯罪、背叛与是非界限模糊的腐败世界中穿行为特征。黑色风格推崇阴暗氛围、内心冲突与粗粝的现实主义，其中每个选择都有代价，救赎从不被保证。');
INSERT INTO "tags" VALUES ('g4053','被不死生物强奸','ero',20,'本游戏包含一个或多个由[url=/g491]不死生物[/url]实施的强奸场景。');
INSERT INTO "tags" VALUES ('g4056','拳皇','cont',9,'这些游戏包含来自[url=https://en.wikipedia.org/wiki/The_King_of_Fighters]拳皇[/url]系列的角色。');
INSERT INTO "tags" VALUES ('g4057','脱衣舞俱乐部','cont',8,'适用于脱衣舞俱乐部是主要场景之一的游戏，角色在其中工作或经常光顾，或俱乐部在情节中扮演重要角色。

脱衣舞俱乐部是一种酒吧或俱乐部，舞者在舞台上脱衣以娱乐顾客。她们也可能提供膝上舞或私人舞蹈以换取金钱。性行为通常不被官方允许，但仍可能存在。如果主要焦点是性行为而非舞蹈和脱衣，请使用妓院（brothel）');
INSERT INTO "tags" VALUES ('g4060','荒诞喜剧','cont',117,'荒诞喜剧是喜剧的一个子类型，其幽默来源于不合逻辑的情景、非理性对话以及超现实或荒谬的事件。荒诞主要不是用来探讨存在主义主题，而是通过不可预测、往往荒唐的设定和笑点来娱乐。

此标签适用于荒诞性为喜剧基调核心的作品，例如刻意无厘头的角色行为、没有理性原因的离奇情节发展，或基于违背叙事逻辑的幽默。');
INSERT INTO "tags" VALUES ('g4066','精神病医院','cont',40,'这部视觉小说有大量场景设定在[url=https://en.wikipedia.org/wiki/Psychiatric_hospital]精神病医院[/url]中。

设定在此处的故事通常探讨心理健康主题、机构生活、医患互动以及心理紧张。');
INSERT INTO "tags" VALUES ('g4067','半人马女主角','cont',9,'本游戏中的一位或多位女主角是半人马。');
INSERT INTO "tags" VALUES ('g4068','鹰身女妖女主角','cont',9,'本游戏中的一位或多位女主角是鹰身女妖。');
INSERT INTO "tags" VALUES ('g4069','失聪主角','cont',6,'主角是聋人或有听力障碍。

聋是一种听力残疾。主角可能部分或完全听不见，或听力不均匀。 

主角可能认同为文化意义上的聋人（例如属于使用当地手语的聋人群体），也可能仅仅是有残疾，而不参与社群或使用手语。');
INSERT INTO "tags" VALUES ('g4075','内战','cont',5,'[url=https://en.wikipedia.org/wiki/Civil_war]内战[/url]在故事中扮演重要角色。

内战是同一国家或组织内派系、地区或群体之间的大规模内部冲突。这些冲突通常源于政治、意识形态、民族或领土争端。');
