INSERT INTO "tags" VALUES ('g4094','杀人狂','cont',32,'恐怖片的一个[url=https://en.wikipedia.org/wiki/Slasher_film]子类型[/url]，兴起于1970年代中后期，以《黑色圣诞节》、《万圣节》和《德州电锯杀人狂》等影片为代表。所有杀人狂片的普遍情节涉及一个凶手尾随并杀害一群人。

大多数杀人狂片中常见的套路包括露骨的血腥、女性裸露，以及一个[url=https://en.wikipedia.org/wiki/Final_girl]“最终女孩”[/url]角色。');
INSERT INTO "tags" VALUES ('g4098','恋母情结主角','cont',24,'本游戏的主角是一个妈宝，即总是充满热情且过度依恋母亲（或类似母亲形象的人）并愿为她做任何事的人。

注意：此标签仅用于描述主角的性格。

如果主角（或视觉小说中的普通大众）将他们的关系视为母亲/子女关系，则该标签有效。他们可能有也可能没有真正的亲子关系。');
