INSERT INTO "tags" VALUES ('g4116','瑜伽','cont',4,'本游戏将瑜伽作为故事元素。瑜伽最初是印度教、耆那教、锡克教和佛教信仰者进行的一种精神修行，但从20世纪开始，它成为一种流行的锻炼方式。');
