INSERT INTO "tags" VALUES ('g4123','失聪女主角','cont',8,'游戏中的一位或多位女主角耳聋或听力不佳。

耳聋是一种听力残疾。女主角可能部分或完全无法听见，或听力不均匀。

女主角可能自认属于文化意义上的聋人（例如属于使用当地手语的聋人社区），但也可能仅仅是患有残疾，并不参与社区或不使用手语。');
INSERT INTO "tags" VALUES ('g4124','代孕','cont',3,'本视觉小说涉及代孕相关主题和事件。

代孕是一种安排，即一名女性代表另一个人或夫妇怀孕并分娩，后者在婴儿出生后成为其合法父母。人们出于多种原因寻求代孕，例如不孕不育、怀孕的危险或不利因素，或怀孕在医学上不可能。');
INSERT INTO "tags" VALUES ('g4126','基于戏剧','tech',9,'本视觉小说基于或改编自一部戏剧\舞台制作。戏剧已经存在了数千年，几乎每种文化中都可以找到其多种形式。');
