INSERT INTO "tags" VALUES ('g4140','赌博','cont',51,'本游戏包含聚焦于[url=https://en.wikipedia.org/wiki/Gambling]赌博[/url]的场景。

赌博是在结果不确定的事件上押注金钱、贵重物品或其他赌注的行为。这些赌注通常涉及运气成分，主要目的是在结果揭晓时赢得奖励。');
INSERT INTO "tags" VALUES ('g4146','仅限鼠标推进文本','tech',5,'该游戏不允许您使用键盘推进，而是强制您每次想要显示下一行时点击视觉小说的窗口。

