INSERT INTO "tags" VALUES ('g4167','加冕礼','cont',4,'这部视觉小说涉及即将举行或正在接受[url=https://en.wikipedia.org/wiki/Coronation]加冕[/url]的人。

加冕典礼标志着君主通过王冠正式获得王权。这一仪式可能包括展示其他王权物品，以及举行其他仪式，如新君主宣誓、授予和展示王权物品，以及新君主臣民的效忠行为。');
